// v2026-05-28k
// ============================================================
// Anti-XSS helper global — escapa contenido de usuario antes de inyectarlo a innerHTML.
// Usalo SIEMPRE para texto que viene de la DB o del input del usuario.
// ============================================================
window.escH = window.escH || function(s) {
    if (s == null) return '';
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
};

// ============================================================
// SUPABASE INIT
// ============================================================
// Capturar el hash inicial ANTES de cualquier routing (para el link secreto de admin)
window.__bootHash = (window.location.hash || '').toLowerCase();
const SUPABASE_URL = 'https://dofbxgqzcvfjpnvcvdjb.supabase.co';
const SUPABASE_KEY = 'sb_publishable_gPwLXkMHk3HvFz9nm9hgKA_1D0IJBKA';
// fetch con TIMEOUT para TODAS las llamadas a Supabase. Sin esto, si el backend no
// responde (503 / red caída) la petición quedaba colgada para siempre: la UI parecía
// congelada, los guardados fallaban en silencio y las listas no refrescaban. Ahora
// aborta a los 15s → la promesa rechaza → el try/catch del código muestra el error.
window._cancheroFetch = function(input, init){
    init = init || {};
    if (init.signal) return fetch(input, init); // respetar un signal ya provisto
    var ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var t = ctrl ? setTimeout(function(){ try { ctrl.abort(); } catch(e){} }, 15000) : null;
    if (ctrl) init.signal = ctrl.signal;
    return fetch(input, init).finally(function(){ if (t) clearTimeout(t); });
};
let _sb = null;
try {
    if (window.supabase) {
        _sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY, {
            auth: {
                persistSession: true,
                autoRefreshToken: true,
                detectSessionInUrl: true,
                storageKey: 'canchero_auth',
            },
            global: { fetch: window._cancheroFetch }
        });
        window._sb = _sb;           // expuesto globalmente para todos los módulos
        window.supabaseClient = _sb; // alias de compatibilidad
        // PARCHE CRÍTICO: el builder de PostgREST (supabase-js v2) es "thenable" pero NO
        // tiene .catch(). En TODO el código hay `sb.from(...).insert(...).catch(...)` que
        // lanzaba "TypeError: .catch is not a function" de forma SÍNCRONA → cortaba la
        // operación y la escritura fallaba EN SILENCIO (guardados que "no hacían nada").
        // Le agregamos .catch al prototipo una sola vez → arregla todos los llamados.
        try {
            var _bp = Object.getPrototypeOf(_sb.from('users').select('email'));
            while (_bp && !Object.prototype.hasOwnProperty.call(_bp, 'then')) _bp = Object.getPrototypeOf(_bp);
            if (_bp && !_bp.catch) Object.defineProperty(_bp, 'catch', {
                value: function(onRejected){ return this.then(undefined, onRejected); },
                writable: true, configurable: true
            });
        } catch(e) { console.warn('postgrest .catch patch:', e); }
        // SEGURIDAD (Fase 1): la service key se quitó del cliente.
        // _sbAdmin queda como alias del cliente anon para compatibilidad de todo
        // el código existente; las operaciones privilegiadas van a funciones api/.
        window._sbAdmin = _sb;
    }
} catch(e) { console.warn('Supabase init error:', e); }

// Restaurar sesión — esperar al DOM para poder navegar correctamente
window._sessionRestored = false;
async function _restoreSessionNow() {
    if (window._sessionRestored) return;
    window._sessionRestored = true;
    const sb = _sb || window._sb;

    function _applyRestoredUser(u) {
        if (!u || !u.email || !u.role) return false;
        userData = u;            // set the let variable so applyUserData() can access it
        window.userData = u;
        try { localStorage.setItem('canchero_user', JSON.stringify(u)); } catch(e) {}
        if (typeof applyUserData === 'function') applyUserData();
        const _paidRoles = ['club','profesional','organizacion','tienda','sponsor'];
        const _vencida = u.sub_paid_until && new Date(u.sub_paid_until) < new Date();
        const _esNegocio = _paidRoles.includes(u.role) && u.email !== 'neurovidstudioia@gmail.com';
        // 2026-07 — Los negocios entran GRATIS sin código ni pago (la cuota con
        // MercadoPago llega más adelante y NO aplica a los ya registrados).
        // Cualquier negocio queda activo automáticamente al entrar.
        const _negocioActivo = _esNegocio;
        if (_esNegocio && u.sub_status !== 'active') {
            u.sub_status = 'active';
            try { localStorage.setItem('canchero_user', JSON.stringify(u)); } catch(e) {}
            try { const _sbAct = window._sb; if (_sbAct) _sbAct.from('users').update({ sub_status: 'active' }).eq('email', u.email).then(function(){}, function(){}); } catch(e) {}
        }
        // Negocio ACTIVO → NO redirigir al CRM standalone. El negocio usa la app
        // principal como todos, con la barra inferior PANEL/Buscar/Inicio/Chats/Perfil
        // (PANEL abre su CRM) + el switcher de rol arriba.
        if (_negocioActivo) {
            window._bizRole = u.role;
            window._isBizUser = true;
        }
        const dest = u.role === 'admin' ? 'admin' : 'jugador';
        if (typeof navigate === 'function') navigate(dest);
        // Rearmar barra inferior (PANEL primero) + switcher para el negocio
        try { if (window._rebuildBottomNav) window._rebuildBottomNav(); } catch(e){}
        try { if (window._renderProfileSwitcher) window._renderProfileSwitcher(); } catch(e){}
        // Restaurar el último tab activo — UNA SOLA VEZ, con delay para que el DOM esté listo
        if (!window._tabRestoreDone) {
            window._tabRestoreDone = true;
            clearTimeout(window._restoreTabTimer);
            window._restoreTabTimer = setTimeout(_doTabRestore, 150);
        }
        // SYNC INMEDIATO con la DB: el localStorage puede tener datos VIEJOS (nombre/foto/
        // portada) de una sesión anterior; sin esto se veía lo viejo hasta 4 min después
        // ("volvieron a como estaban y luego se arreglaron solos"). La DB es la verdad.
        try { setTimeout(function(){ window._syncProfileLive && window._syncProfileLive(); }, 400); } catch(e){}
        return true;
    }

    // Deep-link del email de admin: /?goto=admin-negocios
    function _handleGotoParam() {
        // Link de invitación a un partido: /?invite=<matchId> → abre la ficha (CTA de unirse).
        try {
            var inv = new URLSearchParams(location.search).get('invite');
            if (inv) {
                try { localStorage.setItem('pending_invite', inv); } catch(e){}
                // Esperar TAMBIÉN a que la sesión esté restaurada (userData): si se abría
                // a los 800ms sin sesión, la ficha no renderizaba y la pestaña quedaba en el inicio.
                var _openInv = function(){
                    if (typeof window.viewMatchDetails === 'function' && window.userData && window.userData.email) {
                        window.viewMatchDetails(inv);
                        try{ localStorage.removeItem('pending_invite'); }catch(e){}
                        return true;
                    }
                    return false;
                };
                setTimeout(function(){ if(!_openInv()){ var t=0; var iv=setInterval(function(){ t++; if(_openInv()||t>60) clearInterval(iv); }, 1000); } }, 800);
            }
        } catch(e) {}
        try {
            var perfilEmail = new URLSearchParams(location.search).get('perfil');
            if (perfilEmail && typeof window.viewUserProfile === 'function') {
                setTimeout(function(){ try { window.viewUserProfile(perfilEmail, true); } catch(e){} }, 600);
                return true;
            }
        } catch(e) {}
        // Link al perfil de un EQUIPO/CLUB: /?club=<clubId> → abre su perfil.
        // (Faltaba: los links de equipo desde el panel de torneos caían en el inicio.)
        try {
            var clubRef = new URLSearchParams(location.search).get('club');
            if (clubRef) {
                var _openClub = function(){ if (typeof window.viewClubProfile === 'function') { window.viewClubProfile(clubRef); return true; } return false; };
                setTimeout(function(){ if(!_openClub()){ var tc=0; var ivc=setInterval(function(){ tc++; if(_openClub()||tc>40) clearInterval(ivc); }, 1000); } }, 800);
            }
        } catch(e) {}
        // Link compartido a un POST/REEL/PRODUCTO: /?post=<id> → abre esa publicación
        try {
            var sharedPost = new URLSearchParams(location.search).get('post');
            if (sharedPost) {
                var _openSp = function(){ if (window._openSharedPost && window._sb) { window._openSharedPost(sharedPost); return true; } return false; };
                setTimeout(function(){ if(!_openSp()){ var t2=0; var iv2=setInterval(function(){ t2++; if(_openSp()||t2>30) clearInterval(iv2); }, 1000); } }, 900);
            }
        } catch(e) {}
        // Link compartido a una COMUNIDAD: /?comunidad=<id>
        try {
            var sharedComu = new URLSearchParams(location.search).get('comunidad');
            if (sharedComu) {
                setTimeout(function(){ try { window.CancheroComunidades && window.CancheroComunidades.openCommunity(sharedComu); } catch(e){} }, 1500);
            }
        } catch(e) {}

        try {
            let goto = new URLSearchParams(location.search).get('goto');
            if (!goto && (location.hash === '#admin' || location.hash === '#admin-negocios')) goto = 'admin-negocios';
            if (!goto) return false;
            if (goto === 'admin-negocios') {
                if (userData && userData.role === 'admin') {
                    navigate('admin');
                    setTimeout(() => { try { switchAdminTab('negocios', null); } catch(e) {} }, 400);
                    return true;
                } else if (typeof showToast === 'function') {
                    showToast('Iniciá sesión con la cuenta de administrador para ver las solicitudes.', 'warning');
                }
            }
            // Volver del PANEL (CRM) a una sección de la app: /?goto=feed|buscar|chats|perfil|comunidad
            const _tabMap = { feed:'feed', inicio:'feed', buscar:'buscar', chats:'mensajes', mensajes:'mensajes', perfil:'perfil' };
            if (_tabMap[goto]) {
                setTimeout(() => { try {
                    navigate('jugador');
                    switchDashboardTab('jugador', _tabMap[goto], null);
                } catch(e) {} }, 500);
                return true;
            }
            if (goto === 'comunidades') {
                setTimeout(() => { try { navigate('jugador'); window.CancheroComunidades && window.CancheroComunidades.open(); } catch(e) {} }, 600);
                return true;
            }
        } catch(e) {}
        return false;
    }

    // La app SIEMPRE abre en INICIO (feed). No restauramos el último tab.
    function _doTabRestore() {
        try {
            if (_handleGotoParam()) return;
            const dashRole = userData && (userData.role === 'club' ? 'club' : 'jugador');
            if (typeof switchDashboardTab === 'function') switchDashboardTab(dashRole, 'feed', null);
        } catch(e) { console.warn('[tabRestore]', e); }
    }

    // Intentar desde Supabase
    if (sb) {
        try {
            const { data: { session } } = await sb.auth.getSession();
            if (session?.user) {
                const email = session.user.email;
                // Admin hardcodeado
                if (email === 'neurovidstudioia@gmail.com') {
                    const u = { name: 'SUPER ADMIN', email, role: 'admin' };
                    _applyRestoredUser(u); return;
                }
                // Buscar en tabla users — usar _sbAdmin para bypassar RLS.
                // limit(1) en vez de maybeSingle (maybeSingle falla si hay duplicados).
                const sbq = sb;
                const emailLc = (email||'').toLowerCase();
                let profile = null;
                try { const r = await sbq.from('users').select('*').eq('email', emailLc).limit(1); profile = (r.data && r.data[0]) || null; } catch(e) {}
                if (!profile && emailLc !== email) {
                    try { const r = await sbq.from('users').select('*').eq('email', email).limit(1); profile = (r.data && r.data[0]) || null; } catch(e) {}
                }
                if (!profile) {
                    try { const r = await sbq.from('profiles').select('*').eq('email', emailLc).limit(1); profile = (r.data && r.data[0]) || null; } catch(e) {}
                }
                if (profile) {
                    // DB es la fuente de verdad — tomar photo, cover_photo, bio, pos, city, etc. de DB si existen
                    const savedLocal = localStorage.getItem('canchero_user');
                    let localData = null;
                    if (savedLocal) {
                        try {
                            const ld = JSON.parse(savedLocal);
                            if (ld?.email === profile.email) localData = ld;
                        } catch(e) {}
                    }
                    // Base: localStorage (preserva campos locales), luego DB sobreescribe campos que existan en DB
                    const merged = localData ? { ...localData } : {};
                    merged.email = profile.email;
                    merged.name = profile.name;
                    merged.role = profile.role;
                    merged.created_at = profile.created_at || merged.created_at;
                    // Campos que la DB tiene — si DB los tiene, siempre ganar sobre localStorage
                    if (profile.photo)       merged.photo = profile.photo;
                    if (profile.photo_style) { merged.photoStyle = profile.photo_style; merged.photo_style = profile.photo_style; }
                    if (profile.sub_status) merged.sub_status = profile.sub_status;
                    if (profile.sub_paid_until) merged.sub_paid_until = profile.sub_paid_until;
                    if (profile.cover_photo) { merged.coverPhoto = profile.cover_photo; merged.cover_photo = profile.cover_photo; }
                    if (profile.cover_style) merged.coverStyle = profile.cover_style;
                    if (profile.bio)         merged.bio = profile.bio;
                    if (profile.pos)         { merged.pos = profile.pos; merged.position = profile.pos; }
                    if (profile.city)        { merged.city = profile.city; merged.department = profile.city; }
                    if (profile.nat)         { merged.nat = profile.nat; merged.nationality = profile.nat; }
                    if (profile.foot)        merged.foot = profile.foot;
                    if (profile.age)         merged.age = profile.age;
                    if (profile.nickname)    merged.nickname = profile.nickname;
                    if (profile.stats)       merged.stats = profile.stats;
                    if (profile.points)      merged.points = profile.points;
                    // Disponibilidad — columna "available" en DB, mapeada a isAvailable en JS
                    if (profile.available !== null && profile.available !== undefined) {
                        merged.isAvailable = profile.available;
                        merged.available   = profile.available;
                    }
                    if (profile.availability_schedule) merged.availability = profile.availability_schedule;
                    // Roles multi-dispositivo: los perfiles enlazados y el rol activo viven
                    // en la DB — al loguear en cualquier dispositivo se adopta lo de la DB
                    // (así no hay que re-registrar el fanático ni se pierde la identidad).
                    if (profile.linked_profiles && Object.keys(profile.linked_profiles).length) merged.linked_profiles = profile.linked_profiles;
                    try {
                        if (profile.active_profile) {
                            localStorage.setItem('canchero_active_profile', profile.active_profile);
                            if (profile.active_profile === 'team' && profile.active_team) {
                                localStorage.setItem('canchero_active_team', JSON.stringify(profile.active_team));
                            }
                        }
                    } catch(e) {}
                    profile = merged;
                    _applyRestoredUser(profile); return;
                }
                // Usuario con auth pero sin perfil → intentar localStorage y crear perfil
                const saved = localStorage.getItem('canchero_user');
                let localUser = null;
                if (saved) { try { const u = JSON.parse(saved); if (u?.email === email) localUser = u; } catch(e) {} }
                // Crear perfil en users table para que el login funcione cross-device
                const authMeta = session.user.user_metadata || {};
                const newProfile = {
                    email: email.toLowerCase(),
                    name: (localUser?.name) || authMeta.name || authMeta.full_name || email.split('@')[0],
                    role: (localUser?.role) || authMeta.role || 'jugador'
                };
                try {
                    await sbq.from('users').upsert(newProfile, { onConflict: 'email' });
                } catch(e) { console.warn('profile create error:', e); }
                const finalProfile = localUser ? { ...newProfile, ...localUser } : newProfile;
                _applyRestoredUser(finalProfile); return;
            }
        } catch(e) {}
    }

    // FASE 1 AUTH (2026-06-11): sin sesión de Supabase Auth NO hay sesión.
    // El viejo fallback restauraba un JSON de localStorage como si fuera una
    // sesión real (sesión fantasma) — eliminado. Solo se mantiene en localhost
    // para poder testear la app en desarrollo.
    const _isDev = /^(localhost|127\.0\.0\.1)$/.test(location.hostname);
    const saved = localStorage.getItem('canchero_user');
    if (saved && _isDev) {
        try { const u = JSON.parse(saved); _applyRestoredUser(u); return; } catch(e) {}
    }
    if (saved) {
        // Había una sesión legacy: limpiarla y avisar UNA vez
        try { localStorage.removeItem('canchero_user'); } catch(e) {}
        setTimeout(function(){
            try { if (typeof showToast === 'function') showToast('Tu sesión expiró por seguridad. Volvé a iniciar sesión (o usá "Olvidé mi contraseña" si nunca creaste una).', 'info'); } catch(e) {}
        }, 1200);
    }
}

// Backfill one-time: migrar auth users existentes a tabla users
async function _backfillUsersTable() {
    // Deshabilitado (Fase 5): auth.admin.listUsers requiere service key y el
    // cliente ya no la tiene. El backfill quedó hecho; los usuarios nuevos
    // crean su fila al registrarse/restaurar sesión.
    return;
    if (!window._sbAdmin) return;
    if (localStorage.getItem('_ub_done_v3')) return; // ya corrió
    try {
        const { data: { users: authUsers }, error } = await window._sbAdmin.auth.admin.listUsers({ perPage: 100 });
        if (error || !authUsers?.length) return;
        for (const au of authUsers) {
            if (!au.email) continue;
            const meta = au.user_metadata || {};
            await window._sbAdmin.from('users').upsert({
                email: au.email.toLowerCase(),
                name: meta.name || meta.full_name || au.email.split('@')[0],
                role: meta.role || 'jugador'
            }, { onConflict: 'email', ignoreDuplicates: true });
        }
        localStorage.setItem('_ub_done_v3', '1');
        console.log('[Canchero] Backfill users table: done for', authUsers.length, 'users');
    } catch(e) { console.warn('[Canchero] Backfill error:', e.message); }
}

// Ejecutar cuando el DOM esté listo
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        setTimeout(_restoreSessionNow, 150);
        setTimeout(_backfillUsersTable, 2000);
    });
} else {
    setTimeout(_restoreSessionNow, 150);
    setTimeout(_backfillUsersTable, 2000);
}

// ============================================================
// GOOGLE AUTH
// ============================================================
window.handleGoogleAuth = async function() {
    if (!_sb) { showToast('Error de conexión con el servidor.', 'error'); return; }
    try {
        const { error } = await _sb.auth.signInWithOAuth({
            provider: 'google',
            options: {
                redirectTo: window.location.origin + window.location.pathname,
                queryParams: { access_type: 'offline', prompt: 'consent' }
            }
        });
        if (error) throw error;
    } catch(e) {
        const msg = e.message || '';
        if (msg.toLowerCase().includes('provider is not enabled') || msg.toLowerCase().includes('unsupported provider')) {
            showToast('Google login no está activado en Supabase. Mientras tanto, usá email/contraseña.', 'warning');
        } else {
            showToast('Error con Google: ' + (msg || 'Intentá con email/contraseña.'), 'error');
        }
    }
};

// Navegación post-login centralizada: negocios activos → CRM, resto → jugador/admin
window._navAfterLogin = function(role, email) {
    const _paidRoles = ['club','profesional','organizacion','tienda','sponsor'];
    const u = window.userData || {};
    const _esNegocio = _paidRoles.includes(role) && email !== 'neurovidstudioia@gmail.com';
    // 2026-07 — Negocios GRATIS sin código: se activan solos al entrar.
    const _negocioActivo = _esNegocio;
    if (_esNegocio && u.sub_status !== 'active') {
        u.sub_status = 'active';
        try { localStorage.setItem('canchero_user', JSON.stringify(u)); } catch(e) {}
        try { const _sbA = window._sb; if (_sbA) _sbA.from('users').update({ sub_status: 'active' }).eq('email', email).then(function(){}, function(){}); } catch(e) {}
    }
    if (_negocioActivo) {
        window._bizRole = role;
        window._isBizUser = true;
        // Al ENTRAR como negocio, la identidad activa es el NEGOCIO. Limpiar restos de
        // 'team' de sesiones anteriores (dejaban el perfil como fut-card de jugador y el
        // PANEL/CRM equivocado). Si el negocio estaba en su identidad de jugador/fanático,
        // se respeta; cualquier otro valor (team/vacío) vuelve a 'negocio'.
        try {
            var _apX = localStorage.getItem('canchero_active_profile');
            if (_apX !== 'jugador' && _apX !== 'fanatico' && _apX !== 'negocio' && (_apX||'').indexOf('biz:') !== 0) {
                localStorage.setItem('canchero_active_profile', 'negocio');
                localStorage.removeItem('canchero_active_team');
                if (window.userData) { window.userData._activeProfile = 'negocio'; window.userData._postAsClub = false; window.userData._activeClubId = null; }
                try { if (window._applyActiveProfileOverlay) window._applyActiveProfileOverlay(); } catch(e){}
            }
        } catch(e){}
        // El negocio NO se va al CRM standalone: usa la app principal con la barra
        // PANEL/Buscar/Inicio/Chats/Perfil (PANEL abre su CRM) + switcher de rol.
        navigate('jugador');
        try { if (window._rebuildBottomNav) window._rebuildBottomNav(); } catch(e){}
        try { if (window._renderProfileSwitcher) window._renderProfileSwitcher(); } catch(e){}
        return;
    }
    const dest = role === 'admin' ? 'admin' : role === 'fanatico' ? 'jugador' : (role === 'club' ? 'jugador' : 'jugador');
    navigate(dest);
};

// ============================================================
// PERFILES MÚLTIPLES (jugador / fanático / club) — estilo Instagram
// Un mismo usuario puede tener los 3. El switcher va centrado arriba.
// El perfil ACTIVO define la identidad (nombre, foto, bandera, rol) en
// publicaciones, comentarios, likes, etc.
// ============================================================
window._PROFILE_TYPES = ['jugador','fanatico'];
window._profileMeta = {
    jugador:  { label:'Jugador',  icon:'bx-run' },
    fanatico: { label:'Fanático', icon:'bx-football' },
    club:     { label:'Equipo',   icon:'bx-shield' },
    negocio:  { label:'Negocio',  icon:'bx-store' }
};
window._baseTypeOf = function(role){
    return (role==='fanatico') ? 'fanatico' : 'jugador';
};
// ── MULTI-IDENTIDAD: una cuenta puede tener N negocios a la vez ──────────────
// Fuente de verdad de los negocios = filas de business_requests (APROBADO) del email.
// Cada uno es una identidad seleccionable 'biz:<id>' con su propia foto/nombre/rol.
window._BIZ_ROLES = ['club','complejo','tienda','organizacion','sponsor','profesional'];
window._myBusinesses = window._myBusinesses || [];
// Rol persistido en la fila users (identidad BASE, jugador/fanático o legacy negocio).
window._baseStoredRole = function(){
    try { var u = JSON.parse(localStorage.getItem('canchero_user')||'null'); if (u && u.role) return u.role; } catch(e){}
    return (window.userData && window.userData.role) || 'jugador';
};
// Carga los negocios del usuario a memoria y refresca el switcher.
window._loadMyBusinesses = async function(){
    try {
        var sb = window._sb; var u = window.userData;
        if (!sb || !u || !u.email) return window._myBusinesses;
        if (u.email === 'neurovidstudioia@gmail.com') return (window._myBusinesses = []);
        var r = await sb.from('business_requests').select('*').eq('email', u.email).order('created_at', { ascending: true });
        // Si la consulta FALLA (400/503/red), NO vaciar la lista: el dueño vería "Registrar
        // mi negocio" como si lo hubiera perdido. Conservar lo ya cargado y salir.
        if (r && r.error) { console.warn('[_loadMyBusinesses] error, se conserva la lista previa:', r.error.message); return window._myBusinesses; }
        var rows = (r && r.data) || [];
        var seen = {};
        window._myBusinesses = rows
            .filter(function(b){ var st=(b.status||'').toUpperCase(); return st==='' || st==='APROBADO' || st==='APPROVED' || st==='ACTIVO' || st==='ACTIVE'; })
            .map(function(b){
                var pl = b.payload || {}; try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
                return {
                    id: String(b.id), role: b.role || pl.role || 'tienda', name: b.name || pl.name || 'Mi negocio',
                    photo: b.photo || pl.photo || '', bio: b.bio || pl.bio || '', coverPhoto: b.cover || pl.cover || null,
                    plan: b.plan || pl.plan || 'estandar',
                    // Encuadre (zoom/x/y) de la foto y la portada del negocio. Sin esto el
                    // logo se renderiza con el recorte de CARA por defecto (center 25%).
                    photo_style: pl.photo_style || null, cover_style: pl.cover_style || null,
                    // Datos editables del perfil de negocio (viven en payload).
                    phone: pl.phone || '', whatsapp: pl.whatsapp || '', address: pl.address || '',
                    website: pl.website || '', instagram: pl.instagram || '', price_info: pl.price_info || '',
                    frame_style: pl.frame_style || null
                };
            })
            // Deduplicar por rol+nombre (evita filas repetidas de re-registros)
            .filter(function(b){ var k=b.role+'|'+(b.name||'').toLowerCase(); if (seen[k]) return false; seen[k]=b.id; return true; });
        // FALLBACK de branding: los CRM viejos guardaban foto/portada/bio en `users`
        // (no en business_requests) → si un negocio no tiene foto, tomarla de ahí
        // para que aparezca en momentos, posts y perfil.
        try {
            // SOLO para cuentas cuyo rol BASE es de negocio (ahí users.* ES el negocio);
            // en cuentas de jugador con negocios agregados NO se mezclan identidades.
            var _needs = (window._BIZ_ROLES.indexOf(window._baseStoredRole()) !== -1)
                && window._myBusinesses.some(function(b){ return !b.photo || !b.coverPhoto || !b.bio; });
            if (_needs) {
                var ur = await sb.from('users').select('photo,cover_photo,bio').eq('email', u.email).maybeSingle();
                var uRow = (ur && ur.data) || {};
                // SOLO al negocio PRIMARIO (el más viejo = el que usaba users.*):
                // aplicarlo a todos hacía que la foto/portada de un negocio se
                // "contagiara" a los demás roles de negocio de la cuenta.
                var b0 = window._myBusinesses[0];
                if (b0) {
                    if (!b0.photo && uRow.photo && !String(uRow.photo).includes('ui-avatars')) b0.photo = uRow.photo;
                    if (!b0.coverPhoto && uRow.cover_photo) b0.coverPhoto = uRow.cover_photo;
                    if (!b0.bio && uRow.bio) b0.bio = uRow.bio;
                }
            }
        } catch(e){}
        try { if (window._renderProfileSwitcher) window._renderProfileSwitcher(); } catch(e){}
    } catch(e){ console.warn('_loadMyBusinesses:', e && e.message); }
    return window._myBusinesses;
};
// Id del negocio ACTIVO (según canchero_active_profile), o null si la identidad no es de negocio.
window._activeBizId = function(){
    var ap = localStorage.getItem('canchero_active_profile') || '';
    if (ap.indexOf('biz:') === 0) return ap.slice(4);
    if (ap === 'negocio') { var l = window._myBusinesses || []; return l.length ? String(l[0].id) : '__primary__'; }
    return null;
};
// Objeto del negocio activo (de _myBusinesses, o sintetizado para cuentas legacy).
window._activeBiz = function(){
    var id = window._activeBizId ? window._activeBizId() : null;
    if (!id) return null;
    var l = window._myBusinesses || [];
    var found = l.filter(function(b){ return String(b.id) === String(id); })[0];
    if (found) return found;
    // Legacy: cuenta cuyo rol base ES un negocio y todavía no cargó business_requests.
    var r = window._baseStoredRole();
    if ((window._BIZ_ROLES.indexOf(r) !== -1) || window._isBizUser) {
        var base = null; try { base = JSON.parse(sessionStorage.getItem('canchero_base_snapshot')||'null'); } catch(e){}
        return { id:'__primary__', role: r, name: (base && base.name) || (window.userData && window.userData.name) || 'Mi negocio',
                 photo: (base && base.photo) || (window.userData && window.userData.photo) || '', bio:'', coverPhoto:null,
                 // Legacy: users.* ES el negocio → su encuadre es el de la fila users.
                 photo_style: (base && (base.photo_style || base.photoStyle))
                              || (window.userData && (window.userData.photo_style || window.userData.photoStyle)) || null };
    }
    return null;
};
// ¿La cuenta POSEE algún negocio? (independiente de la identidad activa)
window._hasBusinesses = function(){
    if (window._myBusinesses && window._myBusinesses.length) return true;
    var email = (window.userData && window.userData.email) || '';
    if (email === 'neurovidstudioia@gmail.com') return false;
    return !!(window._isBizUser || window._BIZ_ROLES.indexOf(window._baseStoredRole()) !== -1);
};
// Rol REAL de la identidad ACTIVA. Si es un negocio → su rol (tienda/complejo/...).
// Si no, el rol base persistido (jugador/fanático). userData.role se corrompe con el overlay.
window._trueRole = function(){
    try { var b = window._activeBiz(); if (b && b.role) return b.role; } catch(e){}
    return window._baseStoredRole();
};
// ¿La identidad ACTIVA es de negocio? (para perfil/panel/posts del momento actual)
window._isBizAccount = function(){
    var email = (window.userData && window.userData.email) || '';
    if (email === 'neurovidstudioia@gmail.com') return false;
    try { return !!window._activeBiz(); } catch(e){ return false; }
};
// Rol con el que se DEBE sellar un post nuevo según la identidad activa. Es la fuente
// única para TODOS los composers (feed, perfil, etc.), porque userData.role queda como
// shell 'jugador' con el overlay y sellaba mal (todos los posts salían 'jugador').
window._pubRole = function(){
    var u = window.userData || {};
    if (u._postAsClub || u._activeProfile === 'team') return 'club';
    var ap = u._activeProfile || (window._activeProfileType && window._activeProfileType()) || '';
    if (ap && (String(ap).indexOf('biz:') === 0 || ap === 'negocio')) {
        try { var b = window._activeBiz(); if (b && b.role) return b.role; } catch(e){}
        try { var tr = window._trueRole(); if (tr) return tr; } catch(e){}
    }
    if (ap === 'fanatico') return 'fanatico';
    return u.role || 'jugador';
};
// Id del negocio activo para sellar el post (separa negocios del mismo rol). null si no aplica.
window._pubBizId = function(){
    var u = window.userData || {};
    var ap = u._activeProfile || '';
    if (String(ap).indexOf('biz:') === 0 || ap === 'negocio' || u._activeBizId) {
        var id = (window._activeBizId && window._activeBizId()) || u._activeBizId || null;
        return (id && id !== '__primary__') ? String(id) : null;
    }
    return null;
};
// Foto + encuadre de la identidad ACTIVA, para los composers y el avatar propio.
// Lee _activeBiz() en vez de userData porque el overlay de branding puede no haber
// corrido todavía (_loadMyBusinesses es async) y ahí userData aún es el jugador base.
// Devuelve el mismo contrato que espera _avatarBgCss(): { photo, photo_style }.
window._pubAvatar = function(){
    var u = window.userData || {};
    try {
        var b = window._activeBiz && window._activeBiz();
        if (b) return { photo: b.photo || '', photo_style: b.photo_style || null, name: b.name || u.name || '' };
    } catch(e){}
    return { photo: u.photo || '', photo_style: u.photoStyle || u.photo_style || null, name: u.name || '' };
};
// Cache de equipos del usuario (clubs con owner_email = mi email)
window._myTeamsCache = [];
window._loadMyTeams = async function(){
    const sb = window._sb; const u = window.userData;
    if (!sb || !u || !u.email) return [];
    try {
        // select('*') — evita fallar si falta alguna columna (logo/shield/photo varían por esquema)
        let { data } = await sb.from('clubs').select('*').eq('owner_email', u.email).order('created_at',{ascending:false});
        // Fallback: algunos equipos guardan al capitán en captain_email en vez de owner_email
        if (!data || !data.length) {
            const r2 = await sb.from('clubs').select('*').eq('captain_email', u.email).order('created_at',{ascending:false});
            if (r2.data && r2.data.length) data = r2.data;
        }
        // Último fallback: cache local de Mis Equipos
        if ((!data || !data.length)) {
            try { const c = JSON.parse(localStorage.getItem('canchero_mis_clubes')||'[]'); if (c && c.length) data = c; } catch(e){}
        }
        window._myTeamsCache = data || [];
    } catch(e){
        try { window._myTeamsCache = JSON.parse(localStorage.getItem('canchero_mis_clubes')||'[]'); } catch(_){ window._myTeamsCache = []; }
    }
    return window._myTeamsCache;
};
// Snapshot del perfil base (identidad real de la fila users) — se captura 1 vez por sesión
window._captureBaseSnapshot = function(){
    if (!window.userData) return;
    if (sessionStorage.getItem('canchero_base_snapshot')) return;
    const u = window.userData;
    sessionStorage.setItem('canchero_base_snapshot', JSON.stringify({
        type: window._baseTypeOf(u.role), name:u.name, photo:u.photo,
        nat:u.nat||u.country, coverPhoto:u.coverPhoto, bio:u.bio,
        link: u.link || null,
        photoStyle: u.photoStyle || u.photo_style || null
    }));
};
// Devuelve { jugador?, fanatico?, club? } con los perfiles que tiene el usuario
window._getProfiles = function(){
    const u = window.userData || {};
    let lp = {};
    try { lp = typeof u.linked_profiles === 'string' ? JSON.parse(u.linked_profiles) : (u.linked_profiles || {}); } catch(e){ lp = {}; }
    // Incluir el perfil base (desde el snapshot puro, no el overlay actual)
    let base = null;
    try { base = JSON.parse(sessionStorage.getItem('canchero_base_snapshot')||'null'); } catch(e){}
    if (!base) base = { type: window._baseTypeOf(u.role), name:u.name, photo:u.photo, nat:u.nat||u.country, coverPhoto:u.coverPhoto||u.cover_photo||null, bio:u.bio, photoStyle:u.photoStyle||u.photo_style||null };
    if (!lp[base.type]) lp[base.type] = base;
    // NEGOCIOS: una identidad por cada negocio del usuario. Cada uno con su branding.
    var _biz = window._myBusinesses || [];
    var _primaryName = null;
    if (_biz.length) {
        _biz.forEach(function(b){
            lp['biz:'+b.id] = { type:'negocio', role:b.role, name:b.name, photo:b.photo||'',
                                bio:b.bio||'', coverPhoto:b.coverPhoto||null, bizId:String(b.id), nat:u.nat||u.country };
        });
        // Alias legacy 'negocio' = primer negocio (compat con código viejo).
        lp['negocio'] = lp['biz:'+_biz[0].id];
        _primaryName = _biz[0].name;
    } else if (window._hasBusinesses && window._hasBusinesses()) {
        // Cuenta legacy sin filas cargadas aún: exponer la base como 'negocio'.
        var _tr = window._baseStoredRole();
        var _bn = (base && base.name) || u.name;
        var _bp = (base && base.photo) || u.photo;
        lp['negocio'] = { type:'negocio', role:_tr, name:_bn, photo:_bp, bizId:'__primary__', nat:u.nat||u.country };
        _primaryName = _bn;
    }
    // Con negocios, garantizar una identidad de JUGADOR limpia (no el negocio).
    if (_primaryName && (!lp['jugador'] || lp['jugador'].name === _primaryName)) {
        lp['jugador'] = { type:'jugador', name:'Jugador', photo:'' };
    }
    return lp;
};
window._activeProfileType = function(){
    const u = window.userData || {};
    const stored = localStorage.getItem('canchero_active_profile');
    if (stored) return stored;
    // Cuenta legacy cuyo rol BASE es un negocio: su identidad por defecto es 'negocio'.
    // (Cuentas jugador con negocios agregados arrancan como 'jugador'.)
    if (window._BIZ_ROLES && window._BIZ_ROLES.indexOf(window._baseStoredRole()) !== -1) return 'negocio';
    return window._baseTypeOf(u.role);
};
// Fanático: mover guardados/editar a la línea del nombre (a la derecha, chicos)
window._arrangeFanHeader = function(){
    try {
        const pv = document.getElementById('jugador-perfil');
        if (!pv || !pv.classList.contains('fanatico-profile')) return;
        const nameRow = pv.querySelector('.profile-display-name');
        const actions = pv.querySelector('.profile-header-row > div:last-child');
        if (!nameRow || !actions) return;
        if (nameRow.querySelector('.fan-inline-actions')) return; // ya movidos
        const btns = Array.from(actions.querySelectorAll('button.profile-btn-editar'));
        if (!btns.length) return;
        const wrap = document.createElement('span');
        wrap.className = 'fan-inline-actions';
        // El posicionamiento (absoluto a la derecha) y el centrado del nombre los hace
        // el CSS scoped a .fanatico-profile — así al volver a jugador se revierte SOLO
        // (antes seteaba estilos inline en nameRow que se filtraban al perfil de jugador).
        btns.forEach(b => { b.dataset._fanMoved='1'; wrap.appendChild(b); });
        nameRow.appendChild(wrap);
        actions.style.display = 'none';
    } catch(e){}
};
// Restaurar los botones a su lugar original (perfil de jugador)
window._restoreFanHeader = function(){
    try {
        const pv = document.getElementById('jugador-perfil');
        if (!pv) return;
        const actions = pv.querySelector('.profile-header-row > div:last-child');
        const wrap = pv.querySelector('.fan-inline-actions');
        if (wrap && actions) {
            Array.from(wrap.querySelectorAll('button[data-_fan-moved="1"]')).forEach(b=>{ delete b.dataset._fanMoved; actions.appendChild(b); });
            wrap.remove();
        }
        // Restaurar SIEMPRE la visibilidad del contenedor de acciones (por si quedó oculto)
        if (actions) actions.style.display = '';
        // Limpiar cualquier estilo inline viejo que pudiera haber quedado en el nombre
        const nameRow = pv.querySelector('.profile-display-name');
        if (nameRow) { nameRow.style.position=''; nameRow.style.width=''; nameRow.style.justifyContent=''; nameRow.style.flexWrap=''; }
    } catch(e){}
};
// Etiqueta del perfil activo para el sistema de follows (jugador/fanatico/biz:<id>)
window._myProfileTag = function(){
    const t = (window._activeProfileType && window._activeProfileType()) || 'jugador';
    if (t === 'fanatico') return 'fanatico';
    if (String(t).indexOf('biz:') === 0 || t === 'negocio') {
        var id = window._activeBizId && window._activeBizId();
        if (id && id !== '__primary__') return 'biz:' + id;
        return 'negocio';
    }
    return 'jugador';
};
// Persistir el rol activo en la DB para que quede IGUAL en todos los dispositivos
window._persistActiveProfile = function(){
    try {
        const sb = window._sb; if (!sb || !window.userData || !window.userData.email) return;
        const active = localStorage.getItem('canchero_active_profile') || null;
        let team = null; try { team = JSON.parse(localStorage.getItem('canchero_active_team')||'null'); } catch(e){}
        sb.from('users').update({ active_profile: active, active_team: (active === 'team' ? team : null) })
          .eq('email', window.userData.email)
          .then(function(r){ if (r.error) console.warn('active_profile save:', r.error.message); });
    } catch(e){}
};
// Sync de roles desde la DB (para sesiones ya abiertas / fast-path de login):
// adopta linked_profiles + rol activo guardados y refresca pill/barra si cambió.
window._syncRolesFromDb = async function(){
    try {
        const sb = window._sb; const u = window.userData;
        if (!sb || !u || !u.email || window._rolesSyncDone) return;
        window._rolesSyncDone = true;
        const { data } = await sb.from('users').select('linked_profiles,active_profile,active_team').eq('email', u.email).maybeSingle();
        if (!data) return;
        let changed = false;
        if (data.linked_profiles && Object.keys(data.linked_profiles).length) {
            const localLp = (typeof u.linked_profiles === 'string') ? u.linked_profiles : JSON.stringify(u.linked_profiles || {});
            if (JSON.stringify(data.linked_profiles) !== localLp) { u.linked_profiles = data.linked_profiles; changed = true; }
        }
        const localActive = localStorage.getItem('canchero_active_profile');
        if (data.active_profile && data.active_profile !== localActive) {
            localStorage.setItem('canchero_active_profile', data.active_profile);
            if (data.active_profile === 'team' && data.active_team) localStorage.setItem('canchero_active_team', JSON.stringify(data.active_team));
            changed = true;
        }
        if (changed) {
            try { localStorage.setItem('canchero_user', JSON.stringify(u)); } catch(e){}
            window._applyActiveProfileOverlay();
            try { window._renderProfileSwitcher && window._renderProfileSwitcher(); } catch(e){}
            try { window._rebuildBottomNav && window._rebuildBottomNav(); } catch(e){}
        }
    } catch(e){}
};
// SYNC MULTI-DISPOSITIVO (P0.3, pedido 2026-07-09): los cambios hechos en otro
// dispositivo (foto/portada/bio/nombre/roles) se adoptan solos al volver a la app
// y cada 4 minutos. La DB es la fuente de verdad.
window._syncProfileLive = async function(){
    try {
        const sb = window._sb, u = window.userData;
        if (!sb || !u || !u.email) return;
        const { data: d } = await sb.from('users').select('name,photo,photo_style,cover_photo,bio,linked_profiles,active_profile').eq('email', u.email).maybeSingle();
        if (!d) return;
        let changed = false;
        let snap = {}; try { snap = JSON.parse(sessionStorage.getItem('canchero_base_snapshot')||'{}') || {}; } catch(e){}
        if (d.photo && snap.photo !== d.photo) { snap.photo = d.photo; changed = true; }
        if (d.cover_photo && snap.coverPhoto !== d.cover_photo) { snap.coverPhoto = d.cover_photo; changed = true; }
        if (d.name && snap.name !== d.name) { snap.name = d.name; changed = true; }
        if (d.bio != null && snap.bio !== d.bio) { snap.bio = d.bio; changed = true; }
        if (d.photo_style) snap.photoStyle = d.photo_style;
        try { sessionStorage.setItem('canchero_base_snapshot', JSON.stringify(snap)); } catch(e){}
        if (d.linked_profiles) {
            const lpNew = JSON.stringify(d.linked_profiles);
            const lpOld = typeof u.linked_profiles === 'string' ? u.linked_profiles : JSON.stringify(u.linked_profiles || {});
            if (lpNew !== lpOld) { u.linked_profiles = d.linked_profiles; changed = true; }
        }
        try { if (window._loadMyBusinesses) await window._loadMyBusinesses(); } catch(e){}
        if (changed) {
            // Si la identidad activa es la BASE, refrescar userData con lo nuevo
            const act = (window._activeProfileType && window._activeProfileType()) || 'jugador';
            const baseT = window._baseTypeOf ? window._baseTypeOf((window._baseStoredRole && window._baseStoredRole()) || u.role) : 'jugador';
            if (act === baseT) {
                if (d.photo) u.photo = d.photo;
                if (d.photo_style) { u.photoStyle = d.photo_style; u.photo_style = d.photo_style; }
                if (d.cover_photo) { u.coverPhoto = d.cover_photo; u.cover_photo = d.cover_photo; }
                if (d.name) u.name = d.name;
                if (d.bio != null) u.bio = d.bio;
            }
            try { window._applyActiveProfileOverlay && window._applyActiveProfileOverlay(); } catch(e){}
            try { if (typeof applyUserData === 'function') applyUserData(); } catch(e){}
            try { window._renderProfileSwitcher && window._renderProfileSwitcher(); } catch(e){}
        }
    } catch(e){}
};
document.addEventListener('visibilitychange', function(){ if (!document.hidden) setTimeout(function(){ window._syncProfileLive && window._syncProfileLive(); }, 800); });
setInterval(function(){ try { if (!document.hidden) window._syncProfileLive && window._syncProfileLive(); } catch(e){} }, 240000);

// Cambiar al perfil <type>: overlay de identidad + navegar
// Aplica en memoria la identidad del perfil ACTIVO sobre userData (no toca canchero_user base)
window._applyActiveProfileOverlay = function(){
    if (!window.userData) return;
    const active = window._activeProfileType();
    // Actuar como EQUIPO: identidad del club (nombre/foto/bandera) sobre el shell de jugador
    if (active === 'team') {
        let t = null; try { t = JSON.parse(localStorage.getItem('canchero_active_team')||'null'); } catch(e){}
        if (t && t.id) {
            window.userData.name = t.name || window.userData.name;
            window.userData.photo = t.photo || '';
            // El escudo del club NO usa el encuadre (photoStyle) del jugador —
            // eso cortaba/desplazaba el avatar en el feed al publicar como club.
            window.userData.photoStyle = null;
            window.userData.photo_style = null;
            if (t.nat) window.userData.nat = t.nat;
            // Portada PROPIA del equipo (clubs.cover_photo) — nunca la del rol anterior
            window.userData.coverPhoto = t.coverPhoto || t.cover_photo || null;
            window.userData.cover_photo = window.userData.coverPhoto;
            window.userData.role = 'jugador';
            window.userData._activeProfile = 'team';
            window.userData._activeClubId = t.id;
            window.userData._postAsClub = true;
            return;
        }
        // Sin snapshot válido del equipo → volver al perfil base para que el pill,
        // la barra y el perfil no queden en un estado mixto (icono/nombre de jugador
        // con secciones de equipo).
        try { localStorage.setItem('canchero_active_profile', window._baseTypeOf(window.userData.role)); } catch(e){}
    }
    // NEGOCIO activo ('biz:<id>' o alias 'negocio'): branding del negocio sobre el shell.
    // El rol real lo da _trueRole()/_activeBiz(); el shell queda como 'jugador'.
    if (active && (active.indexOf('biz:') === 0 || active === 'negocio')) {
        var b = window._activeBiz && window._activeBiz();
        if (b) {
            window.userData.name = b.name || window.userData.name;
            window.userData.photo = b.photo || '';
            // Encuadre del NEGOCIO (no el del jugador base, que descuadraba el logo).
            window.userData.photoStyle = b.photo_style || null;
            window.userData.photo_style = b.photo_style || null;
            window.userData.bio = (b.bio != null) ? b.bio : '';
            window.userData.coverPhoto = b.coverPhoto || null;
            window.userData.cover_photo = b.coverPhoto || null;
            if (b.nat) window.userData.nat = b.nat;
            window.userData.role = 'jugador';
            window.userData._activeProfile = active;
            window.userData._activeBizId = String(b.id);
            window.userData._postAsClub = false;
            window.userData._activeClubId = null;
            return;
        }
    } else {
        // Al salir de una identidad de negocio, limpiar el marcador.
        window.userData._activeBizId = null;
    }
    // Rol base desde el rol PERSISTIDO: userData.role queda mutado por el overlay
    // ('fanatico' activo hacía creer que la base era fanático → la portada del
    // jugador se filtraba al fanático y viceversa).
    const baseType = window._baseTypeOf((window._baseStoredRole && window._baseStoredRole()) || window.userData.role);
    const profs = window._getProfiles();
    const p = profs[active];
    if (!p || (active === baseType && !window.userData._activeProfile)) { window.userData._postAsClub = false; window.userData._activeClubId = null; return; }
    if (!p) return;
    // Identidad COMPLETA del perfil activo — cada rol es independiente:
    // el fanático NO hereda foto/encuadre/bio/link del jugador (y viceversa,
    // al volver al rol base se restaura todo desde el snapshot).
    window.userData.name = p.name || window.userData.name;
    window.userData.photo = p.photo || '';
    window.userData.photoStyle = p.photoStyle || null;
    window.userData.photo_style = p.photoStyle || null;
    window.userData.bio = (p.bio != null) ? p.bio : '';
    window.userData.link = (p.link != null) ? p.link : '';
    // Portada: si la copia enlazada de la identidad BASE no tiene portada,
    // usar la del snapshot (users.cover_photo) — sin esto, la portada guardada
    // "desaparecía" al cambiar de rol y volver.
    var _covP = p.coverPhoto || null;
    if (!_covP && active === baseType) {
        try { var _snC = JSON.parse(sessionStorage.getItem('canchero_base_snapshot')||'null'); _covP = (_snC && _snC.coverPhoto) || null; } catch(e){}
    }
    window.userData.coverPhoto = _covP;
    window.userData.cover_photo = _covP;
    if (p.nat) window.userData.nat = p.nat;
    window.userData.role = (active==='fanatico') ? 'fanatico' : 'jugador';
    window.userData._activeProfile = active;
    window.userData._postAsClub = false;
    window.userData._activeClubId = null;
};
// Cambiar a actuar como un EQUIPO específico
window._switchToTeam = function(clubId){
    const t = (window._myTeamsCache||[]).find(x => String(x.id) === String(clubId));
    if (!t) return;
    window._captureBaseSnapshot();
    const snap = { id:t.id, name:t.name, photo: t.logo||t.shield||t.photo||'', nat: t.nat||t.country||null, coverPhoto: t.cover_photo||t.cover||null };
    try { localStorage.setItem('canchero_active_team', JSON.stringify(snap)); } catch(e){}
    localStorage.setItem('canchero_active_profile', 'team');
    window.userData._activeProfile = 'team';
    window._persistActiveProfile();
    window._applyActiveProfileOverlay();
    const _sheet = document.getElementById('profile-switcher-sheet'); if (_sheet) _sheet.remove();
    if (typeof applyUserData === 'function') applyUserData();
    try { if (window._rebuildBottomNav) window._rebuildBottomNav(); } catch(e){}
    // Al cambiar de equipo, abrir el FEED del dashboard (tab 'feed'), NO la landing
    // 'home' (que mostraba la pantalla de bienvenida "ENTRÁ COMO...").
    navigate('jugador');
    try { if (typeof switchDashboardTab === 'function') switchDashboardTab('jugador', 'feed', null); } catch(e){}
    if (typeof showToast === 'function') showToast('Ahora publicás como ' + (t.name||'tu equipo'), 'success', 2500);
    window._renderProfileSwitcher();
};
window._switchToProfile = function(type){
    if (!window.userData) return;
    const profs = window._getProfiles();
    if (!profs[type]) return;
    window._captureBaseSnapshot();
    localStorage.setItem('canchero_active_profile', type);
    window.userData._activeProfile = type;
    window._persistActiveProfile();
    window._applyActiveProfileOverlay();
    const _sheet = document.getElementById('profile-switcher-sheet'); if (_sheet) _sheet.remove();
    if (typeof applyUserData === 'function') applyUserData();
    // Reconstruir la barra inferior según el tipo (fanático = Comunidades)
    try { if (window._rebuildBottomNav) window._rebuildBottomNav(); } catch(e){}
    // Al cambiar de rol, abrir el FEED del dashboard (tab 'feed') con el rol ya
    // aplicado — NO la landing 'home' (que mostraba "ENTRÁ COMO JUGADOR/...").
    navigate('jugador');
    try { if (typeof switchDashboardTab === 'function') switchDashboardTab('jugador', 'feed', null); } catch(e){}
    if (typeof showToast === 'function') {
        var _lbl = (profs[type] && profs[type].name) || (window._profileMeta[type] && window._profileMeta[type].label) || type;
        showToast('Ahora estás como ' + _lbl, 'success', 2500);
    }
    window._renderProfileSwitcher();
};
// Crear un perfil nuevo del tipo indicado
// FANÁTICO: registro REAL con identidad propia (foto/alias/bio independientes
// del jugador) — cada rol es un usuario distinto aunque comparta cuenta.
window._createLinkedProfile = async function(type){
    if (!window.userData) return;
    if (type === 'fanatico') { window._openFanRegistration(); return; }
    const defName = window.userData.name || (window.userData.email||'').split('@')[0];
    const nombre = prompt('Nombre para tu perfil de ' + (window._profileMeta[type]?.label||type) + ':', type==='club' ? 'Mi Club' : defName);
    if (nombre === null) return;
    let lp = {};
    try { lp = typeof window.userData.linked_profiles === 'string' ? JSON.parse(window.userData.linked_profiles) : (window.userData.linked_profiles||{}); } catch(e){ lp = {}; }
    lp[type] = { type:type, name:(nombre||defName), photo: '', nat: window.userData.nat||window.userData.country };
    window.userData.linked_profiles = lp;
    try { localStorage.setItem('canchero_user', JSON.stringify(window.userData)); } catch(e){}
    try {
        const sb = window._sb;
        if (sb) { const r = await sb.from('users').update({ linked_profiles: lp }).eq('email', window.userData.email); if (r.error) console.warn('linked_profiles col?', r.error.message); }
    } catch(e){}
    if (typeof showToast === 'function') showToast('Perfil de ' + (window._profileMeta[type]?.label||type) + ' creado', 'success');
    window._switchToProfile(type);
};
// ── Registro completo de FANÁTICO (wizard, no prompt) ──────────────────────
window._fanRegPhotoB64 = null;
window._openFanRegistration = function(){
    const sheet = document.getElementById('profile-switcher-sheet'); if (sheet) sheet.remove();
    const ex = document.getElementById('fan-reg-modal'); if (ex) { ex.remove(); return; }
    window._fanRegPhotoB64 = null;
    const m = document.createElement('div');
    m.id = 'fan-reg-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:21200;background:rgba(0,0,0,0.85);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:18px;box-sizing:border-box;';
    m.onclick = function(e){ if (e.target === m) m.remove(); };
    m.innerHTML = `<div style="width:100%;max-width:420px;background:#0d0d0d;border:1px solid rgba(255,215,0,0.25);border-radius:20px;padding:22px 18px;max-height:88vh;overflow-y:auto;-webkit-overflow-scrolling:touch;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
            <div style="display:flex;align-items:center;gap:10px;">
                <div style="width:38px;height:38px;border-radius:50%;background:rgba(255,215,0,0.1);border:1px solid rgba(255,215,0,0.4);display:flex;align-items:center;justify-content:center;color:#FFD700;"><i class='bx bx-crown' style="font-size:20px;"></i></div>
                <div><div style="font-size:10px;color:#FFD700;font-weight:900;letter-spacing:1.5px;">NUEVO ROL</div><div style="font-size:16px;font-weight:900;color:#fff;">Registro de Fanático</div></div>
            </div>
            <button onclick="document.getElementById('fan-reg-modal').remove()" style="background:rgba(255,255,255,0.06);border:none;color:#888;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:17px;line-height:1;">&times;</button>
        </div>
        <p style="font-size:11.5px;color:#888;margin:6px 0 16px;line-height:1.5;">Tu perfil de fanático es INDEPENDIENTE del de jugador: tiene su propia foto, alias e info. Es gratis.</p>
        <div style="display:flex;justify-content:center;margin-bottom:16px;">
            <label style="position:relative;cursor:pointer;">
                <div id="fan-reg-photo-prev" style="width:92px;height:92px;border-radius:16px;border:2px dashed rgba(255,215,0,0.5);background:#141414;display:flex;align-items:center;justify-content:center;color:#FFD700;background-size:cover;background-position:center;"><i class='bx bx-camera' style="font-size:28px;"></i></div>
                <div style="position:absolute;bottom:-6px;right:-6px;width:26px;height:26px;border-radius:50%;background:#FFD700;color:#000;display:flex;align-items:center;justify-content:center;border:2px solid #0d0d0d;"><i class='bx bx-plus' style="font-size:15px;"></i></div>
                <input type="file" accept="image/*" style="display:none;" onchange="window._fanRegPickPhoto(event)">
            </label>
        </div>
        <div style="text-align:center;font-size:10px;color:#666;margin-bottom:14px;">Foto de perfil del FANÁTICO (propia, no la de jugador)</div>
        <div id="fan-reg-photo-ctrl" style="display:none;background:#141414;border:1px solid #232323;border-radius:12px;padding:10px 12px;margin-bottom:14px;">
            <div style="font-size:9px;font-weight:800;color:#888;letter-spacing:1.5px;margin-bottom:8px;">AJUSTÁ TU FOTO (tamaño y posición)</div>
            <label style="font-size:9px;color:#666;display:block;">ZOOM</label>
            <input type="range" id="fan-reg-zoom" min="100" max="250" value="100" oninput="window._fanRegUpdatePrev()" style="width:100%;accent-color:var(--accent);">
            <div style="display:flex;gap:10px;">
                <div style="flex:1;"><label style="font-size:9px;color:#666;display:block;">HORIZONTAL</label><input type="range" id="fan-reg-x" min="-50" max="50" value="0" oninput="window._fanRegUpdatePrev()" style="width:100%;accent-color:var(--accent);"></div>
                <div style="flex:1;"><label style="font-size:9px;color:#666;display:block;">VERTICAL</label><input type="range" id="fan-reg-y" min="-50" max="50" value="0" oninput="window._fanRegUpdatePrev()" style="width:100%;accent-color:var(--accent);"></div>
            </div>
        </div>
        <label style="font-size:9px;font-weight:800;color:#666;letter-spacing:1.5px;display:block;margin-bottom:5px;">NOMBRE O ALIAS *</label>
        <input id="fan-reg-name" type="text" placeholder="Ej: El Hincha Celeste" style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:11px 12px;border-radius:10px;font-size:14px;font-weight:600;outline:none;box-sizing:border-box;margin-bottom:12px;">
        <label style="font-size:9px;font-weight:800;color:#666;letter-spacing:1.5px;display:block;margin-bottom:5px;">PAÍS</label>
        <input id="fan-reg-nat" type="text" value="${((window.userData&&window.userData.nat)||'Uruguay').replace(/"/g,'&quot;')}" style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:11px 12px;border-radius:10px;font-size:13px;outline:none;box-sizing:border-box;margin-bottom:12px;">
        <label style="font-size:9px;font-weight:800;color:#666;letter-spacing:1.5px;display:block;margin-bottom:5px;">BIO DE HINCHA (opcional)</label>
        <textarea id="fan-reg-bio" rows="2" placeholder="¿De qué cuadro sos? ¿Qué contenido vas a crear?" style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:11px 12px;border-radius:10px;font-size:13px;resize:none;outline:none;box-sizing:border-box;margin-bottom:16px;"></textarea>
        <button id="fan-reg-save" onclick="window._fanRegSubmit()" style="width:100%;background:linear-gradient(135deg,#FFD700,#e6b800);color:#000;border:none;border-radius:12px;padding:14px;font-weight:900;font-size:14px;cursor:pointer;letter-spacing:.4px;">CREAR MI PERFIL DE FANÁTICO</button>
    </div>`;
    document.body.appendChild(m);
    setTimeout(function(){ try { document.getElementById('fan-reg-name').focus(); } catch(e){} }, 150);
};
window._fanRegPickPhoto = function(event){
    const f = event.target.files && event.target.files[0]; if (!f) return;
    const r = new FileReader();
    r.onload = function(e){
        window._fanRegPhotoB64 = e.target.result;
        const prev = document.getElementById('fan-reg-photo-prev');
        if (prev) { prev.style.backgroundImage = "url('" + e.target.result + "')"; prev.innerHTML = ''; prev.style.borderStyle = 'solid'; }
        const ctrl = document.getElementById('fan-reg-photo-ctrl');
        if (ctrl) ctrl.style.display = 'block';
        window._fanRegUpdatePrev();
    };
    r.readAsDataURL(f);
};
// Aplica el encuadre elegido (zoom/x/y) al preview — mismo formato photoStyle
// que usa el resto de la app: position (50+x)% (50+y)%, size zoom%.
window._fanRegUpdatePrev = function(){
    const prev = document.getElementById('fan-reg-photo-prev');
    if (!prev) return;
    const z = parseFloat((document.getElementById('fan-reg-zoom')||{}).value || 100);
    const x = parseInt((document.getElementById('fan-reg-x')||{}).value || 0);
    const y = parseInt((document.getElementById('fan-reg-y')||{}).value || 0);
    prev.style.backgroundSize = z > 100 ? z + '%' : 'cover';
    prev.style.backgroundPosition = (50 + x) + '% ' + (50 + y) + '%';
};
window._fanRegPhotoStyle = function(){
    const z = (document.getElementById('fan-reg-zoom')||{}).value;
    const x = (document.getElementById('fan-reg-x')||{}).value;
    const y = (document.getElementById('fan-reg-y')||{}).value;
    if (z == null) return null;
    // Devolver SIEMPRE el encuadre elegido (aunque sea el neutro): así lo que se ve
    // en la previsualización es EXACTAMENTE lo que se renderiza en toda la app
    // (antes el neutro devolvía null y los renderers aplicaban otro recorte por defecto).
    return { zoom: z, x: x || 0, y: y || 0 };
};
window._fanRegSubmit = async function(){
    if (!window.userData) return;
    const name = (document.getElementById('fan-reg-name')||{}).value || '';
    if (!name.trim()) { showToast && showToast('Poné un nombre o alias para tu perfil de fanático.', 'warning'); return; }
    const btn = document.getElementById('fan-reg-save');
    if (btn) { btn.disabled = true; btn.textContent = 'Creando...'; }
    let photoUrl = '';
    if (window._fanRegPhotoB64) {
        try {
            const blob = await (await fetch(window._fanRegPhotoB64)).blob();
            if (window.cloudUpload) {
                const r = await window.cloudUpload(blob, { folder:'canchero/fan_profiles' });
                if (r && r.url) photoUrl = r.url;
            } else if (window._sb) {
                const fp = 'fan_profiles/' + window.userData.email + '/avatar_' + Date.now() + '.jpg';
                const up = await window._sb.storage.from('media').upload(fp, blob, { upsert:true, contentType:'image/jpeg' });
                if (!up.error) { const { data: ud } = window._sb.storage.from('media').getPublicUrl(fp); photoUrl = (ud && ud.publicUrl) || ''; }
            }
            if (!photoUrl) photoUrl = window._fanRegPhotoB64;
        } catch(e) { photoUrl = window._fanRegPhotoB64; }
    }
    let lp = {};
    try { lp = typeof window.userData.linked_profiles === 'string' ? JSON.parse(window.userData.linked_profiles) : (window.userData.linked_profiles||{}); } catch(e){ lp = {}; }
    lp.fanatico = {
        type: 'fanatico',
        name: name.trim(),
        photo: photoUrl,
        photoStyle: window._fanRegPhotoStyle ? window._fanRegPhotoStyle() : null,
        nat: ((document.getElementById('fan-reg-nat')||{}).value || '').trim() || window.userData.nat || 'Uruguay',
        bio: ((document.getElementById('fan-reg-bio')||{}).value || '').trim()
    };
    window.userData.linked_profiles = lp;
    try { localStorage.setItem('canchero_user', JSON.stringify(window.userData)); } catch(e){}
    try {
        const sb = window._sb;
        if (sb) { const r = await sb.from('users').update({ linked_profiles: lp }).eq('email', window.userData.email); if (r.error) console.warn('linked_profiles col?', r.error.message); }
    } catch(e){}
    document.getElementById('fan-reg-modal')?.remove();
    showToast && showToast('¡Perfil de fanático creado!', 'success');
    window._switchToProfile('fanatico');
};
// Hoja inferior con los perfiles disponibles + equipos + agregar
window._openProfileSwitcher = async function(){
    const ex = document.getElementById('profile-switcher-sheet'); if (ex) { ex.remove(); return; }
    const sheet = document.createElement('div');
    sheet.id = 'profile-switcher-sheet';
    sheet.style.cssText = 'position:fixed;inset:0;z-index:21000;background:rgba(0,0,0,0.7);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    sheet.onclick = function(e){ if (e.target === sheet) sheet.remove(); };
    sheet.innerHTML = `<div id="psw-card" style="width:100%;max-width:400px;background:#0d0d0d;border:1px solid #1e1e1e;border-radius:20px;padding:20px 16px;box-shadow:0 20px 60px rgba(0,0,0,0.7);max-height:80vh;overflow-y:auto;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">
          <div style="font-size:13px;font-weight:900;color:#fff;letter-spacing:.5px;">CAMBIAR DE PERFIL</div>
          <button onclick="document.getElementById('profile-switcher-sheet').remove()" style="background:rgba(255,255,255,0.06);border:none;color:#888;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:18px;line-height:1;">&times;</button>
        </div>
        <div id="psw-body"><div style="text-align:center;padding:24px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:22px;color:var(--accent);"></i></div></div>
    </div>`;
    document.body.appendChild(sheet);

    await window._loadMyTeams();
    try { await window._loadMyBusinesses(); } catch(e){}
    const body = document.getElementById('psw-body'); if (!body) return;
    const profs = window._getProfiles();
    const active = window._activeProfileType();
    const activeTeamId = (window.userData && window.userData._activeClubId) || null;

    const _uRoleSw = (window._trueRole ? window._trueRole() : ((window.userData && window.userData.role) || ''));
    const _isBizSw = window._isBizAccount ? window._isBizAccount() : false;
    const _bizMetaSw = {
        tienda:{label:'Tienda',icon:'bx-store'}, club:{label:'Complejo',icon:'bx-cancha'},
        complejo:{label:'Complejo',icon:'bx-cancha'}, organizacion:{label:'Organización',icon:'bx-trophy'},
        profesional:{label:'Profesional',icon:'bx-briefcase'}, sponsor:{label:'Sponsor',icon:'bx-dollar-circle'}
    };
    const row = (t) => {
        const p = profs[t] || {};
        // Negocios (biz:<id> o alias 'negocio') toman label/icono del rol real del negocio.
        const _isBizRow = (p.type === 'negocio' || t === 'negocio' || (t||'').indexOf('biz:') === 0);
        let meta = _isBizRow
            ? (_bizMetaSw[p.role || _uRoleSw] || window._profileMeta.negocio)
            : window._profileMeta[t];
        let isAct = (t === active && active !== 'team');
        // La identidad activa de negocio puede estar guardada como alias 'negocio' → marcar
        // igual el renglón del negocio correspondiente por su id.
        if (!isAct && _isBizRow && window._activeBizId) {
            var _abid = window._activeBizId();
            if (_abid && p.bizId && String(_abid) === String(p.bizId)) isAct = true;
        }
        // MISMO encuadre que toda la app (photoStyle de esa identidad o rostro center 25%)
        const av = p.photo ? ((window._avatarBgCss && window._avatarBgCss({ photo: p.photo, photo_style: p.photoStyle })) || `background-image:url('${p.photo}');background-size:cover;background-position:center 25%;`) : 'background:#1a1a1a;';
        // Botón eliminar identidad (negocios, fanático, jugador). El equipo tiene su propio flujo.
        const delBtn = `<button onclick="event.stopPropagation();window._deleteIdentity('${t}')" aria-label="Eliminar" title="Eliminar identidad" style="flex:0 0 30px;width:30px;height:30px;border-radius:50%;background:transparent;border:1px solid #2a2a2a;color:#777;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:15px;"><i class='bx bx-trash'></i></button>`;
        return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;">
            <button onclick="window._switchToProfile('${t}')" style="flex:1;min-width:0;display:flex;align-items:center;gap:12px;background:${isAct?'rgba(186,255,0,0.08)':'transparent'};border:1px solid ${isAct?'rgba(186,255,0,0.3)':'#222'};border-radius:14px;padding:12px 14px;cursor:pointer;text-align:left;">
              <div style="width:44px;height:44px;border-radius:50%;${av}flex-shrink:0;display:flex;align-items:center;justify-content:center;color:var(--accent);">${p.photo?'':`<i class='bx ${meta.icon}' style="font-size:22px;"></i>`}</div>
              <div style="flex:1;min-width:0;"><div style="font-weight:800;font-size:14px;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${p.name||meta.label}</div><div style="font-size:11px;color:#888;">${meta.label}</div></div>
              ${isAct?'<i class="bx bx-check-circle" style="font-size:20px;color:var(--accent);flex-shrink:0;"></i>':''}
            </button>
            ${delBtn}
        </div>`;
    };
    const teamRow = (t) => {
        const isAct = (active === 'team' && String(activeTeamId) === String(t.id));
        const photo = t.logo||t.shield||t.photo||'';
        const av = photo ? `background-image:url('${photo}');background-size:cover;background-position:center;` : 'background:#1a1a1a;';
        // Solo el dueño/capitán puede eliminar el club.
        const _meEmail = ((window.userData&&window.userData.email)||'').toLowerCase();
        const _owner = ((t.owner_email||t.captain_email||'')+'').toLowerCase();
        const _canDel = !_owner || _owner === _meEmail;
        const delBtn = _canDel ? `<button onclick="event.stopPropagation();window._deleteIdentity('team:${t.id}')" aria-label="Eliminar" title="Eliminar club" style="flex:0 0 30px;width:30px;height:30px;border-radius:50%;background:transparent;border:1px solid #2a2a2a;color:#777;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:15px;"><i class='bx bx-trash'></i></button>` : '';
        return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;">
            <button onclick="window._switchToTeam('${t.id}')" style="flex:1;min-width:0;display:flex;align-items:center;gap:12px;background:${isAct?'rgba(186,255,0,0.08)':'transparent'};border:1px solid ${isAct?'rgba(186,255,0,0.3)':'#222'};border-radius:14px;padding:12px 14px;cursor:pointer;text-align:left;">
              <div style="width:44px;height:44px;border-radius:50%;${av}flex-shrink:0;display:flex;align-items:center;justify-content:center;color:var(--accent);">${photo?'':`<i class='bx bx-shield' style="font-size:22px;"></i>`}</div>
              <div style="flex:1;min-width:0;"><div style="font-weight:800;font-size:14px;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${window.escH?window.escH(t.name||'Equipo'):(t.name||'Equipo')}</div><div style="font-size:11px;color:#888;">Equipo</div></div>
              ${isAct?'<i class="bx bx-check-circle" style="font-size:20px;color:var(--accent);flex-shrink:0;"></i>':''}
            </button>
            ${delBtn}
        </div>`;
    };
    const fanatOnboard = `<button onclick="window._createLinkedProfile('fanatico')" style="display:flex;align-items:center;gap:12px;width:100%;background:transparent;border:1px dashed #2a2a2a;border-radius:14px;padding:12px 14px;cursor:pointer;text-align:left;margin-bottom:8px;">
        <div style="width:44px;height:44px;border-radius:50%;background:#141414;flex-shrink:0;display:flex;align-items:center;justify-content:center;color:#666;"><i class='bx bx-crown' style="font-size:22px;"></i></div>
        <div style="flex:1;"><div style="font-weight:800;font-size:14px;color:#ccc;">Activar perfil de Fanático</div><div style="font-size:11px;color:#666;">Comunidades, contenido e hincha</div></div></button>`;
    const createTeam = `<button onclick="document.getElementById('profile-switcher-sheet').remove();window.openClubCreator&&window.openClubCreator()" style="display:flex;align-items:center;gap:12px;width:100%;background:transparent;border:1px dashed #2a2a2a;border-radius:14px;padding:12px 14px;cursor:pointer;text-align:left;margin-bottom:8px;">
        <div style="width:44px;height:44px;border-radius:50%;background:#141414;flex-shrink:0;display:flex;align-items:center;justify-content:center;color:#666;"><i class='bx bx-plus' style="font-size:22px;"></i></div>
        <div style="flex:1;"><div style="font-weight:800;font-size:14px;color:#ccc;">Crear / registrar equipo</div><div style="font-size:11px;color:#666;">Publicá como tu club</div></div></button>`;

    // Roles de NEGOCIO (tienda / complejo): requieren registro de negocio aparte
    const bizRow = (icon, nombre, sub, role) => `<button onclick="document.getElementById('profile-switcher-sheet').remove();window._registerBizFromSwitcher&&window._registerBizFromSwitcher('${role}')" style="display:flex;align-items:center;gap:12px;width:100%;background:transparent;border:1px dashed #2a2a2a;border-radius:14px;padding:12px 14px;cursor:pointer;text-align:left;margin-bottom:8px;">
        <div style="width:44px;height:44px;border-radius:50%;background:#141414;flex-shrink:0;display:flex;align-items:center;justify-content:center;color:#666;"><i class='bx ${icon}' style="font-size:22px;"></i></div>
        <div style="flex:1;"><div style="font-weight:800;font-size:14px;color:#ccc;">${nombre}</div><div style="font-size:11px;color:#666;">${sub}</div></div></button>`;

    const teams = window._myTeamsCache || [];
    body.innerHTML =
        row('jugador') +
        (profs.fanatico ? row('fanatico') : fanatOnboard) +
        `<div style="font-size:11px;font-weight:800;color:#555;letter-spacing:1px;margin:12px 0 8px;">EQUIPOS</div>` +
        (teams.length ? teams.map(teamRow).join('') : '<div style="font-size:12px;color:#666;margin-bottom:8px;padding:0 2px;">Todavía no tenés equipos.</div>') +
        createTeam +
        `<div style="font-size:11px;font-weight:800;color:#555;letter-spacing:1px;margin:12px 0 8px;">MIS NEGOCIOS</div>` +
        // P5.2: negocios AGRUPADOS por tipo (tiendas juntas, complejos juntos, etc.),
        // con sub-título por grupo y orden alfabético dentro del grupo.
        ((window._myBusinesses && window._myBusinesses.length)
            ? (function(){
                var groups = [
                    { roles:['tienda','store','shop'], label:'Tiendas' },
                    { roles:['club','complejo','cancha'], label:'Complejos' },
                    { roles:['organizacion','liga','escuela'], label:'Organizaciones' },
                    { roles:['profesional'], label:'Profesionales' },
                    { roles:['sponsor'], label:'Sponsors' }
                ];
                var used = {}, html = '';
                groups.forEach(function(g){
                    var list = (window._myBusinesses||[]).filter(function(b){
                        return g.roles.indexOf((b.role||'').toLowerCase()) !== -1;
                    }).sort(function(a,b2){ return (a.name||'').localeCompare(b2.name||''); });
                    if (!list.length) return;
                    list.forEach(function(b){ used[b.id] = true; });
                    html += '<div style="font-size:10px;font-weight:800;color:#444;letter-spacing:.5px;margin:6px 0 4px;padding-left:2px;">' + g.label.toUpperCase() + '</div>'
                          + list.map(function(b){ return row('biz:'+b.id); }).join('');
                });
                var rest = (window._myBusinesses||[]).filter(function(b){ return !used[b.id]; });
                if (rest.length) html += rest.map(function(b){ return row('biz:'+b.id); }).join('');
                return html;
              })()
            : (profs.negocio ? row('negocio') : '')) +
        bizRow('bx-store', 'Registrar mi Tienda', 'Vendé indumentaria y artículos de fútbol', 'tienda') +
        bizRow('bx-cancha', 'Registrar mi Complejo', 'Canchas, reservas y torneos', 'complejo') +
        bizRow('bx-trophy', 'Registrar mi Organización', 'Organizá torneos, ligas y eventos', 'organizacion');
};
// A4: registrar/activar una identidad de NEGOCIO desde el switcher (usuario ya logueado).
// Antes los botones abrían el login → "abría como jugador". Ahora crea el negocio
// (gratis/auto-aprobado) para el email actual y cambia a la identidad de negocio.
window._BIZ_LABELS = { tienda:'Tienda', complejo:'Complejo', organizacion:'Organización' };
// Abrir el modal de registro de negocio (reemplaza al prompt() nativo, que la extensión
// de Chrome bloquea/auto-acepta y que además prellenaba mal el nombre).
window._registerBizFromSwitcher = function(role){
    if (!window.userData || !window.userData.email) { if (window._showLoginModal) window._showLoginModal(); return; }
    var labels = window._BIZ_LABELS;
    var icons = { tienda:'bx-store', complejo:'bx-cancha', organizacion:'bx-trophy' };
    var ex = document.getElementById('biz-reg-modal'); if (ex) ex.remove();
    var m = document.createElement('div');
    m.id = 'biz-reg-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:22000;background:rgba(0,0,0,0.72);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    m.onclick = function(e){ if (e.target === m) m.remove(); };
    m.innerHTML = '<div style="width:100%;max-width:380px;background:#0d0d0d;border:1px solid #1e1e1e;border-radius:20px;padding:22px 18px;box-shadow:0 20px 60px rgba(0,0,0,0.7);">'
        + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;"><i class="bx ' + (icons[role]||'bx-store') + '" style="font-size:24px;color:var(--accent);"></i>'
        + '<div style="font-size:16px;font-weight:900;color:#fff;">Registrar ' + (labels[role]||'Negocio') + '</div></div>'
        + '<p style="font-size:11.5px;color:#888;margin:4px 0 16px;line-height:1.5;">Es una identidad NUEVA e independiente, con su propia foto, bio y datos. No reemplaza tus otros perfiles ni negocios: podés tenerlos todos a la vez.</p>'
        + '<div style="display:flex;justify-content:center;margin-bottom:12px;"><label style="position:relative;cursor:pointer;">'
        + '<div id="biz-reg-photo-prev" style="width:84px;height:84px;border-radius:16px;border:2px dashed rgba(186,255,0,0.5);background:#141414;display:flex;align-items:center;justify-content:center;color:var(--accent);background-size:cover;background-position:center;"><i class=\'bx bx-camera\' style="font-size:26px;"></i></div>'
        + '<div style="position:absolute;bottom:-6px;right:-6px;width:24px;height:24px;border-radius:50%;background:var(--accent);color:#000;display:flex;align-items:center;justify-content:center;border:2px solid #0d0d0d;"><i class=\'bx bx-plus\' style="font-size:14px;"></i></div>'
        + '<input type="file" accept="image/*" style="display:none;" onchange="window._bizRegPickPhoto(event)"></label></div>'
        + '<div style="text-align:center;font-size:10px;color:#666;margin-bottom:12px;">Logo o foto de perfil del negocio</div>'
        + '<label style="font-size:10px;color:#666;font-weight:700;letter-spacing:.5px;display:block;margin-bottom:6px;">NOMBRE DEL NEGOCIO *</label>'
        + '<input id="biz-reg-name" type="text" placeholder="Ej: ' + (labels[role]||'Mi negocio') + ' Central" style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:12px;border-radius:10px;font-size:14px;font-weight:600;outline:none;box-sizing:border-box;margin-bottom:12px;">'
        + '<label style="font-size:10px;color:#666;font-weight:700;letter-spacing:.5px;display:block;margin-bottom:6px;">DESCRIPCIÓN / BIO</label>'
        + '<textarea id="biz-reg-bio" rows="2" placeholder="Contá qué ofrecés..." style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:11px 12px;border-radius:10px;font-size:13px;resize:none;outline:none;box-sizing:border-box;margin-bottom:12px;"></textarea>'
        + '<label style="font-size:10px;color:#666;font-weight:700;letter-spacing:.5px;display:block;margin-bottom:6px;">TELÉFONO / WHATSAPP</label>'
        + '<input id="biz-reg-phone" type="tel" placeholder="Ej: 091 234 567" style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:11px 12px;border-radius:10px;font-size:13px;outline:none;box-sizing:border-box;margin-bottom:12px;">'
        + '<label style="font-size:10px;color:#666;font-weight:700;letter-spacing:.5px;display:block;margin-bottom:6px;">DIRECCIÓN / CIUDAD</label>'
        + '<input id="biz-reg-address" type="text" placeholder="Ej: 18 de Julio 1234, Montevideo" style="width:100%;background:#161616;border:1px solid #252525;color:#fff;padding:11px 12px;border-radius:10px;font-size:13px;outline:none;box-sizing:border-box;margin-bottom:16px;">'
        + '<div style="display:flex;gap:10px;">'
        + '<button onclick="document.getElementById(\'biz-reg-modal\').remove()" style="flex:1;background:rgba(255,255,255,0.06);color:#aaa;border:none;border-radius:12px;padding:13px;font-weight:800;font-size:13px;cursor:pointer;">Cancelar</button>'
        + '<button id="biz-reg-save" onclick="window._doRegisterBiz(\'' + role + '\')" style="flex:2;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:13px;cursor:pointer;">CREAR NEGOCIO</button>'
        + '</div></div>';
    document.body.appendChild(m);
    setTimeout(function(){ try { document.getElementById('biz-reg-name').focus(); } catch(e){} }, 120);
};
// Foto elegida en el registro de negocio (base64 hasta subirla)
window._bizRegPhotoB64 = null;
window._bizRegPickPhoto = function(event){
    var f = event.target.files && event.target.files[0]; if (!f) return;
    var r = new FileReader();
    r.onload = function(e){
        window._bizRegPhotoB64 = e.target.result;
        var prev = document.getElementById('biz-reg-photo-prev');
        // Mismo recorte que usan los avatares de negocio en la app (rostro/logo center 25%)
        if (prev) { prev.style.backgroundImage = "url('" + e.target.result + "')"; prev.style.backgroundSize = 'cover'; prev.style.backgroundPosition = 'center 25%'; prev.innerHTML = ''; prev.style.borderStyle = 'solid'; }
    };
    r.readAsDataURL(f);
};
// Crear el negocio (sin pisar rol base ni otros negocios) y cambiar a su identidad.
window._doRegisterBiz = async function(role){
    var labels = window._BIZ_LABELS;
    var input = document.getElementById('biz-reg-name');
    var nombre = (input && input.value || '').trim();
    if (!nombre) { if (window.showToast) showToast('Poné un nombre para tu ' + (labels[role]||'negocio') + '.', 'warning'); if (input) input.focus(); return; }
    var btn = document.getElementById('biz-reg-save');
    if (btn) { btn.disabled = true; btn.textContent = 'Creando...'; }
    // Evitar duplicar un negocio que YA existe con ese rol+nombre.
    var existing = (window._myBusinesses || []).filter(function(b){
        return b.role === role && (b.name||'').toLowerCase() === nombre.toLowerCase();
    });
    var _newBizId = existing.length ? existing[existing.length-1].id : null;
    if (!_newBizId) {
        try {
            await saveBusinessToSupabase({ email: window.userData.email, name: nombre, role: role, plan: 'estandar' });
        } catch(e) { console.warn('registrar negocio:', e); }
        try {
            await window._loadMyBusinesses();
            var match = (window._myBusinesses || []).filter(function(b){
                return b.role === role && (b.name||'').toLowerCase() === nombre.toLowerCase();
            });
            if (match.length) _newBizId = match[match.length - 1].id;
        } catch(e){}
    }
    // REGISTRO COMPLETO: guardar foto/bio/teléfono/dirección de la identidad nueva
    // en su fila de business_requests (payload) — igual que un registro desde el home.
    try {
        var sbR = window._sb;
        if (sbR && _newBizId) {
            var plR = { bio: ((document.getElementById('biz-reg-bio')||{}).value||'').trim(),
                        phone: ((document.getElementById('biz-reg-phone')||{}).value||'').trim(),
                        whatsapp: ((document.getElementById('biz-reg-phone')||{}).value||'').trim(),
                        address: ((document.getElementById('biz-reg-address')||{}).value||'').trim() };
            var photoR = null;
            if (window._bizRegPhotoB64) {
                try {
                    var blobR = await (await fetch(window._bizRegPhotoB64)).blob();
                    if (window.cloudUpload) { var rr = await window.cloudUpload(new File([blobR],'logo.jpg',{type:'image/jpeg'}), { folder:'canchero/biz_profiles' }); if (rr && rr.url) photoR = rr.url; }
                    if (!photoR) {
                        var fpR = 'biz_profiles/' + window.userData.email + '/logo_' + Date.now() + '.jpg';
                        var upR = await sbR.storage.from('media').upload(fpR, blobR, { upsert:true, contentType:'image/jpeg' });
                        if (!upR.error) photoR = sbR.storage.from('media').getPublicUrl(fpR).data.publicUrl;
                    }
                    if (!photoR) photoR = window._bizRegPhotoB64;
                } catch(e){ photoR = window._bizRegPhotoB64; }
            }
            if (photoR) plR.photo = photoR;
            var rowR = await sbR.from('business_requests').select('payload').eq('id', _newBizId).maybeSingle();
            var plOld = (rowR && rowR.data && rowR.data.payload) || {};
            try { if (typeof plOld === 'string') plOld = JSON.parse(plOld); } catch(e){ plOld = {}; }
            Object.keys(plR).forEach(function(k){ if (plR[k]) plOld[k] = plR[k]; });
            var updR = { payload: plOld };
            if (photoR) updR.photo = photoR;
            var rUp = await sbR.from('business_requests').update(updR).eq('id', _newBizId);
            if (rUp.error) await sbR.from('business_requests').update({ payload: plOld }).eq('id', _newBizId);
            // Refrescar cache en memoria para que la identidad nueva ya tenga su branding
            var mbR = (window._myBusinesses||[]).filter(function(b){ return String(b.id)===String(_newBizId); })[0];
            if (mbR) { if (photoR) mbR.photo = photoR; mbR.bio = plR.bio || mbR.bio; mbR.phone = plR.phone||mbR.phone; mbR.whatsapp = plR.whatsapp||mbR.whatsapp; mbR.address = plR.address||mbR.address; }
        }
    } catch(e){ console.warn('registro completo negocio:', e); }
    window._bizRegPhotoB64 = null;
    var mo = document.getElementById('biz-reg-modal'); if (mo) mo.remove();
    if (window.showToast) showToast('¡' + (labels[role]||'Negocio') + ' creada! Ya podés gestionarla.', 'success');
    if (window._switchToProfile) window._switchToProfile(_newBizId ? ('biz:'+_newBizId) : 'negocio');
};
// ── ELIMINAR IDENTIDAD (con confirmación) ────────────────────────────────────
window._deleteIdentity = function(key){
    var u = window.userData || {};
    var kind, title, sub, bizObj = null;
    var teamId = null;
    if (String(key).indexOf('biz:') === 0 || key === 'negocio') {
        var id = (key === 'negocio') ? (window._activeBizId && window._activeBizId()) : key.slice(4);
        bizObj = (window._myBusinesses || []).filter(function(b){ return String(b.id) === String(id); })[0] || null;
        kind = 'biz';
        title = 'Eliminar ' + (bizObj ? bizObj.name : 'este negocio');
        sub = 'Se eliminará esta identidad de negocio y su registro. No se puede deshacer. (Los posts ya publicados no se borran solos.)';
    } else if (String(key).indexOf('team:') === 0) {
        teamId = key.slice(5);
        var _tm = (window._myTeamsCache || []).filter(function(x){ return String(x.id) === String(teamId); })[0];
        kind = 'team';
        title = 'Eliminar ' + (_tm ? (_tm.name||'este club') : 'este club');
        sub = 'Se eliminará el club y dejarás de publicar como él. No se puede deshacer. (Solo el dueño puede eliminarlo.)';
    } else if (key === 'fanatico') {
        kind = 'fanatico'; title = 'Eliminar tu perfil de Fanático';
        sub = 'Se eliminará tu identidad de fanático (foto, alias, bio y equipos favoritos). No se puede deshacer.';
    } else if (key === 'jugador') {
        kind = 'jugador'; title = 'Identidad de Jugador';
        sub = 'La identidad de Jugador es la BASE de tu cuenta y no se puede eliminar (si no, la cuenta quedaría sin acceso). Si querés, podés dejar de usarla cambiando a otra identidad.';
    } else return;
    var ex = document.getElementById('id-del-modal'); if (ex) ex.remove();
    var m = document.createElement('div');
    m.id = 'id-del-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:23000;background:rgba(0,0,0,0.75);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    m.onclick = function(e){ if (e.target === m) m.remove(); };
    var canDelete = (kind !== 'jugador');
    m.innerHTML = '<div style="width:100%;max-width:360px;background:#0d0d0d;border:1px solid #2a1414;border-radius:20px;padding:22px 18px;box-shadow:0 20px 60px rgba(0,0,0,0.7);">'
        + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;"><i class="bx bx-error-circle" style="font-size:24px;color:' + (canDelete ? '#ff4d4d' : 'var(--accent)') + ';"></i>'
        + '<div style="font-size:16px;font-weight:900;color:#fff;">' + title + '</div></div>'
        + '<p style="font-size:12px;color:#999;margin:4px 0 14px;line-height:1.5;">' + sub + '</p>'
        + (canDelete ? ('<label style="display:flex;align-items:center;gap:8px;background:rgba(255,77,77,0.06);border:1px solid rgba(255,77,77,0.2);border-radius:12px;padding:10px 12px;margin-bottom:14px;cursor:pointer;font-size:12px;color:#ddd;">'
            + '<input type="checkbox" id="id-del-posts" style="width:16px;height:16px;accent-color:#ff4d4d;flex-shrink:0;">'
            + 'Eliminar también TODO lo publicado por esta identidad (incluye lo fijado)</label>') : '')
        + '<div style="display:flex;gap:10px;">'
        + '<button onclick="document.getElementById(\'id-del-modal\').remove()" style="flex:1;background:rgba(255,255,255,0.06);color:#ccc;border:none;border-radius:12px;padding:13px;font-weight:800;font-size:13px;cursor:pointer;">' + (canDelete ? 'Cancelar' : 'Entendido') + '</button>'
        + (canDelete ? ('<button id="id-del-go" onclick="window._doDeleteIdentity(\'' + kind + '\',\'' + (bizObj ? bizObj.id : (teamId || '')) + '\')" style="flex:1;background:#ff4d4d;color:#fff;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:13px;cursor:pointer;">Eliminar</button>') : '')
        + '</div></div>';
    document.body.appendChild(m);
};
window._doDeleteIdentity = async function(kind, bizId){
    var sb = window._sb; var u = window.userData || {};
    var btn = document.getElementById('id-del-go'); if (btn) { btn.disabled = true; btn.textContent = 'Eliminando...'; }
    var okMsg = 'Identidad eliminada.';
    // ¿Borrar también TODO lo publicado por esta identidad? (incluye fijados)
    var _wipePosts = !!(document.getElementById('id-del-posts') && document.getElementById('id-del-posts').checked);
    async function _deleteIdentityPosts(){
        if (!_wipePosts || !sb || !u.email) return;
        try {
            if (kind === 'biz') {
                var b0 = (window._myBusinesses || []).filter(function(x){ return String(x.id) === String(bizId); })[0];
                // Posts sellados con este negocio + legacy de su rol sin business_id
                await sb.from('posts').delete().eq('user_email', u.email).eq('business_id', String(bizId));
                if (b0 && b0.role) await sb.from('posts').delete().eq('user_email', u.email).eq('user_role', b0.role).is('business_id', null);
            } else if (kind === 'fanatico') {
                await sb.from('posts').delete().eq('user_email', u.email).eq('user_role', 'fanatico');
            } else if (kind === 'team') {
                var _tm0 = (window._myTeamsCache || []).filter(function(x){ return String(x.id) === String(bizId); })[0];
                if (_tm0 && _tm0.name) await sb.from('posts').delete().eq('user_email', u.email).eq('user_role', 'club').eq('user_name', _tm0.name);
                else await sb.from('posts').delete().eq('user_email', u.email).eq('user_role', 'club');
            }
            okMsg = 'Identidad y publicaciones eliminadas.';
        } catch(e){ console.warn('wipe posts', e); }
    }
    await _deleteIdentityPosts();
    try {
        if (kind === 'biz') {
            var b = (window._myBusinesses || []).filter(function(x){ return String(x.id) === String(bizId); })[0];
            if (b && sb) {
                // Borrar TODAS las filas de ese negocio (rol+nombre) — limpia también duplicados.
                var r = await sb.from('business_requests').delete().eq('email', u.email).eq('role', b.role).eq('name', b.name).select('id');
                if (r && r.error) { if (window.showToast) showToast('No se pudo eliminar (permisos DB): ' + r.error.message, 'error'); if (btn){btn.disabled=false;btn.textContent='Eliminar';} return; }
                // RLS puede "borrar" 0 filas sin error — verificar que realmente se fue.
                if (r && r.data && r.data.length === 0) { if (window.showToast) showToast('No se pudo eliminar: la base rechazó el borrado (RLS). Avisá al admin.', 'error'); if (btn){btn.disabled=false;btn.textContent='Eliminar';} return; }
                okMsg = (b.name || 'Negocio') + ' eliminado.';
            }
            await window._loadMyBusinesses();
            // Si estaba activo, volver a Jugador.
            var actId = window._activeBizId && window._activeBizId();
            if (String(actId) === String(bizId) || (window._myBusinesses||[]).length === 0) {
                localStorage.setItem('canchero_active_profile', 'jugador');
            }
        } else if (kind === 'team') {
            if (sb && bizId) {
                var rt = await sb.from('clubs').delete().eq('id', bizId).eq('owner_email', u.email).select('id');
                var _delOk = rt && !rt.error && rt.data && rt.data.length > 0;
                if (!_delOk) {
                    // Fallback: algunos clubes guardan al dueño en captain_email.
                    var rt2 = await sb.from('clubs').delete().eq('id', bizId).eq('captain_email', u.email).select('id');
                    var _delOk2 = rt2 && !rt2.error && rt2.data && rt2.data.length > 0;
                    if (!_delOk2) { if (window.showToast) showToast('No se pudo eliminar el club: ' + ((rt2&&rt2.error&&rt2.error.message) || (rt&&rt.error&&rt.error.message) || 'la base rechazó el borrado (RLS).'), 'error'); if (btn){btn.disabled=false;btn.textContent='Eliminar';} return; }
                }
                okMsg = 'Club eliminado.';
            }
            // Limpiar cache local de equipos.
            try { window._myTeamsCache = (window._myTeamsCache||[]).filter(function(x){ return String(x.id) !== String(bizId); }); } catch(e){}
            try { var mc = JSON.parse(localStorage.getItem('canchero_mis_clubes')||'[]'); localStorage.setItem('canchero_mis_clubes', JSON.stringify(mc.filter(function(x){ return String(x.id)!==String(bizId); }))); } catch(e){}
            if (window._loadMyTeams) { try { await window._loadMyTeams(); } catch(e){} }
            // Si estaba actuando como ese equipo, volver a Jugador.
            var _apT = localStorage.getItem('canchero_active_profile');
            var _actClub = (window.userData && window.userData._activeClubId);
            if (_apT === 'team' && String(_actClub) === String(bizId)) {
                localStorage.setItem('canchero_active_profile', 'jugador');
                localStorage.removeItem('canchero_active_team');
                if (window.userData) { window.userData._activeClubId = null; window.userData._postAsClub = false; }
            }
        } else if (kind === 'fanatico') {
            var lp = {}; try { lp = typeof u.linked_profiles === 'string' ? JSON.parse(u.linked_profiles) : (u.linked_profiles || {}); } catch(e){ lp = {}; }
            delete lp.fanatico;
            u.linked_profiles = lp;
            try { localStorage.setItem('canchero_user', JSON.stringify(u)); } catch(e){}
            if (sb) { var rf = await sb.from('users').update({ linked_profiles: lp }).eq('email', u.email); if (rf && rf.error) console.warn('del fanatico:', rf.error.message); }
            if ((window._activeProfileType && window._activeProfileType()) === 'fanatico') localStorage.setItem('canchero_active_profile', 'jugador');
            okMsg = 'Perfil de Fanático eliminado.';
        }
    } catch(e){ console.warn('_doDeleteIdentity:', e); }
    var mo = document.getElementById('id-del-modal'); if (mo) mo.remove();
    if (window.showToast) showToast(okMsg, 'success');
    // Re-aplicar identidad activa y refrescar UI.
    try { window._applyActiveProfileOverlay && window._applyActiveProfileOverlay(); } catch(e){}
    try { if (typeof applyUserData === 'function') applyUserData(); } catch(e){}
    try { window._rebuildBottomNav && window._rebuildBottomNav(); } catch(e){}
    try { window._renderProfileSwitcher && window._renderProfileSwitcher(); } catch(e){}
    // Reabrir el switcher actualizado.
    var sheet = document.getElementById('profile-switcher-sheet'); if (sheet) { sheet.remove(); if (window._openProfileSwitcher) window._openProfileSwitcher(); }
};
// Píldora centrada en el header (estilo Instagram)
window._renderProfileSwitcher = function(){
    const nav = document.getElementById('main-nav');
    if (!nav || !window.userData || !window.userData.email) return;
    let pill = document.getElementById('profile-switcher-pill');
    const active = window._activeProfileType();
    let label, icon;
    // NEGOCIO: mostrar el nombre del negocio + su icono (tienda/complejo/etc.)
    const _bizRoles = ['club','complejo','tienda','organizacion','sponsor','profesional'];
    const _uRole = (window._trueRole ? window._trueRole() : (window.userData.role||''));
    const _activeIsBiz = (active === 'negocio' || (active||'').indexOf('biz:') === 0 || _bizRoles.indexOf(active) !== -1);
    if (_activeIsBiz) {
        const _bizIcons = { tienda:'bx-store', club:'bx-cancha', complejo:'bx-cancha', organizacion:'bx-trophy', profesional:'bx-briefcase', sponsor:'bx-dollar-circle' };
        var _ab = window._activeBiz ? window._activeBiz() : null;
        label = (_ab && _ab.name) || window.userData.name || 'Mi Negocio';
        icon = _bizIcons[(_ab && _ab.role) || _uRole] || 'bx-store';
    } else if (active === 'team') {
        let t = null; try { t = JSON.parse(localStorage.getItem('canchero_active_team')||'null'); } catch(e){}
        // Fallback: si se perdió el snapshot, usar el cache de mis equipos
        if ((!t || !t.name) && window._myTeamsCache && window._myTeamsCache.length) {
            const cid = window.userData && window.userData._activeClubId;
            const tc = window._myTeamsCache.find(x => String(x.id) === String(cid)) || window._myTeamsCache[0];
            if (tc) t = { id: tc.id, name: tc.name };
        }
        label = (t && t.name) || 'Equipo'; icon = 'bx-shield';
    } else {
        const profs = window._getProfiles();
        const p = profs[active] || {};
        const meta = window._profileMeta[active] || { label:'Perfil', icon:'bx-user' };
        label = p.name || meta.label; icon = meta.icon;
    }
    if (!pill) {
        pill = document.createElement('button');
        pill.id = 'profile-switcher-pill';
        pill.onclick = window._openProfileSwitcher;
        pill.style.cssText = 'position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:6px;background:rgba(255,255,255,0.06);border:1px solid #2a2a2a;border-radius:22px;padding:6px 12px;cursor:pointer;max-width:200px;z-index:5;';
        // NO tocar nav.style.position: la navbar ya es position:fixed (sirve de contenedor
        // para el pill absoluto). Sobrescribirla a relative la saca del fixed y genera un
        // espacio vacío arriba en todas las secciones.
        nav.appendChild(pill);
    }
    pill.innerHTML = `<i class='bx ${icon}' style="font-size:16px;color:var(--accent);flex-shrink:0;"></i><span style="font-size:13px;font-weight:800;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${label}</span><i class='bx bx-chevron-down' style="font-size:16px;color:#888;flex-shrink:0;"></i>`;
    pill.style.display = 'flex';
};

// Handle OAuth redirect callback
if (_sb) {
    _sb.auth.onAuthStateChange(async (event, session) => {
        // Restore opacity after OAuth callback
        document.body.style.opacity = '1';
        // Link de "restablecer contraseña" → pedir la nueva y guardarla
        if (event === 'PASSWORD_RECOVERY') {
            setTimeout(() => { try { window._showSetNewPassword(); } catch(e) {} }, 300);
            return;
        }
        if (event === 'SIGNED_IN' && session?.user && !userData?.email) {
            // Guard contra doble disparo (Supabase puede emitir SIGNED_IN más de una vez)
            if (window._authInFlight === session.user.email) return;
            window._authInFlight = session.user.email;
            const user = session.user;
            // Check localStorage first (fast path)
            const saved = localStorage.getItem('canchero_user');
            if (saved) {
                try {
                    const u = JSON.parse(saved);
                    if (u.email === user.email && u.role) {
                        userData = u;
                        window.userData = u;
                        applyUserData();
                        window._navAfterLogin(userData.role || 'jugador', userData.email);
                        // Restaurar tab si no fue hecho aún
                        if (!window._tabRestoreDone) {
                            window._tabRestoreDone = true;
                            clearTimeout(window._restoreTabTimer);
                            window._restoreTabTimer = setTimeout(function(){
                                try {
                                    var st = JSON.parse(localStorage.getItem('canchero_last_tab')||'null');
                                    if (st && st.tab && st.tab !== 'perfil' && st.tab !== 'inicio') {
                                        switchDashboardTab(st.dashboard||'jugador', st.tab, null);
                                        if (st.tab==='mensajes' && window.CancheroMessaging) {
                                            window.CancheroMessaging.init();
                                            var lt = JSON.parse(localStorage.getItem('canchero_last_thread')||'null');
                                            if (lt&&lt.type) setTimeout(()=>window.CancheroMessaging.openThread(lt.type,null,lt.partnerEmail,lt.partnerName,lt.groupId,lt.groupName),350);
                                        }
                                    }
                                } catch(e){}
                            }, 350);
                        }
                        return;
                    }
                } catch(e) {}
            }
            // Admin check
            if (user.email === 'neurovidstudioia@gmail.com') {
                userData = { name: 'SUPER ADMIN', email: user.email, role: 'admin' };
                localStorage.setItem('canchero_user', JSON.stringify(userData));
                applyUserData();
                navigate('admin');
                return;
            }
            // Check users table first (con _sbAdmin para bypassar RLS)
            const sbq = _sb;
            const emailLc = (user.email||'').toLowerCase();
            try {
                // Buscar por email exacto Y lowercase. Usar limit(1) (NO maybeSingle:
                // maybeSingle lanza error si hay filas duplicadas y haría fallar la detección)
                let prof = null;
                // Búsqueda case-insensitive (ilike) — cubre mayúsculas/variantes del email guardado
                const rEx = await sbq.from('users').select('*').ilike('email', emailLc).limit(1);
                prof = (rEx.data && rEx.data[0]) || null;
                // Reintento por si la sesión/token no estaba listo en el primer query
                if (!prof) {
                    await new Promise(r => setTimeout(r, 700));
                    const rRetry = await sbq.from('users').select('*').ilike('email', emailLc).limit(1);
                    prof = (rRetry.data && rRetry.data[0]) || null;
                }
                const profile = prof;
                // Si existe CUALQUIER fila (aunque le falte role), es un usuario existente:
                // cargar sus datos y NO mostrar el modal de completar perfil
                if (profile && !profile.role) profile.role = 'jugador';
                if (profile && profile.role) {
                    userData = {
                        name: profile.name || user.user_metadata?.full_name || user.email.split('@')[0],
                        email: user.email,
                        photo: profile.photo || profile.avatar_url || user.user_metadata?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(user.email)}&background=000&color=baff00`,
                        role: profile.role,
                        stats: profile.stats || { goals: 0, assists: 0, matches: 0, mvp: 0, rating: 50 },
                        points: profile.points || 0,
                        dept: profile.dept || '',
                        phone: profile.phone || '',
                        clubs: profile.clubs || [],
                        photoStyle: profile.photo_style || undefined,
                        photo_style: profile.photo_style || undefined,
                        nickname: profile.nickname || undefined,
                        nat: profile.nat || profile.nationality || undefined,
                        bio: profile.bio || undefined,
                        pos: profile.pos || profile.position || undefined,
                        city: profile.city || undefined,
                        age: profile.age || undefined,
                        createdAt: profile.created_at || Date.now(),
                        sub_status: profile.sub_status || undefined,
                        sub_paid_until: profile.sub_paid_until || undefined
                    };
                    window.userData = userData;
                    localStorage.setItem('canchero_user', JSON.stringify(userData));
                    applyUserData();
                    window._navAfterLogin(userData.role, userData.email);
                    return;
                }
            } catch(e) {}
            // Check legacy profiles table
            try {
                const rP = await sbq.from('profiles').select('*').eq('email', user.email).limit(1);
                const profile = (rP.data && rP.data[0]) || null;
                if (profile && profile.role) {
                    userData = {
                        name: profile.name || user.user_metadata?.full_name || user.email.split('@')[0],
                        email: user.email,
                        photo: profile.photo || user.user_metadata?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(user.email)}&background=000&color=baff00`,
                        role: profile.role,
                        stats: profile.stats || { goals: 0, assists: 0, matches: 0, mvp: 0, rating: 50 },
                        points: profile.points || 0,
                        dept: profile.dept || '',
                        phone: profile.phone || '',
                        clubs: profile.clubs || [],
                        photoStyle: profile.photo_style || undefined,
                        photo_style: profile.photo_style || undefined,
                        nickname: profile.nickname || undefined,
                        nat: profile.nat || profile.nationality || undefined,
                        bio: profile.bio || undefined,
                        pos: profile.pos || profile.position || undefined,
                        city: profile.city || undefined,
                        age: profile.age || undefined,
                        createdAt: profile.created_at || Date.now(),
                        sub_status: profile.sub_status || undefined,
                        sub_paid_until: profile.sub_paid_until || undefined
                    };
                    window.userData = userData;
                    localStorage.setItem('canchero_user', JSON.stringify(userData));
                    applyUserData();
                    window._navAfterLogin(userData.role, userData.email);
                    return;
                }
            } catch(e) {}
            // Truly new Google user — show role selection
            showGoogleRoleModal(user);
        }
    });
}

let googleAuthUser = null;
let googleSelectedRole = 'jugador';

async function showGoogleRoleModal(user) {
    googleAuthUser = user;
    // ÚLTIMA verificación defensiva: si ya existe un perfil en CUALQUIER tabla,
    // cargarlo y NO mostrar el modal (evita sobreescribir datos existentes).
    try {
        const sbCheck = window._sb;
        const emailLc = (user.email||'').toLowerCase();
        // Si hay un perfil guardado en este dispositivo para este email, usarlo (no pedir registro)
        try {
            const saved = JSON.parse(localStorage.getItem('canchero_user')||'null');
            if (saved && saved.email && saved.email.toLowerCase() === emailLc && saved.role) {
                userData = saved; applyUserData(); navigate(saved.role); return;
            }
        } catch(e){}
        if (sbCheck) {
            for (const tbl of ['users','profiles']) {
                try {
                    let rr = await sbCheck.from(tbl).select('*').ilike('email', emailLc).limit(1);
                    let p = (rr.data && rr.data[0]) || null;
                    if (!p && emailLc !== user.email) {
                        const rr2 = await sbCheck.from(tbl).select('*').ilike('email', user.email).limit(1);
                        p = (rr2.data && rr2.data[0]) || null;
                    }
                    if (p) {
                        // Usuario existente — cargar sus datos completos
                        userData = {
                            name: p.name || user.user_metadata?.full_name || user.email.split('@')[0],
                            email: user.email,
                            photo: p.photo || p.avatar_url || user.user_metadata?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(user.email)}&background=000&color=baff00`,
                            role: p.role || 'jugador',
                            stats: p.stats || { goals: 0, assists: 0, matches: 0, mvp: 0, rating: 50 },
                            points: p.points || 0,
                            dept: p.dept || '', phone: p.phone || '', clubs: p.clubs || [],
                            photoStyle: p.photo_style || undefined, photo_style: p.photo_style || undefined,
                            nickname: p.nickname || undefined, nat: p.nat || p.nationality || undefined,
                            bio: p.bio || undefined, pos: p.pos || p.position || undefined,
                            city: p.city || undefined, age: p.age || undefined,
                            createdAt: p.created_at || Date.now()
                        };
                        localStorage.setItem('canchero_user', JSON.stringify(userData));
                        applyUserData();
                        navigate(userData.role);
                        return;
                    }
                } catch(e) {}
            }
        }
    } catch(e) {}
    // Usuario REALMENTE nuevo con Google → completar TODO el perfil en el onboarding
    // (registro obligatorio: rol, nombre, foto, portada, etc.). Antes se mostraba un modal
    // mínimo que solo pedía el rol; ahora se rellena todo, como pidió el usuario.
    window.userData = window.userData || {};
    window.userData.email = user.email;
    window.userData.name = user.user_metadata?.full_name || (user.email || '').split('@')[0] || '';
    try { navigate('register'); } catch(e){}
    setTimeout(function(){
        try {
            var n = document.getElementById('reg-name'); if (n && !n.value) n.value = window.userData.name || '';
            var re = document.getElementById('reg-email'); if (re) re.value = user.email;
            var gh = document.getElementById('reg-google-hint'); if (gh) gh.textContent = 'Conectado como ' + user.email + ' — completá tu perfil para terminar.';
            var gb = document.getElementById('reg-google-btn'); if (gb) gb.style.display = 'none';
        } catch(e){}
    }, 180);
}

