window.confirmGoogleCompleteProfile = async function() {
    const name = document.getElementById('gcp-name')?.value?.trim();
    const phone = document.getElementById('gcp-phone')?.value?.trim();
    const dept = document.getElementById('gcp-dept')?.value;
    const pos = document.getElementById('gcp-pos')?.value;
    if (name) userData.name = name;
    if (phone) userData.phone = phone;
    if (dept) userData.dept = dept;
    if (pos) userData.pos = pos;
    localStorage.setItem('canchero_user', JSON.stringify(userData));
    document.getElementById('google-complete-profile-modal').style.display = 'none';
    // Guardar perfil en users table — MERGE no destructivo:
    // leer fila existente y solo completar campos vacíos (nunca borrar datos)
    if (userData.email) {
        const sba = window._sb;
        if (sba) {
            try {
                const { data: existing } = await sba.from('users').select('*').eq('email', userData.email.toLowerCase()).maybeSingle();
                const merged = {
                    email: userData.email.toLowerCase(),
                    // Preferir lo existente; solo usar lo nuevo si lo existente está vacío
                    name: (existing?.name) || userData.name,
                    role: (existing?.role) || userData.role || 'jugador',
                    phone: phone || existing?.phone || null,
                    dept: dept || existing?.dept || null,
                    pos: pos || existing?.pos || existing?.position || null
                };
                // No pisar campos que ya tienen valor en la DB
                if (existing) {
                    if (existing.name) merged.name = existing.name;
                    if (existing.phone && !phone) merged.phone = existing.phone;
                    if (existing.dept && !dept) merged.dept = existing.dept;
                    if ((existing.pos || existing.position) && !pos) merged.pos = existing.pos || existing.position;
                }
                await sba.from('users').upsert(merged, { onConflict: 'email' });
            } catch(e) {
                // Fallback mínimo si la lectura falla
                await sba.from('users').upsert({ email: userData.email.toLowerCase(), name: userData.name, role: userData.role || 'jugador' }, { onConflict: 'email' }).catch(()=>{});
            }
        }
    }
    applyUserData();
    navigate('jugador');
};

