// HELPER — save to Supabase
// ============================================================
async function saveBusinessToSupabase(data) {
    if (!_sb) return;
    // 2026-07 — Negocios GRATIS: quedan APROBADOS/activos automáticamente (sin código).
    try {
        await _sb.from('business_requests').insert([{
            email: data.email,
            name: data.name,
            role: data.role,
            plan: data.plan,
            sub_type: data.subType || null,
            status: 'APROBADO',
            created_at: new Date().toISOString(),
            payload: data
        }]);
    } catch(e) { console.warn('Supabase save error:', e); }
    // MULTI-IDENTIDAD: por defecto NO pisar el rol base (un jugador puede tener negocios
    // sin dejar de ser jugador). Solo cuando la CUENTA se crea como negocio (alta desde
    // el landing) se fija users.role = rol del negocio (data.setBaseRole).
    try {
        var _up = { email: (data.email||'').toLowerCase(), sub_status: 'active' };
        if (data.setBaseRole) { _up.role = data.role; _up.name = data.name; }
        await _sb.from('users').upsert(_up, { onConflict: 'email' });
    } catch(e) { console.warn('users biz upsert:', e); }
    // Aviso por email al admin (Resend, server-side)
    try {
        fetch('/api/notify-admin', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name: data.name, email: data.email, role: data.role, plan: data.plan, sub_type: data.subType || null, phone: data.phone || null })
        }).catch(() => {});
    } catch(e) {}
}

function timeAgo(ms) {
    const s = Math.floor((Date.now() - ms) / 1000);
    if (s < 60) return 'Hace un momento';
    const m = Math.floor(s / 60);
    if (m < 60) return 'Hace ' + m + 'm';
    const h = Math.floor(m / 60);
    if (h < 24) return 'Hace ' + h + 'h';
    const d = Math.floor(h / 24);
    return 'Hace ' + d + 'd';
}

