// Image compression helper function
function compressImage(base64Str, maxWidth, maxHeight, quality, callback) {
    if (!base64Str) {
        callback(base64Str);
        return;
    }
    const img = new Image();
    img.src = base64Str;
    img.onload = function() {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        
        if (width > height) {
            if (width > maxWidth) {
                height = Math.round((height * maxWidth) / width);
                width = maxWidth;
            }
        } else {
            if (height > maxHeight) {
                width = Math.round((width * maxHeight) / height);
                height = maxHeight;
            }
        }
        
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        
        const compressedBase64 = canvas.toDataURL('image/jpeg', quality);
        callback(compressedBase64);
    };
    img.onerror = function() {
        callback(base64Str);
    };
}

// Comprime un File de imagen a un Blob JPEG (reduce egress de Supabase ~10x).
// Imágenes -> max 1280px, calidad 0.72. Videos/no-imágenes se devuelven tal cual.
window._compressImageFile = function(file, maxDim, quality) {
    maxDim = maxDim || 1280; quality = quality || 0.72;
    return new Promise(function(resolve){
        try {
            if (!file || !file.type || !file.type.startsWith('image/') || file.type === 'image/gif') { resolve(file); return; }
            const reader = new FileReader();
            reader.onload = function(e){
                const img = new Image();
                img.onload = function(){
                    let w = img.width, h = img.height;
                    if (w > maxDim || h > maxDim) { if (w >= h) { h = Math.round(h * maxDim / w); w = maxDim; } else { w = Math.round(w * maxDim / h); h = maxDim; } }
                    const canvas = document.createElement('canvas'); canvas.width = w; canvas.height = h;
                    canvas.getContext('2d').drawImage(img, 0, 0, w, h);
                    canvas.toBlob(function(blob){
                        // Si por algún motivo la compresión no ayuda, usar el original
                        if (blob && blob.size < file.size) resolve(blob); else resolve(file);
                    }, 'image/jpeg', quality);
                };
                img.onerror = function(){ resolve(file); };
                img.src = e.target.result;
            };
            reader.onerror = function(){ resolve(file); };
            reader.readAsDataURL(file);
        } catch(err){ resolve(file); }
    });
};

