window._wlSetPlatform = function(p){
    window._wlPlatform = p;
    ['ios','android'].forEach(x=>{ const b=document.getElementById('wl-'+x); if(b){ const on=x===p; b.style.background=on?'var(--accent)':'#1a1a1a'; b.style.color=on?'#000':'#aaa'; b.style.border='1px solid '+(on?'var(--accent)':'#2a2a2a'); }});
    window._wlRenderSteps();
};
window._wlRenderSteps = function(){
    const box = document.getElementById('wl-steps'); if(!box) return;
    const step = (n,icon,txt) => `<div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:12px;">
        <div style="width:26px;height:26px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${n}</div>
        <div style="flex:1;font-size:13px;color:#ddd;line-height:1.5;padding-top:2px;">${txt} <i class='bx ${icon}' style="color:var(--accent);vertical-align:middle;font-size:18px;"></i></div>
    </div>`;
    if (window._wlPlatform === 'desktop'){
        // PC / Mac: si el navegador dio el prompt nativo, es UN clic.
        const canOneClick = !!(window._deferredInstall);
        box.innerHTML = (canOneClick
            ? `<button onclick="window.cancheroInstall()" style="width:100%;background:linear-gradient(135deg,#baff00,#8fd400);color:#000;border:none;border-radius:14px;padding:16px;font-weight:900;font-size:15px;cursor:pointer;margin-bottom:12px;letter-spacing:.4px;"><i class='bx bx-download'></i> INSTALAR EN MI ESCRITORIO (1 clic)</button>`
            : '') +
            step(1,'bx-window','En <b>Chrome o Edge</b>, mirá la barra de direcciones: hay un icono de <b>instalar</b> (un monitor con flecha) a la derecha.') +
            step(2,'bx-download','Tocalo y confirmá <b>"Instalar"</b>. En Mac con Safari: menú <b>Archivo → Agregar al Dock</b>.') +
            step(3,'bx-check','¡Listo! Canchero queda como una app en tu escritorio.');
        return;
    }
    if (window._wlPlatform === 'ios'){
        box.innerHTML =
            step(1,'bx-export','Abrí Canchero en <b>Safari</b> y tocá el botón <b>Compartir</b> (el cuadrito con la flecha hacia arriba), abajo en el centro.') +
            step(2,'bx-plus-square','Deslizá hacia abajo y tocá <b>"Agregar a inicio"</b>.') +
            step(3,'bx-check','Tocá <b>"Agregar"</b> arriba a la derecha. ¡Listo, queda en tu pantalla!');
    } else {
        box.innerHTML =
            step(1,'bx-dots-vertical-rounded','Abrí Canchero en <b>Chrome</b> y tocá el menú <b>⋮</b> (arriba a la derecha).') +
            step(2,'bx-mobile-alt','Tocá <b>"Instalar app"</b> o <b>"Agregar a pantalla de inicio"</b>.') +
            step(3,'bx-check','Confirmá <b>"Instalar"</b>. ¡Listo, queda como una app!');
    }
};

window._joinWaitlist = async function() {
    const email = (document.getElementById('wl-email')?.value || '').trim();
    const name = (document.getElementById('wl-name')?.value || '').trim();
    if (!email || email.indexOf('@') < 0) { if (typeof showToast==='function') showToast('Poné un email válido.', 'error'); return; }
    const sb = window._sb;
    try {
        if (sb) {
            await sb.from('waitlist').upsert({ email: email, name: name || null, platform: window._wlPlatform || 'web', created_at: new Date().toISOString() }, { onConflict: 'email' });
        }
        const form = document.getElementById('waitlist-form');
        if (form) form.innerHTML = '<div style="text-align:center;padding:18px 6px;"><i class="bx bx-check-circle" style="font-size:46px;color:var(--accent);"></i><div style="font-size:15px;font-weight:800;margin-top:8px;">¡Listo! Te avisamos cuando salga.</div></div>';
        if (typeof showToast==='function') showToast('Anotado a la lista de espera ✓', 'success');
    } catch(e) { if (typeof showToast==='function') showToast('No se pudo anotar. Probá de nuevo.', 'error'); }
};

