// Hero CTA — smart entry: si ya hay sesión activa entra directo, sino muestra login
window.heroEntrar = async function(tipo) {
    // 1. Sesión en memoria
    if (window.userData && window.userData.email) {
        const dest = window.userData.role || 'jugador';
        navigate(dest);
        return;
    }

    // 2. Intentar restaurar sesión de Supabase
    const sb = _sb || window._sb;
    if (sb) {
        try {
            const { data: { session } } = await sb.auth.getSession();
            if (session?.user?.email) {
                // Hay sesión activa — buscar en tabla users
                const { data: u } = await sb.from('users').select('*').eq('email', session.user.email).single();
                if (u && u.role) {
                    window.userData = u;
                    try { localStorage.setItem('canchero_user', JSON.stringify(u)); } catch(e) {}
                    if (typeof applyUserData === 'function') applyUserData();
                    navigate(u.role);
                    return;
                }
            }
        } catch(e) {}
    }

    // 3. Sesión en localStorage
    try {
        const saved = localStorage.getItem('canchero_user');
        if (saved) {
            const u = JSON.parse(saved);
            if (u && u.email && u.role) {
                window.userData = u;
                if (typeof applyUserData === 'function') applyUserData();
                navigate(u.role);
                return;
            }
        }
    } catch(e) {}

    // 4. No hay sesión — mostrar modal de login según tipo
    if (tipo === 'negocio') {
        openNegocioModal();
    } else {
        _showLoginModal();
    }
};

