window._validateAccessCode = async function(role) {
    var input = document.getElementById('access-code-input');
    var errEl = document.getElementById('access-code-error');
    if (!input) return;
    var code = input.value.trim().toUpperCase();
    if (!code) { errEl.textContent = 'Ingresá un código.'; errEl.style.display = 'block'; return; }

    var sb = window._sb;
    var valid = false;

    // Sistema REAL: el código que genera el admin vive en business_requests.approval_code
    // y se canjea con la RPC redeem_business_code. Probar esto PRIMERO.
    try {
        if (sb) {
            var rr = await sb.rpc('redeem_business_code', { p_code: code });
            if (!rr.error && rr.data === 'ok') { valid = true; }
            else if (!rr.error && rr.data === 'login') {
                errEl.textContent = 'Iniciá sesión primero (email y contraseña) y volvé a ingresar el código.';
                errEl.style.display = 'block'; return;
            }
        }
    } catch(e) {}

    // Fallback legacy: tabla access_codes (códigos viejos)
    try {
        if (!valid && sb) {
            var { data } = await sb.from('access_codes').select('*').eq('code', code).eq('used', false).maybeSingle();
            if (data && new Date(data.expires_at) > new Date()) {
                valid = true;
                // Marcar como usado
                await sb.from('access_codes').update({ used: true, used_by: (window.userData?.email || 'unknown'), used_at: new Date().toISOString() }).eq('code', code);
            }
        }
    } catch(e) {}

    // Fallback: verificar en localStorage
    if (!valid) {
        var codes = JSON.parse(localStorage.getItem('canchero_access_codes') || '[]');
        var match = codes.find(function(c) { return c.code === code && !c.used && new Date(c.expires_at) > new Date(); });
        if (match) {
            valid = true;
            match.used = true;
            match.used_by = (window.userData?.email || 'unknown');
            localStorage.setItem('canchero_access_codes', JSON.stringify(codes));
        }
    }

    if (valid) {
        // Guardar código activo y fecha de expiración
        localStorage.setItem('canchero_biz_access', JSON.stringify({ code: code, role: role, validUntil: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 1).toISOString() }));
        document.getElementById('access-code-modal')?.remove();
        if (typeof showToast === 'function') showToast('Código válido. Bienvenido!', 'success');
        window.location.href = 'crm.html?role=' + role;
    } else {
        errEl.textContent = 'Código inválido, expirado o ya usado. Pedí uno nuevo por WhatsApp.';
        errEl.style.display = 'block';
        input.style.borderColor = '#ff4444';
    }
};

// Verificar acceso de negocio al cargar CRM (llamar desde crm.html)
window._checkBizAccess = function() {
    var access = JSON.parse(localStorage.getItem('canchero_biz_access') || 'null');
    if (!access) return false;
    if (new Date(access.validUntil) < new Date()) {
        localStorage.removeItem('canchero_biz_access');
        return false;
    }
    return true;
};

