window.renderDashboardHome = function() {
    if (!userData) return;

    // Verificar si hay un tab guardado distinto de perfil
    let savedTabId = null;
    try { const st = JSON.parse(localStorage.getItem('canchero_last_tab') || 'null'); savedTabId = st?.tab; } catch(e) {}

    if (!savedTabId || savedTabId === 'perfil' || savedTabId === 'inicio') {
        // Por defecto abrir en INICIO (feed), NO en el perfil (antes el negocio y el
        // jugador arrancaban mostrando el perfil). Consistente con "cambiar de rol abre
        // en inicio" (A6).
        document.querySelectorAll('#view-jugador .dashboard-tab-content').forEach(t => { t.style.display='none'; t.classList.remove('active'); });
        const feedTab = document.getElementById('jugador-feed');
        if (feedTab) { feedTab.style.display='block'; feedTab.classList.add('active'); }
        const pt0 = document.getElementById('jugador-perfil');
        if (pt0) { pt0.style.display='none'; pt0.classList.remove('active'); }
        try { if (window.loadMainFeed) loadMainFeed(); } catch(e){}
    } else {
        // Hay tab guardado diferente de perfil → aplicar inmediatamente para evitar flash
        document.querySelectorAll('#view-jugador .dashboard-tab-content').forEach(t => { t.style.display='none'; t.classList.remove('active'); });
        // Intentar mostrar el tab guardado ahora mismo (sin esperar el timer de 150ms)
        try {
            const savedTabData = JSON.parse(localStorage.getItem('canchero_last_tab') || 'null');
            if (savedTabData && savedTabData.tab) {
                const targetTab = document.getElementById(`jugador-${savedTabData.tab}`);
                if (targetTab) { targetTab.style.display = 'block'; targetTab.classList.add('active'); }
            }
        } catch(e) {}
    }

    const placeholders = document.querySelectorAll('.user-name-placeholder');
    placeholders.forEach(p => p.innerText = userData.name.split(' ')[0].toUpperCase());
    
    // Stats
    const ptsEl = document.getElementById('dash-user-points');
    const lvlEl = document.getElementById('dash-user-level');
    const ratEl = document.getElementById('dash-user-rating');
    
    if (ptsEl) ptsEl.innerText = userData.points || 0;
    if (lvlEl) lvlEl.innerText = userData.level || 'Amateur';
    if (ratEl) ratEl.innerText = userData.stats?.rating || 50;
    
    // Checklist logic
    const checkPhoto = document.getElementById('check-photo');
    const checkClub = document.getElementById('check-club');
    const checkAvail = document.getElementById('check-avail');
    const checkPremium = document.getElementById('check-premium');
    
    if (userData.photo && !userData.photo.includes('ui-avatars')) {
        checkPhoto?.classList.add('done');
        checkPhoto.innerHTML = `<i class='bx bx-check-circle'></i> Foto de perfil subida`;
    }
    
    if (userData.clubs && userData.clubs.length > 0) {
        checkClub?.classList.add('done');
        checkClub.innerHTML = `<i class='bx bx-check-circle'></i> Equipo creado`;
    }
    
    if (userData.isAvailable) {
        checkAvail?.classList.add('done');
        checkAvail.innerHTML = `<i class='bx bx-check-circle'></i> Disponibilidad activada`;
    }
    
    if (userData.points >= 500) {
        checkPremium?.classList.add('done');
        checkPremium.innerHTML = `<i class='bx bx-check-circle'></i> Carta 3D desbloqueada`;
    }
}

