// Toggle engranaje de perfil
window.toggleProfileGear = function(event) {
    if (event) event.stopPropagation();
    var dd = document.getElementById('profile-gear-dropdown');
    if (!dd) return;
    var isOpen = dd.style.display === 'block';
    dd.style.display = isOpen ? 'none' : 'block';
    if (!isOpen) {
        var close = function(e) {
            if (!dd.contains(e.target) && e.target !== document.getElementById('profile-gear-btn')) {
                dd.style.display = 'none';
                document.removeEventListener('click', close);
            }
        };
        setTimeout(function(){ document.addEventListener('click', close); }, 80);
    }
};

// Expandir/colapsar sub-menú de Buscar en hamburguesa
window.toggleHamburgerSearch = function() {
    const sub = document.getElementById('hamburger-search-sub');
    const chevron = document.getElementById('hamburger-search-chevron');
    if (!sub) return;
    const open = sub.style.display !== 'none' && sub.style.display !== '';
    sub.style.display = open ? 'none' : 'block';
    if (chevron) chevron.style.transform = open ? 'rotate(0deg)' : 'rotate(180deg)';
};

// COMPARTIR APP — funcional con Web Share API + fallback
window.shareApp = function() {
    const user = userData;
    const refCode = user ? (user.email || '').replace(/[^a-z0-9]/gi, '').slice(0, 10) : 'canchero';
    const shareUrl = `https://canchero-app.vercel.app?ref=${refCode}`;
    const shareText = `⚽ ¡Unite a Canchero, la app de fútbol amateur!\nEncontrá canchas, partidos y jugadores cerca tuyo.\n${shareUrl}`;

    if (navigator.share) {
        navigator.share({
            title: 'Canchero — Fútbol Amateur',
            text: shareText,
            url: shareUrl,
        }).catch(() => fallbackShare(shareText, shareUrl));
    } else {
        fallbackShare(shareText, shareUrl);
    }
};

function fallbackShare(text, url) {
    // Modal con opciones de compartir
    const modal = document.createElement('div');
    modal.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,0.8);';
    modal.innerHTML = `
      <div style="background:#111;border:1px solid #333;border-radius:20px;width:100%;max-width:480px;padding:24px;">
        <div style="width:40px;height:4px;background:#333;border-radius:2px;margin:0 auto 20px;"></div>
        <h3 style="font-family:Outfit,sans-serif;margin-bottom:16px;text-align:center;">📤 Compartir Canchero</h3>
        <div style="background:rgba(186,255,0,0.05);border:1px solid rgba(186,255,0,0.2);border-radius:10px;padding:12px;font-size:12px;color:#aaa;margin-bottom:16px;word-break:break-all;">${url}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;">
          <a href="https://wa.me/?text=${encodeURIComponent(text)}" target="_blank" style="display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;background:#25D366;color:#fff;border-radius:10px;text-decoration:none;font-weight:700;font-size:13px;">
            <i class='bx bxl-whatsapp' style="font-size:18px;"></i> WhatsApp
          </a>
          <button onclick="navigator.clipboard.writeText('${url}').then(()=>showToast('¡Enlace copiado!','success'));this.closest('[style*=fixed]').remove();"
            style="display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;background:rgba(186,255,0,0.15);color:var(--accent);border:1px solid var(--accent);border-radius:10px;cursor:pointer;font-weight:700;font-size:13px;font-family:Outfit,sans-serif;">
            <i class='bx bx-copy' style="font-size:18px;"></i> Copiar enlace
          </button>
        </div>
        <button onclick="this.closest('[style*=fixed]').remove()" style="display:block;width:100%;background:none;border:none;color:#666;cursor:pointer;font-size:13px;">Cancelar</button>
      </div>`;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
    document.body.appendChild(modal);
}

window.switchDashboardTab = function(role, tabId, el) {
    const section = document.getElementById(`view-${role}`);
    if(!section) return;
    // Guardar tab anterior para que closeGlobalViewer pueda volver
    if (tabId !== 'global-viewer') window._prevDashTab = tabId;

    // Cerrar paneles de gestión que puedan estar abiertos
    document.querySelectorAll('.gestion-sub-content').forEach(d => d.style.display = 'none');
    // Cerrar overlays de match dashboard
    var mdbOv = document.getElementById('match-dashboard-overlay');
    if (mdbOv) mdbOv.remove();
    // Salir del juego al cambiar de sección
    try { if (typeof closeGamePlayer === 'function') closeGamePlayer(); } catch(e){}
    try { if (typeof closeGamesModal === 'function') closeGamesModal(); } catch(e){}
    // Salir del directo (viewer) al cambiar de sección — no cortar si estás transmitiendo
    try {
        var lvm = document.getElementById('live-viewer-modal');
        if (lvm && lvm.style.display !== 'none' && window.CancheroLive && CancheroLive.closeViewer) CancheroLive.closeViewer();
    } catch(e){}
    // Cerrar modal de torneos al cambiar de sección (la rueda navega, no hace falta la X)
    try { if (typeof closeTorneosModal === 'function') closeTorneosModal(); } catch(e){}
    // Cerrar modal de jugadores disponibles y chicana al cambiar de sección
    try { var _dispM = document.getElementById('buscar-disp-modal'); if (_dispM) _dispM.remove(); } catch(e){}
    try { var _dispM2 = document.getElementById('disponibles-modal'); if (_dispM2) _dispM2.style.display = 'none'; } catch(e){}
    try { var _dispM3 = document.getElementById('clubes-buscan-modal'); if (_dispM3) _dispM3.style.display = 'none'; } catch(e){}
    try { var _chicM = document.getElementById('chicana-modal'); if (_chicM) _chicM.remove(); } catch(e){}
    try { var _predC = document.getElementById('pred-challenge-modal'); if (_predC) _predC.remove(); } catch(e){}
    // Cerrar modal flotante de perfil ajeno al cambiar de sección
    try { var _vupOv = document.getElementById('vup-modal-overlay'); if (_vupOv) _vupOv.remove(); } catch(e){}
    try { var _vupMo = document.getElementById('vup-more-modal'); if (_vupMo) _vupMo.remove(); } catch(e){}
    // Cerrar sheets flotantes (partidos / crear) al cambiar de sección
    try { var ps = document.getElementById('partidos-sheet'); if (ps) ps.remove(); } catch(e){}
    try { var cs = document.getElementById('crear-sheet-modal'); if (cs) cs.remove(); } catch(e){}

    // Hide all tabs
    section.querySelectorAll('.dashboard-tab-content').forEach(tab => {
        tab.style.display = 'none';
    });

    // Show target tab — forzar también que la SECCIÓN padre esté visible
    section.style.display = '';
    const target = document.getElementById(`${role}-${tabId}`);
    if(target) {
        target.style.display = 'block';
        // Fallback de fondo para evitar negro absoluto si el render falla
        if (!target.innerHTML || !target.innerHTML.trim()) {
            target.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#666;"><i class="bx bx-loader-alt bx-spin" style="font-size:32px;display:block;margin-bottom:10px;opacity:0.6;"></i><div style="font-size:13px;">Cargando sección...</div></div>';
        }
    }

    // If el is not passed, find the item whose onclick contains tabId
    if (!el) {
        const sidebar = section.querySelector('.sidebar-menu');
        if (sidebar) {
            const items = Array.from(sidebar.querySelectorAll('.menu-item'));
            el = items.find(item => item.getAttribute('onclick')?.includes(`'${tabId}'`));
        }
    }

    // Sync active state for sidebar menu items
    section.querySelectorAll('.sidebar-menu .menu-item').forEach(item => {
        item.classList.remove('active');
    });
    // SIEMPRE guardar el tab actual — independiente de si el elemento es del sidebar o del nav móvil
    let _savedMenuIndex = -1;
    if (el) {
        el.classList.add('active');
        const sidebar = el.closest('.sidebar-menu');
        if (sidebar) {
            const items = Array.from(sidebar.querySelectorAll('.menu-item'));
            _savedMenuIndex = items.indexOf(el);
        }
    }
    localStorage.setItem('canchero_last_tab', JSON.stringify({dashboard: role, tab: tabId, menuIndex: _savedMenuIndex}));

    // Sync active state for bottom nav items
    document.querySelectorAll('.mobile-nav-item').forEach(item => {
        item.classList.remove('active');
        if (item.onclick && item.onclick.toString().includes(tabId)) {
            item.classList.add('active');
        }
    });

    // Sincronizar la ruleta/barra inferior con la sección real (fix: la barra
    // marcaba una sección distinta a la visible)
    try {
        var _r2map = { 'partidos':'partidos', 'mis-partidos':'partidos', 'crear-partido':'partidos', 'buscar-partidos':'partidos',
            'buscar':'buscar', 'buscar-clubes':'buscar', 'buscar-canchas':'buscar', 'complejos':'buscar', 'tiendas':'buscar', 'profesionales':'buscar', 'organizaciones':'buscar',
            'feed':'feed', 'amigos':'feed', 'mensajes':'mensajes', 'perfil':'perfil',
            // Movidas dentro de Buscar → resaltan "Buscar" en la barra fija
            'mis-clubes':'buscar', 'ranking':'buscar', 'juegos':'buscar', 'en-vivo':'buscar' };
        if (_r2map[tabId] && window._ruleta2SyncById) window._ruleta2SyncById(_r2map[tabId]);
    } catch(e) {}

    if (tabId === 'inicio') renderDashboardHome();
    if (tabId === 'crear-partido') { setTimeout(function(){ initCrearPartidoMap(); _loadMyClubs(); }, 200); }
    // Inyectar spinner visible ANTES de la función de carga (evita pantalla negra si la función falla o tarda)
    var _spin = '<div style="text-align:center;padding:60px 20px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:32px;display:block;margin-bottom:10px;opacity:0.6;"></i><div style="font-size:13px;">Cargando...</div></div>';
    var _spinTargets = { 'buscar-clubes': ['street-city-list','street-club-list'], 'buscar-canchas': ['canchas-cards-list'], 'buscar-partidos': ['partidos-list'], 'ranking': ['ranking-body'] };
    if (_spinTargets[tabId]) { _spinTargets[tabId].forEach(function(sid){ var el = document.getElementById(sid); if (el) el.innerHTML = _spin; }); }

    if (tabId === 'ranking') { try { renderRanking(); } catch(e) { var rb=document.getElementById('ranking-body'); if(rb) rb.innerHTML='<tr><td colspan="4" style="text-align:center;padding:30px;color:#f44;font-size:12px;">Error al cargar. <button onclick="renderRanking()" style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:5px 12px;cursor:pointer;font-weight:700;margin-top:8px;">Reintentar</button></td></tr>'; } }
    if (tabId === 'buscar-clubes') { try { renderBuscarClubes(); } catch(e) { var cl=document.getElementById('street-city-list'); if(cl) cl.innerHTML='<div style="padding:20px;color:#f44;font-size:12px;">Error. <button onclick="renderBuscarClubes()" style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:5px 12px;cursor:pointer;font-weight:700;">Reintentar</button></div>'; } }
    if (tabId === 'amigos') populateSocialFeed();
    if (tabId === 'mis-clubes') renderMisClubes();
    if (tabId === 'buscar-canchas') { try { loadCanchasFromSupabase(); } catch(e) { var cg=document.getElementById('canchas-cards-list'); if(cg) cg.innerHTML='<div style="padding:30px;text-align:center;color:#f44;font-size:12px;">Error. <button onclick="loadCanchasFromSupabase()" style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:5px 12px;cursor:pointer;font-weight:700;">Reintentar</button></div>'; } }
    if (tabId === 'buscar-partidos') { try { if(typeof renderBuscarPartidos==='function') renderBuscarPartidos(); } catch(e) { var pl=document.getElementById('partidos-list'); if(pl) pl.innerHTML='<div style="padding:30px;text-align:center;color:#f44;font-size:12px;">Error. <button onclick="renderBuscarPartidos&&renderBuscarPartidos()" style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:5px 12px;cursor:pointer;font-weight:700;">Reintentar</button></div>'; } }
    if (tabId === 'perfil') {
        renderUserPosts(role);
        setTimeout(() => { try { loadProfilePosts(); } catch(e) {} }, 200);
    }
    if (tabId === 'feed') {
        setTimeout(() => {
            const searchBar = document.querySelector('#view-jugador .global-search-container, #view-club .global-search-container');
            const filterBar = document.getElementById('feed-filter-bar');
            if (searchBar && filterBar) filterBar.style.top = searchBar.offsetHeight + 'px';
            initFeedStoriesBar();
            loadMainFeed();
            // Inicializar swipe animado de tabs Publicaciones/Reels
            setTimeout(() => window._initFeedTabSwipe && window._initFeedTabSwipe(), 300);
        }, 80);
    }
    if (tabId === 'mundo-futbol') { loadMatchCenter(); }
    if (tabId === 'en-vivo') {
        // En Vivo fue reemplazado por la sección Mundial
        if (window.CancheroMundial && CancheroMundial.render) { try { CancheroMundial.render(); } catch(e){} }
    }
    if (tabId === 'mensajes') { setTimeout(function(){ if (window.CancheroMessaging) window.CancheroMessaging.init(); }, 50); }
    if (tabId === 'complejos')     { loadSectionTab('complejos'); }
    if (tabId === 'tiendas')       { loadSectionTab('tiendas'); }
    if (tabId === 'profesionales') { loadSectionTab('profesionales'); }
    if (tabId === 'organizaciones'){ loadSectionTab('organizaciones'); }

    // ── Barra de búsqueda global: oculta en todas las secciones ──
    // (el feed queda limpio; buscar vive en la sección BUSCAR)
    document.querySelectorAll('.global-search-container').forEach(gsc => {
        gsc.style.display = 'none';
        gsc.classList.remove('mobile-visible');
    });

    if (tabId === 'recomendar') {
        const premiumBox = document.getElementById('premium-status-box');
        const isPremium = checkPremiumStatus();
        if (isPremium) {
            if (premiumBox) premiumBox.style.display = 'block';
            const expDate = new Date(userData.premiumUntil);
            const premiumTimer = document.getElementById('premium-timer');
            if (premiumTimer) premiumTimer.innerText = `Expira: ${expDate.toLocaleDateString()} ${expDate.toLocaleTimeString()}`;
        } else {
            if (premiumBox) premiumBox.style.display = 'none';
        }
    }
    if (tabId === 'reservas' && role === 'club') {
        const badge = document.getElementById('res-notif-badge');
        if (badge) badge.style.display = 'none';
        if (typeof renderComplexReservations === 'function') renderComplexReservations();
    }
    if (tabId === 'canchas' && role === 'club') {
        if (typeof renderComplexCourts === 'function') renderComplexCourts();
    }
    
    // Notification logic
    if (typeof checkNewNotifications === 'function') checkNewNotifications();
}

