async function generateRankingHTML() {
    const sb = window._sb;
    if (!sb) return emptyDirectoryHTML('bx-bar-chart-alt-2', 'RANKING', 'Sin conexión.');
    try {
        const { data } = await sb.from('users').select('email,name,photo,stats,city').not('stats', 'is', null).limit(50);
        if (!data || data.length === 0) return emptyDirectoryHTML('bx-bar-chart-alt-2', 'RANKING', 'Sin datos de ranking aún.');
        const sorted = data.filter(u => u.stats && u.stats.rating).sort((a,b) => (b.stats.rating||0) - (a.stats.rating||0));
        return `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;"><button class="btn-back-icon" aria-label="Volver" onclick="switchDashboardTab((window.userData&&window.userData.role)||'jugador','buscar')"><i class='bx bx-left-arrow-alt'></i></button><i class='bx bx-trophy' style="font-size:22px;color:var(--accent);"></i><div><div style="font-size:15px;font-weight:900;">Ranking Global</div><div style="font-size:10px;color:#555;">Los mejores jugadores de Canchero</div></div></div>
        <div style="display:flex;flex-direction:column;gap:0;">${sorted.map((u,i) => {
            const emailEsc = (u.email||'').replace(/'/g,"\\'");
            const medalStyle = ['#FFD700','#C0C0C0','#CD7F32'][i] || '#333';
            const pos = u.position || (u.stats && u.stats.position) || '';
            const city = u.city || '';
            const photoStyle = u.photo && !u.photo.includes('ui-avatars') ? `background-image:url('${u.photo}');background-size:cover;background-position:center;` : `background:var(--accent);`;
            return `<div onclick="window.viewUserProfile('${emailEsc}')" style="display:flex;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid #151515;cursor:pointer;transition:background .15s;" onmouseover="this.style.background='#111'" onmouseout="this.style.background='transparent'">
                <div style="width:28px;text-align:center;font-size:14px;font-weight:900;color:${medalStyle};">${i<3?['🥇','🥈','🥉'][i]:i+1}</div>
                ${window.userAvatar ? window.userAvatar(u,40) : `<div style="width:40px;height:40px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:16px;color:#000;${photoStyle}">${u.photo&&!u.photo.includes('ui-avatars')?'':(u.name||'?')[0].toUpperCase()}</div>`}
                <div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;">${u.name||'Jugador'}</div><div style="font-size:10px;color:#555;">${[pos,city].filter(Boolean).join(' · ')}</div></div>
                <div style="font-size:18px;font-weight:900;color:var(--accent);">${u.stats.rating}</div>
            </div>`;
        }).join('')}</div>`;
    } catch(e) { return emptyDirectoryHTML('bx-bar-chart-alt-2', 'ERROR', e.message); }
}

