async function generateOrganizacionesHTML(query) {
    const sb = window._sb;
    const q = query || '';
    const fc = (document.getElementById('dir-filter-country')||{}).value || '';
    const fci = (document.getElementById('dir-filter-city')||{}).value || '';
    const header = `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;"><button class="btn-back-icon" aria-label="Volver" onclick="switchDashboardTab((window.userData&&window.userData.role)||'jugador','buscar')"><i class='bx bx-left-arrow-alt'></i></button><i class='bx bx-buildings' style="font-size:22px;color:var(--accent);"></i><div><div style="font-size:15px;font-weight:900;">Organizaciones</div><div style="font-size:10px;color:#555;">Ligas, escuelas y organizadores de eventos</div></div></div>`;
    const searchBar = _dirSearchBar('organizaciones', q, { country: fc, city: fci, showLoc: true });
    if (!sb) return header + searchBar + emptyDirectoryHTML('bx-buildings', 'SIN CONEXIÓN', '') + '</div>';
    try {
        let dbq = sb.from('users').select('email,name,photo,city,nat,bio,role').eq('role', 'organizacion').limit(60);
        if (q) dbq = dbq.or(`name.ilike.%${q}%,city.ilike.%${q}%`);
        if (fc) dbq = dbq.ilike('nat', fc);
        if (fci) dbq = dbq.ilike('city', `%${fci}%`);
        let { data } = await dbq;
        data = data || [];
        // Multi-identidad: las organizaciones creadas desde el switcher viven en
        // business_requests (users.role del email suele ser 'jugador') → sin este
        // bloque el directorio salía siempre vacío.
        try {
            let bq = sb.from('business_requests').select('id,email,name,role,payload').in('role', ['organizacion','liga','escuela']).limit(120);
            if (q) bq = bq.ilike('name', `%${q}%`);
            const { data: brs } = await bq;
            if (brs && brs.length) {
                const have = new Set(data.map(u => (u.email||'').toLowerCase()));
                brs.forEach(b => {
                    const em = (b.email||'').toLowerCase();
                    if (!em || have.has(em)) return;
                    let pl = b.payload || {}; try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
                    const cty = pl.city || '';
                    if (fci && cty.toLowerCase().indexOf(fci.toLowerCase()) === -1) return;
                    data.push({ email: b.email, name: b.name, photo: pl.photo || pl.logo || '', city: cty, nat: pl.country || '', bio: pl.bio || '', role: b.role, _bizId: String(b.id) });
                });
            }
        } catch(e){ console.warn('dir organizaciones biz:', e); }
        if (!data || data.length === 0) return header + searchBar + emptyDirectoryHTML('bx-buildings', 'SIN ORGANIZACIONES', 'Todavía no hay organizaciones registradas con esos filtros.') + '</div>';
        return header + searchBar + `<div style="display:flex;flex-direction:column;gap:0;">${data.map(o => {
            const name = (o.name || 'Organización');
            const init = (name[0]||'O').toUpperCase();
            const loc = [o.city, o.nat].filter(Boolean).join(', ') || 'Uruguay';
            const emailSafe = (o.email||'').replace(/'/g,"\\'");
            const hasPhoto = o.photo && !o.photo.includes('ui-avatars');
            const openCall = o._bizId ? `window.viewUserProfile('${emailSafe}', true, { bizId: '${o._bizId}' })` : `window.viewUserProfile('${emailSafe}')`;
            return `<div onclick="${openCall}" style="display:flex;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid #151515;cursor:pointer;transition:background .15s;" onmouseover="this.style.background='#111'" onmouseout="this.style.background='transparent'">
                <div style="width:46px;height:46px;border-radius:12px;background:${hasPhoto?`#000 center/cover url('${o.photo}')`:'rgba(186,255,0,0.12)'};border:1px solid #2a2a2a;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-weight:900;color:var(--accent);">${hasPhoto?'':init}</div>
                <div style="flex:1;min-width:0;"><div style="font-size:14px;font-weight:700;">${name}</div><div style="font-size:11px;color:#555;">${loc}${o.bio?' · '+o.bio.slice(0,40):''}</div></div>
                <i class='bx bx-chevron-right' style="color:#333;font-size:18px;"></i>
            </div>`;
        }).join('')}</div></div>`;
    } catch(e) { return header + searchBar + emptyDirectoryHTML('bx-buildings', 'ERROR', e.message) + '</div>'; }
}

function _dirSearchBar(type, query, filters) {
    const f = filters || {};
    const positions = ['DC','MC','DEF','POR','EXT','MED','DEL','LI','LD','MCI','MCO','EI','ED'];
    const countries = (window.getOrderedCountries ? window.getOrderedCountries() : (window.COUNTRIES||[]).map(c=>c.name));
    // Ciudades según país seleccionado; si no hay país, mostrar las de Uruguay
    const cities = (window.CITIES_BY_COUNTRY && (window.CITIES_BY_COUNTRY[f.country] || window.CITIES_BY_COUNTRY['Uruguay'])) || [];
    const isJugadores = type === 'jugadores';
    const showLoc = f.showLoc || isJugadores;
    const selStyle = "width:100%;background:#111;color:#aaa;border:1px solid #222;border-radius:12px;padding:5px 6px;font-size:10px;font-weight:700;cursor:pointer;outline:none;text-align:center;height:30px;";
    const nCols = (isJugadores ? 3 : 2);
    // Barra compacta: input fino + filtros chicos. Antes era gruesa y en 2 líneas.
    return `
    <div style="margin-bottom:10px;">
        <div style="display:flex;gap:6px;margin-bottom:${showLoc?'6':'0'}px;align-items:center;">
            <div style="flex:1;position:relative;height:40px;">
                <i class='bx bx-search' style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:#666;font-size:16px;pointer-events:none;z-index:1;"></i>
                <input id="dir-search-input" type="text" placeholder="Buscar..." value="${query||''}" style="width:100%;height:40px;background:rgba(255,255,255,0.04);border:1px solid #222;border-radius:14px;color:#fff;font-size:14px;outline:none;margin:0;padding:0 12px 0 36px;box-sizing:border-box;" onfocus="window._dirSearchFocused=true" onblur="window._dirSearchFocused=false" oninput="clearTimeout(window._dirDebounce);window._dirDebounce=setTimeout(()=>window.reloadDirectory('${type}'),350)" onkeydown="if(event.key==='Enter'){window._dirSearchFocused=true;window.reloadDirectory('${type}');}">
            </div>
        </div>
        ${showLoc ? `<div style="display:grid;grid-template-columns:repeat(${nCols},1fr);gap:6px;">
            ${isJugadores ? `<select id="dir-filter-pos" onchange="window.reloadDirectory('${type}')" style="${selStyle}">
                <option value="">POSICIÓN</option>
                ${positions.map(p=>`<option value="${p}" ${f.pos===p?'selected':''}>${p}</option>`).join('')}
            </select>` : ''}
            <select id="dir-filter-country" onchange="window.reloadDirectory('${type}')" style="${selStyle}">
                <option value="">PAÍS</option>
                ${countries.map(c=>`<option value="${c}" ${f.country===c?'selected':''}>${c}</option>`).join('')}
            </select>
            <select id="dir-filter-city" onchange="window.reloadDirectory('${type}')" style="${selStyle}">
                <option value="">CIUDAD</option>
                ${cities.map(c=>`<option value="${c}" ${f.city===c?'selected':''}>${c}</option>`).join('')}
            </select>
        </div>` : ''}
        ${isJugadores ? `<button id="dir-filter-avail" onclick="window._dirToggleAvail(this)" style="margin-top:6px;width:100%;display:flex;align-items:center;justify-content:center;gap:7px;height:34px;border-radius:12px;border:1px solid ${window._dirOnlyAvailable?'#00e676':'#222'};background:${window._dirOnlyAvailable?'rgba(0,230,118,0.12)':'transparent'};color:${window._dirOnlyAvailable?'#00e676':'#888'};font-size:12px;font-weight:800;cursor:pointer;"><span style="width:8px;height:8px;border-radius:50%;background:${window._dirOnlyAvailable?'#00e676':'#555'};box-shadow:${window._dirOnlyAvailable?'0 0 6px #00e676':'none'};"></span> SOLO DISPONIBLES AHORA</button>` : ''}
    </div><div id="dir-results-container">`;
}

