async function generateJugadoresFeedHTML(query, filters) {
    const sb = window._sb;
    const q = query || '';
    const f = filters || {};
    const header = `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;"><button class="btn-back-icon" aria-label="Volver" onclick="closeGlobalViewer((window.userData&&window.userData.role)||'jugador')"><i class='bx bx-left-arrow-alt'></i></button><i class='bx bx-run' style="font-size:22px;color:var(--accent);"></i><div><div style="font-size:15px;font-weight:900;">Directorio de Jugadores</div><div style="font-size:10px;color:#555;">Jugadores registrados en Canchero</div></div></div>`;
    const searchBar = _dirSearchBar('jugadores', q, f);
    if (!sb) return header + searchBar + emptyDirectoryHTML('bx-run', 'SIN CONEXIÓN', '');
    try {
        // Búsqueda por nombre con ilike; el rol se filtra en memoria (combinar
        // .not + .or daba "sin resultados").
        let dbq = sb.from('users').select('*').limit(80);
        if (q) dbq = dbq.ilike('name', `%${q}%`);
        let { data, error } = await dbq;
        if (error) { console.warn('[Directorio jugadores] error:', error.message); const retry = await sb.from('users').select('*').limit(80); data = retry.data || []; }
        const _excl = ['club','complejo','organizacion','profesional','tienda','sponsor','bot','admin'];
        let players = (data || []).filter(u => !_excl.includes(u.role));
        // Aplicar filtros en memoria (evita problemas de RLS con columnas opcionales)
        if (f && f.pos) players = players.filter(u => (u.pos||u.position||'').toLowerCase().includes(f.pos.toLowerCase()));
        if (f && f.country) players = players.filter(u => (u.country||u.nat||'').toLowerCase().includes(f.country.toLowerCase()));
        if (f && f.city) players = players.filter(u => (u.city||u.department||'').toLowerCase().includes(f.city.toLowerCase()));
        // Merge localStorage data for richer display
        players = players.map(u => {
            try {
                const stored = JSON.parse(localStorage.getItem('canchero_user') || '{}');
                if (stored.email === u.email) return { ...u, ...stored };
            } catch(e) {}
            return u;
        });
        if (players.length === 0) return header + searchBar + emptyDirectoryHTML('bx-run', 'SIN RESULTADOS', 'No se encontraron jugadores.') + '</div>';
        return header + searchBar + `<div style="display:flex;flex-direction:column;gap:0;">${players.map(u => {
            const emailEsc = (u.email||'').replace(/'/g,"\\'");
            const pos = u.pos || u.position || 'Polivalente';
            const city = u.city || u.department || '';
            const photoSrc = (u.photo || u.avatar_url || '');
            const hasPhoto = photoSrc && !photoSrc.includes('ui-avatars') && !photoSrc.includes('undefined');
            const photoStyle = hasPhoto ? `background-image:url('${photoSrc}');background-size:cover;background-position:center 25%;` : `background:var(--accent);`;
            const initial = (u.name||'?')[0].toUpperCase();
            return `<div onclick="window.viewUserProfile('${emailEsc}')" style="display:flex;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid #151515;cursor:pointer;transition:background .15s;" onmouseover="this.style.background='#111'" onmouseout="this.style.background='transparent'">
                ${window.userAvatar ? window.userAvatar(u,44) : `<div style="width:44px;height:44px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:17px;color:#000;${photoStyle}">${hasPhoto ? '' : initial}</div>`}
                <div style="flex:1;min-width:0;">
                    <div style="font-size:14px;font-weight:700;">${u.name||'Jugador'}</div>
                    <div style="font-size:11px;color:var(--accent);font-weight:700;">${pos.toUpperCase()}</div>
                    ${city ? `<div style="font-size:10px;color:#555;">${city}</div>` : ''}
                </div>
                <i class='bx bx-chevron-right' style="color:#333;font-size:18px;"></i>
            </div>`;
        }).join('')}</div></div>`;
    } catch(e) { return header + searchBar + emptyDirectoryHTML('bx-run', 'ERROR', e.message) + '</div>'; }
}

// Directorio de FANÁTICOS (hinchas/creadores) — muestra la identidad de fanático
// (linked_profiles.fanatico), no la de jugador.
async function generateFanaticosFeedHTML(query, filters) {
    const sb = window._sb;
    const q = query || '';
    const f = filters || {};
    const header = `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;"><button class="btn-back-icon" aria-label="Volver" onclick="closeGlobalViewer((window.userData&&window.userData.role)||'jugador')"><i class='bx bx-left-arrow-alt'></i></button><i class='bx bx-football' style="font-size:22px;color:var(--accent);"></i><div><div style="font-size:15px;font-weight:900;">Directorio de Fanáticos</div><div style="font-size:10px;color:#555;">Hinchas y creadores de contenido</div></div></div>`;
    // Barra con filtros de PAÍS y CIUDAD (showLoc:true)
    const searchBar = _dirSearchBar('fanaticos', q, Object.assign({}, f, { showLoc: true }));
    if (!sb) return header + searchBar + emptyDirectoryHTML('bx-football', 'SIN CONEXIÓN', '') + '</div>';
    const list = await _buildFanListHTML(q, f);
    return header + searchBar + list + '</div>';
}
// Solo la lista de resultados de fanáticos (para búsqueda/filtros en vivo)
async function _buildFanListHTML(query, filters) {
    const sb = window._sb; const q = query || ''; const f = filters || {};
    if (!sb) return emptyDirectoryHTML('bx-football', 'SIN CONEXIÓN', '');
    try {
        // Filtrar por identidad de fanático en el SERVIDOR. Antes traía las primeras 300
        // filas de `users` (orden arbitrario) y recién después filtraba en memoria, así que
        // un fanático fuera de esa ventana no aparecía nunca en el directorio.
        const _sel = 'email,name,role,linked_profiles,city,nat';
        let data = null;
        try {
            const r = await sb.from('users').select(_sel)
                .or('role.eq.fanatico,linked_profiles->fanatico.not.is.null').limit(500);
            if (r.error) throw r.error;
            data = r.data;
        } catch(e) {
            // Fallback: si el filtro jsonb no estuviera disponible, traer y filtrar acá.
            const r2 = await sb.from('users').select(_sel).limit(1000);
            data = (r2 && r2.data) || [];
        }
        let fans = (data || []).map(u => {
            let lp = {}; try { lp = typeof u.linked_profiles==='string'?JSON.parse(u.linked_profiles):(u.linked_profiles||{}); } catch(e){}
            const fan = lp.fanatico || (u.role === 'fanatico' ? { name:u.name } : null);
            if (!fan) return null;
            return { email:u.email, name: fan.name || u.name || 'Fanático', photo: fan.photo || '', photoStyle: fan.photoStyle||null, nat: fan.nat||u.nat||u.country||'', city: u.city||u.department||'' };
        }).filter(Boolean);
        const meEmail = (window.userData&&window.userData.email||'').toLowerCase();
        fans = fans.filter(x => (x.email||'').toLowerCase() !== meEmail);
        if (q) fans = fans.filter(x => (x.name||'').toLowerCase().includes(q.toLowerCase()));
        if (f.country) fans = fans.filter(x => (x.nat||'').toLowerCase().includes(f.country.toLowerCase()));
        if (f.city) fans = fans.filter(x => (x.city||'').toLowerCase().includes(f.city.toLowerCase()));
        if (!fans.length) return emptyDirectoryHTML('bx-football', 'SIN RESULTADOS', 'No se encontraron fanáticos.');
        return `<div style="display:flex;flex-direction:column;gap:0;">${fans.map(x => {
            const emailEsc = (x.email||'').replace(/'/g,"\\'");
            const hasPhoto = x.photo && !x.photo.includes('ui-avatars');
            const pos = x.photoStyle ? `background-position:${50+parseInt(x.photoStyle.x||0)}% ${50+parseInt(x.photoStyle.y||0)}%;background-size:${(parseFloat(x.photoStyle.zoom||100)>100)?(x.photoStyle.zoom+'%'):'cover'};` : 'background-position:center 25%;background-size:cover;';
            const av = hasPhoto ? `<div style="width:44px;height:44px;border-radius:50%;flex-shrink:0;border:2px solid rgba(186,255,0,0.4);background-image:url('${x.photo}');${pos}"></div>` : `<div style="width:44px;height:44px;border-radius:50%;flex-shrink:0;background:rgba(186,255,0,0.12);border:2px solid rgba(186,255,0,0.4);display:flex;align-items:center;justify-content:center;color:var(--accent);"><i class='bx bx-football' style="font-size:20px;"></i></div>`;
            const flag = (x.nat && window.countryFlag) ? window.countryFlag(x.nat,13) : '';
            return `<div onclick="window.viewUserProfile('${emailEsc}', true)" style="display:flex;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid #151515;cursor:pointer;" onmouseover="this.style.background='#111'" onmouseout="this.style.background='transparent'">
                ${av}
                <div style="flex:1;min-width:0;">
                    <div style="font-size:14px;font-weight:700;display:flex;align-items:center;gap:5px;">${(x.name||'Fanático')}${flag}</div>
                    <div style="font-size:11px;color:var(--accent);font-weight:700;">FANÁTICO</div>
                    ${x.city||x.nat ? `<div style="font-size:10px;color:#555;">${[x.city,x.nat].filter(Boolean).join(', ')}</div>` : ''}
                </div>
                <i class='bx bx-chevron-right' style="color:#333;font-size:18px;"></i>
            </div>`;
        }).join('')}</div>`;
    } catch(e) { return emptyDirectoryHTML('bx-football', 'ERROR', e.message); }
}
window._abrirBuscarFanaticos = function(){ try { window.openGlobalDirectory('fanaticos'); } catch(e){} };

