const _CHICANAS = [
    'Pedila redonda que cuadrada no te la puedo dar.',
    'No te marco porque me da lástima.',
    'Seguí participando.',
    'Te llevo a upa, gordo.',
    '¿Viniste a jugar o a mirar?',
    'Sacale una foto a la pelota que no la vas a ver más.',
    'No te da ni para alcanzapelotas.',
    'Pará de correr que transpirás al pedo.',
    'Con razón te dejan siempre en el banco.',
    'Hablás como crack y jugás como comentarista.'
];

// Mostrar la chicana recibida con animación al centro
window.showChicanaAnimation = function(msg, fromName) {
    var ex = document.getElementById('chicana-anim-overlay');
    if (ex) ex.remove();
    var ov = document.createElement('div');
    ov.id = 'chicana-anim-overlay';
    ov.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.6);backdrop-filter:blur(4px);animation:chicanaFade 0.25s ease;';
    ov.innerHTML = '<div style="text-align:center;padding:30px;max-width:480px;animation:chicanaPop 0.6s cubic-bezier(.34,1.56,.64,1);">' +
        '<div style="font-size:64px;margin-bottom:10px;filter:drop-shadow(0 0 20px #baff00);">⚡</div>' +
        '<div style="font-size:11px;font-weight:900;color:var(--accent);letter-spacing:3px;margin-bottom:14px;">CHICANA DE ' + ((fromName||'ALGUIEN').toUpperCase()) + '</div>' +
        '<div style="font-size:22px;font-weight:800;color:#fff;line-height:1.3;text-shadow:0 2px 12px rgba(0,0,0,0.8);padding:0 10px;">"' + msg + '"</div>' +
        '<button onclick="document.getElementById(\'chicana-anim-overlay\').remove()" style="margin-top:24px;background:var(--accent);color:#000;border:none;border-radius:25px;padding:10px 30px;font-weight:900;font-size:13px;cursor:pointer;">AGUANTAR</button>' +
        '</div>';
    if (!document.getElementById('chicana-anim-style')) {
        var st = document.createElement('style');
        st.id = 'chicana-anim-style';
        st.textContent = '@keyframes chicanaFade{from{opacity:0}to{opacity:1}}@keyframes chicanaPop{0%{transform:scale(0.3) rotate(-8deg);opacity:0}50%{transform:scale(1.08) rotate(2deg)}100%{transform:scale(1) rotate(0)}}';
        document.head.appendChild(st);
    }
    document.body.appendChild(ov);
    // Vibrar y sonido
    try { if (navigator.vibrate) navigator.vibrate([60, 30, 60, 30, 100]); } catch(e){}
    setTimeout(function(){ var c = document.getElementById('chicana-anim-overlay'); if (c) c.remove(); }, 8000);
};

// DESAFÍO entrante: animación grande al centro de la pantalla (igual que las chicanas)
// msg = texto del desafío, fromName = equipo que desafía, matchId = id del partido para aceptar/rechazar
window.showDesafioAnimation = function(msg, fromName, matchId) {
    var ex = document.getElementById('desafio-anim-overlay');
    if (ex) ex.remove();
    var ov = document.createElement('div');
    ov.id = 'desafio-anim-overlay';
    ov.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.7);backdrop-filter:blur(5px);animation:chicanaFade 0.25s ease;';
    var safeMatch = (matchId || '').toString().replace(/'/g, "\\'");
    ov.innerHTML = '<div style="text-align:center;padding:30px;max-width:480px;animation:chicanaPop 0.6s cubic-bezier(.34,1.56,.64,1);">' +
        '<div style="font-size:64px;margin-bottom:10px;filter:drop-shadow(0 0 20px #baff00);">⚔️</div>' +
        '<div style="font-size:11px;font-weight:900;color:var(--accent);letter-spacing:3px;margin-bottom:14px;">DESAFÍO DE ' + ((fromName||'UN EQUIPO').toUpperCase()) + '</div>' +
        '<div style="font-size:18px;font-weight:800;color:#fff;line-height:1.35;text-shadow:0 2px 12px rgba(0,0,0,0.8);padding:0 10px;white-space:pre-line;">' + (msg||'') + '</div>' +
        (matchId ? '<div style="display:flex;gap:10px;margin-top:24px;justify-content:center;">' +
            '<button onclick="document.getElementById(\'desafio-anim-overlay\').remove();window.responderDesafio&&window.responderDesafio(\'' + safeMatch + '\',true);" style="background:var(--accent);color:#000;border:none;border-radius:25px;padding:11px 26px;font-weight:900;font-size:13px;cursor:pointer;">✅ ACEPTAR</button>' +
            '<button onclick="document.getElementById(\'desafio-anim-overlay\').remove();window.responderDesafio&&window.responderDesafio(\'' + safeMatch + '\',false);" style="background:rgba(255,68,68,0.12);color:#ff5555;border:1px solid rgba(255,68,68,0.35);border-radius:25px;padding:11px 22px;font-weight:800;font-size:13px;cursor:pointer;">RECHAZAR</button>' +
          '</div>' +
          '<button onclick="document.getElementById(\'desafio-anim-overlay\').remove();window.viewMatchDetails&&window.viewMatchDetails(\'' + safeMatch + '\');" style="margin-top:12px;background:transparent;color:#888;border:none;font-size:11px;cursor:pointer;text-decoration:underline;">Ver detalles del partido</button>'
          : '<button onclick="document.getElementById(\'desafio-anim-overlay\').remove()" style="margin-top:24px;background:var(--accent);color:#000;border:none;border-radius:25px;padding:10px 30px;font-weight:900;font-size:13px;cursor:pointer;">ENTENDIDO</button>') +
        '</div>';
    if (!document.getElementById('chicana-anim-style')) {
        var st = document.createElement('style');
        st.id = 'chicana-anim-style';
        st.textContent = '@keyframes chicanaFade{from{opacity:0}to{opacity:1}}@keyframes chicanaPop{0%{transform:scale(0.3) rotate(-8deg);opacity:0}50%{transform:scale(1.08) rotate(2deg)}100%{transform:scale(1) rotate(0)}}';
        document.head.appendChild(st);
    }
    document.body.appendChild(ov);
    try { if (navigator.vibrate) navigator.vibrate([80, 40, 80, 40, 120]); } catch(e){}
    setTimeout(function(){ var c = document.getElementById('desafio-anim-overlay'); if (c) c.remove(); }, 15000);
};

// Picker rápido de chicana desde el chat (inyecta la chicana elegida al input)
window._openChicanaPicker = function() {
    var ex = document.getElementById('chicana-picker-modal'); if (ex) ex.remove();
    var m = document.createElement('div');
    m.id = 'chicana-picker-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:30200;background:rgba(0,0,0,0.85);backdrop-filter:blur(8px);display:flex;align-items:flex-end;justify-content:center;';
    m.innerHTML = '<div style="background:#111;border:1px solid #2a2a2a;border-radius:20px 20px 0 0;width:100%;max-width:480px;padding:20px 20px 32px;max-height:75vh;overflow-y:auto;">' +
        '<div style="text-align:center;margin-bottom:14px;"><span style="font-size:28px;">⚡</span><div style="font-size:14px;font-weight:900;color:#ffb400;letter-spacing:1px;margin-top:4px;">ELEGÍ UNA CHICANA</div></div>' +
        '<div style="display:flex;flex-direction:column;gap:6px;margin-bottom:12px;">' +
        _CHICANAS.map(function(c){ return '<button onclick="window._insertChicanaInChat(this.dataset.txt)" data-txt="' + c.replace(/"/g,'&quot;') + '" style="background:rgba(255,180,0,0.06);border:1px solid rgba(255,180,0,0.25);color:#ffd97a;padding:11px 14px;border-radius:12px;text-align:left;cursor:pointer;font-size:12px;font-weight:600;">' + c + '</button>'; }).join('') +
        '</div>' +
        '<button onclick="document.getElementById(\'chicana-picker-modal\').remove()" style="width:100%;padding:11px;background:transparent;border:1px solid #333;color:#aaa;border-radius:12px;cursor:pointer;font-weight:700;font-size:12px;">CANCELAR</button>' +
        '</div>';
    m.onclick = function(e) { if (e.target === m) m.remove(); };
    document.body.appendChild(m);
};
window._insertChicanaInChat = function(txt) {
    var inp = document.getElementById('msg-input');
    if (inp) { inp.value = (inp.value ? inp.value + ' ' : '') + '⚡ ' + txt; inp.focus(); }
    var pk = document.getElementById('chicana-picker-modal'); if (pk) pk.remove();
};

// Detectar @ en el input del chat para autocompletar nombres del partido/grupo
window._msgCheckMention = async function(inp) {
    var val = inp.value;
    var caret = inp.selectionStart || val.length;
    var before = val.slice(0, caret);
    var match = before.match(/@([A-Za-zÀ-ÿ0-9_]*)$/);
    var existing = document.getElementById('msg-mention-pop');
    if (!match) { if (existing) existing.remove(); return; }
    var q = (match[1] || '').toLowerCase();
    // Buscar candidatos del partido activo o grupo
    var candidates = [];
    try {
        var sb = window._sb;
        var thread = window.CancheroMessaging && window.CancheroMessaging._activeThread;
        if (thread && thread.groupId && sb) {
            var matchId = thread.groupId;
            var pls = await sb.from('match_players').select('player_email,player_name').eq('match_id', matchId).limit(40);
            candidates = (pls.data || []).map(function(p){ return { email: p.player_email, name: p.player_name || p.player_email }; });
        }
    } catch(e) {}
    candidates = candidates.filter(function(c){ return (c.name || '').toLowerCase().includes(q); }).slice(0, 6);
    if (!candidates.length) { if (existing) existing.remove(); return; }
    var pop = existing || document.createElement('div');
    pop.id = 'msg-mention-pop';
    var rect = inp.getBoundingClientRect();
    pop.style.cssText = 'position:fixed;left:' + (rect.left + 8) + 'px;bottom:' + (window.innerHeight - rect.top + 6) + 'px;background:#111;border:1px solid #2a2a2a;border-radius:12px;padding:6px;z-index:25000;box-shadow:0 4px 20px rgba(0,0,0,0.7);min-width:200px;max-width:280px;';
    pop.innerHTML = candidates.map(function(c){ return '<button onclick="window._insertMention(\'' + (c.name || '').replace(/'/g, "\\'") + '\')" style="display:block;width:100%;text-align:left;background:none;border:none;color:#fff;padding:8px 10px;border-radius:8px;cursor:pointer;font-size:12px;" onmouseover="this.style.background=\'rgba(186,255,0,0.1)\'" onmouseout="this.style.background=\'none\'">@' + (c.name || '?') + '</button>'; }).join('');
    if (!existing) document.body.appendChild(pop);
};
window._insertMention = function(name) {
    var inp = document.getElementById('msg-input');
    if (!inp) return;
    inp.value = inp.value.replace(/@([A-Za-zÀ-ÿ0-9_]*)$/, '@' + name + ' ');
    var pop = document.getElementById('msg-mention-pop'); if (pop) pop.remove();
    inp.focus();
};

window.sendChicana = function(toEmail, toName) {
    const existing = document.getElementById('chicana-modal');
    if (existing) existing.remove();
    const m = document.createElement('div');
    m.id = 'chicana-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:30100;background:rgba(0,0,0,0.85);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:16px;';
    m.innerHTML = `
      <div style="background:#111;border:1px solid #2a2a2a;border-radius:20px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto;padding:20px 16px 24px;box-sizing:border-box;">
        <div style="text-align:center;margin-bottom:16px;">
          <span style="font-size:28px;">⚡</span>
          <div style="font-size:14px;font-weight:900;color:var(--accent);letter-spacing:1px;margin-top:4px;">ENVIAR CHICANA</div>
          <div style="font-size:11px;color:#666;margin-top:2px;">A ${toName||toEmail} · ${(()=>{const t=new Date().toISOString().slice(0,10);const k=`chicanas_daily_${window.userData?.email}_${t}`;return 5-(parseInt(localStorage.getItem(k)||'0'));})()}/5 chicanas restantes hoy</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:6px;max-height:260px;overflow-y:auto;margin-bottom:14px;" id="chicana-list">
          ${_CHICANAS.map((c,i) => `<button onclick="window._selectChicana(${i})" data-idx="${i}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid #2a2a2a;color:#ccc;padding:10px 14px;border-radius:12px;text-align:left;cursor:pointer;font-size:12px;transition:all .15s;white-space:normal;word-break:break-word;" onmouseover="this.style.borderColor='var(--accent)';this.style.color='#fff'" onmouseout="if(!this.classList.contains('selected')){this.style.borderColor='#2a2a2a';this.style.color='#ccc'}">${c}</button>`).join('')}
        </div>
        <textarea id="chicana-custom" placeholder="O escribí tu propia chicana..." style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;padding:10px 14px;border-radius:12px;font-size:12px;outline:none;resize:none;box-sizing:border-box;margin-bottom:12px;" rows="2"></textarea>
        <div style="display:flex;gap:10px;box-sizing:border-box;">
          <button onclick="document.getElementById('chicana-modal').remove()" style="flex:1;min-width:0;padding:12px 8px;background:transparent;border:1px solid #333;color:#aaa;border-radius:12px;cursor:pointer;font-weight:700;font-size:12px;box-sizing:border-box;">Cancelar</button>
          <button onclick="window._enviarChicana('${toEmail}','${(toName||'').replace(/'/g,"\\'")}' )" style="flex:2;min-width:0;padding:12px 8px;background:var(--accent);color:#000;border:none;border-radius:12px;cursor:pointer;font-weight:900;font-size:12px;box-sizing:border-box;">⚡ ENVIAR CHICANA</button>
        </div>
      </div>`;
    m.onclick = e => { if(e.target===m) m.remove(); };
    document.body.appendChild(m);
    window._selectedChicana = null;
};

window._selectChicana = function(idx) {
    document.querySelectorAll('#chicana-list button').forEach(b => { b.classList.remove('selected'); b.style.borderColor='#2a2a2a'; b.style.color='#ccc'; b.style.background='rgba(255,255,255,0.04)'; });
    const btn = document.querySelector(`#chicana-list button[data-idx="${idx}"]`);
    if (btn) { btn.classList.add('selected'); btn.style.borderColor='var(--accent)'; btn.style.color='#fff'; btn.style.background='rgba(186,255,0,0.08)'; }
    window._selectedChicana = _CHICANAS[idx];
    document.getElementById('chicana-custom').value = '';
};

window._enviarChicana = async function(toEmail, toName) {
    const custom = (document.getElementById('chicana-custom')?.value||'').trim();
    const msg = custom || window._selectedChicana;
    if (!msg) { if(typeof showToast==='function') showToast('Elegí o escribí una chicana','error'); return; }
    document.getElementById('chicana-modal').remove();
    const myEmail = window.userData?.email;
    const myName = window.userData?.name || 'Jugador';
    // Check 5 chicanas/día total en localStorage
    const today = new Date().toISOString().slice(0,10);
    const dailyKey = `chicanas_daily_${myEmail}_${today}`;
    const DAILY_LIMIT = 5;
    const sentToday = parseInt(localStorage.getItem(dailyKey) || '0');
    if (sentToday >= DAILY_LIMIT) { if(typeof showToast==='function') showToast(`Ya enviaste ${DAILY_LIMIT} chicanas hoy. Mañana podés enviar más.`,'error'); return; }
    // Check 1 chicana por destinatario por día
    const toKey = `chicana_${myEmail}_${toEmail}_${today}`;
    if (localStorage.getItem(toKey)) { if(typeof showToast==='function') showToast('Ya le enviaste una chicana hoy a esta persona.','error'); return; }
    localStorage.setItem(dailyKey, String(sentToday + 1));
    localStorage.setItem(toKey, '1');
    // Guardar en Supabase
    const sb = window._sb;
    if (sb) {
        try { await sb.from('nudges').insert({ sender_email: myEmail, sender_name: myName, recipient_email: toEmail, message: msg }); } catch(e) {}
    }
    // Notificación — usar el sistema oficial (columnas actor_email/actor_name correctas)
    try {
        if (window.CancheroNotif && window.CancheroNotif.create) {
            await window.CancheroNotif.create(toEmail, 'chicana', myName, `⚡ ${myName} te chicaneó: "${msg.slice(0,60)}"`);
        } else if (sb) {
            await sb.from('notifications').insert({ recipient_email: toEmail, type: 'chicana', actor_email: myEmail, actor_name: myName, message: `⚡ ${myName} te chicaneó: "${msg.slice(0,60)}"`, read: false });
        }
    } catch(e) {}
    // Vibrar (solo si hay vibración disponible)
    try { if(navigator.vibrate) navigator.vibrate([200,80,200]); } catch(e) {}
    if(typeof showToast==='function') showToast(`⚡ ¡Chicana enviada a ${toName||toEmail}!`,'success');
};

// ============================================================
// BUSCAR JUGADORES DISPONIBLES (modal centralizado)
// ============================================================
window.openBuscarDisponibles = async function() {
    const existing = document.getElementById('buscar-disp-modal');
    if (existing) existing.remove();
    const m = document.createElement('div');
    m.id = 'buscar-disp-modal';
    // Página completa (no modal): fondo sólido, ocupa toda la pantalla
    m.style.cssText = 'position:fixed;left:0;right:0;bottom:0;top:'+(window._navH?window._navH():0)+'px;z-index:9950;background:#0a0a0a;overflow-y:auto;-webkit-overflow-scrolling:touch;';
    m.innerHTML = `<div style="max-width:600px;margin:0 auto;min-height:100%;padding-bottom:90px;">
        <div style="position:sticky;top:0;z-index:5;background:rgba(10,10,10,0.96);backdrop-filter:blur(10px);border-bottom:1px solid #1a1a1a;padding:calc(10px + env(safe-area-inset-top)) 16px 12px;">
            <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">
                <button onclick="document.getElementById('buscar-disp-modal').remove()" style="background:rgba(255,255,255,0.06);border:1px solid #2a2a2a;border-radius:20px;color:#fff;font-size:13px;font-weight:700;cursor:pointer;padding:7px 13px;display:flex;align-items:center;gap:5px;"><i class='bx bx-arrow-back'></i></button>
                <div style="font-size:15px;font-weight:900;color:#00e676;flex:1;"><i class='bx bx-search-alt'></i> Jugadores disponibles</div>
            </div>
            <input id="disp-search" placeholder="Buscar por nombre o posición..." oninput="window._dispFilter()" style="width:100%;background:#141414;border:1px solid #222;border-radius:22px;color:#fff;font-size:13px;padding:10px 16px;outline:none;box-sizing:border-box;margin-bottom:10px;">
            <div style="display:flex;gap:8px;margin-bottom:8px;">
                <button onclick="window._loadDispModal('ciudad',this)" class="disp-scope active" style="flex:1;padding:8px;border-radius:10px;background:rgba(0,230,118,0.12);border:1px solid rgba(0,230,118,0.3);color:#00e676;font-size:11px;font-weight:700;cursor:pointer;">MI CIUDAD</button>
                <button onclick="window._loadDispModal('pais',this)" class="disp-scope" style="flex:1;padding:8px;border-radius:10px;background:transparent;border:1px solid #333;color:#666;font-size:11px;font-weight:700;cursor:pointer;">MI PAÍS</button>
                <button onclick="window._loadDispModal('mundo',this)" class="disp-scope" style="flex:1;padding:8px;border-radius:10px;background:transparent;border:1px solid #333;color:#666;font-size:11px;font-weight:700;cursor:pointer;">MUNDO</button>
            </div>
            <div style="display:flex;gap:8px;">${window.CancheroGeo ? window.CancheroGeo.selectsHTML('disp') : ''}</div>
        </div>
        <div id="buscar-disp-list" style="padding:8px 16px;"><div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div></div>
    </div>`;
    document.body.appendChild(m);
    if (window.CancheroGeo) window.CancheroGeo.bindSelects(document.getElementById('disp-country'), document.getElementById('disp-city'), ()=>window._dispFilter());
    window._loadDispModal('mundo', m.querySelector('.disp-scope:last-child'));
};

window._dispAll = [];
window._loadDispModal = async function(scope, btn) {
    document.querySelectorAll('.disp-scope').forEach(b => { b.style.background='transparent'; b.style.borderColor='#333'; b.style.color='#666'; });
    if (btn) { btn.style.background='rgba(0,230,118,0.12)'; btn.style.borderColor='rgba(0,230,118,0.3)'; btn.style.color='#00e676'; }
    const container = document.getElementById('buscar-disp-list');
    if (!container) return;
    container.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class=\'bx bx-loader-alt bx-spin\' style="font-size:24px;"></i></div>';
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) { container.innerHTML = '<div style="padding:20px;color:#888;text-align:center;">Iniciá sesión para ver disponibles.</div>'; return; }
    try {
        let q = sb.from('users').select('email,name,photo,city,pos,stats').eq('available', true).neq('email', me.email).limit(120);
        if (scope === 'ciudad' && me.city) q = q.ilike('city', `%${me.city}%`);
        else if (scope === 'pais' && (me.country||me.nat)) q = q.ilike('nat', `%${me.country||me.nat}%`);
        const { data } = await q;
        window._dispAll = data || [];
        window._dispFilter();
    } catch(e) { container.innerHTML = `<div style="padding:20px;color:#f44;text-align:center;">Error: ${e.message}</div>`; }
};

window._dispFilter = function() {
    const container = document.getElementById('buscar-disp-list');
    if (!container) return;
    const qy = (document.getElementById('disp-search')?.value||'').toLowerCase();
    const country = (document.getElementById('disp-country')?.value||'').toLowerCase();
    const city = (document.getElementById('disp-city')?.value||'').toLowerCase();
    let data = (window._dispAll||[]).filter(u => {
        const n = (u.name||u.email||'').toLowerCase(), pos = (u.pos||u.position||'').toLowerCase();
        if (qy && !(n.includes(qy)||pos.includes(qy))) return false;
        if (country && !(u.country||'').toLowerCase().includes(country)) return false;
        if (city && !(u.city||'').toLowerCase().includes(city)) return false;
        return true;
    });
    if (!data.length) { container.innerHTML = '<div style="padding:40px;text-align:center;color:#555;font-size:13px;"><i class=\'bx bx-user-x\' style="font-size:36px;display:block;margin-bottom:8px;opacity:0.4;"></i>Sin jugadores disponibles con ese filtro.</div>'; return; }
    container.innerHTML = data.map(u => {
        const ph = u.photo || u.avatar_url;
        const n = u.name || u.email.split('@')[0];
        const pos = u.pos || u.position || '';
        const hasPhoto = ph && !ph.includes('ui-avatars');
        return `<div onclick="document.getElementById('buscar-disp-modal').remove();window.viewUserProfile&&window.viewUserProfile('${u.email}')" style="display:flex;align-items:center;gap:12px;padding:11px 4px;border-bottom:1px solid #1a1a1a;cursor:pointer;" onmouseover="this.style.background='rgba(255,255,255,0.03)'" onmouseout="this.style.background='transparent'">
            ${hasPhoto?`<img src="${ph}" style="width:44px;height:44px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.outerHTML='<div style=\\'width:44px;height:44px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0;\\'>${n[0].toUpperCase()}</div>'">`:`<div style="width:44px;height:44px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0;">${n[0].toUpperCase()}</div>`}
            <div style="flex:1;min-width:0;"><div style="font-size:14px;font-weight:700;">${n}</div><div style="font-size:11px;color:#666;">${pos?pos+' · ':''}${[u.city,u.country].filter(Boolean).join(', ')}</div></div>
            <span style="background:rgba(0,230,118,0.1);border:1px solid rgba(0,230,118,0.3);color:#00e676;border-radius:20px;padding:3px 10px;font-size:10px;font-weight:700;">DISP.</span>
        </div>`;
    }).join('');
};

// ============================================================
// BUSINESS PROFILES — Marcos SVG + Perfil Completo por Rubro
// ============================================================

// Funciones de marco SVG (retornan contenido interno del SVG 110x110)
function _frameCanchaVerde() { return '<rect x="2" y="2" width="106" height="106" rx="12" fill="none" stroke="#4CAF50" stroke-width="3"/><rect x="6" y="6" width="98" height="98" rx="10" fill="none" stroke="#2E7D32" stroke-width="1.5" stroke-dasharray="4 3"/><line x1="55" y1="2" x2="55" y2="108" stroke="#4CAF50" stroke-width="1" opacity="0.5"/><circle cx="55" cy="55" r="14" fill="none" stroke="#4CAF50" stroke-width="1.5" opacity="0.6"/><rect x="2" y="2" width="106" height="106" rx="12" fill="none" stroke="rgba(186,255,0,0.4)" stroke-width="1.5"/>'; }
function _frameCanchaNoche() { return '<rect x="2" y="2" width="106" height="106" rx="12" fill="none" stroke="#00BCD4" stroke-width="3"/><rect x="6" y="6" width="98" height="98" rx="10" fill="none" stroke="#0097A7" stroke-width="1.5" stroke-dasharray="4 3"/><line x1="55" y1="2" x2="55" y2="108" stroke="#00BCD4" stroke-width="1" opacity="0.5"/><circle cx="55" cy="55" r="14" fill="none" stroke="#00BCD4" stroke-width="1.5" opacity="0.6"/><circle cx="20" cy="8" r="4" fill="#FFD600" opacity="0.8"/><circle cx="90" cy="8" r="4" fill="#FFD600" opacity="0.8"/><circle cx="20" cy="102" r="4" fill="#FFD600" opacity="0.8"/><circle cx="90" cy="102" r="4" fill="#FFD600" opacity="0.8"/>'; }
