function _frameEscudo() { return '<path d="M55 4 L102 22 L102 58 Q102 88 55 108 Q8 88 8 58 L8 22 Z" fill="none" stroke="#baff00" stroke-width="3"/><path d="M55 12 L94 27 L94 58 Q94 82 55 100 Q16 82 16 58 L16 27 Z" fill="none" stroke="rgba(186,255,0,0.3)" stroke-width="1.5"/><line x1="55" y1="4" x2="55" y2="108" stroke="rgba(186,255,0,0.2)" stroke-width="1"/><line x1="8" y1="40" x2="102" y2="40" stroke="rgba(186,255,0,0.2)" stroke-width="1"/>'; }
function _frameCopa() { return '<path d="M55 4 L102 22 L102 58 Q102 88 55 108 Q8 88 8 58 L8 22 Z" fill="none" stroke="#FFD600" stroke-width="3"/><path d="M45 4 Q55 0 65 4 L72 24 L55 20 L38 24 Z" fill="none" stroke="#FFD600" stroke-width="1.5" opacity="0.6"/><circle cx="55" cy="55" r="18" fill="none" stroke="#FFD600" stroke-width="1" opacity="0.4"/>'; }
function _frameProfesional() { return '<rect x="2" y="2" width="106" height="106" rx="12" fill="none" stroke="#9C88FF" stroke-width="3"/><rect x="8" y="8" width="94" height="94" rx="8" fill="none" stroke="#9C88FF" stroke-width="1" opacity="0.4"/><circle cx="20" cy="20" r="4" fill="#9C88FF" opacity="0.6"/><circle cx="90" cy="20" r="4" fill="#9C88FF" opacity="0.6"/><circle cx="20" cy="90" r="4" fill="#9C88FF" opacity="0.6"/><circle cx="90" cy="90" r="4" fill="#9C88FF" opacity="0.6"/>'; }
function _frameDT() { return '<path d="M55 4 L102 22 L102 58 Q102 88 55 108 Q8 88 8 58 L8 22 Z" fill="none" stroke="#4FC3F7" stroke-width="3"/><line x1="55" y1="4" x2="55" y2="108" stroke="rgba(79,195,247,0.3)" stroke-width="1"/><line x1="8" y1="40" x2="102" y2="40" stroke="rgba(79,195,247,0.3)" stroke-width="1"/>'; }
function _frameArbitro() { return '<circle cx="55" cy="55" r="50" fill="none" stroke="#F44336" stroke-width="3"/><circle cx="55" cy="55" r="44" fill="none" stroke="#F44336" stroke-width="1" opacity="0.4"/><path d="M35 40 Q55 35 75 40" fill="none" stroke="#F44336" stroke-width="1.5" opacity="0.6"/><path d="M35 70 Q55 75 75 70" fill="none" stroke="#F44336" stroke-width="1.5" opacity="0.6"/>'; }
function _frameKine() { return '<circle cx="55" cy="55" r="50" fill="none" stroke="#66BB6A" stroke-width="3"/><circle cx="55" cy="55" r="44" fill="none" stroke="#66BB6A" stroke-width="1" opacity="0.4"/><line x1="55" y1="20" x2="55" y2="90" stroke="#66BB6A" stroke-width="2" opacity="0.5"/><line x1="20" y1="55" x2="90" y2="55" stroke="#66BB6A" stroke-width="2" opacity="0.5"/>'; }

window._bizFrameHtml = function(role, subType, photoUrl, frameStyle, initials) {
    // Aceptar tanto URLs http como imágenes base64 (data:) — antes se descartaban los data: y la foto "desaparecía"
    var hasPhoto = photoUrl && !photoUrl.includes('ui-avatars');
    var photoContent = hasPhoto
        ? '<div style="width:100%;height:100%;border-radius:12px;background-image:url(\'' + photoUrl + '\');background-size:cover;background-position:center;"></div>'
        : '<div class="biz-frame-initials" style="border-radius:12px;">' + ((initials||'?')[0].toUpperCase()) + '</div>';
    var frameMap = {
        club: { 'default': _frameCanchaVerde, 'cancha-verde': _frameCanchaVerde, 'cancha-noche': _frameCanchaNoche, 'estadio': _frameEstadio },
        tienda: { 'default': _frameBolsaCompra, 'bolsa': _frameBolsaCompra, 'tienda-deportiva': _frameTiendaDeportiva },
        organizacion: { 'default': _frameEscudo, 'escudo': _frameEscudo, 'copa': _frameCopa },
        profesional: { 'default': _frameProfesional, 'profesional': _frameProfesional, 'dt': _frameDT, 'arbitro': _frameArbitro, 'kine': _frameKine }
    };
    var roleFrames = frameMap[role] || frameMap['organizacion'];
    var fs = frameStyle || 'default';
    // Auto-detect from sub_type
    if (fs === 'default' && role === 'profesional') {
        if (subType && subType.toLowerCase().includes('arbitro')) fs = 'arbitro';
        else if (subType && (subType.toLowerCase().includes('kine') || subType.toLowerCase().includes('nutri'))) fs = 'kine';
        else if (subType && (subType.toLowerCase().includes('dt') || subType.toLowerCase().includes('entrenador'))) fs = 'dt';
    }
    var frameFn = (roleFrames[fs] || roleFrames['default'] || _frameEscudo);
    return '<div class="biz-frame-container"><div style="width:100%;height:100%;border-radius:12px;overflow:hidden;">' + photoContent + '</div><svg class="biz-frame-svg" viewBox="0 0 110 110" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' + frameFn() + '</svg></div>';
};

// ── Render de perfil completo de negocio ─────────────────────
// Guardar la portada del NEGOCIO activo donde el perfil de negocio la LEE:
// business_requests.payload.cover (P1.2 — antes iba a users.cover_photo y no se veía).
window._saveBizCover = async function(url) {
    const sb = window._sb;
    let bizId = window._activeBizId && window._activeBizId();
    // Sin id concreto ('__primary__' / lista sin cargar): resolver la fila REAL del
    // negocio por email+rol — antes caía a users.cover_photo y el perfil de negocio
    // (que lee payload.cover) "no cambiaba".
    if (sb && url && (!bizId || bizId === '__primary__') && window.userData && window.userData.email) {
        try {
            const tr = (window._trueRole && window._trueRole()) || '';
            let q = sb.from('business_requests').select('id,role').eq('email', window.userData.email).order('created_at', { ascending: false });
            const { data: rows } = await q;
            const row = (rows||[]).filter(function(b){ return !tr || (b.role||'').toLowerCase() === tr.toLowerCase(); })[0] || (rows||[])[0];
            if (row) bizId = String(row.id);
        } catch(e){}
    }
    if (!sb || !url || !bizId || bizId === '__primary__') {
        // Cuenta legacy sin fila propia: fallback a users.cover_photo (comportamiento viejo)
        if (sb && url && window.userData && window.userData.email) {
            await sb.from('users').update({ cover_photo: url }).eq('email', window.userData.email);
        }
    } else {
        const { data: row, error: e1 } = await sb.from('business_requests').select('payload').eq('id', bizId).single();
        if (e1) throw e1;
        let pl = (row && row.payload) || {};
        try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
        pl.cover = url;
        const { error: e2 } = await sb.from('business_requests').update({ payload: pl }).eq('id', bizId);
        if (e2) throw e2;
        // Cache en memoria para que el switcher/perfil lo reflejen sin recargar
        (window._myBusinesses||[]).forEach(function(b){ if (String(b.id) === String(bizId)) b.coverPhoto = url; });
    }
    if (window.userData) { window.userData.cover_photo = url; window.userData.coverPhoto = url; }
};
// ── PRODUCTOS/SERVICIOS COMPARTIDOS AL FEED (posts con meta.biz_item) ──────────
// Tarjeta moderna con CTA (Comprar/Reservar/Ver) que lleva al perfil del negocio.
window._bizItemMeta = function(p){
    try {
        let m = p.meta; if (typeof m === 'string') m = JSON.parse(m);
        return (m && m.biz_item) ? m.biz_item : null;
    } catch(e){ return null; }
};
window._bizItemCardHTML = function(p){
    const it = window._bizItemMeta(p);
    if (!it) return '';
    const esc = s => String(s==null?'':s).replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    const kind = (it.kind||'producto').toLowerCase();
    // Torneo: NO es "Reservar" — es "Ver torneo" y abre la página pública del torneo,
    // donde "Gestionar" solo aparece para la organización creadora.
    const cta = it.cta || (kind==='torneo' ? 'VER TORNEO' : (kind==='cancha'||kind==='servicio' ? 'RESERVAR' : 'COMPRAR'));
    const icon = { producto:'bx-shopping-bag', cancha:'bx-map-alt', torneo:'bx-trophy', servicio:'bx-briefcase' }[kind] || 'bx-shopping-bag';
    const price = it.price ? `<div style="font-size:16px;font-weight:900;color:var(--accent);">$${esc(it.price)}</div>` : '';
    const em = (p.user_email||'').replace(/'/g,"\\'");
    const bid = (p.business_id || it.bizId || '').toString().replace(/'/g,'');
    const iid = String(it.id||'').replace(/'/g,'');
    const open = kind==='torneo'
        ? `window.CancheroTournaments&&CancheroTournaments.openPublicView('${iid}')`
        : `window._openBizItemFromPost('${em}','${bid}','${kind}','${iid}')`;
    // Con carrusel (media_urls) las fotos se muestran en el carrusel estándar del feed
    const hasCarousel = !!p.media_urls;
    return `<div onclick="${open}" style="cursor:pointer;border:1px solid rgba(186,255,0,0.25);border-radius:14px;overflow:hidden;margin-bottom:12px;background:linear-gradient(160deg,#101510,#0b0b0b);">
        ${(!hasCarousel && it.photo) ? `<img src="${esc(it.photo)}" style="width:100%;max-height:280px;object-fit:cover;display:block;" onerror="this.style.display='none'">` : ''}
        <div style="display:flex;align-items:center;gap:12px;padding:12px 14px;">
          <div style="width:40px;height:40px;border-radius:12px;background:rgba(186,255,0,0.12);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class='bx ${icon}' style="font-size:20px;color:var(--accent);"></i></div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:10px;font-weight:800;letter-spacing:1px;color:#888;text-transform:uppercase;">${esc(it.kindLabel || kind)}</div>
            <div style="font-size:15px;font-weight:900;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(it.name||'')}</div>
            ${it.detail ? `<div style="font-size:11px;color:#999;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(it.detail)}</div>` : ''}
          </div>
          <div style="text-align:right;flex-shrink:0;">
            ${price}
            <button onclick="event.stopPropagation();${open}" style="margin-top:4px;background:var(--accent);color:#000;border:none;border-radius:20px;padding:8px 16px;font-weight:900;font-size:11px;letter-spacing:.5px;cursor:pointer;">${esc(cta)}</button>
          </div>
        </div>
      </div>`;
};
// ── COMPARTIR FUERA DE LA APP (WhatsApp / IG / X / Facebook / etc.) ───────────
// Genera un link que abre Canchero DIRECTO en lo compartido (post, perfil,
// partido, comunidad, producto) + hoja de compartir atractiva con marca.
window.cancheroShareUrl = function(type, id){
    const base = 'https://canchero-app.vercel.app/';
    if (type === 'post' || type === 'reel' || type === 'producto') return base + '?post=' + encodeURIComponent(id);
    if (type === 'perfil')    return base + '?perfil=' + encodeURIComponent(id);
    if (type === 'partido')   return base + '?invite=' + encodeURIComponent(id);
    if (type === 'comunidad') return base + '?comunidad=' + encodeURIComponent(id);
    return base;
};
window.cancheroShare = function(o){
    o = o || {};
    const url = o.url || window.cancheroShareUrl(o.type || 'post', o.id || '');
    const title = o.title || 'Canchero — la app del fútbol uruguayo';
    const text = (o.text ? o.text + '\n\n' : '') + 'Miralo en Canchero:';
    // Nativo (móvil): hoja del sistema con TODAS las apps (WhatsApp, IG, TikTok, X...)
    if (navigator.share) { navigator.share({ title, text, url }).catch(function(){}); return; }
    // Fallback (PC): hoja propia
    let s = document.getElementById('canchero-share-sheet'); if (s) s.remove();
    s = document.createElement('div');
    s.id = 'canchero-share-sheet';
    s.style.cssText = 'position:fixed;inset:0;z-index:100500;background:rgba(0,0,0,0.75);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:20px;';
    const enc = encodeURIComponent(text + ' ' + url);
    const encU = encodeURIComponent(url);
    const btn = (icon, label, href, color) => `<a href="${href}" target="_blank" rel="noopener" style="display:flex;flex-direction:column;align-items:center;gap:6px;text-decoration:none;color:#ddd;font-size:10px;font-weight:700;"><span style="width:52px;height:52px;border-radius:16px;background:${color};display:flex;align-items:center;justify-content:center;"><i class='bx ${icon}' style="font-size:26px;color:#fff;"></i></span>${label}</a>`;
    s.innerHTML = `<div style="background:#0f110f;border:1px solid #1e1e1e;border-radius:20px;width:100%;max-width:380px;padding:20px;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
            <div style="display:flex;align-items:center;gap:8px;"><i class='bx bxs-been-here' style="color:var(--accent);font-size:20px;"></i><span style="font-weight:900;font-size:15px;color:#fff;">Compartir</span></div>
            <button onclick="document.getElementById('canchero-share-sheet').remove()" style="background:rgba(255,255,255,0.06);border:none;color:#888;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:17px;">&times;</button>
        </div>
        <div style="font-size:11px;color:#888;margin-bottom:16px;">${(o.text||title).replace(/</g,'&lt;').slice(0,90)}</div>
        <div style="display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-bottom:16px;">
            ${btn('bxl-whatsapp','WhatsApp','https://wa.me/?text='+enc,'#25D366')}
            ${btn('bxl-twitter','X','https://twitter.com/intent/tweet?text='+enc,'#000')}
            ${btn('bxl-facebook','Facebook','https://www.facebook.com/sharer/sharer.php?u='+encU,'#1877F2')}
            ${btn('bxl-telegram','Telegram','https://t.me/share/url?url='+encU+'&text='+encodeURIComponent(text),'#229ED9')}
        </div>
        <button onclick="navigator.clipboard&&navigator.clipboard.writeText('${url.replace(/'/g,'')}');window.showToast&&showToast('Link copiado. Pegalo en Instagram, TikTok o donde quieras.','success')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:13px;cursor:pointer;"><i class='bx bx-link'></i> COPIAR LINK</button>
    </div>`;
    s.onclick = e => { if (e.target === s) s.remove(); };
    document.body.appendChild(s);
};
// Abrir un post puntual desde un link compartido (?post=<id>)
window._openSharedPost = async function(postId){
    const sb = window._sb; if (!sb || !postId) return;
    try {
        const { data: post } = await sb.from('posts').select('*').eq('id', postId).maybeSingle();
        if (!post) { showToast && showToast('Esta publicación ya no está disponible.', 'warning'); return; }
        try { await window._refreshPostsIdentity([post]); } catch(e){}
        let m = document.getElementById('shared-post-modal'); if (m) m.remove();
        m = document.createElement('div');
        m.id = 'shared-post-modal';
        m.style.cssText = 'position:fixed;inset:0;z-index:100300;background:rgba(0,0,0,0.9);backdrop-filter:blur(6px);display:flex;align-items:flex-start;justify-content:center;padding:70px 14px 30px;overflow-y:auto;';
        m.innerHTML = `<div style="width:100%;max-width:520px;">
            <div style="display:flex;justify-content:flex-end;margin-bottom:8px;"><button onclick="document.getElementById('shared-post-modal').remove()" style="background:rgba(255,255,255,0.1);border:none;color:#fff;width:36px;height:36px;border-radius:50%;font-size:19px;cursor:pointer;">&times;</button></div>
            ${typeof buildPostCard === 'function' ? buildPostCard(post) : ('<div style="background:#111;border-radius:14px;padding:18px;color:#ddd;">' + (post.content||'') + '</div>')}
        </div>`;
        m.onclick = e => { if (e.target === m) m.remove(); };
        document.body.appendChild(m);
    } catch(e){}
};
// ── VIDEO SIEMPRE REPRODUCIBLE ────────────────────────────────────────────────
// Videos subidos desde iPhone (HEVC/.mov) se ven EN NEGRO en Chrome/Android.
// Si el video está en Cloudinary, forzar transcodificación a H.264/mp4 al vuelo.
window._playableVideoUrl = function(u){
    try {
        u = String(u||'');
        if (!u) return u;
        if (u.indexOf('res.cloudinary.com') !== -1 && u.indexOf('/video/upload/') !== -1 && u.indexOf('vc_h264') === -1) {
            u = u.replace('/video/upload/', '/video/upload/f_mp4,vc_h264,ac_aac,q_auto/');
            // La extensión original (.mov/.webm) pisa el f_mp4 → normalizar a .mp4
            u = u.replace(/\.(mov|webm|avi|mkv|m4v)(\?|#|$)/i, '.mp4$2');
        }
        return u;
    } catch(e){ return u; }
};
// Poster (primer frame como JPG) para que iOS NUNCA muestre negro mientras el
// video decodifica. Cloudinary genera el frame con so_0 + extensión .jpg.
window._videoPosterUrl = function(u){
    try {
        u = String(u||'');
        if (u.indexOf('res.cloudinary.com') !== -1 && u.indexOf('/video/upload/') !== -1) {
            var p = u.replace('/video/upload/', '/video/upload/so_0,f_jpg,q_auto/');
            p = p.replace(/\.(mp4|mov|webm|avi|mkv|m4v)(\?|#|$)/i, '.jpg$2');
            if (!/\.jpg(\?|#|$)/i.test(p)) p = p.replace(/(\?|#|$)/, '.jpg$1');
            return p;
        }
    } catch(e){}
    return '';
};
// ── BLOQUE DE RESULTADO DE JUEGO (compartido al feed) ─────────────────────────
window._gameResultMeta = function(p){
    try { let m = p.meta; if (typeof m === 'string') m = JSON.parse(m); return (m && m.game_result) ? m.game_result : null; } catch(e){ return null; }
};
window._gameResultCardHTML = function(p){
    const g = window._gameResultMeta(p);
    if (!g) return '';
    const esc = s => String(s==null?'':s).replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const grad = { 'once-ideal':'linear-gradient(135deg,#16351a,#0a0a0a)', 'adivina':'linear-gradient(135deg,#2a1a35,#0a0a0a)', 'impostor':'linear-gradient(135deg,#351a1a,#0a0a0a)' }[g.gameId] || 'linear-gradient(135deg,#1a2a35,#0a0a0a)';
    const gid = String(g.gameId||'').replace(/'/g,'');
    return `<div style="border:1px solid rgba(186,255,0,0.22);border-radius:16px;overflow:hidden;margin-bottom:12px;background:${grad};">
        <div style="display:flex;align-items:center;gap:12px;padding:14px 16px;">
          <div style="width:48px;height:48px;border-radius:14px;background:rgba(255,255,255,0.08);display:flex;align-items:center;justify-content:center;font-size:26px;flex-shrink:0;">${g.emoji||'🎮'}</div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:10px;font-weight:800;letter-spacing:1px;color:var(--accent);text-transform:uppercase;">Juego · ${esc(g.gameName||'')}</div>
            <div style="font-size:15px;font-weight:900;color:#fff;line-height:1.2;">${esc(g.headline||'')}</div>
            ${g.detail?`<div style="font-size:11.5px;color:#bbb;margin-top:2px;">${esc(g.detail)}</div>`:''}
          </div>
        </div>
        <div style="padding:0 16px 14px;">
          <button onclick="event.stopPropagation();window._launchGameById('${gid}')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:12px;font-weight:900;font-size:13px;letter-spacing:.5px;cursor:pointer;"><i class='bx bx-joystick'></i> JUGAR A ${esc((g.gameName||'ESTE JUEGO').toUpperCase())}</button>
        </div>
      </div>`;
};
window._launchGameById = function(id){
    try {
        if (window._launchCancheroGame) { window._launchCancheroGame(id); return; }
        if (id === 'once-ideal' && window._onceStart) { window._onceStart(); return; }
        if (window.openGamesModal) window.openGamesModal();
    } catch(e){ try { window.openGamesModal && window.openGamesModal(); } catch(_){} }
};
// ── IDENTIDAD VIVA (estilo Instagram) ─────────────────────────────────────────
// Los posts/encuestas muestran SIEMPRE el nombre y la foto ACTUALES del autor
// (según el rol con que publicó), no los que tenía al publicar.
window._refreshPostsIdentity = async function(posts){
    try {
        const sb = window._sb; if (!sb || !posts || !posts.length) return posts;
        const emails = [...new Set(posts.map(p=>p.user_email).filter(Boolean))];
        if (!emails.length) return posts;
        const BIZ = window._BIZ_ROLES || ['club','complejo','tienda','organizacion','sponsor','profesional'];
        // Cache 60s para no repetir queries en cada render
        window._idCache = window._idCache || { t:0, users:{}, biz:{} };
        const now = Date.now();
        const missing = emails.filter(e => !window._idCache.users[e]);
        if (missing.length || (now - window._idCache.t) > 60000) {
            const [ur, br] = await Promise.all([
                sb.from('users').select('email,name,photo,photo_style,linked_profiles').in('email', emails),
                sb.from('business_requests').select('id,email,role,name,payload').in('email', emails)
            ]);
            (ur.data||[]).forEach(u => { window._idCache.users[u.email] = u; });
            (br.data||[]).forEach(b => {
                let pl = b.payload || {}; try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
                const rec = { name: b.name || pl.name, photo: b.photo || pl.photo || null, role: b.role };
                window._idCache.biz['id:'+b.id] = rec;
                window._idCache.biz['er:'+b.email+'|'+(b.role||'')] = rec; // el más nuevo pisa
            });
            window._idCache.t = now;
        }
        posts.forEach(p => {
            const role = (p.user_role||'jugador').toLowerCase();
            const u = window._idCache.users[p.user_email];
            if (BIZ.indexOf(role) !== -1) {
                const b = (p.business_id && window._idCache.biz['id:'+p.business_id])
                       || window._idCache.biz['er:'+p.user_email+'|'+role];
                if (b) {
                    if (b.name) p.user_name = b.name;
                    if (b.photo) p.user_avatar = b.photo;
                    p.user_photo_style = null;
                } else if (u && u.photo && !p.user_avatar) { p.user_avatar = u.photo; }
            } else if (role === 'fanatico') {
                let lp = (u && u.linked_profiles) || {};
                try { if (typeof lp === 'string') lp = JSON.parse(lp); } catch(e){ lp = {}; }
                const f = lp.fanatico;
                if (f) {
                    if (f.name) p.user_name = f.name;
                    if (f.photo) p.user_avatar = f.photo;
                    p.user_photo_style = f.photoStyle || null;
                }
            } else if (role === 'jugador' && u) {
                if (u.name) p.user_name = u.name;
                if (u.photo && !String(u.photo).includes('ui-avatars')) p.user_avatar = u.photo;
                if (u.photo_style) p.user_photo_style = u.photo_style;
            }
        });
    } catch(e){}
    return posts;
};
// COMPRAR/RESERVAR en un post compartido: abre DIRECTO el detalle del ítem
// (mismo modal centrado que al comprarlo desde el perfil del negocio), sin
// pasar por el perfil — antes caía en Publicaciones y "no aparecía nada".
window._openBizItemFromPost = async function(email, bizId, kind, itemId){
    try {
        const sb = window._sb;
        kind = (kind||'').toLowerCase();
        if (kind === 'torneo') {
            if (itemId && window.CancheroTournaments && window.CancheroTournaments.openPublicView) {
                try { window.CancheroTournaments.openPublicView(itemId); return; } catch(e){}
            }
            window.viewUserProfile && window.viewUserProfile(email, true, bizId ? { bizId: bizId } : {});
            return;
        }
        if (kind === 'cancha' && window._openReservationModal) {
            window._openReservationModal(email, '', itemId || '');
            return;
        }
        if (kind === 'producto' && itemId && sb) {
            try {
                const { data: prod } = await sb.from('business_products').select('*').eq('id', itemId).maybeSingle();
                if (prod && window._openProductModal) { window._openProductModal(prod); return; }
            } catch(e){}
        }
        if (kind === 'servicio' && itemId && sb && window._openServiceContactModal) {
            try {
                const { data: sv } = await sb.from('business_services').select('*').eq('id', itemId).maybeSingle();
                if (sv) { window._openServiceContactModal(email, sv.name || 'Servicio', sv.price || 0); return; }
            } catch(e){}
        }
        // Fallback: perfil del negocio con su identidad correcta
        window.viewUserProfile && window.viewUserProfile(email, true, bizId ? { bizId: bizId } : {});
    } catch(e){}
};
// Subir mi portada (negocios y jugadores): storage + persistencia según identidad
window._uploadMyCover = async function(input, email) {
    const f = input.files && input.files[0];
    if (!f) return;
    const sb = window._sb;
    try {
        showToast('Subiendo portada...', 'info');
        const fUp = window._compressImageFile ? await window._compressImageFile(f, 1600, 0.74) : f;
        let url;
        if (window.cloudUpload) { const r = await window.cloudUpload(fUp, { folder:'canchero/covers' }); if(!r||!r.url) throw new Error('cloud'); url = r.url; }
        else { const path = 'covers/' + (email || (window.userData && window.userData.email)) + '/' + Date.now() + '.jpg'; const up = await sb.storage.from('media').upload(path, fUp, { upsert: true, contentType: 'image/jpeg' }); if (up.error) throw up.error; url = sb.storage.from('media').getPublicUrl(path).data.publicUrl; }
        const isMe = window.userData && (!email || email === window.userData.email);
        let bizId = window._activeBizId && window._activeBizId();
        // FIX portada de negocio: si el perfil visible es de un negocio pero la identidad
        // activa no es 'biz:<id>' (p.ej. organización única), bizId venía null y la portada
        // se guardaba en users.cover_photo — pero el perfil de negocio LEE payload.cover,
        // así que "no funcionaba". Buscamos la fila del negocio por email+rol del perfil.
        if (isMe && !bizId) {
            try {
                const prof = document.querySelector('.social-profile[data-biz-role]');
                const bizRole = prof && prof.getAttribute('data-biz-role');
                if (bizRole) {
                    const { data: br } = await sb.from('business_requests').select('id,payload').eq('email', email || window.userData.email).eq('role', bizRole).order('created_at',{ascending:false}).limit(1).maybeSingle();
                    if (br) {
                        let pl = br.payload || {}; try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
                        pl.cover = url;
                        await sb.from('business_requests').update({ payload: pl }).eq('id', br.id);
                        bizId = String(br.id);
                    }
                }
            } catch(e){}
        }
        if (isMe && bizId && window._saveBizCover && window._activeBizId && window._activeBizId()) {
            // Identidad de negocio activa: guardar donde el perfil de negocio lee (payload.cover)
            await window._saveBizCover(url);
        } else {
            const { error } = await sb.from('users').update({ cover_photo: url }).eq('email', email || window.userData.email);
            if (error) throw error;
        }
        if (isMe) { window.userData.cover_photo = url; window.userData.coverPhoto = url; }
        showToast('Portada actualizada.', 'success');
        if (window.viewUserProfile) {
            if (isMe && bizId && bizId !== '__primary__') viewUserProfile(window.userData.email, false, { bizId: bizId });
            else viewUserProfile(email || window.userData.email);
        }
    } catch(e) { showToast('No se pudo subir: ' + (e.message || ''), 'error'); }
};

