    var followBtnHtml = isMe ? '' : ('<button id="' + followBtnId + '" onclick="window._toggleFollowBtn(\'' + followBtnId + '\',\'' + emailSafe + _bizTagJs + '\')" data-following="' + isFollowing + '" ' + (!isFollowing ? 'class="biz-cta-btn biz-cta-secondary"' : 'style="display:flex;align-items:center;gap:5px;background:transparent;color:#fff;border:1px solid #444;border-radius:22px;padding:9px 16px;font-size:12px;font-weight:900;cursor:pointer;"') + '>' + (isFollowing ? '<i class=\'bx bx-check\'></i> Siguiendo' : '<i class=\'bx bx-user-plus\'></i> + Seguir') + '</button>');

    var roleCta = { club:'<button onclick="window._vupBizTab(\'canchas\',\'' + emailSafe + '\')" class="biz-cta-btn biz-cta-primary"><i class=\'bx bx-calendar-check\'></i> VER CANCHAS</button>', tienda:'<button onclick="window._vupBizTab(\'productos\',\'' + emailSafe + '\')" class="biz-cta-btn biz-cta-primary"><i class=\'bx bx-shopping-bag\'></i> VER PRODUCTOS</button>', organizacion:'<button onclick="window._vupBizTab(\'eventos\',\'' + emailSafe + '\')" class="biz-cta-btn biz-cta-primary"><i class=\'bx bx-trophy\'></i> VER EVENTOS</button>', profesional:'<button onclick="window._vupBizTab(\'servicios\',\'' + emailSafe + '\')" class="biz-cta-btn biz-cta-primary"><i class=\'bx bx-briefcase\'></i> CONTRATAR</button>' };
