// Abrir el perfil del AUTOR de un post respetando su ROL (pedido 2026-07-09):
// un post de CLUB abre el perfil del club (no la tienda/jugador del mismo email);
// un post de negocio abre ESE negocio; jugador/fanático → perfil normal.
window._openPostAuthor = async function(email, role, name){
    role = (role || 'jugador').toLowerCase();
    name = name || '';
    try {
        if (role === 'club') {
            const sb = window._sb;
            if (sb) {
                // Buscar el club por dueño y nombre (los posts de club llevan el nombre del club)
                let { data: clubs } = await sb.from('clubs').select('id,name,owner_email,captain_email').or(`owner_email.eq.${email},captain_email.eq.${email}`);
                clubs = clubs || [];
                let club = clubs.find(c => (c.name||'').trim().toLowerCase() === name.trim().toLowerCase()) || clubs[0];
                if (club && window.viewClubProfile) { window.viewClubProfile(club.id); return; }
            }
        }
        const _bizR = ['tienda','complejo','organizacion','profesional','sponsor','cancha'];
        if (_bizR.indexOf(role) !== -1) { window.viewUserProfile(email, true, { bizRole: role }); return; }
    } catch(e){}
    if (window.openPlayerActions) window.openPlayerActions(email, name);
    else window.viewUserProfile(email);
};

// Solo la identidad JUGADOR puede jugar/postularse (tiendas/complejos/organizaciones/
// fanáticos NO juegan). Devuelve true si puede; si no, avisa y devuelve false.
window._mustBeJugador = function(accion){
    var r = (window._pubRole && window._pubRole()) || (window.userData && window.userData.role) || 'jugador';
    if (r === 'jugador') return true;
    if (window.showToast) showToast('Solo los JUGADORES pueden ' + (accion || 'jugar') + '. Cambiá a tu identidad de jugador.', 'warning');
    return false;
};
// Postularse desde la tarjeta "faltan jugadores": valida identidad, envía la solicitud
// y deja el botón en estado POSTULADO (pedido 2026-07-09).
window._urgentApply = async function(btn, clubId, clubName){
    if (!window._mustBeJugador('postularse para jugar')) return;
    try { if (window._requestJoinClub) await window._requestJoinClub(clubId, clubName); } catch(e){}
    if (btn) {
        btn.disabled = true;
        btn.style.background = 'rgba(186,255,0,0.18)';
        btn.style.color = 'var(--accent)';
        btn.style.boxShadow = 'none';
        btn.style.border = '1px solid rgba(186,255,0,0.4)';
        btn.innerHTML = "<i class='bx bx-check-double'></i> POSTULADO";
    }
};
// Tarjeta LIQUID GLASS para el aviso "faltan jugadores" en el feed (pedido 2026-07-08):
// reemplaza el texto plano por un CTA moderno con botón para postularse.
window._urgentPostHTML = function(p){
    try {
        var txt = p && p.content || '';
        if (txt.indexOf('⚡ FALTAN') !== 0) return null;
        var mCount = txt.match(/FALTAN\s+(\d+)/i);
        var mClub  = txt.match(/EN\s+(.+?)(\n|$)/i);
        var mLink  = txt.match(/#club\/([a-z0-9-]+)/i);
        var mPos   = txt.match(/Posición:\s*([^\n·]+)/i);
        var urgente = /URGENTE/.test(txt);
        var mMsg   = txt.split('\n\n')[2];
        if (mMsg && (mMsg.indexOf('→')===0 || mMsg.indexOf('#')===0)) mMsg = '';
        var count = (mCount && mCount[1]) || '1';
        var clubName = ((mClub && mClub[1]) || p.user_name || 'el club').trim();
        var clubId = (mLink && mLink[1]) || (p.meta && p.meta.club_id) || '';
        var clubNameSafe = clubName.replace(/'/g,"\\'").replace(/</g,'&lt;');
        var chips = [];
        if (mPos && mPos[1]) chips.push('<span style="background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.14);border-radius:14px;padding:3px 10px;font-size:10.5px;font-weight:800;color:#fff;"><i class=\'bx bx-target-lock\'></i> ' + mPos[1].trim().replace(/</g,'&lt;') + '</span>');
        if (urgente) chips.push('<span style="background:rgba(255,59,59,0.16);border:1px solid rgba(255,59,59,0.4);border-radius:14px;padding:3px 10px;font-size:10.5px;font-weight:900;color:#ff6b6b;"><i class=\'bx bx-bell\'></i> URGENTE</span>');
        return '<div style="margin:10px 0 6px;border-radius:18px;overflow:hidden;position:relative;background:linear-gradient(135deg,rgba(186,255,0,0.10),rgba(20,28,16,0.65));backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(186,255,0,0.28);box-shadow:inset 0 1px 0 rgba(255,255,255,0.12), 0 8px 26px rgba(0,0,0,0.35);padding:16px;">'
            + '<i class=\'bx bx-cancha\' style="position:absolute;right:12px;top:10px;font-size:52px;color:rgba(186,255,0,0.10);"></i>'
            + '<div style="font-size:10px;font-weight:900;letter-spacing:2px;color:var(--accent);margin-bottom:6px;"><i class=\'bx bx-user-plus\'></i> BUSCAMOS JUGADORES</div>'
            + '<div style="font-size:19px;font-weight:900;color:#fff;line-height:1.2;margin-bottom:4px;">Faltan ' + count + ' jugador' + (count!=='1'?'es':'') + '</div>'
            + '<div style="font-size:13px;color:#cfe5b0;font-weight:700;margin-bottom:10px;">en ' + clubName.replace(/</g,'&lt;') + '</div>'
            + (chips.length ? '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;">' + chips.join('') + '</div>' : '')
            + (mMsg ? '<div style="font-size:12.5px;color:#bbb;line-height:1.5;margin-bottom:12px;">' + mMsg.replace(/</g,'&lt;') + '</div>' : '<div style="height:4px;"></div>')
            + '<div style="display:flex;gap:8px;">'
            + (clubId ? ('<button onclick="event.stopPropagation();window._urgentApply(this,\'' + clubId + '\',\'' + clubNameSafe + '\')" style="flex:2;background:var(--accent);color:#000;border:none;border-radius:12px;padding:12px;font-weight:900;font-size:13px;cursor:pointer;box-shadow:0 0 18px rgba(186,255,0,0.25);"><i class=\'bx bx-run\'></i> POSTULARME</button>'
                + '<button onclick="event.stopPropagation();window.viewClubProfile&&window.viewClubProfile(\'' + clubId + '\')" style="flex:1;background:rgba(255,255,255,0.08);color:#fff;border:1px solid rgba(255,255,255,0.16);border-radius:12px;padding:12px;font-weight:800;font-size:12px;cursor:pointer;">Ver club</button>') : '')
            + '</div></div>';
    } catch(e){ return null; }
};

window._buildClubNeedText = function(club, clubId, count, urg, pos, msg){
    var head = '⚡ FALTAN ' + count + ' JUGADOR' + (count!==1?'ES':'') + ' EN ' + (club.name||'NUESTRO CLUB').toUpperCase();
    var bits = [];
    if (pos) bits.push('Posición: ' + pos);
    if (club.city) bits.push(club.city);
    if (club.country || club.nat) bits.push(club.country || club.nat);
    if (urg==='alta') bits.push('URGENTE');
    var link = 'https://canchero-app.vercel.app/#club/' + clubId;
    return head + '\n\n' + bits.join(' · ') + (msg?('\n\n' + msg):'') + '\n\n→ Sumate al club: ' + link + '\n\n#FaltanJugadores #Canchero';
};

window.publishClubUrgent = async function(clubId) {
    var sb = window._sb; var u = window.userData;
    if (!sb || !u) { window.showToast && showToast('Iniciá sesión para publicar.','warning'); return; }
    var club = window._cun_club || {};
    var count = window._cun_count || 1;
    var urg = window._cun_urg || 'alta';
    var pos = (document.getElementById('cun-pos') || {}).value || '';
    var msg = ((document.getElementById('cun-msg') || {}).value || '').trim();
    try { await sb.from('squad_requests').insert({ club_name: club.name || 'Mi club', club_id: clubId, captain_email: u.email, city: club.city || null, country: club.country || club.nat || null, missing_count: count, status: 'open', urgency: urg, position: pos || null, message: msg || null }); } catch(e2) {}
    document.getElementById('club-urgent-modal')?.remove();
    // Modal "Dónde compartir"
    window._cunCtx = { club: club, clubId: clubId, count: count, urg: urg, pos: pos, msg: msg };
    var pick = document.createElement('div');
    pick.style.cssText = 'position:fixed;inset:0;z-index:30100;background:rgba(0,0,0,0.92);display:flex;align-items:center;justify-content:center;padding:18px;';
    pick.innerHTML = '<div style="background:#0d100d;border:1px solid #1f2a14;border-radius:18px;padding:18px;max-width:400px;width:100%;">'+
      '<div style="font-size:13px;font-weight:900;color:var(--accent);margin-bottom:6px;text-align:center;"><i class="bx bx-user-plus"></i> ¿DÓNDE COMPARTIR EL AVISO?</div>'+
      '<div style="font-size:11px;color:#888;text-align:center;margin-bottom:14px;">Faltan ' + count + ' jugador' + (count!==1?'es':'') + (pos?(' · ' + pos):'') + '</div>'+
      '<div style="display:flex;flex-direction:column;gap:8px;">'+
        '<button onclick="window._cunShareFeed();this.closest(\'div[style*=fixed]\').remove();" style="background:var(--accent);color:#000;border:none;border-radius:12px;padding:12px;font-weight:900;font-size:13px;cursor:pointer;"><i class="bx bx-broadcast"></i> Publicar al feed de Canchero</button>'+
        '<button onclick="window._cunShareExternal();this.closest(\'div[style*=fixed]\').remove();" style="background:rgba(37,211,102,0.10);color:#25d366;border:1px solid rgba(37,211,102,0.3);border-radius:12px;padding:12px;font-weight:900;font-size:13px;cursor:pointer;"><i class="bx bxl-whatsapp"></i> Compartir fuera (WhatsApp/X/IG…)</button>'+
        '<button onclick="window._cunShareChat();this.closest(\'div[style*=fixed]\').remove();" style="background:rgba(100,180,255,0.10);color:#64b4ff;border:1px solid rgba(100,180,255,0.3);border-radius:12px;padding:12px;font-weight:900;font-size:13px;cursor:pointer;"><i class="bx bx-chat"></i> Copiar para chat</button>'+
        '<button onclick="this.closest(\'div[style*=fixed]\').remove()" style="background:transparent;color:#888;border:none;padding:8px;font-size:12px;cursor:pointer;">Cerrar</button>'+
      '</div></div>';
    document.body.appendChild(pick);
};
window._cunShareFeed = async function(){
    var c = window._cunCtx; var sb = window._sb; var u = window.userData;
    if (!c || !sb || !u) return;
    var txt = window._buildClubNeedText(c.club, c.clubId, c.count, c.urg, c.pos, c.msg);
    // Publicar CON IDENTIDAD DE CLUB (nombre + escudo) y con fallback si faltan columnas
    var basePost = {
        user_email: u.email, user_name: (c.club && c.club.name) || u.name || u.email, user_role: 'club',
        user_avatar: (c.club && (c.club.logo_url || c.club.logo)) || null,
        content: txt, media_type:'text', likes_count: 0
    };
    var full = Object.assign({}, basePost, {
        tags:['faltan_jugadores','club'],
        meta:{ club_id: c.clubId, missing_count: c.count, position: c.pos, urgency: c.urg, city: c.club.city, country: c.club.country||c.club.nat },
        expires_at: new Date(Date.now() + 48 * 3600000).toISOString()
    });
    try {
        var r = await sb.from('posts').insert(full);
        if (r.error) {
            // Fallback: reintento mínimo (por si tags/meta/expires_at no existen en posts)
            var r2 = await sb.from('posts').insert(basePost);
            if (r2.error) throw r2.error;
        }
        window.showToast && showToast('Aviso publicado al feed ✓','success');
        try { if (window.loadMainFeed) loadMainFeed(); } catch(e) {}
    } catch(err) { window.showToast && showToast('No se pudo publicar: ' + (err.message||''),'error'); }
};
window._cunShareExternal = async function(){
    var c = window._cunCtx; if (!c) return;
    var txt = window._buildClubNeedText(c.club, c.clubId, c.count, c.urg, c.pos, c.msg);
    var url = 'https://canchero-app.vercel.app/#club/' + c.clubId;
    try { if (navigator.share){ await navigator.share({ title:'Faltan jugadores en el club', text:txt, url:url }); return; } } catch(e){}
    try { await navigator.clipboard.writeText(txt); window.showToast && showToast('Aviso copiado','success'); } catch(e){ alert(txt); }
};
window._cunShareChat = async function(){
    var c = window._cunCtx; if (!c) return;
    var txt = window._buildClubNeedText(c.club, c.clubId, c.count, c.urg, c.pos, c.msg);
    try { await navigator.clipboard.writeText(txt); window.showToast && showToast('Texto copiado — pegalo en cualquier chat','success'); } catch(e){ alert(txt); }
};

