window._clubComposerMedia = null;
window._clubComposerPick = async function(input) {
    const f = input.files && input.files[0]; if (!f) return;
    const sb = window._sb, me = window.userData; if (!sb || !me) return;
    const isVid = f.type.startsWith('video');
    try {
        showToast('Subiendo ' + (isVid?'video':'foto') + '...', 'info');
        const fUp = isVid ? f : (window._compressImageFile ? await window._compressImageFile(f) : f);
        let url;
        if (window.cloudUpload) { const r = await window.cloudUpload(fUp, { folder:'canchero/club_posts' }); if(!r||!r.url) throw new Error('cloud'); url = r.url; }
        else { const path = 'club_posts/' + me.email + '/' + Date.now() + '.' + (isVid ? (f.name.split('.').pop()||'mp4') : 'jpg'); const up = await sb.storage.from('media').upload(path, fUp, { upsert: true, contentType: isVid ? f.type : 'image/jpeg' }); if (up.error) throw up.error; url = sb.storage.from('media').getPublicUrl(path).data.publicUrl; }
        window._clubComposerMedia = { url: url, type: isVid ? 'video' : 'image' };
        const pv = document.getElementById('club-composer-prev');
        pv.style.display = 'block';
        pv.innerHTML = isVid ? '<video src="'+url+'" style="width:100%;max-height:220px;" controls></video>' : '<img src="'+url+'" style="width:100%;max-height:220px;object-fit:cover;">';
    } catch(e) { showToast('Error al subir: ' + e.message, 'error'); }
};
window._publishClubPost = async function(clubId) {
    const txt = (document.getElementById('club-composer-text')?.value || '').trim();
    const media = window._clubComposerMedia;
    if (!txt && !media) { showToast('Escribí algo o subí una foto.', 'warning'); return; }
    const sb = window._sb; const me = window.userData;
    if (!sb || !me) return;
    try {
        let club = null;
        try { const { data } = await sb.from('clubs').select('name,logo,logo_url').eq('id', clubId).single(); club = data; } catch(e) {}
        const { error } = await sb.from('posts').insert({
            user_email: me.email, user_name: (club && club.name) || me.name || 'Club', user_role: 'club',
            user_avatar: (club && (club.logo_url || club.logo)) || me.photo || null,
            content: txt, media_url: media ? media.url : null, media_type: media ? media.type : 'text', likes_count: 0
        });
        if (error) throw error;
        window._clubComposerMedia = null;
        document.getElementById('club-composer-modal')?.remove();
        showToast('Publicado como ' + ((club && club.name) || 'club'), 'success');
        try { if (window.loadMainFeed) loadMainFeed(); } catch(e) {}
    } catch(e) { showToast('No se pudo publicar: ' + (e.message || ''), 'error'); }
};

// Solicitar unirme a un club (queda pendiente hasta que el dueno acepte)
window._requestJoinClub = async function(clubId, clubName) {
    if (window._mustBeJugador && !window._mustBeJugador('unirse a un club')) return;
    const sb = window._sb; const me = window.userData;
    if (!sb || !me) { showToast('Inicia sesion primero.', 'warning'); return; }
    try {
        const { data: ya } = await sb.from('club_members').select('id,status').eq('club_id', clubId).eq('player_email', me.email).limit(1);
        if (ya && ya.length) {
            showToast(ya[0].status === 'pendiente' ? 'Ya enviaste solicitud a este club.' : 'Ya sos parte de este club.', 'info');
            return;
        }
        const { error } = await sb.from('club_members').insert({
            club_id: clubId, player_email: me.email, player_name: me.name || me.email,
            position: me.pos || me.position || 'JUG', role: 'jugador', status: 'pendiente'
        });
        if (error) throw error;
        try {
            const { data: c } = await sb.from('clubs').select('owner_email,captain_email').eq('id', clubId).single();
            if (c && window.CancheroNotif && (c.owner_email||c.captain_email)) CancheroNotif.create(c.owner_email||c.captain_email, 'club_request', me.name || me.email, (me.name || 'Un jugador') + ' quiere unirse a ' + (clubName || 'tu club') + '. Tocá para revisar la solicitud.', clubId);
        } catch(e) {}
        showToast('Solicitud enviada al club.', 'success');
    } catch(e) { showToast('No se pudo enviar: ' + (e.message || ''), 'error'); }
};

