// Modal tinder de solicitudes del club (aceptar / rechazar de a una)
window.renderClubRequestsTinder = async function(clubId) {
    const sb = window._sb;
    let ov = document.getElementById('club-reqs-modal'); if (ov) ov.remove();
    ov = document.createElement('div'); ov.id = 'club-reqs-modal';
    ov.style.cssText = 'position:fixed;inset:0;z-index:100060;background:rgba(0,0,0,0.96);display:flex;flex-direction:column;';
    ov.innerHTML = `<div style="display:flex;align-items:center;gap:10px;padding:max(env(safe-area-inset-top,0px),12px) 14px 10px;background:#0d0d0d;border-bottom:1px solid #1a1a1a;">
        <button onclick="document.getElementById('club-reqs-modal').remove()" title="Volver" style="background:rgba(255,255,255,0.08);border:none;color:#fff;width:38px;height:38px;border-radius:50%;font-size:20px;cursor:pointer;flex-shrink:0;"><i class='bx bx-arrow-back'></i></button>
        <div style="flex:1;font-size:15px;font-weight:900;color:#fff;">Solicitudes del club</div>
        <button onclick="window.CancheroNotif?CancheroNotif.togglePanel():(window.openNotificationsPanel&&window.openNotificationsPanel())" style="background:rgba(255,255,255,0.06);border:1px solid #333;color:#aaa;width:36px;height:36px;border-radius:50%;font-size:18px;cursor:pointer;"><i class='bx bx-bell'></i></button>
        <button onclick="window.switchDashboardTab&&switchDashboardTab((window.userData&&window.userData.role)||'jugador','ajustes',null)" style="background:rgba(255,255,255,0.06);border:1px solid #333;color:#aaa;width:36px;height:36px;border-radius:50%;font-size:18px;cursor:pointer;"><i class='bx bx-cog'></i></button>
    </div>
    <div id="club-reqs-body" style="flex:1;overflow-y:auto;padding:0 16px 24px;"><div style="text-align:center;padding:40px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:26px;"></i></div></div>`;
    document.body.appendChild(ov);
    await window._renderClubReqsBody(clubId);
};
// TINDER de solicitudes del club: cards apiladas con FOTO grande, info y stats,
// deslizar → aceptar/rechazar (mismo estilo que las solicitudes de partido).
window._renderClubReqsBody = async function(clubId) {
    const body = document.getElementById('club-reqs-body'); if (!body) return;
    const sb = window._sb;
    try {
        let { data } = await sb.from('club_members').select('*').eq('club_id', clubId).eq('status', 'pendiente');
        // No repetir solicitudes ya procesadas en este dispositivo
        try {
            const done = JSON.parse(localStorage.getItem('canchero_reqs_done')||'[]');
            data = (data||[]).filter(r => !done.includes('cm:'+r.id));
        } catch(e){}
        if (!data || !data.length) {
            body.innerHTML = `<div style="text-align:center;padding:50px 20px;color:#555;"><i class='bx bx-check-circle' style="font-size:42px;display:block;margin-bottom:10px;opacity:0.4;"></i>No hay solicitudes pendientes.</div>`;
            return;
        }
        // Enriquecer con datos REALES del jugador (foto, posición, ciudad, stats)
        const usersMap = {};
        try {
            const emails = data.map(r => r.player_email).filter(Boolean);
            const { data: us } = await sb.from('users').select('email,name,photo,pos,city,stats').in('email', emails);
            (us||[]).forEach(u => usersMap[u.email] = u);
        } catch(e){}
        window._clubTinderQueue = data.map(r => ({ req: r, user: usersMap[r.player_email] || {} }));
        window._clubTinderClubId = clubId;
        body.innerHTML = '<div id="club-tinder-container" style="padding-top:12px;"></div>';
        _renderClubTinderStack();
    } catch(e) { body.innerHTML = `<div style="text-align:center;padding:40px;color:#f44;">Error al cargar solicitudes.</div>`; }
};
function _renderClubTinderStack() {
    const cont = document.getElementById('club-tinder-container');
    if (!cont) return;
    const queue = window._clubTinderQueue || [];
    if (!queue.length) {
        cont.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;"><i class="bx bx-check-double" style="font-size:36px;display:block;margin-bottom:10px;color:var(--accent);"></i>¡Listo! Procesaste todas las solicitudes.</div>';
        if (window._updateClubReqBadge) window._updateClubReqBadge(window._clubTinderClubId);
        if (window._loadClubJoinRequests) window._loadClubJoinRequests(window._clubTinderClubId);
        return;
    }
    let cardsHtml = '';
    for (let i = Math.min(queue.length, 3) - 1; i >= 0; i--) {
        const item = queue[i];
        const u = item.user || {};
        const r = item.req;
        const nm = u.name || r.player_name || (r.player_email||'').split('@')[0];
        const photo = u.photo || r.player_photo;
        const pos = u.pos || r.position || '';
        const city = u.city || '';
        const st = u.stats || {};
        const initial = (nm||'?').trim()[0].toUpperCase();
        const emEsc = (r.player_email||'').replace(/'/g, "\\'");
        const offset = i * 6, scale = 1 - i * 0.04;
        const bgImg = photo
            ? 'background-image:linear-gradient(to top, rgba(0,0,0,0.88) 0%, rgba(0,0,0,0.1) 50%), url(\'' + photo + '\');background-size:cover;background-position:center 25%;'
            : 'background:linear-gradient(135deg,#1a2a00,#0d0d0d);';
        const avatarBig = photo ? '' : '<div style="position:absolute;top:36%;left:50%;transform:translate(-50%,-50%);width:120px;height:120px;border-radius:50%;background:var(--accent);color:#000;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:54px;">' + initial + '</div>';
        cardsHtml += '<div class="tinder-card" data-idx="' + i + '" style="' + bgImg + 'transform:translateY(' + offset + 'px) scale(' + scale + ');z-index:' + (10 - i) + ';' + (i===0?'':'pointer-events:none;') + '">' +
            avatarBig +
            '<div style="position:absolute;bottom:0;left:0;right:0;padding:20px;">' +
                '<div style="font-size:24px;font-weight:900;color:#fff;">' + nm + '</div>' +
                '<div style="font-size:13px;color:var(--accent);font-weight:700;margin-bottom:8px;">' + (pos || 'Jugador') + (city ? ' · ' + city : '') + '</div>' +
                '<div style="display:flex;gap:14px;font-size:12px;color:#ddd;">' +
                    '<span><i class="bx bx-football"></i> ' + (st.goals||0) + '</span><span><i class="bx bx-target-lock"></i> ' + (st.assists||0) + '</span><span><i class="bx bx-calendar"></i> ' + (st.matches||0) + '</span><span><i class="bx bx-star"></i> ' + (st.rating||50) + '</span>' +
                '</div>' +
                '<button onclick="window.viewUserProfile && window.viewUserProfile(\'' + emEsc + '\', true)" style="margin-top:10px;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);color:#fff;border-radius:20px;padding:6px 14px;font-size:11px;font-weight:700;cursor:pointer;backdrop-filter:blur(4px);">VER PERFIL COMPLETO</button>' +
            '</div>' +
        '</div>';
    }
    cont.innerHTML =
        '<div class="tinder-card-stack">' + cardsHtml + '</div>' +
        '<div class="tinder-actions">' +
            '<button class="tinder-btn tinder-btn-no" onclick="window._swipeClubTinder(\'left\')" title="Rechazar">✗</button>' +
            '<button class="tinder-btn tinder-btn-yes" onclick="window._swipeClubTinder(\'right\')" title="Aceptar">✓</button>' +
        '</div>' +
        '<div style="text-align:center;margin-top:10px;font-size:11px;color:#666;">' + queue.length + ' solicitud' + (queue.length>1?'es':'') + ' pendiente' + (queue.length>1?'s':'') + ' · Deslizá o usá los botones</div>';
    _attachClubTinderDrag();
}
function _attachClubTinderDrag() {
    const card = document.querySelector('#club-tinder-container .tinder-card[data-idx="0"]');
    if (!card) return;
    let startX = 0, curX = 0, dragging = false;
    function down(x){ dragging = true; startX = x; card.style.transition = 'none'; }
    function move(x){ if(!dragging) return; curX = x - startX; card.style.transform = 'translateX(' + curX + 'px) rotate(' + (curX/20) + 'deg)'; }
    function up(){ if(!dragging) return; dragging = false; card.style.transition = 'transform .3s, opacity .3s';
        if (curX > 90) window._swipeClubTinder('right');
        else if (curX < -90) window._swipeClubTinder('left');
        else card.style.transform = 'translateY(0) scale(1)';
        curX = 0;
    }
    card.addEventListener('mousedown', function(e){ down(e.clientX); });
    window.addEventListener('mousemove', function(e){ move(e.clientX); });
    window.addEventListener('mouseup', up);
    card.addEventListener('touchstart', function(e){ down(e.touches[0].clientX); }, {passive:true});
    card.addEventListener('touchmove', function(e){ move(e.touches[0].clientX); }, {passive:true});
    card.addEventListener('touchend', up);
}
window._swipeClubTinder = async function(direction) {
    const queue = window._clubTinderQueue || [];
    if (!queue.length) return;
    const item = queue[0];
    const card = document.querySelector('#club-tinder-container .tinder-card[data-idx="0"]');
    if (card) card.classList.add(direction === 'right' ? 'swipe-right' : 'swipe-left');
    try { await window._respondClubJoin(item.req.id, window._clubTinderClubId, direction === 'right'); } catch(e){}
    setTimeout(function() {
        window._clubTinderQueue = queue.slice(1);
        _renderClubTinderStack();
    }, 320);
};
window._respondClubJoinTinder = async function(rowId, clubId, accept) {
    await window._respondClubJoin(rowId, clubId, accept);
    await window._renderClubReqsBody(clubId);
    if (window._updateClubReqBadge) window._updateClubReqBadge(clubId);
};
window._respondClubJoin = async function(rowId, clubId, accept) {
    const sb = window._sb;
    try {
        let playerEmail = null;
        try { const { data } = await sb.from('club_members').select('player_email').eq('id', rowId).single(); playerEmail = data && data.player_email; } catch(e) {}
        if (accept) { const _rA = await sb.from('club_members').update({ status: 'activo' }).eq('id', rowId); if (_rA.error) console.warn('aceptar club:', _rA.error.message); }
        else { const _rD = await sb.from('club_members').delete().eq('id', rowId); if (_rD.error) { try { await sb.from('club_members').update({ status:'rechazado' }).eq('id', rowId); } catch(_e){} } }
        // Marcar procesada (no vuelve a aparecer aunque la escritura falle)
        try {
            const done = JSON.parse(localStorage.getItem('canchero_reqs_done')||'[]');
            if (!done.includes('cm:'+rowId)) { done.push('cm:'+rowId); localStorage.setItem('canchero_reqs_done', JSON.stringify(done.slice(-500))); }
        } catch(e){}
        if (playerEmail && window.CancheroNotif) CancheroNotif.create(playerEmail, accept ? 'club_accept' : 'club_reject', 'Canchero', accept ? 'Te aceptaron en el club. Ya sos parte del plantel.' : 'Tu solicitud al club fue rechazada.');
        showToast(accept ? 'Jugador aceptado en el plantel.' : 'Solicitud rechazada.', accept ? 'success' : 'default');
        window._loadClubJoinRequests(clubId);
        if (window._loadClubPlanilla) window._loadClubPlanilla(clubId);
    } catch(e) { showToast('Error: ' + (e.message || ''), 'error'); }
};

// Subir portada del club (storage media/club_covers + clubs.cover_photo)
window._uploadClubCover = async function(clubId, input) {
    const f = input.files && input.files[0];
    if (!f) return;
    const sb = window._sb;
    try {
        showToast('Subiendo portada...', 'info');
        const fUp = window._compressImageFile ? await window._compressImageFile(f, 1600, 0.74) : f;
        let url;
        if (window.cloudUpload) { const r = await window.cloudUpload(fUp, { folder:'canchero/club_covers' }); if(!r||!r.url) throw new Error('cloud'); url = r.url; }
        else { const path = 'club_covers/' + clubId + '/' + Date.now() + '.jpg'; const up = await sb.storage.from('media').upload(path, fUp, { upsert: true, contentType: 'image/jpeg' }); if (up.error) throw up.error; url = sb.storage.from('media').getPublicUrl(path).data.publicUrl; }
        const { error } = await sb.from('clubs').update({ cover_photo: url }).eq('id', clubId);
        if (error) throw error;
        showToast('Portada actualizada.', 'success');
        window.viewClubProfile(clubId);
    } catch(e) { showToast('No se pudo subir: ' + (e.message || ''), 'error'); }
};

// Cerrar el perfil del club restaurando el perfil de jugador (estaba oculto anti-flash)
window._closeClubProfileModal = function(){
    const m = document.getElementById('club-profile-modal');
    if (m) m.remove();
    const pv = document.getElementById('jugador-perfil');
    if (pv) pv.style.visibility = '';
};
// Seguir / dejar de seguir un club (tabla club_follows)
window._toggleFollowClub = async function(clubId, btn){
    const sb = window._sb; const me = window.userData;
    if (!sb || !me || !me.email) { showToast && showToast('Iniciá sesión primero.','warning'); return; }
    try {
        const { data: ex } = await sb.from('club_follows').select('id').eq('club_id', String(clubId)).eq('follower_email', me.email).limit(1);
        if (ex && ex.length) {
            await sb.from('club_follows').delete().eq('id', ex[0].id);
            if (btn) { btn.innerHTML = "<i class='bx bx-plus'></i> Seguir"; btn.dataset.following='0'; }
            showToast && showToast('Dejaste de seguir al club.','info');
        } else {
            const { error } = await sb.from('club_follows').insert({ club_id: String(clubId), follower_email: me.email, follower_name: me.name || me.email });
            if (error) throw error;
            if (btn) { btn.innerHTML = "<i class='bx bx-check'></i> Siguiendo"; btn.dataset.following='1'; }
            showToast && showToast('Ahora seguís al club.','success');
        }
        const cnt = document.getElementById('club-followers-count');
        if (cnt) cnt.textContent = Math.max(0, parseInt(cnt.textContent||'0') + (btn && btn.dataset.following==='1' ? 1 : -1));
    } catch(e) { showToast && showToast('No se pudo seguir: ' + (e.message||''), 'error'); }
};
// ── Escudo del club estilo FC 26: la foto va RECORTADA en forma de escudo,
// con trazo fino degradado (nada de borde circular grueso). ──────────────────
window._clubShieldHtml = function(logoSrc, size, clubId){
    size = size || 92;
    const h = Math.round(size * 1.18);
    const uid = 'shld_' + Math.random().toString(36).slice(2, 8);
    const path = 'M50 3 L93 12 L93 60 Q93 87 50 109 Q7 87 7 60 L7 12 Z';
    const inner = logoSrc
        ? `<image href="${logoSrc}" x="0" y="0" width="100" height="112" preserveAspectRatio="xMidYMid slice" clip-path="url(#${uid}c)"/>`
        : `<path d="${path}" fill="rgba(186,255,0,0.08)" clip-path="url(#${uid}c)"/>
           <text x="50" y="66" text-anchor="middle" font-size="34" fill="#baff00" font-family="boxicons">&#xeb5c;</text>`;
    return `<div style="position:relative;width:${size}px;height:${h}px;filter:drop-shadow(0 6px 16px rgba(0,0,0,0.55)) drop-shadow(0 0 10px rgba(186,255,0,0.18));">
      <svg viewBox="0 0 100 112" width="${size}" height="${h}" style="display:block;" ${clubId?`data-club-shield="${clubId}"`:''}>
        <defs>
          <clipPath id="${uid}c"><path d="${path}"/></clipPath>
          <linearGradient id="${uid}g" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#e6ff66"/>
            <stop offset="0.5" stop-color="#baff00"/>
            <stop offset="1" stop-color="#5e8a00"/>
          </linearGradient>
        </defs>
        <path d="${path}" fill="#0c0f0c"/>
        ${inner}
        <path d="${path}" fill="none" stroke="url(#${uid}g)" stroke-width="2.6" stroke-linejoin="round"/>
        <path d="M50 8 L88 16 L88 59 Q88 83 50 103 Q12 83 12 59 L12 16 Z" fill="none" stroke="rgba(255,255,255,0.14)" stroke-width="1"/>
      </svg>
    </div>`;
};
window.viewClubProfile = async function(id) {
    const sb = window._sb;
    // Anti-flash (P1.1): mostrar el modal con loader ANTES de consultar la DB,
    // así nunca se ve el perfil de jugador de fondo mientras carga.
    {
        const _pre = document.getElementById('club-profile-modal');
        if (_pre) _pre.remove();
        const _lm = document.createElement('div');
        _lm.id = 'club-profile-modal';
        _lm.style.cssText = 'position:fixed;top:var(--nav-h,62px);left:0;right:0;bottom:0;z-index:900;background:#0d0d0d;overflow-y:auto;';
        _lm.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:60%;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:30px;color:var(--accent);"></i></div>';
        document.body.appendChild(_lm);
    }
    let club = null;
    if (sb) {
        try { const { data } = await sb.from('clubs').select('*').eq('id', id).maybeSingle(); if (data) club = data; } catch(e) {}
    }
    if (!club) {
        const stored = JSON.parse(localStorage.getItem('canchero_mis_clubes') || '[]');
        club = stored.find(c => String(c.id) === String(id));
    }
    if (!club) { const _lm2=document.getElementById('club-profile-modal'); if(_lm2)_lm2.remove(); if (typeof showToast === 'function') showToast('Club no encontrado.', 'error'); return; }

    window.currentEditingClubId = id;

    // Contadores: jugadores de plantilla + seguidores del club
    let membersCount = 0, followersCount = 0, iFollow = false, myMemberStatus = null;
    if (sb) {
        try { const r = await sb.from('club_members').select('id', { count:'exact', head:true }).eq('club_id', id).or('status.is.null,status.neq.pendiente'); membersCount = r.count || 0; } catch(e){}
        try { const r2 = await sb.from('club_follows').select('id', { count:'exact', head:true }).eq('club_id', String(id)); followersCount = r2.count || 0; } catch(e){}
        try { if (userData && userData.email) { const r3 = await sb.from('club_follows').select('id').eq('club_id', String(id)).eq('follower_email', userData.email).limit(1); iFollow = !!(r3.data && r3.data.length); } } catch(e){}
        // ¿Ya me postulé (desde el feed o donde sea) o ya soy parte? El botón lo refleja.
        try { if (userData && userData.email) { const r4 = await sb.from('club_members').select('status').eq('club_id', id).eq('player_email', userData.email).limit(1); if (r4.data && r4.data.length) myMemberStatus = r4.data[0].status || 'activo'; } } catch(e){}
    }

    // Modal full-screen para el perfil del club
    const existing = document.getElementById('club-profile-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'club-profile-modal';
    // Arranca debajo de la barra superior real (safe-area del iPhone incluida)
    modal.style.cssText = 'position:fixed;top:var(--nav-h,62px);left:0;right:0;bottom:0;z-index:900;background:#0d0d0d;overflow-y:auto;-webkit-overflow-scrolling:touch;';

    const meEmail = userData && userData.email;
    const isOwner = meEmail && (meEmail === club.owner_email || meEmail === club.captain_email || meEmail === club.cap1_email || meEmail === club.cap2_email || meEmail === club.cap || meEmail === (club.captains||{}).primary);
    const logoSrc = club.logo_url || club.logo || club.shield || '';
    const bannerSrc = club.banner_url || club.coverPhoto || club.cover_url || '';
    const socials = (club.socials && typeof club.socials === 'object') ? club.socials : {};
    const linkRow = [];
    if (club.link) { const _u = String(club.link); linkRow.push(`<a href="${_u.startsWith('http')?_u:'https://'+_u}" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:none;display:inline-flex;align-items:center;gap:4px;font-size:12px;"><i class='bx bx-link'></i>${_u.replace(/^https?:\/\//,'').slice(0,32)}</a>`); }
    if (socials.instagram) linkRow.push(`<a href="https://instagram.com/${String(socials.instagram).replace('@','')}" target="_blank" rel="noopener" style="color:#ccc;text-decoration:none;display:inline-flex;align-items:center;gap:4px;font-size:12px;"><i class='bx bxl-instagram'></i>@${String(socials.instagram).replace('@','')}</a>`);
    if (socials.x || socials.twitter) linkRow.push(`<a href="https://x.com/${String(socials.x||socials.twitter).replace('@','')}" target="_blank" rel="noopener" style="color:#ccc;text-decoration:none;display:inline-flex;align-items:center;gap:4px;font-size:12px;"><i class='bx bx-hash'></i>@${String(socials.x||socials.twitter).replace('@','')}</a>`);
    if (socials.youtube) linkRow.push(`<a href="https://youtube.com/${String(socials.youtube)}" target="_blank" rel="noopener" style="color:#ccc;text-decoration:none;display:inline-flex;align-items:center;gap:4px;font-size:12px;"><i class='bx bxl-youtube'></i>YouTube</a>`);

    modal.innerHTML = `
    <div style="max-width:680px;margin:0 auto;padding-bottom:calc(130px + env(safe-area-inset-bottom));">
        <!-- Portada del club (editable por el dueño) -->
        <div style="${(club.cover_photo||bannerSrc)?`background-image:url('${club.cover_photo||bannerSrc}');background-size:cover;background-position:center;`:'background:linear-gradient(135deg,#0e1a0e,#0a0a0a);'}height:150px;position:relative;border-radius:0 0 18px 18px;overflow:hidden;">
            ${(function(){
                // Si estoy ACTUANDO COMO este equipo, el perfil es una sección propia
                // de la barra → SIN botón volver (no hay a dónde "volver").
                var _isMyTeamSection = window.userData && window.userData._activeProfile === 'team' && String(window.userData._activeClubId) === String(id);
                return _isMyTeamSection ? '' : `<button onclick="window._closeClubProfileModal()" style="position:absolute;top:12px;left:12px;background:rgba(0,0,0,0.6);border:none;color:#fff;border-radius:50%;width:36px;height:36px;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;z-index:2;"><i class='bx bx-arrow-back'></i></button>`;
            })()}
            ${isOwner ? `<div style="position:absolute;top:12px;right:12px;display:flex;gap:8px;z-index:2;"><button onclick="document.getElementById('club-cover-input').click()" title="Cambiar portada" style="background:rgba(0,0,0,0.6);border:1px solid rgba(255,255,255,0.25);color:#fff;border-radius:50%;width:36px;height:36px;cursor:pointer;font-size:17px;display:flex;align-items:center;justify-content:center;"><i class='bx bx-camera'></i></button></div><input type="file" id="club-cover-input" accept="image/*" style="display:none;" onchange="window._uploadClubCover('${id}', this)">` : ''}
        </div>
        <!-- Escudo con MARCO en forma de escudo (estilo FC 26, sin borde circular grueso) -->
        <div style="padding:0 16px;position:relative;margin-bottom:10px;">
            <div style="position:absolute;top:-54px;left:16px;">
                ${window._clubShieldHtml ? window._clubShieldHtml(logoSrc, 92, id) : ''}
            </div>
            <div style="padding-top:14px;display:flex;align-items:center;justify-content:flex-end;gap:6px;flex-wrap:wrap;">
                ${isOwner
                    ? `<button onclick="window.openClubUrgentModal&&window.openClubUrgentModal()" title="Faltan jugadores" style="background:rgba(255,59,59,0.12);color:#ff5555;border:1px solid rgba(255,59,59,0.35);border-radius:50%;width:34px;height:34px;font-size:16px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;"><i class='bx bx-user-plus'></i></button>
                       <button onclick="window.CancheroSocial&&CancheroSocial.openSaved&&CancheroSocial.openSaved()" title="Guardados" style="background:rgba(255,255,255,0.05);color:var(--accent);border:1px solid #333;border-radius:50%;width:34px;height:34px;font-size:15px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;"><i class='bx bx-bookmark'></i></button>
                       <button onclick="window.openClubProfileEditor&&window.openClubProfileEditor('${id}')" title="Editar perfil" style="background:rgba(255,255,255,0.05);color:#ccc;border:1px solid #333;border-radius:50%;width:34px;height:34px;font-size:15px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;"><i class='bx bx-edit-alt'></i></button>`
                    : ((myMemberStatus === 'pendiente'
                        ? `<button disabled style="background:rgba(186,255,0,0.12);color:var(--accent);border:1px solid rgba(186,255,0,0.35);border-radius:16px;padding:7px 14px;font-size:11px;font-weight:800;cursor:default;display:inline-flex;align-items:center;gap:4px;"><i class='bx bx-check-double'></i> Solicitud enviada</button>`
                        : myMemberStatus
                        ? `<button disabled style="background:rgba(255,255,255,0.06);color:#00e676;border:1px solid rgba(0,230,118,0.3);border-radius:16px;padding:7px 14px;font-size:11px;font-weight:800;cursor:default;display:inline-flex;align-items:center;gap:4px;"><i class='bx bx-check'></i> Sos parte</button>`
                        : `<button onclick="window._requestJoinClub('${id}','${(club.name||'').replace(/'/g,'')}')" style="background:var(--accent);color:#000;border:none;border-radius:16px;padding:7px 14px;font-size:11px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;gap:4px;"><i class='bx bx-user-plus'></i> Unirme</button>`)
                       + `<button onclick="window._toggleFollowClub('${id}', this)" data-following="${iFollow?'1':'0'}" style="background:rgba(255,255,255,0.06);color:#fff;border:1px solid #333;border-radius:16px;padding:7px 14px;font-size:11px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;gap:4px;">${iFollow?"<i class='bx bx-check'></i> Siguiendo":"<i class='bx bx-plus'></i> Seguir"}</button>`)}
            </div>
        </div>
        <div style="padding:6px 16px 12px;">
            <h1 style="font-family:Outfit,sans-serif;font-weight:900;font-size:22px;margin-bottom:2px;">${club.name}</h1>
            <div style="font-size:12px;color:#555;">@${(club.name||'club').toLowerCase().replace(/\s+/g,'_')} · ${club.city||'Uruguay'}${club.nat&&club.nat!=='Uruguay'?', '+club.nat:''}${club.modality?' · '+String(club.modality).toUpperCase():''}</div>
            ${club.bio ? `<p style="font-size:13px;color:#aaa;margin-top:8px;line-height:1.6;">${club.bio}</p>` : (isOwner?`<p style="font-size:12px;color:#555;margin-top:8px;">Agregá una descripción del club desde <b>Editar perfil</b>.</p>`:'')}
            ${linkRow.length ? `<div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:8px;">${linkRow.join('')}</div>` : ''}
            <div class="profile-follow-row" style="margin-top:12px;">
                <div><strong id="club-followers-count">${followersCount}</strong><span>Seguidores</span></div>
                <div><strong>${membersCount}</strong><span>Jugadores</span></div>
            </div>
        </div>
        <!-- Tabs con iconos (mismo estilo que el perfil de jugador) -->
        <div class="profile-tabs-bar profile-tabs-icons" id="club-profile-tabs" style="margin:0 16px 12px;">
            ${[['posts','bx-grid-alt','Publicaciones'],['jugadores','bx-group','Plantilla'],['stats','bx-stats','Estadísticas'],['logros','bx-medal','Logros'],['info','bx-info-circle','Info']
            ].map((t,i) =>
                `<div onclick="window._clubProfileTab('${t[0]}','${id}',this)" class="profile-tab cp-tab${i===0?' active':''}" title="${t[2]}" aria-label="${t[2]}"><i class='bx ${t[1]}'></i></div>`
            ).join('')}
        </div>
        <div id="club-profile-content" style="padding:0 16px;min-height:200px;">
            <div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div>
        </div>
    </div>`;

    modal.onclick = e => { if (e.target === modal) window._closeClubProfileModal(); };
    document.body.appendChild(modal);
    // Lo primero que se ve = PUBLICACIONES del club
    window._clubProfileTab('posts', id, modal.querySelector('.cp-tab'));
};

window._clubProfileTab = async function(tab, clubId, btn) {
    document.querySelectorAll('#club-profile-tabs .cp-tab').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    else { const b2 = document.querySelector(`#club-profile-tabs .cp-tab[onclick*="'${tab}'"]`); if (b2) b2.classList.add('active'); }
    const content = document.getElementById('club-profile-content');
    if (!content) return;
    content.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div>';
    const sb = window._sb;
    if (!sb) { content.innerHTML = '<div style="padding:20px;color:#f44;text-align:center;">Sin conexión.</div>'; return; }

    // Cargar la fila del club + isOwner en este scope (antes el branch "jugadores" usaba
    // variables de viewClubProfile que no existían acá → spinner infinito).
    let club = null;
    try { const { data } = await sb.from('clubs').select('*').eq('id', clubId).maybeSingle(); club = data || null; } catch(e) {}
    if (!club) {
        try { const stored = JSON.parse(localStorage.getItem('canchero_mis_clubes') || '[]'); club = stored.find(c => String(c.id) === String(clubId)) || null; } catch(e) {}
    }
    if (!club) club = {};
    const _meEmail = (userData && userData.email || '').toLowerCase();
    const isOwner = !!(_meEmail && (_meEmail === (club.owner_email||'').toLowerCase() || _meEmail === (club.captain_email||'').toLowerCase() || _meEmail === (club.cap1_email||'').toLowerCase() || _meEmail === (club.cap2_email||'').toLowerCase()));

    if (tab === 'posts') {
        // PUBLICACIONES del club (posts hechos "como club" por el dueño)
        let posts = [];
        try {
            const ownerEm = (club.owner_email || '').toLowerCase();
            if (ownerEm) {
                const { data } = await sb.from('posts').select('*').eq('user_email', ownerEm).eq('user_role', 'club').order('created_at', { ascending: false }).limit(30);
                posts = data || [];
            }
        } catch(e) {}
        // Si el dueño administra más de un club, quedarnos con los del nombre de ESTE club
        const _filtered = posts.filter(p => !p.user_name || !club.name || p.user_name === club.name);
        if (_filtered.length) posts = _filtered;
        content.innerHTML = posts.length
            ? posts.map(p => { try { return buildPostCard(p); } catch(e) { return ''; } }).join('')
            : `<div style="text-align:center;padding:36px 20px;color:#555;font-size:13px;"><i class='bx bx-news' style="font-size:30px;opacity:.4;display:block;margin-bottom:8px;"></i>El club todavía no publicó nada.${isOwner?`<br><span style="font-size:11px;color:#666;">Publicá desde el INICIO actuando como tu equipo (el composer del feed usa tu rol activo).</span>`:''}</div>`;
    } else if (tab === 'stats') {
        // ESTADÍSTICAS (compactas, en su propia pestaña)
        const _cs = (club.stats && typeof club.stats==='object') ? club.stats : {};
        const pj = _cs.pj || club.matches_played || 0;
        const w  = _cs.w  || club.wins || 0;
        const e  = _cs.e  || club.draws || 0;
        const l  = _cs.l  || club.losses || 0;
        const gf = _cs.gf || club.goals_for || 0;
        const gc = _cs.gc || club.goals_against || 0;
        const pts = (_cs.pts!=null) ? _cs.pts : (w*3 + e);
        const gd = gf - gc;
        const cell = (lbl,val,color) => `<div style="background:#111;border:1px solid #1e1e1e;border-radius:10px;padding:8px 6px;text-align:center;"><div style="font-size:15px;font-weight:900;color:${color||'#fff'};">${val}</div><div style="font-size:8.5px;color:#555;font-weight:700;letter-spacing:1px;">${lbl}</div></div>`;
        content.innerHTML = `
            <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:8px;">${cell('PJ',pj)}${cell('V',w,'#00e676')}${cell('E',e,'#ffaa00')}${cell('D',l,'#ff4444')}</div>
            <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;">${cell('GF',gf,'#baff00')}${cell('GC',gc,'#888')}${cell('DG',(gd>=0?'+':'')+gd,gd>0?'#00e676':gd<0?'#ff4444':'#888')}${cell('Pts',pts,'var(--accent)')}</div>`;
    } else if (tab === 'jugadores') {
        // OJO: .neq('status','pendiente') excluye también las filas con status NULL
        // (por eso había jugadores que se veían en gestión pero no acá).
        let { data: members } = await sb.from('club_members').select('*').eq('club_id', clubId).or('status.is.null,status.neq.pendiente').order('role');
        // El club EMPIEZA SIN JUGADORES: no se inyecta al dueño como capitán. La cuenta
        // que crea el club es la gestión del equipo, no un jugador de la cancha. Los
        // jugadores se suman únicamente por solicitudes aceptadas (club_members activos).
        members = members || [];
        // Cargar fotos faltantes de los miembros
        try {
            const emails = members.map(m=>m.player_email).filter(Boolean);
            if (emails.length) {
                const { data: us } = await sb.from('users').select('email,photo,name').in('email', emails);
                const umap = {}; (us||[]).forEach(u=>umap[(u.email||'').toLowerCase()]=u);
                members.forEach(m=>{ const u=umap[(m.player_email||'').toLowerCase()]; if(u){ m.player_photo=m.player_photo||u.photo; m.player_name=m.player_name||u.name; } });
            }
        } catch(e){}

        // Determinar formato y slots usando CancheroFormations (asigna por posición REAL del jugador)
        const fmtStr = ((club.modality||club.format||'F11')+'').toLowerCase();
        const fmtKey = /5/.test(fmtStr)?'5v5':(/7/.test(fmtStr)?'7v7':'11v11');
        const total = fmtKey==='5v5'?5:fmtKey==='7v7'?7:11;
        const meEmail2 = (userData && userData.email || '').toLowerCase();
        const isMember = members.some(m=>(m.player_email||'').toLowerCase()===meEmail2) || isOwner;

        let slots, assigned;
        if (window.CancheroFormations) {
            slots = window.CancheroFormations.slotsFor(fmtKey, club.formation || null);
            // Mapear members al formato que espera assign() (necesita .id y .position)
            const playersForAssign = members.map((m,i)=>({ id: m.player_email||('p'+i), position: m.position||m.pos||'MED', _m: m }));
            const slotted = window.CancheroFormations.assign(playersForAssign, slots);
            // assigned[idx] → member real (o null)
            assigned = slotted.map(p => p ? p._m : null);
        } else {
            slots = (total===5
                ? [{k:'ARQ',x:50,y:88},{k:'DEF',x:22,y:64},{k:'DEF',x:78,y:64},{k:'DEL',x:35,y:38},{k:'DEL',x:65,y:38}]
                : total===7
                    ? [{k:'ARQ',x:50,y:90},{k:'DEF',x:25,y:72},{k:'DEF',x:75,y:72},{k:'MED',x:50,y:56},{k:'MED',x:28,y:36},{k:'MED',x:72,y:36},{k:'DEL',x:50,y:20}]
                    : [{k:'ARQ',x:50,y:92},{k:'DEF',x:18,y:76},{k:'DEF',x:40,y:78},{k:'DEF',x:60,y:78},{k:'DEF',x:82,y:76},{k:'MED',x:30,y:52},{k:'MED',x:50,y:54},{k:'MED',x:70,y:52},{k:'DEL',x:28,y:28},{k:'DEL',x:72,y:28},{k:'DEL',x:50,y:18}]);
            assigned = slots.map((s,i)=>members[i]||null);
        }

        // Estado para mover posiciones (owner) + referencia de slots para el drop
        window._cpCtx = { clubId: clubId, slots: slots, assigned: assigned, isOwner: isOwner, clubName: club.name || '' };
        const moving = window._cpMove && String(window._cpMove.clubId) === String(clubId) ? window._cpMove : null;

        const cellHtml = (idx) => {
            const m = assigned[idx];
            const x = slots[idx].x, y = slots[idx].y, slotKey = slots[idx].k;
            if (m) {
                const photo = m.player_photo || '';
                // Aplicar g_face de Cloudinary para que se vea la CARA, no el torso
                const photoUrl = photo && window.avatarUrl ? window.avatarUrl(photo, 92) : photo;
                const isMoving = moving && (moving.email||'').toLowerCase() === (m.player_email||'').toLowerCase();
                const ring = isMoving ? 'border:2px solid #ffaa00;box-shadow:0 0 12px rgba(255,170,0,0.8);' : 'border:2px solid var(--accent);';
                const av = photoUrl
                    ? `<div style="width:46px;height:46px;margin:0 auto;border-radius:50%;${ring}background:#000 center/cover url('${photoUrl}');background-position:center 28%;"></div>`
                    : `<div style="width:46px;height:46px;margin:0 auto;border-radius:50%;background:rgba(186,255,0,0.15);${ring}display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--accent);">${(m.player_name||'?')[0].toUpperCase()}</div>`;
                const click = moving
                    ? `window._cpDropMove(${idx})`
                    : `window._cpPlayerTap('${clubId}','${(m.player_email||'').replace(/'/g,"\\'")}','${(m.player_name||'Jugador').replace(/'/g,'')}',${isOwner?'true':'false'},${idx})`;
                return `<div onclick="${click}" style="position:absolute;left:${x}%;top:${y}%;transform:translate(-50%,-50%);text-align:center;cursor:pointer;width:64px;">
                    ${av}
                    <div style="font-size:9px;font-weight:800;color:#fff;margin-top:3px;max-width:64px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 1px 3px #000;">${(m.player_name||'Jugador').split(' ')[0]}</div>
                    <div style="font-size:8px;color:var(--accent);">${slotKey}${m.role==='capitan'?' C':''}</div>
                </div>`;
            }
            if (moving) {
                return `<div onclick="window._cpDropMove(${idx})" style="position:absolute;left:${x}%;top:${y}%;transform:translate(-50%,-50%);text-align:center;cursor:pointer;width:64px;">
                    <div style="width:46px;height:46px;margin:0 auto;border-radius:50%;background:rgba(255,170,0,0.15);border:2px dashed #ffaa00;display:flex;align-items:center;justify-content:center;color:#ffaa00;font-weight:900;font-size:18px;">↓</div>
                    <div style="font-size:8.5px;color:#ffaa00;margin-top:3px;font-weight:800;">${slotKey}</div>
                </div>`;
            }
            const clickable = !isMember;
            return `<div ${clickable?`onclick="window._requestJoinClubSlot('${clubId}','${(club.name||'').replace(/'/g,'')}',${idx})"`:''} style="position:absolute;left:${x}%;top:${y}%;transform:translate(-50%,-50%);text-align:center;${clickable?'cursor:pointer;':''}width:64px;">
                <div style="width:46px;height:46px;margin:0 auto;border-radius:50%;background:rgba(255,255,255,0.06);border:2px dashed ${clickable?'var(--accent)':'rgba(255,255,255,0.25)'};display:flex;align-items:center;justify-content:center;color:${clickable?'var(--accent)':'#888'};font-weight:900;font-size:${clickable?'22px':'10px'};">${clickable?'+':slotKey}</div>
                <div style="font-size:8.5px;color:${clickable?'var(--accent)':'#888'};margin-top:3px;font-weight:800;">${clickable?'UNIRME':slotKey}</div>
            </div>`;
        };
        let pitchCells = '';
        for (let i=0;i<slots.length;i++) pitchCells += cellHtml(i);
        const filled = members.length;

        // SUPLENTES: miembros de la plantilla que no entraron en la formación
        const assignedEmails = new Set(assigned.filter(Boolean).map(m => (m.player_email||'').toLowerCase()));
        const subs = members.filter(m => !assignedEmails.has((m.player_email||'').toLowerCase()));
        const subsHtml = subs.length ? `
            <div style="font-size:11px;color:#888;font-weight:800;letter-spacing:1px;margin:16px 0 8px;">SUPLENTES (${subs.length})</div>
            <div style="display:flex;flex-direction:column;gap:8px;">
                ${subs.map(m => {
                    const photo = m.player_photo || '';
                    const photoUrl = photo && window.avatarUrl ? window.avatarUrl(photo, 80) : photo;
                    const av = photoUrl
                        ? `<div style="width:40px;height:40px;border-radius:50%;border:2px solid #444;background:#000 center/cover url('${photoUrl}');background-position:center 28%;flex-shrink:0;"></div>`
                        : `<div style="width:40px;height:40px;border-radius:50%;background:#1a1a1a;border:2px solid #444;display:flex;align-items:center;justify-content:center;font-weight:900;color:#888;flex-shrink:0;">${(m.player_name||'?')[0].toUpperCase()}</div>`;
                    return `<div onclick="window._cpPlayerTap('${clubId}','${(m.player_email||'').replace(/'/g,"\\'")}','${(m.player_name||'Jugador').replace(/'/g,'')}',${isOwner?'true':'false'},-1)" style="display:flex;align-items:center;gap:10px;background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:8px 12px;cursor:pointer;">
                        ${av}
                        <div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:800;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${m.player_name||'Jugador'}</div><div style="font-size:10px;color:#666;">${m.position||m.pos||'SUP'}</div></div>
                        <span style="font-size:9px;color:#888;background:rgba(255,255,255,0.05);border:1px solid #2a2a2a;border-radius:10px;padding:3px 8px;font-weight:800;">SUPLENTE</span>
                    </div>`;
                }).join('')}
            </div>` : '';

        // Cancha de fútbol REAL: rayas de césped + áreas + círculo central + punto penal
        content.innerHTML = `
            <div style="font-size:11px;color:#888;font-weight:700;margin-bottom:8px;">PLANTILLA ${filled}/${total} · ${fmtStr.toUpperCase()}${filled<total&&!isMember?' · <span style="color:var(--accent);">tocá un lugar libre para unirte</span>':''}</div>
            ${moving ? `<div style="display:flex;align-items:center;gap:8px;background:rgba(255,170,0,0.1);border:1px solid rgba(255,170,0,0.35);border-radius:12px;padding:8px 12px;margin-bottom:10px;"><i class='bx bx-move' style="color:#ffaa00;font-size:18px;"></i><span style="flex:1;font-size:11.5px;color:#ffd27f;font-weight:700;">Moviendo a <b>${moving.name}</b> — tocá el lugar de destino</span><button onclick="window._cpCancelMove()" style="background:transparent;border:1px solid rgba(255,170,0,0.4);color:#ffaa00;border-radius:10px;padding:5px 10px;font-size:10px;font-weight:800;cursor:pointer;">Cancelar</button></div>` : ''}
            <div style="position:relative;width:100%;max-width:380px;margin:0 auto;aspect-ratio:3/4;background:repeating-linear-gradient(180deg,#0d2c15 0 12%,#0b2712 12% 24%);border:2px solid #1f3a1f;border-radius:16px;overflow:hidden;">
                <!-- Área grande superior -->
                <div style="position:absolute;top:0;left:15%;right:15%;height:14%;border:2px solid rgba(255,255,255,0.22);border-top:none;"></div>
                <!-- Área chica superior -->
                <div style="position:absolute;top:0;left:32%;right:32%;height:6%;border:2px solid rgba(255,255,255,0.18);border-top:none;"></div>
                <!-- Área grande inferior -->
                <div style="position:absolute;bottom:0;left:15%;right:15%;height:14%;border:2px solid rgba(255,255,255,0.22);border-bottom:none;"></div>
                <!-- Área chica inferior -->
                <div style="position:absolute;bottom:0;left:32%;right:32%;height:6%;border:2px solid rgba(255,255,255,0.18);border-bottom:none;"></div>
                <!-- Línea media -->
                <div style="position:absolute;top:50%;left:0;right:0;height:2px;background:rgba(255,255,255,0.22);"></div>
                <!-- Círculo central -->
                <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:78px;height:78px;border:2px solid rgba(255,255,255,0.22);border-radius:50%;"></div>
                <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:6px;height:6px;background:rgba(255,255,255,0.4);border-radius:50%;"></div>
                ${pitchCells}
            </div>
            ${subsHtml}`;
    } else if (tab === 'logros') {
        const CLUB_ACH = [
            { id:'club_created', icon:'🛡️', name:'Club Fundado', desc:'Creaste el club', check:()=>true },
            { id:'club_10members', icon:'👥', name:'Popular', desc:'10+ jugadores en plantilla', rarity:'raro' },
            { id:'club_first_win', icon:'🏆', name:'Primera Victoria', desc:'Primera victoria oficial', rarity:'común' },
            { id:'club_10wins', icon:'💪', name:'Dominante', desc:'10 victorias', rarity:'raro' },
            { id:'club_tournament', icon:'🥇', name:'Campeones', desc:'Ganaron un torneo', rarity:'épico' },
            { id:'club_50followers', icon:'📣', name:'Hinchada', desc:'50 seguidores del club', rarity:'raro' },
            { id:'club_no_goals', icon:'🧤', name:'Muralla', desc:'5 partidos sin goles en contra', rarity:'raro' },
            { id:'club_100matches', icon:'⭐', name:'Institución', desc:'100 partidos jugados', rarity:'épico' },
        ];
        const { data: unlocked } = await sb.from('club_achievements').select('achievement_id').eq('club_id', clubId);
        const unlockedSet = new Set((unlocked||[]).map(a => a.achievement_id));
        const rarityColors = { común:'#888', raro:'#4fc3f7', épico:'#9c88ff', legendario:'#FFD700' };
        content.innerHTML = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(100px,1fr));gap:10px;">
            ${CLUB_ACH.map(a => {
                const got = unlockedSet.has(a.id);
                const rc = rarityColors[a.rarity||'común'];
                return `<div style="background:#111;border:1px solid ${got?rc:'#1e1e1e'};border-radius:12px;padding:12px;text-align:center;opacity:${got?1:0.3};">
                    <div style="font-size:28px;margin-bottom:6px;">${a.icon}</div>
                    <div style="font-size:10px;font-weight:800;color:${got?'#fff':'#555'};">${a.name}</div>
                    <div style="font-size:9px;color:#555;margin-top:2px;">${a.desc}</div>
                </div>`;
            }).join('')}
        </div>`;
    } else if (tab === 'info') {
        const { data: club } = await sb.from('clubs').select('*').eq('id', clubId).maybeSingle();
        if (!club) { content.innerHTML = '<div style="padding:20px;color:#555;text-align:center;">Sin datos.</div>'; return; }
        const genderLabel = club.gender === 'masculino' ? '♂ Masculino' : club.gender === 'femenino' ? '♀ Femenino' : '⚥ Mixto';
        content.innerHTML = `<div style="display:flex;flex-direction:column;gap:10px;">
            ${[
                { label:'FUNDADO', val: club.founded || '—' },
                { label:'CIUDAD', val: club.city || '—' },
                { label:'PAÍS', val: club.nat || 'Uruguay' },
                { label:'ABREVIATURA', val: club.abbrev || '—' },
                { label:'APODO', val: club.nickname || '—' },
                { label:'FORMACIÓN', val: club.formation || '4-3-3' },
                { label:'GÉNERO', val: genderLabel },
            ].map(r => `<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:#111;border:1px solid #1e1e1e;border-radius:10px;">
                <span style="font-size:10px;color:#555;font-weight:900;letter-spacing:1px;">${r.label}</span>
                <span style="font-size:13px;font-weight:700;">${r.val}</span>
            </div>`).join('')}
        </div>`;

    } else if (tab === 'editar') {
        const { data: club } = await sb.from('clubs').select('*').eq('id', clubId).maybeSingle();
        if (!club || !userData || userData.email !== club.owner_email) {
            content.innerHTML = '<div style="padding:20px;color:#f44;text-align:center;">Solo el creador puede editar el club.</div>'; return;
        }
        const genBtns = ['mixto','masculino','femenino'].map(g =>
            `<div class="type-btn${(club.gender||'mixto')===g?' active':''}" data-gender="${g}" onclick="this.parentElement.querySelectorAll('.type-btn').forEach(b=>b.classList.remove('active'));this.classList.add('active');" style="flex:1;text-align:center;padding:8px 0;font-size:12px;cursor:pointer;">${g==='mixto'?'⚥ Mixto':g==='masculino'?'♂ Masculino':'♀ Femenino'}</div>`
        ).join('');
        content.innerHTML = `<div style="display:flex;flex-direction:column;gap:12px;">
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">NOMBRE DEL CLUB</label>
                <input id="edit-club-name" type="text" value="${(club.name||'').replace(/"/g,'&quot;')}" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:14px;font-weight:700;box-sizing:border-box;"></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">APODO</label>
                <input id="edit-club-nickname" type="text" value="${(club.nickname||'').replace(/"/g,'&quot;')}" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;box-sizing:border-box;"></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">ABREVIATURA (máx 4 letras)</label>
                <input id="edit-club-abbrev" type="text" maxlength="4" value="${(club.abbrev||'').replace(/"/g,'&quot;')}" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;box-sizing:border-box;"></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">CIUDAD</label>
                <input id="edit-club-city" type="text" value="${(club.city||'').replace(/"/g,'&quot;')}" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;box-sizing:border-box;"></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">DESCRIPCIÓN</label>
                <textarea id="edit-club-bio" rows="3" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;resize:none;box-sizing:border-box;font-family:inherit;">${club.bio||''}</textarea></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:6px;">GÉNERO DEL EQUIPO</label>
                <div class="type-selector" id="edit-club-gender-sel" style="display:flex;gap:6px;">${genBtns}</div></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">TIPO DE CLUB</label>
                <select id="edit-club-modality" onchange="window._repopClubFormations(this.value)" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;font-family:inherit;">
                    ${(function(){
                        var mod = (club.modality||'F5').toUpperCase(); if (mod.includes('11')) mod='F11'; else if (mod.includes('7')) mod='F7'; else if (mod.includes('5')) mod='F5';
                        return [['F5','Fútbol 5'],['F7','Fútbol 7'],['F11','Fútbol 11']].map(function(o){return '<option value="'+o[0]+'"'+(mod===o[0]?' selected':'')+'>'+o[1]+'</option>';}).join('');
                    })()}
                </select></div>
            <div><label style="font-size:10px;color:#555;font-weight:700;letter-spacing:1px;display:block;margin-bottom:4px;">FORMACIÓN</label>
                <select id="edit-club-formation" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;font-family:inherit;">
                    ${(function(){
                        var mod = (club.modality||'').toUpperCase();
                        var F = window.FORMATIONS || {};
                        var opts;
                        if (mod.includes('5') || mod === 'F5') opts = F['F5'] || ['1-2-1','2-2','1-1-2','1-3'];
                        else if (mod.includes('7') || mod === 'F7') opts = F['F7'] || ['2-3-1','3-2-1','2-2-2','1-4-1'];
                        else opts = F['F11'] || ['4-3-3','4-4-2','3-5-2','4-2-3-1','5-3-2'];
                        return opts.map(f=>'<option value="'+f+'"'+((club.formation||opts[0])===f?' selected':'')+'>'+f+'</option>').join('');
                    })()}
                </select></div>
            <button onclick="window._saveClubEdit('${clubId}')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:14px;font-weight:900;font-size:15px;cursor:pointer;">GUARDAR CAMBIOS</button>
        </div>`;

    } else if (tab === 'escudo') {
        // C8: sin generador de escudo por IA — solo subir imagen del escudo.
        content.innerHTML = `<div style="display:flex;flex-direction:column;gap:12px;">
            <p style="font-size:13px;color:#aaa;margin:0;">Subí la imagen del escudo de tu club. Fondo negro recomendado, formato cuadrado.</p>
            <div style="border:2px dashed #333;border-radius:12px;padding:22px 16px;text-align:center;">
                <input type="file" id="escudo-direct-upload" accept="image/*" style="display:none;" onchange="window._previewAndSaveEscudo(this,'${clubId}')">
                <button onclick="document.getElementById('escudo-direct-upload').click()" style="background:#1a1a1a;color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:12px 22px;font-weight:900;cursor:pointer;display:inline-flex;align-items:center;gap:8px;"><i class='bx bx-upload'></i> SUBIR IMAGEN DEL ESCUDO</button>
                <div id="escudo-upload-preview" style="margin-top:12px;"></div>
            </div>
        </div>`;
    }
};

// ── Cancha del perfil del club: tap en jugador + mover de posición ─────────
window._cpMove = null;
window._cpPlayerTap = function(clubId, email, name, canManage, slotIdx){
    // Sin permisos de gestión → directo al perfil PÚBLICO del jugador
    // (forcePublic evita el self-redirect que abría el perfil del equipo)
    if (!canManage) { if (email && window.viewUserProfile) window.viewUserProfile(email, true); return; }
    const ex = document.getElementById('cp-player-sheet'); if (ex) ex.remove();
    const sheet = document.createElement('div');
    sheet.id = 'cp-player-sheet';
    sheet.style.cssText = 'position:fixed;inset:0;z-index:21500;background:rgba(0,0,0,0.7);display:flex;align-items:flex-end;justify-content:center;';
    sheet.onclick = function(e){ if (e.target === sheet) sheet.remove(); };
    sheet.innerHTML = `<div style="background:#111;border:1px solid #2a2a2a;border-radius:20px 20px 0 0;width:100%;max-width:480px;padding:18px 16px calc(22px + env(safe-area-inset-bottom));">
        <div style="font-size:14px;font-weight:900;color:#fff;margin-bottom:14px;">${name}</div>
        <button onclick="document.getElementById('cp-player-sheet').remove();window.viewUserProfile&&window.viewUserProfile('${(email||'').replace(/'/g,"\\'")}', true)" style="display:flex;align-items:center;gap:10px;width:100%;background:rgba(255,255,255,0.05);border:1px solid #2a2a2a;color:#fff;border-radius:12px;padding:13px 14px;font-size:13px;font-weight:800;cursor:pointer;margin-bottom:8px;"><i class='bx bx-user' style="font-size:18px;color:var(--accent);"></i> Ver perfil del jugador</button>
        <button onclick="document.getElementById('cp-player-sheet').remove();window._cpStartMove('${clubId}','${(email||'').replace(/'/g,"\\'")}','${(name||'').replace(/'/g,'')}')" style="display:flex;align-items:center;gap:10px;width:100%;background:rgba(255,170,0,0.08);border:1px solid rgba(255,170,0,0.3);color:#ffaa00;border-radius:12px;padding:13px 14px;font-size:13px;font-weight:800;cursor:pointer;margin-bottom:8px;"><i class='bx bx-move' style="font-size:18px;"></i> Cambiar de posición</button>
        <button onclick="document.getElementById('cp-player-sheet').remove()" style="width:100%;background:transparent;border:none;color:#777;padding:10px;font-size:12px;cursor:pointer;">Cancelar</button>
    </div>`;
    document.body.appendChild(sheet);
};
window._cpStartMove = function(clubId, email, name){
    window._cpMove = { clubId: clubId, email: email, name: name };
    window._clubProfileTab('jugadores', clubId, document.querySelector(`#club-profile-tabs .cp-tab[onclick*="'jugadores'"]`));
    showToast && showToast('Tocá el lugar de la cancha donde lo querés poner.', 'info', 3000);
};
window._cpCancelMove = function(){
    const mv = window._cpMove; window._cpMove = null;
    if (mv) window._clubProfileTab('jugadores', mv.clubId, document.querySelector(`#club-profile-tabs .cp-tab[onclick*="'jugadores'"]`));
};
window._cpDropMove = async function(slotIdx){
    const mv = window._cpMove; const ctx = window._cpCtx;
    if (!mv || !ctx || !ctx.slots || !ctx.slots[slotIdx]) { window._cpMove = null; return; }
    const sb = window._sb; if (!sb) return;
    const targetKey = ctx.slots[slotIdx].k;
    const target = ctx.assigned ? ctx.assigned[slotIdx] : null;
    const movingEmail = (mv.email||'').toLowerCase();
    try {
        // Posición actual del que se mueve (para el intercambio)
        let oldPos = null;
        try {
            const { data: cur } = await sb.from('club_members').select('id,position').eq('club_id', mv.clubId).eq('player_email', mv.email).limit(1);
            if (cur && cur.length) oldPos = cur[0].position;
        } catch(e){}
        // Actualizar (o crear la fila si es el dueño sin fila propia en club_members)
        const { data: upd } = await sb.from('club_members').update({ position: targetKey }).eq('club_id', mv.clubId).eq('player_email', mv.email).select();
        if (!upd || !upd.length) {
            await sb.from('club_members').insert({ club_id: mv.clubId, player_email: mv.email, player_name: mv.name || mv.email, position: targetKey, role: 'capitan', status: 'activo' });
        }
        // Si el destino estaba ocupado por otro jugador → intercambio de posiciones
        if (target && (target.player_email||'').toLowerCase() !== movingEmail) {
            await sb.from('club_members').update({ position: oldPos || target.position || 'MED' }).eq('club_id', mv.clubId).eq('player_email', target.player_email);
        }
        showToast && showToast(mv.name + ' ahora juega de ' + targetKey + '.', 'success');
    } catch(e) { showToast && showToast('No se pudo mover: ' + (e.message||''), 'error'); }
    window._cpMove = null;
    window._clubProfileTab('jugadores', mv.clubId, document.querySelector(`#club-profile-tabs .cp-tab[onclick*="'jugadores'"]`));
};

// Guardar edición del club
// C7: al cambiar el tipo de club (F5/F7/F11) repoblar las formaciones válidas.
window._repopClubFormations = function(mod){
    var sel = document.getElementById('edit-club-formation');
    if (!sel) return;
    var F = window.FORMATIONS || {};
    var opts = (mod === 'F11') ? (F['F11'] || ['4-3-3','4-4-2','3-5-2','4-2-3-1','5-3-2'])
             : (mod === 'F7') ? (F['F7'] || ['2-3-1','3-2-1','2-2-2','1-4-1'])
             : (F['F5'] || ['1-2-1','2-2','1-1-2','1-3']);
    sel.innerHTML = opts.map(function(f){ return '<option value="'+f+'">'+f+'</option>'; }).join('');
};
window._saveClubEdit = async function(clubId) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) return;
    const name = document.getElementById('edit-club-name')?.value?.trim();
    if (!name) { showToast && showToast('El nombre es obligatorio', 'error'); return; }
    const activeG = document.querySelector('#edit-club-gender-sel .type-btn.active');
    const updates = {
        name,
        nickname: document.getElementById('edit-club-nickname')?.value?.trim() || null,
        abbrev: document.getElementById('edit-club-abbrev')?.value?.trim() || null,
        city: document.getElementById('edit-club-city')?.value?.trim() || null,
        bio: document.getElementById('edit-club-bio')?.value?.trim() || null,
        gender: activeG?.dataset?.gender || 'mixto',
        formation: document.getElementById('edit-club-formation')?.value || '4-3-3',
    };
    // C7: permitir cambiar el TIPO de club (F5/F7/F11) después de creado.
    var _modSel = document.getElementById('edit-club-modality');
    if (_modSel && _modSel.value) updates.modality = _modSel.value;
    try {
        // Permitir editar al owner O al capitán. Supabase no lanza excepción: hay que leer {error}.
        const { error, data } = await sb.from('clubs').update(updates).eq('id', clubId).select();
        if (error) { showToast && showToast('Error al guardar: ' + error.message, 'error'); return; }
        if (!data || !data.length) {
            // Update no afectó filas (posible permiso): reintentar restringido al owner por compatibilidad
            const retry = await sb.from('clubs').update(updates).eq('id', clubId).eq('owner_email', me.email).select();
            if (retry.error || !retry.data || !retry.data.length) {
                showToast && showToast('No se pudo guardar. ¿Sos el creador o capitán del club?', 'error');
                return;
            }
        }
        // Sincronizar cache local
        try {
            const local = JSON.parse(localStorage.getItem('canchero_mis_clubes') || '[]');
            const idx = local.findIndex(c => String(c.id) === String(clubId));
            if (idx >= 0) { local[idx] = { ...local[idx], ...updates }; localStorage.setItem('canchero_mis_clubes', JSON.stringify(local)); }
        } catch(e) {}
        showToast && showToast('¡Club actualizado!', 'success');
        setTimeout(() => window.viewClubProfile && window.viewClubProfile(clubId), 400);
    } catch(e) { showToast && showToast('Error al guardar: ' + e.message, 'error'); }
};

// Preview y guardar escudo subido directamente
window._previewAndSaveEscudo = async function(input, clubId) {
    const file = input.files[0];
    if (!file) return;
    const preview = document.getElementById('escudo-upload-preview');
    const reader = new FileReader();
    reader.onload = async (e) => {
        if (preview) preview.innerHTML = `
            <img src="${e.target.result}" style="width:80px;height:80px;border-radius:50%;object-fit:cover;border:3px solid var(--accent);margin-bottom:10px;">
            <br><button onclick="window._uploadEscudoFile(${JSON.stringify(clubId)})" style="background:var(--accent);color:#000;border:none;border-radius:10px;padding:8px 20px;font-weight:900;font-size:12px;cursor:pointer;">✅ GUARDAR ESCUDO</button>`;
        window._escudoFile = file;
        window.currentEditingClubId = clubId;
    };
    reader.readAsDataURL(file);
};

window._uploadEscudoFile = async function(clubId) {
    const sb = window._sb;
    const file = window._escudoFile;
    if (!sb || !file || !clubId) return;
    try {
        const ext = file.name.split('.').pop() || 'jpg';
        const path = `clubs/${clubId}/logo_${Date.now()}.${ext}`;
        const { error: upErr } = await sb.storage.from('media').upload(path, file, { upsert: true });
        if (upErr) {
            // Fallback: intentar con bucket photos
            const { error: upErr2 } = await sb.storage.from('photos').upload(path, file, { upsert: true });
            if (upErr2) throw upErr2;
            const { data: { publicUrl } } = sb.storage.from('photos').getPublicUrl(path);
            await sb.from('clubs').update({ logo_url: publicUrl, logo: publicUrl }).eq('id', clubId);
        } else {
            const { data: { publicUrl } } = sb.storage.from('media').getPublicUrl(path);
            await sb.from('clubs').update({ logo_url: publicUrl, logo: publicUrl }).eq('id', clubId);
        }
        showToast && showToast('¡Escudo guardado!', 'success');
        document.querySelectorAll(`[data-club-shield="${clubId}"], [data-club-id="${clubId}"]`).forEach(img => {
            if (img.src !== undefined) img.src = window.URL.createObjectURL(file);
        });
        try {
            const local = JSON.parse(localStorage.getItem('canchero_mis_clubes') || '[]');
            const idx = local.findIndex(c => String(c.id) === String(clubId));
            if (idx >= 0) { local[idx].logo = local[idx].logo_url = window._lastEscudoUrl || local[idx].logo; localStorage.setItem('canchero_mis_clubes', JSON.stringify(local)); }
        } catch(e) {}
    } catch(e) {
        // Fallback: si el storage de Supabase falla (bucket/RLS), guardar el escudo como base64 directo
        try {
            const dataUrl = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(file); });
            const { error: dbErr } = await sb.from('clubs').update({ logo_url: dataUrl, logo: dataUrl }).eq('id', clubId).select();
            if (dbErr) throw dbErr;
            try {
                const local = JSON.parse(localStorage.getItem('canchero_mis_clubes') || '[]');
                const idx = local.findIndex(c => String(c.id) === String(clubId));
                if (idx >= 0) { local[idx].logo = local[idx].logo_url = dataUrl; localStorage.setItem('canchero_mis_clubes', JSON.stringify(local)); }
            } catch(_) {}
            showToast && showToast('¡Escudo guardado!', 'success');
            document.querySelectorAll(`[data-club-shield="${clubId}"], [data-club-id="${clubId}"]`).forEach(img => { if (img.src !== undefined) img.src = dataUrl; });
        } catch(e2) {
            showToast && showToast('Error al guardar escudo: ' + (e2.message || e.message), 'error');
        }
    }
};

// Abrir editor de escudo desde el perfil del club
