window._openAddPlayerModal = function(clubId) {
    const existing = document.getElementById('add-player-modal');
    if (existing) existing.remove();
    const m = document.createElement('div');
    m.id = 'add-player-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:10001;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:18px;';
    m.innerHTML = `
        <div style="background:#0f0f0f;border:1px solid #222;border-radius:20px;width:100%;max-width:520px;max-height:80vh;overflow-y:auto;padding:20px;box-sizing:border-box;padding-bottom:calc(20px + env(safe-area-inset-bottom));">
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">
                <div style="font-size:16px;font-weight:900;"><i class='bx bx-user-plus' style="color:var(--accent);"></i> Agregar Jugador</div>
                <button onclick="document.getElementById('add-player-modal').remove()" style="background:none;border:none;color:#888;font-size:22px;cursor:pointer;">&times;</button>
            </div>
            <div style="display:flex;gap:8px;margin-bottom:12px;">
                <div style="flex:1;display:flex;align-items:center;gap:8px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:8px 12px;">
                    <i class='bx bx-search' style="color:#555;"></i>
                    <input id="add-player-search" type="text" placeholder="Buscá por nombre o email..." style="background:none;border:none;color:#fff;width:100%;outline:none;font-size:13px;" oninput="window._searchPlayersToAdd(this.value,'${clubId}')">
                </div>
            </div>
            <div id="add-player-results" style="min-height:100px;">
                <div style="text-align:center;padding:20px;color:#555;font-size:12px;">Buscá un jugador por nombre o email para agregarlo a tu club.</div>
            </div>
        </div>`;
    m.addEventListener('click', e => { if (e.target === m) m.remove(); });
    document.body.appendChild(m);
    setTimeout(() => document.getElementById('add-player-search')?.focus(), 100);
};

window._searchPlayersToAdd = async function(query, clubId) {
    const results = document.getElementById('add-player-results');
    if (!results) return;
    if (!query || query.length < 2) {
        results.innerHTML = '<div style="text-align:center;padding:20px;color:#555;font-size:12px;">Ingresá al menos 2 caracteres.</div>';
        return;
    }
    const sb = window._sb;
    if (!sb) return;
    results.innerHTML = '<div style="text-align:center;padding:16px;color:#555;"><i class="bx bx-loader-alt bx-spin"></i></div>';
    try {
        // Buscar en users. Select robusto: si falla por columna inexistente, reintentar simple.
        const sbQ = sb;
        let { data: users, error: usersErr } = await sbQ.from('users').select('email,name,pos,photo').or(`name.ilike.%${query}%,email.ilike.%${query}%`).limit(15);
        if (usersErr) {
            const r = await sbQ.from('users').select('email,name,photo').or(`name.ilike.%${query}%,email.ilike.%${query}%`).limit(15);
            users = r.data; usersErr = r.error;
        }
        if (usersErr) { results.innerHTML = '<div style="text-align:center;padding:20px;color:#f66;font-size:12px;">Error al buscar: '+(usersErr.message||'')+'</div>'; return; }
        // Normalizar campos
        users = (users || []).map(u => ({ ...u, position: u.position || u.pos || 'JUG', photo: u.photo || u.avatar_url || '' }));
        // Filtrar los que ya son miembros (tolerante a errores)
        let existing = [];
        try { const r = await sb.from('club_members').select('player_email').eq('club_id', clubId); existing = r.data || []; } catch(e){}
        const existingEmails = new Set((existing||[]).map(m => m.player_email));
        const filtered = (users||[]).filter(u => !existingEmails.has(u.email));
        if (!filtered.length) {
            results.innerHTML = '<div style="text-align:center;padding:20px;color:#555;font-size:12px;">Sin resultados o todos ya son miembros.</div>';
            return;
        }
        results.innerHTML = filtered.map(u => `
            <div style="display:flex;align-items:center;gap:10px;padding:10px;border:1px solid #1e1e1e;border-radius:12px;margin-bottom:8px;cursor:pointer;" onclick="window._addPlayerToClub('${clubId}','${u.email}','${(u.name||u.email).replace(/'/g,"\\'")}','${u.position||'JUG'}','${u.photo||''}')" onmouseover="this.style.background='rgba(186,255,0,0.05)'" onmouseout="this.style.background='transparent'">
                ${u.photo ? `<img src="${u.photo}" style="width:38px;height:38px;border-radius:50%;object-fit:cover;border:2px solid #333;">` : `<div style="width:38px;height:38px;border-radius:50%;background:#1a1a1a;border:2px solid #333;display:flex;align-items:center;justify-content:center;font-weight:900;color:#555;">${(u.name||u.email||'?')[0].toUpperCase()}</div>`}
                <div style="flex:1;">
                    <div style="font-weight:700;font-size:13px;">${u.name || u.email}</div>
                    <div style="font-size:10px;color:#555;">${u.position || 'Sin posición'} · ${u.email}</div>
                </div>
                <button style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:900;cursor:pointer;">+ AGREGAR</button>
            </div>`).join('');
    } catch(e) {
        results.innerHTML = `<div style="padding:16px;color:#f44;text-align:center;font-size:12px;">Error: ${e.message}</div>`;
    }
};

window._addPlayerToClub = async function(clubId, email, name, position, photo) {
    const sb = window._sb;
    if (!sb || !clubId || !email) return;
    try {
        const { error } = await sb.from('club_members').insert({
            club_id: clubId,
            player_email: email,
            player_name: name,
            position: position,
            player_photo: photo || null,
            role: 'jugador',
            status: 'activo',
            joined_at: new Date().toISOString()
        });
        if (error) throw error;
        showToast && showToast(`${name} agregado al club ✓`, 'success');
        // Actualizar resultados: quitar el elemento clickeado
        document.getElementById('add-player-modal')?.remove();
        window._loadClubPlanilla(clubId);
    } catch(e) {
        showToast && showToast('Error al agregar: ' + e.message, 'error');
    }
};

window._removePlayerFromClub = async function(memberId, name, clubId) {
    if (!confirm(`¿Quitar a ${name} del club?`)) return;
    const sb = window._sb;
    if (!sb) return;
    try {
        const { data: del, error } = await sb.from('club_members').delete().eq('id', memberId).select('id');
        if (error) throw error;
        if (!del || !del.length) { showToast && showToast('No se pudo quitar (solo el capitán/dueño puede).', 'error'); return; }
        showToast && showToast(`${name} quitado del club`, 'success');
        window._loadClubPlanilla(clubId);
        try { localStorage.removeItem('canchero_club_roster'); } catch(e){}
    } catch(e) {
        showToast && showToast('Error: ' + e.message, 'error');
    }
};

// ============================================================
// EXPORTAR PLANILLA PDF (via print)
// ============================================================
window._exportPlanillaPDF = async function(clubId) {
    const sb = window._sb;
    if (!sb || !clubId) { showToast && showToast('No se puede exportar ahora', 'error'); return; }
    try {
        const { data: club } = await sb.from('clubs').select('name,city,modality').eq('id', clubId).maybeSingle();
        const { data: members } = await sb.from('club_members').select('*').eq('club_id', clubId).neq('status','pendiente');
        const clubName = club?.name || 'Mi Equipo';
        const rows = (members||[]).map((m, i) => `
            <tr>
                <td>${m.number || i+1}</td>
                <td>${m.player_name || m.player_email || '-'}</td>
                <td>${(m.position || '-').toUpperCase()}</td>
                <td>${m.goals || 0}</td>
                <td>${m.assists || 0}</td>
                <td>${m.matches_played || 0}</td>
                <td>${m.role === 'capitan' ? '★ Capitán' : m.role === 'capitan2' ? '☆ Cap2' : 'Jugador'}</td>
                <td>${m.status === 'lesionado' ? 'Lesionado' : m.status === 'suspendido' ? 'Suspendido' : 'Activo'}</td>
            </tr>`).join('');
        const win = window.open('', '_blank', 'width=800,height=600');
        win.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Planilla ${clubName}</title>
            <style>
                body { font-family: Arial, sans-serif; margin: 20px; color: #000; }
                h1 { font-size: 22px; margin-bottom: 4px; }
                .sub { color: #666; font-size: 13px; margin-bottom: 16px; }
                table { width: 100%; border-collapse: collapse; font-size: 13px; }
                th { background: #1a1a1a; color: #fff; padding: 8px 10px; text-align: left; border: 1px solid #333; }
                td { padding: 7px 10px; border: 1px solid #ddd; }
                tr:nth-child(even) { background: #f5f5f5; }
                .footer { margin-top: 20px; font-size: 11px; color: #999; }
                @media print { button { display: none; } }
            </style></head><body>
            <div style="display:flex;align-items:center;gap:14px;margin-bottom:8px;">
                <div style="width:52px;height:52px;background:#1a1a1a;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:24px;">⚽</div>
                <div><h1>${clubName}</h1><div class="sub">${club?.city || ''} · ${club?.modality || 'Fútbol'} · Generado ${new Date().toLocaleDateString('es-UY')}</div></div>
            </div>
            <table>
                <thead><tr><th>#</th><th>JUGADOR</th><th>POS</th><th>G</th><th>A</th><th>PJ</th><th>ROL</th><th>ESTADO</th></tr></thead>
                <tbody>${rows || '<tr><td colspan="8" style="text-align:center;padding:20px;color:#999;">Sin jugadores en la planilla</td></tr>'}</tbody>
            </table>
            <div class="footer">CANCHERO — planilla generada automáticamente · ${(members||[]).length} jugadores</div>
            <br><button onclick="window.print()" style="padding:8px 18px;background:#000;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:13px;">🖨️ Imprimir / Guardar PDF</button>
        </body></html>`);
        win.document.close();
    } catch(e) {
        showToast && showToast('Error al exportar: ' + e.message, 'error');
    }
};

// Rellena el header de gestión con el escudo y nombre del club en edición
window._fillClubGestionHeader = async function() {
    const nombreEl = document.getElementById('club-gestion-nombre');
    const escudoEl = document.getElementById('club-gestion-escudo');
    const subEl = document.getElementById('club-gestion-sub');
    if (!nombreEl) return;
    const clubId = window.currentEditingClubId;
    let club = null;
    // Buscar en cache local primero
    try {
        const local = JSON.parse(localStorage.getItem('canchero_mis_clubes') || '[]');
        club = local.find(c => String(c.id) === String(clubId)) || local[0];
    } catch(e){}
    // Si hay conexión, traer datos frescos
    const sb = window._sb;
    if (sb && clubId) {
        try { const { data } = await sb.from('clubs').select('name,logo,logo_url,city,nat,modality').eq('id', clubId).maybeSingle(); if (data) club = data; } catch(e){}
    }
    if (!club) return;
    nombreEl.textContent = (club.name || 'Mi Equipo').toUpperCase();
    if (subEl) subEl.textContent = [club.city, club.nat, club.modality].filter(Boolean).join(' · ') || 'Gestión del club';
    const logo = club.logo_url || club.logo;
    if (escudoEl) {
        escudoEl.innerHTML = logo
            ? `<img src="${logo}" style="width:100%;height:100%;object-fit:cover;">`
            : `<i class='bx bxs-shield' style="color:var(--accent); font-size:28px;"></i>`;
    }
};

