// RESERVAS DEL COMPLEJO (mock)
// ============================================================
window.renderComplexReservations = function() {
    const container = document.getElementById('reservas-list') || document.querySelector('#club-reservas .panel');
    if (!container) return;
    const reservas = JSON.parse(localStorage.getItem('canchero_reservations') || '[]');
    if (!reservas.length) {
        container.innerHTML = `<div style="text-align:center;padding:40px 20px;color:#666;">
            <i class='bx bx-calendar-x' style="font-size:42px;display:block;margin-bottom:10px;opacity:0.4;"></i>
            <div style="font-size:13px;">No tenés reservas todavía.</div>
            <div style="font-size:11px;margin-top:4px;">Cuando los jugadores reserven una cancha, aparecerán acá.</div>
        </div>`;
        return;
    }
    container.innerHTML = reservas.map(r => `
        <div style="display:flex;align-items:center;gap:15px;padding:15px;background:rgba(255,255,255,0.03);border:1px solid var(--border-color);border-radius:10px;margin-bottom:10px;flex-wrap:wrap;">
            <div style="flex:1;min-width:200px;">
                <div style="font-weight:700;font-size:14px;">${r.jugador}</div>
                <div style="font-size:12px;color:#888;margin-top:3px;"><i class='bx bx-map-pin'></i> ${r.cancha}</div>
                <div style="font-size:12px;color:#888;"><i class='bx bx-time'></i> ${r.fecha} · ${r.hora}</div>
            </div>
            <div style="text-align:center;">
                <div style="font-size:18px;font-weight:900;color:var(--accent);">${r.precio}</div>
                <div style="font-size:10px;color:#666;">por hora</div>
            </div>
            <div style="display:flex;gap:8px;flex-wrap:wrap;">
                ${r.estado === 'pendiente' ? `
                    <button class="btn btn-primary btn-sm" onclick="confirmReserva(this, '${r.jugador}')"><i class='bx bx-check'></i> CONFIRMAR</button>
                    <button class="btn btn-outline btn-sm" style="color:#ff4d4d;border-color:#ff4d4d;" onclick="this.closest('div[style]').remove()"><i class='bx bx-x'></i> RECHAZAR</button>
                ` : `<span style="color:var(--accent);font-weight:700;font-size:12px;"><i class='bx bx-check-circle'></i> CONFIRMADA</span>`}
            </div>
        </div>
    `).join('') || '<p style="color:#666;text-align:center;padding:30px;">No hay reservas pendientes.</p>';
};

window.confirmReserva = function(btn, nombre) {
    const row = btn.closest('div[style]');
    row.querySelector('div:last-child').innerHTML = `<span style="color:var(--accent);font-weight:700;font-size:12px;"><i class='bx bx-check-circle'></i> CONFIRMADA</span>`;
    alert(`Reserva de ${nombre} confirmada.`);
};

