// ============================================================
// TÁCTICAS DEL CLUB
// ============================================================

// ============================================================
// CLUB TACTICS & CANVAS DRAWING
// ============================================================
window.FORMATIONS = {
    'F5': ['1-2-1', '2-2', '1-1-2', '1-3'],
    'F7': ['2-3-1', '3-2-1', '2-2-2', '1-4-1'],
    'F11': ['4-3-3', '4-4-2', '3-5-2', '4-2-3-1', '5-3-2']
};

// Helper: obtener slots totales según modalidad
window.getSlotsForModality = function(modality) {
    var m = (modality || '').toString().toLowerCase();
    if (m.includes('5') || m === 'f5') return 10;
    if (m.includes('7') || m === 'f7') return 14;
    return 22; // F11 default
};

let tacCanvas, tacCtx;
let isDrawing = false, tacMode = 'move';
let tacColor = '#baff00';
let players = [];
let drawnLines = [];

function initTactics() {
    tacCanvas = document.getElementById('tactic-canvas');
    if(!tacCanvas) return;
    tacCtx = tacCanvas.getContext('2d');
    
    // Resize handling
    const container = document.getElementById('club-tactic-board-container');
    if(container) {
        tacCanvas.width = container.clientWidth || 600;
        tacCanvas.height = container.clientHeight || 400;
    }

    tacCanvas.addEventListener('mousedown', startTacEvent);
    tacCanvas.addEventListener('mousemove', moveTacEvent);
    tacCanvas.addEventListener('mouseup', stopTacEvent);
    tacCanvas.addEventListener('mouseleave', stopTacEvent);
    tacCanvas.addEventListener('touchstart', (e) => { e.preventDefault(); startTacEvent(e.touches[0]); }, {passive: false});
    tacCanvas.addEventListener('touchmove', (e) => { e.preventDefault(); moveTacEvent(e.touches[0]); }, {passive: false});
    tacCanvas.addEventListener('touchend', stopTacEvent);
}

function getTacPos(e) {
    const rect = tacCanvas.getBoundingClientRect();
    const scaleX = tacCanvas.width / rect.width;
    const scaleY = tacCanvas.height / rect.height;
    return {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top) * scaleY
    };
}

let draggedPlayer = null;

function startTacEvent(e) {
    const pos = getTacPos(e);
    if(tacMode === 'move') {
        const hit = players.find(p => Math.hypot(p.x - pos.x, p.y - pos.y) < 15);
        if(hit) draggedPlayer = hit;
    } else if(tacMode === 'draw' || tacMode === 'erase') {
        isDrawing = true;
        if(tacMode === 'draw') {
            drawnLines.push({ color: tacColor, points: [{x: pos.x, y: pos.y}] });
        }
    }
}

function moveTacEvent(e) {
    const pos = getTacPos(e);
    if(isDrawing && tacMode === 'draw') {
        drawnLines[drawnLines.length - 1].points.push({x: pos.x, y: pos.y});
        renderTacBoard();
    } else if(isDrawing && tacMode === 'erase') {
        drawnLines = drawnLines.filter(line => {
            return !line.points.some(pt => Math.hypot(pt.x - pos.x, pt.y - pos.y) < 20);
        });
        renderTacBoard();
    }
}

function stopTacEvent() {
    isDrawing = false;
}

window.renderTacBoard = function() {
    if(!tacCtx) return;
    tacCtx.clearRect(0, 0, tacCanvas.width, tacCanvas.height);
    
    // Draw lines
    drawnLines.forEach(line => {
        if(line.points.length < 2) return;
        tacCtx.beginPath();
        tacCtx.moveTo(line.points[0].x, line.points[0].y);
        for(let i=1; i<line.points.length; i++) {
            tacCtx.lineTo(line.points[i].x, line.points[i].y);
        }
        tacCtx.strokeStyle = line.color;
        tacCtx.lineWidth = 4;
        tacCtx.lineCap = 'round';
        tacCtx.lineJoin = 'round';
        tacCtx.stroke();
    });
    
    // Render players as HTML squad badges inside tactic-players-container!
    const container = document.getElementById('tactic-players-container');
    if (container) {
        container.innerHTML = '';
        players.forEach((p, idx) => {
            const badge = document.createElement('div');
            badge.className = 'tactic-player-badge';
            badge.style.position = 'absolute';
            badge.style.left = `${(p.x / tacCanvas.width) * 100}%`;
            badge.style.top = `${(p.y / tacCanvas.height) * 100}%`;
            badge.style.transform = 'translate(-50%, -50%)';
            badge.style.pointerEvents = 'auto'; // LET DRAGGING WORK!
            badge.style.cursor = 'grab';
            badge.style.display = 'flex';
            badge.style.flexDirection = 'column';
            badge.style.alignItems = 'center';
            badge.style.zIndex = '10';
            
            const glowColor = p.gk ? '#ff4d4d' : (p.isMe ? '#00e676' : 'var(--accent)');
            const initials = p.name ? p.name.split(' ').map(x => x[0]).join('').substring(0, 2).toUpperCase() : (idx + 1);
            // Insignia de capitán: 1 = primer capitán (C), 2 = segundo capitán (C2)
            const capBadge = p.captain
                ? `<div style="position:absolute;top:-4px;right:-4px;background:${p.captain===1?'#FFD700':'#c0c0c0'};color:#000;font-size:8px;font-weight:900;width:16px;height:16px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:1.5px solid #000;z-index:2;font-family:var(--font-display);">${p.captain===1?'C':'C2'}</div>`
                : '';
            const meRing = p.isMe ? 'box-shadow: 0 0 14px #00e676, 0 0 0 2px #00e676;' : `box-shadow: 0 0 10px ${glowColor};`;

            // MISMO encuadre que toda la app (photoStyle del jugador o rostro center 25%)
            const _photoBg = p.photo
                ? ((window._avatarBgCss && window._avatarBgCss({ photo: p.photo, photo_style: p.photoStyle })) || `background-image:url('${p.photo}');background-size:cover;background-position:center 25%;`)
                : 'background:#000;';
            badge.innerHTML = `
                <div class="fut-avatar" style="
                    position: relative;
                    width: 42px;
                    height: 42px;
                    border-radius: 50%;
                    ${_photoBg}
                    border: 2px solid ${glowColor};
                    ${meRing}
                    display: flex;
                      align-items: center;
                      justify-content: center;
                      font-weight: 900;
                      color: #fff;
                      font-size: 14px;
                      font-family: var(--font-display);
                      transition: transform 0.2s;
                ">
                    ${p.photo ? '' : initials}
                    ${capBadge}
                </div>
                <div style="
                    background: rgba(0, 0, 0, 0.85); 
                    color: #fff; 
                    font-size: 9px; 
                    font-weight: bold; 
                    padding: 2px 6px; 
                    border-radius: 4px; 
                    margin-top: 4px; 
                    white-space: nowrap; 
                    border: 1px solid rgba(255,255,255,0.1);
                    font-family: var(--font-display);
                    letter-spacing: 0.5px;
                ">
                    ${p.name ? p.name.split(' ')[0] : 'Jugador'} <span style="color:${glowColor};">${p.pos || 'JUG'}</span>${(p.nat && window.countryFlag) ? (' ' + (window.countryFlag(p.nat, 9)||'')) : ''}
                </div>
            `;
            
            let isDraggingPlayer = false;
            
            const startDrag = (e) => {
                if (tacMode !== 'move') return;
                isDraggingPlayer = true;
                badge.style.cursor = 'grabbing';
                const av = badge.querySelector('.fut-avatar');
                if(av) av.style.transform = 'scale(1.15)';
                e.stopPropagation();
            };
            
            const moveDrag = (e) => {
                if (!isDraggingPlayer) return;
                const rect = tacCanvas.getBoundingClientRect();
                const clientX = e.touches ? e.touches[0].clientX : e.clientX;
                const clientY = e.touches ? e.touches[0].clientY : e.clientY;
                
                let newX = ((clientX - rect.left) / rect.width) * tacCanvas.width;
                let newY = ((clientY - rect.top) / rect.height) * tacCanvas.height;
                
                newX = Math.max(15, Math.min(tacCanvas.width - 15, newX));
                newY = Math.max(15, Math.min(tacCanvas.height - 15, newY));
                
                p.x = newX;
                p.y = newY;
                
                badge.style.left = `${(newX / tacCanvas.width) * 100}%`;
                badge.style.top = `${(newY / tacCanvas.height) * 100}%`;
            };
            
            const stopDrag = () => {
                if (!isDraggingPlayer) return;
                isDraggingPlayer = false;
                badge.style.cursor = 'grab';
                const av = badge.querySelector('.fut-avatar');
                if(av) av.style.transform = 'scale(1)';
            };
            
            badge.addEventListener('mousedown', startDrag);
            window.addEventListener('mousemove', moveDrag);
            window.addEventListener('mouseup', stopDrag);
            
            badge.addEventListener('touchstart', (e) => startDrag(e.touches[0]));
            window.addEventListener('touchmove', (e) => {
                if(isDraggingPlayer) {
                    e.preventDefault();
                    moveDrag(e.touches[0]);
                }
            }, {passive: false});
            window.addEventListener('touchend', stopDrag);
            
            container.appendChild(badge);
        });
    }
};

window.updateTacticFormations = function() {
    const typeEl = document.getElementById('club-tac-type');
    const formEl = document.getElementById('club-tac-formation');
    if (!typeEl || !formEl) return;
    const opts = FORMATIONS[typeEl.value] || FORMATIONS['F5'];
    formEl.innerHTML = opts.map(f => `<option>${f}</option>`).join('');
    updateClubTacticBoard();
};

window.updateClubTacticBoard = function() {
    if(!tacCanvas) initTactics();
    if(!tacCanvas) return;

    const w = tacCanvas.width;
    const h = tacCanvas.height;
    const formStr = document.getElementById('club-tac-formation')?.value || '1-2-1';

    players = [];
    // Tomar plantilla real del club desde cache
    let roster = JSON.parse(localStorage.getItem('canchero_club_roster') || '[]');
    roster = Array.isArray(roster) ? roster.slice() : [];

    // Si roster vacío, usar al usuario actual como placeholder
    if (!roster.length && userData && userData.email) {
        roster = [{ name: userData.name || 'Yo', pos: userData.position || 'JUG', email: userData.email, isMe: true }];
    } else if (userData && userData.email) {
        const meInRoster = roster.find(p => p.email && p.email === userData.email);
        if (meInRoster) { meInRoster.isMe = true; if (!meInRoster.photo && userData.photo) meInRoster.photo = userData.photo; if (!meInRoster.pos && userData.pos) meInRoster.pos = userData.pos; }
    }

    // Definir grupos de posición según línea en la formación
    const posGroups = {
        gk:  /^(por|arq|gk|portero|arquero)$/i,
        // OJO: en Canchero "DC" = Delantero Centro (igual que CancheroFormations)
        def: /^(df|ld|li|dfc|lat|lb|rb|cb|ct|cad|lad|lateral|defensa|back|zag|zaguero)$/i,
        mid: /^(mc|mcd|mci|mco|vol|med|cm|dm|am|cam|cdm|meia|mediocampo|medio|volante)$/i,
        fwd: /^(ca|dc|dl|del|eng|sd|ex|exi|exd|st|cf|lw|rw|delantero|forward|striker|at|punta|extremo|nueve|9|10)$/i
    };
    const getGroup = pos => {
        const p = (pos || '').toUpperCase().trim();
        if (posGroups.gk.test(p)) return 'gk';
        if (posGroups.def.test(p)) return 'def';
        if (posGroups.mid.test(p)) return 'mid';
        if (posGroups.fwd.test(p)) return 'fwd';
        return 'mid'; // default
    };

    const gkPlayer = roster.find(p => getGroup(p.pos) === 'gk') || { name: '—', pos: 'POR' };
    players.push({ name: gkPlayer.name, pos: gkPlayer.pos || 'POR', photo: gkPlayer.photo, photoStyle: gkPlayer.photoStyle, nat: gkPlayer.nat, x: w*0.5, y: h*0.88, gk:true, captain:gkPlayer.captain, isMe:gkPlayer.isMe });

    const outfield = roster.filter(p => p !== gkPlayer);
    const parts = formStr.split('-').map(x => parseInt(x));
    const lineCount = parts.length;

    // Mapear líneas de la formación a grupos de posición
    const lineGroups = parts.map((_, idx) => {
        if (lineCount === 3) return ['def','mid','fwd'][idx];
        if (lineCount === 4) return ['def','mid','mid','fwd'][idx];
        if (lineCount === 2) return ['def','fwd'][idx];
        return 'mid';
    });

    // Agrupar jugadores por grupo de posición
    const grouped = { def:[], mid:[], fwd:[] };
    outfield.forEach(p => {
        const g = getGroup(p.pos);
        if (grouped[g]) grouped[g].push(p);
        else grouped.mid.push(p);
    });

    // Asignar a líneas en 2 FASES para que cada jugador caiga en su posición real
    // (un DC no debe terminar en defensa solo porque la línea de defensa estaba vacía).
    const usedEmails = new Set();
    // Fase 1: cada línea toma SOLO de su grupo correcto
    const lineAssignments = parts.map((count, lineIdx) => {
        const group = lineGroups[lineIdx];
        const res = [];
        for (const p of (grouped[group] || [])) {
            if (!usedEmails.has(p.email) && res.length < count) { res.push(p); usedEmails.add(p.email); }
        }
        return res;
    });
    // Fase 2: completar slots vacíos con los que sobraron (cualquier grupo), luego placeholders
    const leftovers = [];
    ['def','mid','fwd'].forEach(g => (grouped[g] || []).forEach(p => { if (!usedEmails.has(p.email)) { leftovers.push(p); usedEmails.add(p.email); } }));
    let li = 0;
    lineAssignments.forEach((res, lineIdx) => {
        while (res.length < parts[lineIdx]) { res.push(leftovers[li++] || { name: '—', pos: '---' }); }
    });

    parts.forEach((count, lineIdx) => {
        const linePlayers = lineAssignments[lineIdx];
        const stepX = w / (count + 1);
        const lineY = h * 0.72 - (lineIdx * (h * 0.45 / Math.max(lineCount - 1, 1)));
        linePlayers.forEach((pData, i) => {
            players.push({
                name: pData.name, pos: pData.pos, photo: pData.photo, photoStyle: pData.photoStyle, nat: pData.nat,
                x: stepX * (i + 1), y: lineY,
                gk: false, captain: pData.captain, isMe: pData.isMe
            });
        });
    });

    // Suplentes (jugadores no en cancha)
    const onFieldEmails = new Set([...(gkPlayer.email ? [gkPlayer.email] : []), ...Array.from(usedEmails)]);
    const subs = roster.filter(p => p.email && !onFieldEmails.has(p.email));
    window._currentSubs = subs;
    _renderSubsBench(subs);

    renderTacBoard();
};

// Panel de suplentes junto a la cancha
window._currentSubs = [];
window._renderSubsBench = function(subs) {
    let bench = document.getElementById('subs-bench-panel');
    const boardContainer = document.getElementById('club-tactic-board-container');
    if (!boardContainer) return;

    // Crear o limpiar el panel de suplentes
    const wrapper = boardContainer.closest('.panel') || boardContainer.parentElement;
    if (!bench) {
        bench = document.createElement('div');
        bench.id = 'subs-bench-panel';
        bench.style.cssText = 'margin-top:14px;background:#0d0d0d;border:1px solid #1e1e1e;border-radius:14px;padding:12px;';
        // Insertar después del contenedor del board
        boardContainer.insertAdjacentElement('afterend', bench);
    }

    if (!subs || !subs.length) {
        bench.innerHTML = '<div style="text-align:center;padding:10px;color:#444;font-size:11px;">Sin suplentes en planilla</div>';
        return;
    }

    bench.innerHTML = `
        <div style="font-size:10px;color:#555;font-weight:900;letter-spacing:1px;margin-bottom:8px;">SUPLENTES / BANCA (${subs.length})</div>
        <div style="display:flex;flex-wrap:wrap;gap:8px;">
            ${subs.map(p => `
                <div style="display:flex;align-items:center;gap:6px;background:#111;border:1px solid #222;border-radius:10px;padding:6px 10px;font-size:11px;cursor:pointer;"
                     onclick="window._subPlayerIn('${p.email}','${(p.name||'').replace(/'/g,"\\'")}','${p.pos||'JUG'}')"
                     title="Click para poner en cancha">
                    ${p.photo ? `<img src="${p.photo}" style="width:24px;height:24px;border-radius:50%;object-fit:cover;">` : `<div style="width:24px;height:24px;border-radius:50%;background:#1a1a1a;border:1px solid #333;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:900;color:#555;">${(p.name||'?')[0]}</div>`}
                    <div>
                        <div style="font-weight:700;color:#fff;">${p.name?.split(' ')[0] || p.email?.split('@')[0] || 'Jug'}</div>
                        <div style="font-size:9px;color:var(--accent);">${(p.pos||'JUG').toUpperCase()}</div>
                    </div>
                    <i class='bx bx-transfer' style="color:#444;font-size:12px;"></i>
                </div>`).join('')}
        </div>
        <div style="font-size:10px;color:#444;margin-top:8px;">Tocá un suplente para intercambiarlo con el último jugador seleccionado en cancha.</div>`;
};

window._lastSelectedPlayer = null;
window._subPlayerIn = function(email, name, pos) {
    // Si hay un jugador seleccionado en cancha, hacer el cambio
    if (window._lastSelectedPlayer !== null) {
        const idx = window._lastSelectedPlayer;
        if (players[idx]) {
            const subData = window._currentSubs.find(p => p.email === email);
            if (subData) {
                const oldPlayer = players[idx];
                players[idx] = { ...players[idx], name: name, pos: pos, email: email };
                // Actualizar lista de subs
                window._currentSubs = window._currentSubs.filter(p => p.email !== email);
                if (oldPlayer.name && oldPlayer.name !== '—') {
                    window._currentSubs.push({ name: oldPlayer.name, pos: oldPlayer.pos, email: oldPlayer.email });
                }
                window._lastSelectedPlayer = null;
                window._renderSubsBench(window._currentSubs);
                renderTacBoard();
                showToast && showToast(`${name} entra por ${oldPlayer.name || 'jugador'}`, 'success');
                return;
            }
        }
    }
    showToast && showToast(`Seleccioná primero un jugador en cancha para hacer el cambio`, 'info');
};

window.undoTacticAction = function() {
    if (drawnLines.length > 0) {
        drawnLines.pop();
        renderTacBoard();
    }
};

window.clearTacticBoard = function() {
    drawnLines = [];
    renderTacBoard();
};

// ── Guardar / cargar tácticas ──────────────────────────────────
window._saveTactic = async function() {
    const clubId = window.currentEditingClubId;
    const formation = document.getElementById('club-tac-formation')?.value || '';
    const type = document.getElementById('club-tac-type')?.value || 'F11';
    const name = prompt('Nombre de la táctica:', `${type} ${formation}`);
    if (!name) return;
    // Capturar posiciones actuales de los jugadores en la cancha
    const positions = (players || []).map(p => ({ name: p.name, pos: p.pos, x: p.x, y: p.y, email: p.email, gk: !!p.gk }));
    const tacticData = { name, formation, type, positions, lines: drawnLines };
    const sb = window._sb;
    const me = window.userData;
    // Guardar en localStorage siempre (respaldo)
    const localKey = `canchero_tactics_${clubId||'default'}`;
    let localTactics = [];
    try { localTactics = JSON.parse(localStorage.getItem(localKey) || '[]'); } catch(e) {}
    localTactics.unshift({ ...tacticData, id: 'local_' + Date.now(), created_at: new Date().toISOString() });
    localStorage.setItem(localKey, JSON.stringify(localTactics.slice(0, 20)));
    // Guardar en Supabase
    if (sb && clubId) {
        try {
            await sb.from('club_tactics').insert({ club_id: clubId, name, formation, positions: tacticData, created_by: me?.email });
        } catch(e) {}
    }
    if (typeof showToast === 'function') showToast('Táctica guardada ✓', 'success');
};

window._openSavedTactics = async function() {
    const panel = document.getElementById('saved-tactics-panel');
    const list = document.getElementById('saved-tactics-list');
    if (!panel || !list) return;
    panel.style.display = 'block';
    list.innerHTML = '<div style="color:#555;font-size:11px;text-align:center;padding:10px;"><i class="bx bx-loader-alt bx-spin"></i></div>';
    const clubId = window.currentEditingClubId;
    const sb = window._sb;
    let tactics = [];
    // Cargar de Supabase
    if (sb && clubId) {
        try {
            const { data } = await sb.from('club_tactics').select('*').eq('club_id', clubId).order('created_at', { ascending: false });
            if (data) tactics = data.map(t => ({ id: t.id, name: t.name, formation: t.formation, ...((t.positions)||{}), created_at: t.created_at }));
        } catch(e) {}
    }
    // Merge con localStorage
    try {
        const localKey = `canchero_tactics_${clubId||'default'}`;
        const local = JSON.parse(localStorage.getItem(localKey) || '[]');
        tactics = [...tactics, ...local.filter(l => !tactics.find(t => t.name === l.name))];
    } catch(e) {}
    if (!tactics.length) {
        list.innerHTML = '<div style="color:#555;font-size:11px;text-align:center;padding:14px;">No hay tácticas guardadas todavía. Guardá una con el botón GUARDAR TÁCTICA.</div>';
        return;
    }
    list.innerHTML = tactics.map(t => `
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px;border:1px solid #1e1e1e;border-radius:10px;margin-bottom:6px;">
            <div style="flex:1;min-width:0;">
                <div style="font-size:12px;font-weight:700;">${t.name||'Táctica'}</div>
                <div style="font-size:10px;color:#555;">${t.formation||''} ${t.type?'· '+t.type:''}</div>
            </div>
            <button onclick='window._loadTactic(${JSON.stringify(JSON.stringify(t)).replace(/'/g,"&#39;")})' style="background:rgba(186,255,0,0.1);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:8px;padding:5px 10px;font-size:10px;font-weight:700;cursor:pointer;">CARGAR</button>
        </div>`).join('');
};

window._loadTactic = function(tacticJson) {
    let t;
    try { t = typeof tacticJson === 'string' ? JSON.parse(tacticJson) : tacticJson; } catch(e) { return; }
    if (!t) return;
    // Aplicar formación
    const typeEl = document.getElementById('club-tac-type');
    const formEl = document.getElementById('club-tac-formation');
    if (typeEl && t.type) { typeEl.value = t.type; window.updateTacticFormations(); }
    if (formEl && t.formation) formEl.value = t.formation;
    // Aplicar posiciones guardadas
    if (t.positions && Array.isArray(t.positions)) {
        players = t.positions.map(p => ({ ...p }));
    }
    if (t.lines) drawnLines = t.lines;
    if (typeof renderTacBoard === 'function') renderTacBoard();
    const panel = document.getElementById('saved-tactics-panel');
    if (panel) panel.style.display = 'none';
    if (typeof showToast === 'function') showToast('Táctica cargada ✓', 'success');
};

window.setTacticMode = function(mode) {
    tacMode = mode;
    ['move','draw','erase'].forEach(m => {
        const btn = document.getElementById('btn-tac-' + m);
        if (btn) btn.className = btn.className.replace('btn-primary','btn-glass');
    });
    const active = document.getElementById('btn-tac-' + mode);
    if (active) active.className = active.className.replace('btn-glass','btn-primary');
    
    const picker = document.getElementById('tac-color-picker');
    if (picker) picker.style.display = mode === 'draw' ? 'flex' : 'none';
};

window.setTacColor = function(color, el) {
    tacColor = color;
    document.querySelectorAll('.tac-color-btn').forEach(b => b.style.border = '2px solid transparent');
    if (el) el.style.border = '2px solid white';
};

window.undoTacLine = function() {
    drawnLines.pop();
    renderTacBoard();
};

window.clearTacBoard = function() {
    drawnLines = [];
    renderTacBoard();
};


// ============================================================
// ACTUALIZAR switchDashboardTab para tabs adicionales
// ============================================================
const _origSwitch = window.switchDashboardTab;
window.switchDashboardTab = function(role, tabId, el) {
    _origSwitch(role, tabId, el);
    if (tabId === 'mensajes') {
        if (typeof window.CancheroMessaging !== 'undefined') {
            window.CancheroMessaging.init();
        } else window.renderMensajes();
        // Limpiar badge de mensajes al entrar a la sección
        const _msgBadge = document.getElementById('mobile-msg-badge');
        if (_msgBadge) _msgBadge.style.display = 'none';
        // Marcar notificaciones de DM como leídas en Supabase
        try {
            const _sb2 = window._sb;
            const _email2 = window.userData?.email;
            if (_sb2 && _email2) {
                _sb2.from('notifications').update({ read: true }).eq('recipient_email', _email2).eq('type', 'dm').eq('read', false).then(() => {});
            }
        } catch(e) {}
    }
    if (tabId === 'mundo-futbol') { try { loadMatchCenter(); } catch(e){} }
    if (tabId === 'club-gestion') {
        switchClubGestionTab('tacticas', document.querySelector('.club-gestion-tab'));
        updateTacticFormations();
    }
    if (tabId === 'mis-partidos') {
        setTimeout(() => {
            if (typeof loadMisPartidos === 'function') loadMisPartidos('creados');
        }, 80);
        // Verificar invitaciones pendientes para el badge
        try {
            const _sb3 = window._sb;
            const _email3 = window.userData?.email;
            if (_sb3 && _email3) {
                _sb3.from('match_invites').select('id', { count: 'exact', head: true })
                    .eq('to_email', _email3).eq('status', 'pendiente')
                    .then(({ count }) => {
                        const badge = document.getElementById('mobile-partidos-badge');
                        if (badge) {
                            badge.textContent = String(count || 0);
                            badge.style.display = (count > 0) ? 'flex' : 'none';
                        }
                    });
            }
        } catch(e) {}
    }
};

