window.navigatePanel = function() {
    if (userData) navigate(userData.role || 'jugador');
};

function updateAvailabilityDot(isAvailable) {
    const badge = document.getElementById('profile-availability-badge');
    if (badge) badge.style.background = isAvailable ? '#00ff88' : '#555';
    // Pastilla "DISPONIBLE" en la cabecera del perfil — ocultar si se desactiva
    const pAvail = document.getElementById('p-avail-dot');
    if (pAvail) pAvail.style.display = isAvailable ? 'inline-flex' : 'none';
    // Actualizar en feed cards y perfiles de este usuario
    if (window.userData && window.userData.email) {
        document.querySelectorAll('.user-avail-dot[data-email="' + window.userData.email + '"]').forEach(d => {
            d.style.background = isAvailable ? '#00ff88' : '#555';
            // Si tiene texto, actualizar estilo
            if (d.style.borderRadius === '20px') {
                d.style.display = isAvailable ? 'inline-flex' : 'none';
            }
        });
        // Actualizar badge en dashboard del jugador
        const dashBadge = document.getElementById('player-avail-badge');
        if (dashBadge) {
            dashBadge.style.display = isAvailable ? 'flex' : 'none';
        }
    }
}

window.toggleUserAvailability = function(active) {
    const toggle = document.getElementById('availability-toggle');
    if (toggle) toggle.checked = active;
    const item = document.getElementById('check-avail');
    if (item && item.querySelector('i')) { item.classList.add('done'); item.querySelector('i').className = 'bx bx-check-circle'; }
    // Guardar en userData y localStorage
    if (window.userData) {
        window.userData.isAvailable = active;
        window.userData.available = active;
        try { localStorage.setItem('canchero_user', JSON.stringify(window.userData)); } catch(e) {}
        // Guardar en Supabase — columna correcta es "available"
        const _sdb = window._sb;
        if (_sdb && window.userData.email) {
            _sdb.from('users').update({ available: active }).eq('email', window.userData.email)
                .then(r => {
                    if (r.error) console.warn('[availability] Supabase update error:', r.error.message);
                    else {
                        const msg = active ? '¡Estás disponible para jugar!' : 'Ya no aparecerás como disponible';
                        if (typeof showToast === 'function') showToast(msg, active ? 'success' : 'info');
                    }
                }).catch(e => console.warn('[availability]', e.message));
        }
    }
    updateAvailabilityDot(active);
};

window.addTeamInvitation = function() {
    const select = document.getElementById('ct-invitar-select');
    if (!select) return;
    const value = select.value;
    const text = select.options[select.selectedIndex].text;
    
    const container = document.getElementById('ct-invited-list');
    if (!container) return;
    const existing = container.querySelectorAll(`[data-val="${value}"]`);
    if (existing.length > 0) return;
    
    const badge = document.createElement('span');
    badge.className = 'badge';
    badge.setAttribute('data-val', value);
    badge.style.background = 'rgba(186,255,0,0.1)';
    badge.style.border = '1px solid var(--accent)';
    badge.style.color = 'var(--accent)';
    badge.style.padding = '5px 12px';
    badge.style.borderRadius = '20px';
    badge.style.fontSize = '12px';
    badge.style.display = 'flex';
    badge.style.alignItems = 'center';
    badge.style.gap = '6px';
    badge.innerHTML = `${text} <i class='bx bx-x' style='cursor:pointer;' onclick='this.parentElement.remove()'></i>`;
    container.appendChild(badge);
};

