window.approveTeamRequest = function(teamName, elementId) {
    alert(`¡Has aprobado e inscrito al equipo "${teamName}" en tu torneo!`);
    const el = document.getElementById(elementId);
    if(el) el.remove();
    
    const container = document.getElementById('ct-inscribed-list');
    if(container) {
        const item = document.createElement('li');
        item.style.cssText = "display: flex; align-items: center; gap: 10px; padding: 8px 12px; background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.05); border-radius: 8px; margin-top: 8px;";
        item.innerHTML = `
            <img src="https://ui-avatars.com/api/?name=${teamName.substring(0,2)}&background=222&color=baff00" style="width: 32px; height: 32px; border-radius: 50%;" />
            <div>
                <strong style="color: #fff; font-size: 14px;">${teamName}</strong>
                <div style="font-size: 11px; color: #888;">Inscrito mediante Solicitud Abierta</div>
            </div>
        `;
        container.appendChild(item);
    }
};

window.rejectTeamRequest = function(elementId) {
    if(confirm('¿Seguro que deseas rechazar esta solicitud de inscripción?')) {
        const el = document.getElementById(elementId);
        if(el) el.remove();
    }
};

window.openApplicantsModal = async function(matchId) {
    if (!_sb) { showToast('Sin conexión', 'error'); return; }
    try {
        const { data } = await _sb.from('match_requests').select('user_name, user_email, status, side_pref').eq('match_id', matchId);
        if (!data || !data.length) {
            showToast('Aún no hay solicitudes para este partido.', 'info');
            return;
        }
        const list = data.map(r => `${r.user_name || r.user_email} (${r.status})`).join('\n');
        alert(`SOLICITUDES:\n\n${list}`);
    } catch(e) {
        showToast('Error: ' + e.message, 'error');
    }
};

// Render real matches from Supabase (called by switchDashboardTab buscar-partidos)
window.renderBuscarPartidos = async function(genderFilter) {
    const list = document.getElementById('partidos-list');
    if (!list) return;
    // Modo "equipos buscan jugadores": switchPartidosTab pinta su propia lista en
    // #partidos-list. El auto-render de switchDashboardTab (sin argumentos) NO debe
    // pisarla (antes ganaba la carrera async y las dos tarjetas mostraban lo mismo).
    if (window._partidosView === 'buscan' && arguments.length === 0) return;
    if (arguments.length > 0) window._partidosView = 'todos';
    const sbP = window._sb;
    if (!sbP) {
        list.innerHTML = '<div style="text-align:center;padding:40px;color:#666;"><i class="bx bx-loader-alt bx-spin" style="font-size:28px;display:block;margin-bottom:10px;"></i>Conectando...</div>';
        setTimeout(() => window.renderBuscarPartidos(genderFilter), 1500);
        return;
    }
    // Filtros UI (género)
    const filterHtml = `<div style="display:flex;gap:6px;margin-bottom:12px;overflow-x:auto;scrollbar-width:none;" id="partidos-gender-filter">
        <button onclick="renderBuscarPartidos('todos')" class="pf-btn ${!genderFilter||genderFilter==='todos'?'active':''}" style="background:${!genderFilter||genderFilter==='todos'?'rgba(186,255,0,0.1)':'transparent'};color:${!genderFilter||genderFilter==='todos'?'var(--accent)':'#666'};border:1px solid ${!genderFilter||genderFilter==='todos'?'rgba(186,255,0,0.3)':'#333'};border-radius:10px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">⚽ Todos</button>
        <button onclick="renderBuscarPartidos('mixto')" class="pf-btn" style="background:${genderFilter==='mixto'?'rgba(180,180,180,0.15)':'transparent'};color:${genderFilter==='mixto'?'#aaa':'#666'};border:1px solid ${genderFilter==='mixto'?'#555':'#333'};border-radius:10px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">⚥ Mixto</button>
        <button onclick="renderBuscarPartidos('masculino')" class="pf-btn" style="background:${genderFilter==='masculino'?'rgba(100,180,255,0.15)':'transparent'};color:${genderFilter==='masculino'?'#64b4ff':'#666'};border:1px solid ${genderFilter==='masculino'?'rgba(100,180,255,0.4)':'#333'};border-radius:10px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">♂ Masculino</button>
        <button onclick="renderBuscarPartidos('femenino')" class="pf-btn" style="background:${genderFilter==='femenino'?'rgba(255,150,200,0.15)':'transparent'};color:${genderFilter==='femenino'?'#ff96c8':'#666'};border:1px solid ${genderFilter==='femenino'?'rgba(255,150,200,0.4)':'#333'};border-radius:10px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">♀ Femenino</button>
    </div>`;
    list.innerHTML = filterHtml + '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div>';
    try {
        // Traer todos y filtrar en memoria para evitar problemas de columnas
        let { data, error } = await sbP.from('matches')
            .select('*')
            .gte('scheduled_at', new Date().toISOString())
            .order('scheduled_at', { ascending: true })
            .limit(60);
        if (error) throw error;
        // Filtrar abiertos en memoria — y NUNCA mostrar finalizados/cancelados
        let matches = (data || []).filter(m =>
            (m.status !== 'finished' && m.status !== 'cancelled' && m.status !== 'finalizado' && m.status !== 'cancelado') &&
            (m.is_open === true ||
            (m.match_type||'').toLowerCase().includes('open') ||
            (m.modality||'').toLowerCase().includes('abierto') ||
            (m.match_type||'').toLowerCase() === 'abierto')
        );
        if (genderFilter && genderFilter !== 'todos') {
            matches = matches.filter(m => (m.gender||'').toLowerCase() === genderFilter);
        }
        data = matches;
        const filterDiv = document.getElementById('partidos-gender-filter') || list;
        const contentArea = document.createElement('div');
        // Saber en qué partidos ya participo (para mostrar "Ya sos parte" en vez de "Unirme")
        let _myPartSet = new Set();
        try {
            const _myEmail0 = userData && userData.email;
            if (_myEmail0) {
                const { data: _mp } = await sbP.from('match_players').select('match_id').eq('player_email', _myEmail0);
                (_mp||[]).forEach(r => _myPartSet.add(String(r.match_id)));
            }
        } catch(e) {}

        if (!data || !data.length) {
            contentArea.innerHTML = `<div style="text-align:center;padding:50px 20px;color:#666;">
                <i class='bx bx-football' style="font-size:48px;display:block;margin-bottom:12px;opacity:0.4;"></i>
                <div style="font-size:14px;font-weight:700;margin-bottom:6px;">No hay partidos abiertos${genderFilter&&genderFilter!=='todos'?' de este tipo':''}</div>
                <div style="font-size:12px;">Creá el primero.</div>
                <button class="btn btn-primary" style="margin-top:18px;" onclick="switchDashboardTab('jugador','crear-partido')"><i class='bx bx-plus'></i> CREAR UN PARTIDO</button>
            </div>`;
        } else {
            const myEmail = userData && userData.email;
            contentArea.innerHTML = data.map(m => {
                const when = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{weekday:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : 'Sin fecha';
                const slotsLeft = Math.max(0, (m.slots_total||10) - (m.slots_taken||0));
                const genLabel = m.gender === 'masculino' ? '<span style="color:#64b4ff;font-size:9px;">♂</span>' : m.gender === 'femenino' ? '<span style="color:#ff96c8;font-size:9px;">♀</span>' : '<span style="color:#888;font-size:9px;">⚥</span>';
                const isMine = m.created_by === myEmail;
                const isPart = isMine || _myPartSet.has(String(m.id));
                return `<div onclick="window.viewMatchDetails&&window.viewMatchDetails('${m.id}')" style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:16px;margin-bottom:10px;cursor:pointer;transition:.15s;" onmouseover="this.style.borderColor='rgba(186,255,0,0.2)'" onmouseout="this.style.borderColor='#1e1e1e'">
                    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">
                        <div style="flex:1;min-width:0;">
                            <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap;">
                                <span style="background:#00e676;color:#000;font-size:9px;font-weight:900;padding:2px 7px;border-radius:8px;">ABIERTO</span>
                                ${genLabel}
                                <span style="font-size:12px;color:#555;">${m.modality||'F5'}</span>
                            </div>
                            <div style="font-weight:800;font-size:14px;margin-bottom:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${m.name||'Partido'}</div>
                            <div style="font-size:11px;color:#666;display:flex;gap:10px;flex-wrap:wrap;">
                                <span><i class='bx bx-map'></i> ${m.venue||m.city||'—'}</span>
                                <span><i class='bx bx-time'></i> ${when}</span>
                            </div>
                        </div>
                        <div style="text-align:right;flex-shrink:0;">
                            <div style="font-size:12px;color:${slotsLeft>0?'#00e676':'#ff4444'};font-weight:700;">${slotsLeft>0?slotsLeft+' libre'+( slotsLeft!==1?'s':''):'COMPLETO'}</div>
                            <div style="font-size:11px;color:#555;margin-top:2px;">${m.price?'$'+m.price:'Gratis'}</div>
                        </div>
                    </div>
                    <div style="display:flex;gap:8px;margin-top:10px;" onclick="event.stopPropagation()">
                        <button onclick="window.viewMatchDetails&&window.viewMatchDetails('${m.id}')" style="flex:1;background:rgba(186,255,0,0.06);color:var(--accent);border:1px solid rgba(186,255,0,0.25);border-radius:10px;padding:7px;font-size:11px;font-weight:700;cursor:pointer;"><i class='bx bx-info-circle'></i> Ver detalles</button>
                        ${isPart ? `<div style="flex:1;background:rgba(0,230,118,0.1);color:#00e676;border:1px solid rgba(0,230,118,0.3);border-radius:10px;padding:7px;font-size:11px;font-weight:800;text-align:center;"><i class='bx bx-check-circle'></i> Ya sos parte</div>` : (slotsLeft > 0 ? `<button onclick="joinOpenMatch&&joinOpenMatch('${m.id}')" style="flex:1;background:var(--accent);color:#000;border:none;border-radius:10px;padding:7px;font-size:11px;font-weight:900;cursor:pointer;"><i class='bx bx-user-plus'></i> UNIRME</button>` : `<div style="flex:1;background:#1a1a1a;color:#666;border:1px solid #2a2a2a;border-radius:10px;padding:7px;font-size:11px;font-weight:800;text-align:center;">COMPLETO</div>`)}
                    </div>
                </div>`;
            }).join('');
        }
        // Replace loader with content after filter
        const loader = list.querySelector('div:not(#partidos-gender-filter)');
        if (loader) loader.replaceWith(contentArea);
        else list.appendChild(contentArea);
    } catch(e) {
        list.innerHTML += `<div style="text-align:center;padding:30px;color:#888;">Error: ${e.message}</div>`;
    }
};

window.viewMatchDetails = async function(matchId, opts) {
    // opts.forceModal: renderizar SIEMPRE en un modal overlay (no en la pestaña global-viewer).
    // Lo usa la ficha completa de un partido de TORNEO: así el partido real se muestra ENCIMA
    // del torneo (z-index alto) y al cerrar volvés al torneo, en vez de que switchDashboardTab
    // te saque a otra sección del dashboard ("me saca de todo").
    opts = opts || {};
    // Accessible to all users — espectadores pueden ver sin participar
    const isLoggedIn = !!userData;
    const dashboard = userData && userData.role === 'club' ? 'club' : 'jugador';

    // Try modal first (works for any logged-in context), then tab
    const existingModal = document.getElementById('match-detail-modal');
    if (existingModal) existingModal.remove();

    // For non-logged users or when called from feed, use a modal overlay
    let content;
    let useModal = false;
    const tabContent = document.getElementById(`${dashboard}-global-viewer-content`);
    if (!opts.forceModal && isLoggedIn && tabContent) {
        if(typeof switchDashboardTab === 'function') switchDashboardTab(dashboard, 'global-viewer');
        content = tabContent;
    } else {
        // Modal for espectadores / no-login context / ficha completa de torneo (forceModal).
        useModal = true;
        // Sobre el modal del torneo (cmd-modal=100004, cti=100008) para que quede ENCIMA.
        const _z = opts.forceModal ? 100012 : 9900;
        const overlay = document.createElement('div');
        overlay.id = 'match-detail-modal';
        overlay.style.cssText = 'position:fixed;inset:0;z-index:'+_z+';background:rgba(0,0,0,0.9);overflow-y:auto;padding:16px;';
        overlay.innerHTML = '<div id="match-detail-modal-content" style="max-width:600px;margin:0 auto;padding-bottom:40px;"></div>';
        // No cerrar al tocar el fondo (el usuario se salía sin querer al tocar abajo). Se
        // cierra con el botón Volver del propio contenido.
        document.body.appendChild(overlay);
        content = document.getElementById('match-detail-modal-content');
    }

    content.innerHTML = `<div style="text-align:center;padding:60px 20px;"><i class='bx bx-loader-alt bx-spin' style="font-size:32px;color:var(--accent);"></i><div style="margin-top:10px;color:#555;font-size:12px;">Cargando partido...</div></div>`;

    const sb = window._sb;
    if (!sb) { content.innerHTML = '<div style="padding:20px;color:#f44;text-align:center;">Sin conexión a la base de datos.</div>'; return; }

    try {
        const { data: m, error: mErr } = await sb.from('matches').select('*').eq('id', matchId).single();
        if (mErr || !m) {
            content.innerHTML = '<div style="padding:20px;color:#f44;text-align:center;">Partido no encontrado.</div>';
            return;
        }

        const { data: players } = await sb.from('match_players').select('*').eq('match_id', matchId);
        const myEmail = userData && userData.email;
        const isCaptain = m.created_by === myEmail || m.captain_home_email === myEmail || m.captain_away_email === myEmail;
        // El creador/capitán siempre cuenta como participante aunque no esté en match_players,
        // para que tenga acceso al CHAT y al PANEL del partido.
        const isParticipant = isCaptain || (players || []).some(p => p.player_email === myEmail);
        // Total de cupos derivado del formato (corrige partidos viejos con slots_total incorrecto)
        const _fmtStr = ((m.name||'') + ' ' + (m.format||'') + ' ' + (m.modality||'')).toLowerCase();
        const _derivedTotal = (_fmtStr.includes('5v5')||_fmtStr.includes('f5')||_fmtStr.includes('futbol 5')||_fmtStr.includes('fútbol 5')) ? 10
            : (_fmtStr.includes('7v7')||_fmtStr.includes('f7')||_fmtStr.includes('futbol 7')||_fmtStr.includes('fútbol 7')) ? 14
            : (_fmtStr.includes('11')) ? 22 : (m.slots_total || 22);
        const _total = _derivedTotal;
        const slotsLeft = Math.max(0, _total - (m.slots_taken || (players || []).length));

        const teamHome = (players || []).filter(p => p.team === 'home' || !p.team);
        const teamAway = (players || []).filter(p => p.team === 'away');

        const dateStr = m.scheduled_at
            ? new Date(m.scheduled_at).toLocaleString('es-UY', { weekday:'short', day:'numeric', month:'short', hour:'2-digit', minute:'2-digit' })
            : 'Sin fecha';

        function buildTeamHtml(teamPlayers, color) {
            if (!teamPlayers.length) return `<div style="color:#444;font-size:12px;text-align:center;padding:20px 0;">Sin jugadores anotados</div>`;
            return teamPlayers.map(p => {
                const n = (p.player_name || 'Jugador').replace(/</g,'&lt;');
                const initial = n[0] ? n[0].toUpperCase() : '?';
                return `<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #111;">
                    <div style="width:32px;height:32px;border-radius:50%;background:${color};display:flex;align-items:center;justify-content:center;font-weight:900;font-size:13px;color:#000;flex-shrink:0;">${initial}</div>
                    <div style="flex:1;min-width:0;">
                        <div style="font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${n}</div>
                        <div style="font-size:10px;color:#555;">${p.position||p.pos||'JUG'}${p.is_captain?' ⭐':''}</div>
                    </div>
                </div>`;
            }).join('');
        }

        const captainActions = isCaptain ? `
            <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;">
                <button onclick="editMatchOpen('${matchId}')" style="flex:1;min-width:100px;background:rgba(255,170,0,0.1);color:#ffaa00;border:1px solid rgba(255,170,0,0.3);border-radius:10px;padding:10px;font-size:12px;font-weight:700;cursor:pointer;"><i class='bx bx-edit'></i> Editar</button>
                <button onclick="deleteMatch('${matchId}')" style="flex:1;min-width:100px;background:rgba(255,68,68,0.1);color:#ff4444;border:1px solid rgba(255,68,68,0.3);border-radius:10px;padding:10px;font-size:12px;font-weight:700;cursor:pointer;"><i class='bx bx-trash'></i> Eliminar</button>
                ${(m.match_type === 'abierto' || m.modality === 'abierto') && slotsLeft > 0 ? `<button onclick="publishNeedPlayer('${matchId}')" style="flex:1;min-width:140px;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:10px;font-size:12px;font-weight:700;cursor:pointer;"><i class='bx bx-user-plus'></i> Publicar "Busco jugador"</button>` : ''}
            </div>` : '';

        const joinBtn = !isParticipant && slotsLeft > 0 ? `
            <button onclick="joinOpenMatch('${matchId}')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:14px;font-weight:900;font-size:14px;cursor:pointer;margin-top:12px;"><i class='bx bx-user-plus'></i> UNIRSE AL PARTIDO (${slotsLeft} lugar${slotsLeft!==1?'es':''})</button>` : '';

        const leaveBtn = isParticipant && !isCaptain ? `
            <button onclick="leaveMatch && leaveMatch('${matchId}')" style="width:100%;background:rgba(255,68,68,0.08);color:#ff4444;border:1px solid rgba(255,68,68,0.25);border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;margin-top:8px;"><i class='bx bx-log-out'></i> SALIR DEL PARTIDO</button>` : '';

        // Chat duplicado removido: el acceso al chat queda solo en el ícono/tile "Chat" (sin botón grande repetido)
        const chatBtn = '';

        const panelBtn = isParticipant ? `
            <button onclick="window.MatchDashboard&&window.MatchDashboard.open('${matchId}')" style="width:100%;background:#1a1a1a;color:#ccc;border:1px solid #333;border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;margin-top:8px;"><i class='bx bx-layout'></i> PANEL DEL PARTIDO</button>
            <button onclick="window.CancheroPolls&&window.CancheroPolls.openCreator('match','${matchId}')" style="width:100%;background:rgba(100,180,255,0.08);color:#64b4ff;border:1px solid rgba(100,180,255,0.25);border-radius:12px;padding:10px;font-weight:700;font-size:12px;cursor:pointer;margin-top:6px;"><i class='bx bx-poll'></i> CREAR ENCUESTA DEL PARTIDO</button>` : '';

        const shareBtn = `<button onclick="shareMatch('${matchId}','${(m.name||'').replace(/'/g,"\\'")}','${(m.venue||'').replace(/'/g,"\\'")}','${dateStr}')" style="width:100%;background:#1a1a1a;color:#888;border:1px solid #222;border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;margin-top:8px;"><i class='bx bx-share-alt'></i> COMPARTIR PARTIDO</button>`;

        const managePlayers = isCaptain ? `
            <button onclick="window.CancheroMatchPlayers&&window.CancheroMatchPlayers.openPlayersPanel('${matchId}')"
                style="width:100%;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;margin-top:8px;">
                <i class='bx bx-user-plus'></i> GESTIONAR JUGADORES
            </button>
            <button onclick="window._loadAvailablePlayersForMatch('${matchId}','home')"
                style="width:100%;background:rgba(0,230,118,0.06);color:#00e676;border:1px solid rgba(0,230,118,0.25);border-radius:12px;padding:10px;font-weight:700;font-size:12px;cursor:pointer;margin-top:6px;">
                🟢 VER JUGADORES DISPONIBLES PARA INVITAR
            </button>` : '';

        const betBtn = isLoggedIn ? `
            <button onclick="window.CancheroMatchPlayers&&window.CancheroMatchPlayers.openBetModal('${matchId}','${isCaptain?'captain':isParticipant?'player':'spectator'}')"
                style="width:100%;background:rgba(255,170,0,0.08);color:#ffaa00;border:1px solid rgba(255,170,0,0.3);border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;margin-top:8px;">
                <i class='bx bx-gift'></i> APUESTA / PREMIO
            </button>` : '';

        // Badge tipo partido
        const modalityVal = (m.modality || m.match_type || 'abierto').toLowerCase();
        const typeBadge = modalityVal.includes('cerr')
            ? '<span style="background:#ff4444;color:#fff;font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;margin-right:6px;">🔒 CERRADO</span>'
            : modalityVal.includes('amist') || m.is_friendly
            ? '<span style="background:#9c88ff;color:#fff;font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;margin-right:6px;">🤝 AMISTOSO</span>'
            : '<span style="background:#00e676;color:#000;font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;margin-right:6px;">ABIERTO</span>';
        const genderBadge = m.gender === 'masculino'
            ? '<span style="background:rgba(100,180,255,0.15);color:#64b4ff;font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;margin-right:6px;">♂ MASCULINO</span>'
            : m.gender === 'femenino'
            ? '<span style="background:rgba(255,150,200,0.15);color:#ff96c8;font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;margin-right:6px;">♀ FEMENINO</span>'
            : '<span style="background:rgba(180,180,180,0.1);color:#aaa;font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;margin-right:6px;">⚥ MIXTO</span>';

        // En modal mostramos un "Volver" propio. En el tab global-viewer NO duplicamos:
        // ese contenedor ya tiene su botón "VOLVER" hardcodeado (evita el doble botón).
        const backBtn = useModal
            ? `<button onclick="document.getElementById('match-detail-modal').remove()" style="display:flex;align-items:center;gap:6px;background:transparent;border:none;color:#888;cursor:pointer;font-size:13px;padding:0;margin-bottom:16px;"><i class='bx bx-arrow-back'></i></button>`
            : '';

        // ── Datos para el hero VS (defensivo: challenge tiene clubes; abierto no) ──
        const homeName = (m.home_club_name || m.team_home_name || 'LOCAL').toString();
        const awayName = (m.away_club_name || m.team_away_name || (modalityVal.includes('abiert') ? 'ABIERTO' : 'VISITANTE')).toString();
        const homeLogo = m.home_club_logo || m.home_logo || '';
        const awayLogo = m.away_club_logo || m.away_logo || '';
        const hasResult = (m.home_score != null && m.away_score != null);
        const fmtType = ((m.name&&m.name.match(/5v5|7v7|11v11/i)||[''])[0]) || m.format || m.match_type || '';
        const timeOnly = (m.scheduled_at ? new Date(m.scheduled_at).toLocaleTimeString('es-UY',{hour:'2-digit',minute:'2-digit'}) : '');
        const escudo = (logo, name, color) => logo
            ? `<div style="width:74px;height:74px;border-radius:14px;background:#0a0a0a;border:2px solid ${color};box-shadow:0 0 18px ${color}33;background-image:url('${logo}');background-size:cover;background-position:center;"></div>`
            : `<div style="width:74px;height:74px;border-radius:14px;background:linear-gradient(135deg,#141414,#0a0a0a);border:2px solid ${color};box-shadow:0 0 18px ${color}33;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:26px;color:${color};">${(name||'?')[0].toUpperCase()}</div>`;

        // Botón secundario compacto (icono + label) para el grid de acciones
        const actTile = (onclick, icon, label, color) => `<button onclick="${onclick}" style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;background:#111;border:1px solid #232323;border-radius:14px;padding:13px 6px;cursor:pointer;color:#ddd;font-size:11px;font-weight:700;transition:.15s;" onmouseover="this.style.borderColor='${color}';this.style.color='${color}'" onmouseout="this.style.borderColor='#232323';this.style.color='#ddd'"><i class='bx ${icon}' style="font-size:22px;color:${color};"></i><span>${label}</span></button>`;

        const secondaryTiles = [];
        if (isParticipant) secondaryTiles.push(actTile(`openMatchGroupChat('${matchId}','${(m.name||'Partido').replace(/'/g,"\\'")}','${m.captain_home_email||''}')`, 'bx-chat', 'Chat', '#baff00'));
        if (isParticipant) secondaryTiles.push(actTile(`window.MatchDashboard&&window.MatchDashboard.open('${matchId}')`, 'bx-layout', 'Panel', '#baff00'));
        if (isLoggedIn) secondaryTiles.push(actTile(`window.CancheroMatchPlayers&&window.CancheroMatchPlayers.openBetModal('${matchId}','${isCaptain?'captain':isParticipant?'player':'spectator'}')`, 'bx-gift', 'Apuesta', '#ffaa00'));
        if (isParticipant) secondaryTiles.push(actTile(`window.CancheroPolls&&window.CancheroPolls.openCreator('match','${matchId}')`, 'bx-poll', 'Encuesta', '#64b4ff'));
        secondaryTiles.push(actTile(`shareMatch('${matchId}','${(m.name||'').replace(/'/g,"\\'")}','${(m.venue||'').replace(/'/g,"\\'")}','${dateStr}')`, 'bx-share-alt', 'Compartir', '#888'));

        content.innerHTML = `
            ${backBtn}
            <!-- HERO VS -->
            <div style="position:relative;background:radial-gradient(circle at 50% 0%,#16240f 0%,#0a0c0a 60%);border-radius:20px;padding:18px 16px 20px;margin-bottom:14px;border:1px solid rgba(186,255,0,0.18);overflow:hidden;">
                <div style="position:absolute;inset:0;background-image:url('https://www.transparenttextures.com/patterns/dark-mosaic.png');opacity:0.25;"></div>
                <div style="position:relative;display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:14px;">
                    ${typeBadge}${genderBadge}${fmtType?`<span style="background:rgba(186,255,0,0.1);color:var(--accent);font-size:9px;font-weight:900;padding:3px 10px;border-radius:12px;letter-spacing:1px;">${fmtType.toUpperCase()}</span>`:''}
                </div>
                <div style="position:relative;display:flex;align-items:center;justify-content:center;gap:14px;">
                    <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:8px;max-width:120px;">
                        ${escudo(homeLogo, homeName, 'var(--accent)')}
                        <div style="font-size:12px;font-weight:800;text-align:center;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px;">${homeName.toUpperCase()}</div>
                    </div>
                    <div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex-shrink:0;">
                        ${hasResult
                            ? `<div style="font-size:30px;font-weight:900;color:#fff;letter-spacing:2px;">${m.home_score}<span style="color:#555;">-</span>${m.away_score}</div><div style="font-size:9px;color:#888;font-weight:700;letter-spacing:1px;">FINAL</div>`
                            : `<div style="font-size:24px;font-weight:900;color:var(--accent);text-shadow:0 0 12px rgba(186,255,0,0.5);">VS</div><div style="font-size:9px;color:#888;font-weight:700;">${timeOnly||''}</div>`}
                    </div>
                    <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:8px;max-width:120px;">
                        ${escudo(awayLogo, awayName, '#9c88ff')}
                        <div style="font-size:12px;font-weight:800;text-align:center;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:110px;">${awayName.toUpperCase()}</div>
                    </div>
                </div>
                <div style="position:relative;text-align:center;margin-top:14px;color:#aaa;font-size:12px;display:flex;flex-wrap:wrap;gap:10px;justify-content:center;">
                    <span><i class='bx bx-calendar' style="color:var(--accent);"></i> ${dateStr}</span>
                    <span><i class='bx bx-map' style="color:var(--accent);"></i> ${m.venue||m.city||'Sin lugar'}</span>
                </div>
            </div>

            <!-- CHIPS INFO -->
            <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px;">
                <div style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:11px;text-align:center;"><div style="font-size:9px;color:#555;letter-spacing:1px;margin-bottom:3px;">FORMATO</div><div style="font-size:15px;font-weight:900;">${_total===10?'Fútbol 5':_total===14?'Fútbol 7':_total===22?'Fútbol 11':(m.format||'—')}</div></div>
                <div style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:11px;text-align:center;"><div style="font-size:9px;color:#555;letter-spacing:1px;margin-bottom:3px;">LUGARES</div><div style="font-size:15px;font-weight:900;color:${slotsLeft>0?'var(--accent)':'#ff4444'};">${slotsLeft>0?slotsLeft+' libre'+(slotsLeft!==1?'s':''):'LLENO'}</div></div>
                <div style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:11px;text-align:center;"><div style="font-size:9px;color:#555;letter-spacing:1px;margin-bottom:3px;">ANOTADOS</div><div style="font-size:15px;font-weight:900;">${(players||[]).length}</div></div>
            </div>

            <!-- DESAFÍO: estado + aceptar/rechazar (capitán rival) -->
            ${m.challenge_status === 'pending' ? `<div style="margin-top:12px;background:rgba(255,170,0,0.08);border:1px solid rgba(255,170,0,0.3);border-radius:14px;padding:14px;text-align:center;">
                <div style="font-size:12px;color:#ffaa00;font-weight:800;margin-bottom:${(myEmail===m.captain_away_email)?'10px':'0'};">⚔️ Desafío pendiente de aceptación</div>
                ${(myEmail===m.captain_away_email) ? `<div style="display:flex;gap:8px;">
                    <button onclick="window.responderDesafio('${matchId}',true)" style="flex:1;background:var(--accent);color:#000;border:none;border-radius:10px;padding:11px;font-weight:900;font-size:13px;cursor:pointer;">✅ ACEPTAR</button>
                    <button onclick="window.responderDesafio('${matchId}',false)" style="flex:1;background:rgba(255,68,68,0.1);color:#ff4444;border:1px solid rgba(255,68,68,0.3);border-radius:10px;padding:11px;font-weight:700;font-size:13px;cursor:pointer;">RECHAZAR</button>
                </div>` : ''}
            </div>` : m.challenge_status === 'accepted' ? `<div style="margin-top:12px;background:rgba(0,230,118,0.08);border:1px solid rgba(0,230,118,0.3);border-radius:12px;padding:10px;text-align:center;font-size:12px;color:#00e676;font-weight:800;">✅ Desafío aceptado — ¡partido confirmado!</div>` : m.challenge_status === 'rejected' ? `<div style="margin-top:12px;background:rgba(255,68,68,0.08);border:1px solid rgba(255,68,68,0.25);border-radius:12px;padding:10px;text-align:center;font-size:12px;color:#ff4444;font-weight:700;">Desafío rechazado</div>` : ''}

            <!-- ACCIÓN PRINCIPAL -->
            ${joinBtn}${leaveBtn}

            <!-- ACCIONES SECUNDARIAS (grid, sin amontonar) -->
            ${secondaryTiles.length ? `<div style="display:grid;grid-template-columns:repeat(${Math.min(secondaryTiles.length,4)},1fr);gap:8px;margin-top:12px;">${secondaryTiles.join('')}</div>` : ''}

            <!-- GESTIÓN (solo capitán) -->
            ${isCaptain ? `<div style="margin-top:16px;background:#0d0f0d;border:1px solid #1c1c1c;border-radius:16px;padding:14px;">
                <div style="font-size:10px;color:#666;font-weight:900;letter-spacing:1.5px;margin-bottom:10px;">⚙️ GESTIÓN DEL PARTIDO</div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
                    ${actTile(`window.CancheroMatchPlayers&&window.CancheroMatchPlayers.openPlayersPanel('${matchId}')`, 'bx-group', 'Jugadores', '#baff00')}
                    ${actTile(`window._loadAvailablePlayersForMatch('${matchId}','home')`, 'bx-user-plus', 'Invitar', '#00e676')}
                    ${actTile(`editMatchOpen('${matchId}')`, 'bx-edit', 'Editar', '#ffaa00')}
                    ${actTile(`deleteMatch('${matchId}')`, 'bx-trash', 'Eliminar', '#ff4444')}
                </div>
            </div>` : ''}
            <div id="avail-players-for-match-${matchId}" style="display:none;margin-top:12px;"></div>

            <!-- CANCHA Y POSICIONES -->
            <div style="margin-top:16px;background:#0d0f0d;border:1px solid #1c1c1c;border-radius:16px;padding:14px;">
                <div style="font-size:10px;color:#666;font-weight:900;letter-spacing:1.5px;margin-bottom:10px;">⚽ CANCHA Y POSICIONES <span style="font-weight:700;color:#444;letter-spacing:0;">· tocá un jugador para cambiar su posición</span></div>
                <div data-pitch data-team="home" id="vmd-pitch"></div>
            </div>

            <!-- PLANTELES VS -->
            <div style="display:grid;grid-template-columns:1fr auto 1fr;gap:10px;margin-top:18px;align-items:start;">
                <div style="background:#111;border:1px solid rgba(186,255,0,0.15);border-radius:14px;padding:14px;">
                    <div style="font-size:11px;color:var(--accent);font-weight:900;letter-spacing:1px;margin-bottom:10px;">${homeName.toUpperCase().slice(0,12)} (${teamHome.length})</div>
                    ${buildTeamHtml(teamHome,'var(--accent)')}
                </div>
                <div style="align-self:center;font-size:13px;font-weight:900;color:#444;">VS</div>
                <div style="background:#111;border:1px solid rgba(156,136,255,0.15);border-radius:14px;padding:14px;">
                    <div style="font-size:11px;color:#9c88ff;font-weight:900;letter-spacing:1px;margin-bottom:10px;">${awayName.toUpperCase().slice(0,12)} (${teamAway.length})</div>
                    ${buildTeamHtml(teamAway,'#9c88ff')}
                </div>
            </div>
        `;
        // Render de la cancha visual (mismo componente que el panel del partido)
        try {
            var _vmdPitch = document.getElementById('vmd-pitch');
            if (_vmdPitch && window.CancheroPitch) {
                CancheroPitch.render(_vmdPitch, m, players || [], {
                    canJoin: !isParticipant,
                    canManage: isCaptain,
                    onJoin: function(){ if (window.joinOpenMatch) window.joinOpenMatch(matchId); },
                    onTapPlayer: function(p){ CancheroPitch.changePosition(p); }
                });
            }
        } catch(_pe) { console.warn('vmd pitch', _pe); }
    } catch(e) {
        console.error('viewMatchDetails error:', e);
        content.innerHTML = `<div style="padding:20px;color:#f44;text-align:center;">Error al cargar: ${e.message}</div>`;
    }
};

// Cargar jugadores disponibles para invitar al partido (para capitán)
window._loadAvailablePlayersForMatch = async function(matchId, teamDefault) {
    const container = document.getElementById('avail-players-for-match-' + matchId);
    if (!container) return;
    const isVisible = container.style.display !== 'none';
    if (isVisible) { container.style.display = 'none'; return; }
    container.style.display = 'block';
    container.innerHTML = '<div style="text-align:center;padding:20px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:20px;"></i></div>';
    const sb = window._sb;
    if (!sb) return;
    try {
        const me = window.userData;
        // Cargar jugadores disponibles, poner primero al usuario actual si está disponible
        let { data: avail } = await sb.from('users').select('name,email,photo,pos,city,nat,available').eq('available', true).neq('role', 'club').limit(40);
        let _availNote = '';
        if (!avail || !avail.length) {
            // Fallback: que el capitán pueda invitar a CUALQUIER jugador registrado
            const { data: all } = await sb.from('users').select('name,email,photo,pos,city,nat,available').neq('role', 'club').limit(40);
            avail = all || [];
            _availNote = '<div style="font-size:10px;color:#888;margin-bottom:8px;">Nadie está marcado como disponible ahora — te mostramos todos los jugadores.</div>';
        }
        if (!avail.length) {
            container.innerHTML = '<div style="padding:16px;text-align:center;color:#555;font-size:12px;">No hay jugadores para invitar todavía.</div>';
            return;
        }
        // Moverme al inicio si estoy disponible
        const sorted = me && me.available ? [me, ...avail.filter(u => u.email !== me.email)] : avail;
        container.innerHTML = `
            <div style="background:#0a0c0a;border:1px solid rgba(0,230,118,0.2);border-radius:14px;padding:14px;">
                <div style="font-size:11px;color:#00e676;font-weight:900;letter-spacing:1px;margin-bottom:10px;">🟢 JUGADORES DISPONIBLES (${avail.length})</div>
                <div style="font-size:10px;color:#555;margin-bottom:10px;">El invitado elige en qué equipo quiere jugar al aceptar</div>
                ${_availNote}
                ${sorted.map(u => {
                    const ini = (u.name||'?')[0].toUpperCase();
                    const eSafe = (u.email||'').replace(/'/g,"\\'");
                    const nSafe = (u.name||'').replace(/'/g,"\\'");
                    const isMe = me && u.email === me.email;
                    return `<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #111;">
                        <div style="width:36px;height:36px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;font-weight:900;font-size:14px;color:#000;flex-shrink:0;">${ini}</div>
                        <div style="flex:1;min-width:0;">
                            <div style="font-size:13px;font-weight:700;">${u.name||'Jugador'}${isMe?' <span style=\'font-size:9px;color:#00e676;\'>(Vos)</span>':''}</div>
                            <div style="font-size:10px;color:#555;">${u.pos||'JUG'}${u.city?' · '+u.city:''}</div>
                        </div>
                        ${!isMe ? `<button onclick="window._sendMatchInviteToPlayer('${matchId}','${eSafe}','${nSafe}')" style="background:rgba(0,230,118,0.1);color:#00e676;border:1px solid rgba(0,230,118,0.25);border-radius:8px;padding:5px 10px;font-size:10px;font-weight:700;cursor:pointer;flex-shrink:0;white-space:nowrap;">INVITAR</button>` : '<span style="font-size:9px;color:#00e676;font-weight:700;">TÚ</span>'}
                    </div>`;
                }).join('')}
            </div>`;
        window._matchInviteTeam = teamDefault || 'home';
    } catch(e) {
        container.innerHTML = '<div style="padding:12px;color:#f44;font-size:12px;">Error: ' + e.message + '</div>';
    }
};

window._sendMatchInviteToPlayer = async function(matchId, toEmail, toName) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me || !toEmail) return;
    try {
        // Sin equipo asignado: el invitado elige local o visitante al aceptar
        const { error: invErr } = await sb.from('match_invites').upsert({
            match_id: matchId, from_email: me.email, to_email: toEmail, team: null, status: 'pendiente'
        }, { onConflict: 'match_id,to_email' });
        if (invErr) {
            // sin constraint única: insert directo
            const { error: insErr } = await sb.from('match_invites').insert({ match_id: matchId, from_email: me.email, to_email: toEmail, status: 'pendiente' });
            if (insErr) throw insErr;
        }
        // Notificar al jugador
        if (typeof notif !== 'undefined') {
            notif.create(toEmail, 'match_invite', me.name || me.email,
                `⚽ ${me.name||me.email} te invitó a su partido. Revisá tus invitaciones.`);
        }
        if (typeof showToast === 'function') showToast(`✅ Invitación enviada a ${toName}`, 'success');
        // Cambiar botón
        const btns = document.querySelectorAll(`[onclick*="_sendMatchInviteToPlayer('${matchId}','${toEmail.replace(/'/g,"\\'")}"]`);
        btns.forEach(b => { b.textContent = 'ENVIADA ✓'; b.disabled = true; b.style.opacity = '0.5'; });
    } catch(e) {
        if (typeof showToast === 'function') showToast('Error: ' + e.message, 'error');
    }
};

// publishNeedPlayer — marca partido como buscando jugador
window.publishNeedPlayer = async function(matchId) {
    const sb = window._sb;
    if (!sb) return;
    try {
        await sb.from('matches').update({ need_player: true }).eq('id', matchId);
        if(typeof showToast==='function') showToast('¡Publicado! Aparece en "Equipos buscan jugadores".','success');
    } catch(e) {
        if(typeof showToast==='function') showToast('Error al publicar: '+e.message,'error');
    }
};

window.openCourtModal = function() {
    alert('Funcionalidad de agregar cancha próximamente.');
};

