window.switchAdminTab = function(tabId, el) {
    const section = document.getElementById('view-admin');
    if(!section) return;

    section.querySelectorAll('.admin-tab-content').forEach(tab => {
        tab.style.display = 'none';
    });

    const target = document.getElementById('admin-' + tabId);
    if(target) target.style.display = 'block';

    if (el) {
        section.querySelectorAll('.sidebar-menu .menu-item').forEach(item => item.classList.remove('active'));
        el.classList.add('active');
    }

    // Cargar datos según tab
    if (tabId === 'dashboard') { try { renderAdminDashboard(); } catch(e) { console.warn('admin dash', e); } }
    if (tabId === 'jugadores') window._adminLoadPlayers();
    if (tabId === 'negocios') window._adminLoadBusinesses();
    if (tabId === 'codigos') window._adminLoadCodes();
    if (tabId === 'reportes') window._adminLoadReports();
    if (tabId === 'partidos-admin') window._adminLoadMatches();
    if (tabId === 'contenido') window._adminLoadContent();
};

