// Período de filtro para métricas
window._adminSetPeriod = function(period, btn) {
    window._adminPeriod = period;
    document.querySelectorAll('#admin-period-selector button').forEach(b => {
        b.className = b.className.replace('btn-primary','btn-glass');
    });
    if (btn) btn.className = btn.className.replace('btn-glass','btn-primary');
    renderAdminDashboard();
};

function _adminDateFilter(period) {
    const now = new Date();
    if (period === 'hoy') return new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();
    if (period === 'semana') { const d = new Date(now); d.setDate(d.getDate()-7); return d.toISOString(); }
    if (period === 'mes') { const d = new Date(now); d.setMonth(d.getMonth()-1); return d.toISOString(); }
    if (period === 'año') { const d = new Date(now); d.setFullYear(d.getFullYear()-1); return d.toISOString(); }
    return '2020-01-01T00:00:00Z'; // total
}

// Lista real de usuarios en el panel admin (tab Jugadores)
window._adminLoadPlayers = async function() {
    const list = document.getElementById('admin-player-list');
    if (!list) return;
    const sb = window._sb;
    if (!sb) return;
    list.innerHTML = '<div style="color:#555;padding:14px;"><i class="bx bx-loader-alt bx-spin"></i> Cargando usuarios...</div>';
    try {
        const { data } = await sb.from('users').select('email,name,role,city,available,created_at,photo').order('created_at', { ascending: false }).limit(500);
        window._adminAllPlayers = data || [];
        window._adminFilterPlayers('');
    } catch(e) { list.innerHTML = '<p style="color:#f44;">Error: '+e.message+'</p>'; }
};

// Detección robusta de bot: email patrón bot-*@canchero.app
window._isBot = function(u) {
    const e = (u.email || '').toLowerCase();
    return (e.includes('bot-') && e.includes('@canchero.app')) || e.startsWith('bot') && e.includes('@canchero');
};

window._adminFilterPlayers = function(query) {
    const list = document.getElementById('admin-player-list');
    if (!list) return;
    const filter = (document.getElementById('admin-player-filter')?.value || '').toLowerCase();
    const q = (query || '').toLowerCase();
    let players = window._adminAllPlayers || [];
    if (q) players = players.filter(u => (u.name||'').toLowerCase().includes(q) || (u.email||'').toLowerCase().includes(q));
    if (filter === 'bot') players = players.filter(u => window._isBot(u));
    else if (filter) players = players.filter(u => u.role === filter);

    const botCount = (window._adminAllPlayers||[]).filter(u => window._isBot(u)).length;
    const bulkBtn = botCount > 0 ? `<button onclick="window._adminDeleteAllBots()" style="background:rgba(255,68,68,0.12);border:1px solid rgba(255,68,68,0.4);color:#ff4444;border-radius:10px;padding:8px 14px;font-size:11px;font-weight:800;cursor:pointer;margin-bottom:10px;"><i class='bx bx-trash'></i> ELIMINAR TODOS LOS BOTS (${botCount})</button>` : '';

    if (!players.length) { list.innerHTML = bulkBtn + '<p style="color:#888;">Sin resultados.</p>'; return; }
    list.innerHTML = bulkBtn + `<div style="font-size:11px;color:#555;margin-bottom:8px;">${players.length} usuario${players.length!==1?'s':''}</div>` + players.map(u => `
        <div style="background:rgba(255,255,255,0.04);padding:12px 14px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;gap:10px;">
            <div style="min-width:0;flex:1;">
                <div style="font-weight:700;color:#fff;font-size:13px;">${u.name||u.email} ${u.available?'<span style="color:#00e676;font-size:9px;">● disp.</span>':''}${u.account_status==='suspendido'?'<span style="color:#ffb400;font-size:9px;"> ● susp.</span>':''}</div>
                <div style="font-size:11px;color:#888;">${u.email} · <span style="color:var(--accent);">${u.role||'jugador'}</span>${u.city?' · '+u.city:''}</div>
            </div>
            <div style="display:flex;gap:6px;align-items:center;">
                ${u.account_status==='suspendido'
                  ? `<button onclick="window._adminSuspendUser('${(u.email||'').replace(/'/g,"\\'")}',false)" style="background:rgba(0,230,118,0.1);border:1px solid rgba(0,230,118,0.35);color:#00e676;border-radius:8px;padding:6px 10px;font-size:10px;font-weight:700;cursor:pointer;">ACTIVAR</button>`
                  : `<button onclick="window._adminSuspendUser('${(u.email||'').replace(/'/g,"\\'")}',true)" style="background:rgba(255,180,0,0.1);border:1px solid rgba(255,180,0,0.35);color:#ffb400;border-radius:8px;padding:6px 10px;font-size:10px;font-weight:700;cursor:pointer;">SUSP.</button>`}
                <button onclick="window._adminDeleteUser('${(u.email||'').replace(/'/g,"\\'")}')" title="Eliminar" style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);color:#ff4444;border-radius:8px;padding:6px 10px;font-size:10px;font-weight:700;cursor:pointer;">ELIMINAR</button>
            </div>
        </div>`).join('');
};

window._adminDeleteAllBots = async function() {
    const bots = (window._adminAllPlayers||[]).filter(u => window._isBot(u));
    if (!bots.length) { showToast && showToast('No hay bots para eliminar.', 'info'); return; }
    if (!confirm('¿Eliminar ' + bots.length + ' bots? Esto borra todos los usuarios bot-*@canchero.app y sus datos. No se puede deshacer.')) return;
    const sb = window._sb;
    if (!sb) return;
    const list = document.getElementById('admin-player-list');
    if (list) list.innerHTML = '<div style="color:#555;padding:14px;"><i class="bx bx-loader-alt bx-spin"></i> Eliminando bots...</div>';
    let deleted = 0;
    for (const b of bots) {
        try {
            await sb.from('users').delete().eq('email', b.email);
            try { await sb.from('posts').delete().eq('user_email', b.email); } catch(e){}
            try { await sb.from('stories').delete().eq('user_email', b.email); } catch(e){}
            try { await sb.from('match_players').delete().eq('player_email', b.email); } catch(e){}
            deleted++;
        } catch(e){}
    }
    if (typeof showToast === 'function') showToast('✅ ' + deleted + ' bots eliminados', 'success');
    window._adminLoadPlayers();
};

window._adminDeleteUser = async function(email, reload) {
    if (!confirm('¿Eliminar usuario ' + email + '? Esta acción no se puede deshacer.')) return;
    const sb = window._sb;
    if (!sb) return;
    try {
        // Intentar RPC — puede devolver "Cannot coerce" en void, lo cual no es error real
        let rpcOk = false;
        try {
            const { error: rpcErr } = await sb.rpc('admin_delete_user', { p_email: email });
            if (!rpcErr) rpcOk = true;
            // "Cannot coerce" = la función corrió bien pero Supabase no puede parsear void
            if (rpcErr && rpcErr.message && rpcErr.message.includes('coerce')) rpcOk = true;
        } catch(e) {
            if (e.message && e.message.includes('coerce')) rpcOk = true;
        }
        if (!rpcOk) {
            // Fallback directo tabla por tabla
            try { await sb.from('match_players').delete().eq('player_email', email); } catch(e){}
            try { await sb.from('stories').delete().eq('user_email', email); } catch(e){}
            try { await sb.from('posts').delete().eq('user_email', email); } catch(e){}
            try { await sb.from('business_requests').delete().eq('email', email); } catch(e){}
            const { error } = await sb.from('users').delete().eq('email', email);
            if (error) throw error;
        }
        if (typeof showToast === 'function') showToast('Usuario eliminado: ' + email, 'success');
        if (reload === 'biz') window._adminLoadBusinesses(); else window._adminLoadPlayers();
    } catch(e) {
        if (typeof showToast === 'function') showToast('Error: ' + e.message, 'error');
    }
};

// Suspender / reactivar una cuenta (account_status). suspend=true → suspendida.
window._adminSuspendUser = async function(email, suspend, reload) {
    const sb = window._sb;
    if (!sb) return;
    const nuevo = suspend ? 'suspendido' : 'activo';
    if (!confirm((suspend ? 'Suspender' : 'Reactivar') + ' la cuenta ' + email + '?')) return;
    try {
        // RPC SECURITY DEFINER (bypasea RLS) — void puede dar "Cannot coerce", ignorar
        let rpcOk = false;
        try {
            const { error: rpcErr } = await sb.rpc('admin_set_account_status', { p_email: email, p_status: nuevo });
            rpcOk = !rpcErr || (rpcErr.message && rpcErr.message.includes('coerce'));
        } catch(e) { rpcOk = e.message && e.message.includes('coerce'); }
        if (!rpcOk) {
            const { error } = await sb.from('users').update({ account_status: nuevo, sub_status: suspend ? 'suspendido' : 'active' }).eq('email', email);
            if (error) throw error;
        }
        try { if (window.CancheroNotif) CancheroNotif.create(email, 'cuenta', 'Canchero', suspend ? 'Tu cuenta fue suspendida por el equipo de Canchero.' : 'Tu cuenta fue reactivada. ¡Bienvenido de vuelta!'); } catch(e){}
        if (typeof showToast === 'function') showToast(suspend ? 'Cuenta suspendida.' : 'Cuenta reactivada.', 'success');
        if (reload === 'biz') window._adminLoadBusinesses(); else window._adminLoadPlayers();
    } catch(e) {
        if (typeof showToast === 'function') showToast('Error: ' + e.message, 'error');
    }
};

// Negocios (complejos, tiendas, organizaciones, profesionales)
// Solicitudes de negocios pendientes: aprobar (genera codigo) / rechazar
// GESTIÓN DE NEGOCIOS (el flujo de solicitudes/códigos fue RETIRADO — los negocios
// se registran gratis y auto-activados). El admin puede SUSPENDER o ELIMINAR.
window._adminLoadBizRequests = async function() {
    const box = document.getElementById('admin-biz-requests');
    if (!box) return;
    const sb = window._sb;
    try {
        const { data } = await sb.from('business_requests').select('*').order('created_at', { ascending: false }).limit(200);
        const rows = data || [];
        if (!rows.length) { box.innerHTML = '<div style="font-size:12px;color:#666;">No hay negocios registrados.</div>'; return; }
        const roleLbl = { tienda:'Tienda', club:'Complejo', complejo:'Complejo', organizacion:'Organización', profesional:'Profesional', sponsor:'Sponsor' };
        const card = (r) => {
            const st = String(r.status || '').toUpperCase();
            const susp = st.startsWith('SUSP');
            return `<div style="display:flex;align-items:center;gap:10px;background:rgba(255,255,255,0.04);padding:12px 14px;border-radius:12px;border-left:3px solid ${susp ? '#ffb400' : '#00e676'};margin-bottom:8px;">
                <div style="flex:1;min-width:0;">
                    <div style="font-weight:800;color:#fff;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${r.name || r.email} ${susp ? '<span style="font-size:9px;color:#ffb400;font-weight:900;letter-spacing:1px;">· SUSPENDIDO</span>' : ''}</div>
                    <div style="font-size:10.5px;color:#888;">${r.email} · ${roleLbl[(r.role||'').toLowerCase()] || r.role || ''} · ${r.created_at ? new Date(r.created_at).toLocaleDateString('es-UY') : ''}</div>
                </div>
                <button onclick="window._adminToggleSuspendBiz('${r.id}', ${susp ? 'false' : 'true'})" title="${susp?'Reactivar':'Suspender'}" style="background:${susp?'rgba(0,230,118,0.1)':'rgba(255,180,0,0.1)'};border:1px solid ${susp?'rgba(0,230,118,0.35)':'rgba(255,180,0,0.35)'};color:${susp?'#00e676':'#ffb400'};border-radius:8px;padding:7px 11px;font-size:11px;font-weight:800;cursor:pointer;flex-shrink:0;">${susp?'REACTIVAR':'SUSPENDER'}</button>
                <button onclick="window._adminDeleteBizRow('${r.id}','${(r.name||'').replace(/'/g,'')}')" title="Eliminar negocio" style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);color:#ff4444;border-radius:8px;padding:7px 11px;font-size:11px;font-weight:700;cursor:pointer;flex-shrink:0;"><i class='bx bx-trash'></i></button>
            </div>`;
        };
        box.innerHTML = `<div style="font-size:12px;font-weight:900;color:var(--accent);letter-spacing:1px;margin-bottom:10px;"><i class='bx bx-buildings'></i> NEGOCIOS REGISTRADOS (${rows.length})</div>` + rows.map(card).join('');
    } catch(e) { box.innerHTML = '<p style="color:#f44;font-size:12px;">Error negocios: ' + e.message + '</p>'; }
};
// Suspender / reactivar un negocio (deja de operar pero conserva sus datos)
window._adminToggleSuspendBiz = async function(reqId, suspend) {
    const sb = window._sb;
    try {
        const { error } = await sb.from('business_requests').update({ status: suspend ? 'SUSPENDIDO' : 'APROBADO' }).eq('id', reqId);
        if (error) throw error;
        showToast(suspend ? 'Negocio suspendido.' : 'Negocio reactivado.', 'success');
        window._adminLoadBizRequests();
    } catch(e) { showToast('Error: ' + (e.message || ''), 'error'); }
};

window._adminApproveBiz = async function(reqId) {
    const sb = window._sb;
    const code = 'CAN-' + Date.now().toString(36).toUpperCase().slice(-4) + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
    try {
        const { data: reqArr } = await sb.from('business_requests').select('email,role').eq('id', reqId).limit(1);
        const req = reqArr && reqArr[0] ? reqArr[0] : null;
        const { error } = await sb.from('business_requests').update({ status: 'APROBADO', approval_code: code, code_used: false }).eq('id', reqId);
        if (error) throw error;
        if (req) {
            try { await sb.from('users').update({ role: req.role }).eq('email', req.email); } catch(e) {}
            try { if (window.CancheroNotif) CancheroNotif.create(req.email, 'biz_approved', 'Canchero', 'Tu cuenta fue APROBADA. Inicia sesion e ingresa el codigo de activacion que te enviamos.'); } catch(e) {}
        }
        showToast('Aprobado. Codigo: ' + code + ' — envialo por WhatsApp o email.', 'success');
        window._adminLoadBizRequests();
    } catch(e) { showToast('Error al aprobar: ' + (e.message || ''), 'error'); }
};
window._adminRejectBiz = async function(reqId) {
    if (!confirm('Rechazar y ELIMINAR esta solicitud? Desaparece de la lista.')) return;
    const sb = window._sb;
    try {
        const { data: reqArr } = await sb.from('business_requests').select('email').eq('id', reqId).limit(1);
        const reqEmail = reqArr && reqArr[0] ? reqArr[0].email : null;
        // Borrar la solicitud (no solo marcarla) para que no quede en la lista
        const { error } = await sb.from('business_requests').delete().eq('id', reqId);
        if (error) throw error;
        try { if (reqEmail && window.CancheroNotif) CancheroNotif.create(reqEmail, 'biz_rejected', 'Canchero', 'Tu solicitud de cuenta de negocio fue rechazada. Escribinos si crees que es un error.'); } catch(e) {}
        showToast('Solicitud rechazada y eliminada.', 'default');
        window._adminLoadBizRequests();
    } catch(e) { showToast('Error: ' + (e.message || ''), 'error'); }
};
// Eliminar un negocio del sistema (con verificación de que realmente se borró —
// antes un delete bloqueado por RLS "pasaba" en silencio sin borrar nada)
window._adminDeleteBizRow = async function(reqId, name) {
    if (!confirm('¿Eliminar el negocio "' + (name||'') + '"? Se borra su registro definitivamente.')) return;
    const sb = window._sb;
    try {
        const { data: del, error } = await sb.from('business_requests').delete().eq('id', reqId).select('id');
        if (error) throw error;
        if (!del || !del.length) { showToast('No se pudo borrar (permisos RLS): iniciá sesión con la cuenta ADMIN real.', 'error'); return; }
        showToast('Negocio eliminado.', 'success');
        window._adminLoadBizRequests();
    } catch(e) { showToast('Error: ' + (e.message || ''), 'error'); }
};
// ── Admin: gestión de CLUBES (listar + eliminar) ──────────────────────────
window._adminLoadClubs = async function() {
    const box = document.getElementById('admin-clubs-list');
    if (!box) return;
    const sb = window._sb;
    try {
        const { data } = await sb.from('clubs').select('id,name,city,nat,owner_email,created_at').order('created_at', { ascending: false }).limit(100);
        if (!data || !data.length) { box.innerHTML = '<div style="font-size:12px;color:#666;">No hay clubes registrados.</div>'; return; }
        box.innerHTML = `<div style="font-size:12px;font-weight:900;color:var(--accent);letter-spacing:1px;margin-bottom:10px;"><i class='bx bx-shield'></i> CLUBES (${data.length})</div>` +
            data.map(c => `<div style="display:flex;align-items:center;gap:10px;background:rgba(255,255,255,0.04);padding:10px 12px;border-radius:10px;margin-bottom:8px;">
                <div style="flex:1;min-width:0;"><div style="font-weight:800;color:#fff;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${(c.name||'Sin nombre')}</div><div style="font-size:10px;color:#888;">${[c.city,c.nat].filter(Boolean).join(', ')||'—'} · ${c.owner_email||'sin dueño'}</div></div>
                <button onclick="window._adminDeleteClub('${c.id}','${(c.name||'').replace(/'/g,"\\'")}')" style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);color:#ff4444;border-radius:8px;padding:7px 11px;font-size:11px;font-weight:700;cursor:pointer;flex-shrink:0;"><i class='bx bx-trash'></i></button>
            </div>`).join('');
    } catch(e) { box.innerHTML = '<div style="font-size:12px;color:#f66;">Error clubes: ' + (e.message||'') + '</div>'; }
};
window._adminDeleteClub = async function(clubId, clubName) {
    if (!confirm('¿Eliminar el club "' + (clubName||'') + '"? Se borra el club y su plantilla. No se puede deshacer.')) return;
    const sb = window._sb;
    try {
        try { await sb.from('club_members').delete().eq('club_id', clubId); } catch(e) {}
        try { await sb.from('club_follows').delete().eq('club_id', String(clubId)); } catch(e) {}
        const { error } = await sb.from('clubs').delete().eq('id', clubId);
        if (error) throw error;
        showToast('Club eliminado.', 'success');
        window._adminLoadClubs();
    } catch(e) { showToast('Error al eliminar: ' + (e.message||''), 'error'); }
};

window._adminLoadSponsors = async function() {
    const box = document.getElementById('admin-sponsor-requests');
    if (!box) return;
    const sb = window._sb;
    try {
        const { data } = await sb.from('sponsor_requests').select('*').order('created_at', { ascending: false }).limit(40);
        if (!data || !data.length) { box.innerHTML = '<div style="font-size:12px;color:#666;"><i class="bx bx-dollar-circle"></i> Sin solicitudes de sponsors.</div>'; return; }
        const card = (r) => `<div style="background:rgba(255,255,255,0.04);padding:12px 14px;border-radius:12px;border-left:3px solid #baff00;margin-bottom:8px;">
            <div style="display:flex;justify-content:space-between;gap:10px;">
              <div style="min-width:0;">
                <div style="font-weight:800;color:#fff;font-size:14px;">${(r.company||'Sin nombre')}</div>
                <div style="font-size:11px;color:#baff00;font-weight:700;">${(r.type||'Sponsor')}</div>
                <div style="font-size:11px;color:#aaa;margin-top:3px;">${(r.contact||'')} · <a href="mailto:${r.email||''}" style="color:#64b4ff;">${r.email||''}</a>${r.phone?(' · '+r.phone):''}</div>
                ${r.budget?`<div style="font-size:11px;color:#888;margin-top:2px;">Presupuesto: ${r.budget}</div>`:''}
                ${r.message?`<div style="font-size:11px;color:#ccc;margin-top:6px;background:rgba(0,0,0,0.3);padding:7px 9px;border-radius:8px;">${(r.message||'').replace(/</g,'&lt;')}</div>`:''}
              </div>
              <div style="font-size:10px;color:#555;white-space:nowrap;">${r.created_at?new Date(r.created_at).toLocaleDateString('es-UY'):''}</div>
            </div>
          </div>`;
        box.innerHTML = `<div style="font-size:12px;font-weight:900;color:#baff00;letter-spacing:1px;margin-bottom:10px;"><i class='bx bx-dollar-circle'></i> SOLICITUDES DE SPONSORS (${data.length})</div>` + data.map(card).join('');
    } catch(e) { box.innerHTML = '<div style="font-size:12px;color:#f66;">Error sponsors: ' + (e.message||'') + '</div>'; }
};

window._adminLoadBusinesses = async function() {
    window._adminLoadBizRequests();
    window._adminLoadSponsors();
    try { window._adminLoadClubs(); } catch(e) {}
    const list = document.getElementById('admin-business-list');
    if (!list) return;
    const sb = window._sb;
    if (!sb) return;
    list.innerHTML = '<div style="color:#555;padding:14px;"><i class="bx bx-loader-alt bx-spin"></i> Cargando negocios...</div>';
    try {
        const { data } = await sb.from('users').select('*').in('role', ['club','complejo','tienda','profesional','organizacion','sponsor']).order('created_at', { ascending: false });
        if (!data || !data.length) { list.innerHTML = '<p style="color:#888;">Sin negocios registrados.</p>'; return; }
        list.innerHTML = data.map(u => {
            const roleMap = { club:'Complejo', complejo:'Complejo', tienda:'Tienda', profesional:'Profesional', organizacion:'Organización', sponsor:'Sponsor' };
            const roleColor = { club:'#64b4ff', complejo:'#64b4ff', tienda:'#ff9800', profesional:'#9c88ff', organizacion:'#ff96c8', sponsor:'#baff00' };
            return `<div style="background:rgba(255,255,255,0.04);padding:14px;border-radius:12px;border-left:3px solid ${roleColor[u.role]||'#888'};">
                <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;">
                    <div style="min-width:0;flex:1;">
                        <div style="font-weight:700;color:#fff;font-size:14px;">${u.name||u.email}</div>
                        <div style="font-size:11px;color:#888;margin-top:2px;">${u.email}${u.city?' · '+u.city:''}</div>
                        <div style="display:inline-block;margin-top:6px;padding:2px 10px;border-radius:6px;font-size:10px;font-weight:800;color:${roleColor[u.role]||'#888'};background:${roleColor[u.role]||'#888'}22;">${(roleMap[u.role]||u.role).toUpperCase()}</div>
                        ${u.access_code ? '<span style="margin-left:8px;font-size:10px;color:#00e676;">● Código activo</span>' : '<span style="margin-left:8px;font-size:10px;color:#ff4444;">● Sin código</span>'}
                        ${u.account_status==='suspendido' ? '<span style="margin-left:8px;font-size:10px;color:#ffb400;">● SUSPENDIDA</span>' : ''}
                    </div>
                    <div style="display:flex;flex-direction:column;gap:6px;">
                        ${u.account_status==='suspendido'
                          ? `<button onclick="window._adminSuspendUser('${(u.email||'').replace(/'/g,"\\'")}',false,'biz')" style="background:rgba(0,230,118,0.1);border:1px solid rgba(0,230,118,0.35);color:#00e676;border-radius:8px;padding:6px 12px;font-size:10px;font-weight:700;cursor:pointer;">ACTIVAR</button>`
                          : `<button onclick="window._adminSuspendUser('${(u.email||'').replace(/'/g,"\\'")}',true,'biz')" style="background:rgba(255,180,0,0.1);border:1px solid rgba(255,180,0,0.35);color:#ffb400;border-radius:8px;padding:6px 12px;font-size:10px;font-weight:700;cursor:pointer;">SUSPENDER</button>`}
                        <button onclick="window._adminDeleteUser('${(u.email||'').replace(/'/g,"\\'")}','biz')" style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);color:#ff4444;border-radius:8px;padding:6px 12px;font-size:10px;font-weight:700;cursor:pointer;">ELIMINAR</button>
                    </div>
                </div>
            </div>`;
        }).join('');
    } catch(e) { list.innerHTML = '<p style="color:#f44;">Error: '+e.message+'</p>'; }
};

// Sistema de códigos de acceso mensuales
window._adminGenerateCode = async function() {
    const sb = window._sb;
    if (!sb) return;
    const code = 'CAN-' + Date.now().toString(36).toUpperCase().slice(-4) + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
    const now = new Date();
    const expiresAt = new Date(now.getFullYear(), now.getMonth() + 1, 1); // 1ro del mes siguiente
    try {
        await sb.from('access_codes').insert({
            code: code,
            created_at: now.toISOString(),
            expires_at: expiresAt.toISOString(),
            used: false,
            used_by: null
        });
        if (typeof showToast === 'function') showToast('Código generado: ' + code, 'success');
        window._adminLoadCodes();
    } catch(e) {
        // Si la tabla no existe, guardar en localStorage como fallback
        var codes = JSON.parse(localStorage.getItem('canchero_access_codes') || '[]');
        codes.push({ code, created_at: now.toISOString(), expires_at: expiresAt.toISOString(), used: false, used_by: null });
        localStorage.setItem('canchero_access_codes', JSON.stringify(codes));
        if (typeof showToast === 'function') showToast('Código generado (local): ' + code, 'success');
        window._adminLoadCodes();
    }
};

window._adminBulkGenerateCodes = async function() {
    for (var i = 0; i < 10; i++) {
        await window._adminGenerateCode();
    }
};

window._adminLoadCodes = async function() {
    const list = document.getElementById('admin-codes-list');
    if (!list) return;
    const sb = window._sb;
    var codes = [];
    try {
        if (sb) {
            const { data } = await sb.from('access_codes').select('*').order('created_at', { ascending: false });
            if (data) codes = data;
        }
    } catch(e) {}
    // Fallback local
    if (!codes.length) {
        codes = JSON.parse(localStorage.getItem('canchero_access_codes') || '[]');
    }
    if (!codes.length) { list.innerHTML = '<p style="color:#888;">No hay códigos generados. Generá uno nuevo.</p>'; return; }
    const now = new Date();
    list.innerHTML = codes.map(c => {
        const expired = new Date(c.expires_at) < now;
        const status = c.used ? `<span style="color:#64b4ff;">Usado por ${c.used_by||'—'}</span>` : expired ? '<span style="color:#ff4444;">Expirado</span>' : '<span style="color:#00e676;">Disponible</span>';
        return `<div style="background:rgba(255,255,255,0.04);padding:14px;border-radius:12px;display:flex;justify-content:space-between;align-items:center;gap:10px;border-left:3px solid ${c.used?'#64b4ff':expired?'#ff4444':'#00e676'};">
            <div>
                <div style="font-family:monospace;font-size:16px;font-weight:900;color:#fff;letter-spacing:2px;">${c.code}</div>
                <div style="font-size:10px;color:#555;margin-top:4px;">Expira: ${new Date(c.expires_at).toLocaleDateString('es-UY')} · ${status}</div>
            </div>
            <div style="display:flex;gap:6px;">
                <button onclick="navigator.clipboard.writeText('${c.code}');showToast&&showToast('Copiado!','success')" style="background:#1a1a1a;border:1px solid #2a2a2a;color:#aaa;border-radius:8px;padding:6px 10px;font-size:10px;cursor:pointer;"><i class='bx bx-copy'></i></button>
                ${!c.used && !expired ? `<button onclick="window._adminRevokeCode('${c.code}')" style="background:rgba(255,68,68,0.1);border:1px solid rgba(255,68,68,0.3);color:#ff4444;border-radius:8px;padding:6px 10px;font-size:10px;cursor:pointer;">REVOCAR</button>` : ''}
            </div>
        </div>`;
    }).join('');
};

window._adminRevokeCode = async function(code) {
    const sb = window._sb;
    try {
        if (sb) await sb.from('access_codes').delete().eq('code', code);
    } catch(e) {}
    var codes = JSON.parse(localStorage.getItem('canchero_access_codes') || '[]');
    codes = codes.filter(c => c.code !== code);
    localStorage.setItem('canchero_access_codes', JSON.stringify(codes));
    if (typeof showToast === 'function') showToast('Código revocado', 'success');
    window._adminLoadCodes();
};

