// Link secreto admin: overlay AUTÓNOMO con #panel-canchero (no depende de otros modales)
window.openAdminLogin = function() {
    if (document.getElementById('admin-login-overlay')) return;
    const o = document.createElement('div');
    o.id = 'admin-login-overlay';
    o.style.cssText = 'position:fixed;inset:0;z-index:100000;background:#070807;display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    o.innerHTML = `<div style="background:#0f110f;border:1px solid rgba(186,255,0,0.25);border-radius:20px;width:100%;max-width:380px;padding:28px 24px;box-shadow:0 0 50px rgba(186,255,0,0.08);">
        <div style="text-align:center;margin-bottom:20px;">
            <div style="font-size:34px;">🔐</div>
            <div style="font-family:Outfit,sans-serif;font-size:20px;font-weight:900;color:var(--accent);margin-top:6px;">PANEL ADMIN</div>
            <div style="font-size:11px;color:#666;margin-top:2px;">Acceso exclusivo Canchero</div>
        </div>
        <input id="admin-login-email" type="email" placeholder="Correo" value="neurovidstudioia@gmail.com" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:13px;color:#fff;font-size:14px;margin-bottom:10px;box-sizing:border-box;">
        <input id="admin-login-pass" type="password" placeholder="Contraseña" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:13px;color:#fff;font-size:14px;margin-bottom:8px;box-sizing:border-box;" onkeydown="if(event.key==='Enter')window._doAdminLogin()">
        <div id="admin-login-err" style="display:none;color:#ff4444;font-size:12px;margin-bottom:8px;"></div>
        <button onclick="window._doAdminLogin()" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:15px;cursor:pointer;margin-top:6px;">INGRESAR</button>
        <button onclick="document.getElementById('admin-login-overlay').remove();location.hash='';" style="width:100%;background:transparent;border:none;color:#555;padding:12px;cursor:pointer;font-size:12px;margin-top:4px;">Cancelar</button>
    </div>`;
    document.body.appendChild(o);
    setTimeout(()=>{ const p=document.getElementById('admin-login-pass'); if(p)p.focus(); }, 200);
};
window._ADMIN_EMAILS = ['neurovidstudioia@gmail.com'];
window._doAdminLogin = async function() {
    const email = (document.getElementById('admin-login-email')?.value||'').trim().toLowerCase();
    const pass = (document.getElementById('admin-login-pass')?.value||'').trim();
    const err = document.getElementById('admin-login-err');
    // Seguridad: validar con el login REAL de Supabase (la contraseña ya no está en el código).
    // El admin se concede solo si el email está en la allowlist Y la sesión de Supabase es válida.
    if (!window._ADMIN_EMAILS.includes(email)) { if (err) { err.textContent = 'Esta cuenta no es de administrador.'; err.style.display='block'; } return; }
    const _sbA = window._sb;
    if (!_sbA) { if (err) { err.textContent = 'Sin conexión.'; err.style.display='block'; } return; }
    let _ok = false;
    try { const { error: e } = await _sbA.auth.signInWithPassword({ email, password: pass }); _ok = !e; } catch(_e){ _ok = false; }
    if (_ok) {
        window.userData = { name: 'SUPER ADMIN', email: email, role: 'admin' };
        try { localStorage.setItem('canchero_user', JSON.stringify(window.userData)); } catch(e){}
        window._adminMode = true;
        document.getElementById('admin-login-overlay')?.remove();
        try { navigate('admin'); } catch(e){}
        try { renderAdminDashboard(); } catch(e){}
        // Guard: forzar la vista admin con !important para ganarle al restore que la re-oculta
        function _forceAdmin() {
            const av = document.getElementById('view-admin');
            if (!av) return;
            document.querySelectorAll('.view-section').forEach(v => { if (v !== av) v.style.display = 'none'; });
            av.style.setProperty('display', 'block', 'important');
            document.body.classList.remove('is-home');
        }
        _forceAdmin();
        let _g = 0;
        const _iv = setInterval(function(){ _g++; if (window._adminMode) _forceAdmin(); if (_g >= 24) clearInterval(_iv); }, 250);
    } else {
        if (err) { err.textContent = 'Credenciales incorrectas.'; err.style.display='block'; }
    }
};
(function(){
    function _isAdminHash() {
        const h = (window.location.hash||'').toLowerCase();
        return h === '#panel-canchero' || window.__bootHash === '#panel-canchero';
    }
    function _checkSecretAdmin() {
        if (_isAdminHash() && !document.getElementById('admin-login-overlay')) {
            let tries = 0;
            const iv = setInterval(function(){
                tries++;
                if (typeof window.openAdminLogin === 'function') { clearInterval(iv); window.openAdminLogin(); window.__bootHash=''; }
                else if (tries > 40) clearInterval(iv);
            }, 200);
        }
    }
    // Chequear en varios momentos (el routing puede pisar el hash en el load)
    if (document.readyState === 'loading') window.addEventListener('load', _checkSecretAdmin);
    setTimeout(_checkSecretAdmin, 300);
    setTimeout(_checkSecretAdmin, 1500);
    setTimeout(_checkSecretAdmin, 3000);
    window.addEventListener('hashchange', _checkSecretAdmin);
})();

// ── Monitoreo de sistema (Supabase, storage, noticias) para el panel admin ──
window._renderAdminSystemMonitor = async function() {
    const box = document.getElementById('admin-sys-monitor');
    const sb = window._sb;
    if (!box) return;
    box.innerHTML = '<div style="color:#555;padding:14px;text-align:center;"><i class="bx bx-loader-alt bx-spin"></i> Cargando monitoreo del sistema...</div>';
    async function cntAll(table){ try { const { count } = await sb.from(table).select('*',{count:'exact',head:true}); return count||0; } catch(e){ return 0; } }
    // Tablas que más crecen (impactan storage/DB)
    const [momentos, mediaPosts, debates, pollVotes, msgs, groupMsgs, waitlist, saved] = await Promise.all([
        cntAll('momentos'),
        (async()=>{ try{ const {count}=await sb.from('posts').select('*',{count:'exact',head:true}).not('media_url','is',null); return count||0; }catch(e){return 0;} })(),
        cntAll('debates'),
        cntAll('poll_votes'),
        cntAll('messages'),
        cntAll('group_messages'),
        cntAll('waitlist'),
        cntAll('saved_posts'),
    ]);
    // Estado del feed de noticias (no ocupa storage: se sirve en vivo)
    let newsStatus = 'desconocido', newsN = 0;
    try { const r = await fetch('/api/news'); const j = await r.json(); newsStatus = j.source==='gnews'?'GNews (real)':'respaldo'; newsN = (j.articles||[]).length; } catch(e){ newsStatus='sin conexión'; }
    // Estimación MUY aproximada de media (no exacta; el dato real está en Supabase Storage)
    const estMediaMB = Math.round((momentos*1.5 + mediaPosts*0.4)); // ~1.5MB/momento, ~0.4MB/foto post
    const FREE_STORAGE_MB = 1024; // Free tier Supabase = 1GB
    const pct = Math.min(100, Math.round(estMediaMB/FREE_STORAGE_MB*100));
    const barColor = pct>80?'#ff4444':pct>50?'#ffaa00':'#00e676';
    const row = (label,val,sub) => `<div style="display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid #161616;"><span style="font-size:12px;color:#aaa;">${label}</span><span style="font-size:13px;font-weight:800;color:#fff;text-align:right;">${val}${sub?`<div style="font-size:9px;color:#666;font-weight:400;">${sub}</div>`:''}</span></div>`;
    box.innerHTML = `
        <div style="font-size:11px;color:#666;font-weight:800;letter-spacing:1px;margin:18px 0 12px;"><i class='bx bx-server' style="color:var(--accent);"></i> MONITOREO DEL SISTEMA</div>
        <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:14px;padding:16px;margin-bottom:14px;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span style="font-size:12px;color:#aaa;">Storage estimado (media)</span><span style="font-size:13px;font-weight:800;color:${barColor};">~${estMediaMB} MB / ${FREE_STORAGE_MB} MB</span></div>
            <div style="height:8px;background:#1a1a1a;border-radius:4px;overflow:hidden;"><div style="height:100%;width:${pct}%;background:${barColor};"></div></div>
            <div style="font-size:10px;color:#666;margin-top:6px;">Estimación aproximada. El valor exacto está en Supabase → Storage. ${pct>80?'<b style="color:#ff4444;">Cerca del límite del plan Free: considerá Supabase Pro o limpiar media vieja.</b>':''}</div>
        </div>
        <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:14px;padding:16px;margin-bottom:14px;">
            ${row('Momentos (fotos/videos)', momentos, '~1.5 MB c/u')}
            ${row('Posts con media', mediaPosts)}
            ${row('Mensajes (DM)', msgs)}
            ${row('Mensajes de grupo', groupMsgs)}
            ${row('Debates', debates)}
            ${row('Votos de encuestas', pollVotes)}
            ${row('Noticias en el feed', newsStatus + ' · ' + newsN + ' notas', 'no ocupa storage (se sirve en vivo, 3/hora)')}
            ${row('Publicaciones guardadas', saved)}
        </div>
        <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:14px;padding:16px;margin-bottom:14px;">
            <div style="display:flex;justify-content:space-between;align-items:center;"><span style="font-size:13px;color:#fff;font-weight:800;"><i class='bx bx-list-check' style="color:var(--accent);"></i> Lista de espera (APK)</span><span style="font-size:20px;font-weight:900;color:var(--accent);">${waitlist}</span></div>
            <button onclick="window._adminViewWaitlist&&window._adminViewWaitlist()" style="width:100%;margin-top:10px;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:9px;font-size:12px;font-weight:800;cursor:pointer;">Ver anotados</button>
        </div>
        <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:14px;padding:16px;margin-bottom:14px;">
            <div style="font-size:13px;color:#fff;font-weight:800;margin-bottom:8px;"><i class='bx bx-bar-chart-alt-2' style="color:var(--accent);"></i> Analíticas de uso</div>
            <div style="font-size:11px;color:#888;margin-bottom:10px;">Qué secciones usan más, clicks y actividad de los usuarios.</div>
            <button onclick="window._adminViewAnalytics&&window._adminViewAnalytics()" style="width:100%;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:9px;font-size:12px;font-weight:800;cursor:pointer;">Ver analíticas</button>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;">
            <a href="https://supabase.com/dashboard/project/_/database/tables" target="_blank" style="flex:1;min-width:140px;text-align:center;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:10px;font-size:12px;font-weight:800;text-decoration:none;"><i class='bx bx-data'></i> Supabase DB</a>
            <a href="https://supabase.com/dashboard/project/_/storage/buckets" target="_blank" style="flex:1;min-width:140px;text-align:center;background:rgba(100,180,255,0.08);color:#64b4ff;border:1px solid rgba(100,180,255,0.3);border-radius:10px;padding:10px;font-size:12px;font-weight:800;text-decoration:none;"><i class='bx bx-hdd'></i> Storage</a>
            <a href="https://supabase.com/dashboard/project/_/reports" target="_blank" style="flex:1;min-width:140px;text-align:center;background:rgba(255,255,255,0.05);color:#aaa;border:1px solid #2a2a2a;border-radius:10px;padding:10px;font-size:12px;font-weight:800;text-decoration:none;"><i class='bx bx-line-chart'></i> Uso/Reportes</a>
        </div>`;
};

// Lista de anotados a la waitlist (admin)
window._adminViewWaitlist = async function() {
    const sb = window._sb; if (!sb) return;
    let m = document.getElementById('admin-waitlist-modal'); if (m) m.remove();
    m = document.createElement('div'); m.id = 'admin-waitlist-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:100110;background:rgba(0,0,0,0.9);display:flex;flex-direction:column;';
    m.innerHTML = `<div style="display:flex;align-items:center;gap:10px;padding:max(env(safe-area-inset-top,0px),12px) 14px 10px;background:#0d0d0d;border-bottom:1px solid #1a1a1a;">
        <button onclick="document.getElementById('admin-waitlist-modal').remove()" style="background:rgba(255,255,255,0.08);border:none;color:#fff;width:36px;height:36px;border-radius:50%;font-size:20px;cursor:pointer;"><i class='bx bx-arrow-back'></i></button>
        <div style="flex:1;font-size:15px;font-weight:900;color:#fff;">Lista de espera</div>
        <button onclick="window._adminExportWaitlist&&window._adminExportWaitlist()" style="background:rgba(186,255,0,0.1);border:1px solid rgba(186,255,0,0.3);color:var(--accent);border-radius:10px;padding:7px 12px;font-size:12px;font-weight:800;cursor:pointer;">CSV</button>
    </div>
    <div id="admin-wl-body" style="flex:1;overflow-y:auto;padding:12px;"><div style="text-align:center;color:#555;padding:30px;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div></div>`;
    document.body.appendChild(m);
    try {
        const { data } = await sb.from('waitlist').select('*').order('created_at', { ascending: false }).limit(500);
        window._adminWaitlistData = data || [];
        const body = document.getElementById('admin-wl-body');
        if (!data || !data.length) { body.innerHTML = '<div style="text-align:center;color:#555;padding:30px;">Todavía no hay anotados.</div>'; return; }
        body.innerHTML = '<div style="font-size:11px;color:#666;margin-bottom:10px;">'+data.length+' anotados</div>' + data.map(w=>`<div style="display:flex;align-items:center;gap:10px;padding:11px 6px;border-bottom:1px solid #161616;">
            <div style="width:34px;height:34px;border-radius:50%;background:rgba(186,255,0,0.12);display:flex;align-items:center;justify-content:center;color:var(--accent);font-weight:900;">${(w.name||w.email||'?')[0].toUpperCase()}</div>
            <div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;color:#fff;">${(w.name||'—')}</div><div style="font-size:11px;color:#888;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${w.email||''}</div></div>
            <span style="font-size:10px;color:#666;">${w.platform||''}</span>
        </div>`).join('');
    } catch(e) { const body=document.getElementById('admin-wl-body'); if(body) body.innerHTML='<div style="text-align:center;color:#888;padding:30px;font-size:13px;">No se pudo cargar (¿falta el SQL de waitlist?).</div>'; }
};
// Analíticas de uso (admin): qué secciones se usan más + eventos
window._adminViewAnalytics = async function() {
    const sb = window._sb; if (!sb) return;
    let m = document.getElementById('admin-analytics-modal'); if (m) m.remove();
    m = document.createElement('div'); m.id = 'admin-analytics-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:100110;background:rgba(0,0,0,0.92);display:flex;flex-direction:column;';
    m.innerHTML = `<div style="display:flex;align-items:center;gap:10px;padding:max(env(safe-area-inset-top,0px),12px) 14px 10px;background:#0d0d0d;border-bottom:1px solid #1a1a1a;">
        <button onclick="document.getElementById('admin-analytics-modal').remove()" style="background:rgba(255,255,255,0.08);border:none;color:#fff;width:36px;height:36px;border-radius:50%;font-size:20px;cursor:pointer;"><i class='bx bx-arrow-back'></i></button>
        <div style="flex:1;font-size:15px;font-weight:900;color:#fff;">Analíticas de uso</div>
    </div>
    <div id="admin-an-body" style="flex:1;overflow-y:auto;padding:14px;"><div style="text-align:center;color:#555;padding:30px;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div></div>`;
    document.body.appendChild(m);
    const body = document.getElementById('admin-an-body');
    try {
        // Traer últimos 5000 eventos y agregar en el cliente (suficiente para un panel)
        const { data } = await sb.from('analytics_events').select('event,props,user_email,created_at').order('created_at',{ascending:false}).limit(5000);
        if (!data || !data.length) { body.innerHTML = '<div style="text-align:center;color:#555;padding:30px;font-size:13px;">Todavía no hay datos de uso. Se empiezan a registrar cuando la gente navega la app.</div>'; return; }
        const sections = {}, events = {}, users = new Set();
        data.forEach(e=>{
            if (e.user_email) users.add(e.user_email);
            events[e.event] = (events[e.event]||0)+1;
            if (e.event === 'section_view' && e.props && e.props.section) sections[e.props.section] = (sections[e.props.section]||0)+1;
        });
        const topSections = Object.entries(sections).sort((a,b)=>b[1]-a[1]);
        const maxS = topSections.length ? topSections[0][1] : 1;
        const bar = (label,n,max,color) => `<div style="margin-bottom:8px;"><div style="display:flex;justify-content:space-between;font-size:12px;color:#ccc;margin-bottom:3px;"><span>${label}</span><span style="font-weight:800;">${n}</span></div><div style="height:8px;background:#1a1a1a;border-radius:4px;overflow:hidden;"><div style="height:100%;width:${Math.round(n/max*100)}%;background:${color||'var(--accent)'};"></div></div></div>`;
        body.innerHTML = `
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;">
                <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:12px;padding:14px;"><div style="font-size:10px;color:#666;font-weight:800;">EVENTOS (muestra)</div><div style="font-size:24px;font-weight:900;color:var(--accent);">${data.length}</div></div>
                <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:12px;padding:14px;"><div style="font-size:10px;color:#666;font-weight:800;">USUARIOS ACTIVOS</div><div style="font-size:24px;font-weight:900;color:#64b4ff;">${users.size}</div></div>
            </div>
            <div style="font-size:12px;font-weight:800;color:#fff;margin-bottom:10px;">Secciones más usadas</div>
            <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:12px;padding:14px;margin-bottom:16px;">
                ${topSections.length ? topSections.map(([s,n])=>bar(s,n,maxS)).join('') : '<div style="color:#555;font-size:12px;">Sin vistas de sección aún.</div>'}
            </div>
            <div style="font-size:12px;font-weight:800;color:#fff;margin-bottom:10px;">Tipos de evento</div>
            <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:12px;padding:14px;">
                ${Object.entries(events).sort((a,b)=>b[1]-a[1]).map(([e,n])=>bar(e,n,Math.max(...Object.values(events)),'#64b4ff')).join('')}
            </div>
            <div style="font-size:10px;color:#555;text-align:center;margin-top:14px;">Muestra de los últimos 5.000 eventos. Para histórico completo, exportá desde Supabase.</div>`;
    } catch(e) { body.innerHTML = '<div style="text-align:center;color:#888;padding:30px;font-size:13px;">No se pudo cargar (¿falta el SQL de analytics_events?).</div>'; }
};

window._adminExportWaitlist = function() {
    const d = window._adminWaitlistData || []; if (!d.length) return;
    const csv = 'email,name,platform,fecha\n' + d.map(w=>`${w.email||''},${(w.name||'').replace(/,/g,' ')},${w.platform||''},${w.created_at||''}`).join('\n');
    const a = document.createElement('a'); a.href = 'data:text/csv;charset=utf-8,'+encodeURIComponent(csv); a.download = 'canchero-waitlist.csv'; a.click();
};

window.renderAdminDashboard = async function() {
    const sb = window._sb;
    const dash = document.getElementById('admin-dashboard');
    const period = window._adminPeriod || 'mes';
    const sinceISO = _adminDateFilter(period); // null/2020 = total
    const applyPeriod = period !== 'total';
    // Helper: contar filas de una tabla (exact count sin traer datos)
    // dateCol = columna de fecha a filtrar por período (default created_at)
    async function cnt(table, filter, dateCol) {
        try {
            let q = sb.from(table).select('*', { count: 'exact', head: true });
            if (filter) q = filter(q);
            if (applyPeriod) {
                const col = dateCol || 'created_at';
                q = q.gte(col, sinceISO);
            }
            const { count, error } = await q;
            return error ? 0 : (count || 0);
        } catch(e) { return 0; }
    }
    // Inyectar bloque de métricas reales si no existe
    let metricsBox = document.getElementById('admin-real-metrics');
    if (!metricsBox && dash) {
        metricsBox = document.createElement('div');
        metricsBox.id = 'admin-real-metrics';
        dash.insertBefore(metricsBox, dash.children[1] || null);
    }
    if (metricsBox) metricsBox.innerHTML = '<div style="color:#555;padding:20px;text-align:center;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i> Cargando métricas reales...</div>';

    if (sb) {
        const [usuarios, jugadores, clubes, tiendas, pros, orgs, complejosTbl, partidos, posts, encuestas, historias, disponibles, grupos, notifs] = await Promise.all([
            cnt('users'),
            cnt('users', q => q.eq('role','jugador')),
            cnt('users', q => q.in('role',['club','complejo'])),
            cnt('users', q => q.eq('role','tienda')),
            cnt('users', q => q.eq('role','profesional')),
            cnt('users', q => q.eq('role','organizacion')),
            cnt('clubs'),
            cnt('matches'),
            cnt('posts'),
            cnt('polls'),
            cnt('stories'),
            (async () => { try { const { count } = await sb.from('users').select('*', { count:'exact', head:true }).eq('available', true); return count||0; } catch(e){ return 0; } })(),
            cnt('group_chats'),
            cnt('notifications'),
        ]);
        const _periodLabel = { hoy:'HOY', semana:'ÚLTIMA SEMANA', mes:'ÚLTIMO MES', 'año':'ÚLTIMO AÑO', total:'TOTAL' }[period] || 'ÚLTIMO MES';
        const card = (label, val, color, icon) => `
            <div style="background:#0d0f0d;border:1px solid #1c1c1c;border-radius:14px;padding:16px;">
                <div style="display:flex;align-items:center;gap:8px;color:#666;font-size:10px;font-weight:800;letter-spacing:1px;margin-bottom:8px;"><i class='bx ${icon}' style="color:${color};font-size:16px;"></i> ${label}</div>
                <div style="font-size:28px;font-weight:900;color:${color};">${val}</div>
            </div>`;
        if (metricsBox) metricsBox.innerHTML = `
            <div style="font-size:11px;color:#666;font-weight:800;letter-spacing:1px;margin:4px 0 12px;">📊 MÉTRICAS · ${_periodLabel}</div>
            <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-bottom:20px;">
                ${card('USUARIOS TOTALES', usuarios, '#baff00', 'bx-group')}
                ${card('JUGADORES', jugadores, '#baff00', 'bx-run')}
                ${card('DISPONIBLES AHORA', disponibles, '#00e676', 'bx-circle')}
                ${card('COMPLEJOS', Math.max(clubes, complejosTbl), '#64b4ff', 'bx-cancha')}
                ${card('TIENDAS', tiendas, '#ff9800', 'bx-store')}
                ${card('PROFESIONALES', pros, '#9c88ff', 'bx-briefcase')}
                ${card('ORGANIZACIONES', orgs, '#ff96c8', 'bx-trophy')}
                ${card('PARTIDOS', partidos, '#baff00', 'bx-football')}
                ${card('PUBLICACIONES', posts, '#fff', 'bx-news')}
                ${card('ENCUESTAS', encuestas, '#64b4ff', 'bx-poll')}
                ${card('HISTORIAS', historias, '#ffb400', 'bx-camera')}
                ${card('CHATS GRUPALES', grupos, '#9c88ff', 'bx-chat')}
                ${card('NOTIFICACIONES', notifs, '#888', 'bx-bell')}
            </div>
            <div id="admin-sys-monitor"></div>`;
        try { window._renderAdminSystemMonitor && window._renderAdminSystemMonitor(); } catch(e){}
        // Compat con los stats viejos
        const se = (id,v)=>{const el=document.getElementById(id);if(el)el.innerText=v;};
        se('admin-stat-comp', Math.max(clubes, complejosTbl));
        se('admin-stat-jug', jugadores);
        const negocios = clubes + tiendas + pros + orgs;
        const mrr = negocios * 1500;
        se('admin-stat-mrr', '$' + mrr);
        // Lista real de jugadores
        window._adminLoadPlayers();
    }
    let allComplexes = [];
    try { allComplexes = JSON.parse(localStorage.getItem('canchero_complexes') || '[]'); } catch(e) {}

    const compList = document.getElementById('admin-complex-list');
    if(compList) {
        if(allComplexes.length === 0) {
            compList.innerHTML = '<p style="color:#888;">No hay complejos registrados.</p>';
        } else {
            compList.innerHTML = allComplexes.map(c => `
                <div style="background:rgba(255,255,255,0.05); padding:15px; border-radius:8px; display:flex; justify-content:space-between; align-items:center;">
                    <div>
                        <h4 style="margin:0; color:var(--accent);">${c.name} <span style="font-size:10px; background:white; color:black; padding:2px 5px; border-radius:3px;">${c.status}</span></h4>
                        <span style="font-size:12px; color:#888;">Dueño: ${c.owner} - Tel: ${c.phone} - Email: ${c.email}</span>
                    </div>
                    <div>
                        <button class="btn btn-primary btn-sm" onclick="alert('Funcionalidad para aprobar complejo.')">APROBAR</button>
                        <button class="btn btn-glass btn-sm" style="color:#ff4444; border-color:#ff4444;">RECHAZAR</button>
                    </div>
                </div>
            `).join('');
        }
    }

    // Chart.js
    const ctx = document.getElementById('adminRevenueChart');
    if(ctx) {
        if(adminRevenueChartInstance) adminRevenueChartInstance.destroy();
        adminRevenueChartInstance = new Chart(ctx, {
            type: 'line',
            data: {
                labels: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun'],
                datasets: [{
                    label: 'Ingresos MRR ($)',
                    data: [200, 400, 800, 1000, 1200, 1500],
                    borderColor: '#baff00',
                    backgroundColor: 'rgba(186, 255, 0, 0.1)',
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4
                }]
            },
            options: {
                responsive: true,
                plugins: { legend: { display: false } },
                scales: { 
                    y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' } },
                    x: { grid: { color: 'rgba(255,255,255,0.05)' } }
                }
            }
        });
    }
};

// Altura del header global — las secciones overlay arrancan debajo para que
// el bloque negro (logo + campana + ajustes) se vea SIEMPRE.
window._navH = function(){
  try {
    const nav = document.getElementById('main-nav');
    if (nav){ const cs=getComputedStyle(nav); const r=nav.getBoundingClientRect();
      if (cs.display!=='none' && cs.visibility!=='hidden' && r.height>0 && r.bottom>0) return Math.round(r.bottom); }
  } catch(e){}
  return 0;
};

window.toggleSidebar = function() {
    const sidebar = document.querySelector('.sidebar');
    if (sidebar) {
        sidebar.classList.toggle('active');
    }
};

// ============================================================
// MÓDULO SOCIAL — Posts, Stories, Likes, Comments, Reports
// ============================================================
const social = (() => {
    // sb siempre apunta al cliente global autenticado (se resuelve en cada uso)
    function getSb() { return window._sb || window.supabaseClient || null; }

    function getUser() {
        const u = window.userData || {};
        return {
            email: u.email || localStorage.getItem('canchero_email') || 'anonimo@canchero.uy',
            name:  u.name  || localStorage.getItem('canchero_name')  || 'Jugador',
            role:  u.role  || localStorage.getItem('canchero_role')  || 'jugador',
            avatar: u.photo || null,
        };
    }

    function timeAgoStr(dateStr) {
        if (!dateStr) return '';
        const d = new Date(dateStr), now = new Date();
        const s = Math.floor((now - d) / 1000);
        if (s < 60) return 'Hace un momento';
        if (s < 3600) return `Hace ${Math.floor(s/60)} min`;
        if (s < 86400) return `Hace ${Math.floor(s/3600)}h`;
        return `Hace ${Math.floor(s/86400)}d`;
    }

    function avatarEl(name, photoUrl, size = 42, photoStyle, hasStory = false, isOwnPost = false) {
        const letter = (name || '?')[0].toUpperCase();
        const storyBorder = hasStory ? 'border:2px solid #ff3333;box-shadow:0 0 7px rgba(255,51,51,0.45);' : 'border:2px solid var(--border);';
        const myAttr = isOwnPost ? ' data-myavatar="1"' : '';
        const clickAttr = isOwnPost ? ` onclick="window.openMyStory()" ` : '';
        const cursorStyle = isOwnPost ? 'cursor:pointer;' : '';
        if (photoUrl && !photoUrl.includes('randomuser')) {
            let bgPos = 'center 25%'; // default rostro — consistente en toda la app
            let bgSize = 'cover';
            if (photoStyle) {
                const px = 50 + parseInt(photoStyle.x || 0);
                const py = 50 + parseInt(photoStyle.y || 0);
                bgPos = `${px}% ${py}%`;
                if (photoStyle.zoom && parseFloat(photoStyle.zoom) > 100) bgSize = `${photoStyle.zoom}%`;
            }
            return `<div${myAttr}${clickAttr}style="width:${size}px;height:${size}px;border-radius:50%;background-image:url('${photoUrl}');background-size:${bgSize};background-position:${bgPos};flex-shrink:0;${cursorStyle}${storyBorder}"></div>`;
        }
        return `<div${myAttr}${clickAttr}style="width:${size}px;height:${size}px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;font-size:${Math.floor(size*0.35)}px;display:flex;align-items:center;justify-content:center;flex-shrink:0;${cursorStyle}${storyBorder}">${letter}</div>`;
    }

    function roleBadge(role) {
        const map = { club:'Club', complejo:'Complejo', profesional:'Profesional', organizacion:'Organización', tienda:'Tienda', sponsor:'Sponsor', fanatico:'Fanático' };
        if (!map[role]) return '';
        return `<span style="font-size:9px;background:rgba(186,255,0,0.15);color:var(--accent);padding:1px 6px;border-radius:4px;margin-left:6px;font-weight:700;text-transform:uppercase;">${map[role]}</span>`;
    }

    function postCardHTML(p, likedByMe, isFollowing, isMe) {
        const liked = likedByMe;
        const hasMedia = p.media_url && p.media_type !== 'text';
        const isVideo = p.media_type === 'video';
        const safeUserName = (p.user_name||'').replace(/'/g,"\\'");
        const followBtn = isMe ? '' : `<button onclick="social.toggleFollow(this,'${p.user_email}','${safeUserName}')" data-following="${isFollowing?'true':'false'}" style="background:${isFollowing?'transparent':'rgba(186,255,0,0.12)'};color:${isFollowing?'#555':'var(--accent)'};border:1px solid ${isFollowing?'#333':'rgba(186,255,0,0.4)'};font-size:10px;font-weight:700;padding:3px 10px;border-radius:20px;cursor:pointer;white-space:nowrap;transition:.15s;">${isFollowing?'Siguiendo':'+ Seguir'}</button>`;
        const myInitial = (window.userData && window.userData.name) ? window.userData.name[0].toUpperCase() : '?';
        return `
        <div class="post-card" id="post-card-${p.id}" data-post-id="${p.id}" style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:16px;margin-bottom:12px;">
          <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">
            ${(() => {
                // Solo sustituir con MI foto actual si el post fue hecho con el MISMO rol
                // (los posts de club/fanático conservan su identidad; el encuadre del
                // jugador no debe aplicarse a la foto del fan ni al escudo del club)
                // OJO multi-identidad: comparar contra el rol REAL de publicación (_pubRole)
                const _actRoleP = ((window._pubRole && window._pubRole()) || (window.userData && window.userData.role) || 'jugador').toLowerCase();
                const _postRoleP = (p.user_role || 'jugador').toLowerCase();
                const _sameIdentity = isMe && (_postRoleP === 'jugador' || _postRoleP === 'fanatico') && _postRoleP === _actRoleP;
                const _av = _sameIdentity ? (window.userData?.photo || p.user_avatar) : p.user_avatar;
                const _st = _sameIdentity ? (window.userData?.photoStyle || p.user_photo_style) : p.user_photo_style;
                return avatarEl(p.user_name, _av, 42, _st, p.user_has_story, isMe);
            })()}
            <div style="flex:1;min-width:0;">
              <div onclick="window._openPostAuthor('${(p.user_email||'').replace(/'/g,"\\'")}','${(p.user_role||'jugador').replace(/'/g,'')}','${safeUserName}')" style="font-weight:700;font-size:13px;display:flex;align-items:center;flex-wrap:wrap;gap:4px;cursor:pointer;">
                ${(p.user_name||'Jugador').toUpperCase()}${roleBadge(p.user_role)}
              </div>
              <div style="font-size:11px;color:#666;">${timeAgoStr(p.created_at)}</div>
            </div>
            <div style="display:flex;align-items:center;gap:4px;">${followBtn}${isMe
                ? `<button onclick="${p.pinned?'unpinPost':'pinPost'}('${p.id}')" title="${p.pinned?'Desfijar':'Fijar en perfil'}" style="background:none;border:none;cursor:pointer;padding:4px 5px;border-radius:8px;color:${p.pinned?'var(--accent)':'#555'};font-size:18px;line-height:1;"><i class='bx bx-pin'></i></button><button onclick="deleteOwnPost('${p.id}')" title="Eliminar" style="background:none;border:none;cursor:pointer;padding:4px 5px;border-radius:8px;color:#555;font-size:18px;line-height:1;"><i class='bx bx-trash'></i></button>`
                : `<button onclick="openOtherPostMenu('${p.id}','${(p.user_email||'').replace(/'/g,"\\'")}')" style="background:none;border:none;color:#555;cursor:pointer;font-size:22px;padding:0 4px;line-height:1;">⋯</button>`}</div>
          </div>
          ${p.content ? ((window._urgentPostHTML && window._urgentPostHTML(p)) || (window.renderPostContent ? window.renderPostContent(p.content) : `<p style="font-size:13px;line-height:1.55;margin:0 0 12px;word-break:break-word;">${escapeHtml(p.content)}</p>`)) : ''}
          ${(window._bizItemCardHTML && window._bizItemCardHTML(p)) || ''}
          ${(window._gameResultCardHTML && window._gameResultCardHTML(p)) || ''}
          ${(p.tags && p.tags.length && window.cancheroFeatures) ? window.cancheroFeatures.tags.renderTagsHtml(p.tags, p.id) : ''}
          ${(() => {
              // Producto/servicio compartido SIN carrusel: la tarjeta CTA ya muestra la foto
              if (window._bizItemMeta && window._bizItemMeta(p) && !p.media_urls) return '';
              // Carrusel estilo Instagram: 1 foto visible, deslizar para ver el resto
              let arr = [];
              try { if (p.media_urls) arr = (typeof p.media_urls === 'string' ? JSON.parse(p.media_urls) : p.media_urls) || []; } catch(e) {}
              if (!arr.length && hasMedia) arr = [{ url: p.media_url, type: p.media_type || 'image' }];
              if (!arr.length) return '';
              const item = (md) => md.type === 'video'
                ? `<video src="${window._playableVideoUrl ? window._playableVideoUrl(md.url) : md.url}" controls preload="metadata" onplay="if(!this._v){this._v=1;window._registerPostView&&window._registerPostView('${p.id}')}" onended="this._v=0" style="width:100%;max-height:340px;object-fit:cover;display:block;"></video>`
                : `<img src="${md.url}" style="width:100%;max-height:360px;object-fit:cover;display:block;" onerror="this.style.display='none'">`;
              if (arr.length === 1) return `<div style="border-radius:10px;overflow:hidden;margin-bottom:12px;">${item(arr[0])}</div>`;
              const cid = 'carousel-' + p.id;
              return `<div style="margin-bottom:12px;position:relative;overflow:hidden;">
                <div id="${cid}" data-idx="0" data-count="${arr.length}" style="display:flex;width:100%;overflow-x:auto;scroll-snap-type:x mandatory;border-radius:10px;scrollbar-width:none;-webkit-overflow-scrolling:touch;scroll-behavior:smooth;" onscroll="window._carouselSync&&window._carouselSync('${cid}')">
                  ${arr.map(md=>`<div style="flex:0 0 100%;min-width:100%;scroll-snap-align:start;border-radius:10px;overflow:hidden;">${item(md)}</div>`).join('')}
                </div>
                <div id="${cid}-counter" style="position:absolute;top:8px;right:10px;background:rgba(0,0,0,0.6);color:#fff;font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;">1/${arr.length}</div>
                <div id="${cid}-dots" style="display:flex;justify-content:center;gap:5px;margin-top:6px;">${arr.map((_,i)=>`<span style="width:6px;height:6px;border-radius:50%;background:${i===0?'var(--accent)':'#444'};transition:.2s;"></span>`).join('')}</div>
              </div>`;
          })()}
          <!-- Likers preview -->
          <div id="likers-preview-${p.id}" style="min-height:0;"></div>
          <div style="display:flex;gap:4px;border-top:1px solid var(--border);padding-top:12px;margin-top:4px;">
            <button class="post-action-btn ${liked?'liked':''}" onclick="social.toggleLike(this)" data-post-id="${p.id}" style="flex:1;background:${liked?'rgba(186,255,0,0.08)':'rgba(255,255,255,0.03)'};border:1px solid ${liked?'rgba(186,255,0,0.2)':'rgba(255,255,255,0.06)'};color:${liked?'var(--accent)':'#888'};cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 6px;border-radius:10px;font-size:12px;font-weight:700;transition:all .2s;">
              <i class='bx ${liked?'bxs-heart':'bx-heart'}' style="font-size:16px;"></i> <span class="like-count">${p.likes_count||0}</span>
            </button>
            <button onclick="toggleInlineComments('${p.id}')" id="comment-btn-${p.id}" style="flex:1;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);color:#888;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 6px;border-radius:10px;font-size:12px;font-weight:700;transition:all .2s;" onmouseover="this.style.color='#fff';this.style.background='rgba(255,255,255,0.07)'" onmouseout="this.style.color='#888';this.style.background='rgba(255,255,255,0.03)'">
              <i class='bx bx-comment' style="font-size:16px;"></i> <span id="comment-count-${p.id}">${p.comments_count||0}</span>
            </button>
            <button onclick="toggleInlineShare('${p.id}','${safeUserName}')" style="flex:1;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);color:#888;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 6px;border-radius:10px;font-size:12px;font-weight:700;transition:all .2s;" onmouseover="this.style.color='#fff';this.style.background='rgba(255,255,255,0.07)'" onmouseout="this.style.color='#888';this.style.background='rgba(255,255,255,0.03)'">
              <i class='bx bx-share-alt' style="font-size:16px;"></i> <span>${p.shares_count||0}</span>
            </button>
          </div>
          <!-- Compartir inline -->
          <div id="inline-share-${p.id}" style="display:none;border-top:1px solid var(--border);padding:10px 0 4px;margin-top:8px;">
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">
              <button onclick="social.repostToProfile('${p.id}');toggleInlineShare('${p.id}')" style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);border:1px solid #2a2a2a;border-radius:10px;padding:10px 12px;color:#ccc;cursor:pointer;font-size:12px;font-weight:700;text-align:left;">
                <i class='bx bx-repost' style="font-size:18px;color:var(--accent);flex-shrink:0;"></i><div><div>En mi perfil</div><div style="font-size:10px;color:#555;font-weight:400;">Repostear en tu feed</div></div>
              </button>
              <button onclick="social._shareExternal('${p.id}');toggleInlineShare('${p.id}')" style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);border:1px solid #2a2a2a;border-radius:10px;padding:10px 12px;color:#ccc;cursor:pointer;font-size:12px;font-weight:700;text-align:left;">
                <i class='bx bx-link-external' style="font-size:18px;color:var(--accent);flex-shrink:0;"></i><div><div>Externamente</div><div style="font-size:10px;color:#555;font-weight:400;">WhatsApp, copiar link</div></div>
              </button>
            </div>
            <div id="inline-share-friends-${p.id}" style="display:none;"></div>
            <button onclick="toggleInlineShareFriends('${p.id}')" style="display:flex;align-items:center;gap:8px;width:100%;background:rgba(255,255,255,0.03);border:1px solid #2a2a2a;border-radius:10px;padding:10px 12px;color:#888;cursor:pointer;font-size:12px;font-weight:700;margin-bottom:4px;">
              <i class='bx bx-user-voice' style="font-size:18px;color:var(--accent);flex-shrink:0;"></i> Enviar a un seguido
            </button>
          </div>
          <!-- Sección inline de comentarios -->
          <div id="inline-comments-${p.id}" style="display:none;border-top:1px solid var(--border);padding-top:12px;margin-top:8px;">
            <div id="inline-comments-list-${p.id}" style="margin-bottom:10px;"></div>
            <div style="display:flex;gap:8px;align-items:center;">
              <div style="width:30px;height:30px;border-radius:50%;background:#1e1e1e;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px;font-weight:900;color:var(--accent);">${myInitial}</div>
              <input id="inline-comment-input-${p.id}" type="text" placeholder="Escribí un comentario..." autocomplete="off"
                style="flex:1;background:rgba(255,255,255,0.05);border:1px solid #2a2a2a;border-radius:22px;padding:9px 14px;color:#fff;font-size:13px;outline:none;min-width:0;"
                onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'"
                onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submitInlineComment('${p.id}');}">
              <button onclick="submitInlineComment('${p.id}')" style="background:var(--accent);color:#000;border:none;border-radius:50%;width:34px;height:34px;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;">
                <i class='bx bx-send' style="font-size:16px;"></i>
              </button>
            </div>
          </div>
        </div>`;
    }

    function escapeHtml(str) {
        return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

    // ── LOAD FEED ─────────────────────────────────────────────
    async function loadFeed(containerId = 'amigos-feed', followingOnly = false) {
        const el = document.getElementById(containerId);
        if (!el) return;
        el.innerHTML = `<div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div>`;

        if (!getSb()) {
            // Retry automático — puede ser race condition de init
            el.innerHTML = `<div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i><div style="margin-top:8px;font-size:12px;">Conectando...</div></div>`;
            setTimeout(() => {
                if (getSb()) { loadFeed(containerId, followingOnly); }
                else { el.innerHTML = `<div class="post-card" style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:24px;text-align:center;color:#555;font-size:13px;"><i class='bx bx-wifi-off' style="font-size:32px;display:block;margin-bottom:8px;color:#ff4444;"></i>Sin conexión. Verificá tu internet e intentá de nuevo.</div>`; }
            }, 1200);
            return;
        }

        try {
            const me = getUser();
            let followingEmails = new Set();
            try {
                // Intentar cargar follows (con fallback a user_follows si falla)
                let followRes = await getSb().from('follows').select('following_email').eq('follower_email', me.email);
                if (followRes.error) {
                    followRes = await getSb().from('user_follows').select('following_email').eq('follower_email', me.email);
                }
                (followRes.data || []).forEach(f => followingEmails.add(f.following_email));
            } catch(e) { console.warn('follows query error:', e); }

            if (followingOnly && followingEmails.size === 0) {
                el.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><i class='bx bx-user-plus' style="font-size:36px;margin-bottom:10px;display:block;"></i><p>Aún no seguís a nadie.<br><span style="font-size:12px;">Explorá el feed general y seguí jugadores.</span></p></div>`;
                return;
            }

            const nowIso = new Date().toISOString();
            const cutoff12h = new Date(Date.now() - 12 * 3600000).toISOString();
            let query = getSb().from('posts').select('*')
                .or(`is_official.eq.true,pinned.eq.true,expires_at.gt.${nowIso},and(expires_at.is.null,created_at.gt.${cutoff12h})`)
                .order('is_official', { ascending: false })
                .order('created_at', { ascending: false }).limit(30);
            if (followingOnly) query = query.in('user_email', [...followingEmails]);

            let { data: posts, error } = await query;
            if (error) throw error;
            // Excluir reels y respuestas de hilo (se ven al abrir el hilo, estilo X)
            if (posts) posts = posts.filter(p => !p.is_reel && !p.parent_post_id);
            // Avisos "faltan jugadores": SOLO los ven jugadores y clubes (pedido 2026-07-09)
            {
                const _vr = ((window._pubRole && window._pubRole()) || 'jugador').toLowerCase();
                if (_vr !== 'jugador' && _vr !== 'club' && posts) posts = posts.filter(p => (p.content||'').indexOf('⚡ FALTAN') !== 0);
            }

            let likedIds = new Set();
            if (posts && posts.length) {
                try {
                    const { data: myLikes } = await getSb().from('post_likes').select('post_id').eq('user_email', me.email).in('post_id', posts.map(p => p.id));
                    (myLikes || []).forEach(l => likedIds.add(l.post_id));
                } catch(e) {}
            }

            if (!posts || posts.length === 0) {
                el.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><i class='bx bx-message-square-detail' style="font-size:36px;margin-bottom:10px;display:block;"></i><p>${followingOnly ? 'Los jugadores que seguís aún no publicaron nada.' : 'Sé el primero en publicar algo.'}</p></div>`;
                return;
            }
            // Filtrar posts ocultos localmente (eliminados sin permiso en DB)
            const hiddenIds = typeof window.isHiddenPost === 'function' ? (function(){try{return JSON.parse(localStorage.getItem('canchero_hidden_posts')||'[]');}catch(e){return [];}})() : [];
            const visible = posts.filter(p => !hiddenIds.includes(String(p.id)));
            // Identidad VIVA: nombre/foto ACTUALES del autor (jugador/fanático/negocio)
            try { await window._refreshPostsIdentity(visible); } catch(e){}

            // Enriquecer posts propios con datos actualizados. MULTI-IDENTIDAD: NO pisar el
            // nombre/foto con la identidad activa — cada post conserva la identidad con la que
            // se publicó (tienda/complejo/jugador/etc.). Solo corregir si el nombre guardado
            // falta o quedó como un email, y solo con la identidad base de jugador.
            // Foto BASE del jugador (para fallback de posts de jugador sin avatar guardado)
            // — nunca la de la identidad activa, que puede ser otro rol.
            let _basePhotoP = null;
            try { const _s = JSON.parse(sessionStorage.getItem('canchero_base_snapshot')||'null'); _basePhotoP = _s && _s.photo; } catch(e){}
            const enriched = visible.map(p => {
                if (userData && p.user_email === userData.email) {
                    const _nm = p.user_name;
                    const _needName = !_nm || /@/.test(String(_nm));
                    const _prP = (p.user_role || 'jugador').toLowerCase();
                    const _fallbackPhoto = (_prP === 'jugador') ? (_basePhotoP || userData.photo) : null;
                    return {
                        ...p,
                        user_name: _needName ? (userData.name || _nm) : _nm,
                        user_avatar: p.user_avatar || _fallbackPhoto,
                        user_nickname: p.user_nickname || null,
                        user_available: userData.isAvailable || false,
                        user_photo_style: p.user_photo_style || (p.user_avatar ? null : userData.photoStyle) || null,
                        pinned: window.isPinnedLocally ? (window.isPinnedLocally(p.id) || p.pinned) : p.pinned
                    };
                }
                return p;
            });
            // Batch-query historias activas para borde rojo en avatares
            try {
                const uniqueEmails2 = [...new Set(enriched.map(p => p.user_email).filter(Boolean))];
                if (uniqueEmails2.length > 0 && (getSb())) {
                    const sbStories = getSb();
                    const nowS = new Date().toISOString();
                    const { data: activeS } = await sbStories.from('stories').select('user_email').gt('expires_at', nowS).in('user_email', uniqueEmails2);
                    if (activeS && activeS.length) {
                        const storySet = new Set(activeS.map(s => s.user_email));
                        enriched.forEach(p => { if (storySet.has(p.user_email)) p.user_has_story = true; });
                    }
                }
            } catch(_) {}
            el.innerHTML = enriched.map(p => postCardHTML(p, likedIds.has(p.id), followingEmails.has(p.user_email), p.user_email === me.email)).join('');

            // Insertar bot de actividades recientes al tope del feed
            setTimeout(() => window._insertActivityBot && window._insertActivityBot(el), 300);

            // Cargar encuestas del feed e insertar mezcladas con posts
            setTimeout(async () => {
                if (!window.CancheroPolls) return;
                try {
                    const followArr = [...followingEmails];
                    if (me) followArr.push(me.email);
                    const polls = await window.CancheroPolls.loadFeedPolls(el, followArr);
                    polls.forEach(poll => {
                        const html = window.CancheroPolls.renderPollCard(poll, poll._myVote);
                        const articles = el.querySelectorAll('article');
                        let inserted = false;
                        for (const art of articles) {
                            const artDate = art.dataset && art.dataset.createdAt ? new Date(art.dataset.createdAt) : null;
                            if (!artDate) continue;
                            if (new Date(poll.created_at) > artDate) {
                                art.insertAdjacentHTML('beforebegin', html); inserted = true; break;
                            }
                        }
                        if (!inserted) el.insertAdjacentHTML('beforeend', html);
                    });
                } catch(_) {}
            }, 400);

            // Cargar likers preview async
            enriched.forEach(p => {
                if ((p.likes_count || 0) > 0) {
                    setTimeout(() => window.loadLikersPreview && window.loadLikersPreview(p.id), 0);
                }
            });
            // Cargar conteos reales de comentarios (los stored pueden estar desactualizados)
            setTimeout(async () => {
                try {
                    const postIds = enriched.map(p => p.id);
                    const { data: cmtCounts } = await getSb().from('post_comments').select('post_id').in('post_id', postIds);
                    if (cmtCounts && cmtCounts.length) {
                        const counts = {};
                        cmtCounts.forEach(c => { counts[c.post_id] = (counts[c.post_id]||0) + 1; });
                        Object.entries(counts).forEach(([pid, cnt]) => {
                            document.querySelectorAll('#comment-count-' + pid).forEach(el2 => { el2.textContent = cnt; });
                        });
                    }
                } catch(_) {}
            }, 500);
        } catch(e) {
            el.innerHTML = `<div style="text-align:center;padding:24px;color:#f44;font-size:12px;">Error cargando el feed: ${e.message}</div>`;
        }
    }

    // ── CREATE POST ───────────────────────────────────────────
    async function createPost(role) {
        const textEl = document.getElementById(role === 'jugador' ? 'player-post-text' : 'club-post-text');
        const mediaInput = document.getElementById(role === 'jugador' ? 'player-post-media' : 'club-post-media');
        if (!textEl) return;
        const text = textEl.value.trim();
        const file = mediaInput && mediaInput.files && mediaInput.files[0];
        if (!text && !file) { showToast('Escribí algo antes de publicar.', 'error'); return; }

        const btn = document.querySelector('.btn-post');
        if (btn) { btn.disabled = true; btn.textContent = 'Publicando...'; }

        const me = getUser();
        // Si la publicación es del club (no del jugador), tomar nombre/foto del club
        // del usuario — antes salía con la foto/apodo del usuario logueado.
        let pubName = me.name, pubAvatar = me.photo || me.avatar || null, pubRole = me.role;
        // A3: si la identidad activa es un EQUIPO (publicar como club), etiquetar el post
        // como 'club' aunque el shell sea el de jugador — así no cuenta como jugador ni
        // aparece en el perfil de jugador (el overlay ya puso nombre/logo del club).
        if (me._postAsClub || me._activeProfile === 'team') { pubRole = 'club'; }
        // Identidad de NEGOCIO activa → sellar el post con el rol del negocio (tienda/complejo/
        // organización), así aparece en "sus" publicaciones y no en las del jugador.
        let pubBizId = null;
        if (me._activeBizId || (me._activeProfile && String(me._activeProfile).indexOf('biz:') === 0) || me._activeProfile === 'negocio') {
            try { pubRole = (window._trueRole && window._trueRole()) || pubRole; } catch(e){}
            // business_id: separa negocios del MISMO rol (dos tiendas ≠ misma bandeja de posts).
            try { pubBizId = (window._activeBizId && window._activeBizId()) || me._activeBizId || null; } catch(e){}
            if (pubBizId === '__primary__') pubBizId = null;
        }
        if (role === 'club') {
            try {
                const _sbC = getSb();
                if (_sbC) {
                    const { data: _c } = await _sbC.from('clubs').select('name,logo_url,logo').eq('owner_email', me.email).limit(1).maybeSingle();
                    if (_c) { pubName = _c.name || pubName; pubAvatar = _c.logo_url || _c.logo || pubAvatar; pubRole = 'club'; }
                }
            } catch(e){}
        }
        let mediaUrl = null, mediaType = 'text';
        let _mediaArr = []; // carrusel

        const allFiles = (mediaInput && mediaInput.files) ? Array.from(mediaInput.files).slice(0,10) : [];
        if (allFiles.length && getSb()) {
            for (const f of allFiles) {
                try {
                    const isVid = f.type.startsWith('video/');
                    // Comprimir imágenes antes de subir
                    const fileToUp = isVid ? f : await window._compressImageFile(f, 1280, 0.72);
                    // Subida a Supabase Storage (fallback y ruta sin Cloudinary)
                    const _uploadToSupabase = async () => {
                        const ext = isVid ? (f.name.split('.').pop()||'mp4').toLowerCase() : 'jpg';
                        const ctype = isVid ? (f.type || 'video/mp4') : 'image/jpeg';
                        const safePath = `posts/${Date.now()}_${Math.random().toString(36).slice(2,6)}.${ext}`;
                        const { error: upErr } = await getSb().storage.from('media').upload(safePath, fileToUp, { cacheControl: '31536000', upsert: true, contentType: ctype });
                        if (!upErr) {
                            const { data: urlData } = getSb().storage.from('media').getPublicUrl(safePath);
                            _mediaArr.push({ url: urlData.publicUrl, type: isVid ? 'video' : 'image' });
                        }
                    };
                    if (window.cloudUpload) {
                        // Cloudinary (media fuera de Supabase → no consume egress; ADEMÁS
                        // transcodifica el video a mp4/H.264 con faststart + genera póster,
                        // clave para que iOS NO muestre el reel en negro).
                        const r = await window.cloudUpload(fileToUp, { folder:'canchero/posts' });
                        if (r && r.url) {
                            let _u = r.url;
                            // Fallback de recorte: aplicar so_/du_ a la URL del video
                            if (isVid && window._postMediaTrim && window.cloudTrimUrl) {
                                _u = window.cloudTrimUrl(_u, window._postMediaTrim.start, window._postMediaTrim.du);
                            }
                            _mediaArr.push({ url: _u, type: isVid ? 'video' : 'image' });
                        } else {
                            // Cloudinary falló (video muy grande, red, etc.) → NO perder el
                            // archivo: guardarlo en Supabase para que el post no quede sin media.
                            await _uploadToSupabase();
                        }
                    } else {
                        await _uploadToSupabase();
                    }
                } catch(e) { console.warn('Upload exception:', e); }
            }
            if (_mediaArr.length) { mediaUrl = _mediaArr[0].url; mediaType = _mediaArr[0].type; }
            else { showToast('Error al subir archivos.', 'error'); if (btn) { btn.disabled=false; btn.textContent='PUBLICAR'; } return; }
        }

        // Check for URL in media input (text-based URL input)
        const mediaUrlInput = document.getElementById(role === 'jugador' ? 'player-post-mediaurl' : 'club-post-mediaurl');
        if (!mediaUrl && mediaUrlInput && mediaUrlInput.value.trim()) {
            mediaUrl = mediaUrlInput.value.trim();
            mediaType = mediaUrl.match(/\.(mp4|webm|ogg)$/i) ? 'video' : 'image';
        }

        // Extract tags from textarea data attribute (set by canchero-features tag autocomplete)
        let tags = [];
        try { tags = JSON.parse(textEl.dataset.tags || '[]'); } catch(e){}

        // Permanencia: si el creador marca "mantener", el post no expira (pinned previene el borrado, sin reordenar)
        const _permEl = document.getElementById('player-post-permanent') || document.getElementById('club-post-permanent');
        const _permanent = !!(_permEl && _permEl.checked);
        const post = {
            user_email:  me.email,
            user_name:   pubName,
            user_role:   pubRole,
            user_avatar: pubAvatar,
            content:     text || null,
            media_url:   mediaUrl,
            media_type:  mediaType,
            tags:        tags,
            pinned:      _permanent,
            expires_at:  _permanent ? null : new Date(Date.now() + 12 * 60 * 60 * 1000).toISOString(),
        };
        if (pubBizId) post.business_id = pubBizId;
        if (_permEl) _permEl.checked = false;
        if (_mediaArr.length > 1) post.media_urls = JSON.stringify(_mediaArr); // carrusel
        // TODOS los videos se suben como REEL (video único, no carrusel) — pedido del usuario.
        if (mediaType === 'video' && _mediaArr.length <= 1) post.is_reel = true;

        const _sbNow = getSb() || window._sb;
        if (_sbNow) {
            let { error, data: inserted } = await _sbNow.from('posts').insert(post).select().single();
            // Si falla por columna media_urls, reintentar sin ella
            if (error && error.message && error.message.includes('media_urls')) {
                const p2 = { ...post }; delete p2.media_urls;
                const r = await _sbNow.from('posts').insert(p2).select().single();
                error = r.error; inserted = r.data;
            }
            // Si falla por columna tags, reintentar sin tags
            if (error && error.message && error.message.includes('tags')) {
                const postNoTags = { ...post }; delete postNoTags.tags; delete postNoTags.media_urls;
                const r2 = await _sbNow.from('posts').insert(postNoTags).select().single();
                error = r2.error; inserted = r2.data;
            }
            // Si falla por columna is_reel (no existe en el esquema), reintentar sin ella
            if (error && error.message && error.message.includes('is_reel')) {
                const p3 = { ...post }; delete p3.is_reel;
                const r3 = await _sbNow.from('posts').insert(p3).select().single();
                error = r3.error; inserted = r3.data;
            }
            // Si falla por columna business_id (aún no migrada), reintentar sin ella.
            if (error && error.message && error.message.includes('business_id')) {
                const p4 = { ...post }; delete p4.business_id;
                const r4 = await _sbNow.from('posts').insert(p4).select().single();
                error = r4.error; inserted = r4.data;
            }
            if (!error && inserted && tags.length && window.cancheroFeatures) {
                window.cancheroFeatures.tags.onPostPublished(inserted.id, tags);
            }
            textEl.dataset.tags = '[]';
            if (error) {
                showToast('Error al publicar: ' + error.message, 'error');
                if (btn) { btn.disabled = false; btn.textContent = 'PUBLICAR'; }
                return;
            }
        }

        // Clear composer
        textEl.value = '';
        if (mediaInput) { mediaInput.value = ''; }
        if (mediaUrlInput) mediaUrlInput.value = '';
        window._isReelPostProfile = false;
        const previewEl = document.getElementById(role === 'jugador' ? 'player-post-preview' : 'club-post-preview');
        if (previewEl) { previewEl.innerHTML = ''; previewEl.style.display = 'none'; }
        if (btn) { btn.disabled = false; btn.textContent = 'PUBLICAR'; }

        showToast('¡Publicación creada!', 'success');

        // Publicar partes del hilo del perfil si las hay
        const profileHiloItems = (window._profileHiloItems || []).filter(t => t.trim());
        if (profileHiloItems.length) {
            try {
                const { data: newPost } = await (_sbNow||getSb()).from('posts').select('id').eq('user_email', me.email).order('created_at', { ascending: false }).limit(1).single();
                if (newPost) {
                    const rootId = newPost.id;
                    for (const hiloText of profileHiloItems) {
                        const hp = { user_email: me.email, user_name: me.name, user_avatar: me.photo||null, user_role: me.role||'jugador', content: hiloText, media_type: 'text', likes_count: 0, parent_post_id: rootId, thread_root_id: rootId, expires_at: new Date(Date.now()+12*3600000).toISOString() };
                        await (_sbNow||getSb()).from('posts').insert(hp).catch(() => {});
                    }
                    await (_sbNow||getSb()).from('posts').update({ reply_count: profileHiloItems.length }).eq('id', rootId).catch(() => {});
                }
            } catch(e) {}
            window._profileHiloItems = [];
            const profileHiloPanel = document.getElementById('profile-hilo-panel');
            if (profileHiloPanel) { profileHiloPanel.style.display = 'none'; const c = document.getElementById('profile-hilo-items'); if (c) c.innerHTML = ''; }
            const profileHiloBtn = document.getElementById('profile-hilo-btn');
            if (profileHiloBtn) profileHiloBtn.style.color = 'var(--text-muted)';
        }

        loadFeed('amigos-feed');
        loadFeed('jugador-profile-feed-posts');
        // Refrescar el feed principal (INICIO) y el perfil para que la publicación
        // aparezca en AMBOS lados (perfil ↔ feed unificados).
        try { if (typeof window.loadMainFeed === 'function') window.loadMainFeed(); } catch(e) {}
        try { if (typeof window.loadProfilePosts === 'function') window.loadProfilePosts(); } catch(e) {}
        setTimeout(() => { try { window._hydrateMatchCards && window._hydrateMatchCards(); } catch(e){} }, 400);
    }

    // ── LIKE TOGGLE ───────────────────────────────────────────
    async function toggleLike(el) {
        const sb = getSb() || window._sb;
        const postId = el.dataset.postId;
        if (!postId || !sb) return;
        const me = getUser();
        if (!me || !me.email) return;
        if (el._liking) return; // evitar doble disparo
        el._liking = true;

        const icon = el.querySelector('i');
        const countEl = el.querySelector('.like-count');
        if (!window._myLikedPostIds) window._myLikedPostIds = new Set();

        // ── UI OPTIMISTA estilo Threads: cambiar al instante + animación ──
        const wasLiked = el.classList.contains('liked');
        const willLike = !wasLiked;
        let count = parseInt((countEl && countEl.textContent) || '0', 10) || 0;
        count = Math.max(0, count + (willLike ? 1 : -1));
        el.classList.toggle('liked', willLike);
        el.style.color = willLike ? 'var(--accent)' : '#666';
        if (icon) {
            icon.className = willLike ? 'bx bxs-heart' : 'bx bx-heart';
            // animación de "pop"
            icon.style.transition = 'transform .18s cubic-bezier(.34,1.7,.5,1)';
            icon.style.transform = 'scale(1.5)';
            setTimeout(() => { icon.style.transform = 'scale(1)'; }, 180);
        }
        if (countEl) countEl.textContent = count;
        try { if (willLike && navigator.vibrate) navigator.vibrate(10); } catch(e) {}
        if (willLike) window._myLikedPostIds.add(String(postId)); else window._myLikedPostIds.delete(String(postId));

        // ── Persistencia en segundo plano (revertir si falla) ──
        try {
            if (willLike) {
                await sb.from('post_likes').insert({ post_id: postId, user_email: me.email, user_name: me.name || me.email });
                try {
                    const { data: pOwner } = await sb.from('posts').select('user_email').eq('id', postId).single();
                    if (pOwner && pOwner.user_email && pOwner.user_email !== me.email && window.notif && window.notif.create) {
                        window.notif.create(pOwner.user_email, 'like', me.name || 'Alguien', `❤️ ${me.name || 'Alguien'} le dio like a tu publicación.`, postId);
                    }
                } catch(e) {}
            } else {
                await sb.from('post_likes').delete().eq('post_id', postId).eq('user_email', me.email);
            }
            // Conteo real (el TRIGGER de Postgres mantiene posts.likes_count —
            // con RLS el cliente ya no puede updatear posts ajenos)
            const { data: allLikes } = await sb.from('post_likes').select('user_email').eq('post_id', postId);
            const realCount = (allLikes || []).length;
            if (countEl) countEl.textContent = realCount;
            setTimeout(() => window.loadLikersPreview && window.loadLikersPreview(postId), 200);
        } catch(e) {
            // revertir UI optimista
            console.warn('toggleLike error:', e);
            el.classList.toggle('liked', wasLiked);
            el.style.color = wasLiked ? 'var(--accent)' : '#666';
            if (icon) icon.className = wasLiked ? 'bx bxs-heart' : 'bx bx-heart';
            if (countEl) countEl.textContent = Math.max(0, count + (willLike ? -1 : 1));
        }
        el._liking = false;
    }

    // ── COMMENTS ─────────────────────────────────────────────
    async function openComments(postId) {
        let modal = document.getElementById('social-comments-modal');
        if (modal) modal.remove(); // always recreate to avoid stale postId
        modal = document.createElement('div');
        modal.id = 'social-comments-modal';
        var _reelsOpen = !!document.getElementById('reels-modal');
        modal.style.cssText = 'position:fixed;inset:0;z-index:' + (_reelsOpen ? 10600 : 9900) + ';display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.75);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);';
        modal.innerHTML = `
          <div style="background:#111;border:1px solid #222;border-radius:20px;width:calc(100% - 32px);max-width:560px;height:min(75vh,560px);display:flex;flex-direction:column;overflow:hidden;box-shadow:0 8px 40px rgba(0,0,0,0.9);">
            <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #1e1e1e;flex-shrink:0;">
              <div style="display:flex;align-items:center;gap:8px;">
                <i class='bx bx-comment' style="color:var(--accent);font-size:18px;"></i>
                <span style="font-size:15px;font-weight:800;letter-spacing:.3px;">Comentarios</span>
              </div>
              <button onclick="document.getElementById('social-comments-modal').remove()" style="width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.06);border:none;color:#aaa;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;line-height:1;transition:.2s;">&times;</button>
            </div>
            <div id="comments-list" style="flex:1;overflow-y:auto;padding:14px 18px;"></div>
            <div style="padding:12px 14px;border-top:1px solid #1e1e1e;display:flex;gap:8px;flex-shrink:0;background:#111;">
              <input id="comment-input" type="text" placeholder="Escribí un comentario..." style="flex:1;background:rgba(255,255,255,0.06);border:1px solid #2a2a2a;border-radius:24px;padding:11px 16px;color:#fff;font-size:13px;outline:none;min-width:0;" onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'" onkeydown="if(event.key==='Enter')social.submitComment('${postId}')">
              <button id="comment-send-btn" onclick="social.submitComment('${postId}')" style="background:var(--accent);color:#000;border:none;border-radius:24px;padding:11px 18px;font-weight:900;font-size:12px;cursor:pointer;white-space:nowrap;flex-shrink:0;">ENVIAR</button>
            </div>
          </div>`;
        modal.onclick = (e) => { if (e.target === modal) modal.remove(); };
        document.body.appendChild(modal);
        loadComments(postId);
    }

    async function loadComments(postId) {
        const list = document.getElementById('comments-list');
        if (!list) return;
        list.innerHTML = `<div style="text-align:center;color:#555;padding:20px;"><i class='bx bx-loader-alt bx-spin'></i></div>`;
        if (!getSb()) { list.innerHTML = '<div style="color:#555;padding:12px;">Sin conexión.</div>'; return; }
        const { data, error } = await getSb().from('post_comments').select('*').eq('post_id', postId).order('created_at', { ascending: true });
        if (error || !data || !data.length) {
            list.innerHTML = '<div style="text-align:center;color:#555;padding:20px;font-size:13px;">Sé el primero en comentar.</div>';
            return;
        }
        // Organizar en hilos: top-level + respuestas anidadas
        const topLevel = data.filter(c => !c.parent_comment_id);
        const replies = data.filter(c => c.parent_comment_id);
        const replyMap = {};
        replies.forEach(r => {
            if (!replyMap[r.parent_comment_id]) replyMap[r.parent_comment_id] = [];
            replyMap[r.parent_comment_id].push(r);
        });
        // Enriquecer comentarios con fotos de perfil reales
        try {
            const cemails = [...new Set(data.map(c=>c.user_email).filter(Boolean))];
            if (cemails.length && getSb()) {
                const { data: cus } = await getSb().from('users').select('email,photo,photo_style,nat').in('email', cemails);
                const cuMap = {};
                (cus||[]).forEach(u => { cuMap[u.email] = u; });
                data.forEach(c => { const u = cuMap[c.user_email]; if (u) { c._photo = u.photo || u.avatar_url; c._pstyle = u.photo_style || null; c._nat = u.nat || u.country || null; } });
            }
        } catch(e) {}
        // Enriquecer con likes de comentarios (cuáles likeé yo)
        try {
            const myEm = (window.userData && window.userData.email) || '';
            if (myEm) {
                const cids = data.map(c=>c.id);
                const { data: cl } = await getSb().from('comment_likes').select('comment_id').eq('user_email', myEm).in('comment_id', cids);
                const liked = new Set((cl||[]).map(x=>x.comment_id));
                data.forEach(c => { c._liked = liked.has(c.id); });
            }
        } catch(e) {}

        function renderComment(c, depth) {
            const indent = depth > 0 ? 'margin-left:' + Math.min(depth * 24, 48) + 'px;' : '';
            const threadLine = depth > 0 ? 'border-left:2px solid #222;padding-left:10px;' : '';
            const childReplies = replyMap[c.id] || [];
            const sz = depth > 0 ? 28 : 34;
            const ph = c._photo && !c._photo.includes('ui-avatars') ? c._photo : null;
            // Mismo encuadre que TODOS los avatares de la app (photoStyle o rostro center 25%)
            const avatarHtmlC = ph
                ? `<div style="width:${sz}px;height:${sz}px;border-radius:50%;flex-shrink:0;${(window._avatarBgCss && window._avatarBgCss({ photo: ph, photo_style: c._pstyle })) || `background-image:url('${ph}');background-size:cover;background-position:center 25%;`}"></div>`
                : avatarEl(c.user_name, null, sz);
            const _cEmail = (c.user_email||'').replace(/'/g,"\\'");
            return `<div style="${indent}${threadLine}margin-bottom:10px;">
              <div style="display:flex;gap:10px;">
                <div onclick="window.viewUserProfile('${_cEmail}')" style="cursor:pointer;flex-shrink:0;">${avatarHtmlC}</div>
                <div style="background:rgba(255,255,255,0.04);border-radius:12px;padding:8px 12px;flex:1;">
                  <div onclick="window.viewUserProfile('${_cEmail}')" style="font-size:11px;font-weight:700;margin-bottom:3px;cursor:pointer;display:flex;align-items:center;">${(c.user_name||'Jugador').toUpperCase()}${(c._nat && window.countryFlag) ? `<span style="margin-left:4px;flex-shrink:0;line-height:1;">${window.countryFlag(c._nat,12)}</span>` : ''}</div>
                  <div style="font-size:13px;line-height:1.4;">${escapeHtml(c.content)}</div>
                  <div style="display:flex;align-items:center;gap:12px;margin-top:4px;">
                    <span style="font-size:10px;color:#555;">${timeAgoStr(c.created_at)}</span>
                    <button id="cml-${c.id}" onclick="window._likeComment('${c.id}',this)" data-liked="${c._liked?'1':'0'}" style="background:none;border:none;color:${c._liked?'var(--accent)':'#888'};font-size:10px;font-weight:700;cursor:pointer;padding:0;display:flex;align-items:center;gap:4px;"><i class='bx ${c._liked?'bxs-heart':'bx-heart'}' style="font-size:14px;"></i><span>${c.likes_count||0}</span></button>
                    <button onclick="window._replyToComment('${postId}','${c.id}','${(c.user_name||'').replace(/'/g,"\\'")}')" style="background:none;border:none;color:#888;font-size:10px;font-weight:700;cursor:pointer;padding:0;">RESPONDER</button>
                  </div>
                </div>
              </div>
              ${childReplies.map(r => renderComment(r, depth + 1)).join('')}
            </div>`;
        }
        list.innerHTML = topLevel.map(c => renderComment(c, 0)).join('');
        list.scrollTop = list.scrollHeight;
    }

    // Función para responder a un comentario específico (hilo)
    window._replyToComment = function(postId, parentCommentId, userName) {
        const input = document.getElementById('comment-input');
        if (!input) return;
        input.dataset.parentCommentId = parentCommentId;
        input.placeholder = `Respondiendo a ${userName}...`;
        input.focus();
        // Agregar indicador visual de respuesta
        let replyIndicator = document.getElementById('reply-indicator');
        if (!replyIndicator) {
            replyIndicator = document.createElement('div');
            replyIndicator.id = 'reply-indicator';
            replyIndicator.style.cssText = 'padding:6px 14px;background:rgba(186,255,0,0.08);border-left:3px solid var(--accent);font-size:11px;color:#aaa;display:flex;align-items:center;justify-content:space-between;';
            input.parentElement.insertBefore(replyIndicator, input.parentElement.firstChild);
        }
        replyIndicator.innerHTML = `<span>Respondiendo a <strong style="color:var(--accent);">${userName}</strong></span><button onclick="window._cancelReply()" style="background:none;border:none;color:#888;cursor:pointer;font-size:16px;line-height:1;">&times;</button>`;
        replyIndicator.style.display = 'flex';
    };
    window._cancelReply = function() {
        const input = document.getElementById('comment-input');
        if (input) { delete input.dataset.parentCommentId; input.placeholder = 'Escribí un comentario...'; }
        const ri = document.getElementById('reply-indicator');
        if (ri) ri.style.display = 'none';
    };

    async function submitComment(postId) {
        const input = document.getElementById('comment-input');
        const sendBtn = document.getElementById('comment-send-btn');
        if (!input) return;
        const text = input.value.trim();
        if (!text) return;
        const me = getUser();
        if (!me || !me.email) { if (typeof showToast === 'function') showToast('Iniciá sesión para comentar.', 'warning'); return; }
        // Usar sbAdmin cuando esté disponible para evitar bloqueos de RLS en comentarios
        const sb = window._sb;
        if (!sb) { if (typeof showToast === 'function') showToast('Sin conexión. Recargá la página.', 'error'); return; }
        const prevText = input.value;
        input.value = '';
        if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = '...'; }
        let insertError = null;
        try {
            const parentId = input.dataset.parentCommentId || null;
            const commentData = {
                post_id: postId,
                user_email: me.email,
                user_name: me.name || me.email,
                content: text
            };
            if (parentId) commentData.parent_comment_id = parentId;
            let { error: err1 } = await sb.from('post_comments').insert(commentData);
            // Si falla por la columna parent_comment_id (no existe aún), reintentar sin ella
            if (err1 && parentId) {
                delete commentData.parent_comment_id;
                const { error: err2 } = await sb.from('post_comments').insert(commentData);
                insertError = err2;
            } else { insertError = err1; }
            // Limpiar estado de respuesta
            if (typeof window._cancelReply === 'function') window._cancelReply();
        } catch(e) { insertError = { message: e.message || 'Error desconocido' }; }
        if (sendBtn) { sendBtn.disabled = false; sendBtn.textContent = 'ENVIAR'; }
        if (insertError) {
            input.value = prevText;
            if (typeof showToast === 'function') showToast('No se pudo comentar. Intentá de nuevo.', 'error');
            return;
        }
        // Incrementar contador en DB (sin bloquear el hilo)
        sb.from('posts').select('comments_count').eq('id', postId).single().then(({ data: post }) => {
            // comments_count lo mantiene el trigger de Postgres (RLS)
        }).catch(() => {});
        // Actualizar contador en DOM — todos los selectores posibles
        document.querySelectorAll(`button.comment-count-btn[data-post-id="${postId}"] .comment-count`).forEach(el => {
            el.textContent = (parseInt(el.textContent)||0) + 1;
        });
        document.querySelectorAll(`#comment-count-${postId}`).forEach(el => {
            el.textContent = (parseInt(el.textContent)||0) + 1;
        });
        // Actualizar el span del botón de comentarios en la card del reel activo
        const reelCommentSpan = document.getElementById('reel-comment-count-' + postId);
        if (reelCommentSpan) reelCommentSpan.textContent = (parseInt(reelCommentSpan.textContent)||0) + 1;
        loadComments(postId);
    }

    // ── STORIES ──────────────────────────────────────────────
    async function loadStories() {
        const container = document.getElementById('stories-container');
        if (!container) return;
        if (!getSb()) return;

        const now = new Date().toISOString();
        const sbData = getSb();
        const { data: stories } = await sbData.from('stories').select('*').gt('expires_at', now).order('created_at', { ascending: false }).limit(30);

        const me = getUser();

        // Verificar si el usuario actual tiene historia activa
        let myHasStory = false;
        if (me?.email && stories) {
            myHasStory = stories.some(s => s.user_email === me.email);
        }

        // Estilo del círculo propio según si tiene historia o no
        const myCircleStyle = myHasStory
            ? 'width:60px;height:60px;border-radius:50%;background:var(--bg3);border:3px solid #ff3333;box-shadow:0 0 10px rgba(255,51,51,0.5);display:flex;align-items:center;justify-content:center;overflow:hidden;'
            : 'width:60px;height:60px;border-radius:50%;background:var(--bg3);border:2px dashed var(--accent);display:flex;align-items:center;justify-content:center;';

        // Foto propia si tiene historia
        const myPhotoEl = myHasStory && me?.photo
            ? `<img src="${me.photo}" style="width:100%;height:100%;object-fit:cover;" onerror="this.style.display='none'">`
            : `<i class='bx bx-plus' style="font-size:22px;color:var(--accent);"></i>`;

        let html = `
          <div onclick="social.openCreateStory()" style="display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;flex-shrink:0;">
            <div style="${myCircleStyle}">
              ${myPhotoEl}
            </div>
            <span style="font-size:10px;color:#888;">${myHasStory ? '🔴 Tu story' : 'Tu story'}</span>
          </div>`;

        // Agrupar por usuario — UN bubble por usuario con todas sus historias
        const otherStoriesRaw = stories ? stories.filter(s => !me?.email || s.user_email !== me.email) : [];
        const userMap = {};
        // Reordenar: más viejas primero para viewer, thumbnail = la más reciente
        const sorted = [...(stories||[])].sort((a,b) => new Date(a.created_at) - new Date(b.created_at));
        sorted.forEach(s => {
            if (!userMap[s.user_email]) userMap[s.user_email] = { user_name: s.user_name, stories: [] };
            userMap[s.user_email].stories.push(s);
        });

        const otherEmails = Object.keys(userMap).filter(e => !me?.email || e !== me.email);
        if (otherEmails.length) {
            html += otherEmails.map(email => {
                const ud = userMap[email];
                const lastStory = ud.stories[ud.stories.length - 1];
                const countBadge = ud.stories.length > 1
                    ? `<div style="position:absolute;top:-2px;right:-2px;background:var(--accent);color:#000;border-radius:50%;width:16px;height:16px;font-size:9px;font-weight:900;display:flex;align-items:center;justify-content:center;border:1px solid #0d0d0d;">${ud.stories.length}</div>` : '';
                return `
              <div onclick="window.viewUserStories&&window.viewUserStories('${email.replace(/'/g,"\\'")}')" style="display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;flex-shrink:0;position:relative;">
                <div style="position:relative;display:inline-block;">
                  <div style="width:60px;height:60px;border-radius:50%;background:${lastStory.media_url?'#111':'var(--bg3)'};border:3px solid #ff3333;box-shadow:0 0 8px rgba(255,51,51,0.4);overflow:hidden;display:flex;align-items:center;justify-content:center;">
                    ${lastStory.media_url ? `<img src="${lastStory.media_url}" style="width:100%;height:100%;object-fit:cover;" onerror="this.style.display='none'">` : `<i class='bx bx-message-rounded' style="font-size:22px;color:#aaa;"></i>`}
                  </div>
                  ${countBadge}
                </div>
                <span style="font-size:10px;color:#aaa;max-width:60px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center;">${(ud.user_name||'').split(' ')[0]}</span>
              </div>`;
            }).join('');
        }

        container.innerHTML = html;
        // Actualizar borde rojo en tarjeta FIFA si hay historia activa
        if (myHasStory) {
            setTimeout(() => window._updateCardStoryBorder && window._updateCardStoryBorder(), 200);
        }
    }

    const _stories_cache = {};
    async function viewStory(storyId) {
        if (!getSb()) return;
        const { data: s } = await getSb().from('stories').select('*').eq('id', storyId).single();
        if (!s) return;

        let existing = document.getElementById('story-viewer-modal');
        if (existing) existing.remove();

        const me = getUser();
        // Cargar likes y comentarios de la historia
        const sb2 = getSb();
        let likeCount = 0, isLiked = false, storyComments = [];
        // Cargar desde Supabase con fallback a localStorage
        try {
            const [{ data: likes }, { data: cmts }] = await Promise.all([
                sb2.from('story_likes').select('user_email').eq('story_id', storyId),
                sb2.from('story_comments').select('*').eq('story_id', storyId).order('created_at', {ascending:true}).limit(50)
            ]);
            likeCount = (likes||[]).length;
            isLiked = me && (likes||[]).some(l => l.user_email === me.email);
            storyComments = cmts || [];
        } catch(e) {
            // Fallback a localStorage
            try {
                const lsLikes = JSON.parse(localStorage.getItem('canchero_story_likes_' + storyId) || '[]');
                likeCount = lsLikes.length;
                isLiked = me && lsLikes.includes(me.email);
                storyComments = JSON.parse(localStorage.getItem('canchero_story_cmts_' + storyId) || '[]');
            } catch(e2) {}
        }

        const modal = document.createElement('div');
        modal.id = 'story-viewer-modal';
        modal.style.cssText = 'position:fixed;inset:0;z-index:100050;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.92);';
        const isVideo = s.media_url && (s.media_url.match(/\.(mp4|webm|mov|m4v|ogg)/i) || s.media_url.includes('video'));
        const mediaHtml = s.media_url
            ? (isVideo
                ? `<video src="${s.media_url}" autoplay playsinline controls style="width:100%;height:100%;object-fit:contain;display:block;max-height:100%;" onerror="this.outerHTML='<div style=padding:20px;color:#888;text-align:center>Error al cargar video</div>'"></video>`
                : `<img src="${s.media_url}" style="width:100%;height:100%;object-fit:contain;display:block;max-height:100%;" loading="lazy" onerror="this.outerHTML='<div style=padding:20px;color:#888;text-align:center>Error al cargar imagen</div>'">`)
            : `<div style="flex:1;display:flex;align-items:center;justify-content:center;padding:30px;font-size:18px;color:#fff;line-height:1.6;text-align:center;">${escapeHtml(s.content||'')}</div>`;

        // Auto-cerrar después de 8s via timeout (más confiable que onanimationend)
        window._storyAutoCloseTimer = clearTimeout(window._storyAutoCloseTimer);
        window._storyAutoCloseTimer = setTimeout(() => { modal.remove(); }, 8000);

        modal.innerHTML = `
          <div style="width:100%;max-width:430px;height:100%;max-height:100svh;display:flex;flex-direction:column;position:relative;background:#000;overflow:hidden;" onclick="event.stopPropagation()">
            <!-- Barra de progreso -->
            <div style="position:absolute;top:0;left:0;right:0;height:3px;background:rgba(255,255,255,0.15);z-index:10;overflow:hidden;border-radius:2px;">
              <div style="height:100%;background:var(--accent);width:0%;transition:none;animation:story-progress 8s linear forwards;"></div>
            </div>
            <!-- Header -->
            <div style="position:absolute;top:0;left:0;right:0;display:flex;align-items:center;gap:10px;padding:16px 14px 10px;z-index:10;background:linear-gradient(to bottom,rgba(0,0,0,0.75) 0%,transparent 100%);">
              ${avatarEl(s.user_name, s.user_photo || s.user_avatar, 36)}
              <div style="flex:1;min-width:0;">
                <div style="font-size:13px;font-weight:800;color:#fff;text-shadow:0 1px 4px rgba(0,0,0,0.8);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${(s.user_name||'Jugador').toUpperCase()}</div>
                <div style="font-size:10px;color:rgba(255,255,255,0.65);">${timeAgoStr(s.created_at)}</div>
              </div>
              <button onclick="clearTimeout(window._storyAutoCloseTimer);document.getElementById('story-viewer-modal')?.remove()" style="background:rgba(0,0,0,0.5);border:none;color:#fff;font-size:22px;cursor:pointer;width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;">&times;</button>
            </div>
            <!-- Media -->
            <div style="flex:1;display:flex;align-items:center;justify-content:center;overflow:hidden;min-height:0;padding-top:60px;padding-bottom:${storyComments.length > 0 ? '200px' : '160px'};">
              ${mediaHtml}
            </div>
            <!-- Texto overlay (si hay media Y texto) -->
            ${s.media_url && s.content ? `<div style="position:absolute;left:0;right:0;bottom:${storyComments.length > 0 ? '205px' : '165px'};padding:10px 16px;background:linear-gradient(transparent,rgba(0,0,0,0.8));pointer-events:none;">
              <div style="font-size:15px;color:#fff;line-height:1.5;text-shadow:0 1px 4px rgba(0,0,0,0.9);">${escapeHtml(s.content)}</div>
            </div>` : ''}
            <!-- Acciones -->
            <div style="position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent,rgba(0,0,0,0.95) 20%,#0a0a0a);border-top:1px solid #1e1e1e;padding:10px 14px calc(16px + env(safe-area-inset-bottom));flex-shrink:0;">
                <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
                    <button id="story-like-btn-${storyId}" onclick="window._toggleStoryLike('${storyId}',this)" style="display:flex;align-items:center;gap:6px;background:rgba(255,255,255,0.07);border:none;color:${isLiked?'var(--accent)':'#aaa'};cursor:pointer;font-size:13px;font-weight:700;padding:7px 12px;border-radius:20px;">
                        <i class='bx ${isLiked?'bxs-heart':'bx-heart'}' style="font-size:20px;"></i> <span id="story-like-count-${storyId}">${likeCount}</span>
                    </button>
                    <span style="flex:1;font-size:11px;color:#555;">${storyComments.length > 0 ? storyComments.length + ' comentario' + (storyComments.length!==1?'s':'') : ''}</span>
                    ${s.user_email !== (getUser&&getUser().email) ? `<button onclick="window._sendStoryReplyToDM('${storyId}','${(s.user_email||'').replace(/'/g,"\\'")}','${(s.user_name||'').replace(/'/g,"\\'")}','${(s.content||'historia').replace(/'/g,"\\'").slice(0,50)}')" style="background:rgba(186,255,0,0.1);color:var(--accent);border:1px solid rgba(186,255,0,0.25);border-radius:20px;padding:7px 12px;font-weight:900;font-size:11px;cursor:pointer;" title="Responder por DM"><i class='bx bx-message-rounded' style="font-size:14px;margin-right:4px;"></i>Responder</button>` : ''}
                </div>
                ${storyComments.length > 0 ? `<div id="story-comments-list-${storyId}" style="max-height:80px;overflow-y:auto;margin-bottom:8px;">
                    ${storyComments.map(c => `<div style="display:flex;gap:8px;padding:4px 0;border-bottom:1px solid #181818;">
                        <div style="width:22px;height:22px;border-radius:50%;background:var(--accent);color:#000;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:9px;flex-shrink:0;">${(c.user_name||'?')[0].toUpperCase()}</div>
                        <div style="flex:1;min-width:0;"><span style="font-size:11px;font-weight:700;color:#aaa;">${c.user_name||'Jugador'} </span><span style="font-size:12px;color:#ccc;">${escapeHtml(c.content||'')}</span></div>
                    </div>`).join('')}
                </div>` : ''}
                <div style="display:flex;gap:8px;">
                    <input id="story-comment-input-${storyId}" type="text" placeholder="Comentar..." maxlength="200"
                        style="flex:1;background:rgba(255,255,255,0.08);border:1px solid #2a2a2a;border-radius:20px;padding:9px 14px;color:#fff;font-size:13px;outline:none;min-width:0;"
                        onkeydown="if(event.key==='Enter')window._submitStoryComment('${storyId}')">
                    <button onclick="window._submitStoryComment('${storyId}')" style="background:var(--accent);color:#000;border:none;border-radius:20px;padding:9px 14px;font-weight:900;font-size:12px;cursor:pointer;white-space:nowrap;flex-shrink:0;">ENV</button>
                </div>
            </div>
          </div>`;
        modal.onclick = (e) => { if (e.target === modal) { clearTimeout(window._storyAutoCloseTimer); modal.remove(); } };
        document.body.appendChild(modal);
    }

    // ── HELPERS PARA STORY LIKES/COMMENTS (con localStorage fallback si no hay tablas) ──
    function _storyLikeKey(storyId) { return 'canchero_story_likes_' + storyId; }
    function _storyCommentsKey(storyId) { return 'canchero_story_cmts_' + storyId; }

    function _getStoryLikes(storyId) {
        try { return JSON.parse(localStorage.getItem(_storyLikeKey(storyId)) || '[]'); } catch(e) { return []; }
    }
    function _saveStoryLikes(storyId, arr) {
        try { localStorage.setItem(_storyLikeKey(storyId), JSON.stringify(arr)); } catch(e) {}
    }
    function _getStoryComments(storyId) {
        try { return JSON.parse(localStorage.getItem(_storyCommentsKey(storyId)) || '[]'); } catch(e) { return []; }
    }
    function _saveStoryComments(storyId, arr) {
        try { localStorage.setItem(_storyCommentsKey(storyId), JSON.stringify(arr)); } catch(e) {}
    }

    // Exponer funciones de historia globalmente
    window._toggleStoryLike = async function(storyId, btn) {
        if (!userData) return;
        const isLiked = btn.querySelector('i').className.includes('bxs');
        const countEl = document.getElementById(`story-like-count-${storyId}`);
        const current = parseInt(countEl?.textContent || '0');

        // Intentar Supabase, fallback a localStorage
        const sb2 = window._sb;
        let ok = false;
        if (sb2) {
            try {
                if (isLiked) {
                    await sb2.from('story_likes').delete().eq('story_id', storyId).eq('user_email', userData.email);
                } else {
                    await sb2.from('story_likes').upsert({ story_id: storyId, user_email: userData.email, user_name: userData.name }, { onConflict: 'story_id,user_email' });
                }
                ok = true;
            } catch(e) {}
        }
        // localStorage fallback
        let likes = _getStoryLikes(storyId);
        if (isLiked) {
            likes = likes.filter(e => e !== userData.email);
        } else if (!likes.includes(userData.email)) {
            likes.push(userData.email);
        }
        _saveStoryLikes(storyId, likes);

        // UI update
        if (isLiked) {
            btn.style.color = '#888';
            btn.querySelector('i').className = 'bx bx-heart';
            if (countEl) countEl.textContent = Math.max(0, likes.length);
        } else {
            btn.style.color = 'var(--accent)';
            btn.querySelector('i').className = 'bx bxs-heart';
            if (countEl) countEl.textContent = likes.length;
            window._footballLikeAnim(btn);
        }
    };

    window._submitStoryComment = async function(storyId) {
        const input = document.getElementById(`story-comment-input-${storyId}`);
        if (!input) return;
        const text = input.value.trim();
        if (!text || !userData) return;
        input.disabled = true;

        const newComment = { user_email: userData.email, user_name: userData.name, content: text, created_at: new Date().toISOString() };

        // Intentar Supabase, fallback a localStorage
        const sb2 = window._sb;
        if (sb2) {
            try { await sb2.from('story_comments').insert({ story_id: storyId, ...newComment }); } catch(e) {}
        }
        // localStorage fallback
        const cmts = _getStoryComments(storyId);
        cmts.push(newComment);
        _saveStoryComments(storyId, cmts);

        input.value = '';
        const list = document.getElementById(`story-comments-list-${storyId}`);
        if (list) {
            const div = document.createElement('div');
            div.style.cssText = 'display:flex;gap:8px;padding:5px 0;border-bottom:1px solid #1a1a1a;';
            div.innerHTML = `<div style="width:28px;height:28px;border-radius:50%;background:var(--accent);color:#000;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:11px;flex-shrink:0;">${(userData.name||'?')[0].toUpperCase()}</div><div style="flex:1;min-width:0;"><div style="font-size:11px;font-weight:700;">${userData.name}</div><div style="font-size:12px;color:#ccc;">${escapeHtml(text)}</div></div>`;
            list.appendChild(div);
            list.scrollTop = list.scrollHeight;
        }
        input.disabled = false;
    };

    function openCreateStory() {
        let existing = document.getElementById('create-story-modal');
        if (existing) existing.remove();
        const modal = document.createElement('div');
        modal.id = 'create-story-modal';
        // Pantalla completa estilo Instagram
        modal.style.cssText = 'position:fixed;inset:0;z-index:19000;background:#000;display:flex;flex-direction:column;overflow:hidden;';
        modal.innerHTML = `
          <!-- Header -->
          <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 16px;position:absolute;top:0;left:0;right:0;z-index:5;">
            <button onclick="document.getElementById('create-story-modal').remove()" style="background:rgba(0,0,0,0.5);border:1px solid rgba(255,255,255,0.2);color:#fff;width:38px;height:38px;border-radius:50%;font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center;">&times;</button>
            <div style="font-size:13px;font-weight:800;color:#fff;letter-spacing:1px;">NUEVA HISTORIA</div>
            <div style="width:38px;"></div>
          </div>

          <!-- Preview área (9:16) -->
          <div id="story-preview-area" style="flex:1;position:relative;display:flex;align-items:center;justify-content:center;background:#111;overflow:hidden;min-height:0;">
            <div id="story-bg" style="position:absolute;inset:0;background:linear-gradient(135deg,#1a1a2e,#16213e,#0f3460);"></div>
            <!-- Texto overlay -->
            <div id="story-text-overlay" style="position:relative;z-index:3;width:90%;text-align:center;display:none;">
              <div id="story-text-display" style="font-size:24px;font-weight:900;color:#fff;text-shadow:0 2px 8px rgba(0,0,0,0.8);line-height:1.3;word-break:break-word;"></div>
            </div>
            <!-- Media preview -->
            <img id="story-img-preview" src="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:none;z-index:1;">
            <!-- Placeholder -->
            <div id="story-placeholder" style="position:relative;z-index:2;text-align:center;color:rgba(255,255,255,0.4);">
              <i class='bx bx-image-add' style="font-size:60px;display:block;margin-bottom:12px;"></i>
              <div style="font-size:13px;">Tocá para agregar foto o video</div>
            </div>
          </div>

          <!-- Herramientas inferiores -->
          <div style="padding:16px;background:rgba(0,0,0,0.8);backdrop-filter:blur(10px);">
            <!-- Fila de opciones -->
            <div style="display:flex;gap:12px;margin-bottom:14px;overflow-x:auto;scrollbar-width:none;">
              <button onclick="document.getElementById('story-file-input').click()" style="display:flex;flex-direction:column;align-items:center;gap:4px;background:rgba(255,255,255,0.1);border:none;color:#fff;border-radius:12px;padding:10px 16px;cursor:pointer;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;"><i class='bx bx-image' style="font-size:22px;"></i>GALERÍA</button>
              <button onclick="document.getElementById('story-text-tool').style.display=document.getElementById('story-text-tool').style.display==='none'?'flex':'none'" style="display:flex;flex-direction:column;align-items:center;gap:4px;background:rgba(255,255,255,0.1);border:none;color:#fff;border-radius:12px;padding:10px 16px;cursor:pointer;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;"><i class='bx bx-text' style="font-size:22px;"></i>TEXTO</button>
              <button onclick="window._addStoryEmoji()" style="display:flex;flex-direction:column;align-items:center;gap:4px;background:rgba(255,255,255,0.1);border:none;color:#fff;border-radius:12px;padding:10px 16px;cursor:pointer;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;"><span style="font-size:22px;">😊</span>STICKER</button>
              <!-- Selector de fondo -->
              <div style="display:flex;gap:6px;align-items:center;flex-shrink:0;">
                ${['linear-gradient(135deg,#1a1a2e,#16213e,#0f3460)','linear-gradient(135deg,#0d0d0d,#1a1a1a)','linear-gradient(135deg,#4a1942,#8b1a5e)','linear-gradient(135deg,#004d3f,#00b88a)','linear-gradient(135deg,#1a0a00,#8b4513)'].map((bg,i)=>
                  `<div onclick="document.getElementById('story-bg').style.background='${bg}'" style="width:32px;height:32px;border-radius:50%;background:${bg};cursor:pointer;border:2px solid rgba(255,255,255,0.3);flex-shrink:0;"></div>`
                ).join('')}
              </div>
            </div>
            <!-- Input de texto (oculto por defecto) -->
            <div id="story-text-tool" style="display:none;flex-direction:column;gap:8px;margin-bottom:12px;">
              <input id="story-text-input" type="text" placeholder="Escribí tu historia..." maxlength="150"
                style="width:100%;background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);color:#fff;border-radius:12px;padding:12px 14px;font-size:16px;font-weight:700;outline:none;box-sizing:border-box;"
                oninput="(function(v){var d=document.getElementById('story-text-display');var ov=document.getElementById('story-text-overlay');if(v){d.textContent=v;ov.style.display='block';document.getElementById('story-placeholder').style.display='none';}else{ov.style.display='none';if(!document.getElementById('story-img-preview').src.includes('blob')&&!document.getElementById('story-img-preview').src.startsWith('http'))document.getElementById('story-placeholder').style.display='block';}})(this.value)">
            </div>
            <!-- Botón publicar -->
            <button onclick="social.submitStory()" style="width:100%;background:var(--accent);color:#000;border:none;padding:14px;border-radius:14px;font-weight:900;font-size:14px;cursor:pointer;letter-spacing:0.5px;">
              <i class='bx bx-send' style="margin-right:6px;"></i>PUBLICAR HISTORIA
            </button>
            <div style="text-align:center;font-size:10px;color:#444;margin-top:8px;">Dura 12 horas · visible para todos</div>
          </div>

          <input type="file" id="story-file-input" accept="image/*,video/*" style="display:none;" onchange="window._handleStoryFile(this)">`;
        document.body.appendChild(modal);
    }

    window._handleStoryFile = function(input) {
        const file = input.files[0];
        if (!file) return;
        const url = URL.createObjectURL(file);
        const img = document.getElementById('story-img-preview');
        const placeholder = document.getElementById('story-placeholder');
        if (img) { img.src = url; img.style.display = 'block'; }
        if (placeholder) placeholder.style.display = 'none';
        document.getElementById('story-bg').style.background = '#000';
        window._storyMediaFile = file;
    };

    window._addStoryEmoji = function() {
        const emojis = ['⚽','🏆','🔥','💪','🎯','⚡','🦁','🏅','👊','🎉','🙌','💥','🥅','👟','🤙'];
        const em = emojis[Math.floor(Math.random()*emojis.length)];
        const input = document.getElementById('story-text-input');
        if (input) { input.value += em; input.dispatchEvent(new Event('input')); }
    };

    async function submitStory() {
        const text = (document.getElementById('story-text-input') || document.getElementById('story-text'))?.value?.trim() || '';
        const mediaFile = window._storyMediaFile || null;
        if (!text && !mediaFile) { showToast('Agregá texto o imagen a tu historia.', 'error'); return; }
        const me = getUser();
        if (!getSb()) { showToast('Sin conexión','error'); return; }
        let mediaUrl = null;
        if (mediaFile) {
            try {
                const ext = mediaFile.name.split('.').pop() || 'jpg';
                const path = `stories/${me.email.replace(/[^a-z0-9]/gi,'_')}_${Date.now()}.${ext}`;
                const { data: upData, error: upErr } = await getSb().storage.from('media').upload(path, mediaFile, { upsert: true });
                if (!upErr && upData) {
                    const { data: urlData } = getSb().storage.from('media').getPublicUrl(path);
                    mediaUrl = urlData?.publicUrl || null;
                }
            } catch(e) {}
        }
        const { error } = await getSb().from('stories').insert({
            user_email: me.email, user_name: me.name, user_role: me.role,
            user_photo: me.photo || null,
            content: text || null, media_url: mediaUrl || null,
            expires_at: new Date(Date.now() + 12 * 60 * 60 * 1000).toISOString(),
        });
        if (error) { showToast('Error al publicar: ' + error.message, 'error'); return; }
        window._storyMediaFile = null;
        document.getElementById('create-story-modal')?.remove();
        showToast('¡Historia publicada!', 'success');
        loadStories();
    }

    // ── REPORT ───────────────────────────────────────────────
    async function reportPost(postId) {
        const reasons = ['Spam', 'Contenido inapropiado', 'Violencia', 'Contenido sexual', 'Información falsa', 'Otro'];
        const reason = await new Promise(resolve => {
            let modal = document.getElementById('report-modal');
            if (modal) modal.remove();
            modal = document.createElement('div');
            modal.id = 'report-modal';
            modal.style.cssText = 'position:fixed;inset:0;z-index:9100;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.8);padding:20px;';
            modal.innerHTML = `
              <div style="background:var(--bg2);border:1px solid var(--border);border-radius:16px;width:100%;max-width:380px;padding:24px;">
                <h3 style="font-family:Outfit,sans-serif;font-weight:800;margin-bottom:6px;">Reportar contenido</h3>
                <p style="font-size:12px;color:#888;margin-bottom:16px;">¿Por qué querés reportar esto?</p>
                ${reasons.map(r => `<button onclick="document.getElementById('report-modal').dispatchEvent(new CustomEvent('pick',{detail:'${r}'}))" style="display:block;width:100%;text-align:left;background:rgba(255,255,255,0.04);border:1px solid var(--border);border-radius:8px;padding:10px 14px;color:#fff;font-size:13px;cursor:pointer;margin-bottom:6px;">${r}</button>`).join('')}
                <button onclick="document.getElementById('report-modal').remove()" style="display:block;width:100%;background:none;border:none;color:#666;cursor:pointer;margin-top:8px;font-size:12px;">Cancelar</button>
              </div>`;
            modal.addEventListener('pick', e => { modal.remove(); resolve(e.detail); });
            modal.onclick = (e) => { if (e.target === modal) { modal.remove(); resolve(null); } };
            document.body.appendChild(modal);
        });

        if (!reason || !sb) return;
        const me = getUser();
        await getSb().from('reports').insert({ content_type: 'post', content_id: postId, reporter_email: me.email, reason });
        showToast('Reporte enviado. Lo revisaremos pronto.', 'success');
    }

    async function sharePost(postId, userName) {
        let sheet = document.getElementById('share-sheet-modal');
        if (sheet) sheet.remove();
        sheet = document.createElement('div');
        sheet.id = 'share-sheet-modal';
        sheet.style.cssText = 'position:fixed;inset:0;z-index:9950;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,0.75);backdrop-filter:blur(6px);';
        sheet.innerHTML = `
          <div style="background:#111;border-radius:20px;width:100%;max-width:500px;padding:20px;box-shadow:0 8px 40px rgba(0,0,0,0.8);max-height:80vh;overflow-y:auto;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;">
              <span style="font-size:15px;font-weight:900;letter-spacing:.5px;">COMPARTIR</span>
              <button onclick="document.getElementById('share-sheet-modal').remove()" style="width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.06);border:none;color:#aaa;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;transition:.2s;">&times;</button>
            </div>
            <div style="display:flex;flex-direction:column;gap:10px;">
              <button onclick="social.repostToProfile('${postId}','${userName || ''}');document.getElementById('share-sheet-modal').remove();" style="display:flex;align-items:center;gap:14px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:14px;padding:14px 16px;cursor:pointer;color:#fff;font-size:14px;font-weight:700;width:100%;text-align:left;transition:.2s;" onmouseover="this.style.background='#222'" onmouseout="this.style.background='#1a1a1a'">
                <i class='bx bx-repost' style="font-size:22px;color:var(--accent);"></i>
                <div><div style="font-weight:800;">Compartir en mi perfil</div><div style="font-size:11px;color:#666;margin-top:2px;">Aparece en tu feed y tu muro</div></div>
              </button>
              <button onclick="social._shareExternal('${postId}','${userName || ''}');document.getElementById('share-sheet-modal').remove();" style="display:flex;align-items:center;gap:14px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:14px;padding:14px 16px;cursor:pointer;color:#fff;font-size:14px;font-weight:700;width:100%;text-align:left;transition:.2s;" onmouseover="this.style.background='#222'" onmouseout="this.style.background='#1a1a1a'">
                <i class='bx bx-share-alt' style="font-size:22px;color:#aaa;"></i>
                <div><div style="font-weight:800;">Compartir externamente</div><div style="font-size:11px;color:#666;margin-top:2px;">WhatsApp, Instagram, copiar link...</div></div>
              </button>
              <div style="margin-top:6px;">
                <div style="font-size:11px;color:#555;font-weight:700;letter-spacing:.5px;margin-bottom:10px;">ENVIAR A UN SEGUIDO</div>
                <div id="share-following-list" style="display:flex;flex-direction:column;gap:8px;">
                  <div style="color:#555;font-size:12px;text-align:center;padding:10px;"><i class='bx bx-loader-alt bx-spin'></i></div>
                </div>
              </div>
            </div>
          </div>`;
        sheet.onclick = (e) => { if (e.target === sheet) sheet.remove(); };
        document.body.appendChild(sheet);
        // Cargar lista de seguidos asincrónicamente
        const sb = getSb() || window._sb;
        const me = getUser();
        if (sb && me && me.email) {
            try {
                const { data: follows } = await sb.from('follows').select('following_email').eq('follower_email', me.email).limit(30);
                const listEl = document.getElementById('share-following-list');
                if (!listEl) return;
                if (!follows || !follows.length) {
                    listEl.innerHTML = '<div style="color:#444;font-size:12px;text-align:center;padding:8px;">No seguís a nadie todavía.</div>';
                    return;
                }
                // Buscar datos de los seguidos
                const emails = follows.map(f => f.following_email);
                const { data: users } = await sb.from('users').select('email,name,photo').in('email', emails).limit(30);
                const usersMap = {};
                (users || []).forEach(u => { usersMap[u.email] = u; });
                listEl.innerHTML = follows.map(f => {
                    const u = usersMap[f.following_email] || {};
                    const name = u.name || f.following_email.split('@')[0];
                    const initials = name[0].toUpperCase();
                    const avatar = u.photo
                        ? `<img src="${u.photo}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">`
                        : '';
                    return `<button onclick="social._sendPostToUser('${postId}','${f.following_email}','${name.replace(/'/g,"\\'")}','${userName||''}');document.getElementById('share-sheet-modal').remove();"
                      style="display:flex;align-items:center;gap:12px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:10px 14px;cursor:pointer;color:#fff;width:100%;text-align:left;transition:.2s;"
                      onmouseover="this.style.background='#222'" onmouseout="this.style.background='#1a1a1a'">
                      <div style="width:36px;height:36px;border-radius:50%;background:#222;flex-shrink:0;overflow:hidden;display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--accent);">
                        ${avatar}<span ${avatar ? 'style="display:none"' : ''}>${initials}</span>
                      </div>
                      <span style="font-size:13px;font-weight:700;">${name}</span>
                      <i class='bx bx-send' style="margin-left:auto;color:#555;font-size:16px;"></i>
                    </button>`;
                }).join('');
            } catch(e) {
                const listEl = document.getElementById('share-following-list');
                if (listEl) listEl.innerHTML = '<div style="color:#444;font-size:12px;text-align:center;">Error cargando seguidos.</div>';
            }
        }
    }

    async function _sendPostToUser(postId, recipientEmail, recipientName, originalUserName) {
        const me = getUser();
        const sb = getSb() || window._sb;
        if (!me || !sb) return;
        const url = `${window.location.origin}${window.location.pathname}#post-${postId}`;
        try {
            // Enviar como mensaje directo
            await sb.from('messages').insert({
                sender_email: me.email,
                sender_name: me.name || me.email,
                recipient_email: recipientEmail,
                content: `📤 Te comparto una publicación de @${originalUserName || 'alguien'}: ${url}`,
                read: false
            });
        } catch(e) {}
        // Crear notificación para el destinatario
        try {
            notif.create(
                recipientEmail,
                'message',
                me.name || me.email,
                `📤 ${me.name || 'Alguien'} te compartió una publicación`,
                postId
            );
        } catch(e) {}
        if (typeof showToast === 'function') showToast(`Enviado a ${recipientName} ✓`, 'success');
    }

    async function repostToProfile(postId, originalUserName) {
        try { window._registerPostShare && window._registerPostShare(postId); } catch(e){}
        const me = getUser();
        if (!me || !me.email) { if (typeof showToast === 'function') showToast('Iniciá sesión primero.', 'warning'); return; }
        const sb = getSb();
        if (!sb) { if (typeof showToast === 'function') showToast('Sin conexión.', 'error'); return; }
        // Get original post
        const { data: orig } = await sb.from('posts').select('*').eq('id', postId).single();
        if (!orig) { if (typeof showToast === 'function') showToast('No se pudo cargar el post.', 'error'); return; }
        // Create a repost
        const repostContent = `🔁 Compartido de @${originalUserName || orig.user_name || 'alguien'}:\n\n${orig.content || ''}`;
        // Sellar el repost con la identidad ACTIVA, igual que el composer del feed. Sin
        // user_role/business_id el perfil del negocio lo descartaba al filtrar por identidad
        // (todas las identidades comparten email) → se compartía al feed pero NO aparecía
        // en el perfil de la organización.
        const _av = (window._pubAvatar && window._pubAvatar()) || {};
        const _pRole = (window._pubRole && window._pubRole()) || me.role || 'jugador';
        const _pBizId = (window._pubBizId && window._pubBizId()) || null;
        // OJO: `posts` NO tiene columnas repost_of ni image_url — insertarlas devolvía
        // 400 y el repost no se creaba NUNCA (ni en el feed ni en el perfil). El marcador
        // de repost es original_user_email, que es lo que ya filtran reels//perfil.
        const _repost = {
            user_email: me.email,
            user_name: _av.name || me.name || me.email,
            user_role: _pRole,
            user_avatar: _av.photo || me.photo || null,
            content: repostContent,
            media_url: orig.media_url || null,
            media_type: orig.media_type || 'text',
            likes_count: 0,
            comments_count: 0,
            original_user_name: orig.user_name || originalUserName || null,
            original_user_email: orig.user_email || null
        };
        if (_pBizId) _repost.business_id = _pBizId;
        const { error } = await sb.from('posts').insert(_repost);
        if (!error) {
            if (typeof showToast === 'function') showToast('¡Reposteado! Aparece en el feed y en tu perfil.', 'success');
            loadFeed();
        } else {
            if (typeof showToast === 'function') showToast('Error al compartir: ' + (error.message || ''), 'error');
        }
    }

    function _shareExternal(postId, userName) {
        try { window._registerPostShare && window._registerPostShare(postId); } catch(e){}
        // Hoja unificada: WhatsApp/IG/X/Facebook + link que abre DIRECTO el post en Canchero
        window.cancheroShare({ type: 'post', id: postId, title: 'Post en Canchero',
            text: (userName ? 'Mirá este post de ' + userName + ' en Canchero' : 'Mirá este post en Canchero') });
    }

    // ── FOLLOW SYSTEM ─────────────────────────────────────────
    async function follow(targetEmail, targetName, targetProfile) {
        const me = getUser();
        if (!getSb() || !targetEmail) return;
        // Se PUEDE seguir a otra identidad propia (mismo email, distinto rol) — cada rol
        // es único. Solo se bloquea seguirse a la MISMA identidad.
        if (targetEmail === me.email) {
            const _myTag = (window._myProfileTag && window._myProfileTag()) || 'jugador';
            if ((targetProfile || 'jugador') === _myTag) return;
        }
        try {
            // Etiquetar el rol: sigo COMO mi perfil activo, y sigo AL perfil indicado
            // (default jugador; 'fanatico' cuando vengo de Buscar Fanáticos).
            const payload = { follower_email: me.email, following_email: targetEmail,
                follower_profile: (window._myProfileTag && window._myProfileTag()) || 'jugador',
                following_profile: targetProfile || 'jugador' };
            let { error } = await getSb().from('follows').insert(payload);
            if (error && /profile/.test(error.message||'')) {
                await getSb().from('follows').insert({ follower_email: me.email, following_email: targetEmail });
            }
            if (window.notif) window.notif.create(targetEmail, 'follow', me.name, `${me.name} ahora te sigue.`);
        } catch(e) {}
    }

    async function unfollow(targetEmail) {
        const me = getUser();
        if (!getSb()) return;
        try { await getSb().from('follows').delete().eq('follower_email', me.email).eq('following_email', targetEmail); } catch(e) {}
    }

    async function toggleFollow(el, targetEmail, targetName) {
        const isFollowing = el.dataset.following === 'true';
        el.disabled = true;
        if (isFollowing) {
            await unfollow(targetEmail);
            el.dataset.following = 'false';
            el.textContent = '+ Seguir';
            el.style.background = 'rgba(186,255,0,0.12)';
            el.style.color = 'var(--accent)';
            el.style.border = '1px solid rgba(186,255,0,0.4)';
        } else {
            await follow(targetEmail, targetName);
            el.dataset.following = 'true';
            el.textContent = 'Siguiendo';
            el.style.background = 'transparent';
            el.style.color = '#555';
            el.style.border = '1px solid #333';
        }
        el.disabled = false;
    }

    // Helper: trae datos reales (name, photo, pos) de users por emails
    async function _fetchUsersMap(sbLocal, emails) {
        const map = {};
        if (!emails || !emails.length) return map;
        try {
            const { data } = await sbLocal.from('users').select('email,name,photo,pos').in('email', emails);
            (data || []).forEach(u => { map[u.email] = u; });
        } catch(e) {}
        return map;
    }

    function _fanRowHtml(targetEmail, uinfo, isFollowing, isMe) {
        const name = (uinfo && uinfo.name) || targetEmail.split('@')[0];
        const photo = uinfo && uinfo.photo;
        const pos = uinfo && uinfo.pos;
        const initial = (name || '?').trim()[0].toUpperCase();
        const avatar = photo
            ? `<div style="width:44px;height:44px;border-radius:50%;background-image:url('${photo}');background-size:cover;background-position:center;flex-shrink:0;border:1px solid #333;"></div>`
            : `<div style="width:44px;height:44px;border-radius:50%;background:var(--accent);color:#000;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:18px;flex-shrink:0;">${initial}</div>`;
        const emEsc = targetEmail.replace(/'/g, "\\'");
        const nmEsc = name.replace(/'/g, "\\'");
        const actions = isMe
            ? '<span style="font-size:11px;color:#666;">Tú</span>'
            : `<button onclick="event.stopPropagation();social.toggleFollow(this,'${emEsc}','${nmEsc}')" data-following="${isFollowing?'true':'false'}" style="background:${isFollowing?'transparent':'rgba(186,255,0,0.12)'};color:${isFollowing?'#888':'var(--accent)'};border:1px solid ${isFollowing?'#333':'rgba(186,255,0,0.4)'};font-size:10px;font-weight:700;padding:5px 12px;border-radius:20px;cursor:pointer;white-space:nowrap;">${isFollowing?'Siguiendo':'+ Seguir'}</button><button onclick="event.stopPropagation();window.openDM&&window.openDM('${emEsc}','${nmEsc}')" style="background:rgba(255,255,255,0.06);color:#aaa;border:1px solid #333;font-size:13px;padding:5px 9px;border-radius:20px;cursor:pointer;"><i class='bx bx-message-dots'></i></button>`;
        return `<div onclick="window.viewUserProfile&&window.viewUserProfile('${emEsc}')" style="display:flex;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid #1a1a1a;cursor:pointer;transition:background .15s;" onmouseover="this.style.background='rgba(255,255,255,0.03)'" onmouseout="this.style.background='transparent'">
            ${avatar}
            <div style="flex:1;min-width:0;">
                <div style="font-size:13px;font-weight:800;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${name.toUpperCase()}</div>
                <div style="font-size:11px;color:#777;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${pos ? pos + ' · ' : ''}@${targetEmail.split('@')[0]}</div>
            </div>
            <div style="display:flex;gap:6px;align-items:center;flex-shrink:0;">${actions}</div>
        </div>`;
    }

    // Helper: query follows table con fallback a user_follows
    async function _queryFollows(sbLocal, column, value, select) {
        let res = await sbLocal.from('follows').select(select).eq(column, value);
        if (res.error) {
            res = await sbLocal.from('user_follows').select(select).eq(column, value);
        }
        return res.data || [];
    }

    async function loadFollowersList(email, containerId) {
        const el = document.getElementById(containerId);
        const sbLocal = getSb() || window._sb;
        if (!el || !sbLocal) return;
        el.innerHTML = '<div style="text-align:center;padding:20px;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;color:#555;"></i></div>';
        try {
            const data = await _queryFollows(sbLocal, 'following_email', email, 'follower_email');
            if (!data.length) {
                el.innerHTML = '<div style="text-align:center;padding:28px;color:#555;font-size:12px;"><i class="bx bx-user-plus" style="font-size:28px;display:block;margin-bottom:8px;"></i>Sin seguidores aún.</div>';
                return;
            }
            const me = getUser();
            const emails = data.map(f => f.follower_email);
            const [usersMap, myFolData] = await Promise.all([
                _fetchUsersMap(sbLocal, emails),
                _queryFollows(sbLocal, 'follower_email', me.email, 'following_email')
            ]);
            const myFolSet = new Set(myFolData.map(f => f.following_email));
            el.innerHTML = data.map(f => _fanRowHtml(f.follower_email, usersMap[f.follower_email], myFolSet.has(f.follower_email), f.follower_email === me.email)).join('');
        } catch(e) {
            console.error('loadFollowersList error:', e);
            el.innerHTML = '<div style="color:#f44;padding:16px;text-align:center;font-size:12px;">Error cargando seguidores.</div>';
        }
    }

    async function loadFollowingList(email, containerId) {
        const el = document.getElementById(containerId);
        const sbLocal = getSb() || window._sb;
        if (!el || !sbLocal) return;
        el.innerHTML = '<div style="text-align:center;padding:20px;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;color:#555;"></i></div>';
        try {
            const data = await _queryFollows(sbLocal, 'follower_email', email, 'following_email');
            if (!data.length) {
                el.innerHTML = '<div style="text-align:center;padding:28px;color:#555;font-size:12px;"><i class="bx bx-user-check" style="font-size:28px;display:block;margin-bottom:8px;"></i>No seguís a nadie aún.</div>';
                return;
            }
            const me = getUser();
            const emails = data.map(f => f.following_email);
            const usersMap = await _fetchUsersMap(sbLocal, emails);
            el.innerHTML = data.map(f => _fanRowHtml(f.following_email, usersMap[f.following_email], true, f.following_email === me.email)).join('');
        } catch(e) {
            console.error('loadFollowingList error:', e);
            el.innerHTML = '<div style="color:#f44;padding:16px;text-align:center;font-size:12px;">Error cargando seguidos.</div>';
        }
    }

    return { getUser, loadFeed, createPost, toggleLike, openComments, submitComment, loadStories, viewStory, openCreateStory, submitStory, reportPost, sharePost, repostToProfile, _shareExternal, _sendPostToUser, follow, unfollow, toggleFollow, loadFollowersList, loadFollowingList };
})();
// Exponer globalmente para que los onclick="social.xxx()" en el HTML funcionen
window.social = social;
// Alias global para que los onclick="window.openComments(id)" en Reels funcionen
window.openComments = function(postId) {
    if (window.social && window.social.openComments) window.social.openComments(postId);
};

// ============================================================
// EDITAR INFO DEL PERFIL
// ============================================================
window.openEditInfoModal = function() {
    const u = window.userData || {};
    let existing = document.getElementById('edit-info-modal');
    if (existing) existing.remove();

    const modal = document.createElement('div');
    modal.id = 'edit-info-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:99000;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;padding:20px;';

    const positions = ['Arquero','Defensa Central','Lateral Derecho','Lateral Izquierdo','Mediocampista Defensivo','Mediocampista Central','Mediocampista Ofensivo','Extremo Derecho','Extremo Izquierdo','Delantero Centro','Segunda Punta'];
    const depts = ['Artigas','Canelones','Cerro Largo','Colonia','Durazno','Flores','Florida','Lavalleja','Maldonado','Montevideo','Paysandú','Río Negro','Rivera','Rocha','Salto','San José','Soriano','Tacuarembó','Treinta y Tres'];

    const _inp = (id, type, val, placeholder) => `<input id="${id}" type="${type}" value="${val}" placeholder="${placeholder}" style="width:100%;background:#161616;border:1px solid #2a2a2a;color:#fff;padding:8px 10px;border-radius:9px;font-size:13px;box-sizing:border-box;outline:none;" onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'">`;
    const _lbl = (txt) => `<label style="font-size:9px;font-weight:800;color:#555;letter-spacing:1.2px;display:block;margin-bottom:4px;">${txt}</label>`;
    modal.innerHTML = `
    <div style="background:#111;border-radius:20px;width:100%;max-width:480px;max-height:88vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 8px 40px rgba(0,0,0,0.8);">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:14px 16px 12px;flex-shrink:0;border-bottom:1px solid #1e1e1e;">
            <span style="font-size:15px;font-weight:900;color:#fff;letter-spacing:.5px;">EDITAR PERFIL</span>
            <button onclick="document.getElementById('edit-info-modal').remove()" style="background:rgba(255,255,255,0.06);border:none;color:#aaa;font-size:18px;cursor:pointer;width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;">✕</button>
        </div>
        <div style="flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:14px 16px 6px;display:flex;flex-direction:column;gap:10px;">
            <!-- Posición + Edad en fila -->
            <div style="display:grid;grid-template-columns:2fr 1fr;gap:8px;">
                <div>
                    ${_lbl('POSICIÓN')}
                    <select id="eif-pos" style="width:100%;background:#161616;border:1px solid #2a2a2a;color:#fff;padding:8px 10px;border-radius:9px;font-size:13px;outline:none;" onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'">
                        ${positions.map(p => `<option value="${p}" ${(u.position||u.pos||'') === p ? 'selected' : ''}>${p}</option>`).join('')}
                    </select>
                </div>
                <div>
                    ${_lbl('EDAD')}
                    ${_inp('eif-age','number',u.age||'','24')}
                </div>
            </div>
            <!-- Ciudad + Teléfono en fila -->
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
                <div>
                    ${_lbl('CIUDAD / DEPTO')}
                    <select id="eif-city" style="width:100%;background:#161616;border:1px solid #2a2a2a;color:#fff;padding:8px 10px;border-radius:9px;font-size:13px;outline:none;" onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'">
                        ${depts.map(d => `<option value="${d}" ${(u.city||u.dept||'') === d ? 'selected' : ''}>${d}</option>`).join('')}
                    </select>
                </div>
                <div>
                    ${_lbl('TELÉFONO')}
                    ${_inp('eif-phone','tel',u.phone||'','099 123 456')}
                </div>
            </div>
            <!-- Nac + Apodo en fila -->
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
                <div>
                    ${_lbl('NACIONALIDAD')}
                    ${_inp('eif-nat','text',u.nationality||u.nat||'Uruguay','Uruguay')}
                </div>
                <div>
                    ${_lbl('APODO (opcional)')}
                    ${_inp('eif-nick','text',u.nickname||'','Tu apodo')}
                </div>
            </div>
            <!-- Bio -->
            <div>
                ${_lbl('SOBRE MÍ')}
                <textarea id="eif-bio" rows="2" placeholder="Contá algo sobre vos..." style="width:100%;background:#161616;border:1px solid #2a2a2a;color:#fff;padding:8px 10px;border-radius:9px;font-size:13px;resize:none;box-sizing:border-box;outline:none;" onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'">${u.bio||''}</textarea>
            </div>
            <div id="eif-status" style="text-align:center;font-size:12px;color:#aaa;display:none;margin-top:2px;"></div>
        </div>
        <div style="padding:12px 16px calc(12px + env(safe-area-inset-bottom));border-top:1px solid #1e1e1e;flex-shrink:0;background:#111;display:flex;flex-direction:column;gap:8px;">
            <button id="eif-save-btn" onclick="saveEditInfo()" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:14px;cursor:pointer;letter-spacing:.3px;">GUARDAR CAMBIOS</button>
            <button onclick="resetMyStats()" style="width:100%;background:transparent;color:#ff4444;border:1px solid #ff444433;border-radius:12px;padding:9px;font-weight:700;font-size:12px;cursor:pointer;">RESETEAR ESTADÍSTICAS</button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
};

window.saveEditInfo = async function() {
    const u = window.userData;
    if (!u || !u.email) { showToast('No hay sesión activa', 'error'); return; }

    const pos  = document.getElementById('eif-pos')?.value?.trim();
    const age  = document.getElementById('eif-age')?.value?.trim();
    const city = document.getElementById('eif-city')?.value?.trim();
    const phone= document.getElementById('eif-phone')?.value?.trim();
    const nat  = document.getElementById('eif-nat')?.value?.trim();
    const nick = document.getElementById('eif-nick')?.value?.trim();
    const bio  = document.getElementById('eif-bio')?.value?.trim();

    const btn    = document.getElementById('eif-save-btn');
    const status = document.getElementById('eif-status');
    if (btn) { btn.disabled = true; btn.textContent = 'GUARDANDO...'; }

    // La tabla users solo tiene: email, name, role, created_at
    // Todo lo demás se guarda en userData + localStorage
    if (pos  !== undefined) u.pos  = pos;
    if (city !== undefined) { u.city = city; u.department = city; }
    if (phone!== undefined) u.phone = phone;
    if (nat  !== undefined) { u.nat = nat; u.nationality = nat; }
    if (nick !== undefined) u.nickname = nick;
    if (bio  !== undefined) u.bio = bio;
    if (age  !== undefined) u.age = age ? parseInt(age) : u.age;

    try {
        localStorage.setItem('canchero_user', JSON.stringify(u));
    } catch(e) {}

    if (typeof applyUserData === 'function') applyUserData();

    const setEl = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val || '—'; };
    setEl('info-pos',   pos);
    setEl('info-age',   age);
    setEl('info-city',  city);
    setEl('info-phone', phone || '—');
    setEl('info-nat',   nat);
    const nickEl = document.getElementById('p-display-nickname');
    if (nickEl) { if (nick) { nickEl.textContent = `(${nick})`; nickEl.style.display = 'inline'; } else { nickEl.style.display = 'none'; } }

    // Guardar en Supabase para sincronizar entre dispositivos
    try {
        const _sdb = window._sb;
        if (_sdb && u.email) {
            const dbUpdates = {};
            if (pos  !== undefined && pos  !== '') dbUpdates.pos      = pos;
            if (city !== undefined && city !== '') { dbUpdates.city   = city; }
            if (nat  !== undefined && nat  !== '') dbUpdates.nat      = nat;
            if (nick !== undefined && nick !== '') dbUpdates.nickname = nick;
            if (bio  !== undefined && bio  !== '') dbUpdates.bio      = bio;
            if (age  !== undefined && age  !== '') dbUpdates.age      = parseInt(age) || null;
            if (Object.keys(dbUpdates).length > 0) {
                _sdb.from('users').update(dbUpdates).eq('email', u.email).then(r => {
                    if (r.error) console.warn('saveEditInfo DB error:', r.error.message);
                });
            }
        }
    } catch(e) { console.warn('saveEditInfo DB save error:', e); }

    if (btn) { btn.disabled = false; btn.textContent = 'GUARDAR CAMBIOS'; }
    document.getElementById('edit-info-modal')?.remove();
    showToast('Perfil actualizado ✓', 'success');
};

window.resetMyStats = async function() {
    const sb = _sb || window._sb;
    const u = window.userData;
    if (!sb || !u || !u.email) { showToast('No hay sesión activa', 'error'); return; }
    if (!confirm('¿Seguro que querés resetear tus estadísticas a cero? (goles, asistencias, partidos, etc.)')) return;
    const zeroStats = { goals: 0, assists: 0, matches: 0, mvp: 0, rit: 50, reg: 50, tir: 50, def: 50, pas: 50, fis: 50, rating: 50 };
    try {
        await sb.from('users').update({ stats: zeroStats }).eq('email', u.email);
        window.userData.stats = zeroStats;
        try { localStorage.setItem('canchero_user', JSON.stringify(window.userData)); } catch(e) {}
        if (typeof applyUserData === 'function') applyUserData();
        document.getElementById('edit-info-modal')?.remove();
        showToast('Estadísticas reseteadas a cero ✓', 'success');
    } catch(err) {
        showToast('Error al resetear: ' + err.message, 'error');
    }
};

// Auto-load feed/stories when switching tabs
const _origSwitchTab = window.switchDashboardTab;
window.switchDashboardTab = function(role, tab, el) {
    if (_origSwitchTab) _origSwitchTab(role, tab, el);
    if (tab === 'amigos') {
        setTimeout(() => { social.loadFeed('amigos-feed'); social.loadStories(); }, 100);
    }
    if (tab === 'feed') {
        setTimeout(() => {
            const searchBar = document.querySelector('#view-jugador .global-search-container, #view-club .global-search-container');
            const filterBar = document.getElementById('feed-filter-bar');
            if (searchBar && filterBar) {
                filterBar.style.top = searchBar.offsetHeight + 'px';
            }
            // Evitar el "salto" al volver por swipe: si el feed ya tiene posts
            // y se cargó hace <60s, NO re-renderizar (igual que Instagram).
            const cont = document.getElementById('main-feed-container');
            const fresh = window._feedLoadedAt && (Date.now() - window._feedLoadedAt < 60000);
            const hasPosts = cont && cont.querySelector('.post-card');
            if (hasPosts && fresh) return;
            window._feedLoadedAt = Date.now();
            initFeedStoriesBar();
            loadMainFeed();
        }, 80);
    }
    if (tab === 'inicio' || tab === 'publicaciones') {
        setTimeout(() => { try { loadProfileStoryRing(); loadProfilePosts(); } catch(e){} }, 300);
    }
    if (tab === 'crear-partido' || tab === 'buscar-partidos') {
        setTimeout(() => { try { loadComplejoOptions(); } catch(e){} }, 100);
        if (tab === 'crear-partido') setTimeout(() => { try { window._prefillCrearPartido && window._prefillCrearPartido(); } catch(e){} }, 150);
    }
    // Formularios largos → wizard por pasos (más fácil y entretenido)
    if (tab === 'crear-partido') setTimeout(() => { try { window._wizardize('jugador-crear-partido'); } catch(e){} }, 150);
    if (tab === 'crear-torneo') setTimeout(() => { try { window._wizardize('jugador-crear-torneo'); } catch(e){} }, 150);
};

// Prellenado inteligente del formulario de crear partido (para organizar en <2 min)
window._prefillCrearPartido = function() {
    const u = window.userData || {};
    const _set = (id, val) => { const e = document.getElementById(id); if (e && !e.value) e.value = val; };
    // Fecha: próximo sábado
    try {
        const d = new Date(); const day = d.getDay(); const add = (6 - day + 7) % 7 || 7; d.setDate(d.getDate() + add);
        _set('cp-fecha', d.toISOString().slice(0,10));
    } catch(e){}
    // Hora típica de partido
    _set('cp-hora', '20:00');
    // País/ciudad desde el perfil del usuario
    try {
        const paisSel = document.getElementById('cp-pais');
        if (paisSel && !paisSel.value && (u.country || u.nat)) { paisSel.value = u.country || u.nat; paisSel.dispatchEvent(new Event('change')); }
        setTimeout(() => { const citySel = document.getElementById('cp-ciudad'); if (citySel && !citySel.value && (u.city || u.department)) citySel.value = u.city || u.department; }, 120);
    } catch(e){}
    // El nombre del partido se arma como "Local vs Visitante" (no usar "Picado en…" por defecto)
    // Dejar cp-nombre vacío; se completa al guardar con los nombres de los equipos.
    // Solo prefijar el nombre si el usuario tiene un club real; si no, dejar vacío (placeholder)
    _set('cp-home-name', u.club_name || '');
};

window._complejosReales = {};
async function loadComplejoOptions() {
    const sb = _sb || window._sb;
    const sel = document.getElementById('cp-cancha');
    if (!sel) return;
    if (!sb) { sel.innerHTML = '<option value="__manual__">Ingresar manualmente...</option>'; var mw = document.getElementById('cp-cancha-manual-wrap'); if (mw) mw.style.display = 'block'; return; }
    try {
        // Complejos REALES: negocios activos (role club/complejo). Nada de datos falsos.
        const { data } = await sb.from('users').select('email,name,city,whatsapp,phone')
            .in('role', ['club','complejo']).eq('sub_status','active').order('name').limit(100);
        window._complejosReales = {};
        sel.innerHTML = '<option value="">Seleccioná un complejo de Canchero...</option>';
        (data||[]).forEach(function(c) {
            window._complejosReales[c.email] = c;
            const opt = document.createElement('option');
            opt.value = 'biz:' + c.email;
            opt.textContent = (c.name||c.email) + (c.city ? ' — ' + c.city : '');
            sel.appendChild(opt);
        });
        const manualOpt = document.createElement('option');
        manualOpt.value = '__manual__';
        manualOpt.textContent = 'Otra cancha (ingresar manualmente)...';
        sel.appendChild(manualOpt);
        if (!data || !data.length) {
            // sin complejos registrados → directo a manual
            var mwEl0 = document.getElementById('cp-cancha-manual-wrap'); if (mwEl0) mwEl0.style.display = 'block';
        }
    } catch(e) {
        sel.innerHTML = '<option value="__manual__">Ingresar manualmente...</option>';
        var mwElB = document.getElementById('cp-cancha-manual-wrap');
        if (mwElB) mwElB.style.display = 'block';
    }
}

// ============================================================
// LOGO → va al perfil si está logueado
// ============================================================
// (ya manejado en el onclick del HTML, pero también interceptamos clicks en nav-brand)

// ============================================================
// HISTORIA PROPIA EN PERFIL — ring verde si tiene historia activa
// ============================================================
window.loadProfileStoryRing = async function() {
    const sb = window._sb;
    if (!sb || !userData) return;
    try {
        const now = new Date().toISOString();
        const { data } = await sb.from('stories')
            .select('id, created_at, content, media_url, expires_at')
            .eq('user_email', userData.email)
            .gt('expires_at', now)
            .order('created_at', { ascending: false })
            .limit(1);

        const hasStory = data && data.length > 0;
        // Buscar el card del perfil y agregar ring de historia
        const cardImg = document.querySelector('#view-jugador .card-img, #view-jugador .fut-card-large .card-img');
        const storyBtn = document.getElementById('profile-story-ring');

        if (hasStory) {
            // Poner ring ROJO en la tarjeta del perfil (igual que historias en posts)
            const cardWrapper = document.querySelector('#view-jugador .fut-card-large');
            let ring = document.getElementById('profile-story-ring');
            if (cardWrapper && !ring) {
                ring = document.createElement('div');
                ring.id = 'profile-story-ring';
                ring.style.cssText = 'position:absolute;inset:-6px;border-radius:inherit;border:3px solid #ff3333;box-shadow:0 0 16px rgba(255,51,51,0.6);pointer-events:none;z-index:10;animation:story-ring-pulse 2s ease-in-out infinite;';
                cardWrapper.style.position = 'relative';
                cardWrapper.appendChild(ring);
            }
            // Hacer la FOTO DEL PERFIL (card-img) clickeable para ver historia
            const cardImg = document.querySelector('#view-jugador .fut-card-3d-container .card-img');
            if (cardImg) {
                cardImg.style.cursor = 'pointer';
                cardImg.onclick = (e) => { e.stopPropagation(); viewOwnStory(data[0]); };
                cardImg.title = 'Ver mi historia';
            }
            // También el contenedor 3D completo
            const cardContainer = document.querySelector('#view-jugador .fut-card-3d-container');
            if (cardContainer) {
                cardContainer.style.cursor = 'pointer';
                cardContainer.onclick = () => viewOwnStory(data[0]);
            }
            // Borde rojo en sidebar-avatar del perfil
            const sidebarAv = document.querySelector('#view-jugador .sidebar-avatar, .profile-header-row .sidebar-avatar');
            if (sidebarAv) {
                sidebarAv.style.boxShadow = '0 0 0 3px #ff3333, 0 0 12px rgba(255,51,51,0.5)';
                sidebarAv.style.cursor = 'pointer';
                sidebarAv.onclick = () => viewOwnStory(data[0]);
            }
        } else {
            const existing = document.getElementById('profile-story-ring');
            if (existing) existing.remove();
            // Limpiar borde del sidebar avatar
            const sidebarAv = document.querySelector('#view-jugador .sidebar-avatar, .profile-header-row .sidebar-avatar');
            if (sidebarAv) { sidebarAv.style.boxShadow = ''; sidebarAv.onclick = null; }
        }
    } catch(e) {}
};

// Abre la historia propia si existe, si no abre el creador de historia
// Encuadre de foto de perfil (photoStyle x/y/zoom) como CSS de background.
// Úsalo en cualquier avatar circular para que la foto se vea como la
// configuró el usuario (igual que Instagram).
window._avatarBgCss = function(u) {
    u = u || window.userData || {};
    const photo = u.photo && !String(u.photo).includes('ui-avatars') ? u.photo : null;
    if (!photo) return null;
    const st = u.photoStyle || u.photo_style || null;
    // Default: recorte de ROSTRO (center 25%) — mismo en perfil, feed, pill y momentos
    let pos = 'center 25%', size = 'cover';
    if (st) {
        pos = (50 + parseInt(st.x || 0)) + '% ' + (50 + parseInt(st.y || 0)) + '%';
        const z = parseFloat(st.zoom || 100);
        if (z > 100) size = z + '%';
    }
    return "background-image:url('" + photo + "');background-size:" + size + ";background-position:" + pos + ";";
};

window.openMyStory = async function(allowCreate) {
    const u = window.userData || userData;
    if (!u || !u.email) return;
    const sb = window._sb;
    if (!sb) return;
    try {
        const now = new Date().toISOString();
        // Cargar TODAS las historias propias activas en orden (más vieja primero — igual que Instagram)
        const { data } = await sb.from('stories').select('*').eq('user_email', u.email).gt('expires_at', now).order('created_at', { ascending: true });
        if (data && data.length > 0) {
            // Guardar en caché y abrir el viewer completo
            if (!window._feedStoriesByUser) window._feedStoriesByUser = {};
            window._feedStoriesByUser[u.email] = { user_name: u.name, user_avatar: u.photo, stories: data };
            window._openStoryViewer(data, 0);
        } else if (allowCreate) {
            // Solo el "+" de la barra de historias abre el creador
            if (typeof social !== 'undefined' && typeof social.openCreateStory === 'function') {
                social.openCreateStory();
            } else if (typeof addStory === 'function') {
                addStory();
            }
        } else {
            // Tocar la foto de perfil sin historias activas NO debe abrir el creador
            if (typeof showToast === 'function') showToast('No tenés historias activas.', 'info');
        }
    } catch(e) { console.warn('[openMyStory]', e); }
};

// Hook: responder historia → abre DM via CancheroMessaging
window._sendStoryReplyToDM = function(storyId, ownerEmail, ownerName, storyContent) {
    const input = document.getElementById(`story-comment-input-${storyId}`);
    const replyText = (input && input.value.trim()) || prompt(`Responder la historia de ${ownerName}:`);
    if (!replyText) return;
    if (input) input.value = '';
    if (typeof window.CancheroMessaging !== 'undefined') {
        document.getElementById('story-viewer-modal')?.remove();
        window.CancheroMessaging.storyReplyToDM(ownerEmail, ownerName, storyContent, replyText);
    }
};

window.viewOwnStory = function(s) {
    let existing = document.getElementById('story-viewer-modal');
    if (existing) existing.remove();

    const ago = s.created_at ? timeAgo(s.created_at) : '';
    window._storyAutoCloseTimer = clearTimeout(window._storyAutoCloseTimer);
    window._storyAutoCloseTimer = setTimeout(() => { document.getElementById('story-viewer-modal')?.remove(); }, 8000);

    const isVideo = s.media_url && s.media_url.match(/\.(mp4|webm|mov|m4v)/i);
    const modal = document.createElement('div');
    modal.id = 'story-viewer-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9500;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.92);';
    const myPhoto = userData.photo && !userData.photo.startsWith('data:') ? userData.photo : null;
    modal.innerHTML = `
      <div style="width:100%;max-width:430px;height:100%;max-height:100svh;display:flex;flex-direction:column;position:relative;background:#000;overflow:hidden;" onclick="event.stopPropagation()">
        <div style="position:absolute;top:0;left:0;right:0;height:3px;background:rgba(255,255,255,0.15);z-index:10;overflow:hidden;">
          <div style="height:100%;background:var(--accent);animation:story-progress 8s linear forwards;"></div>
        </div>
        <div style="position:absolute;top:0;left:0;right:0;display:flex;align-items:center;gap:10px;padding:16px 14px 10px;z-index:10;background:linear-gradient(to bottom,rgba(0,0,0,0.75),transparent);">
          <div style="width:36px;height:36px;border-radius:50%;${myPhoto?`background-image:url('${myPhoto}');background-size:cover;background-position:center;`:'background:var(--accent);'}display:flex;align-items:center;justify-content:center;font-weight:900;color:#000;font-size:14px;">
            ${myPhoto ? '' : (userData.name||'?')[0].toUpperCase()}
          </div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:13px;font-weight:800;color:#fff;">${(userData.name||'Vos').toUpperCase()}</div>
            <div style="font-size:10px;color:rgba(255,255,255,0.65);">${ago} · Tu historia</div>
          </div>
          <button onclick="clearTimeout(window._storyAutoCloseTimer);document.getElementById('story-viewer-modal')?.remove()" style="background:rgba(0,0,0,0.5);border:none;color:#fff;font-size:22px;cursor:pointer;width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;">&times;</button>
        </div>
        <div style="flex:1;display:flex;align-items:center;justify-content:center;overflow:hidden;min-height:0;padding-top:60px;padding-bottom:20px;">
          ${s.media_url
            ? (isVideo
                ? `<video src="${s.media_url}" autoplay playsinline controls style="width:100%;height:100%;object-fit:contain;" onerror="this.outerHTML='<div style=padding:20px;color:#888>Error</div>'"></video>`
                : `<img src="${s.media_url}" style="width:100%;height:100%;object-fit:contain;" onerror="this.style.display='none'">`)
            : `<div style="flex:1;display:flex;align-items:center;justify-content:center;padding:30px;font-size:18px;color:#fff;line-height:1.6;text-align:center;">${escapeHtml(s.content||'')}</div>`}
        </div>
        ${s.media_url && s.content ? `<div style="position:absolute;bottom:24px;left:16px;right:16px;background:rgba(0,0,0,0.75);backdrop-filter:blur(8px);border-radius:10px;padding:12px 16px;font-size:15px;font-weight:600;line-height:1.5;color:#fff;">${escapeHtml(s.content)}</div>` : ''}
      </div>`;
    modal.onclick = (e) => { if (e.target === modal) { clearTimeout(window._storyAutoCloseTimer); modal.remove(); } };
    document.body.appendChild(modal);
};

function timeAgo(isoStr) {
    if (!isoStr) return '';
    const diff = Date.now() - new Date(isoStr).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return 'ahora mismo';
    if (mins < 60) return `hace ${mins} min`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `hace ${hrs}h`;
    return `hace ${Math.floor(hrs/24)}d`;
}

function escapeHtml(s) {
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}




