// Posts hidden locally (when Supabase DELETE is denied)
function _getHiddenPosts() {
    try { return JSON.parse(localStorage.getItem('canchero_hidden_posts') || '[]'); } catch(e) { return []; }
}
function _hidePostLocally(postId) {
    const h = _getHiddenPosts();
    if (!h.includes(String(postId))) h.push(String(postId));
    localStorage.setItem('canchero_hidden_posts', JSON.stringify(h));
}
window.isHiddenPost = function(postId) {
    return _getHiddenPosts().includes(String(postId));
};

window.editOwnPost = function(postId, currentText) {
    const ex = document.getElementById('edit-post-modal');
    if (ex) ex.remove();
    const m = document.createElement('div');
    m.id = 'edit-post-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:9980;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    const txt = (currentText||'').replace(/\\n/g,'\n');
    m.innerHTML = `<div style="background:#111;border:1px solid #2a2a2a;border-radius:20px;width:100%;max-width:480px;padding:20px;">
        <div style="font-size:14px;font-weight:900;margin-bottom:14px;"><i class='bx bx-edit' style="color:var(--accent);margin-right:8px;"></i>EDITAR PUBLICACIÓN</div>
        <textarea id="edit-post-text" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;padding:12px;border-radius:12px;font-size:14px;outline:none;resize:none;box-sizing:border-box;min-height:100px;" rows="4">${txt}</textarea>
        <div style="display:flex;gap:10px;margin-top:12px;">
            <button onclick="document.getElementById('edit-post-modal').remove()" style="flex:1;padding:12px;background:transparent;border:1px solid #333;color:#aaa;border-radius:12px;cursor:pointer;font-weight:700;font-size:12px;">Cancelar</button>
            <button onclick="window._saveEditPost('${postId}')" style="flex:2;padding:12px;background:var(--accent);color:#000;border:none;border-radius:12px;cursor:pointer;font-weight:900;font-size:12px;">GUARDAR CAMBIOS</button>
        </div>
    </div>`;
    m.onclick = e => { if(e.target===m) m.remove(); };
    document.body.appendChild(m);
    setTimeout(()=>{ const ta=document.getElementById('edit-post-text'); if(ta){ta.focus();ta.selectionStart=ta.selectionEnd=ta.value.length;} },80);
};

window._saveEditPost = async function(postId) {
    const ta = document.getElementById('edit-post-text');
    const newText = ta ? ta.value.trim() : '';
    if (!newText) { if(typeof showToast==='function') showToast('El texto no puede estar vacío','error'); return; }
    const sb = window._sb;
    if (!sb) { if(typeof showToast==='function') showToast('Sin conexión','error'); return; }
    try {
        const { error } = await sb.from('posts').update({ content: newText, updated_at: new Date().toISOString() }).eq('id', postId);
        if (error) throw error;
        document.getElementById('edit-post-modal').remove();
        if(typeof showToast==='function') showToast('Publicación actualizada ✓','success');
        try { loadMainFeed(); } catch(e) {}
        try { loadProfilePosts(); } catch(e) {}
    } catch(e) { if(typeof showToast==='function') showToast('Error: '+e.message,'error'); }
};

window.deleteOwnPost = async function(postId) {
    if (!userData) return;
    if (!confirm('¿Eliminar esta publicación?')) return;
    // Usar _sbAdmin (service_role) para que el DELETE realmente se aplique en la DB (no solo local)
    const sb = window._sb;
    let deleted = false;
    if (sb) {
        try {
            const { error } = await sb.from('posts').delete().eq('id', postId);
            if (error) { showToast && showToast('No se pudo eliminar: ' + error.message, 'error'); }
            else deleted = true;
        } catch(e) { showToast && showToast('Error al eliminar: ' + (e.message||e), 'error'); }
    }
    if (!deleted) return; // si no se borró en DB, no engañar al usuario
    _hidePostLocally(postId);
    const pins = _getPinnedPosts().filter(id => id !== String(postId));
    _savePinnedPosts(pins);
    showToast('Publicación eliminada.', 'success');
    const card = document.querySelector(`.post-card[data-post-id="${postId}"]`);
    if (card) card.closest('.post-card')?.parentElement?.removeChild(card.closest('.post-card')) || card.remove();
    try { loadMainFeed(); } catch(e) {}
    try { loadProfilePosts(); } catch(e) {}
};

// ============================================================
// BLOQUEO DE USUARIOS
// ============================================================
window.openBlockUser = async function(targetEmail) {
    if (!userData || !targetEmail) return;
    const sb = window._sb;
    if (!sb) return;

    // Verificar si ya está bloqueado
    const { data: existing } = await sb.from('blocks').select('id').eq('blocker_email', userData.email).eq('blocked_email', targetEmail).single();
    const isBlocked = !!existing;

    const modal = document.createElement('div');
    modal.style.cssText = 'position:fixed;inset:0;z-index:9600;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.85);padding:20px;';
    modal.innerHTML = `
      <div style="background:#111;border:1px solid #333;border-radius:20px;padding:24px;width:100%;max-width:360px;text-align:center;">
        <i class='bx bx-block' style="font-size:48px;color:#ff8c00;margin-bottom:12px;display:block;"></i>
        <h3 style="font-family:Outfit,sans-serif;margin-bottom:8px;">${isBlocked ? 'Desbloquear usuario' : 'Bloquear usuario'}</h3>
        <p style="font-size:13px;color:#888;margin-bottom:20px;">${isBlocked ?
          'Si desbloqueás a este usuario podrá verte e interactuar con vos nuevamente.' :
          'Si bloqueás a este usuario no podrá ver tu perfil ni interactuar con vos.'}</p>
        <div style="display:flex;gap:10px;">
          <button onclick="confirmBlockUser('${targetEmail}',${isBlocked});this.closest('[style*=fixed]').remove()" style="flex:1;background:${isBlocked?'var(--accent)':'#ff4d4d'};color:${isBlocked?'#000':'#fff'};border:none;padding:12px;border-radius:10px;font-family:Outfit,sans-serif;font-weight:900;cursor:pointer;">${isBlocked ? 'DESBLOQUEAR' : 'BLOQUEAR'}</button>
          <button onclick="this.closest('[style*=fixed]').remove()" style="flex:1;background:transparent;color:#888;border:1px solid #444;padding:12px;border-radius:10px;font-family:Outfit,sans-serif;font-weight:700;cursor:pointer;">CANCELAR</button>
        </div>
      </div>`;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
    document.body.appendChild(modal);
};

window.confirmBlockUser = async function(targetEmail, isBlocked) {
    const sb = window._sb;
    if (!sb || !userData) return;
    try {
        if (isBlocked) {
            await sb.from('blocks').delete().eq('blocker_email', userData.email).eq('blocked_email', targetEmail);
            showToast('Usuario desbloqueado.', 'success');
        } else {
            await sb.from('blocks').insert({ blocker_email: userData.email, blocked_email: targetEmail });
            showToast('Usuario bloqueado. Ya no verá tu contenido.', 'success');
        }
    } catch(e) { showToast('Error: ' + e.message, 'error'); }
};

// Exponer bloqueo desde cualquier perfil
window.blockUserFromProfile = function(targetEmail) { openBlockUser(targetEmail); };
window.unblockUser = function(targetEmail) { openBlockUser(targetEmail); };

// ============================================================
// REPORTES CON PRUEBAS ADJUNTAS
// ============================================================
window.openReportContent = function(contentId, contentType, authorEmail) {
    const reasons = ['Spam', 'Contenido inapropiado', 'Violencia', 'Contenido sexual', 'Información falsa', 'Acoso', 'Cuenta falsa', 'Otro'];
    const modal = document.createElement('div');
    modal.id = 'report-content-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9600;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.85);padding:20px;overflow-y:auto;';
    modal.innerHTML = `
      <div style="background:#111;border:1px solid #333;border-radius:20px;padding:24px;width:100%;max-width:400px;margin:auto;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">
          <h3 style="font-family:Outfit,sans-serif;color:#ff4d4d;"><i class='bx bx-flag'></i> Reportar</h3>
          <button onclick="this.closest('#report-content-modal').remove()" style="background:none;border:none;color:#888;font-size:22px;cursor:pointer;">&times;</button>
        </div>
        <p style="font-size:12px;color:#888;margin-bottom:16px;">¿Por qué querés reportar este contenido?</p>
        <div id="report-reasons" style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px;">
          ${reasons.map(r => `
            <button onclick="selectReportReason(this,'${r}')"
              style="padding:10px 8px;border-radius:8px;border:1px solid #333;background:transparent;color:#aaa;font-size:12px;cursor:pointer;text-align:left;transition:all 0.2s;"
              data-reason="${r}">${r}</button>`).join('')}
        </div>
        <div style="margin-bottom:12px;">
          <label style="font-size:11px;color:#888;text-transform:uppercase;display:block;margin-bottom:6px;">Descripción adicional (opcional)</label>
          <textarea id="report-description" rows="3" placeholder="Describí el problema con más detalle..." style="width:100%;background:rgba(255,255,255,0.04);border:1px solid #333;border-radius:8px;padding:10px;color:#fff;font-size:13px;resize:none;outline:none;"></textarea>
        </div>
        <div style="margin-bottom:20px;">
          <label style="font-size:11px;color:#888;text-transform:uppercase;display:block;margin-bottom:6px;">Adjuntar prueba (imagen, opcional)</label>
          <label style="display:flex;align-items:center;gap:10px;padding:10px;border:1px dashed #333;border-radius:8px;cursor:pointer;">
            <i class='bx bx-image-add' style="font-size:20px;color:#666;"></i>
            <span id="report-file-name" style="font-size:12px;color:#666;">Seleccionar imagen...</span>
            <input type="file" id="report-evidence-file" accept="image/*" style="display:none;" onchange="document.getElementById('report-file-name').textContent=this.files[0]?.name||'Seleccionar imagen...'">
          </label>
        </div>
        <button onclick="submitReport('${contentId}','${contentType}','${authorEmail}')" style="width:100%;background:#ff4d4d;color:#fff;border:none;padding:13px;border-radius:10px;font-family:Outfit,sans-serif;font-weight:900;font-size:14px;cursor:pointer;text-transform:uppercase;">ENVIAR REPORTE</button>
      </div>`;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
    document.body.appendChild(modal);
};

window.selectReportReason = function(btn, reason) {
    document.querySelectorAll('#report-reasons button').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = '#aaa';
        b.style.borderColor = '#333';
    });
    btn.style.background = 'rgba(255,77,77,0.15)';
    btn.style.color = '#ff4d4d';
    btn.style.borderColor = '#ff4d4d';
    btn.dataset.selected = 'true';
};

window.submitReport = async function(contentId, contentType, authorEmail) {
    const sb = window._sb;
    if (!sb || !userData) { showToast('Iniciá sesión para reportar.', 'warning'); return; }

    const selectedBtn = document.querySelector('#report-reasons button[data-selected="true"]');
    if (!selectedBtn) { showToast('Seleccioná un motivo.', 'warning'); return; }
    const reason = selectedBtn.dataset.reason;
    const description = document.getElementById('report-description')?.value.trim() || '';
    const evidenceFile = document.getElementById('report-evidence-file')?.files?.[0];

    let evidenceUrl = null;
    if (evidenceFile) {
        try {
            const path = `reports/${Date.now()}_${userData.email.replace('@','_')}.${evidenceFile.name.split('.').pop()}`;
            const { error } = await sb.storage.from('media').upload(path, evidenceFile, { upsert: true });
            if (!error) {
                const { data: urlData } = sb.storage.from('media').getPublicUrl(path);
                evidenceUrl = urlData?.publicUrl || null;
            }
        } catch(e) {}
    }

    try {
        await sb.from('reports').insert({
            content_type: contentType,
            content_id: contentId,
            reporter_email: userData.email,
            reported_email: authorEmail,
            reason,
            description: description || null,
            evidence_url: evidenceUrl,
        });
        document.getElementById('report-content-modal')?.remove();
        showToast('Reporte enviado. Lo revisaremos pronto.', 'success');
    } catch(e) {
        showToast('Error al enviar reporte: ' + e.message, 'error');
    }
};

// ============================================================
// MÓDULO NOTIFICACIONES
// ============================================================
const notif = (() => {
    // Usar el cliente principal (_sb/_sbAdmin) en lugar de crear uno nuevo
    // Esto asegura que la sesión autenticada del usuario esté activa y RLS funcione
    function getSb() { return window._sb || null; }
    let _realtimeChannel = null;
    let _panelOpen = false;

    function getEmail() {
        return (window.userData && window.userData.email) || localStorage.getItem('canchero_email') || null;
    }

    async function load() {
        const email = getEmail();
        const sb = getSb();
        if (!email || !sb) return;
        try {
            const { data } = await sb.from('notifications').select('*').eq('recipient_email', email).order('created_at', { ascending: false }).limit(30);
            render(data || []);
        } catch(e) {}
    }

    function render(items) {
        const list = document.getElementById('notif-list');
        if (!list) return;
        const unread = items.filter(n => !n.read).length;

        // Update badge
        const badge = document.getElementById('notif-badge');
        if (badge) {
            badge.textContent = unread > 9 ? '9+' : unread;
            badge.style.display = unread > 0 ? 'flex' : 'none';
        }
        const icon = document.getElementById('notif-bell-icon');
        if (icon) icon.className = unread > 0 ? 'bx bxs-bell' : 'bx bx-bell';

        if (!items.length) {
            list.innerHTML = '<div style="padding:24px;text-align:center;color:#555;font-size:13px;"><i class=\'bx bx-bell-off\' style="font-size:28px;display:block;margin-bottom:8px;"></i>Sin notificaciones aún.</div>';
            return;
        }

        const icons = { like: 'bxs-heart', comment: 'bx-comment', follow: 'bx-user-plus', story: 'bx-radio-circle', message: 'bx-message-rounded-dots', chicana: 'bx-zap', group: 'bx-group', prediction_bet: 'bx-trophy', match_invite: 'bx-football', match: 'bx-football', match_accept: 'bx-check-circle' };
        const colors = { like: '#ff4444', comment: '#baff00', follow: '#4fc3f7', story: '#ffb400', message: '#7c8cf8', chicana: '#baff00', group: '#9c88ff', prediction_bet: '#FFD700', match_invite: '#00e676', match: '#00e676', match_accept: '#00e676' };
        list.innerHTML = items.map(n => {
            // Determinar acción de navegación al hacer click
            const meta = n.meta || n.data || {};
            // La tabla notifications usa actor_email/actor_name (con fallbacks)
            const actorEmail = (n.actor_email || n.from_email || meta.sender_email || meta.from_email || '').replace(/'/g,"\\'");
            const actorName = (n.actor_name || n.from_name || meta.sender_name || '').replace(/'/g,"\\'");
            let navCall = `notif.markRead('${n.id}')`;
            if (n.type === 'message' || n.type === 'group') {
                navCall = `notif.markRead('${n.id}');document.getElementById('notif-panel').style.display='none';if(window.CancheroMessaging){if(typeof switchDashboardTab==='function')switchDashboardTab(window.userData&&window.userData.role||'jugador','mensajes',null);setTimeout(()=>window.CancheroMessaging.openThread('dm',null,'${actorEmail}','${actorName}'),300);}`;
            } else if (n.type === 'like' || n.type === 'comment') {
                const postId = meta.post_id || n.post_id || '';
                navCall = `notif.markRead('${n.id}');document.getElementById('notif-panel').style.display='none';if(typeof switchDashboardTab==='function')switchDashboardTab(window.userData&&window.userData.role||'jugador','feed',null);setTimeout(()=>{const el=document.getElementById('post-${postId}');if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},400);`;
            } else if (n.type === 'follow' || n.type === 'chicana') {
                // Abrir el perfil del que te siguió / chicaneó (podés responderle)
                navCall = `notif.markRead('${n.id}');document.getElementById('notif-panel').style.display='none';if(window.viewUserProfile&&'${actorEmail}')window.viewUserProfile('${actorEmail}');`;
            } else if (n.type === 'match_accept' || ((n.type === 'match_invite' || n.type === 'match') && (meta.match_id || n.post_id))) {
                const mId = meta.match_id || n.match_id || n.post_id || '';
                navCall = `notif.markRead('${n.id}');document.getElementById('notif-panel').style.display='none';if(window.MatchDashboard)window.MatchDashboard.open('${mId}');`;
            } else if (n.type === 'match_invite' || n.type === 'match') {
                navCall = `notif.markRead('${n.id}');document.getElementById('notif-panel').style.display='none';if(typeof switchDashboardTab==='function')switchDashboardTab('jugador','mis-partidos',null);`;
            } else if (n.type === 'prediction_bet') {
                navCall = `notif.markRead('${n.id}');document.getElementById('notif-panel').style.display='none';if(typeof switchDashboardTab==='function')switchDashboardTab('jugador','mundo-futbol',null);`;
            }
            return `
            <div onclick="${navCall}" style="display:flex;align-items:flex-start;gap:12px;padding:12px 16px;border-bottom:1px solid rgba(255,255,255,0.04);cursor:pointer;background:${n.read ? 'transparent' : 'rgba(186,255,0,0.03)'};" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background='${n.read?'transparent':'rgba(186,255,0,0.03)'}'">
                <div style="width:32px;height:32px;border-radius:50%;background:${colors[n.type]||'#555'}22;display:flex;align-items:center;justify-content:center;flex-shrink:0;">
                    <i class='bx ${icons[n.type]||'bx-bell'}' style="color:${colors[n.type]||'#888'};font-size:16px;"></i>
                </div>
                <div style="flex:1;min-width:0;">
                    <div style="font-size:12px;line-height:1.4;">${n.message||''}</div>
                    <div style="font-size:10px;color:#555;margin-top:3px;">${timeStr(n.created_at)}</div>
                </div>
                ${!n.read ? '<div style="width:7px;height:7px;border-radius:50%;background:#baff00;flex-shrink:0;margin-top:4px;"></div>' : ''}
            </div>`;
        }).join('');
    }

    function timeStr(d) {
        if (!d) return '';
        const s = Math.floor((new Date() - new Date(d)) / 1000);
        if (s < 60) return 'Ahora';
        if (s < 3600) return `${Math.floor(s/60)} min`;
        if (s < 86400) return `${Math.floor(s/3600)}h`;
        return `${Math.floor(s/86400)}d`;
    }

    async function markRead(id) {
        const sb = getSb();
        if (!sb) return;
        try { await sb.from('notifications').update({ read: true }).eq('id', id); } catch(e) {}
        load();
    }

    async function markAllRead() {
        const email = getEmail();
        const sb = getSb();
        if (!email || !sb) return;
        try { await sb.from('notifications').update({ read: true }).eq('recipient_email', email).eq('read', false); } catch(e) {}
        load();
        const panel = document.getElementById('notif-panel');
        if (panel) panel.style.display = 'none';
        _panelOpen = false;
    }

    function togglePanel() {
        const panel = document.getElementById('notif-panel');
        if (!panel) return;
        _panelOpen = !_panelOpen;
        panel.style.display = _panelOpen ? 'flex' : 'none';
        if (_panelOpen) load();
    }

    // Create a notification for another user
    async function create(recipientEmail, type, actorName, message, postId = null) {
        const sb = getSb();
        const senderEmail = getEmail();
        if (!sb || !recipientEmail || recipientEmail === senderEmail) return;
        try {
            await sb.from('notifications').insert({
                recipient_email: recipientEmail, type, actor_name: actorName,
                actor_email: senderEmail, post_id: postId, message, read: false,
            });
        } catch(e) { console.warn('[notif.create]', e); }
    }

    // Supabase Realtime: listen for new posts and refresh feed
    function startRealtime() {
        const sb = getSb();
        if (!sb || _realtimeChannel) return;
        try {
            const myEmail = getEmail();
            _realtimeChannel = sb.channel('notif-realtime-' + (myEmail || 'anon'))
                .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'posts' }, () => {
                    const feedEl = document.getElementById('amigos-feed');
                    if (feedEl && document.getElementById('jugador-amigos') && document.getElementById('jugador-amigos').style.display !== 'none') {
                        social.loadFeed('amigos-feed');
                    }
                })
                .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications',
                    filter: myEmail ? `recipient_email=eq.${myEmail}` : undefined }, () => {
                    // Nueva notificación → recargar campana en tiempo real
                    load();
                })
                .subscribe();
        } catch(e) {}
    }

    function showBell(show) {
        const wrap = document.getElementById('notif-bell-wrap');
        if (wrap) wrap.style.display = show ? 'flex' : 'none';
        if (show) { load(); startRealtime(); }
    }

    // Close panel when clicking outside
    document.addEventListener('click', (e) => {
        if (_panelOpen && !e.target.closest('#notif-bell-wrap')) {
            const panel = document.getElementById('notif-panel');
            if (panel) panel.style.display = 'none';
            _panelOpen = false;
        }
    });

    return { load, togglePanel, markRead, markAllRead, create, showBell, startRealtime };
})();

// Expose notif globally. Para evitar DOBLE sistema de notificaciones (este + CancheroNotif)
// que renderizan al mismo #notif-list y se pisan dejando el panel vacío:
// si CancheroNotif está disponible, este objeto delega en él (un solo origen de verdad).
window.notif = new Proxy(notif, {
    get(target, prop) {
        const CN = window.CancheroNotif;
        if (CN && typeof CN[prop] === 'function') return CN[prop].bind(CN);
        return target[prop];
    }
});
// Neutralizar el realtime/load propio de este objeto si CancheroNotif maneja la campana
setTimeout(function(){
    if (window.CancheroNotif) {
        try { notif.startRealtime = function(){}; notif.load = function(){ if (window.CancheroNotif) window.CancheroNotif.load(); }; } catch(e){}
    }
}, 1500);

// Hook: show bell + create notifications on like/comment
// Patch social.toggleLike to also create notification
const _origToggleLike = window.likePost;
window.likePost = async function(el) {
    const postId = el.dataset ? el.dataset.postId : null;
    await social.toggleLike(el);
    // Notify post owner usando el cliente compartido
    if (postId && window._sb) {
        try {
            const { data: post } = await window._sb.from('posts').select('user_email,user_name').eq('id', postId).single();
            if (post) {
                const me = window.userData;
                if (post.user_email !== (me && me.email)) {
                    notif.create(post.user_email, 'like', (me&&me.name)||'Alguien', `❤️ ${(me&&me.name)||'Alguien'} le dio like a tu publicación.`, postId);
                }
            }
        } catch(e) {}
    }
};

// Show bell when user logs in
const _origApplyUserData = window.applyUserData;
window.applyUserData = function() {
    if (_origApplyUserData) _origApplyUserData();
    notif.showBell(true);
    // Perfiles múltiples: renderizar el switcher centrado en el header
    try { if (window.userData && window.userData.email && window._renderProfileSwitcher) window._renderProfileSwitcher(); } catch(e) {}
    // Reconstruir la barra inferior según el rol ACTIVO (fanático=Comunidades,
    // equipo=7 ítems). Al cargar, la ruleta se arma antes de restaurar la sesión
    // y quedaba con la barra de jugador aunque el rol activo fuera otro.
    try { if (window.userData && window.userData.email && window._rebuildBottomNav) window._rebuildBottomNav(); } catch(e) {}
    // Adoptar roles/rol activo guardados en la DB (multi-dispositivo, 1 vez por sesión)
    setTimeout(() => { try { window._syncRolesFromDb && window._syncRolesFromDb(); } catch(e) {} }, 1200);
    // Inicializar módulos de mensajería y notificaciones extendidas
    if (typeof window.CancheroNotif !== 'undefined') window.CancheroNotif.init();
    if (typeof window.CancheroMessaging !== 'undefined') window.CancheroMessaging.init();
    // Cargar notificaciones de directos pendientes de aceptar
    if (typeof window.CancheroLive !== 'undefined' && window.userData) {
        setTimeout(() => { try { CancheroLive.loadPinnedLiveNotifications(); } catch(e) {} }, 1200);
    }
    // Inicializar Realtime para likes/comentarios/posts en tiempo real
    setTimeout(() => { try { if (typeof window._initFeedRealtime === 'function') window._initFeedRealtime(); } catch(e) {} }, 800);
    // Inicializar badge de mensajes en tiempo real (canal dedicado, robusto)
    setTimeout(() => { try { window._initMsgBadgeRealtime(); } catch(e) {} }, 1600);
};

// ── Badge de mensajes en tiempo real — canal dedicado e independiente ──
window._msgBadgeChannel = null;
window._initMsgBadgeRealtime = function() {
    const sb = window._sb;
    const email = window.userData && window.userData.email;
    if (!sb || !email) return;
    // limpiar canal anterior
    try { if (window._msgBadgeChannel) sb.removeChannel(window._msgBadgeChannel); } catch(e) {}

    async function refreshBadge() {
        try {
            const { count } = await sb.from('messages').select('id', { count: 'exact', head: true })
                .eq('recipient_email', email).eq('read', false);
            const badge = document.getElementById('mobile-msg-badge');
            if (badge) {
                if (count > 0) { badge.textContent = count > 9 ? '9+' : String(count); badge.style.display = 'flex'; }
                else { badge.style.display = 'none'; }
            }
        } catch(e) {}
    }
    refreshBadge(); // estado inicial

    window._msgBadgeChannel = sb.channel('msgbadge-' + email)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: 'recipient_email=eq.' + email }, (payload) => {
            const m = payload.new;
            refreshBadge();
            // Toast + notificación nativa si no estoy viendo ese chat
            try {
                const viewing = window.CancheroMessaging && window.CancheroMessaging._activeThreadEmail && window.CancheroMessaging._activeThreadEmail() === (m && m.sender_email);
                if (viewing || !m) return;
                const senderName = m.sender_name || (m.sender_email||'').split('@')[0] || 'Mensaje';
                const preview = m.media_type === 'image' ? '📷 Foto' : (m.media_type === 'audio' ? '🎤 Audio' : (m.content || 'Nuevo mensaje'));
                if (typeof showToast === 'function') showToast(senderName + ': ' + preview, 'info');
                if ('Notification' in window && Notification.permission === 'granted' && document.visibilityState !== 'visible') {
                    const n = new Notification('💬 ' + senderName, { body: preview, icon: '/logo-oficial.png', tag: 'msg-'+(m.sender_email||'') });
                    n.onclick = function(){ window.focus(); if (typeof switchDashboardTab==='function') switchDashboardTab('jugador','mensajes',null); setTimeout(()=>{ if(window.CancheroMessaging) window.CancheroMessaging.openThread('dm',null,m.sender_email,senderName); },300); n.close(); };
                }
            } catch(e) {}
        })
        .subscribe();
    // Refrescar el badge al marcar como leído también (cuando abrís un chat)
    window._refreshMsgBadge = refreshBadge;
};

