// --- FEED PRINCIPAL con filtros ---
let _feedFilter = 'all';
let _feedSubFilter = 'all';
let _feedLocation = 'all';
let _feedMapInstance = null;

let _feedMenuOpen = false;

window.toggleFeedCategoryMenu = function() {
    const menu = document.getElementById('feed-category-menu');
    const arrow = document.getElementById('feed-cat-arrow');
    if (!menu) return;
    _feedMenuOpen = !_feedMenuOpen;
    menu.style.display = _feedMenuOpen ? 'block' : 'none';
    if (arrow) arrow.style.transform = _feedMenuOpen ? 'rotate(180deg)' : 'rotate(0deg)';
};

// Cierra el menú de filtros y fija el label (para Ver todo/Seguidos/Disponibles)
window.pickFeedLabel = function(label) {
    const menu = document.getElementById('feed-category-menu');
    const arrow = document.getElementById('feed-cat-arrow');
    if (menu) menu.style.display = 'none';
    if (arrow) arrow.style.transform = 'rotate(0deg)';
    _feedMenuOpen = false;
    const lbl = document.getElementById('feed-active-label');
    if (lbl) lbl.textContent = label;
    document.querySelectorAll('.feed-cat-item').forEach(b => b.classList.remove('active'));
};

// Desplegable EXPLORAR (rankings/clubes/jugadores/complejos) junto al buscador
window.toggleExploreMenu = function(event) {
    if (event) event.stopPropagation();
    const menu = document.getElementById('explore-menu');
    if (!menu) return;
    const open = menu.style.display === 'block';
    menu.style.display = open ? 'none' : 'block';
    if (!open) {
        const close = function(e) {
            if (!menu.contains(e.target) && !(e.target.closest && e.target.closest('[onclick*="toggleExploreMenu"]'))) {
                menu.style.display = 'none';
                document.removeEventListener('click', close);
            }
        };
        setTimeout(function(){ document.addEventListener('click', close); }, 60);
    }
};

window.pickFeedCategory = function(filter, label, itemEl) {
    // Cerrar menú
    const menu = document.getElementById('feed-category-menu');
    const arrow = document.getElementById('feed-cat-arrow');
    if (menu) menu.style.display = 'none';
    if (arrow) arrow.style.transform = 'rotate(0deg)';
    _feedMenuOpen = false;
    // Actualizar label del toggle
    const lbl = document.getElementById('feed-active-label');
    if (lbl) lbl.textContent = label;
    // Desactivar VER TODO
    const allBtn = document.getElementById('feed-btn-all');
    if (allBtn) allBtn.classList.remove('active');
    // Marcar toggle como activo
    const toggle = document.getElementById('feed-category-toggle');
    if (toggle) { toggle.style.borderColor = 'var(--accent)'; toggle.style.color = 'var(--accent)'; }
    // Marcar item activo
    document.querySelectorAll('.feed-cat-item').forEach(b => b.classList.remove('active'));
    if (itemEl) itemEl.classList.add('active');
    // Aplicar filtro
    setFeedFilter(filter, null);
};

// Cerrar menú al clic fuera
document.addEventListener('click', function(e) {
    if (_feedMenuOpen && !e.target.closest('#feed-filter-bar')) {
        const menu = document.getElementById('feed-category-menu');
        const arrow = document.getElementById('feed-cat-arrow');
        if (menu) menu.style.display = 'none';
        if (arrow) arrow.style.transform = 'rotate(0deg)';
        _feedMenuOpen = false;
    }
});

// ── WIZARD GENÉRICO: convierte un formulario largo en pasos de a 2-3 campos ──
// Mantiene los MISMOS campos e IDs (no rompe la lógica de creación existente).
window._wizardize = function(tabId, opts) {
    opts = opts || {};
    const panel = document.querySelector('#' + tabId + ' .panel');
    if (!panel) return;
    if (panel.dataset.wizard === '1') { panel._wIdx = 0; window._wizardShow(panel, tabId); return; }
    panel.dataset.wizard = '1';
    const kids = [...panel.children];
    const submit = kids.filter(k => k.tagName === 'BUTTON' && /crear|guardar|publicar/i.test(k.textContent)).pop() || kids.filter(k => k.tagName === 'BUTTON').pop();
    const blocks = kids.filter(k => k !== submit);
    const PER = opts.perStep || 3;
    const steps = []; let cur = []; let w = 0;
    blocks.forEach(b => {
        const isField = b.classList && (b.classList.contains('form-group') || b.classList.contains('form-row'));
        if (isField && w >= PER) { steps.push(cur); cur = []; w = 0; }
        cur.push(b);
        if (isField) w++;
    });
    if (cur.length) steps.push(cur);
    panel._wSteps = steps; panel._wIdx = 0; panel._wSubmit = submit;
    if (submit) submit.style.display = 'none';
    const nav = document.createElement('div');
    nav.id = tabId + '-wizard-nav';
    nav.style.cssText = 'margin-top:18px;';
    nav.innerHTML = `
        <div id="${tabId}-wdots" style="display:flex;justify-content:center;gap:7px;margin-bottom:14px;"></div>
        <div style="display:flex;gap:10px;">
            <button id="${tabId}-wback" style="flex:1;background:transparent;border:1px solid #2a2a2a;color:#888;border-radius:12px;padding:13px;font-weight:800;font-size:13px;cursor:pointer;font-family:inherit;">← ATRÁS</button>
            <button id="${tabId}-wnext" style="flex:2;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:14px;cursor:pointer;font-family:inherit;box-shadow:0 0 16px rgba(186,255,0,0.25);">SIGUIENTE →</button>
        </div>`;
    panel.appendChild(nav);
    document.getElementById(tabId + '-wback').onclick = () => { if (panel._wIdx > 0) { panel._wIdx--; window._wizardShow(panel, tabId); } };
    document.getElementById(tabId + '-wnext').onclick = () => {
        if (panel._wIdx < panel._wSteps.length - 1) { panel._wIdx++; window._wizardShow(panel, tabId); }
        else if (panel._wSubmit) panel._wSubmit.click();
    };
    window._wizardShow(panel, tabId);
};
window._wizardShow = function(panel, tabId) {
    if (!panel || !panel._wSteps) return;
    const steps = panel._wSteps, idx = panel._wIdx;
    steps.forEach((blocks, i) => blocks.forEach(b => {
        if (i === idx) {
            if ('_wPrev' in b.dataset) { b.style.display = b.dataset._wPrev; delete b.dataset._wPrev; }
        } else {
            if (!('_wPrev' in b.dataset)) b.dataset._wPrev = b.style.display || '';
            b.style.display = 'none';
        }
    }));
    const dots = document.getElementById(tabId + '-wdots');
    if (dots) dots.innerHTML = steps.map((_, i) => `<span style="width:${i===idx?'22px':'8px'};height:8px;border-radius:8px;background:${i<=idx?'var(--accent)':'#2a2a2a'};transition:.25s;"></span>`).join('');
    const back = document.getElementById(tabId + '-wback');
    const next = document.getElementById(tabId + '-wnext');
    if (back) back.style.visibility = idx === 0 ? 'hidden' : 'visible';
    if (next) next.innerHTML = idx === steps.length - 1 ? '⚽ CREAR' : `SIGUIENTE → <span style="font-weight:400;font-size:11px;opacity:0.7;">(${idx+1}/${steps.length})</span>`;
    const tab = document.getElementById(tabId);
    if (tab) { try { tab.scrollIntoView({ block: 'start' }); } catch(e){} }
    try { window.scrollTo(0, 0); } catch(e){}
    // El mapa Leaflet se crea con el paso oculto (tamaño 0) y queda negro:
    // recalcular tamaño cuando el paso que lo contiene se hace visible.
    setTimeout(function(){ try { if (window._cpMap && document.getElementById('cp-leaflet-map') && document.getElementById('cp-leaflet-map').offsetParent) window._cpMap.invalidateSize(); } catch(e){} }, 180);
};

// ── Composer fino estilo X: colapsado por defecto, se expande al tocar ──
window._composerExpand = function(open) {
    const box = document.getElementById('feed-composer-box');
    const actions = document.getElementById('feed-composer-actions');
    const ta = document.getElementById('feed-post-text');
    if (!box || !actions || !ta) return;
    if (open) {
        box.style.padding = '14px 16px';
        ta.style.minHeight = '64px';
        actions.style.display = 'flex';
    } else {
        box.style.padding = '9px 14px';
        ta.style.minHeight = '24px';
        actions.style.display = 'none';
        const menu = document.getElementById('feed-composer-menu');
        if (menu) menu.style.display = 'none';
    }
};
window._composerMenuToggle = function(force) {
    const menu = document.getElementById('feed-composer-menu');
    if (!menu) return;
    const show = (typeof force === 'boolean') ? force : menu.style.display === 'none';
    menu.style.display = show ? 'block' : 'none';
};
// Colapsar al tocar fuera si está vacío y sin media
document.addEventListener('click', function(e) {
    const box = document.getElementById('feed-composer-box');
    if (!box || box.contains(e.target)) return;
    const ta = document.getElementById('feed-post-text');
    const prev = document.getElementById('feed-post-preview');
    const hasMedia = prev && prev.style.display !== 'none' && prev.innerHTML.trim();
    if (ta && !ta.value.trim() && !hasMedia) window._composerExpand(false);
});

// Pills "Para ti / Siguiendo" del feed — bloque segmentado
window._setFeedScope = function(scope) {
    const pa = document.getElementById('feed-scope-parati');
    const si = document.getElementById('feed-scope-siguiendo');
    const base = 'flex:1;padding:9px 0;font-family:var(--font-display);font-size:12px;font-weight:800;letter-spacing:0.5px;border:none;cursor:pointer;transition:background .2s,color .2s;';
    const on  = base + 'background:var(--accent);color:#000;';
    const off = base + 'background:transparent;color:#888;';
    if (pa) pa.style.cssText = scope === 'all' ? on : off;
    if (si) si.style.cssText = scope === 'siguiendo' ? on : off;
    window.setFeedFilter(scope, document.getElementById(scope === 'all' ? 'feed-btn-all' : 'feed-btn-siguiendo'));
};

window.setFeedFilter = function(filter, btn) {
    _feedFilter = filter;
    // Persistir filtro activo para restaurar al recargar
    try { localStorage.setItem('canchero_last_feedfilter', filter); } catch(e) {}
    // Resetear botones de filtro superior
    document.querySelectorAll('.feed-filter-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    // Si se llama directamente (VER TODO), resetear toggle
    if (filter === 'all') {
        const lbl = document.getElementById('feed-active-label');
        if (lbl) lbl.textContent = 'CATEGORÍA';
        const toggle = document.getElementById('feed-category-toggle');
        if (toggle) { toggle.style.borderColor = '#333'; toggle.style.color = '#aaa'; }
        document.querySelectorAll('.feed-cat-item').forEach(b => b.classList.remove('active'));
    }
    const subFilters = document.getElementById('feed-prof-subfilters');
    const locBar = document.getElementById('feed-location-bar');
    const dispLocBar = document.getElementById('disponibles-location-bar');
    if (subFilters) subFilters.style.display = (filter === 'profesional') ? 'block' : 'none';
    if (locBar) locBar.style.display = (filter !== 'all' && filter !== 'siguiendo' && filter !== 'jugador' && filter !== 'disponibles') ? 'flex' : 'none';
    if (dispLocBar) dispLocBar.style.display = (filter === 'disponibles') ? 'flex' : 'none';
    if (filter !== 'profesional') { _feedSubFilter = 'all'; }
    if (filter === 'disponibles') {
        loadDisponibles('ciudad', document.querySelector('.disp-loc-btn'));
    } else {
        loadMainFeed();
    }
};

window.setSubFilter = function(sub, btn) {
    _feedSubFilter = sub;
    document.querySelectorAll('#feed-prof-subfilters .feed-filter-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    loadMainFeed();
};

window.setLocationFilter = function(loc) {
    _feedLocation = loc;
    loadMainFeed();
};

window.toggleFeedMap = function() {
    const mapEl = document.getElementById('feed-map-container');
    if (!mapEl) return;
    if (mapEl.style.display === 'none' || !mapEl.style.display) {
        mapEl.style.display = 'block';
        if (!_feedMapInstance && window.L) {
            _feedMapInstance = L.map('feed-map-container', { zoomControl: true }).setView([-32.5, -56.0], 6);
            L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '© OpenStreetMap' }).addTo(_feedMapInstance);
        } else if (_feedMapInstance) { _feedMapInstance.invalidateSize(); }
    } else {
        mapEl.style.display = 'none';
    }
};

