// Alias de compatibilidad
window.CITY_DATA = window.CITIES_BY_COUNTRY;
try { CITY_DATA = window.CITIES_BY_COUNTRY; } catch(e) {}

window.getCitiesForCountry = function(country) {
    if (!country) return [];
    // Búsqueda exacta primero, luego por coincidencia parcial
    if (window.CITIES_BY_COUNTRY[country]) return window.CITIES_BY_COUNTRY[country];
    const match = Object.keys(window.CITIES_BY_COUNTRY).find(k => k.toLowerCase() === country.toLowerCase());
    return match ? window.CITIES_BY_COUNTRY[match] : [];
};

window.updateCitySelectForCountry = function(countrySelectId, citySelectId, defaultCityPrompt) {
    const countryEl = document.getElementById(countrySelectId);
    const cityEl = document.getElementById(citySelectId);
    if (!countryEl || !cityEl) return;
    const country = countryEl.value;
    const cities = getCitiesForCountry(country);
    cityEl.innerHTML = `<option value="">${defaultCityPrompt || 'Seleccioná ciudad'}</option>` +
        cities.map(c => `<option value="${c}">${c}</option>`).join('');
};

// ── Lista de países ordenada (Uruguay y región primero) ──
window.getOrderedCountries = function() {
    const all = Object.keys(window.CITIES_BY_COUNTRY || {});
    const priority = ['Uruguay','Argentina','Brasil','Chile','Paraguay','Costa Rica','Panamá','Cuba','Haití','Jamaica','España','Portugal','Alemania','Italia','Polonia','Nigeria','Sudáfrica','Kenia','Marruecos','Tanzania','Japón','India','Turquía','Indonesia','Malasia','Australia','Papúa Nueva Guinea','Fiji','Islas Salomón','Vanuatu'];
    const rest = all.filter(c => !priority.includes(c)).sort((a,b)=>a.localeCompare(b,'es'));
    return [...priority.filter(c => all.includes(c)), ...rest];
};

// ── Inicializa un par de selects (país + ciudad) enlazados ──
// countryId/cityId: ids de los <select>. opts: { defaultCountry, defaultCity, countryPrompt, cityPrompt, onCountryChange }
window.buildLocationSelects = function(countryId, cityId, opts) {
    opts = opts || {};
    const ctrySel = document.getElementById(countryId);
    const citySel = document.getElementById(cityId);
    if (!ctrySel || !citySel) return;
    const sorted = window.getOrderedCountries();
    const defCountry = opts.defaultCountry || '';
    ctrySel.innerHTML = (opts.countryPrompt !== false ? `<option value="">${opts.countryPrompt || 'Elegí un país...'}</option>` : '') +
        sorted.map(c => `<option value="${c}"${c === defCountry ? ' selected' : ''}>${c}</option>`).join('');
    function _updateCities() {
        const country = ctrySel.value;
        const cities = (window.CITIES_BY_COUNTRY && window.CITIES_BY_COUNTRY[country]) || [];
        citySel.innerHTML = `<option value="">${opts.cityPrompt || 'Elegí una ciudad...'}</option>` +
            cities.map(c => `<option value="${c}"${c === opts.defaultCity ? ' selected' : ''}>${c}</option>`).join('');
        if (typeof opts.onCountryChange === 'function') opts.onCountryChange(country, cities);
    }
    // Evitar listeners duplicados
    if (ctrySel._locHandler) ctrySel.removeEventListener('change', ctrySel._locHandler);
    ctrySel._locHandler = _updateCities;
    ctrySel.addEventListener('change', _updateCities);
    _updateCities();
};

// Inicializa TODOS los pares de selects país+ciudad presentes en el DOM
window.initAllLocationSelects = function() {
    const pairs = [
        // reg-nat/reg-city lo maneja initCountrySelect()
        ['cp-pais','cp-ciudad',{defaultCountry:'Uruguay',cityPrompt:'Elegí una ciudad...'}],
        ['complejos-country-filter','complejos-city-filter',{defaultCountry:'Uruguay',countryPrompt:'Todo el mundo',cityPrompt:'Todo el país',onCountryChange:function(){ try{loadSectionTab('complejos');}catch(e){} }}],
        ['tiendas-country-filter','tiendas-city-filter',{defaultCountry:'Uruguay',countryPrompt:'Todo el mundo',cityPrompt:'Todo el país',onCountryChange:function(){ try{loadSectionTab('tiendas');}catch(e){} }}],
        ['profesionales-country-filter','profesionales-city-filter',{defaultCountry:'Uruguay',countryPrompt:'Todo el mundo',cityPrompt:'Todo el país',onCountryChange:function(){ try{loadSectionTab('profesionales');}catch(e){} }}],
        ['torneo-filter-pais','torneo-filter-ciudad',{countryPrompt:'Todo el mundo',cityPrompt:'Toda la ciudad',onCountryChange:function(){ try{loadTorneos();}catch(e){} }}],
        ['organizaciones-country-filter','organizaciones-city-filter',{defaultCountry:'Uruguay',countryPrompt:'Todo el mundo',cityPrompt:'Todo el país',onCountryChange:function(){ try{loadSectionTab('organizaciones');}catch(e){} }}],
        ['canchas-country-filter','canchas-dept-filter',{defaultCountry:'Uruguay',countryPrompt:'Todo el mundo',cityPrompt:'Todos los departamentos',onCountryChange:function(){ try{filterCanchas();}catch(e){} }}],
    ];
    pairs.forEach(([cId, ctId, o]) => { if (document.getElementById(cId) && document.getElementById(ctId)) { try { window.buildLocationSelects(cId, ctId, o); } catch(e){} } });
};
// Inicializar los selects de ubicación al cargar (y reintentar por si el DOM tarda)
(function(){
    function _initLoc(){ try { window.initAllLocationSelects(); } catch(e){} }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _initLoc);
    else _initLoc();
    setTimeout(_initLoc, 1200);
})();

