const _sectionActiveFilters = { complejos: new Set(), tiendas: new Set(), profesionales: new Set(), organizaciones: new Set() };

window.loadSectionTab = async function(section, searchQuery) {
    const cfg = SECTION_CONFIG[section];
    if (!cfg) return;

    const container = document.getElementById(`${section}-feed-container`);
    if (!container) return;

    // Renderizar botones de filtro si no están
    const filtersDiv = document.getElementById(`${section}-filters`);
    if (filtersDiv && filtersDiv.children.length === 0) {
        filtersDiv.innerHTML = cfg.filters.map(f => `
            <button class="section-filter-btn" id="sfbtn-${section}-${f.id}"
                onclick="toggleSectionFilter('${section}','${f.id}')"
                style="padding:6px 14px;border-radius:20px;border:1px solid #333;background:transparent;color:#888;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap;transition:all 0.2s;font-family:inherit;">
                ${f.label}
            </button>`).join('');
    }

    container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:28px;"></i></div>`;

    const sb = window._sb;
    if (!sb) { container.innerHTML = `<div style="text-align:center;padding:30px;color:#555;">Sin conexión.</div>`; return; }

    const activeFilters = Array.from(_sectionActiveFilters[section]);
    const cityFilter = document.getElementById(`${section}-city-filter`)?.value || '';
    const countryFilter = document.getElementById(`${section}-country-filter`)?.value || '';
    const query = searchQuery !== undefined ? searchQuery : (document.getElementById(`search-${section}`)?.value?.trim() || '');

    try {
        let q = sb.from('users')
            .select('*')
            .in('role', cfg.roles)
            .order('name')
            .limit(200);

        if (cityFilter) q = q.ilike('city', `%${cityFilter}%`);
        if (query) q = q.ilike('name', `${query}%`);

        let { data, error } = await q;
        if (error) throw error;
        data = data || [];

        // Multi-identidad: los negocios creados desde el switcher viven en business_requests
        // (users.role del email puede seguir siendo 'jugador') → sin este bloque, esas
        // organizaciones/tiendas/complejos NO aparecen en Buscar.
        try {
            const _bizRoleSet = ['club','complejo','cancha','tienda','store','shop','profesional','organizacion','liga','escuela','sponsor'];
            const bizRolesWanted = cfg.roles.filter(r => _bizRoleSet.indexOf(r) !== -1);
            if (bizRolesWanted.length) {
                let bq = sb.from('business_requests').select('id,email,name,role,payload').in('role', bizRolesWanted).limit(300);
                if (query) bq = bq.ilike('name', `${query}%`);
                const { data: brs } = await bq;
                if (brs && brs.length) {
                    const have = new Set(data.map(u => (u.email||'').toLowerCase()));
                    const extraEmails = [...new Set(brs.map(b => (b.email||'').toLowerCase()).filter(e => e && !have.has(e)))];
                    const uByEmail = {};
                    if (extraEmails.length) {
                        const { data: us } = await sb.from('users').select('email,city,nat,country,photo').in('email', extraEmails);
                        (us||[]).forEach(u => { uByEmail[(u.email||'').toLowerCase()] = u; });
                    }
                    brs.forEach(b => {
                        const em = (b.email||'').toLowerCase();
                        if (!em || have.has(em)) return; // ya está: el bloque de branding lo expande
                        let pl = b.payload || {}; try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
                        const u0 = uByEmail[em] || {};
                        const cty = pl.city || u0.city || '';
                        if (cityFilter && cty.toLowerCase().indexOf(cityFilter.toLowerCase()) === -1) return;
                        data.push({ email: b.email, name: b.name, role: b.role, city: cty, nat: u0.nat || '', country: pl.country || u0.country || '', photo: pl.photo || pl.logo || u0.photo || '', cover_photo: pl.cover || pl.coverPhoto || pl.cover_photo || '', _bizId: String(b.id) });
                    });
                }
            }
        } catch(e){ console.warn('directorio biz extra:', e); }

        // Filtro de PAÍS en memoria (tolerante a country/nat). Antes se ignoraba por
        // completo: elegir "Argentina" devolvía igual los negocios uruguayos.
        if (countryFilter) {
            const cf = countryFilter.toString().toLowerCase().trim();
            data = (data || []).filter(u => [u.country, u.nat, u.nationality, u.pais].some(c => (c||'').toString().toLowerCase().includes(cf)));
        }

        if (!data || data.length === 0) {
            container.innerHTML = `
                <div style="text-align:center;padding:40px 20px;">
                    <i class='bx ${cfg.icon}' style="font-size:48px;color:#222;display:block;margin-bottom:12px;"></i>
                    <div style="color:#555;font-size:14px;">${cfg.emptyMsg}</div>
                </div>`;
            return;
        }

        // Si hay filtros activos, filtrar también por bio/tags
        let filtered = data;
        if (activeFilters.length > 0) {
            filtered = data.filter(u => {
                const bioLower = (u.bio || '').toLowerCase();
                return activeFilters.some(f => bioLower.includes(f));
            });
        }

        if (filtered.length === 0) {
            container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><i class='bx ${cfg.icon}' style="font-size:40px;color:#222;display:block;margin-bottom:10px;"></i><div style="font-size:13px;">Sin resultados para los filtros seleccionados.</div><button class="btn btn-glass" style="margin-top:12px;font-size:12px;" onclick="_sectionActiveFilters['${section}'].clear();document.querySelectorAll('[id^=sfbtn-${section}]').forEach(b=>{b.style.background='transparent';b.style.borderColor='#333';b.style.color='#888';});loadSectionTab('${section}')">Quitar filtros</button></div>`;
            return;
        }

        // Nombre COMERCIAL del negocio (no el de la persona): cada negocio del email
        // es su propia tarjeta, con branding del payload de business_requests.
        try {
            const _bizEmails = [...new Set(filtered.map(u => u.email).filter(Boolean))];
            if (_bizEmails.length) {
                const { data: _brs } = await sb.from('business_requests').select('id,email,name,role,payload').in('email', _bizEmails);
                if (_brs && _brs.length) {
                    const _byEmail = {};
                    _brs.forEach(b => { (_byEmail[(b.email||'').toLowerCase()] = _byEmail[(b.email||'').toLowerCase()] || []).push(b); });
                    const _rolesOk = (r) => cfg.roles.indexOf(r) !== -1 || (cfg.roles.indexOf('club') !== -1 && (r === 'complejo' || r === 'cancha'));
                    const _expanded = [];
                    filtered.forEach(u => {
                        const mine = (_byEmail[(u.email||'').toLowerCase()] || []).filter(b => _rolesOk((b.role||'').toLowerCase()));
                        if (!mine.length) { _expanded.push(u); return; }
                        mine.forEach(b => {
                            let pl = b.payload || {}; try { if (typeof pl === 'string') pl = JSON.parse(pl); } catch(e){ pl = {}; }
                            _expanded.push(Object.assign({}, u, {
                                name: b.name || u.name,
                                photo: b.photo || pl.photo || pl.logo || '',
                                photo_style: null,
                                cover_photo: pl.cover || pl.coverPhoto || pl.cover_photo || '',
                                role: b.role || u.role,
                                _bizId: String(b.id)
                            }));
                        });
                    });
                    filtered = _expanded;
                }
            }
        } catch(e){ console.warn('directorio biz names:', e); }

        const roleIcon = { club:'bx-cancha', complejo:'bx-cancha', cancha:'bx-cancha', tienda:'bx-store', store:'bx-store', shop:'bx-store', profesional:'bx-briefcase', dt:'bx-clipboard', arbitro:'bx-whistle', preparador:'bx-dumbbell', fotografo:'bx-camera', scout:'bx-search-alt', kinesiologo:'bx-plus-medical', organizacion:'bx-trophy', liga:'bx-trophy', escuela:'bx-trophy' };
        const roleName = { club:'Complejo', complejo:'Complejo', cancha:'Complejo', tienda:'Tienda', store:'Tienda', shop:'Tienda', profesional:'Profesional', dt:'DT', arbitro:'Árbitro', preparador:'Prep. Físico', fotografo:'Fotógrafo', scout:'Scout', kinesiologo:'Kinesiólogo', organizacion:'Organización', liga:'Liga', escuela:'Escuela' };
        container.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">' + filtered.map(u => {
            const initials = (u.name||'?')[0].toUpperCase();
            const ic = roleIcon[u.role] || cfg.icon;
            // Portada (banner) — usa cover_photo, sino gradiente glass
            const coverBg = u.cover_photo
                ? `background:url('${u.cover_photo}') center/cover;`
                : `background:linear-gradient(135deg,rgba(186,255,0,0.10),rgba(255,255,255,0.02));`;
            // Avatar con encuadre
            let avPos='center', avSize='cover';
            if (u.photo_style) { try { const st=typeof u.photo_style==='string'?JSON.parse(u.photo_style):u.photo_style; avPos=(50+parseInt(st.x||0))+'% '+(50+parseInt(st.y||0))+'%'; const z=parseFloat(st.zoom||100); if(z>100) avSize=z+'%'; } catch(e){} }
            const avHtml = u.photo
                ? `<div style="width:48px;height:48px;border-radius:50%;background-image:url('${u.photo}');background-size:${avSize};background-position:${avPos};border:3px solid #0a0a0a;background-color:#111;"></div>`
                : `<div style="width:48px;height:48px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;font-weight:900;color:#000;font-size:18px;border:3px solid #0a0a0a;">${initials}</div>`;
            return `
                <div onclick="viewUserProfile('${u.email}', true${u._bizId ? `, { bizId: '${u._bizId}' }` : ''})" style="background:#0d0d0d;border:1px solid rgba(255,255,255,0.07);border-radius:16px;overflow:hidden;cursor:pointer;transition:transform .15s, border-color .15s;" onmouseenter="this.style.borderColor='rgba(186,255,0,0.3)';this.style.transform='translateY(-2px)'" onmouseleave="this.style.borderColor='rgba(255,255,255,0.07)';this.style.transform='none'">
                    <div style="height:64px;${coverBg}position:relative;">
                        <div style="position:absolute;left:12px;bottom:-22px;">${avHtml}</div>
                    </div>
                    <div style="padding:26px 12px 14px;">
                        <div style="font-weight:900;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${u.name||'Sin nombre'}</div>
                        <div style="font-size:10.5px;color:var(--accent);font-weight:800;display:flex;align-items:center;gap:4px;margin-top:2px;"><i class='bx ${ic}'></i> ${roleName[u.role]||u.role||''}</div>
                        ${u.city || u.nat ? `<div style="font-size:10.5px;color:#666;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"><i class='bx bx-map-pin'></i> ${[u.city,u.nat].filter(Boolean).join(', ')}</div>` : ''}
                    </div>
                </div>`;
        }).join('') + '</div>';
    } catch(e) {
        container.innerHTML = `<div style="text-align:center;padding:30px;color:#555;">Error al cargar: ${e.message}</div>`;
    }
};

// Abrir/cerrar panel de filtros
window._toggleFilterPanel = function(panelId, toggleId) {
    const panel = document.getElementById(panelId);
    const toggle = document.getElementById(toggleId);
    if (!panel) return;
    const isOpen = panel.style.display === 'block';
    panel.style.display = isOpen ? 'none' : 'block';
    const arrow = panel.previousElementSibling?.querySelector('[id$="-filter-arrow"]') ||
                  toggle?.querySelector('i:last-child');
    if (arrow) arrow.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
    // Cerrar al hacer click fuera
    if (!isOpen) {
        const closer = (e) => {
            if (!panel.contains(e.target) && e.target.id !== toggleId && !toggle?.contains(e.target)) {
                panel.style.display = 'none';
                if (arrow) arrow.style.transform = 'rotate(0deg)';
                document.removeEventListener('click', closer);
            }
        };
        setTimeout(() => document.addEventListener('click', closer), 0);
    }
};

window._closeFilterPanel = function(panelId, toggleId, arrowId) {
    const panel = document.getElementById(panelId);
    const arrow = arrowId ? document.getElementById(arrowId) : null;
    if (panel) panel.style.display = 'none';
    if (arrow) arrow.style.transform = 'rotate(0deg)';
};

// Renderizar chips de filtros activos
function _renderActiveFilterChips(section) {
    const chipsContainer = document.getElementById(`${section}-active-chips`);
    if (!chipsContainer) return;
    const active = Array.from(_sectionActiveFilters[section]);
    if (active.length === 0) { chipsContainer.style.display = 'none'; chipsContainer.innerHTML = ''; return; }
    chipsContainer.style.display = 'flex';
    const cfg = SECTION_CONFIG[section];
    chipsContainer.innerHTML = active.map(f => {
        const label = cfg?.filters?.find(x => x.id === f)?.label || f;
        return `<span style="display:inline-flex;align-items:center;gap:6px;background:rgba(186,255,0,0.12);border:1px solid rgba(186,255,0,0.3);color:var(--accent);border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;">
            ${label}
            <button onclick="window.toggleSectionFilter('${section}','${f}')" style="background:none;border:none;color:var(--accent);cursor:pointer;font-size:14px;line-height:1;padding:0;">✕</button>
        </span>`;
    }).join('');
}

window.toggleSectionFilter = function(section, filterId) {
    const filters = _sectionActiveFilters[section];
    const btn = document.getElementById(`sfbtn-${section}-${filterId}`);
    if (filters.has(filterId)) {
        filters.delete(filterId);
        if (btn) { btn.style.background = 'transparent'; btn.style.borderColor = '#333'; btn.style.color = '#888'; }
    } else {
        filters.add(filterId);
        if (btn) { btn.style.background = 'rgba(186,255,0,0.15)'; btn.style.borderColor = 'var(--accent)'; btn.style.color = 'var(--accent)'; }
    }
    _renderActiveFilterChips(section);
    // Actualizar contador en botón FILTROS
    const count = _sectionActiveFilters[section].size;
    const toggle = document.getElementById(`${section}-filter-toggle`);
    if (toggle) {
        const countBadge = toggle.querySelector('.filter-count-badge');
        if (count > 0) {
            if (countBadge) { countBadge.textContent = count; }
            else {
                const badge = document.createElement('span');
                badge.className = 'filter-count-badge';
                badge.textContent = count;
                badge.style.cssText = 'background:var(--accent);color:#000;border-radius:50%;width:16px;height:16px;font-size:9px;font-weight:900;display:inline-flex;align-items:center;justify-content:center;margin-left:2px;';
                toggle.insertBefore(badge, toggle.querySelector('i:last-child'));
            }
            toggle.style.borderColor = 'var(--accent)';
            toggle.style.color = 'var(--accent)';
        } else {
            if (countBadge) countBadge.remove();
            toggle.style.borderColor = '#333';
            toggle.style.color = '#aaa';
        }
    }
    loadSectionTab(section);
};

window.sectionSearch = function(section, value) {
    clearTimeout(window[`_sectionSearchTimer_${section}`]);
    window[`_sectionSearchTimer_${section}`] = setTimeout(() => {
        loadSectionTab(section, value.trim());
    }, 250);
};

