// Juegos — URL de lanzamiento
function _buildGameProxyUrl(gameId) {
    const g = _GAMES_CATALOG[gameId];
    if (g && g.url) return g.url;
    return `/games/${gameId}.html`;
}

window.openGamesModal = function() {
    // Lanzar directamente el único juego disponible
    launchGame('tiros-libres');
};

window.closeGamesModal = function() {
    const modal = document.getElementById('games-modal');
    if (!modal) return;
    modal.style.display = 'none';
    document.body.style.overflow = '';
};

// Abrir el juego en el player embebido (iframe con proxy)
window.launchGame = function(gameId) {
    const game = _GAMES_CATALOG[gameId];
    if (!game) return;

    // Cerrar el selector de juegos
    closeGamesModal();

    const playerModal = document.getElementById('game-player-modal');
    const iframe = document.getElementById('game-iframe');
    const title = document.getElementById('game-player-title');
    const loadingOverlay = document.getElementById('game-loading-overlay');

    if (!playerModal || !iframe) return;

    // Mostrar loading
    if (loadingOverlay) { loadingOverlay.style.display = 'flex'; }
    const fallbackBtn = document.getElementById('game-fallback-btn');
    if (fallbackBtn) fallbackBtn.style.display = 'none';

    // Setear título
    if (title) title.textContent = game.name.toUpperCase();

    // Setear src del iframe
    const gameUrl = _buildGameProxyUrl(gameId);
    iframe.src = gameUrl;

    // Timer fallback: si en 8s el loading sigue visible, mostrar botón de abrir externamente
    if (window._gameFallbackTimer) clearTimeout(window._gameFallbackTimer);
    window._gameFallbackTimer = setTimeout(() => {
        const lo = document.getElementById('game-loading-overlay');
        if (lo && lo.style.display !== 'none') {
            // El iframe no cargó — mostrar botón externo
            const spinner = lo.querySelector('div:first-child');
            if (spinner) spinner.style.display = 'none';
            const txt = lo.querySelector('div:nth-child(2)');
            if (txt) txt.style.display = 'none';
            const fb = document.getElementById('game-fallback-btn');
            if (fb) { fb.style.display = 'flex'; }
            // Intentar abrir directamente
            window.open(gameUrl, '_blank');
        }
    }, 8000);

    // Mostrar modal del player
    playerModal.style.display = 'flex';
    document.body.style.overflow = 'hidden';
};

window.closeGamePlayer = function() {
    const playerModal = document.getElementById('game-player-modal');
    const iframe = document.getElementById('game-iframe');
    if (!playerModal) return;
    // Salir de fullscreen si estaba activo
    if (document.fullscreenElement) { try { document.exitFullscreen(); } catch(e) {} }
    // Limpiar iframe para detener el juego y liberar memoria
    if (iframe) iframe.src = 'about:blank';
    playerModal.style.display = 'none';
    document.body.style.overflow = '';
    // NO volver a abrir el modal de juegos — simplemente cerrar
};

window.toggleGameFullscreen = function() {
    const playerModal = document.getElementById('game-player-modal');
    const icon = document.getElementById('fullscreen-icon');
    if (!playerModal) return;
    if (!document.fullscreenElement) {
        playerModal.requestFullscreen && playerModal.requestFullscreen();
        if (icon) { icon.classList.remove('bx-fullscreen'); icon.classList.add('bx-exit-fullscreen'); }
    } else {
        document.exitFullscreen && document.exitFullscreen();
        if (icon) { icon.classList.remove('bx-exit-fullscreen'); icon.classList.add('bx-fullscreen'); }
    }
};

// Salir de fullscreen al cerrar el player
document.addEventListener('fullscreenchange', () => {
    if (!document.fullscreenElement) {
        const icon = document.getElementById('fullscreen-icon');
        if (icon) { icon.classList.remove('bx-exit-fullscreen'); icon.classList.add('bx-fullscreen'); }
    }
});

function buildPostCard(p, isLiked) {
    if (isLiked === undefined) {
        const likedSet = window._myLikedPostIds;
        isLiked = likedSet ? likedSet.has(String(p.id)) : false;
    }
    const isOwn = userData && userData.email === p.user_email;
    const isPinned = p.pinned === true;
    const initials = (p.user_name||'?')[0].toUpperCase();
    // Usar la foto actual del usuario SOLO si el post fue hecho con el mismo rol:
    // los posts como club (escudo) o como fanático conservan su propia identidad
    // y el encuadre (photoStyle) del jugador no se aplica a fotos de otros roles.
    // OJO multi-identidad: userData.role queda 'jugador' aunque actúes como negocio →
    // comparar contra el rol REAL de publicación (_pubRole), y solo para jugador/fanático.
    const _actRoleCard = ((window._pubRole && window._pubRole()) || (userData && userData.role) || 'jugador').toLowerCase();
    const _postRoleCard = (p.user_role || 'jugador').toLowerCase();
    const _sameIdentity = isOwn && (_postRoleCard === 'jugador' || _postRoleCard === 'fanatico') && _postRoleCard === _actRoleCard;
    const avatarSrc = (_sameIdentity && userData && userData.photo) ? userData.photo : (p.user_photo || p.user_avatar || '');
    const photoStyle = (_sameIdentity && userData && userData.photoStyle) ? userData.photoStyle : (p.user_photo_style || null);
    // Default de recorte de ROSTRO (center 25%) — consistente con el perfil y momentos
    let _objPos = 'center 25%', _objSize = 'cover';
    if (photoStyle) {
        const _px = 50 + parseInt(photoStyle.x || 0);
        const _py = 50 + parseInt(photoStyle.y || 0);
        _objPos = `${_px}% ${_py}%`;
        if (photoStyle.zoom && parseFloat(photoStyle.zoom) > 100) _objSize = `${photoStyle.zoom}%`;
    }
    // Usar background-image para evitar stretch — igual que avatarEl()
    const _storyRing = p.user_has_story ? 'border:2px solid #ff3333;box-shadow:0 0 7px rgba(255,51,51,0.5);' : 'border:2px solid #222;';
    // data-myavatar para que _updateCardStoryBorder pueda actualizarlos después
    const _myAvatarAttr = isOwn ? ' data-myavatar="1"' : '';
    const _clickStory = isOwn ? ' onclick="window.openMyStory()" style-cursor="pointer"' : '';
    const _avatarOnclick = isOwn ? 'window.openMyStory()' : `window._openPostAuthor('${(p.user_email||'').replace(/'/g,"\\'")}','${(p.user_role||'jugador').replace(/'/g,"")}','${(p.user_name||'').replace(/'/g,"\\'")}')`;
    const _isAdminPost = p.user_email && p.user_email.toLowerCase() === 'neurovidstudioia@gmail.com';
    let avatarHtml;
    if (_isAdminPost) {
        const _imgContent = avatarSrc
            ? `background-image:url('${avatarSrc}');background-size:${_objSize === 'cover' ? 'cover' : _objSize};background-position:${_objPos};`
            : `background:#1a1a1a;`;
        avatarHtml = `<div style="position:relative;width:46px;height:46px;flex-shrink:0;cursor:pointer;" onclick="${_avatarOnclick}">
            <div${_myAvatarAttr} style="width:42px;height:42px;border-radius:50%;${_imgContent}${!avatarSrc?'display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--accent);font-size:17px;':''}overflow:hidden;${_storyRing}">${!avatarSrc?initials:''}</div>
            <svg style="position:absolute;inset:-4px;width:calc(100%+8px);height:calc(100%+8px);pointer-events:none;" viewBox="0 0 54 54"><polygon points="27,1 33,18 51,18 37,29 43,47 27,36 11,47 17,29 3,18 21,18" fill="none" stroke="#FFD600" stroke-width="2.5" stroke-linejoin="round"/></svg>
        </div>`;
    } else {
        avatarHtml = avatarSrc
            ? `<div${_myAvatarAttr} onclick="${_avatarOnclick}" style="width:42px;height:42px;border-radius:50%;background-image:url('${avatarSrc}');background-size:${_objSize === 'cover' ? 'cover' : _objSize};background-position:${_objPos};flex-shrink:0;cursor:pointer;${_storyRing}" onerror=""></div>`
            : `<div${_myAvatarAttr} onclick="${_avatarOnclick}" style="width:42px;height:42px;border-radius:50%;background:#1a1a1a;display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--accent);font-size:17px;flex-shrink:0;cursor:pointer;${_storyRing}">${initials}</div>`;
    }

    const pinnedBadge = isPinned
        ? `<span style="font-size:9px;background:rgba(186,255,0,0.12);color:var(--accent);border:1px solid rgba(186,255,0,0.25);border-radius:10px;padding:2px 8px;font-weight:700;white-space:nowrap;"><i class='bx bx-pin'></i> FIJADO</span>`
        : '';
    const officialBadge = p.is_official
        ? `<div style="display:inline-flex;align-items:center;gap:4px;background:rgba(186,255,0,0.12);color:var(--accent);border:1px solid rgba(186,255,0,0.35);border-radius:20px;padding:3px 10px;font-size:9px;font-weight:900;letter-spacing:1px;margin-bottom:6px;">⚡ CANCHERO OFICIAL</div>`
        : '';

    const expiresInfo = (!isPinned && p.expires_at) ? (() => {
        const left = new Date(p.expires_at) - Date.now();
        if (left <= 0) return '';
        const h = Math.floor(left / 3600000);
        const m = Math.floor((left % 3600000) / 60000);
        if (isOwn) {
            // Para el dueño: aviso de expiración más visible
            const urgent = left < 3600000; // menos de 1 hora
            return `<span style="font-size:10px;color:${urgent?'#ff8c00':'#555'};cursor:pointer;" title="Fijar para no borrar" onclick="pinPost('${p.id}')">⏱ ${h}h ${m}m — <span style="text-decoration:underline;">Fijar</span></span>`;
        }
        return `<span style="font-size:10px;color:#444;">⏱ ${h}h ${m}m</span>`;
    })() : '';

    const menuBtn = isOwn
        ? `<div style="display:flex;align-items:center;gap:2px;flex-shrink:0;">
            <button onclick="${isPinned?'unpinPost':'pinPost'}('${p.id}')" title="${isPinned?'Desfijar':'Fijar en perfil'}" style="background:none;border:none;cursor:pointer;padding:4px 5px;border-radius:8px;color:${isPinned?'var(--accent)':'#555'};font-size:18px;line-height:1;transition:.15s;" onmouseover="this.style.background='rgba(255,255,255,0.06)'" onmouseout="this.style.background='none'"><i class='bx bx-pin'></i></button>
            <button onclick="window.editOwnPost('${p.id}','${(p.content||'').replace(/'/g,"\\'").replace(/\n/g,'\\n')}')" title="Editar publicación" style="background:none;border:none;cursor:pointer;padding:4px 5px;border-radius:8px;color:#555;font-size:18px;line-height:1;transition:.15s;" onmouseover="this.style.color='var(--accent)';this.style.background='rgba(186,255,0,0.06)'" onmouseout="this.style.color='#555';this.style.background='none'"><i class='bx bx-edit'></i></button>
            <button onclick="deleteOwnPost('${p.id}')" title="Eliminar publicación" style="background:none;border:none;cursor:pointer;padding:4px 5px;border-radius:8px;color:#555;font-size:18px;line-height:1;transition:.15s;" onmouseover="this.style.color='#ff4d4d';this.style.background='rgba(255,77,77,0.08)'" onmouseout="this.style.color='#555';this.style.background='none'"><i class='bx bx-trash'></i></button>
           </div>`
        : `<button onclick="openOtherPostMenu('${p.id}','${(p.user_email||'').replace(/'/g,"\\'")}' )" style="background:none;border:none;color:#555;cursor:pointer;font-size:22px;padding:0 4px;flex-shrink:0;line-height:1;">⋯</button>`;

    // Media: soporta carrusel (media_urls JSON) + orientación (media_fit)
    let _mediaArr = [];
    try { if (p.media_urls) _mediaArr = (typeof p.media_urls === 'string' ? JSON.parse(p.media_urls) : p.media_urls) || []; } catch(e) {}
    if (!_mediaArr.length && p.media_url) _mediaArr = [{ url: p.media_url, type: p.media_type || 'image' }];
    // Los reels SIEMPRE son verticales (aunque no tengan media_fit seteado)
    const _vertical = p.media_fit === 'vertical' || p.is_reel;
    const _mh = _vertical ? '520px' : '340px';
    const _fit = _vertical ? 'contain' : 'cover';
    // #t=0.1 fuerza al navegador a pintar el primer frame como poster (evita el "negro")
    const _poster = (u) => (String(u||'').indexOf('#t=') === -1 ? (u + '#t=0.1') : u);
    const _mediaItem = (md) => md.type === 'video'
        ? (p.is_reel
            ? `<div style="position:relative;cursor:pointer;height:${_mh};background:#000;border-radius:12px;overflow:hidden;" onclick="window.openReels&&window.openReels('${p.id}')"><video src="${window._playableVideoUrl?window._playableVideoUrl(md.url):md.url}" ${(window._videoPosterUrl&&window._videoPosterUrl(md.url))?`poster="${window._videoPosterUrl(md.url)}"`:''} muted playsinline webkit-playsinline preload="metadata" onloadedmetadata="try{if(this.currentTime<0.05)this.currentTime=0.1;}catch(e){}" onloadeddata="try{if(this.currentTime<0.05)this.currentTime=0.1;}catch(e){}" style="width:100%;height:100%;object-fit:cover;display:block;pointer-events:none;"></video><div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;"><span style="width:54px;height:54px;border-radius:50%;background:rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);"><i class='bx bx-play' style="font-size:32px;color:#fff;"></i></span></div><div style="position:absolute;top:8px;right:8px;background:rgba(0,0,0,0.5);color:#fff;font-size:10px;font-weight:800;padding:3px 8px;border-radius:20px;display:flex;align-items:center;gap:4px;"><i class='bx bx-movie-play'></i> REEL</div></div>`
            : `<div style="position:relative;"><video src="${window._playableVideoUrl?window._playableVideoUrl(md.url):md.url}" data-autoplay muted loop playsinline controls style="width:100%;max-height:${_mh};${_vertical?'background:#000;':''}object-fit:${_fit};display:block;" preload="metadata" onplay="if(!this._v){this._v=1;window._registerPostView&&window._registerPostView('${p.id}')}" onended="this._v=0"></video><button onclick="(function(b){var v=b.parentElement.querySelector('video');if(v){v.muted=!v.muted;b.querySelector('i').className=v.muted?'bx bx-volume-mute':'bx bx-volume-full';}})(this)" style="position:absolute;bottom:10px;right:10px;background:rgba(0,0,0,0.55);border:none;color:#fff;width:34px;height:34px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;z-index:2;"><i class='bx bx-volume-mute' style="font-size:18px;"></i></button></div>`)
        : `<img src="${md.url}" loading="lazy" decoding="async" style="width:100%;max-height:${_mh};object-fit:${_fit};${_vertical?'background:#000;':''}display:block;cursor:zoom-in;" onerror="this.style.display='none'" onclick="window.openLightbox('${md.url.replace(/'/g,"\\'")}')">`;
    // Marca de agua sutil de Canchero (visible en capturas / compartidos, sin molestar)
    const _wm = `<div style="position:absolute;bottom:9px;left:10px;z-index:4;display:flex;align-items:center;gap:3px;pointer-events:none;opacity:.62;text-shadow:0 1px 3px rgba(0,0,0,0.6);"><i class='bx bxs-been-here' style="font-size:12px;color:#baff00;"></i><span style="font-size:10px;font-weight:900;color:#fff;letter-spacing:.5px;">Canchero</span></div>`;
    let media = '';
    if (_mediaArr.length === 1) {
        media = `<div style="margin:12px 0 4px;border-radius:12px;overflow:hidden;position:relative;">${_mediaItem(_mediaArr[0])}${_wm}</div>`;
    } else if (_mediaArr.length > 1) {
        // Carrusel: deslizar + botones ‹ › para ir adelante/atrás + dots + contador
        const cid = 'carousel-' + p.id;
        const n = _mediaArr.length;
        media = `<div style="margin:12px 0 4px;position:relative;overflow:hidden;width:100%;max-width:100%;">
            <div id="${cid}" data-idx="0" data-count="${n}" style="display:flex;width:100%;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;border-radius:12px;scrollbar-width:none;-webkit-overflow-scrolling:touch;scroll-behavior:smooth;touch-action:pan-x pan-y;" onscroll="window._carouselSync('${cid}')">
                ${_mediaArr.map(md => `<div style="flex:0 0 100%;min-width:100%;width:100%;scroll-snap-align:start;border-radius:12px;overflow:hidden;touch-action:pan-x pan-y;">${_mediaItem(md)}</div>`).join('')}
            </div>
            <button onclick="window._carouselNav('${cid}',-1,event)" id="${cid}-prev" style="position:absolute;top:50%;left:8px;transform:translateY(-50%);background:rgba(0,0,0,0.55);border:none;color:#fff;width:36px;height:36px;border-radius:50%;cursor:pointer;font-size:24px;display:none;align-items:center;justify-content:center;line-height:1;z-index:6;">‹</button>
            <button onclick="window._carouselNav('${cid}',1,event)" id="${cid}-next" style="position:absolute;top:50%;right:8px;transform:translateY(-50%);background:rgba(0,0,0,0.55);border:none;color:#fff;width:36px;height:36px;border-radius:50%;cursor:pointer;font-size:24px;display:flex;align-items:center;justify-content:center;line-height:1;z-index:6;">›</button>
            <div id="${cid}-counter" style="position:absolute;top:8px;right:10px;background:rgba(0,0,0,0.6);color:#fff;font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;z-index:6;">1/${n}</div>
            <div id="${cid}-dots" style="display:flex;justify-content:center;gap:5px;margin-top:6px;">${_mediaArr.map((_,i)=>`<span style="width:6px;height:6px;border-radius:50%;background:${i===0?'var(--accent)':'#444'};transition:.2s;"></span>`).join('')}</div>
            ${_wm}
        </div>`;
    }

    const border = isPinned ? 'rgba(186,255,0,0.2)' : '#1e1e1e';
    const shadow = isPinned ? 'box-shadow:0 0 16px rgba(186,255,0,0.06);' : '';
    const likeCount = p.likes_count || 0;
    const commentCount = p.comments_count || 0;

    // Atribución del post original cuando es un repost
    let repostOriginalName = p.original_user_name || null;
    let repostOriginalEmail = p.original_user_email || null;
    // `posts` no tiene columna repost_of: el marcador real de repost es original_user_email.
    const _isRepost = !!(p.repost_of || p.original_user_email);
    if (!repostOriginalName && _isRepost && p.content) {
        const m = p.content.match(/🔁 Compartido de @([^:\n]+)/);
        if (m) repostOriginalName = m[1].trim();
    }
    const repostHeader = (_isRepost && repostOriginalName)
        ? `<div style="display:flex;align-items:center;gap:6px;padding:7px 0 9px;font-size:11px;color:#555;border-bottom:1px solid #1a1a1a;margin-bottom:10px;">
             <i class='bx bx-repost' style="font-size:15px;color:var(--accent);flex-shrink:0;"></i>
             <span>Compartido de</span>
             <span onclick="window.viewUserProfile('${(repostOriginalEmail||'').replace(/'/g,"\\'")}')" style="color:var(--accent);cursor:pointer;font-weight:700;${repostOriginalEmail?'':'pointer-events:none;'}">@${repostOriginalName}</span>
           </div>`
        : '';

    return `<article id="post-card-${p.id}" class="post-card" data-post-id="${p.id}" data-user-email="${(p.user_email||'').replace(/"/g,'&quot;')}" style="background:#111;border:1px solid ${p.is_official?'rgba(186,255,0,0.25)':border};border-radius:16px;padding:14px 16px;margin-bottom:12px;${p.is_official?'box-shadow:0 0 20px rgba(186,255,0,0.07);':''}${shadow}overflow:hidden;">
  ${officialBadge}${repostHeader}<!-- Cabecera: avatar | nombre+tiempo | menú -->
  <div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:10px;">
    <div style="display:flex;flex-shrink:0;">${avatarHtml}</div>
    <div style="flex:1;min-width:0;overflow:hidden;">
      <div style="display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:2px;">
        <span onclick="${isOwn ? '' : `window.viewUserProfile('${(p.user_email||'').replace(/'/g,"\\'")}' )`}" style="font-weight:800;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:160px;${isOwn ? '' : 'cursor:pointer;'}" ${isOwn ? '' : 'onmouseover="this.style.color=\'var(--accent)\'" onmouseout="this.style.color=\'\'"'}>${p.user_name||'Usuario'}</span>
        ${(function(){ var _c = (isOwn && userData) ? (userData.nat||userData.country) : (p.user_country||p.user_nat||p.user_nationality); return (_c && window.countryFlag) ? `<span style="flex-shrink:0;line-height:1;">${window.countryFlag(_c,14)}</span>` : ''; })()}
        ${p.user_nickname ? `<span style="font-size:10px;color:#555;font-weight:400;">(${p.user_nickname})</span>` : ''}
        ${p.user_available ? `<span class="user-avail-dot" data-email="${p.user_email}" style="width:8px;height:8px;border-radius:50%;background:#00ff88;display:inline-block;flex-shrink:0;" title="Disponible"></span>` : ''}
        ${pinnedBadge}
      </div>
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
        <span style="font-size:10px;color:#555;">${formatTimeAgo(p.created_at)}</span>
      </div>
    </div>
    ${menuBtn}
  </div>
  <!-- Contenido texto — para reposts limpiar el texto de atribución duplicado -->
  ${(() => {
      let txt = p.content || '';
      if (_isRepost) txt = txt.replace(/🔁\s*Compartido\s*de\s*@[^\n]*/gi, '').trim();
      if (!txt) return '';
      const _urg = window._urgentPostHTML ? window._urgentPostHTML(p) : null;
      if (_urg) return _urg;
      return window.renderPostContent ? window.renderPostContent(txt) : `<p style="font-size:14px;color:#ddd;line-height:1.65;margin:0 0 4px;word-break:break-word;">${txt}</p>`;
  })()}
  ${(window._bizItemCardHTML && window._bizItemCardHTML(p)) || ''}
  ${(window._gameResultCardHTML && window._gameResultCardHTML(p)) || ''}
  <!-- Media (producto SIN carrusel: la foto va en la tarjeta CTA; CON carrusel se desliza acá) -->
  ${(window._bizItemMeta && window._bizItemMeta(p) && !p.media_urls) ? '' : media}
  ${_mediaArr.length ? (function(){
      var _hasVid = _mediaArr.some(function(md){ return md.type === 'video' || /\.(mp4|webm|mov|m4v|ogg)(\?|$)/i.test(String(md.url||md||'')); });
      if (!_hasVid) return '';
      var _n = window._fmtViews ? window._fmtViews(p.views_count||0) : (p.views_count||0);
      return `<div style="display:flex;align-items:center;gap:5px;color:#666;font-size:11px;font-weight:700;margin-top:2px;"><i class='bx bx-play' style="font-size:14px;"></i> ${_n} reproducciones</div>`;
  })() : ''}
  <!-- Likers preview (se carga async) -->
  <div id="likers-preview-${p.id}" style="min-height:0;"></div>
  <!-- Acciones -->
  <div style="display:flex;align-items:center;justify-content:space-between;margin-top:10px;padding-top:10px;border-top:1px solid #1a1a1a;">
    <button onclick="likePost(this)" data-post-id="${p.id}" class="${isLiked?'liked':''}" style="background:none;border:none;color:${isLiked?'var(--accent)':'#666'};font-size:13px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;padding:6px 4px;flex:1;">
      <i class='bx ${isLiked?'bxs-heart':'bx-heart'}' style="font-size:18px;transition:.2s;"></i> <span class="like-count" data-post-id="${p.id}">${likeCount}</span>
    </button>
    <button onclick="toggleInlineComments('${p.id}')" id="comment-btn-${p.id}" style="background:none;border:none;color:#666;font-size:13px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;padding:6px 4px;flex:1;">
      <i class='bx bx-comment' style="font-size:18px;"></i> <span id="comment-count-${p.id}">${commentCount}</span>
    </button>
    <button onclick="toggleInlineShare('${p.id}','${(p.user_name||'').replace(/'/g,"\\'")}')" id="share-btn-${p.id}" style="background:none;border:none;color:#666;font-size:13px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;padding:6px 4px;flex:1;">
      <i class='bx bx-share-alt' style="font-size:18px;"></i> <span style="font-size:12px;">${p.shares_count||0}</span>
    </button>
    ${(window.userData && (p.user_email||'').toLowerCase()===(window.userData.email||'').toLowerCase()) ? `<button onclick="window.CancheroSocial&&CancheroSocial.showStats('${p.id}')" title="Estadísticas" style="background:none;border:none;color:#666;font-size:13px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;padding:6px 4px;flex:1;"><i class='bx bx-bar-chart-alt-2' style="font-size:18px;"></i></button>` : ''}
    <button onclick="window.CancheroSocial&&CancheroSocial.toggleSave('${p.id}',this)" id="save-btn-${p.id}" title="Guardar" style="background:none;border:none;color:#666;font-size:13px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;padding:6px 4px;flex:1;">
      <i class='bx bx-bookmark' style="font-size:18px;"></i>
    </button>
  </div>
  <!-- Sección inline de COMPARTIR (oculta por defecto) -->
  <div id="inline-share-${p.id}" style="display:none;border-top:1px solid #1a1a1a;padding:10px 0 4px;margin-top:4px;">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">
      <button onclick="social.repostToProfile('${p.id}');toggleInlineShare('${p.id}')" style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);border:1px solid #2a2a2a;border-radius:10px;padding:10px 12px;color:#ccc;cursor:pointer;font-size:12px;font-weight:700;text-align:left;">
        <i class='bx bx-repost' style="font-size:18px;color:var(--accent);flex-shrink:0;"></i><div><div>En mi perfil</div><div style="font-size:10px;color:#555;font-weight:400;">Repostear en tu feed</div></div>
      </button>
      <button onclick="social._shareExternal('${p.id}');toggleInlineShare('${p.id}')" style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.04);border:1px solid #2a2a2a;border-radius:10px;padding:10px 12px;color:#ccc;cursor:pointer;font-size:12px;font-weight:700;text-align:left;">
        <i class='bx bx-link-external' style="font-size:18px;color:var(--accent);flex-shrink:0;"></i><div><div>Externamente</div><div style="font-size:10px;color:#555;font-weight:400;">WhatsApp, copiar link</div></div>
      </button>
    </div>
    <div id="inline-share-friends-${p.id}" style="display:none;"></div>
    <button onclick="toggleInlineShareFriends('${p.id}')" style="display:flex;align-items:center;gap:8px;width:100%;background:rgba(255,255,255,0.03);border:1px solid #2a2a2a;border-radius:10px;padding:10px 12px;color:#888;cursor:pointer;font-size:12px;font-weight:700;margin-bottom:4px;">
      <i class='bx bx-user-voice' style="font-size:18px;color:var(--accent);flex-shrink:0;"></i> Enviar a un seguido
    </button>
  </div>
  <!-- Sección inline de comentarios (oculta por defecto) -->
  <div id="inline-comments-${p.id}" style="display:none;border-top:1px solid #1a1a1a;padding-top:12px;margin-top:4px;">
    <div id="inline-comments-list-${p.id}" style="margin-bottom:10px;"></div>
    <div style="display:flex;gap:8px;align-items:center;">
      <div style="width:32px;height:32px;border-radius:50%;background:#1e1e1e;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:13px;font-weight:900;color:var(--accent);">
        ${(userData && userData.name) ? userData.name[0].toUpperCase() : '?'}
      </div>
      <input id="inline-comment-input-${p.id}" type="text" placeholder="Escribí un comentario..." autocomplete="off"
        style="flex:1;background:rgba(255,255,255,0.05);border:1px solid #2a2a2a;border-radius:22px;padding:9px 14px;color:#fff;font-size:13px;outline:none;min-width:0;"
        onfocus="this.style.borderColor='var(--accent)'" onblur="this.style.borderColor='#2a2a2a'"
        onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submitInlineComment('${p.id}');}">
      <button onclick="submitInlineComment('${p.id}')" style="background:var(--accent);color:#000;border:none;border-radius:50%;width:34px;height:34px;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;">
        <i class='bx bx-send' style="font-size:16px;"></i>
      </button>
    </div>
  </div>
</article>`;
}

// ── TOGGLE INLINE COMMENTS ─────────────────────────────────

// ── Fix IDs duplicados: el mismo post puede estar renderizado en feed,
// perfil y amigos a la vez. getElementById devuelve la PRIMERA copia (a
// menudo oculta) y los botones parecen muertos. Este helper devuelve la
// copia VISIBLE del elemento.
window._postEl = function(fullId) {
    var els = document.querySelectorAll('[id="' + fullId + '"]');
    if (els.length <= 1) return els[0] || null;
    for (var i = 0; i < els.length; i++) {
        var tab = els[i].closest('.dashboard-tab-content');
        if (!tab || tab.style.display !== 'none') return els[i];
    }
    return els[0];
};

window.toggleInlineComments = function(postId) {
    const section = window._postEl('inline-comments-' + postId);
    if (!section) return;
    const isOpen = section.style.display !== 'none';
    if (isOpen) {
        section.style.display = 'none';
    } else {
        section.style.display = 'block';
        loadInlineComments(postId);
        setTimeout(() => {
            const input = window._postEl('inline-comment-input-' + postId);
            if (input) input.focus();
        }, 100);
    }
};

// ── HILOS INLINE (estilo X/Threads, se expanden debajo del post) ──
window.toggleInlineThread = async function(postId, rootId) {
    rootId = rootId || postId;
    const box = document.getElementById('thread-inline-' + postId);
    if (!box) return;
    if (box.style.display !== 'none') { box.style.display = 'none'; return; }
    box.style.display = 'block';
    box.innerHTML = '<div style="text-align:center;color:#555;padding:14px;"><i class="bx bx-loader-alt bx-spin"></i></div>';
    const sb = window._sb;
    if (!sb) { box.innerHTML = '<div style="color:#555;padding:10px;">Sin conexión.</div>'; return; }
    try {
        // Traer respuestas del hilo (todas las que cuelgan del root)
        const { data: replies } = await sb.from('posts').select('*').eq('thread_root_id', rootId).order('created_at',{ascending:true});
        const list = (replies || []).filter(r => r.id !== rootId);
        const myInit = (userData && userData.name) ? userData.name[0].toUpperCase() : '?';
        let html = '';
        if (list.length) {
            html += list.map((r, idx) => {
                const init = (r.user_name||'?')[0].toUpperCase();
                const av = (r.user_avatar && !String(r.user_avatar).includes('ui-avatars'))
                    ? `<div style="width:32px;height:32px;border-radius:50%;background:#000 url('${r.user_avatar}') center/cover;flex-shrink:0;border:1px solid #2a2a2a;"></div>`
                    : `<div style="width:32px;height:32px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${init}</div>`;
                const isLast = idx === list.length - 1;
                return `<div style="display:flex;gap:10px;padding:6px 0;">
                    <div style="display:flex;flex-direction:column;align-items:center;flex-shrink:0;">
                        ${av}
                        ${isLast ? '' : '<div style="width:2px;flex:1;background:#222;margin-top:4px;min-height:10px;border-radius:2px;"></div>'}
                    </div>
                    <div style="flex:1;min-width:0;padding-bottom:6px;">
                        <div style="font-size:12px;font-weight:800;">${(r.user_name||'Jugador').replace(/</g,'&lt;')} <span style="font-size:10px;color:#666;font-weight:400;">· ${_timeAgoSimple?_timeAgoSimple(r.created_at):''}</span></div>
                        <div style="font-size:13px;color:#ddd;margin-top:2px;word-break:break-word;line-height:1.5;">${(r.content||'').replace(/</g,'&lt;')}</div>
                    </div>
                </div>`;
            }).join('');
        } else {
            html += '<div style="font-size:12px;color:#555;padding:4px 0 10px;">Sé el primero en responder este hilo.</div>';
        }
        // Caja de respuesta inline (estilo X)
        html += `<div style="display:flex;gap:8px;align-items:center;margin-top:8px;">
            <div style="width:30px;height:30px;border-radius:50%;background:#1e1e1e;color:var(--accent);font-weight:900;font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${myInit}</div>
            <input id="thread-reply-input-${postId}" type="text" placeholder="Respondé al hilo..." style="flex:1;background:rgba(255,255,255,0.05);border:1px solid #2a2a2a;border-radius:22px;padding:9px 14px;color:#fff;font-size:13px;outline:none;min-width:0;" onkeydown="if(event.key==='Enter'){event.preventDefault();window._submitInlineThread('${postId}','${rootId}');}">
            <button onclick="window._submitInlineThread('${postId}','${rootId}')" style="background:var(--accent);color:#000;border:none;border-radius:50%;width:34px;height:34px;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;"><i class='bx bx-send' style="font-size:16px;"></i></button>
        </div>`;
        box.innerHTML = html;
    } catch(e) { box.innerHTML = '<div style="color:#f44;padding:10px;font-size:12px;">No se pudo cargar el hilo.</div>'; }
};

window._submitInlineThread = async function(postId, rootId) {
    const inp = document.getElementById('thread-reply-input-' + postId);
    if (!inp) return;
    const text = inp.value.trim();
    if (!text) return;
    const sb = window._sb;
    if (!sb || !userData) { showToast && showToast('Iniciá sesión.', 'warning'); return; }
    inp.value = ''; inp.disabled = true;
    const payload = {
        user_email: userData.email, user_name: userData.name, user_avatar: userData.photo || null,
        user_role: userData.role || 'jugador', content: text, media_type: 'text', likes_count: 0,
        expires_at: new Date(Date.now() + 12*3600000).toISOString(),
        parent_post_id: postId, thread_root_id: rootId || postId
    };
    const { error } = await sb.from('posts').insert(payload);
    inp.disabled = false;
    if (error) { showToast && showToast('Falta correr el SQL de hilos (parent_post_id): ' + error.message, 'error'); return; }
    try { const { data: pp } = await sb.from('posts').select('reply_count').eq('id', rootId||postId).single(); if (pp) await sb.from('posts').update({ reply_count:(pp.reply_count||0)+1 }).eq('id', rootId||postId); } catch(e){}
    // Recargar el hilo inline
    const box = document.getElementById('thread-inline-' + postId);
    if (box) box.style.display = 'none';
    window.toggleInlineThread(postId, rootId);
};

// (Compat) modal antiguo — ahora redirige al inline
window.replyToPost = async function(postId, rootId, authorName) {
    const sb = window._sb;
    if (!sb || !userData) { showToast && showToast('Iniciá sesión para responder.', 'warning'); return; }
    let orig = null;
    try { const { data } = await sb.from('posts').select('user_name,content,media_url,media_type').eq('id', postId).single(); orig = data; } catch(e){}
    let modal = document.getElementById('reply-post-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'reply-post-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:10600;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);display:flex;align-items:flex-start;justify-content:center;padding:0;';
    const myInit = (userData.name||'?')[0].toUpperCase();
    const origInit = (authorName||(orig&&orig.user_name)||'?')[0].toUpperCase();
    modal.innerHTML = `
      <div style="background:#0d0d0d;width:100%;max-width:560px;height:100%;display:flex;flex-direction:column;">
        <div style="display:flex;align-items:center;justify-content:space-between;padding:calc(12px + env(safe-area-inset-top)) 16px 12px;border-bottom:1px solid #1e1e1e;">
          <button onclick="document.getElementById('reply-post-modal').remove()" style="background:none;border:none;color:#aaa;font-size:15px;cursor:pointer;font-weight:700;">Cancelar</button>
          <button onclick="window._submitThreadReply('${postId}','${rootId||postId}')" style="background:var(--accent);color:#000;border:none;border-radius:20px;padding:8px 20px;font-weight:900;font-size:13px;cursor:pointer;">Responder</button>
        </div>
        <div style="flex:1;overflow-y:auto;padding:16px;">
          <!-- Post original -->
          <div style="display:flex;gap:10px;">
            <div style="display:flex;flex-direction:column;align-items:center;">
              <div style="width:40px;height:40px;border-radius:50%;background:#333;color:#fff;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${origInit}</div>
              <div style="width:2px;flex:1;background:#222;margin-top:4px;min-height:24px;"></div>
            </div>
            <div style="flex:1;min-width:0;padding-bottom:8px;">
              <div style="font-size:14px;font-weight:800;">${authorName||(orig&&orig.user_name)||'Publicación'}</div>
              <div style="font-size:14px;color:#ccc;margin-top:2px;word-break:break-word;">${orig&&orig.content?(orig.content||'').replace(/</g,'&lt;'):'[contenido]'}</div>
              <div style="font-size:12px;color:#666;margin-top:6px;">Respondiendo a <span style="color:var(--accent);">${authorName||(orig&&orig.user_name)||''}</span></div>
            </div>
          </div>
          <!-- Mi respuesta -->
          <div style="display:flex;gap:10px;margin-top:4px;">
            <div style="width:40px;height:40px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${myInit}</div>
            <textarea id="thread-reply-text" placeholder="Escribí tu respuesta..." autofocus style="flex:1;background:none;border:none;color:#fff;font-size:16px;resize:none;outline:none;min-height:120px;font-family:inherit;"></textarea>
          </div>
        </div>
      </div>`;
    document.body.appendChild(modal);
    setTimeout(()=>{ const t = document.getElementById('thread-reply-text'); if (t) t.focus(); }, 100);
};

window._submitThreadReply = async function(postId, rootId) {
    const sb = window._sb;
    const text = (document.getElementById('thread-reply-text')||{}).value;
    if (!sb || !userData || !text || !text.trim()) { showToast && showToast('Escribí algo.', 'warning'); return; }
    const payload = {
        user_email: userData.email, user_name: userData.name, user_avatar: userData.photo || null,
        user_role: userData.role || 'jugador', content: text.trim(), media_type: 'text', likes_count: 0,
        expires_at: new Date(Date.now() + 12*3600000).toISOString(),
        parent_post_id: postId, thread_root_id: rootId || postId
    };
    let { error } = await sb.from('posts').insert(payload);
    if (error) { showToast && showToast('Necesitás correr el SQL de hilos (parent_post_id). Error: ' + error.message, 'error'); return; }
    // Incrementar reply_count del raíz
    try { const { data: pp } = await sb.from('posts').select('reply_count').eq('id', rootId||postId).single(); if (pp) await sb.from('posts').update({ reply_count: (pp.reply_count||0)+1 }).eq('id', rootId||postId); } catch(e){}
    document.getElementById('reply-post-modal')?.remove();
    showToast && showToast('Respuesta publicada en el hilo 🧵', 'success');
    // Abrir el hilo para ver el encadenado
    setTimeout(()=> window.openPostThread(rootId || postId), 200);
};
window.cancelReplyToPost = function(){ document.getElementById('reply-post-modal')?.remove(); };

// Ver el hilo completo (post raíz + todas las respuestas en orden)
window.openPostThread = async function(rootId) {
    const sb = window._sb;
    if (!sb || !rootId) return;
    let modal = document.getElementById('post-thread-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'post-thread-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9900;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);display:flex;flex-direction:column;';
    modal.innerHTML = '<div style="display:flex;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid #1e1e1e;background:#0d0d0d;">' +
        '<button onclick="document.getElementById(\'post-thread-modal\').remove()" style="background:rgba(255,255,255,0.08);border:1px solid #2a2a2a;color:#fff;width:36px;height:36px;border-radius:50%;cursor:pointer;font-size:18px;"><i class="bx bx-arrow-back"></i></button>' +
        '<div style="font-weight:900;font-size:15px;">🧵 Hilo</div></div>' +
        '<div id="post-thread-body" style="flex:1;overflow-y:auto;padding:14px;max-width:600px;margin:0 auto;width:100%;box-sizing:border-box;"><div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div></div>';
    document.body.appendChild(modal);
    try {
        // Traer raíz + todos los posts del hilo
        const { data: root } = await sb.from('posts').select('*').eq('id', rootId).single();
        const { data: replies } = await sb.from('posts').select('*').eq('thread_root_id', rootId).order('created_at', { ascending: true });
        const all = [root].concat(replies || []).filter(Boolean);
        const body = document.getElementById('post-thread-body');
        if (body) {
            body.innerHTML = all.map((p, i) => {
                const init = (p.user_name||'?')[0].toUpperCase();
                const isRoot = i === 0;
                return '<div style="display:flex;gap:10px;padding:12px 0;border-bottom:1px solid #1a1a1a;">' +
                    '<div style="display:flex;flex-direction:column;align-items:center;">' +
                        '<div style="width:38px;height:38px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0;">' + init + '</div>' +
                        (i < all.length-1 ? '<div style="width:2px;flex:1;background:#222;margin-top:4px;"></div>' : '') +
                    '</div>' +
                    '<div style="flex:1;min-width:0;">' +
                        '<div style="font-size:13px;font-weight:800;">' + (p.user_name||'Jugador') + (isRoot?' <span style="font-size:9px;color:var(--accent);">· INICIO</span>':'') + '</div>' +
                        '<div style="font-size:14px;color:#ddd;margin-top:4px;word-break:break-word;white-space:pre-wrap;">' + ((p.content||'').replace(/</g,'&lt;')) + '</div>' +
                        (p.media_url && p.media_type!=='text' ? '<img src="'+p.media_url+'" style="width:100%;border-radius:10px;margin-top:8px;max-height:300px;object-fit:cover;">' : '') +
                    '</div></div>';
            }).join('') +
            '<button onclick="document.getElementById(\'post-thread-modal\').remove();window.replyToPost(\''+rootId+'\',\''+rootId+'\',\''+((root&&root.user_name)||'').replace(/'/g,"")+'\')" style="width:100%;background:rgba(186,255,0,0.1);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:12px;padding:12px;font-weight:800;font-size:13px;cursor:pointer;margin-top:14px;"><i class="bx bx-message-add"></i> RESPONDER AL HILO</button>';
        }
    } catch(e) {
        const body = document.getElementById('post-thread-body');
        if (body) body.innerHTML = '<div style="padding:20px;color:#f44;">No se pudo cargar el hilo.</div>';
    }
};

// ── TOGGLE INLINE SHARE ────────────────────────────────────
window.toggleInlineShare = function(postId, userName) {
    const section = window._postEl('inline-share-' + postId);
    if (!section) return;
    const isOpen = section.style.display !== 'none';
    section.style.display = isOpen ? 'none' : 'block';
    // Cerrar comentarios si están abiertos
    if (!isOpen) {
        const cmt = window._postEl('inline-comments-' + postId);
        if (cmt) cmt.style.display = 'none';
    }
};

window.toggleInlineShareFriends = async function(postId) {
    const container = window._postEl('inline-share-friends-' + postId);
    if (!container) return;
    const isOpen = container.style.display !== 'none';
    if (isOpen) { container.style.display = 'none'; return; }
    container.style.display = 'block';
    container.innerHTML = `<div style="padding:8px;color:#555;font-size:12px;text-align:center;"><i class='bx bx-loader-alt bx-spin'></i></div>`;
    const sb = window._sb;
    if (!sb || !userData) { container.innerHTML = `<div style="padding:8px;color:#555;font-size:11px;">Iniciá sesión para enviar.</div>`; return; }
    try {
        const { data: follows } = await sb.from('follows').select('following_email').eq('follower_email', userData.email).limit(30);
        if (!follows || !follows.length) { container.innerHTML = `<div style="padding:8px;color:#555;font-size:11px;">No seguís a nadie todavía.</div>`; return; }
        const emails = follows.map(f => f.following_email);
        const { data: users } = await sb.from('users').select('email,name,photo').in('email', emails).limit(30);
        container.innerHTML = `<div style="max-height:180px;overflow-y:auto;border:1px solid #2a2a2a;border-radius:10px;margin-bottom:6px;">${(users||[]).map(u => {
            const init = (u.name||'?')[0].toUpperCase();
            const photoStyle = u.photo && !u.photo.includes('ui-avatars') ? `background-image:url('${u.photo}');background-size:cover;background-position:center;` : `background:var(--accent);`;
            const nameEsc = (u.name||'').replace(/'/g,"\\'");
            const emailEsc = (u.email||'').replace(/'/g,"\\'");
            return `<div onclick="social._sendPostToUser('${postId}','${emailEsc}','${nameEsc}');window._postEl('inline-share-${postId}').style.display='none';" style="display:flex;align-items:center;gap:10px;padding:10px 12px;border-bottom:1px solid #1a1a1a;cursor:pointer;transition:background .15s;" onmouseover="this.style.background='#111'" onmouseout="this.style.background='transparent'">
                <div style="width:36px;height:36px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:14px;color:#000;${photoStyle}">${u.photo&&!u.photo.includes('ui-avatars')?'':init}</div>
                <div style="font-size:13px;font-weight:700;">${u.name||u.email}</div>
                <i class='bx bx-send' style="margin-left:auto;color:var(--accent);font-size:16px;"></i>
            </div>`;
        }).join('')}</div>`;
    } catch(e) { container.innerHTML = `<div style="padding:8px;color:#f44;font-size:11px;">Error: ${e.message}</div>`; }
};

window.loadInlineComments = async function(postId) {
    const list = window._postEl('inline-comments-list-' + postId);
    if (!list) return;
    const sb = window._sb;
    if (!sb) { list.innerHTML = '<div style="color:#555;font-size:12px;text-align:center;padding:8px;">Sin conexión.</div>'; return; }
    list.innerHTML = '<div style="text-align:center;color:#555;padding:8px;"><i class="bx bx-loader-alt bx-spin" style="font-size:14px;"></i></div>';
    try {
        const { data, error } = await sb.from('post_comments').select('*').eq('post_id', postId).order('created_at', { ascending: true }).limit(50);
        if (error) throw error;
        if (!data || !data.length) {
            list.innerHTML = '<div style="text-align:center;color:#444;font-size:12px;padding:8px 0;">Sin comentarios todavía. ¡Sé el primero!</div>';
            return;
        }
        const myEmail = window.userData?.email || '';
        // Enriquecer con foto de perfil + país de cada comentador (para mostrar avatar y bandera)
        try {
            const cem = [...new Set(data.map(c=>c.user_email).filter(Boolean))];
            if (cem.length) {
                const { data: cus } = await sb.from('users').select('email,photo,photo_style,nat').in('email', cem);
                const cmap = {}; (cus||[]).forEach(u => cmap[u.email]=u);
                data.forEach(c => { const u = cmap[c.user_email]; if (u) { c._photo = (u.photo||u.avatar_url); c._pstyle = u.photo_style||null; c._nat = u.nat||u.country||null; } });
            }
        } catch(e) {}
        // Enriquecer con MIS likes de comentarios (para pintar el corazón)
        try {
            if (myEmail) {
                const { data: cl } = await sb.from('comment_likes').select('comment_id').eq('user_email', myEmail).in('comment_id', data.map(c=>c.id));
                const likedSet = new Set((cl||[]).map(x=>x.comment_id));
                data.forEach(c => { c._liked = likedSet.has(c.id); });
            }
        } catch(e) {}
        // Organizar en hilos: comentarios raíz + respuestas anidadas
        const topLevel = data.filter(c => !c.parent_comment_id);
        const replyMap = {};
        data.filter(c => c.parent_comment_id).forEach(r => {
            (replyMap[r.parent_comment_id] = replyMap[r.parent_comment_id] || []).push(r);
        });
        function renderC(c, depth) {
            const initC = (c.user_name || '?')[0].toUpperCase();
            const canDelete = myEmail && (c.user_email === myEmail);
            const _sz = depth>0?26:30;
            // Avatar con FOTO (default rostro center 25%, o photoStyle) + bandera al lado del nombre
            const _ph = c._photo && !String(c._photo).includes('ui-avatars');
            let _bgPos = 'center 25%', _bgSize = 'cover';
            if (c._pstyle) { try { const s = typeof c._pstyle==='string'?JSON.parse(c._pstyle):c._pstyle; _bgPos = (50+parseInt(s.x||0))+'% '+(50+parseInt(s.y||0))+'%'; if (parseFloat(s.zoom||100)>100) _bgSize = s.zoom+'%'; } catch(e){} }
            const _avatar = _ph
                ? `<div onclick="window.viewUserProfile&&window.viewUserProfile('${(c.user_email||'').replace(/'/g,"\\'")}')" style="width:${_sz}px;height:${_sz}px;border-radius:50%;background-image:url('${c._photo}');background-size:${_bgSize};background-position:${_bgPos};flex-shrink:0;cursor:pointer;"></div>`
                : `<div style="width:${_sz}px;height:${_sz}px;border-radius:50%;background:#1e1e1e;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px;font-weight:900;color:var(--accent);">${initC}</div>`;
            const _flag = (c._nat && window.countryFlag) ? `<span style="flex-shrink:0;line-height:1;margin-left:4px;">${window.countryFlag(c._nat,12)}</span>` : '';
            const delBtn = canDelete
                ? `<button onclick="window.deleteInlineComment('${c.id}','${postId}')" title="Eliminar comentario" style="background:none;border:none;cursor:pointer;color:#444;padding:2px 4px;border-radius:6px;font-size:14px;flex-shrink:0;transition:.15s;" onmouseover="this.style.color='#ff4444'" onmouseout="this.style.color='#444'"><i class='bx bx-trash'></i></button>`
                : '';
            const indent = depth > 0 ? `margin-left:${Math.min(depth*18,36)}px;border-left:2px solid #1e1e1e;padding-left:8px;` : '';
            const nameEsc = (c.user_name||'Jugador').replace(/'/g,"\\'");
            const kids = replyMap[c.id] || [];
            return `<div style="${indent}">
              <div id="comment-item-${c.id}" style="display:flex;gap:8px;margin-bottom:6px;align-items:flex-start;">
                ${_avatar}
                <div style="flex:1;background:rgba(255,255,255,0.04);border-radius:10px;padding:7px 11px;">
                  <div style="font-size:11px;font-weight:800;color:#ccc;margin-bottom:2px;display:flex;align-items:center;">${c.user_name || 'Jugador'}${_flag}</div>
                  <div style="font-size:13px;color:#ddd;word-break:break-word;">${(c.content||'').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div>
                  <div style="display:flex;align-items:center;gap:12px;margin-top:3px;">
                    <span style="font-size:10px;color:#444;">${_timeAgoSimple(c.created_at)}</span>
                    <button onclick="window._likeComment('${c.id}',this)" data-liked="${c._liked?'1':'0'}" style="background:none;border:none;color:${c._liked?'var(--accent)':'#888'};font-size:10px;font-weight:700;cursor:pointer;padding:0;display:flex;align-items:center;gap:4px;"><i class='bx ${c._liked?'bxs-heart':'bx-heart'}' style="font-size:13px;"></i><span>${c.likes_count||0}</span></button>
                    <button onclick="window.replyInlineComment('${postId}','${c.id}','${nameEsc}')" style="background:none;border:none;color:#888;font-size:10px;font-weight:700;cursor:pointer;padding:0;">RESPONDER</button>
                  </div>
                </div>
                ${delBtn}
              </div>
              ${kids.map(k => renderC(k, depth+1)).join('')}
            </div>`;
        }
        list.innerHTML = topLevel.map(c => renderC(c, 0)).join('');
        // Actualizar contador visible
        const countEl = window._postEl('comment-count-' + postId);
        if (countEl) countEl.textContent = data.length;
    } catch(e) {
        list.innerHTML = '<div style="color:#f44;font-size:12px;text-align:center;padding:8px;">Error al cargar comentarios.</div>';
    }
};

// Activar modo respuesta en un comentario (hilo)
window.replyInlineComment = function(postId, parentCommentId, userName) {
    const input = window._postEl('inline-comment-input-' + postId);
    if (!input) return;
    input.dataset.parentCommentId = parentCommentId;
    input.placeholder = 'Respondiendo a ' + userName + '...';
    input.focus();
    if (typeof showToast === 'function') showToast('Respondiendo a ' + userName + ' — escribí y enviá', 'default');
};

window.submitInlineComment = async function(postId) {
    const input = window._postEl('inline-comment-input-' + postId);
    if (!input) return;
    const text = input.value.trim();
    if (!text) return;
    const me = window.userData;
    if (!me || !me.email) { if (typeof showToast === 'function') showToast('Iniciá sesión para comentar.', 'warning'); return; }
    const sb = window._sb;
    if (!sb) { if (typeof showToast === 'function') showToast('Sin conexión.', 'error'); return; }
    const parentId = input.dataset.parentCommentId || null;
    input.value = '';
    input.disabled = true;
    try {
        const payload = {
            post_id: postId,
            user_email: me.email,
            user_name: me.name || me.email,
            content: text
        };
        if (parentId) payload.parent_comment_id = parentId;
        let { error } = await sb.from('post_comments').insert(payload);
        // Fallback si la columna parent_comment_id no existe
        if (error && parentId) { delete payload.parent_comment_id; ({ error } = await sb.from('post_comments').insert(payload)); }
        if (error) throw error;
        // Resetear modo respuesta
        delete input.dataset.parentCommentId;
        input.placeholder = 'Escribí un comentario...';
        // Incrementar contador en DOM optimistamente
        const ccEl = window._postEl('comment-count-' + postId);
        if (ccEl) ccEl.textContent = (parseInt(ccEl.textContent)||0) + 1;
        // Incrementar contador en DB
        const sbD = window._sb;
        sbD.from('posts').select('comments_count').eq('id', postId).single().then(({ data: post }) => {
            // comments_count lo mantiene el trigger de Postgres (RLS)
        }).catch(()=>{});
        // Recargar comentarios inline
        loadInlineComments(postId);
        // Notificación al dueño del post
        try {
            const { data: origPost } = await sbD.from('posts').select('user_email,user_name').eq('id', postId).single();
            if (origPost && origPost.user_email !== me.email && typeof notif !== 'undefined') {
                notif.create(origPost.user_email, 'comment', me.name || 'Alguien', `💬 ${me.name || 'Alguien'} comentó tu publicación.`, postId);
            }
        } catch(e) {}
    } catch(e) {
        input.value = text;
        if (typeof showToast === 'function') showToast('No se pudo comentar. Intentá de nuevo.', 'error');
    }
    input.disabled = false;
    input.focus();
};

// Carga preview de quienes dieron like (primeros 3) — se llama después de renderizar las cards
window.loadLikersPreview = async function(postId) {
    const container = window._postEl('likers-preview-' + postId);
    if (!container) return;
    const sb = window._sb;
    if (!sb) return;
    try {
        const { data, count } = await sb.from('post_likes').select('user_email,user_name', { count: 'exact' }).eq('post_id', postId).limit(5);
        // Actualizar el contador de likes en el DOM con el valor real
        if (count !== null) {
            document.querySelectorAll(`.like-count[data-post-id="${postId}"]`).forEach(el => { el.textContent = count; });
        }
        if (!data || !data.length) return;
        const names = data.map(l => (l.user_name || l.user_email.split('@')[0]));
        const preview = names.length === 1
            ? `<span style="font-weight:700;">${names[0]}</span> le dio like`
            : names.length === 2
                ? `<span style="font-weight:700;">${names[0]}</span> y <span style="font-weight:700;">${names[1]}</span> le dieron like`
                : `<span style="font-weight:700;">${names[0]}</span>, <span style="font-weight:700;">${names[1]}</span> y ${data.length > 2 ? (data.length - 2) + ' más' : names[2]} le dieron like`;
        container.innerHTML = `<button onclick="window.showLikersModal('${postId}')" style="font-size:11px;color:#555;padding:4px 0 2px;display:flex;align-items:center;gap:4px;background:none;border:none;cursor:pointer;text-align:left;" onmouseover="this.style.color='#888'" onmouseout="this.style.color='#555'"><i class='bx bxs-heart' style="color:var(--accent);font-size:12px;flex-shrink:0;"></i>${preview}</button>`;
    } catch(e) {}
};

