// ── CARRUSEL: navegación con botones ‹ › + sincronizar dots/contador/flechas ──
window._carouselNav = function(cid, dir, ev) {
    if (ev) { try { ev.stopPropagation(); ev.preventDefault(); } catch(e){} }
    const track = document.getElementById(cid);
    if (!track) return;
    const count = parseInt(track.dataset.count) || track.children.length;
    // idx real según el scroll actual (no confiar solo en data-idx)
    let idx = Math.round(track.scrollLeft / Math.max(1, track.clientWidth));
    idx = Math.max(0, Math.min(count - 1, idx + dir));
    track.dataset.idx = idx;
    // Usar la posición real del hijo destino (más fiable que clientWidth*idx)
    const child = track.children[idx];
    const left = child ? child.offsetLeft : track.clientWidth * idx;
    track.scrollTo({ left: left, behavior: 'smooth' });
    window._carouselUpdateUI(cid, idx, count);
};
window._carouselSync = function(cid) {
    const track = document.getElementById(cid);
    if (!track) return;
    const count = parseInt(track.dataset.count) || track.children.length;
    const idx = Math.round(track.scrollLeft / Math.max(1, track.clientWidth));
    track.dataset.idx = idx;
    window._carouselUpdateUI(cid, idx, count);
};
window._carouselUpdateUI = function(cid, idx, count) {
    const counter = document.getElementById(cid + '-counter');
    if (counter) counter.textContent = (idx + 1) + '/' + count;
    const prev = document.getElementById(cid + '-prev');
    const next = document.getElementById(cid + '-next');
    if (prev) prev.style.display = idx <= 0 ? 'none' : 'flex';
    if (next) next.style.display = idx >= count - 1 ? 'none' : 'flex';
    const dots = document.getElementById(cid + '-dots');
    if (dots) [...dots.children].forEach((d, i) => { d.style.background = i === idx ? 'var(--accent)' : '#444'; });
};

// ── EDITAR PUBLICACIÓN PROPIA (texto + media + carrusel + orientación) ──
window._editPostMedia = []; // [{url, type}] media a conservar/agregar
window.editOwnPost = async function(postId) {
    const sb = window._sb;
    if (!sb || !userData) return;
    const { data: post } = await sb.from('posts').select('*').eq('id', postId).single();
    if (!post) { showToast && showToast('No se encontró la publicación.', 'error'); return; }
    if ((post.user_email||'').toLowerCase() !== (userData.email||'').toLowerCase()) { showToast && showToast('Solo podés editar tus publicaciones.', 'error'); return; }

    // Reunir media existente (carrusel media_urls o media_url simple)
    let media = [];
    try { if (post.media_urls) media = (typeof post.media_urls === 'string' ? JSON.parse(post.media_urls) : post.media_urls) || []; } catch(e) {}
    if (!media.length && post.media_url) media = [{ url: post.media_url, type: post.media_type || 'image' }];
    window._editPostMedia = media.slice();
    const fit = post.media_fit || 'horizontal';

    const m = document.createElement('div');
    m.id = 'edit-post-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,0.85);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    m.innerHTML = `
      <div style="background:#0f110f;border:1px solid #1e1e1e;border-radius:20px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto;padding:20px;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">
          <h3 style="font-size:16px;font-weight:900;margin:0;">✏️ Editar publicación</h3>
          <button onclick="document.getElementById('edit-post-modal').remove()" style="background:rgba(255,255,255,0.06);border:1px solid #333;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:18px;">&times;</button>
        </div>
        <textarea id="edit-post-text" rows="4" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:12px;color:#fff;font-size:14px;font-family:inherit;resize:vertical;box-sizing:border-box;">${(post.content||'').replace(/</g,'&lt;')}</textarea>
        <div style="margin-top:10px;">
          <div style="font-size:10px;letter-spacing:1px;color:#666;font-weight:700;margin-bottom:6px;">FORMATO DE LAS IMÁGENES/VIDEOS</div>
          <div style="display:flex;gap:8px;">
            <button id="edit-fit-horizontal" onclick="window._setEditFit('horizontal')" style="flex:1;padding:9px;border-radius:10px;border:1px solid ${fit==='horizontal'?'var(--accent)':'#2a2a2a'};background:${fit==='horizontal'?'rgba(186,255,0,0.08)':'transparent'};color:${fit==='horizontal'?'var(--accent)':'#aaa'};font-weight:700;font-size:12px;cursor:pointer;"><i class='bx bx-rectangle'></i> Horizontal</button>
            <button id="edit-fit-vertical" onclick="window._setEditFit('vertical')" style="flex:1;padding:9px;border-radius:10px;border:1px solid ${fit==='vertical'?'var(--accent)':'#2a2a2a'};background:${fit==='vertical'?'rgba(186,255,0,0.08)':'transparent'};color:${fit==='vertical'?'var(--accent)':'#aaa'};font-weight:700;font-size:12px;cursor:pointer;">📱 Vertical</button>
          </div>
        </div>
        <div id="edit-media-grid" style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;"></div>
        <input type="file" id="edit-post-files" accept="image/*,video/*" multiple style="display:none;" onchange="window._addEditMedia(this)">
        <button onclick="document.getElementById('edit-post-files').click()" style="width:100%;margin-top:10px;background:transparent;border:1px dashed #333;border-radius:10px;padding:10px;color:#888;font-weight:700;font-size:12px;cursor:pointer;"><i class='bx bx-images'></i> Agregar fotos/videos (carrusel)</button>
        <button onclick="window._saveEditPost('${postId}')" id="edit-post-save" style="width:100%;margin-top:14px;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:14px;cursor:pointer;">GUARDAR CAMBIOS</button>
      </div>`;
    m.onclick = e => { if (e.target === m) m.remove(); };
    document.body.appendChild(m);
    window._editPostFit = fit;
    window._renderEditMediaGrid();
};

window._setEditFit = function(f) {
    window._editPostFit = f;
    ['horizontal','vertical'].forEach(x => {
        const b = document.getElementById('edit-fit-' + x);
        if (b) { const on = x===f; b.style.borderColor = on?'var(--accent)':'#2a2a2a'; b.style.background = on?'rgba(186,255,0,0.08)':'transparent'; b.style.color = on?'var(--accent)':'#aaa'; }
    });
};

window._renderEditMediaGrid = function() {
    const grid = document.getElementById('edit-media-grid');
    if (!grid) return;
    grid.innerHTML = (window._editPostMedia||[]).map((md, i) => `
      <div style="position:relative;width:74px;height:74px;border-radius:10px;overflow:hidden;border:1px solid #2a2a2a;flex-shrink:0;">
        ${md.type==='video' ? `<video src="${md.url}" style="width:100%;height:100%;object-fit:cover;"></video>` : `<img src="${md.url}" style="width:100%;height:100%;object-fit:cover;">`}
        <button onclick="window._removeEditMedia(${i})" style="position:absolute;top:2px;right:2px;background:rgba(0,0,0,0.7);border:none;color:#ff4444;width:20px;height:20px;border-radius:50%;cursor:pointer;font-size:13px;line-height:1;">&times;</button>
      </div>`).join('') || '<div style="font-size:11px;color:#555;padding:6px;">Sin imágenes. Agregá si querés.</div>';
};

window._removeEditMedia = function(i) {
    window._editPostMedia.splice(i, 1);
    window._renderEditMediaGrid();
};

window._addEditMedia = async function(input) {
    const files = Array.from(input.files || []);
    if (!files.length) return;
    const sb = window._sb;
    const saveBtn = document.getElementById('edit-post-save');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Subiendo...'; }
    for (const file of files) {
        if (window._editPostMedia.length >= 10) { showToast && showToast('Máx 10 elementos.', 'warning'); break; }
        let url = null;
        const type = file.type.startsWith('video') ? 'video' : 'image';
        try {
            const path = `posts/${userData.email}/${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
            const { error } = await sb.storage.from('media').upload(path, file, { upsert: true, contentType: file.type });
            if (error) throw error;
            url = sb.storage.from('media').getPublicUrl(path).data.publicUrl;
        } catch(e) {
            // Fallback base64 si el archivo es chico
            if (file.size <= 3*1024*1024) { try { url = await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);}); } catch(_){} }
        }
        if (url) window._editPostMedia.push({ url, type });
    }
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'GUARDAR CAMBIOS'; }
    input.value = '';
    window._renderEditMediaGrid();
};

window._saveEditPost = async function(postId) {
    const sb = window._sb;
    if (!sb) return;
    const text = (document.getElementById('edit-post-text')?.value || '').trim();
    const media = window._editPostMedia || [];
    const fit = window._editPostFit || 'horizontal';
    const update = {
        content: text || null,
        media_urls: media.length ? JSON.stringify(media) : null,
        media_url: media.length ? media[0].url : null,
        media_type: media.length ? media[0].type : 'text',
        media_fit: fit
    };
    const saveBtn = document.getElementById('edit-post-save');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Guardando...'; }
    let { error } = await sb.from('posts').update(update).eq('id', postId);
    if (error) {
        // Reintento sin columnas que puedan faltar (media_urls/media_fit)
        const minimal = { content: update.content, media_url: update.media_url, media_type: update.media_type };
        ({ error } = await sb.from('posts').update(minimal).eq('id', postId));
    }
    if (error) { showToast && showToast('Error al guardar: ' + error.message, 'error'); if (saveBtn){saveBtn.disabled=false;saveBtn.textContent='GUARDAR CAMBIOS';} return; }
    showToast && showToast('Publicación actualizada ✓', 'success');
    document.getElementById('edit-post-modal')?.remove();
    try { if (typeof loadProfilePosts === 'function') loadProfilePosts(); } catch(e){}
    try { if (typeof loadMainFeed === 'function') loadMainFeed(); } catch(e){}
};

window.openOtherPostMenu = function(postId, authorEmail) {
    const modal = document.createElement('div');
    modal.id = 'other-post-menu-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9500;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,0.75);backdrop-filter:blur(6px);';
    const dismiss = `document.getElementById('other-post-menu-modal')&&document.getElementById('other-post-menu-modal').remove()`;
    const isAdmin = window.userData && window.userData.role === 'admin';
    const isBot = authorEmail && authorEmail.includes('bot-') && authorEmail.includes('@canchero.app');
    const adminDeleteBtn = (isAdmin && isBot) ? `
        <button onclick="window._adminDeletePost('${postId}','${authorEmail}');${dismiss}"
          style="display:flex;align-items:center;gap:14px;width:100%;background:none;border:none;color:#ff4d4d;padding:14px 0;cursor:pointer;font-size:15px;font-weight:700;border-bottom:1px solid #1e1e1e;text-align:left;">
          <i class='bx bx-trash' style='font-size:20px;flex-shrink:0;'></i> 🛡️ Eliminar post del bot
        </button>` : '';
    modal.innerHTML = `
      <div style="background:#111;border:1px solid #222;border-radius:20px;width:100%;max-width:480px;padding:20px;box-shadow:0 8px 40px rgba(0,0,0,0.8);">
        <div style="width:36px;height:4px;background:#2a2a2a;border-radius:4px;margin:0 auto 18px;"></div>
        ${adminDeleteBtn}
        <button onclick="openBlockUser('${authorEmail}');${dismiss}"
          style="display:flex;align-items:center;gap:14px;width:100%;background:none;border:none;color:#fff;padding:14px 0;cursor:pointer;font-size:15px;font-weight:700;border-bottom:1px solid #1e1e1e;text-align:left;">
          <i class='bx bx-block' style='font-size:20px;flex-shrink:0;color:#ff8c00'></i> Bloquear usuario
        </button>
        <button onclick="openReportContent('${postId}','post','${authorEmail}');${dismiss}"
          style="display:flex;align-items:center;gap:14px;width:100%;background:none;border:none;color:#fff;padding:14px 0;cursor:pointer;font-size:15px;font-weight:700;border-bottom:1px solid #1e1e1e;text-align:left;">
          <i class='bx bx-flag' style='font-size:20px;flex-shrink:0;color:#ff4d4d'></i> Reportar contenido
        </button>
        <button onclick="${dismiss}"
          style="display:block;width:100%;background:none;border:none;color:#555;padding:14px 0;cursor:pointer;font-size:14px;text-align:center;margin-top:4px;">Cancelar</button>
      </div>`;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
    document.body.appendChild(modal);
};

window._adminDeletePost = async function(postId, authorEmail) {
    const sb = window._sb;
    if (!sb) return;
    if (!confirm('¿Eliminar este post del bot?')) return;
    const { error } = await sb.from('posts').delete().eq('id', postId);
    if (error) { showToast('Error al eliminar: ' + error.message, 'error'); return; }
    showToast('Post eliminado.', 'success');
    try { loadFeed('amigos-feed'); } catch(e) {}
    try { loadFeed('jugador-profile-feed-posts'); } catch(e) {}
};

// ============================================================
// PIN / UNPIN DE POSTS — almacenado en localStorage (sin permiso UPDATE en Supabase)
// ============================================================
function _getPinnedPosts() {
    try { return JSON.parse(localStorage.getItem('canchero_pinned_posts') || '[]'); } catch(e) { return []; }
}
function _savePinnedPosts(arr) {
    localStorage.setItem('canchero_pinned_posts', JSON.stringify(arr));
}
window.isPinnedLocally = function(postId) {
    return _getPinnedPosts().includes(String(postId));
};

window.pinPost = async function(postId) {
    if (!userData) return;
    const pins = _getPinnedPosts();
    if (pins.length >= 20) {
        showToast('Límite: ya tenés 20 publicaciones fijadas. Desfijá alguna primero.', 'warning');
        return;
    }
    if (!pins.includes(String(postId))) pins.push(String(postId));
    _savePinnedPosts(pins);
    // Try Supabase too (may fail silently — ok)
    const sb = window._sb;
    if (sb) {
        try { await sb.from('posts').update({ pinned: true, pinned_at: new Date().toISOString() }).eq('id', postId).eq('user_email', userData.email); } catch(e) {}
    }
    showToast('📌 Publicación fijada en tu perfil.', 'success');
    try { loadMainFeed(); } catch(e) {}
    try { loadProfilePosts(); } catch(e) {}
};

window.unpinPost = async function(postId) {
    if (!userData) return;
    const pins = _getPinnedPosts().filter(id => id !== String(postId));
    _savePinnedPosts(pins);
    const sb = window._sb;
    if (sb) {
        const newExpiry = new Date(Date.now() + 12 * 60 * 60 * 1000).toISOString();
        try { await sb.from('posts').update({ pinned: false, pinned_at: null, expires_at: newExpiry }).eq('id', postId).eq('user_email', userData.email); } catch(e) {}
    }
    showToast('Publicación desfijada.', 'success');
    try { loadMainFeed(); } catch(e) {}
    try { loadProfilePosts(); } catch(e) {}
};

// ============================================================
// PUBLICACIONES DEL PERFIL — fijadas + recientes no expiradas
// ============================================================
window.loadProfilePosts = async function() {
    const container = document.getElementById('jugador-profile-feed-posts') ||
                      document.getElementById('jugador-publicaciones-feed') ||
                      document.getElementById('player-posts-feed') ||
                      document.querySelector('#jugador-publicaciones .social-feed');
    if (!container) return;
    // Esperar _sb Y userData si aún no están listos (race condition al recargar)
    // Retry hasta 5 veces con 800ms = 4 segundos máximo de espera
    if (!_sb || !userData) {
        let attempts = 0;
        await new Promise(resolve => {
            const wait = setInterval(() => {
                attempts++;
                if ((_sb && userData) || attempts >= 5) { clearInterval(wait); resolve(); }
            }, 800);
        });
    }
    if (!_sb || !userData) return;
    container.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div>';
    // Mostrar posts no expirados o fijados (incluye posts viejos sin expires_at hasta 12hs)
    const _now = new Date().toISOString();
    const _cut = new Date(Date.now() - 12 * 3600000).toISOString();
    const sbP = _sb;
    let { data, error } = await sbP.from('posts')
        .select('*')
        .eq('user_email', userData.email)
        .or(`pinned.eq.true,expires_at.gt.${_now},and(expires_at.is.null,created_at.gt.${_cut})`)
        .order('created_at', { ascending: false })
        .limit(100);
    // Retry una vez si no hay datos (posible race condition)
    if (!error && (!data || data.length === 0)) {
        await new Promise(r => setTimeout(r, 800));
        const retry = await sbP.from('posts').select('*').eq('user_email', userData.email)
            .or(`pinned.eq.true,expires_at.gt.${_now},and(expires_at.is.null,created_at.gt.${_cut})`)
            .order('created_at', { ascending: false }).limit(100);
        if (!retry.error) data = retry.data;
    }
    if (error) {
        container.innerHTML = '<div style="padding:40px;text-align:center;color:#555;font-size:13px;">Error al cargar publicaciones.</div>';
        return;
    }
    // Filtrar posts ocultos localmente y enriquecer con datos actuales del usuario
    const hiddenIds = (function(){try{return JSON.parse(localStorage.getItem('canchero_hidden_posts')||'[]');}catch(e){return [];}})();
    const pinnedLocal = (function(){try{return JSON.parse(localStorage.getItem('canchero_pinned_posts')||'[]');}catch(e){return [];}})();
    // IDENTIDADES SEPARADAS (A1): "mis publicaciones" muestra SOLO los posts hechos
    // con la identidad activa (jugador / fanático / club / negocio), no todos los del
    // email. Los posts guardan user_role; mapear la identidad activa a los roles válidos.
    const _actProf = (window._activeProfileType && window._activeProfileType()) || 'jugador';
    let _allowRoles = null; // null = mostrar todo (fallback)
    if (_actProf === 'fanatico') _allowRoles = ['fanatico'];
    else if (_actProf === 'team') _allowRoles = ['club', 'cancha'];
    else if (_actProf === 'negocio' || (_actProf||'').indexOf('biz:') === 0) {
        // Identidad de negocio: mostrar SOLO los posts de ese rol de negocio (tienda ≠ complejo).
        const _tr = ((window._trueRole && window._trueRole()) || '').toLowerCase();
        if (_tr === 'tienda') _allowRoles = ['tienda', 'store', 'shop'];
        else if (_tr === 'club' || _tr === 'complejo') _allowRoles = ['complejo', 'club'];
        else if (_tr) _allowRoles = [_tr];
        else _allowRoles = ['tienda', 'complejo', 'organizacion'];
    } else { // jugador (incluye posts viejos sin rol)
        _allowRoles = ['jugador', 'player', ''];
    }
    const visible = (data || [])
        .filter(p => !hiddenIds.includes(String(p.id)) && !p.parent_post_id)
        .filter(p => !_allowRoles || _allowRoles.includes((p.user_role || 'jugador').toLowerCase()))
        .map(p => ({
            ...p,
            user_name: userData.name || p.user_name,
            user_avatar: userData.photo || p.user_avatar,
            pinned: pinnedLocal.includes(String(p.id)) || p.pinned
        }))
        .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    if (!visible.length) {
        container.innerHTML = '<div style="padding:40px;text-align:center;color:#555;font-size:13px;"><i class="bx bx-message-square-detail" style="font-size:36px;display:block;margin-bottom:10px;"></i>Aún no has realizado ninguna publicación.</div>';
        return;
    }
    // Cargar qué posts ya likeó el usuario para marcar el botón correctamente
    let likedIds = new Set();
    try {
        const sbLike = _sb;
        const { data: myLikes } = await sbLike.from('post_likes')
            .select('post_id')
            .eq('user_email', userData.email)
            .in('post_id', visible.map(p => p.id));
        (myLikes || []).forEach(l => likedIds.add(String(l.post_id)));
        window._myLikedPostIds = likedIds; // cache global para buildPostCard sin param
    } catch(e) {}

    container.innerHTML = visible.map(p => buildPostCard(p, likedIds.has(String(p.id)))).join('');

    // Actualizar conteos REALES de comentarios (no depender de columna posiblemente desactualizada)
    try {
        const postIds = visible.map(p => p.id).filter(Boolean);
        if (postIds.length > 0) {
            const sbC = _sb;
            const { data: cmtRows } = await sbC.from('post_comments').select('post_id').in('post_id', postIds);
            if (cmtRows) {
                const counts = {};
                cmtRows.forEach(c => { counts[c.post_id] = (counts[c.post_id] || 0) + 1; });
                Object.entries(counts).forEach(([pid, cnt]) => {
                    const el = window._postEl('comment-count-' + pid);
                    if (el) el.textContent = cnt;
                });
            }
        }
    } catch(e) {}

    // Cargar encuestas propias e insertar entre posts
    setTimeout(async () => {
        if (!window.CancheroPolls) return;
        try {
            const myPolls = await window.CancheroPolls.loadProfilePolls(userData.email);
            if (!myPolls.length) return;
            // Insertar cada encuesta en su posición cronológica
            myPolls.forEach(poll => {
                const html = window.CancheroPolls.renderPollCard(poll, poll._myVote);
                const articles = container.querySelectorAll('article.post-card, article.poll-card');
                let inserted = false;
                for (const art of articles) {
                    const postDate = art.dataset.createdAt ? new Date(art.dataset.createdAt) : null;
                    if (!postDate) {
                        art.insertAdjacentHTML('afterend', html);
                        inserted = true; break;
                    }
                    if (new Date(poll.created_at) > postDate) {
                        art.insertAdjacentHTML('beforebegin', html);
                        inserted = true; break;
                    }
                }
                if (!inserted) container.insertAdjacentHTML('beforeend', html);
            });
        } catch(e) {}
    }, 300);
};

// --- FEED MEDIA PREVIEW ---
window._feedPostFit = 'horizontal';
window._setFeedFit = function(f) {
    window._feedPostFit = f;
    ['horizontal','vertical'].forEach(x => {
        const b = document.getElementById('feed-fit-' + x);
        if (b) { const on = x===f; b.style.borderColor = on?'var(--accent)':'#2a2a2a'; b.style.background = on?'rgba(186,255,0,0.08)':'transparent'; b.style.color = on?'var(--accent)':'#aaa'; }
    });
};

// ── HILOS (vista tipo X/Threads) ───────────────────────────
window.openHilos = async function() {
    let modal = document.getElementById('hilos-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'hilos-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:10500;background:#0a0a0a;display:flex;flex-direction:column;';
    modal.innerHTML = `
        <div style="display:flex;align-items:center;gap:12px;padding:calc(12px + env(safe-area-inset-top)) 16px 12px;border-bottom:1px solid #1e1e1e;background:#0d0d0d;">
            <button onclick="document.getElementById('hilos-modal').remove()" style="background:rgba(255,255,255,0.08);border:1px solid #2a2a2a;color:#fff;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:19px;"><i class='bx bx-arrow-back'></i></button>
            <div style="font-weight:900;font-size:17px;">Hilos</div>
        </div>
        <div id="hilos-body" style="flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;max-width:600px;margin:0 auto;width:100%;box-sizing:border-box;padding:8px 0;"><div style="text-align:center;padding:40px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div></div>`;
    document.body.appendChild(modal);
    const sb = window._sb;
    const body = document.getElementById('hilos-body');
    if (!sb || !body) return;
    try {
        // Hilos = todas las publicaciones y hilos, EXCEPTO los reels (esos van al apartado Reels)
        let { data } = await sb.from('posts').select('*').neq('is_reel', true).order('created_at',{ascending:false}).limit(60);
        if (!data) {
            // fallback si la columna is_reel no existe aún
            ({ data } = await sb.from('posts').select('*').order('created_at',{ascending:false}).limit(60));
        }
        // Excluир respuestas de hilo del listado principal (se ven al abrir el hilo)
        if (data) data = data.filter(p => !p.parent_post_id);
        if (!data || !data.length) { body.innerHTML = '<div style="text-align:center;padding:50px 20px;color:#666;"><i class="bx bx-conversation" style="font-size:48px;opacity:0.3;display:block;margin-bottom:12px;"></i>Todavía no hay publicaciones.</div>'; return; }
        body.innerHTML = data.map(p => {
            const init = (p.user_name||'?')[0].toUpperCase();
            const rootId = p.thread_root_id || p.id;
            return `<div onclick="document.getElementById('hilos-modal').remove();openPostThread('${rootId}')" style="display:flex;gap:12px;padding:14px 16px;border-bottom:1px solid #161616;cursor:pointer;">
                <div style="width:42px;height:42px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${init}</div>
                <div style="flex:1;min-width:0;">
                    <div style="font-size:14px;font-weight:800;">${p.user_name||'Jugador'} <span style="font-size:11px;color:#666;font-weight:400;">· ${_timeAgoSimple? _timeAgoSimple(p.created_at):''}</span></div>
                    <div style="font-size:14px;color:#ddd;margin-top:3px;word-break:break-word;">${((p.content||'[media]')).replace(/</g,'&lt;').slice(0,180)}</div>
                    <div style="display:flex;gap:18px;margin-top:8px;color:#666;font-size:12px;">
                        <span><i class='bx bx-conversation'></i> ${p.reply_count||0}</span>
                        <span><i class='bx bx-heart'></i> ${p.likes_count||0}</span>
                        <span style="color:var(--accent);font-weight:700;">Ver hilo</span>
                    </div>
                </div>
            </div>`;
        }).join('');
    } catch(e) { body.innerHTML = '<div style="padding:20px;color:#f44;">No se pudieron cargar los hilos.</div>'; }
};

// Reel desde el perfil (composer del perfil)
window._startReelComposeProfile = function() {
    window._isReelPostProfile = true;
    const inp = document.getElementById('player-post-media');
    if (inp) { inp.setAttribute('accept', 'video/*'); inp.click(); }
    if (typeof showToast === 'function') showToast('Elegí un video vertical para tu Reel 🎬', 'default');
};

// ── REELS ──────────────────────────────────────────────────
window._startReelCompose = function() {
    window._isReelPost = true;
    window._feedPostFit = 'vertical';
    const inp = document.getElementById('feed-post-media');
    if (inp) {
        inp.setAttribute('accept', 'video/*');
        inp.click();
    }
    if (typeof showToast === 'function') showToast('Elegí un video vertical para tu Reel 🎬', 'default');
};

window._reelsState = { items: [], offset: 0, loading: false, done: false, idx: 0 };

// Cierra reels cortando el audio: pausa y vacía todos los videos antes de quitar
// el modal (en algunos WebViews el audio seguía sonando al solo remover el nodo).
window._closeReels = function() {
    var m = document.getElementById('reels-modal');
    // Restaurar la barra inferior (ruleta) que se ocultó al abrir los reels.
    try { ['player-bottom-nav','club-bottom-nav'].forEach(function(n){ var el=document.getElementById(n); if(el) el.style.removeProperty('display'); }); } catch(e){}
    try { if (window._reelsIO) { window._reelsIO.disconnect(); window._reelsIO = null; } } catch(e){}
    if (m) {
        m.querySelectorAll('video').forEach(function(v){
            try { v.pause(); v.muted = true; v.removeAttribute('src'); v.load(); } catch(e){}
        });
        m.remove();
    }
    // Reset del pool → la próxima entrada vuelve a mezclar (orden distinto cada vez)
    if (window._reelsState) { window._reelsState._pool = null; window._reelsState._poolIdx = 0; window._reelsState.offset = 0; window._reelsState.items = []; window._reelsState.done = false; }
};

// Toggle robusto de pausa/reproducción del reel al tocar el centro (P6.2).
// Recibe el <video> directamente (this) → no depende de ids ni de overlays.
// Marca data-userpaused para que los handlers de scroll no lo re-reproduzcan solos.
window._reelTogglePause = function(v){
    try {
        if (!v || v.tagName !== 'VIDEO') return;
        if (v.paused) { v.dataset.userpaused = ''; v.play().catch(function(){}); }
        else { v.pause(); v.dataset.userpaused = '1'; }
        var card = (v.closest && v.closest('[data-reel-card]')) || v.parentElement;
        var ic = card && card.querySelector && card.querySelector('.reel-pause-icon');
        if (ic) ic.style.display = v.paused ? 'flex' : 'none';
    } catch(e){}
};
window.openReels = async function(startId) {
    window._reelsStartId = startId || null;
    let modal = document.getElementById('reels-modal');
    if (modal) window._closeReels();
    modal = document.createElement('div');
    modal.id = 'reels-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:10500;background:#000;';
    // Ocultar la barra inferior (ruleta) mientras se ven reels — no debe verse encima.
    try { ['player-bottom-nav','club-bottom-nav'].forEach(function(n){ var el=document.getElementById(n); if(el) el.style.setProperty('display','none','important'); }); } catch(e){}
    modal.innerHTML = `
        <div style="position:absolute;top:0;left:0;right:0;z-index:10;display:flex;align-items:center;justify-content:space-between;padding:calc(10px + env(safe-area-inset-top)) 16px 10px;background:linear-gradient(180deg,rgba(0,0,0,0.6),transparent);">
            <div style="font-weight:900;font-size:18px;color:#fff;">REELS</div>
            <button onclick="window._closeReels()" style="background:rgba(255,255,255,0.12);border:none;color:#fff;width:38px;height:38px;border-radius:50%;font-size:20px;cursor:pointer;"><i class='bx bx-x'></i></button>
        </div>
        <div id="reels-scroll" style="height:100vh;height:100dvh;overflow-y:scroll;scroll-snap-type:y mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none;"></div>`;
    document.body.appendChild(modal);
    window._reelsState = { items: [], offset: 0, loading: false, done: false, idx: 0 };
    if (typeof window._reelsMuted === 'undefined') window._reelsMuted = true; // primer play debe ser muteado (política autoplay)
    await window._loadMoreReels();
    const sc = document.getElementById('reels-scroll');

    // Autoplay confiable con IntersectionObserver (reproduce el reel visible, pausa el resto)
    // Si el video se quedó "en negro" (Cloudinary/Safari libera el frame), recargá su src.
    window._reelsIO = new IntersectionObserver(function(entries){
        entries.forEach(function(en){
            const v = en.target.querySelector('video');
            if (!v) return;
            if (en.isIntersecting && en.intersectionRatio >= 0.6){
                // Respetar la pausa manual del usuario (P6.2)
                if (v.dataset.userpaused === '1') return;
                // VIRTUALIZACIÓN: mantener vivos SOLO el reel visible y sus 2 vecinos.
                // iOS deja de decodificar video tras acumular demasiados <video> → todos
                // se ven en NEGRO. Liberamos los lejanos y restauramos los cercanos.
                try { window._reelsVirtualize && window._reelsVirtualize(en.target); } catch(_e){}
                try {
                    if (v.readyState < 2) { v.load(); }
                    v.setAttribute('playsinline',''); v.setAttribute('webkit-playsinline','');
                    v.playsInline = true;
                } catch(_e){}
                v.muted = (typeof window._reelsMuted === 'undefined') ? true : window._reelsMuted;
                var _pp = v.play();
                if (_pp && _pp.catch) _pp.catch(function(){
                    v.muted = true;
                    v.play().catch(function(){
                        // Autoplay bloqueado (iOS Modo bajo consumo): mostrar botón de play grande
                        try { var c = v.closest('[data-reel-card]'); var a = c && c.querySelector('.reel-play-affordance'); if (a) a.style.display = 'flex'; } catch(e){}
                    });
                });
            } else {
                v.pause();
                // Liberar buffer del video lejos (no del adyacente) — mejora memoria móvil
                try {
                    if (en.intersectionRatio === 0) {
                        // marcar pero no liberar todavía; si está MUY lejos, sí
                    }
                } catch(_e){}
            }
        });
    }, { threshold: [0, 0.6, 1] });
    window._reelsObserveAll = function(){
        if (!sc || !window._reelsIO) return;
        sc.querySelectorAll('[data-reel-card]').forEach(c=>{ try{ window._reelsIO.observe(c); }catch(e){} });
        // fallback si las cards no tienen el data-attr: observar hijos directos
        if (!sc.querySelector('[data-reel-card]')) Array.from(sc.children).forEach(c=>{ try{ window._reelsIO.observe(c); }catch(e){} });
    };
    // Mantiene cargados SOLO el reel central y sus 2 vecinos; libera el <video> (suelta
    // el decoder) de los lejanos para no agotar el límite de iOS (que deja todo en negro).
    window._reelsVirtualize = function(centerEl){
        try {
            var cards = Array.prototype.slice.call(sc.querySelectorAll('[data-reel-card]'));
            var ci = cards.indexOf(centerEl);
            if (ci < 0) return;
            cards.forEach(function(c, i){
                var v = c.querySelector('video'); if (!v) return;
                if (Math.abs(i - ci) <= 1){
                    // Cercano: restaurar el src si estaba liberado.
                    if (!v.getAttribute('src') && v.dataset.vsrc){ v.setAttribute('src', v.dataset.vsrc); try { v.load(); } catch(e){} }
                } else {
                    // Lejano: guardar el src y liberar el elemento de video.
                    if (v.getAttribute('src')){ v.dataset.vsrc = v.getAttribute('src'); try { v.pause(); } catch(e){} v.removeAttribute('src'); try { v.load(); } catch(e){} }
                }
            });
        } catch(e){}
    };
    window._reelsObserveAll();
    // Reproducir el primero ya
    setTimeout(()=>{ const first = sc && sc.querySelector('video'); if(first){ first.muted = window._reelsMuted; first.play().catch(()=>{ first.muted=true; first.play().catch(()=>{}); }); } }, 150);

    if (sc) {
        sc.addEventListener('scroll', function() {
            if (sc.scrollTop + sc.clientHeight * 2.5 >= sc.scrollHeight) {
                window._loadMoreReels().then(()=>{ if(window._reelsObserveAll) window._reelsObserveAll(); });
            }
        }, { passive: true });
        // El tap sobre el video pausa/reanuda (P6.2) — lo maneja el onclick del
        // propio <video> (_reelTogglePause). El sonido va por el botón de parlante.
    }
    // Swipe horizontal: deslizar a la derecha cierra Reels y vuelve a Publicaciones
    let _rsx=0,_rsy=0;
    modal.addEventListener('touchstart', e=>{ _rsx=e.touches[0].clientX; _rsy=e.touches[0].clientY; }, {passive:true});
    modal.addEventListener('touchend', e=>{
        const dx=e.changedTouches[0].clientX-_rsx, dy=e.changedTouches[0].clientY-_rsy;
        if (dx>80 && Math.abs(dx)>Math.abs(dy)*1.5){ window._closeReels(); if(window.switchFeedView) window.switchFeedView('publicaciones'); }
    }, {passive:true});
};

// Seguir desde el reel
window._reelFollow = async function(email, btn) {
    const sb = window._sb; const me = window.userData;
    if (!sb || !me || !email) { showToast && showToast('Iniciá sesión.', 'warning'); return; }
    try {
        await sb.from('follows').insert({ follower_email: me.email, following_email: email });
        btn.textContent = 'Siguiendo'; btn.style.background = 'transparent';
        showToast && showToast('Ahora seguís a este jugador', 'success');
    } catch(e) { btn.textContent = 'Siguiendo'; btn.style.background = 'transparent'; }
};

// Like en reel
window._reelLike = async function(postId, btn) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) { showToast && showToast('Iniciá sesión.', 'warning'); return; }
    const liked = btn.getAttribute('data-liked') === 'true';
    const countEl = document.getElementById('reel-like-' + postId);
    let n = parseInt(countEl?.textContent || '0');
    try {
        if (liked) {
            await sb.from('post_likes').delete().eq('post_id', postId).eq('user_email', me.email);
            btn.setAttribute('data-liked','false'); btn.style.color='#fff';
            btn.querySelector('i').className='bx bx-heart'; if(countEl) countEl.textContent = Math.max(0,n-1);
        } else {
            await sb.from('post_likes').insert({ post_id: postId, user_email: me.email, user_name: me.name });
            btn.setAttribute('data-liked','true'); btn.style.color='var(--accent)';
            btn.querySelector('i').className='bx bxs-heart'; if(countEl) countEl.textContent = n+1; window._footballLikeAnim(btn);
            try { const { data: pp } = await sb.from('posts').select('likes_count').eq('id',postId).single(); if(pp) await sb.from('posts').update({likes_count:(pp.likes_count||0)+1}).eq('id',postId); } catch(e){}
        }
    } catch(e) {}
};

// Compartir reel: a mi perfil/feed o por mensaje (con preview)
window._shareReel = function(postId) {
    try { window._registerPostShare && window._registerPostShare(postId); const el=document.getElementById('reel-share-'+postId); if(el) el.textContent = (parseInt(el.textContent)||0)+1; } catch(e){}
    let sheet = document.getElementById('reel-share-sheet');
    if (sheet) sheet.remove();
    sheet = document.createElement('div');
    sheet.id = 'reel-share-sheet';
    sheet.style.cssText = 'position:fixed;inset:0;z-index:10700;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    sheet.innerHTML = `
        <div style="background:#161616;border:1px solid #2a2a2a;border-radius:20px;width:100%;max-width:300px;padding:18px 16px;box-shadow:0 8px 40px rgba(0,0,0,0.9);animation:sharePopIn .18s cubic-bezier(0.34,1.56,0.64,1) both;">
            <div style="font-weight:900;font-size:14px;margin-bottom:14px;text-align:center;color:#fff;">Compartir reel</div>
            <button onclick="window._reelRepost('${postId}')" style="display:flex;align-items:center;gap:12px;width:100%;background:rgba(186,255,0,0.06);border:1px solid rgba(186,255,0,0.15);border-radius:12px;padding:12px 14px;color:#fff;cursor:pointer;margin-bottom:8px;font-size:13px;font-weight:700;box-sizing:border-box;">
                <i class='bx bx-repost' style="font-size:20px;color:var(--accent);flex-shrink:0;"></i> Repostear en mi feed
            </button>
            <button onclick="window._reelSendDM('${postId}')" style="display:flex;align-items:center;gap:12px;width:100%;background:rgba(186,255,0,0.06);border:1px solid rgba(186,255,0,0.15);border-radius:12px;padding:12px 14px;color:#fff;cursor:pointer;margin-bottom:8px;font-size:13px;font-weight:700;box-sizing:border-box;">
                <i class='bx bx-send' style="font-size:20px;color:var(--accent);flex-shrink:0;"></i> Enviar por mensaje
            </button>
            <button onclick="document.getElementById('reel-share-sheet').remove();window.cancheroShare({type:'reel',id:'${postId}',title:'Reel en Canchero',text:'Mirá este reel en Canchero'})" style="display:flex;align-items:center;gap:12px;width:100%;background:rgba(186,255,0,0.06);border:1px solid rgba(186,255,0,0.15);border-radius:12px;padding:12px 14px;color:#fff;cursor:pointer;margin-bottom:12px;font-size:13px;font-weight:700;box-sizing:border-box;">
                <i class='bx bx-link-external' style="font-size:20px;color:var(--accent);flex-shrink:0;"></i> WhatsApp, Instagram, X...
            </button>
            <button onclick="document.getElementById('reel-share-sheet').remove()" style="width:100%;background:transparent;border:1px solid #2a2a2a;color:#555;border-radius:12px;padding:9px;cursor:pointer;font-size:12px;font-weight:700;">Cancelar</button>
        </div>`;
    sheet.onclick = e => { if (e.target === sheet) sheet.remove(); };
    document.body.appendChild(sheet);
};
window._reelRepost = async function(postId) {
    const sb = window._sb; const me = window.userData;
    document.getElementById('reel-share-sheet')?.remove();
    if (!sb || !me) return;
    try {
        const { data: orig } = await sb.from('posts').select('*').eq('id', postId).single();
        if (!orig) return;
        await sb.from('posts').insert({ user_email: me.email, user_name: me.name, user_avatar: me.photo||null, user_role: me.role||'jugador', content: (orig.content||'')+' (reel compartido)', media_url: orig.media_url, media_type: 'video', is_reel: true, likes_count:0, expires_at: new Date(Date.now()+12*3600000).toISOString() });
        showToast && showToast('Reel reposteado en tu perfil 🎬', 'success');
    } catch(e) { showToast && showToast('Error: '+e.message, 'error'); }
};
window._reelSendDM = async function(postId) {
    document.getElementById('reel-share-sheet')?.remove();
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) { showToast && showToast('Iniciá sesión.', 'warning'); return; }
    // Abrir sheet para elegir un contacto (seguidos)
    let sheet = document.getElementById('reel-dm-sheet');
    if (sheet) sheet.remove();
    sheet = document.createElement('div');
    sheet.id = 'reel-dm-sheet';
    sheet.style.cssText = 'position:fixed;inset:0;z-index:10700;background:rgba(0,0,0,0.8);display:flex;align-items:flex-end;justify-content:center;';
    sheet.innerHTML = `<div style="background:#111;width:100%;max-width:520px;max-height:65vh;border-radius:20px 20px 0 0;padding:14px 16px calc(14px + env(safe-area-inset-bottom));display:flex;flex-direction:column;box-sizing:border-box;">
        <div style="width:36px;height:4px;background:#333;border-radius:2px;margin:0 auto 12px;flex-shrink:0;"></div>
        <div style="font-weight:900;font-size:14px;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;">
            <span>Enviar reel a...</span>
            <button onclick="document.getElementById('reel-dm-sheet').remove()" style="background:none;border:none;color:#888;font-size:20px;cursor:pointer;line-height:1;">&times;</button>
        </div>
        <input id="reel-dm-search" type="text" placeholder="Buscar contacto..." style="background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:12px;padding:9px 14px;font-size:13px;outline:none;margin-bottom:8px;flex-shrink:0;box-sizing:border-box;width:100%;">
        <div id="reel-dm-list" style="flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;min-height:80px;"><div style="text-align:center;padding:20px;color:#555;"><i class='bx bx-loader-alt bx-spin'></i></div></div>
    </div>`;
    document.body.appendChild(sheet);
    sheet.onclick = e => { if (e.target === sheet) sheet.remove(); };

    // Cargar seguidos
    try {
        const { data: follows } = await sb.from('follows').select('following_email').eq('follower_email', me.email).limit(60);
        const emails = (follows||[]).map(f=>f.following_email).filter(Boolean);
        let users = [];
        if (emails.length){ const { data } = await sb.from('users').select('email,name,photo').in('email', emails); users = data || []; }
        const list = document.getElementById('reel-dm-list');
        if (!list) return;
        function _render(filter) {
            const q = (filter||'').toLowerCase();
            const fu = users.filter(u => !q || (u.name||'').toLowerCase().includes(q) || (u.email||'').toLowerCase().includes(q));
            if (!fu.length){ list.innerHTML = '<div style="text-align:center;padding:30px;color:#555;font-size:12px;">No tenés a quien enviarlo. Seguí jugadores y volvé.</div>'; return; }
            list.innerHTML = fu.map(u => {
                const init = (u.name||'?')[0].toUpperCase();
                const hasPhoto = u.photo && !u.photo.includes('ui-avatars');
                const avatar = hasPhoto
                    ? `<div style="width:38px;height:38px;border-radius:50%;background:#000 center/cover url('${u.photo}');flex-shrink:0;"></div>`
                    : `<div style="width:38px;height:38px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0;">${init}</div>`;
                return `<div onclick="window._reelDoSendDM('${postId}','${(u.email||'').replace(/'/g,"\\'")}','${(u.name||'').replace(/'/g,"\\'")}')" style="display:flex;align-items:center;gap:10px;padding:10px;border-bottom:1px solid #1a1a1a;cursor:pointer;">
                    ${avatar}<div style="flex:1;font-size:13px;font-weight:700;">${u.name||u.email}</div>
                    <button style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:6px 14px;font-size:11px;font-weight:800;cursor:pointer;">Enviar</button>
                </div>`;
            }).join('');
        }
        _render('');
        const inp = document.getElementById('reel-dm-search');
        if (inp) inp.oninput = e => _render(e.target.value);
    } catch(e) { showToast && showToast('Error: '+e.message, 'error'); }
};

window._reelDoSendDM = async function(postId, recipientEmail, recipientName) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) return;
    const url = `${window.location.origin}${window.location.pathname}#post-${postId}`;
    try {
        // Enviar mensaje con marcador #post-<uuid> que el chat detecta y renderiza como tarjeta clickeable
        await sb.from('messages').insert({
            sender_email: me.email,
            sender_name: me.name || me.email,
            recipient_email: recipientEmail,
            content: `🎬 Te comparto este reel: ${url}`,
            read: false
        });
        try {
            if (window.CancheroNotif) window.CancheroNotif.create(recipientEmail, 'message', me.name || me.email, '🎬 Te compartieron un reel', postId);
            else if (typeof notif !== 'undefined') notif.create(recipientEmail, 'message', me.name || me.email, '🎬 Te compartieron un reel', postId);
        } catch(e){}
        document.getElementById('reel-dm-sheet')?.remove();
        showToast && showToast(`Reel enviado a ${recipientName} ✓`, 'success');
    } catch(e) { showToast && showToast('Error al enviar: '+e.message, 'error'); }
};

// ── Visualizaciones: cada reproducción suma (estilo TikTok/IG, loops incluidos) ──
window._registerPostView = async function(postId) {
    if (!postId) return;
    const sb = window._sb;
    if (!sb) return;
    try {
        const { error } = await sb.rpc('increment_post_views', { p_post_id: postId });
        if (error) { // fallback si el RPC no existe aún
            const { data: pp } = await sb.from('posts').select('views_count').eq('id', postId).single();
            if (pp) await sb.from('posts').update({ views_count: (pp.views_count||0)+1 }).eq('id', postId);
        }
    } catch(e) {}
};
window._registerPostShare = async function(postId) {
    if (!postId) return;
    const sb = window._sb;
    if (!sb) return;
    try {
        const { error } = await sb.rpc('increment_post_shares', { p_post_id: postId });
        if (error) {
            await sb.rpc('bump_share', { p_post_id: postId }).catch?.(()=>{});
        }
    } catch(e) {}
};
window._fmtViews = function(n) {
    n = n || 0;
    if (n >= 1000000) return (n/1000000).toFixed(1).replace('.0','') + ' M';
    if (n >= 1000) return (n/1000).toFixed(1).replace('.0','') + ' mil';
    return String(n);
};

window._loadMoreReels = async function() {
    const st = window._reelsState;
    if (st.loading || st.done) return;
    st.loading = true;
    const sc = document.getElementById('reels-scroll');
    const sb = window._sb;
    if (!sb || !sc) { st.loading = false; return; }
    const PAGE = 5;
    try {
        // Primera carga: traer hasta 80 reels recientes y MEZCLAR (orden tipo IG,
        // ponderado por reciente y engagement). En cargas siguientes, seguir
        // sirviendo de ese pool ya mezclado.
        if (!st._pool) {
            // TODOS los videos son reels (pedido del usuario): no filtrar por is_reel,
            // así los videos que no quedaron marcados como reel igual aparecen acá.
            let { data } = await sb.from('posts').select('*').eq('media_type','video').is('parent_post_id',null).order('created_at',{ascending:false}).limit(80);
            data = (data||[]).filter(p => !p.repost_of && !p.original_user_email && p.media_url);
            // Score: engagement (likes/comments) + freshness; con jitter aleatorio para variar entre sesiones
            const now = Date.now();
            data.forEach(p => {
                const ageH = (now - new Date(p.created_at||now).getTime())/3600000;
                const fresh = 1/(1 + ageH/24); // decae con el tiempo
                const eng = (p.likes_count||0) + (p.comments_count||0)*2;
                p._score = eng + fresh*5 + Math.random()*6;
            });
            data.sort((a,b)=>b._score-a._score);
            // Si se abrió desde un reel específico del feed, ponerlo primero
            if (window._reelsStartId) {
                const _si = data.findIndex(p => String(p.id) === String(window._reelsStartId));
                if (_si > 0) { const [pick] = data.splice(_si,1); data.unshift(pick); }
                else if (_si < 0) {
                    try { const { data: one } = await sb.from('posts').select('*').eq('id', window._reelsStartId).single(); if (one && one.media_url) data.unshift(one); } catch(e){}
                }
            }
            st._pool = data;
            st._poolIdx = 0;
            // No mostrar al mismo autor 2 veces seguidas
            const reord = []; const seen = {};
            data.forEach(p => {
                const last = reord[reord.length-1];
                if (last && last.user_email===p.user_email) { seen[p.id] = p; return; }
                reord.push(p);
            });
            Object.values(seen).forEach(p=>reord.push(p));
            st._pool = reord;
        }
        const data = st._pool.slice(st._poolIdx, st._poolIdx + PAGE);
        if (!data.length) {
            st.done = true;
            if (st.items.length === 0) sc.innerHTML = '<div style="height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#666;gap:12px;padding:20px;text-align:center;"><i class="bx bx-movie-play" style="font-size:54px;opacity:0.3;"></i><div style="font-size:15px;font-weight:700;">Todavía no hay Reels</div><div style="font-size:12px;">Subí el primero desde el ícono de cámara del feed</div></div>';
            st.loading = false; return;
        }
        st._poolIdx += data.length;
        st.offset = st._poolIdx;
        st.items = st.items.concat(data);
        // Enriquecer con info del autor (foto, disponibilidad)
        const emails = [...new Set(data.map(p => p.user_email).filter(Boolean))];
        const uMap = {};
        try { if (emails.length){ const { data: us } = await sb.from('users').select('email,name,photo,photo_style,available').in('email', emails); (us||[]).forEach(u => uMap[u.email]=u); } } catch(e){}
        // Likes míos
        const myEmail = window.userData && window.userData.email;
        const myLikes = new Set();
        try { if (myEmail){ const ids = data.map(p=>p.id); const { data: lk } = await sb.from('post_likes').select('post_id').eq('user_email', myEmail).in('post_id', ids); (lk||[]).forEach(l=>myLikes.add(l.post_id)); } } catch(e){}

        data.forEach(p => {
            const u = uMap[p.user_email] || {};
            const photo = (u.photo && !u.photo.includes('ui-avatars')) ? u.photo : (p.user_avatar||'');
            const avail = !!u.available;
            const liked = myLikes.has(p.id);
            const card = document.createElement('div');
            card.setAttribute('data-reel-card','1');
            card.style.cssText = 'height:100vh;height:100dvh;min-height:100vh;width:100%;scroll-snap-align:start;scroll-snap-stop:always;position:relative;display:flex;align-items:center;justify-content:center;background:#000;';
            const init = (p.user_name||'?')[0].toUpperCase();
            const emailSafe = (p.user_email||'').replace(/'/g,"\\'");
            const nameSafe = (p.user_name||'').replace(/'/g,"\\'");
            // Foto de perfil con el MISMO encuadre que toda la app (photo_style del autor
            // o recorte de rostro center 25% por defecto) — no torso ni descentrada.
            const _avCss = (window._avatarBgCss && window._avatarBgCss({ photo: photo, photo_style: u.photo_style })) || (photo ? `background-image:url('${photo}');background-size:cover;background-position:center 25%;` : '');
            const avatarEl = photo
                ? `<div style="width:40px;height:40px;border-radius:50%;${_avCss}border:2px solid #fff;flex-shrink:0;"></div>`
                : `<div style="width:40px;height:40px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0;border:2px solid #fff;">${init}</div>`;
            const isMe = myEmail && p.user_email === myEmail;
            const reelVideoId = 'rv_' + p.id;
            // SIN fragmento #t= (rompe el range en iOS). El primer frame se fuerza con
            // un seek en onloadeddata → iOS decodifica y muestra el cuadro (no negro).
            let _reelSrc = window._playableVideoUrl ? window._playableVideoUrl(p.media_url) : p.media_url;
            const _reelPoster = (window._videoPosterUrl && window._videoPosterUrl(p.media_url)) || '';
            card.innerHTML = `
                <video id="${reelVideoId}" src="${_reelSrc}" ${_reelPoster?`poster="${_reelPoster}"`:''} loop playsinline webkit-playsinline preload="metadata" muted style="width:100%;height:100%;object-fit:contain;cursor:pointer;background:#000;" onloadedmetadata="try{if(this.currentTime<0.05)this.currentTime=0.1;}catch(e){}" onloadeddata="try{if(this.currentTime<0.05)this.currentTime=0.1;}catch(e){}" onplaying="try{var c=this.closest('[data-reel-card]');var i=c&&c.querySelector('.reel-play-affordance');if(i)i.style.display='none';}catch(e){}" onpause="try{if(this.dataset.userpaused!=='1')return;}catch(e){}" onclick="window._reelTogglePause(this)"></video>
                <div style="position:absolute;top:calc(58px + env(safe-area-inset-top));left:14px;z-index:6;display:flex;align-items:center;gap:3px;pointer-events:none;opacity:.6;text-shadow:0 1px 3px rgba(0,0,0,0.7);"><i class='bx bxs-been-here' style="font-size:13px;color:#baff00;"></i><span style="font-size:11px;font-weight:900;color:#fff;letter-spacing:.5px;">Canchero</span></div>
                <div class="reel-pause-icon" style="display:none;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:60px;height:60px;border-radius:50%;background:rgba(0,0,0,0.55);align-items:center;justify-content:center;pointer-events:none;"><i class='bx bx-pause' style="font-size:32px;color:#fff;"></i></div>
                <div class="reel-play-affordance" onclick="var v=this.closest('[data-reel-card]').querySelector('video');this.style.display='none';if(v){v.muted=false;window._reelsMuted=false;v.play().catch(function(){v.muted=true;v.play().catch(function(){});});}" style="display:none;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:76px;height:76px;border-radius:50%;background:rgba(0,0,0,0.6);align-items:center;justify-content:center;cursor:pointer;z-index:7;"><i class='bx bx-play' style="font-size:44px;color:#fff;margin-left:4px;"></i></div>
                <div class="reel-sound-hint" style="position:absolute;top:38%;left:50%;transform:translate(-50%,-50%);pointer-events:none;color:rgba(255,255,255,0.85);font-size:12px;background:rgba(0,0,0,0.4);padding:6px 12px;border-radius:20px;"><i class='bx bx-volume-mute'></i> sonido con el parlante</div>
                <!-- Barra de reproducción (interactiva) — por encima de la barra de opciones inferior -->
                <div style="position:absolute;left:12px;right:12px;bottom:calc(78px + env(safe-area-inset-bottom));z-index:8;display:flex;align-items:center;gap:8px;">
                    <span id="reel-cur-${p.id}" style="font-size:10px;color:#fff;font-weight:700;min-width:30px;text-shadow:0 1px 3px #000;">0:00</span>
                    <input id="reel-seek-${p.id}" type="range" min="0" max="1000" value="0" oninput="(function(s){var v=document.getElementById('${reelVideoId}');if(v&&v.duration){window._reelSeeking=true;v.currentTime=(s.value/1000)*v.duration;}})(this)" onchange="window._reelSeeking=false;" style="flex:1;height:4px;-webkit-appearance:none;appearance:none;background:rgba(255,255,255,0.3);border-radius:2px;outline:none;cursor:pointer;accent-color:var(--accent);">
                    <span id="reel-dur-${p.id}" style="font-size:10px;color:#fff;font-weight:700;min-width:30px;text-align:right;text-shadow:0 1px 3px #000;">0:00</span>
                </div>
                <!-- Columna de acciones (derecha) -->
                <div style="position:absolute;right:10px;bottom:calc(140px + env(safe-area-inset-bottom));display:flex;flex-direction:column;gap:18px;align-items:center;z-index:5;">
                    <button id="reel-mute-${p.id}" onclick="(function(b){var v=document.getElementById('${reelVideoId}');if(!v)return;v.muted=!v.muted;window._reelsMuted=v.muted;if(!v.muted)v.play().catch(()=>{});b.querySelector('i').className='bx '+(v.muted?'bx-volume-mute':'bx-volume-full');})(this)" style="background:none;border:none;color:#fff;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;"><i class='bx ${window._reelsMuted?'bx-volume-mute':'bx-volume-full'}' style="font-size:30px;"></i></button>
                    <button onclick="window._reelLike('${p.id}',this)" data-liked="${liked}" style="background:none;border:none;color:${liked?'var(--accent)':'#fff'};display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;"><i class='bx ${liked?'bxs-heart':'bx-heart'}' style="font-size:32px;"></i><span style="font-size:11px;font-weight:700;" id="reel-like-${p.id}">${p.likes_count||0}</span></button>
                    <button onclick="window.openComments&&window.openComments('${p.id}')" style="background:none;border:none;color:#fff;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;"><i class='bx bx-comment' style="font-size:30px;"></i><span id="reel-comment-count-${p.id}" style="font-size:11px;font-weight:700;">${p.comments_count||0}</span></button>
                    <button onclick="window._shareReel('${p.id}')" style="background:none;border:none;color:#fff;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;"><i class='bx bx-share' style="font-size:30px;"></i><span style="font-size:11px;font-weight:700;" id="reel-share-${p.id}">${p.shares_count||0}</span></button>
                </div>
                <!-- Info autor (abajo izquierda) — padding-bottom mayor para que el contador
                     de reproducciones quede ARRIBA de la barra de reproducción (P6.1). -->
                <div style="position:absolute;left:0;right:66px;bottom:0;padding:16px 16px calc(112px + env(safe-area-inset-bottom));background:linear-gradient(0deg,rgba(0,0,0,0.85) 0%,rgba(0,0,0,0.5) 60%,transparent 100%);z-index:5;">
                    <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
                        <div onclick="window._closeReels();window.viewUserProfile&&window.viewUserProfile('${emailSafe}')" style="cursor:pointer;">${avatarEl}</div>
                        <div onclick="window._closeReels();window.viewUserProfile&&window.viewUserProfile('${emailSafe}')" style="font-weight:800;font-size:14px;color:#fff;cursor:pointer;display:flex;align-items:center;gap:6px;">${p.user_name||'Jugador'}${avail?'<span style="width:9px;height:9px;background:#00e676;border-radius:50%;box-shadow:0 0 6px #00e676;"></span>':''}</div>
                        ${isMe?'':`<button onclick="window._reelFollow('${emailSafe}',this)" style="background:rgba(255,255,255,0.15);border:1px solid #fff;color:#fff;border-radius:8px;padding:4px 12px;font-size:11px;font-weight:800;cursor:pointer;">Seguir</button>`}
                    </div>
                    ${p.content ? `<div style="font-size:13px;color:#eee;line-height:1.4;">${(p.content||'').replace(/</g,'&lt;')}</div>` : ''}
                    <div style="display:flex;align-items:center;gap:5px;margin-top:6px;color:rgba(255,255,255,0.75);font-size:11.5px;font-weight:700;"><i class='bx bx-play' style="font-size:15px;"></i> ${window._fmtViews(p.views_count)} reproducciones</div>
                </div>`;
            // Progress bar + seek update
            const vid = card.querySelector('video');
            const seek = card.querySelector('#reel-seek-' + p.id);
            const curEl = card.querySelector('#reel-cur-' + p.id);
            const durEl = card.querySelector('#reel-dur-' + p.id);
            const _fmtT = function(s){ s=Math.max(0,Math.floor(s||0)); var m=Math.floor(s/60); var ss=s%60; return m+':'+(ss<10?'0':'')+ss; };
            if (vid) {
                vid.addEventListener('play', function(){ window._registerPostView && window._registerPostView(p.id); }, { once: true });
                vid.addEventListener('loadedmetadata', function(){ if(durEl) durEl.textContent = _fmtT(vid.duration); });
                let _lastT = 0;
                vid.addEventListener('timeupdate', function() {
                    if (vid.duration && !window._reelSeeking) {
                        if (seek) seek.value = (vid.currentTime / vid.duration) * 1000;
                    }
                    if (curEl) curEl.textContent = _fmtT(vid.currentTime);
                    if (durEl && vid.duration && durEl.textContent === '0:00') durEl.textContent = _fmtT(vid.duration);
                    // Detección de loop: el video volvió al inicio → cuenta otra reproducción
                    if (vid.currentTime < _lastT - 1) { window._registerPostView && window._registerPostView(p.id); }
                    _lastT = vid.currentTime;
                });
                // Ocultar el cartel "tocá para sonido" en cuanto el video tiene sonido
                const _hideHint = function(){ const h = card.querySelector('.reel-sound-hint'); if (h && !vid.muted) h.style.display = 'none'; };
                vid.addEventListener('volumechange', _hideHint);
                vid.addEventListener('play', function(){ if(!vid.muted) _hideHint(); });
            }
            sc.appendChild(card);
        });
        // reproducir el primero
        setTimeout(() => { const v = sc.querySelector('video'); if (v) v.play().catch(()=>{}); }, 100);
    } catch(e) { st.done = true; }
    st.loading = false;
};

// Anti-skip: bloquear scroll de reels por 600ms para no saltar varios
(function() {
    var _reelLocked = false;
    function _lockReelScroll(sc) {
        // Desactivado: el scroll-snap ya maneja el paso de a un reel.
        // El bloqueo de overflow trababa el scroll entre reels.
        return;
    }
    var _origObserver = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) {
            m.addedNodes.forEach(function(n) {
                if (n.id === 'reels-scroll' || (n.querySelector && n.querySelector('#reels-scroll'))) {
                    var sc = n.id === 'reels-scroll' ? n : n.querySelector('#reels-scroll');
                    if (!sc) return;
                    sc.addEventListener('touchstart', function(e) { window._reelTouchY = e.touches[0].clientY; }, { passive: true });
                    sc.addEventListener('touchend', function(e) {
                        var dy = e.changedTouches[0].clientY - (window._reelTouchY || 0);
                        // Solo re-evaluar play/pausa cuando hubo SCROLL real (dy grande). Antes
                        // corría también en un TAP → re-reproducía el video y deshacía la pausa
                        // manual del usuario (P6.2). Un tap (dy≈0) NO debe tocar el estado.
                        if (Math.abs(dy) > 24) {
                            _lockReelScroll(sc);
                            setTimeout(function() {
                                sc.querySelectorAll('video').forEach(function(v) {
                                    var r = v.getBoundingClientRect();
                                    var visible = r.top >= 0 && r.top < window.innerHeight * 0.7;
                                    // Scroll limpia la pausa manual y reproduce el visible.
                                    if (visible) { v.dataset.userpaused=''; v.play().catch(function(){}); } else { v.pause(); }
                                });
                            }, 700);
                        }
                    }, { passive: true });
                }
            });
        });
    });
    _origObserver.observe(document.body, { childList: true, subtree: true });
})();

// ── Tabs deslizables del feed: Publicaciones <-> Reels ─────
window._feedView = 'publicaciones';
window.switchFeedView = function(view) {
    window._feedView = view;
    const pub = document.getElementById('main-feed-container');
    const reels = document.getElementById('feed-reels-panel');
    const ind = document.getElementById('feed-seg-indicator');
    const tabP = document.getElementById('feedtab-publicaciones');
    const tabR = document.getElementById('feedtab-reels');
    if (!pub || !reels) return;
    if (view === 'reels') {
        // Reels en PANTALLA COMPLETA (estilo TikTok), no inline
        if (ind) { ind.style.transition='left .2s ease'; ind.style.left = '50%'; }
        if (tabP) tabP.style.color = '#666';
        if (tabR) tabR.style.color = 'var(--accent)';
        if (window.openReels) window.openReels();
        // Volver visualmente a Publicaciones debajo (el reel queda en overlay)
        setTimeout(function(){ window._feedView = 'publicaciones'; if (ind) { ind.style.transition='left .2s ease'; ind.style.left='0'; } if (tabP) tabP.style.color='var(--accent)'; if (tabR) tabR.style.color='#666'; }, 400);
        pub.style.display = '';
        reels.style.display = 'none';
    } else {
        pub.style.display = '';
        reels.style.display = 'none';
        if (ind) { ind.style.transition='left .2s ease'; ind.style.left = '0'; }
        if (tabP) tabP.style.color = 'var(--accent)';
        if (tabR) tabR.style.color = '#666';
    }
};

// Carga reels en el panel inline (scroll vertical tipo TikTok dentro del feed)
window._feedReelsState = { offset: 0, loading: false, done: false };
window._loadFeedReels = async function(more) {
    const panel = document.getElementById('feed-reels-panel');
    if (!panel) return;
    const st = window._feedReelsState;
    if (!more) {
        st.offset = 0; st.done = false;
        panel.innerHTML = `<div id="feed-reels-scroll" style="height:calc(100vh - 230px);overflow-y:scroll;scroll-snap-type:y mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none;border-radius:14px;background:#000;"></div>`;
        const sc = document.getElementById('feed-reels-scroll');
        if (sc) sc.addEventListener('scroll', function() {
            if (sc.scrollTop + sc.clientHeight * 2.5 >= sc.scrollHeight) window._loadFeedReels(true);
            sc.querySelectorAll('video').forEach(v => {
                const r = v.getBoundingClientRect(); const mid = r.top < window.innerHeight/2 && r.bottom > window.innerHeight/2;
                // Respetar la pausa manual del usuario (P6.2): no auto-reproducir el que pausó.
                if (mid) { if (v.dataset.userpaused !== '1') v.play().catch(()=>{}); } else { v.pause(); v.dataset.userpaused=''; }
            });
        }, { passive: true });
    }
    if (st.loading || st.done) return;
    st.loading = true;
    const sc = document.getElementById('feed-reels-scroll');
    const sb = window._sb;
    if (!sb || !sc) { st.loading = false; return; }
    try {
        // TODOS los videos = reels (sin filtro is_reel). Excluir reposts (parent_post_id no nulo).
        let { data } = await sb.from('posts').select('*').eq('media_type','video').is('parent_post_id', null).order('created_at',{ascending:false}).range(st.offset, st.offset+4);
        // Filtrar reposts en memoria (los reels compartidos tienen repost_of)
        if (data) data = data.filter(p => !p.repost_of && !p.original_user_email);
        if (!data || !data.length) {
            st.done = true;
            if (st.offset === 0) sc.innerHTML = '<div style="height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#666;gap:12px;padding:20px;text-align:center;"><i class="bx bx-movie-play" style="font-size:54px;opacity:0.3;"></i><div style="font-size:15px;font-weight:700;">Todavía no hay Reels</div><div style="font-size:12px;">Subí el primero con el ícono 🎬 del composer</div></div>';
            st.loading = false; return;
        }
        st.offset += data.length;
        data.forEach(p => {
            const card = document.createElement('div');
            card.setAttribute('data-reel-card','1');
            card.style.cssText = 'height:100vh;height:100dvh;min-height:100vh;width:100%;scroll-snap-align:start;scroll-snap-stop:always;position:relative;display:flex;align-items:center;justify-content:center;background:#000;';
            const init = (p.user_name||'?')[0].toUpperCase();
            card.innerHTML = `<video src="${p.media_url}" loop playsinline muted preload="auto" style="width:100%;height:100%;object-fit:contain;cursor:pointer;" onclick="window._reelTogglePause(this)"></video>
                <div class="reel-pause-icon" style="display:none;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:60px;height:60px;border-radius:50%;background:rgba(0,0,0,0.55);align-items:center;justify-content:center;pointer-events:none;"><i class='bx bx-pause' style="font-size:32px;color:#fff;"></i></div>
                <div style="position:absolute;left:0;right:0;bottom:0;padding:16px;background:linear-gradient(0deg,rgba(0,0,0,0.8),transparent);">
                    <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;"><div style="width:36px;height:36px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;">${init}</div><div style="font-weight:800;font-size:14px;color:#fff;">${p.user_name||'Jugador'}</div></div>
                    ${p.content?`<div style="font-size:13px;color:#eee;">${(p.content||'').replace(/</g,'&lt;')}</div>`:''}
                </div>`;
            sc.appendChild(card);
        });
        setTimeout(()=>{ const v = sc.querySelector('video'); if (v) v.play().catch(()=>{}); }, 100);
    } catch(e) { st.done = true; }
    st.loading = false;
};

// Gesto de swipe horizontal para cambiar entre Publicaciones y Reels
window._bindFeedSwipe = function() {
    const wrap = document.getElementById('feed-swipe-wrap');
    if (!wrap || wrap._swipeBound) return;
    wrap._swipeBound = true;
    let sx = 0, sy = 0, tracking = false;
    wrap.addEventListener('touchstart', e => { sx = e.touches[0].clientX; sy = e.touches[0].clientY; tracking = true; }, { passive: true });
    wrap.addEventListener('touchend', e => {
        if (!tracking) return; tracking = false;
        const dx = e.changedTouches[0].clientX - sx;
        const dy = e.changedTouches[0].clientY - sy;
        if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) {
            // A Reels SOLO se entra por el botón. Deslizar a la derecha vuelve a Publicaciones.
            if (dx > 0 && window._feedView !== 'publicaciones') window.switchFeedView('publicaciones');
        }
    }, { passive: true });
};

window.previewFeedMedia = function(input) {
    const preview = document.getElementById('feed-post-preview') || document.getElementById('feed-media-preview');
    const toggle = document.getElementById('feed-format-toggle');
    if (!preview) return;
    const files = Array.from(input.files || []);
    if (!files.length) { preview.style.display = 'none'; preview.innerHTML = ''; if (toggle) toggle.style.display = 'none'; return; }
    if (files.length > 10) { showToast && showToast('Máximo 10 elementos por publicación.', 'warning'); }
    const shown = files.slice(0, 10);
    // Si es un Reel, previsualizar en VERTICAL (9:16) grande, como Instagram
    if (window._isReelPost && shown.length && shown[0].type.startsWith('video/')) {
        const url = URL.createObjectURL(shown[0]);
        preview.innerHTML = `<div style="display:flex;flex-direction:column;align-items:center;gap:8px;">
            <div style="font-size:11px;color:var(--accent);font-weight:800;letter-spacing:1px;"><i class='bx bx-movie-play'></i> VISTA PREVIA DEL REEL</div>
            <video src="${url}" controls playsinline style="width:200px;aspect-ratio:9/16;object-fit:cover;border-radius:14px;border:2px solid var(--accent);background:#000;"></video>
            <div style="font-size:10px;color:#888;">Así se verá vertical. Publicá para subirlo a Reels.</div>
        </div>`;
        preview.style.display = 'block';
        if (toggle) toggle.style.display = 'none';
        return;
    }
    preview.innerHTML = `<div style="display:flex;gap:6px;overflow-x:auto;padding:2px;scrollbar-width:none;">${shown.map(file => {
        const url = URL.createObjectURL(file);
        return file.type.startsWith('video/')
            ? `<video src="${url}" style="width:84px;height:84px;object-fit:cover;border-radius:8px;flex-shrink:0;border:1px solid #2a2a2a;"></video>`
            : `<img src="${url}" style="width:84px;height:84px;object-fit:cover;border-radius:8px;flex-shrink:0;border:1px solid #2a2a2a;">`;
    }).join('')}</div>${files.length>1?`<div style="font-size:10px;color:#888;margin-top:4px;">🎠 Carrusel de ${shown.length} elementos</div>`:''}`;
    preview.style.display = 'block';
    if (toggle) toggle.style.display = 'flex';
};

// ── HILO en el feed composer ──────────────────────────────────
window._feedHiloItems = []; // textos adicionales del hilo

window._toggleFeedHilo = function() {
    const panel = document.getElementById('feed-hilo-panel');
    const btn = document.getElementById('feed-hilo-btn');
    if (!panel) return;
    const visible = panel.style.display !== 'none';
    panel.style.display = visible ? 'none' : 'block';
    if (btn) btn.style.color = visible ? 'var(--text-muted)' : 'var(--accent)';
    if (!visible && window._feedHiloItems.length === 0) window._addHiloItem();
};

