// ── SWIPE ANIMADO en los tabs Publicaciones/Reels ─────────────
window._initFeedTabSwipe = function() {
    const wrap = document.getElementById('feed-swipe-wrap');
    const indicator = document.getElementById('feed-seg-indicator');
    const tabP = document.getElementById('feedtab-publicaciones');
    const tabR = document.getElementById('feedtab-reels');
    if (!wrap || !indicator || window._feedTabSwipeBound) return;
    window._feedTabSwipeBound = true;

    var sx=0, sy=0, tracking=false, moved=false;
    const W = () => wrap.offsetWidth || window.innerWidth;

    wrap.addEventListener('touchstart', function(e) {
        if (e.target.closest('button,a,input,textarea,select,video')) return;
        // Dentro de un carrusel de fotos el gesto horizontal es del carrusel,
        // NO del cambio a Reels (causaba que pasar de foto te lleve a Reels)
        if (e.target.closest('[id^="carousel-"],[style*="scroll-snap-type"],[style*="overflow-x"]')) return;
        sx = e.touches[0].clientX; sy = e.touches[0].clientY;
        tracking = true; moved = false;
    }, { passive: true });

    wrap.addEventListener('touchmove', function(e) {
        if (!tracking) return;
        const dx = e.touches[0].clientX - sx;
        const dy = e.touches[0].clientY - sy;
        if (!moved && Math.abs(dy) > Math.abs(dx)) { tracking = false; return; }
        if (!moved && Math.abs(dx) < 8) return;
        moved = true;
        // A Reels solo se entra por el botón → no animar la transición por swipe.
    }, { passive: true });

    wrap.addEventListener('touchend', function(e) {
        if (!tracking || !moved) { tracking = false; return; }
        tracking = false;
        const dx = e.changedTouches[0].clientX - sx;
        const dy = e.changedTouches[0].clientY - sy;
        if (Math.abs(dx) < 60 || Math.abs(dx) < Math.abs(dy) * 1.5) {
            // Snap back
            indicator.style.transition = 'left .2s ease';
            indicator.style.left = '0';
            if (tabP) tabP.style.color = 'var(--accent)';
            if (tabR) tabR.style.color = '#666';
            return;
        }
        if (false) {
        } else {
            // A Reels solo se entra por el botón → siempre snap back
            indicator.style.transition = 'left .2s ease';
            indicator.style.left = '0';
            if (tabP) tabP.style.color = 'var(--accent)';
            if (tabR) tabR.style.color = '#666';
        }
    }, { passive: true });
};

window.createFeedPost = async function() {
    const sb = _sb || window._sb;
    const text = document.getElementById('feed-post-text')?.value?.trim();
    const fileInput = document.getElementById('feed-post-media');
    if (!text && (!fileInput || !fileInput.files[0])) { showToast('Escribí algo o subí una imagen/video.', 'warning'); return; }
    if (!sb) { showToast('Iniciá sesión primero.', 'error'); return; }
    if (!userData) { showToast('Iniciá sesión para publicar.', 'error'); return; }

    const btn = document.querySelector('#jugador-feed .btn-post, .feed-composer .btn-post, #main-feed-container ~ * .btn-post, [onclick="createFeedPost()"]');
    const allPostBtns = document.querySelectorAll('[onclick="createFeedPost()"]');
    allPostBtns.forEach(b => { b.disabled = true; b.innerHTML = '<i class="bx bx-loader-alt bx-spin"></i>'; });

    // Subir TODOS los archivos elegidos (carrusel). Fallback a base64 si el storage falla.
    const sbU = sb;
    const files = Array.from(fileInput?.files || []).slice(0, 10);
    const mediaArr = [];
    for (const file of files) {
        const type = file.type.startsWith('video') ? 'video' : 'image';
        let url = null;
        try {
            const ext = (file.name.split('.').pop() || 'jpg').replace(/[^a-z0-9]/gi,'');
            const path = `posts/${Date.now()}_${Math.random().toString(36).slice(2,7)}.${ext}`;
            const { error: upErr } = await sbU.storage.from('media').upload(path, file, { upsert: true, contentType: file.type });
            if (upErr) throw upErr;
            url = sbU.storage.from('media').getPublicUrl(path).data?.publicUrl;
        } catch(e) {
            if (file.size <= 3*1024*1024) { try { url = await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);}); } catch(_){} }
        }
        if (url) mediaArr.push({ url, type });
    }
    const mediaUrl = mediaArr.length ? mediaArr[0].url : null;
    const mediaFit = window._feedPostFit || 'horizontal';

    const shouldPin = document.getElementById('feed-pin-post')?.checked || false;
    const expiresAt = shouldPin ? null : new Date(Date.now() + 12 * 60 * 60 * 1000).toISOString();
    const _pubBizIdF = (window._pubBizId && window._pubBizId()) || null;
    const basePost = {
        user_email: userData?.email,
        user_name: userData?.name,
        user_avatar: userData?.photo || null,
        user_role: (window._pubRole && window._pubRole()) || userData?.role || 'jugador',
        content: text || null,
        media_url: mediaUrl,
        media_type: mediaArr.length ? mediaArr[0].type : 'text',
        likes_count: 0,
        pinned: shouldPin,
        pinned_at: shouldPin ? new Date().toISOString() : null,
        expires_at: expiresAt,
    };
    if (_pubBizIdF) basePost.business_id = _pubBizIdF;
    // Reel: video vertical para el feed de reels
    const isReel = !!window._isReelPost;
    if (isReel) basePost.is_reel = true;
    // Si es respuesta a un hilo, agregar referencias
    const replyTo = window._replyingToPost || null;
    const threadPost = replyTo ? { ...basePost, parent_post_id: replyTo.id, thread_root_id: replyTo.root || replyTo.id } : basePost;
    // Intentar con carrusel/formato/hilo; si las columnas no existen, reintentar sin ellas
    let { error } = await sb.from('posts').insert({ ...threadPost, media_urls: mediaArr.length>1 ? JSON.stringify(mediaArr) : null, media_fit: mediaFit });
    if (error) { ({ error } = await sb.from('posts').insert(threadPost)); }
    if (error && isReel) { delete basePost.is_reel; delete threadPost.is_reel; ({ error } = await sb.from('posts').insert(threadPost)); }
    // Si falla por la columna business_id (aún no migrada), quitarla y reintentar.
    if (error && error.message && error.message.includes('business_id')) {
        delete basePost.business_id; delete threadPost.business_id;
        ({ error } = await sb.from('posts').insert(threadPost));
    }
    if (error) { ({ error } = await sb.from('posts').insert(basePost)); } // último fallback sin hilo
    window._isReelPost = false;
    // Incrementar reply_count del post padre
    if (!error && replyTo) {
        try {
            const { data: pp } = await sb.from('posts').select('reply_count').eq('id', replyTo.id).single();
            if (pp) await sb.from('posts').update({ reply_count: (pp.reply_count||0) + 1 }).eq('id', replyTo.id);
        } catch(e){}
        // Notificar al autor del post original
        try {
            const { data: op } = await sb.from('posts').select('user_email,user_name').eq('id', replyTo.id).single();
            if (op && op.user_email !== userData.email && typeof notif !== 'undefined') {
                notif.create(op.user_email, 'comment', userData.name || 'Alguien', '🧵 ' + (userData.name||'Alguien') + ' respondió a tu publicación en un hilo.', replyTo.id);
            }
        } catch(e){}
    }
    window._replyingToPost = null; // limpiar estado de respuesta

    allPostBtns.forEach(b => { b.disabled = false; b.innerHTML = 'PUBLICAR'; });

    if (error) { showToast('Error al publicar: ' + error.message, 'error'); return; }

    showToast(shouldPin ? '📌 Publicación fijada en tu perfil.' : '¡Publicación creada! Dura 12 horas.', 'success');

    // Publicar partes del hilo encadenadas
    const hiloItems = (window._feedHiloItems || []).filter(t => t.trim());
    if (hiloItems.length) {
        // Obtener el ID del post recién creado
        try {
            const { data: newPost } = await sb.from('posts').select('id').eq('user_email', userData.email).order('created_at', { ascending: false }).limit(1).single();
            if (newPost) {
                const rootId = newPost.id;
                for (const hiloText of hiloItems) {
                    const hp = { user_email: userData.email, user_name: userData.name, user_avatar: userData.photo||null, user_role: userData.role||'jugador', content: hiloText, media_type: 'text', likes_count: 0, parent_post_id: rootId, thread_root_id: rootId };
                    await sb.from('posts').insert(hp).catch(() => {});
                }
                await sb.from('posts').update({ reply_count: hiloItems.length }).eq('id', rootId).catch(() => {});
            }
        } catch(e) {}
        window._feedHiloItems = [];
        const hiloPanel = document.getElementById('feed-hilo-panel');
        if (hiloPanel) { hiloPanel.style.display = 'none'; const c = document.getElementById('feed-hilo-items'); if (c) c.innerHTML = ''; }
        const hiloBtn = document.getElementById('feed-hilo-btn');
        if (hiloBtn) hiloBtn.style.color = 'var(--text-muted)';
    }

    const ta = document.getElementById('feed-post-text');
    if (ta) ta.value = '';
    if (fileInput) fileInput.value = '';
    const preview = document.getElementById('feed-post-preview');
    if (preview) { preview.style.display = 'none'; preview.innerHTML = ''; }
    const pinCb = document.getElementById('feed-pin-post'); if (pinCb) pinCb.checked = false;
    const pinHint = document.getElementById('feed-pin-hint'); if (pinHint) pinHint.style.display = 'none';
    loadMainFeed();
    try { loadProfilePosts(); } catch(e) {}
    // También recargar feed del panel social si está visible
    try { if (typeof loadFeed === 'function') { loadFeed('amigos-feed'); loadFeed('jugador-profile-feed-posts'); } } catch(e) {}
};

