// PREDICCIONES (apuestas casino) — todos los partidos próximos en una lista única
window._allPredMatches = [];
window.loadPredicciones = async function() {
    const list = document.getElementById('mc-pred-list');
    if (!list) return;
    list.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div>';
    const sb = window._sb;
    if (!sb) { list.innerHTML = '<div style="padding:30px;color:#555;text-align:center;">Sin conexión.</div>'; return; }
    try {
        const { data: upcoming } = await sb.from('matches').select('*').gte('scheduled_at', new Date().toISOString()).order('scheduled_at',{ascending:true}).limit(50);
        // Solo partidos realmente próximos: excluir finalizados (no tiene sentido predecir un partido jugado)
        window._allPredMatches = (upcoming || []).filter(m => !['finished','finalizado','terminado'].includes((m.status||'').toLowerCase()));
        // Poblar dropdown de ciudades
        const citySelect = document.getElementById('pred-filter-ciudad');
        if (citySelect) {
            const cities = [...new Set((upcoming||[]).map(m=>m.city||m.venue_city).filter(Boolean))];
            citySelect.innerHTML = '<option value="">Todas las ciudades</option>' + cities.map(c=>`<option value="${c}">${c}</option>`).join('');
        }
        window._renderPredList(window._allPredMatches);
    } catch(e) { list.innerHTML = '<div style="padding:20px;color:#f44;text-align:center;">Error: ' + e.message + '</div>'; }
};

window._renderPredList = function(matches) {
    const list = document.getElementById('mc-pred-list');
    if (!list) return;
    if (!matches || !matches.length) {
        list.innerHTML = `<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;">
            <i class='bx bx-dice-5' style="font-size:42px;display:block;margin-bottom:10px;color:var(--accent);opacity:.4;"></i>
            <div style="font-size:14px;font-weight:700;margin-bottom:4px;">Sin partidos encontrados</div>
            <div style="font-size:12px;color:#888;">Intentá otro filtro.</div>
        </div>`; return;
    }
    list.innerHTML = matches.map(m => buildPredictionCard(m, (m.match_type==='tournament'||m.is_tournament)?'torneos':'amistosos')).join('');
};

window._filterPredicciones = function() {
    const q = (document.getElementById('pred-search')?.value||'').toLowerCase().trim();
    const ciudad = document.getElementById('pred-filter-ciudad')?.value||'';
    let matches = window._allPredMatches || [];
    if (q) matches = matches.filter(m => (m.name||'').toLowerCase().includes(q) || (m.venue||'').toLowerCase().includes(q));
    if (ciudad) matches = matches.filter(m => (m.city||m.venue_city||'') === ciudad);
    window._renderPredList(matches);
};

// RESEÑAS (Letterboxd-style)
window._resenaTab = 'proximos';
window.switchResena = function(tab, btn) {
    window._resenaTab = tab;
    document.querySelectorAll('.mc-resena-tab').forEach(b => {
        b.style.background = 'transparent'; b.style.color = '#888'; b.style.borderColor = '#222';
    });
    if (btn) { btn.style.background = 'rgba(186,255,0,0.12)'; btn.style.color = 'var(--accent)'; btn.style.borderColor = 'rgba(186,255,0,0.3)'; }
    window.loadResenas(tab);
};

window.loadResenas = async function(tab) {
    const list = document.getElementById('mc-resenas-list');
    if (!list) return;
    list.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div>';
    const sb = window._sb;
    if (!sb) { list.innerHTML = '<div style="padding:30px;color:#555;text-align:center;">Sin conexión.</div>'; return; }
    try {
        const now = new Date().toISOString();
        let matches = [];
        const _isFin = (m) => ['finished','finalizado','terminado'].includes((m.status||'').toLowerCase()) || (m.scheduled_at && new Date(m.scheduled_at) < new Date());
        if (tab === 'proximos') {
            const { data } = await sb.from('matches').select('*').gte('scheduled_at', now).order('scheduled_at',{ascending:true}).limit(40);
            // Próximo = fecha futura Y no finalizado (mutuamente excluyente con Finalizados)
            matches = (data || []).filter(m => !_isFin(m));
        } else if (tab === 'finalizados') {
            const { data } = await sb.from('matches').select('*').order('scheduled_at',{ascending:false}).limit(80);
            matches = (data || []).filter(_isFin);
        } else if (tab === 'mejores') {
            // Ranking de partidos por rating promedio
            const { data: reviews } = await sb.from('match_reviews').select('match_id,rating').limit(500);
            const agg = {};
            (reviews||[]).forEach(r => { (agg[r.match_id]=agg[r.match_id]||{tot:0,n:0}); agg[r.match_id].tot += (r.rating||0); agg[r.match_id].n += 1; });
            const top = Object.entries(agg).map(([id,a]) => ({ id, avg: a.tot/a.n, n: a.n })).sort((a,b)=>b.avg-a.avg).slice(0,20);
            if (top.length){
                const ids = top.map(t=>t.id);
                const { data: mm } = await sb.from('matches').select('*').in('id', ids);
                const byId = {}; (mm||[]).forEach(m=>byId[m.id]=m);
                matches = top.map(t => ({ ...byId[t.id], _avg: t.avg, _n: t.n })).filter(m=>m.id);
            }
        } else if (tab === 'mis') {
            const me = window.userData;
            if (!me) { list.innerHTML = '<div style="padding:30px;color:#555;text-align:center;">Iniciá sesión para ver tus reseñas.</div>'; return; }
            const { data: mine } = await sb.from('match_reviews').select('match_id,rating,comment,created_at').eq('user_email', me.email).order('created_at',{ascending:false}).limit(30);
            if (!mine || !mine.length) { list.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;"><i class="bx bxs-star" style="font-size:42px;color:#333;display:block;margin-bottom:8px;"></i>Aún no escribiste reseñas.</div>'; return; }
            const ids = mine.map(r=>r.match_id);
            const { data: mm } = await sb.from('matches').select('*').in('id', ids);
            const byId = {}; (mm||[]).forEach(m=>byId[m.id]=m);
            list.innerHTML = mine.map(r => {
                const m = byId[r.match_id] || {};
                const stars = '★★★★★'.slice(0, r.rating||0) + '☆☆☆☆☆'.slice(0, Math.max(0,5-(r.rating||0)));
                return `<div onclick="window.openMatchReview('${r.match_id}')" style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:14px;margin-bottom:10px;cursor:pointer;">
                    <div style="font-size:13px;font-weight:800;margin-bottom:4px;">${m.name||'Partido'}</div>
                    <div style="font-size:14px;color:#FFD700;letter-spacing:2px;margin-bottom:4px;">${stars}</div>
                    ${r.comment?`<div style="font-size:12px;color:#bbb;margin-top:4px;">${(r.comment||'').replace(/</g,'&lt;')}</div>`:''}
                    <div style="font-size:10px;color:#555;margin-top:6px;">${new Date(r.created_at).toLocaleDateString('es-UY')}</div>
                </div>`;
            }).join('');
            return;
        }
        if (!matches.length){ list.innerHTML = '<div style="text-align:center;padding:40px;color:#555;">Sin resultados.</div>'; return; }
        list.innerHTML = matches.map(m => buildMatchReviewCard(m)).join('');
    } catch(e) { list.innerHTML = '<div style="padding:20px;color:#f44;text-align:center;font-size:12px;">Error: ' + (e.message||'') + '</div>'; }
};

// Card de reseña estilo Letterboxd (escudos + estrellas + acción "Reseñar")
function buildMatchReviewCard(m) {
    const home = m.home_club_name || 'LOCAL';
    const away = m.away_club_name || 'VISITANTE';
    const homeLogo = m.home_club_logo, awayLogo = m.away_club_logo;
    const dt = m.scheduled_at ? new Date(m.scheduled_at).toLocaleDateString('es-UY',{day:'2-digit',month:'short',year:'2-digit'}) : '';
    const sh = (logo, name, color) => logo
        ? `<div style="width:48px;height:48px;border-radius:50%;background:#000 center/cover url('${logo}');border:2px solid ${color};"></div>`
        : `<div style="width:48px;height:48px;border-radius:50%;background:#0a0a0a;border:2px solid ${color};display:flex;align-items:center;justify-content:center;font-weight:900;color:${color};">${(name[0]||'?').toUpperCase()}</div>`;
    const avg = m._avg ? '<span style="color:#FFD700;font-weight:900;">★ ' + m._avg.toFixed(1) + '</span> <span style="color:#555;font-size:10px;">('+m._n+' reseñas)</span>' : '';
    const score = (m.home_score!=null && m.away_score!=null) ? `<div style="font-size:18px;font-weight:900;color:#fff;letter-spacing:2px;">${m.home_score} - ${m.away_score}</div><div style="font-size:9px;color:#888;font-weight:700;">FINAL</div>` : `<div style="font-size:12px;color:var(--accent);font-weight:900;">VS</div><div style="font-size:9px;color:#888;">${dt}</div>`;
    return `<div onclick="window.openMatchReview('${m.id}')" style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:14px;margin-bottom:10px;cursor:pointer;transition:.15s;" onmouseover="this.style.borderColor='rgba(186,255,0,0.3)'" onmouseout="this.style.borderColor='#1e1e1e'">
        <div style="display:flex;align-items:center;gap:10px;">
            <div style="flex:1;text-align:center;">${sh(homeLogo,home,'var(--accent)')}<div style="font-size:11px;font-weight:800;margin-top:4px;color:#fff;">${home}</div></div>
            <div style="text-align:center;flex-shrink:0;padding:0 6px;">${score}</div>
            <div style="flex:1;text-align:center;">${sh(awayLogo,away,'#9c88ff')}<div style="font-size:11px;font-weight:800;margin-top:4px;color:#fff;">${away}</div></div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding-top:10px;border-top:1px solid #1a1a1a;">
            <div>${avg}</div>
            <div style="font-size:11px;color:var(--accent);font-weight:700;"><i class='bx bxs-star'></i> Reseñar</div>
        </div>
    </div>`;
}

// Modal para escribir una reseña con estrellas + comentario (Letterboxd-style)
window.openMatchReview = async function(matchId) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb) return;
    const { data: m } = await sb.from('matches').select('*').eq('id', matchId).single();
    if (!m) { showToast && showToast('Partido no disponible.', 'warning'); return; }
    // Obtener reseñas existentes
    let reviews = [];
    try { const { data } = await sb.from('match_reviews').select('*').eq('match_id', matchId).order('created_at',{ascending:false}); reviews = data || []; } catch(e){}
    const myReview = me ? reviews.find(r => r.user_email === me.email) : null;
    let modal = document.getElementById('match-review-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'match-review-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:10600;background:rgba(0,0,0,0.92);display:flex;align-items:center;justify-content:center;padding:16px;overflow-y:auto;';
    const home = m.home_club_name||'LOCAL'; const away = m.away_club_name||'VISITANTE';
    const myRating = myReview?.rating || 0;
    modal.innerHTML = `
      <div style="background:#0d0d0d;border:1px solid #222;border-radius:20px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto;padding:18px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">
            <div style="font-weight:900;font-size:15px;">Reseña del partido</div>
            <button onclick="document.getElementById('match-review-modal').remove()" style="background:none;border:none;color:#888;font-size:22px;cursor:pointer;">&times;</button>
        </div>
        <div style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:14px;margin-bottom:14px;text-align:center;">
            <div style="font-size:13px;font-weight:800;margin-bottom:6px;">${home} <span style="color:#666;">vs</span> ${away}</div>
            <div style="font-size:11px;color:#888;">${m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY') : ''}</div>
        </div>
        ${me ? `
        <div style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:14px;margin-bottom:14px;">
            <div style="font-size:11px;color:#888;letter-spacing:.5px;margin-bottom:6px;">${myReview?'TU RESEÑA':'TU CALIFICACIÓN'}</div>
            <div id="mr-stars" style="display:flex;gap:4px;margin-bottom:10px;justify-content:center;font-size:32px;">
                ${[1,2,3,4,5].map(n => `<span data-star="${n}" onclick="window._mrPickStar(${n})" style="cursor:pointer;color:${myRating>=n?'#FFD700':'#333'};">★</span>`).join('')}
            </div>
            <textarea id="mr-comment" rows="3" placeholder="¿Qué te pareció el partido?" style="width:100%;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px 12px;font-size:13px;outline:none;resize:none;box-sizing:border-box;font-family:inherit;">${myReview?.comment||''}</textarea>
            <button onclick="window._submitMatchReview('${matchId}')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:10px;padding:11px;font-weight:900;font-size:13px;cursor:pointer;margin-top:10px;">${myReview?'ACTUALIZAR RESEÑA':'PUBLICAR RESEÑA'}</button>
        </div>` : '<div style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:12px;text-align:center;color:#888;font-size:12px;margin-bottom:14px;">Iniciá sesión para reseñar este partido.</div>'}
        <div style="font-size:11px;color:#888;letter-spacing:.5px;margin-bottom:8px;">${reviews.length} RESEÑA${reviews.length!==1?'S':''}</div>
        <div id="mr-list">${reviews.length ? reviews.map(r => {
            const stars = '★★★★★'.slice(0, r.rating||0) + '☆☆☆☆☆'.slice(0, Math.max(0,5-(r.rating||0)));
            return `<div style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:12px;margin-bottom:8px;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                    <div style="font-size:12px;font-weight:800;">${r.user_name||r.user_email}</div>
                    <div style="color:#FFD700;font-size:13px;letter-spacing:1px;">${stars}</div>
                </div>
                ${r.comment?`<div style="font-size:12px;color:#bbb;margin-top:4px;">${(r.comment||'').replace(/</g,'&lt;')}</div>`:''}
            </div>`;
        }).join('') : '<div style="color:#555;font-size:12px;text-align:center;padding:14px 0;">Aún no hay reseñas. Sé el primero.</div>'}</div>
      </div>`;
    document.body.appendChild(modal);
    window._mrRating = myRating;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
};

window._mrPickStar = function(n) {
    window._mrRating = n;
    document.querySelectorAll('#mr-stars span').forEach(s => {
        const v = parseInt(s.getAttribute('data-star'));
        s.style.color = v <= n ? '#FFD700' : '#333';
    });
};

window._submitMatchReview = async function(matchId) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) { showToast && showToast('Iniciá sesión.', 'warning'); return; }
    const rating = window._mrRating || 0;
    const comment = (document.getElementById('mr-comment')?.value || '').trim();
    if (!rating) { showToast && showToast('Elegí una calificación con estrellas.', 'warning'); return; }
    try {
        await sb.from('match_reviews').upsert({
            match_id: matchId, user_email: me.email, user_name: me.name || me.email,
            rating, comment: comment || null
        }, { onConflict: 'match_id,user_email' });
        showToast && showToast('¡Reseña publicada! ⭐', 'success');
        document.getElementById('match-review-modal')?.remove();
        // Refrescar lista actual
        if (window._mcView === 'resenas') window.loadResenas(window._resenaTab||'proximos');
    } catch(e) { showToast && showToast('Necesitás correr el SQL de match_reviews. Error: ' + e.message, 'error'); }
};

window.loadMatchCenterSection = async function(type) {
    const predList = document.getElementById(`mc-${type}-pred-list`);
    const resList = document.getElementById(`mc-${type}-res-list`);
    if (!_sb) {
        if (predList) predList.innerHTML = '<div style="padding:30px;text-align:center;color:#666;">Iniciá sesión para ver partidos.</div>';
        return;
    }
    const matchType = type === 'torneos' ? 'tournament' : 'friendly';
    const { data: upcoming } = await _sb.from('matches').select('*')
        .eq('match_type', matchType).in('status', ['scheduled','live']).order('scheduled_at').limit(10);
    const { data: results } = await _sb.from('matches').select('*')
        .eq('match_type', matchType).eq('status', 'finished').order('scheduled_at', {ascending:false}).limit(10);

    if (predList) {
        if (!upcoming || upcoming.length === 0) {
            predList.innerHTML = '<div style="padding:30px;text-align:center;color:#666;font-size:13px;"><i class="bx bx-football" style="font-size:32px;display:block;margin-bottom:8px;"></i>No hay partidos próximos en tu región.</div>';
        } else {
            predList.innerHTML = upcoming.map(m => buildPredictionCard(m, type)).join('');
        }
    }
    if (resList) {
        if (!results || results.length === 0) {
            resList.innerHTML = '<div style="padding:30px;text-align:center;color:#666;font-size:13px;">No hay resultados aún.</div>';
        } else {
            resList.innerHTML = results.map(m => buildResultCard(m, type)).join('');
        }
    }
};

// ── Compartir partido como tarjeta linda (en feed/perfil) ──────────────────
window._matchLinkRegex = /(?:https?:\/\/[^\s]*)?(?:#partido\/|[?&]invite=)([a-zA-Z0-9\-]+)/;
window.extractMatchId = function(text) {
    const m = (text || '').match(window._matchLinkRegex);
    return m ? m[1] : null;
};
window.openSharedMatch = function(id) {
    try {
        // Abrir el panel del partido (ficha mv2 con tablero/timeline)
        if (window.viewMatchDetails) window.viewMatchDetails(id);
        else if (window.MatchDashboard && window.MatchDashboard.open) window.MatchDashboard.open(id);
        else { window.switchDashboardTab && window.switchDashboardTab('jugador','mis-partidos',null); }
    } catch(e) {}
};
// Devuelve el HTML del contenido de un post: texto (sin el link) + tarjeta de partido si hay
window.renderPostContent = function(content) {
    if (!content) return '';
    const id = window.extractMatchId(content);
    const esc = (s) => (window.escapeHtml ? window.escapeHtml(s) : String(s));
    if (!id) {
        return `<p style="font-size:13px;line-height:1.55;margin:0 0 12px;word-break:break-word;">${esc(content)}</p>`;
    }
    const clean = content.replace(window._matchLinkRegex, '').trim();
    let html = '';
    if (clean) html += `<p style="font-size:13px;line-height:1.55;margin:0 0 12px;word-break:break-word;">${esc(clean)}</p>`;
    html += `<div class="match-share-card" data-match-id="${id}" onclick="window.openSharedMatch&&window.openSharedMatch('${id}')" style="cursor:pointer;position:relative;overflow:hidden;background:linear-gradient(160deg,#101510 0%,#0b0b0b 55%,#0e120a 100%);border:1px solid rgba(186,255,0,0.18);border-radius:18px;padding:0;margin:10px 0 12px;transition:border-color .2s, box-shadow .2s;box-shadow:0 4px 18px rgba(0,0,0,0.35);" onmouseover="this.style.borderColor='rgba(186,255,0,0.5)';this.style.boxShadow='0 4px 24px rgba(186,255,0,0.08)'" onmouseout="this.style.borderColor='rgba(186,255,0,0.18)';this.style.boxShadow='0 4px 18px rgba(0,0,0,0.35)'">
        <div style="position:absolute;top:-40px;right:-40px;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle,rgba(186,255,0,0.10),transparent 70%);pointer-events:none;"></div>
        <div style="display:flex;align-items:center;justify-content:space-between;padding:11px 14px 9px;border-bottom:1px solid rgba(255,255,255,0.05);">
            <div style="font-size:10px;color:var(--accent);font-weight:900;letter-spacing:2.5px;display:flex;align-items:center;gap:7px;"><span style="width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 8px var(--accent);"></span>PARTIDO</div>
            <i class='bx bx-football' style="color:#2f3a22;font-size:18px;"></i>
        </div>
        <div class="msc-body" style="display:flex;align-items:center;justify-content:center;gap:14px;padding:16px 14px 12px;"><div style="color:#777;font-size:12px;padding:8px 0;"><i class='bx bx-loader-alt bx-spin'></i> Cargando partido…</div></div>
        <div class="msc-info" style="display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:6px;font-size:11px;color:#999;padding:0 14px 12px;"></div>
        <div class="msc-cta" style="display:flex;align-items:stretch;border-radius:0 0 17px 17px;overflow:hidden;">
            <div style="flex:1;display:flex;align-items:center;justify-content:center;gap:6px;font-size:12px;color:#000;background:var(--accent);font-weight:900;letter-spacing:.5px;padding:10px;">VER PARTIDO <i class='bx bx-right-arrow-alt' style="font-size:16px;"></i></div>
        </div>
    </div>`;
    return html;
};
window._hydrateMatchCards = function() {
    const sb = window._sb || window.supabaseClient;
    if (!sb) return;
    const cards = document.querySelectorAll('.match-share-card[data-match-id]:not([data-hydrated])');
    cards.forEach((card) => {
        card.setAttribute('data-hydrated', '1');
        const id = card.getAttribute('data-match-id');
        sb.from('matches').select('*').eq('id', id).single().then((r) => {
            const m = r.data; if (!m) return;
            const aName = m.team_a_name || m.home_club_name || 'Equipo A';
            const bName = m.team_b_name || m.away_club_name || 'Equipo B';
            const aLogo = m.team_a_logo || m.home_club_logo;
            const bLogo = m.team_b_logo || m.away_club_logo;
            const when = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{dateStyle:'short',timeStyle:'short'}) : '';
            const place = m.venue || m.complex_name || m.city || '';
            const shield = (logo, name, acc) => logo
                ? `<div style="width:54px;height:54px;border-radius:50%;background:#000 url('${logo}') center/cover;border:2px solid ${acc?'var(--accent)':'#3a3a3a'};box-shadow:0 0 14px ${acc?'rgba(186,255,0,0.25)':'rgba(0,0,0,0.5)'};margin:0 auto;"></div>`
                : `<div style="width:54px;height:54px;border-radius:50%;background:linear-gradient(145deg,#1d1d1d,#111);border:2px solid ${acc?'var(--accent)':'#3a3a3a'};box-shadow:0 0 14px ${acc?'rgba(186,255,0,0.25)':'rgba(0,0,0,0.5)'};display:flex;align-items:center;justify-content:center;font-weight:900;font-size:19px;color:${acc?'var(--accent)':'#aaa'};margin:0 auto;">${((name[0]||'?')).toUpperCase()}</div>`;
            const body = card.querySelector('.msc-body');
            if (body) body.innerHTML =
                `<div style="text-align:center;flex:1;min-width:0;">${shield(aLogo,aName,true)}<div style="font-size:12px;font-weight:800;margin-top:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#fff;">${aName}</div></div>`+
                `<div style="text-align:center;flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:2px;">${(m.home_score!=null&&m.away_score!=null)?`<span style="font-size:20px;font-weight:900;color:#fff;letter-spacing:1px;">${m.home_score}<span style="color:var(--accent);margin:0 3px;">-</span>${m.away_score}</span>`:`<span style="font-size:10px;font-weight:900;letter-spacing:1px;color:#666;">VS</span>`}<span style="width:26px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--accent),#ff4444);"></span></div>`+
                `<div style="text-align:center;flex:1;min-width:0;">${shield(bLogo,bName,false)}<div style="font-size:12px;font-weight:800;margin-top:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#fff;">${bName}</div></div>`;
            const info = card.querySelector('.msc-info');
            const chip = (ic, txt) => `<span style="display:inline-flex;align-items:center;gap:5px;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.07);border-radius:20px;padding:4px 10px;max-width:100%;"><i class='bx ${ic}' style="color:var(--accent);font-size:13px;flex-shrink:0;"></i><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${txt}</span></span>`;
            if (info) info.innerHTML = [when ? chip('bx-calendar', when) : '', place ? chip('bx-map', place) : ''].filter(Boolean).join('');
            // Botón secundario "SUMARME" — solo en partidos abiertos y futuros
            try {
                const cta = card.querySelector('.msc-cta');
                const _email = window.userData && window.userData.email;
                const stOpen = !['finished','finalizado','terminado','cancelado','cancelled'].includes((m.status||'').toLowerCase());
                const future = m.scheduled_at ? (new Date(m.scheduled_at) - Date.now()) > 20*60000 : true;
                const isMine = _email && (m.created_by === _email || m.creator_email === _email);
                const isPart = (window._myJoinedMatchIds && window._myJoinedMatchIds.has(m.id)) || (window._bpState && window._bpState.myPart && window._bpState.myPart.has(String(m.id)));
                const slotsLeft = (m.slots_total||0) - (m.slots_taken||0);
                const hasRoom = (m.slots_total ? slotsLeft > 0 : true);
                // Partido cerrado: no ofrecer sumarse salvo que esté marcado que faltan jugadores
                const isClosed = (m.modality||m.match_type||'').toLowerCase().includes('cerr') || (m.modality||m.match_type||'').toLowerCase().includes('closed');
                const isOpen2 = m.is_open===true || (m.match_type||'').toLowerCase().includes('open') || (m.modality||'').toLowerCase().includes('abierto');
                const allowJoin = (isOpen2 || (isClosed && m.needs_players===true)) ;
                if (cta && stOpen && future && !isMine && !isPart && hasRoom && allowJoin && !cta.querySelector('.msc-join')) {
                    const b = document.createElement('div');
                    b.className = 'msc-join';
                    b.style.cssText = 'flex:0 0 38%;display:flex;align-items:center;justify-content:center;gap:5px;font-size:12px;color:var(--accent);background:rgba(186,255,0,0.10);border-left:1px solid rgba(186,255,0,0.25);font-weight:900;letter-spacing:.5px;padding:10px;cursor:pointer;';
                    b.innerHTML = "<i class='bx bx-user-plus' style='font-size:15px;'></i> SUMARME";
                    b.onclick = function(ev){ ev.stopPropagation(); (window.joinOpenMatch||window.openSharedMatch)(id); };
                    cta.appendChild(b);
                }
            } catch(e){}
        }).catch(()=>{});
    });
};
// Hidratar tarjetas de partido periódicamente (cuando aparecen en feed/perfil).
// Pausa cuando la app está en segundo plano para no gastar CPU/batería en móvil.
setInterval(function(){ try { if (document.hidden) return; window._hydrateMatchCards && window._hydrateMatchCards(); } catch(e){} }, 2500);

function buildPredictionCard(m, type) {
    const accent = type === 'torneos' ? '#FFD700' : 'var(--accent)';
    const label = type === 'torneos' ? '🏆 TORNEO' : '⚽ AMISTOSO';
    const dt = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{dateStyle:'short',timeStyle:'short'}) : '';
    // Compatibilidad de esquema: team_a_* o home_club_*
    m.team_a_name = m.team_a_name || m.home_club_name || m.team_a_name;
    m.team_b_name = m.team_b_name || m.away_club_name || m.team_b_name;
    m.team_a_logo = m.team_a_logo || m.home_club_logo || null;
    m.team_b_logo = m.team_b_logo || m.away_club_logo || null;
    const aName = m.team_a_name||'Local', bName = m.team_b_name||'Visita';
    // Cuotas simuladas (estética casino) — coherentes por partido usando el id como semilla
    const seed = (m.id||'').split('').reduce((a,c)=>a+c.charCodeAt(0),0);
    const odd1 = (1.5 + (seed%70)/40).toFixed(2);
    const oddX = (2.8 + (seed%50)/50).toFixed(2);
    const odd2 = (1.6 + (seed%60)/40).toFixed(2);
    const logoEl = (logo, name, acc) => logo
        ? `<div style="width:50px;height:50px;border-radius:50%;margin:0 auto 6px;border:2px solid ${acc};background:#000 url('${logo}') center/cover;box-shadow:0 0 14px ${acc}55;"></div>`
        : `<div style="width:50px;height:50px;border-radius:50%;margin:0 auto 6px;border:2px solid ${acc};background:#0a0a0a;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:20px;color:${acc};box-shadow:0 0 14px ${acc}55;">${(name||'?')[0].toUpperCase()}</div>`;
    return `<div style="background:radial-gradient(ellipse at 50% -20%, rgba(186,255,0,0.10), transparent 60%), linear-gradient(160deg,#0c120c,#0a0a0a);border:1px solid #233316;border-radius:18px;padding:0;margin-bottom:16px;position:relative;overflow:hidden;box-shadow:0 0 0 1px rgba(186,255,0,0.04), 0 8px 30px rgba(0,0,0,0.5);" data-match-id="${m.id}">
        <div style="position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,${accent},transparent);"></div>
        <!-- Cabecera tipo casa de apuestas -->
        <div style="display:flex;align-items:center;justify-content:space-between;padding:11px 16px;border-bottom:1px solid #1a2410;background:rgba(186,255,0,0.03);">
            <span style="color:${accent};font-weight:900;font-size:10px;letter-spacing:3px;display:flex;align-items:center;gap:6px;"><i class='bx bx-dice-5'></i> ${label.replace(/[^A-ZÁÉÍÓÚ ]/gi,'').trim()}</span>
            <span style="color:#7a8a6a;font-size:10px;">${dt}</span>
        </div>
        <!-- Enfrentamiento -->
        <div style="display:flex;justify-content:space-around;align-items:center;padding:16px 16px 8px;">
            <div style="text-align:center;flex:1;min-width:0;">${logoEl(m.team_a_logo, aName, accent)}<div style="font-weight:800;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${aName}</div></div>
            <div style="text-align:center;padding:0 6px;">
                <div style="display:flex;gap:6px;align-items:center;">
                    <input type="number" min="0" max="20" placeholder="0" id="pred-a-${m.id}" style="width:44px;height:44px;background:#000;border:2px solid ${accent};color:${accent};text-align:center;border-radius:10px;font-size:20px;font-weight:900;outline:none;">
                    <span style="font-size:18px;font-weight:900;color:#3a4a2a;">:</span>
                    <input type="number" min="0" max="20" placeholder="0" id="pred-b-${m.id}" style="width:44px;height:44px;background:#000;border:2px solid ${accent};color:${accent};text-align:center;border-radius:10px;font-size:20px;font-weight:900;outline:none;">
                </div>
                <div style="font-size:8px;color:#666;margin-top:4px;letter-spacing:1px;">MARCADOR EXACTO</div>
            </div>
            <div style="text-align:center;flex:1;min-width:0;">${logoEl(m.team_b_logo, bName, '#3a4a2a')}<div style="font-weight:800;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${bName}</div></div>
        </div>
        <!-- Cuotas 1 X 2 estilo casino -->
        <div style="display:flex;gap:8px;padding:6px 16px 12px;">
            ${[['1',odd1,'Gana '+aName],['X',oddX,'Empate'],['2',odd2,'Gana '+bName]].map(([k,o,t]) =>
                `<button onclick="window._pickOutcome('${m.id}','${k}',this)" title="${t}" data-odd-btn style="flex:1;background:#0e1609;border:1px solid #2a3a1a;border-radius:12px;padding:10px 4px;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:2px;transition:.15s;">
                    <span style="font-size:11px;font-weight:900;color:#8aa06a;">${k}</span>
                    <span style="font-size:16px;font-weight:900;color:${accent};">${o}</span>
                </button>`).join('')}
        </div>
        <!-- Goleador + MVP -->
        <div style="display:flex;gap:8px;padding:0 16px 10px;">
            <div style="flex:1;"><div style="font-size:9px;color:#555;font-weight:700;letter-spacing:1px;margin-bottom:4px;">⚽ GOLEADOR</div>
            <input id="pred-scorer-${m.id}" type="text" placeholder="Nombre..." style="width:100%;background:#0d0d0d;border:1px solid #2a2a2a;color:#fff;border-radius:8px;padding:7px 10px;font-size:11px;outline:none;box-sizing:border-box;"></div>
            <div style="flex:1;"><div style="font-size:9px;color:#555;font-weight:700;letter-spacing:1px;margin-bottom:4px;">⭐ MVP</div>
            <input id="pred-mvp-${m.id}" type="text" placeholder="Nombre..." style="width:100%;background:#0d0d0d;border:1px solid #2a2a2a;color:#fff;border-radius:8px;padding:7px 10px;font-size:11px;outline:none;box-sizing:border-box;"></div>
        </div>
        <!-- CTA -->
        <div style="padding:0 16px 16px;display:flex;gap:8px;">
            <button class="btn" style="flex:2;height:44px;font-weight:900;letter-spacing:1px;border-radius:12px;background:linear-gradient(180deg,${accent},#9ad400);color:#000;border:none;box-shadow:0 4px 16px rgba(186,255,0,0.3);display:flex;align-items:center;justify-content:center;gap:8px;" onclick="window._submitPredictionCard(this)" data-match-id="${m.id}"><i class='bx bx-coin-stack'></i> PREDECIR</button>
            <button style="flex:1;height:44px;background:rgba(186,255,0,0.06);color:var(--accent);border:1px solid rgba(186,255,0,0.25);border-radius:12px;font-weight:800;font-size:11px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;" onclick="window._challengePrediction('${m.id}','${(m.name||'Partido').replace(/'/g,"\\'")}','${aName}','${bName}')"><i class='bx bx-shield-quarter'></i>APOSTAR</button>
        </div>
    </div>`;
}
window._pickOutcome = function(matchId, k, btn) {
    // Resaltar selección (estética casino) y prellenar marcador sugerido
    const card = btn.closest('[data-match-id]');
    if (card) card.querySelectorAll('[data-odd-btn]').forEach(b => { b.style.background='#0e1609'; b.style.borderColor='#2a3a1a'; });
    btn.style.background = 'rgba(186,255,0,0.15)';
    btn.style.borderColor = 'var(--accent)';
    window._predOutcome = window._predOutcome || {};
    window._predOutcome[matchId] = k;
};

function buildResultCard(m, type) {
    const accent = type === 'torneos' ? '#FFD700' : 'var(--accent)';
    const label = type === 'torneos' ? '🏆 TORNEO' : 'AMISTOSO';
    const dt = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{dateStyle:'short',timeStyle:'short'}) : '';
    return `<div style="background:linear-gradient(135deg,#0a0a0a,#151515);border:1px solid #282828;border-radius:14px;overflow:hidden;margin-bottom:12px;">
        <div style="background:linear-gradient(90deg,rgba(186,255,0,0.07),transparent);padding:12px 16px;border-bottom:1px solid #1a1a1a;display:flex;justify-content:space-between;align-items:center;">
            <span style="font-size:10px;color:${accent};font-weight:800;letter-spacing:2px;">${label}</span>
            <span style="font-size:10px;color:#666;">${dt}${m.complex_name ? ' · ' + m.complex_name : ''}</span>
        </div>
        <div style="padding:16px;">
            <div style="display:flex;justify-content:space-around;align-items:center;">
                <div style="text-align:center;flex:1;"><div style="font-weight:900;font-size:13px;">${m.team_a_name||'Equipo A'}</div></div>
                <div style="text-align:center;padding:0 16px;"><div style="font-size:32px;font-weight:900;color:${accent};letter-spacing:4px;">${m.score_a??'-'} - ${m.score_b??'-'}</div><div style="font-size:10px;color:#555;font-weight:700;letter-spacing:2px;">FINAL</div></div>
                <div style="text-align:center;flex:1;"><div style="font-weight:900;font-size:13px;">${m.team_b_name||'Equipo B'}</div></div>
            </div>
            ${m.mvp ? `<div style="margin-top:12px;text-align:center;font-size:11px;color:#888;">⭐ MVP: <span style="color:${accent};font-weight:700;">${m.mvp}</span></div>` : ''}
        </div>
    </div>`;
}

window._submitPredictionCard = async function(btn) {
    const card = btn.closest('[data-match-id]');
    const matchId = btn.dataset.matchId || card?.dataset.matchId;
    if (!matchId) { if(typeof showToast==='function') showToast('Error: partido no encontrado.','error'); return; }
    if (!userData) { if(typeof showToast==='function') showToast('Iniciá sesión para hacer predicciones.','error'); return; }
    const scoreA = parseInt(document.getElementById(`pred-a-${matchId}`)?.value);
    const scoreB = parseInt(document.getElementById(`pred-b-${matchId}`)?.value);
    if (isNaN(scoreA) || isNaN(scoreB)) { if(typeof showToast==='function') showToast('Ingresá los dos marcadores.','error'); return; }
    const scorer = document.getElementById(`pred-scorer-${matchId}`)?.value.trim() || null;
    const mvp = document.getElementById(`pred-mvp-${matchId}`)?.value.trim() || null;
    const outcome = (window._predOutcome || {})[matchId] || null;
    btn.disabled = true;
    btn.innerHTML = '<i class="bx bx-loader-alt bx-spin"></i>';
    const sb = window._sb;
    const { error } = await sb.from('predictions').upsert({
        user_email: userData.email, user_name: userData.name,
        match_id: matchId, score_a: scoreA, score_b: scoreB,
        scorer_prediction: scorer, mvp_prediction: mvp, outcome_prediction: outcome,
        created_at: new Date().toISOString()
    }, { onConflict: 'user_email,match_id' });
    btn.disabled = false;
    if (error) {
        btn.innerHTML = 'REINTENTAR';
        if(typeof showToast==='function') showToast('Error: '+error.message,'error');
        return;
    }
    btn.innerHTML = '✅ PREDICCIÓN ENVIADA';
    btn.style.background = '#1a4a1a';
    btn.style.color = 'var(--accent)';
    if(typeof showToast==='function') showToast('¡Predicción guardada!','success');
    // Ofrecer compartir en el feed
    setTimeout(() => {
        const shareBtn = document.createElement('button');
        shareBtn.style.cssText = 'width:100%;margin-top:8px;background:rgba(186,255,0,0.06);color:var(--accent);border:1px solid rgba(186,255,0,0.25);border-radius:10px;padding:9px;font-size:11px;font-weight:700;cursor:pointer;';
        shareBtn.innerHTML = '<i class="bx bx-share-alt"></i> Compartir predicción en el feed';
        shareBtn.onclick = async function() {
            shareBtn.disabled = true;
            const card = btn.closest('[data-match-id]');
            const mId = card?.dataset.matchId || matchId;
            const sbS = window._sb;
            if (!sbS || !userData) return;
            try {
                const { data: m } = await sbS.from('matches').select('name,home_club_name,away_club_name,team_a_name,team_b_name').eq('id', mId).maybeSingle();
                const mName = (m?.name) || 'Partido';
                const home = m?.home_club_name || m?.team_a_name || 'Local';
                const away = m?.away_club_name || m?.team_b_name || 'Visitante';
                const text = `🎯 Mi predicción para ${mName}:\n${home} ${scoreA} - ${scoreB} ${away}${scorer ? '\n⚽ Goleador: '+scorer : ''}${mvp ? '\n⭐ MVP: '+mvp : ''}\n#CancheroPrediccion`;
                await sbS.from('posts').insert({ user_email: userData.email, user_name: userData.name, user_avatar: userData.photo||null, user_role: userData.role||'jugador', content: text, media_type: 'text', likes_count: 0, expires_at: new Date(Date.now()+12*3600000).toISOString() });
                shareBtn.innerHTML = '✅ Compartido en el feed';
                shareBtn.disabled = true;
                if(typeof showToast==='function') showToast('Predicción compartida en el feed ✓','success');
                try { loadMainFeed(); } catch(e) {}
            } catch(e) { shareBtn.disabled = false; }
        };
        const ctaDiv = btn.closest('.btn')?.parentElement || btn.parentElement;
        if (ctaDiv) ctaDiv.appendChild(shareBtn);
    }, 300);
};

window._challengePrediction = function(matchId, matchName, homeTeam, awayTeam) {
    if (!userData) { if(typeof showToast==='function') showToast('Iniciá sesión','error'); return; }
    const scoreA = parseInt(document.getElementById(`pred-a-${matchId}`)?.value);
    const scoreB = parseInt(document.getElementById(`pred-b-${matchId}`)?.value);
    if (isNaN(scoreA) || isNaN(scoreB)) { if(typeof showToast==='function') showToast('Primero ingresá tu predicción de marcador','error'); return; }
    const ex = document.getElementById('pred-challenge-modal');
    if (ex) ex.remove();
    const m = document.createElement('div');
    m.id = 'pred-challenge-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:19900;background:rgba(0,0,0,0.88);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    m.innerHTML = `<div style="background:#111;border:1px solid #2a2a2a;border-radius:20px;width:100%;max-width:420px;padding:20px;">
        <div style="font-size:14px;font-weight:900;color:var(--accent);margin-bottom:4px;"><i class='bx bx-trophy'></i> APOSTAR PREDICCIÓN</div>
        <div style="font-size:11px;color:#666;margin-bottom:16px;">Mi predicción: <strong style="color:#fff;">${homeTeam} ${scoreA} - ${scoreB} ${awayTeam}</strong></div>
        <div style="font-size:11px;color:#888;font-weight:700;margin-bottom:8px;">BUSCAR RIVAL</div>
        <div style="display:flex;gap:8px;margin-bottom:10px;">
            <input id="pred-rival-search" type="text" placeholder="Nombre del jugador..." style="flex:1;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:10px;font-size:12px;outline:none;" oninput="window._searchPredRival(this.value)">
        </div>
        <div id="pred-rival-results" style="min-height:60px;margin-bottom:14px;"></div>
        <div style="display:flex;gap:8px;">
            <button onclick="document.getElementById('pred-challenge-modal').remove()" style="flex:1;padding:12px;background:transparent;border:1px solid #333;color:#aaa;border-radius:12px;cursor:pointer;font-weight:700;font-size:12px;">Cancelar</button>
        </div>
    </div>`;
    m.onclick = e => { if(e.target===m) m.remove(); };
    m._matchId = matchId; m._scoreA = scoreA; m._scoreB = scoreB; m._matchName = matchName;
    document.body.appendChild(m);
    window._pendingChallengeData = { matchId, scoreA, scoreB, matchName, homeTeam, awayTeam };
    setTimeout(() => document.getElementById('pred-rival-search')?.focus(), 80);
};

window._searchPredRival = async function(q) {
    const results = document.getElementById('pred-rival-results');
    if (!results) return;
    if (!q || q.length < 2) { results.innerHTML = '<div style="text-align:center;color:#555;font-size:11px;padding:10px;">Ingresá 2+ caracteres</div>'; return; }
    const sb = window._sb;
    if (!sb) return;
    results.innerHTML = '<div style="text-align:center;color:#555;"><i class="bx bx-loader-alt bx-spin"></i></div>';
    try {
        const { data } = await sb.from('users').select('email,name,photo').ilike('name', `%${q}%`).neq('email', userData?.email).limit(5);
        if (!data?.length) { results.innerHTML = '<div style="text-align:center;color:#555;font-size:11px;padding:10px;">Sin resultados</div>'; return; }
        results.innerHTML = data.map(u => {
            const ph = u.photo || u.avatar_url;
            return `<div onclick="window._sendPredChallenge('${u.email}','${(u.name||u.email).replace(/'/g,"\\'")}' )" style="display:flex;align-items:center;gap:10px;padding:8px;border-radius:10px;cursor:pointer;border:1px solid #1e1e1e;margin-bottom:6px;" onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='#1e1e1e'">
                ${ph ? `<img src="${ph}" style="width:32px;height:32px;border-radius:50%;object-fit:cover;">` : `<div style="width:32px;height:32px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;font-size:12px;display:flex;align-items:center;justify-content:center;">${(u.name||'?')[0].toUpperCase()}</div>`}
                <div style="font-size:12px;font-weight:700;">${u.name||u.email}</div>
                <div style="margin-left:auto;font-size:10px;color:var(--accent);font-weight:700;"><i class='bx bx-shield-quarter'></i> DESAFIAR</div>
            </div>`;
        }).join('');
    } catch(e) {}
};

window._sendPredChallenge = async function(rivalEmail, rivalName) {
    const d = window._pendingChallengeData;
    if (!d || !userData) return;
    const sb = window._sb;
    if (!sb) return;
    document.getElementById('pred-challenge-modal')?.remove();
    const msg = `⚽ @${userData.name} te desafía en Canchero!\n🎯 Partido: ${d.matchName}\n🏆 Mi predicción: ${d.homeTeam} ${d.scoreA} - ${d.scoreB} ${d.awayTeam}\n¿Cuál es la tuya? Entrá y apostamolos: https://canchero-app.vercel.app/#jugador`;
    try {
        // Guardar apuesta en DB
        await sb.from('prediction_bets').insert({ match_id: d.matchId, challenger_email: userData.email, challenger_name: userData.name, rival_email: rivalEmail, rival_name: rivalName, challenger_score_a: d.scoreA, challenger_score_b: d.scoreB, status: 'pending', created_at: new Date().toISOString() }).catch(()=>{});
        // Enviar por chat
        if (window.CancheroMessaging) {
            await window.CancheroMessaging.sendMessage(msg, 'text');
        } else if (window._sb) {
            await window._sb.from('messages').insert({ sender_email: userData.email, sender_name: userData.name, recipient_email: rivalEmail, content: msg, read: false });
        }
        // Notificación
        if (window.CancheroNotif && window.CancheroNotif.create) {
            await window.CancheroNotif.create(rivalEmail, 'prediction_bet', userData.name, `🎯 ${userData.name} te desafía en predicciones para ${d.matchName}`);
        } else {
            await sb.from('notifications').insert({ recipient_email: rivalEmail, type: 'prediction_bet', actor_email: userData.email, actor_name: userData.name, message: `🎯 ${userData.name} te desafía en predicciones para ${d.matchName}`, read: false }).catch(()=>{});
        }
        if(typeof showToast==='function') showToast(`⚽ ¡Desafío enviado a ${rivalName}!`,'success');
    } catch(e) { if(typeof showToast==='function') showToast('Error: '+e.message,'error'); }
};

// --- PUNTOS — COMPARTIR ---
window.sharePoints = function() {
    const pts = document.getElementById('player-points')?.innerText || '0';
    const msg = `¡Tengo ${pts} Canchero Coins en Canchero! 🟢⚽ Sumate en canchero-app.vercel.app`;
    if (navigator.share) { navigator.share({ title: 'Mis puntos en Canchero', text: msg }); }
    else { navigator.clipboard?.writeText(msg); alert('Texto copiado al portapapeles.'); }
};

// ═══════════════════════════════════════════════════════════════════
// SISTEMA DE PREDICCIONES: PUNTOS · RACHAS · LOGROS · DUOLINGO
// ═══════════════════════════════════════════════════════════════════

// Dar puntos de predicción y actualizar racha cuando se confirma un resultado
window._awardPredictionPoints = async function(matchId) {
    const sb = window._sb;
    if (!sb || !userData) return;
    try {
        // Obtener resultado real del partido
        const { data: match } = await sb.from('matches').select('score_a,score_b,team_a_name,team_b_name,name').eq('id', matchId).maybeSingle();
        if (!match || match.score_a == null || match.score_b == null) return;

        // Obtener predicciones de todos los usuarios para este partido
        const { data: preds } = await sb.from('predictions').select('*').eq('match_id', matchId);
        if (!preds?.length) return;

        for (const pred of preds) {
            let points = 0;
            let correct = false;

            // Marcador exacto → 3 puntos
            if (pred.score_a === match.score_a && pred.score_b === match.score_b) {
                points = 3;
                correct = true;
            } else if (pred.outcome_prediction) {
                // Solo resultado (1/X/2) → 1 punto
                const realOutcome = match.score_a > match.score_b ? '1' : match.score_a < match.score_b ? '2' : 'X';
                if (pred.outcome_prediction === realOutcome) { points = 1; correct = true; }
            }

            // Actualizar predicción con resultado
            await sb.from('predictions').update({
                is_correct: correct,
                points_awarded: points,
                real_score_a: match.score_a,
                real_score_b: match.score_b
            }).eq('id', pred.id).catch(()=>{});

            if (points > 0) {
                // Sumar puntos al usuario
                await sb.rpc('increment_user_points', { user_email: pred.user_email, amount: points }).catch(async () => {
                    // fallback manual
                    const { data: u } = await sb.from('users').select('prediction_points,prediction_streak,prediction_total,prediction_correct').eq('email', pred.user_email).maybeSingle();
                    const newPts = (u?.prediction_points || 0) + points;
                    const newTotal = (u?.prediction_total || 0) + 1;
                    const newCorrect = (u?.prediction_correct || 0) + (correct ? 1 : 0);
                    const newStreak = correct ? (u?.prediction_streak || 0) + 1 : 0;
                    await sb.from('users').update({
                        prediction_points: newPts,
                        prediction_streak: newStreak,
                        prediction_total: newTotal,
                        prediction_correct: newCorrect
                    }).eq('email', pred.user_email).catch(()=>{});

                    // Verificar logro: 1 correcta cada 20 → partido gratis
                    if (correct && newTotal > 0 && newTotal % 20 === 0) {
                        await window._grantFreeMatchVoucher(pred.user_email, pred.user_name, 'prediccion_racha');
                    }
                });
            }
        }

        // Resolver apuestas activas para este partido
        await window._resolvePredictionBets(matchId, match);
    } catch(e) { console.warn('_awardPredictionPoints error:', e); }
};

// Resolver duelos de apuesta entre jugadores
window._resolvePredictionBets = async function(matchId, match) {
    const sb = window._sb;
    if (!sb) return;
    const { data: bets } = await sb.from('prediction_bets').select('*').eq('match_id', matchId).eq('status','active').catch(()=>({data:[]}));
    if (!bets?.length) return;

    for (const bet of bets) {
        const realA = match.score_a, realB = match.score_b;
        // Exactness score para cada lado
        const chalDiff = Math.abs(bet.challenger_score_a - realA) + Math.abs(bet.challenger_score_b - realB);
        const rivalDiff = (bet.rival_score_a != null && bet.rival_score_b != null)
            ? Math.abs(bet.rival_score_a - realA) + Math.abs(bet.rival_score_b - realB)
            : 999;
        const winner = chalDiff < rivalDiff ? bet.challenger_email : rivalDiff < chalDiff ? bet.rival_email : null;
        await sb.from('prediction_bets').update({ status: 'resolved', winner_email: winner }).eq('id', bet.id).catch(()=>{});
        if (winner) {
            // Notificar ganador
            const winnerName = winner === bet.challenger_email ? bet.challenger_name : bet.rival_name;
            const loserEmail = winner === bet.challenger_email ? bet.rival_email : bet.challenger_email;
            if (window.CancheroNotif?.create) {
                await window.CancheroNotif.create(winner, 'prediction_win', 'Sistema', `🏆 ¡Ganaste la apuesta de predicción para ${match.name || 'el partido'}!`).catch(()=>{});
                await window.CancheroNotif.create(loserEmail, 'prediction_lose', 'Sistema', `😔 Perdiste la apuesta de predicción para ${match.name || 'el partido'}.`).catch(()=>{});
            }
        }
    }
};

// Otorgar voucher de partido gratis
window._grantFreeMatchVoucher = async function(userEmail, userName, reason) {
    const sb = window._sb;
    if (!sb) return;
    try {
        await sb.from('free_match_vouchers').insert({
            user_email: userEmail,
            user_name: userName,
            reason: reason,
            status: 'pending', // complejo debe aceptar/rechazar
            created_at: new Date().toISOString(),
            code: 'GRATIS-' + Math.random().toString(36).substr(2,6).toUpperCase()
        }).catch(()=>{});
        // Notificar al jugador
        if (window.CancheroNotif?.create) {
            await window.CancheroNotif.create(userEmail, 'free_match', 'Canchero',
                reason === 'prediccion_racha'
                    ? '🎯 ¡Lograste 1 acierto en 20 predicciones! Tenés un partido GRATIS. Presentalo en el complejo.'
                    : '🏟️ ¡Lograste tu racha Duolingo! Tenés un partido GRATIS en el complejo.'
            ).catch(()=>{});
        }
        if(typeof showToast==='function') showToast('🎉 ¡LOGRASTE UN PARTIDO GRATIS! Revisá tus logros.','success');
    } catch(e) {}
};

// Racha Duolingo: contar partidos en el mismo complejo
window._checkDuolingoStreak = async function(userEmail, userName, complexName) {
    const sb = window._sb;
    if (!sb || !complexName) return;
    try {
        const { data } = await sb.from('match_attendance')
            .select('id')
            .eq('user_email', userEmail)
            .eq('complex_name', complexName)
            .catch(()=>({data:null}));
        const count = data?.length || 0;
        const DUOLINGO_TARGET = 15;
        if (count > 0 && count % DUOLINGO_TARGET === 0) {
            await window._grantFreeMatchVoucher(userEmail, userName, 'duolingo_complejo_' + complexName);
            // Avisar también al COMPLEJO para que tenga el partido gratis listo
            try {
                const { data: biz } = await sb.from('users').select('email').or(`name.ilike.%${complexName}%,complex_name.ilike.%${complexName}%`).in('role',['club','complejo']).limit(1);
                const bizEmail = biz && biz[0] && biz[0].email;
                if (bizEmail && window.CancheroNotif?.create) {
                    await window.CancheroNotif.create(bizEmail, 'free_match', 'Canchero',
                        `🏟️ ${userName || 'Un jugador'} completó 15 partidos en tu complejo. Le corresponde 1 partido GRATIS — coordiná la fecha.`).catch(()=>{});
                }
            } catch(e){}
        } else if (count > 0 && (count % DUOLINGO_TARGET) === (DUOLINGO_TARGET - 1)) {
            // Falta 1 → aviso anticipado al jugador
            if (window.CancheroNotif?.create) {
                await window.CancheroNotif.create(userEmail, 'free_match', 'Canchero',
                    `🔥 ¡Te falta 1 partido en ${complexName} para ganar un partido GRATIS!`).catch(()=>{});
            }
        }
    } catch(e) {}
};

// Ver mis predicciones y estadísticas
window._openPredStats = async function() {
    const sb = window._sb;
    if (!sb || !userData) { showToast && showToast('Iniciá sesión','error'); return; }
    const ex = document.getElementById('pred-stats-modal');
    if (ex) ex.remove();

    // Cargar datos del usuario
    const { data: u } = await sb.from('users').select('prediction_points,prediction_streak,prediction_total,prediction_correct').eq('email', userData.email).maybeSingle().catch(()=>({data:null}));
    const pts = u?.prediction_points || 0;
    const streak = u?.prediction_streak || 0;
    const total = u?.prediction_total || 0;
    const correct = u?.prediction_correct || 0;
    const pct = total > 0 ? Math.round(correct/total*100) : 0;

    // Cargar mis predicciones recientes
    const { data: preds } = await sb.from('predictions').select('*,matches(name,team_a_name,team_b_name,score_a,score_b)').eq('user_email', userData.email).order('created_at',{ascending:false}).limit(10).catch(()=>({data:[]}));

    // Cargar mis apuestas
    const { data: bets } = await sb.from('prediction_bets').select('*').or(`challenger_email.eq.${userData.email},rival_email.eq.${userData.email}`).order('created_at',{ascending:false}).limit(10).catch(()=>({data:[]}));

    // Cargar vouchers
    const { data: vouchers } = await sb.from('free_match_vouchers').select('*').eq('user_email', userData.email).order('created_at',{ascending:false}).limit(5).catch(()=>({data:[]}));

    const modal = document.createElement('div');
    modal.id = 'pred-stats-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:19900;background:rgba(0,0,0,0.9);overflow-y:auto;padding:20px 16px;box-sizing:border-box;';

    const progressTo20 = total > 0 ? (correct % 20) / 20 * 100 : 0;
    const betsPending = (bets||[]).filter(b=>b.status==='pending'||b.status==='active');
    const betsWon = (bets||[]).filter(b=>b.status==='resolved'&&b.winner_email===userData.email);

    modal.innerHTML = `
    <div style="max-width:480px;margin:0 auto;">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:20px;">
            <button onclick="document.getElementById('pred-stats-modal').remove()" style="background:none;border:none;color:#fff;font-size:22px;cursor:pointer;padding:4px;"><i class='bx bx-arrow-back'></i></button>
            <div style="font-size:16px;font-weight:900;color:var(--accent);">🎯 MIS PREDICCIONES</div>
        </div>

        <!-- Stats banner -->
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:16px;">
            ${[['🏆','Puntos',pts],['🔥','Racha',streak],['📊','Total',total],['✅','Aciertos',correct]].map(([ic,lb,vl])=>`
            <div style="background:#111;border:1px solid #222;border-radius:12px;padding:10px;text-align:center;">
                <div style="font-size:18px;">${ic}</div>
                <div style="font-size:16px;font-weight:900;color:var(--accent);">${vl}</div>
                <div style="font-size:9px;color:#666;">${lb}</div>
            </div>`).join('')}
        </div>

        <!-- Progreso a partido gratis -->
        <div style="background:#111;border:1px solid #222;border-radius:14px;padding:14px;margin-bottom:14px;">
            <div style="font-size:11px;font-weight:900;color:var(--accent);margin-bottom:6px;">🎯 PROGRESO → PARTIDO GRATIS</div>
            <div style="font-size:10px;color:#666;margin-bottom:8px;">1 predicción acertada cada 20 = partido gratis + insignia</div>
            <div style="background:#1a1a1a;border-radius:6px;height:8px;overflow:hidden;">
                <div style="height:100%;background:linear-gradient(90deg,var(--accent),#9ad400);width:${progressTo20}%;transition:width 0.5s;border-radius:6px;"></div>
            </div>
            <div style="display:flex;justify-content:space-between;margin-top:4px;font-size:10px;color:#666;">
                <span>${correct % 20} / 20 aciertos</span>
                <span>${pct}% efectividad</span>
            </div>
        </div>

        <!-- Vouchers -->
        ${vouchers?.length ? `<div style="background:rgba(186,255,0,0.06);border:1px solid rgba(186,255,0,0.3);border-radius:14px;padding:14px;margin-bottom:14px;">
            <div style="font-size:11px;font-weight:900;color:var(--accent);margin-bottom:10px;">🎁 MIS PARTIDOS GRATIS</div>
            ${vouchers.map(v=>`
            <div style="background:#111;border:1px solid #222;border-radius:10px;padding:10px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;">
                <div>
                    <div style="font-size:12px;font-weight:700;">Código: <span style="color:var(--accent);">${v.code}</span></div>
                    <div style="font-size:10px;color:#666;">${v.reason==='prediccion_racha'?'Por racha de predicciones':'Por racha Duolingo'}</div>
                </div>
                <div style="font-size:10px;font-weight:700;padding:4px 8px;border-radius:8px;background:${v.status==='pending'?'rgba(186,255,0,0.15)':v.status==='approved'?'rgba(0,200,80,0.15)':'rgba(255,60,0,0.15)'};color:${v.status==='pending'?'var(--accent)':v.status==='approved'?'#00c851':'#ff3c00'};">${v.status==='pending'?'PENDIENTE':v.status==='approved'?'APROBADO':'RECHAZADO'}</div>
            </div>`).join('')}
        </div>` : ''}

        <!-- Apuestas -->
        <div style="background:#111;border:1px solid #222;border-radius:14px;padding:14px;margin-bottom:14px;">
            <div style="font-size:11px;font-weight:900;color:var(--accent);margin-bottom:10px;">⚔️ MIS APUESTAS <span style="font-size:10px;color:#666;">(${betsWon.length} ganadas · ${betsPending.length} pendientes)</span></div>
            ${(bets||[]).slice(0,5).length ? (bets||[]).slice(0,5).map(b=>{
                const isMe = b.challenger_email===userData.email;
                const rival = isMe ? b.rival_name : b.challenger_name;
                const myScore = isMe ? `${b.challenger_score_a}-${b.challenger_score_b}` : (b.rival_score_a!=null?`${b.rival_score_a}-${b.rival_score_b}`:'?');
                const statusColor = b.status==='pending'?'#ffb400':b.status==='resolved'&&b.winner_email===userData.email?'var(--accent)':b.status==='resolved'?'#f44':' #888';
                const statusLabel = b.status==='pending'?'ESPERANDO':b.status==='active'?'EN JUEGO':b.winner_email===userData.email?'GANASTE':'PERDISTE';
                return `<div style="border:1px solid #1e1e1e;border-radius:10px;padding:9px 12px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;">
                    <div><div style="font-size:11px;font-weight:700;">vs ${rival}</div><div style="font-size:10px;color:#666;">Tu pred: ${myScore}</div></div>
                    <div style="font-size:9px;font-weight:900;color:${statusColor};">${statusLabel}</div>
                </div>`;
            }).join('') : '<div style="text-align:center;color:#555;font-size:11px;padding:10px;">Sin apuestas aún. ¡Desafiá a alguien!</div>'}
        </div>

        <!-- Historial predicciones -->
        <div style="background:#111;border:1px solid #222;border-radius:14px;padding:14px;">
            <div style="font-size:11px;font-weight:900;color:var(--accent);margin-bottom:10px;">📋 HISTORIAL</div>
            ${(preds||[]).slice(0,5).length ? (preds||[]).slice(0,5).map(p=>{
                const m = p.matches;
                const done = p.is_correct != null;
                return `<div style="border:1px solid #1e1e1e;border-radius:10px;padding:9px 12px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;">
                    <div>
                        <div style="font-size:11px;font-weight:700;">${m?.name||'Partido'}</div>
                        <div style="font-size:10px;color:#888;">Tu pred: ${p.score_a??'?'}-${p.score_b??'?'}${done?` · Real: ${p.real_score_a}-${p.real_score_b}`:''}</div>
                    </div>
                    ${done ? `<div style="font-size:11px;font-weight:900;${p.is_correct?'color:var(--accent)':'color:#f44'};">${p.is_correct?'+'+p.points_awarded+'pts':'✗'}</div>` : '<div style="font-size:10px;color:#666;">PENDIENTE</div>'}
                </div>`;
            }).join('') : '<div style="text-align:center;color:#555;font-size:11px;padding:10px;">Sin predicciones aún.</div>'}
        </div>

        <!-- Compare con rival -->
        <div style="margin-top:14px;background:#111;border:1px solid #222;border-radius:14px;padding:14px;">
            <div style="font-size:11px;font-weight:900;color:var(--accent);margin-bottom:10px;">🆚 COMPARAR CON JUGADOR</div>
            <div style="display:flex;gap:8px;">
                <input id="pred-compare-input" type="text" placeholder="Buscar jugador..." style="flex:1;background:#1a1a1a;border:1px solid #2a2a2a;color:#fff;border-radius:10px;padding:9px 12px;font-size:12px;outline:none;" oninput="window._searchComparePlayer(this.value)">
            </div>
            <div id="pred-compare-results" style="margin-top:8px;"></div>
        </div>
    </div>`;
    modal.onclick = e => { if(e.target===modal) modal.remove(); };
    document.body.appendChild(modal);
};

window._searchComparePlayer = async function(q) {
    const results = document.getElementById('pred-compare-results');
    if (!results || !q || q.length < 2) { if(results) results.innerHTML=''; return; }
    const sb = window._sb;
    const { data } = await sb.from('users').select('email,name,photo,prediction_points,prediction_correct,prediction_total').ilike('name',`%${q}%`).neq('email',userData?.email).limit(5).catch(()=>({data:[]}));
    if (!data?.length) { results.innerHTML='<div style="color:#555;font-size:11px;text-align:center;padding:8px;">Sin resultados</div>'; return; }
    results.innerHTML = data.map(u=>{
        const ph = u.photo;
        const pct = u.prediction_total>0?Math.round(u.prediction_correct/u.prediction_total*100):0;
        return `<div style="display:flex;align-items:center;gap:10px;padding:8px;border:1px solid #1e1e1e;border-radius:10px;margin-bottom:6px;">
            ${ph?`<img src="${ph}" style="width:34px;height:34px;border-radius:50%;object-fit:cover;">`:`<div style="width:34px;height:34px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;">${(u.name||'?')[0].toUpperCase()}</div>`}
            <div style="flex:1;">
                <div style="font-size:12px;font-weight:700;">${u.name||u.email}</div>
                <div style="font-size:10px;color:#666;">${u.prediction_points||0} pts · ${pct}% efectividad</div>
            </div>
            <button onclick="window._compareWith('${u.email}','${(u.name||'').replace(/'/g,'\\\'')}')" style="background:rgba(186,255,0,0.1);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:8px;padding:5px 10px;font-size:10px;font-weight:700;cursor:pointer;">COMPARAR</button>
        </div>`;
    }).join('');
};

window._compareWith = async function(rivalEmail, rivalName) {
    const sb = window._sb;
    if (!sb || !userData) return;
    const results = document.getElementById('pred-compare-results');
    if (results) results.innerHTML = '<div style="text-align:center;padding:10px;color:#555;"><i class="bx bx-loader-alt bx-spin"></i></div>';

    // Obtener predicciones de ambos en los mismos partidos
    const [{ data: myPreds }, { data: theirPreds }] = await Promise.all([
        sb.from('predictions').select('match_id,score_a,score_b,is_correct,points_awarded,matches(name)').eq('user_email', userData.email).not('is_correct','is',null).limit(20),
        sb.from('predictions').select('match_id,score_a,score_b,is_correct,points_awarded,matches(name)').eq('user_email', rivalEmail).not('is_correct','is',null).limit(20)
    ]).catch(()=>[{data:[]},{data:[]}]);

    const myMap = Object.fromEntries((myPreds||[]).map(p=>[p.match_id,p]));
    const theirMap = Object.fromEntries((theirPreds||[]).map(p=>[p.match_id,p]));
    const shared = Object.keys(myMap).filter(id=>theirMap[id]);

    if (!shared.length) {
        if (results) results.innerHTML = '<div style="color:#555;font-size:11px;text-align:center;padding:10px;">No tienen predicciones en los mismos partidos todavía.</div>';
        return;
    }

    let myWins=0, theirWins=0, draws=0;
    const rows = shared.map(id => {
        const me = myMap[id], them = theirMap[id];
        const winner = me.points_awarded > them.points_awarded ? 'me' : them.points_awarded > me.points_awarded ? 'them' : 'draw';
        if (winner==='me') myWins++; else if (winner==='them') theirWins++; else draws++;
        return `<div style="border:1px solid #1e1e1e;border-radius:9px;padding:8px 10px;margin-bottom:5px;font-size:10px;display:flex;justify-content:space-between;align-items:center;">
            <div style="color:${winner==='me'?'var(--accent)':'#666'};font-weight:700;">${me.score_a}-${me.score_b} ${me.is_correct?'✓':'✗'}</div>
            <div style="color:#555;font-size:9px;">${me.matches?.name||'Partido'}</div>
            <div style="color:${winner==='them'?'var(--accent)':'#666'};font-weight:700;">${them.score_a}-${them.score_b} ${them.is_correct?'✓':'✗'}</div>
        </div>`;
    }).join('');

    if (results) results.innerHTML = `
    <div style="background:#0d1209;border:1px solid #1e2a10;border-radius:12px;padding:12px;margin-top:8px;">
        <div style="display:flex;justify-content:space-around;margin-bottom:10px;">
            <div style="text-align:center;"><div style="font-size:20px;font-weight:900;color:var(--accent);">${myWins}</div><div style="font-size:9px;color:#666;">TUS VICTORIAS</div></div>
            <div style="text-align:center;"><div style="font-size:20px;font-weight:900;color:#555;">${draws}</div><div style="font-size:9px;color:#666;">EMPATES</div></div>
            <div style="text-align:center;"><div style="font-size:20px;font-weight:900;color:#888;">${theirWins}</div><div style="font-size:9px;color:#666;">DE ${rivalName}</div></div>
        </div>
        ${rows}
    </div>`;
};

// Aceptar apuesta de predicción desde notificación
window._acceptPredBet = async function(betId) {
    const sb = window._sb;
    if (!sb || !userData) return;
    // Mostrar modal para que el rival ingrese su predicción
    const { data: bet } = await sb.from('prediction_bets').select('*').eq('id', betId).maybeSingle().catch(()=>({data:null}));
    if (!bet) { showToast && showToast('Apuesta no encontrada','error'); return; }

    const m = document.createElement('div');
    m.style.cssText = 'position:fixed;inset:0;z-index:19900;background:rgba(0,0,0,0.88);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    m.innerHTML = `<div style="background:#111;border:1px solid #2a2a2a;border-radius:20px;width:100%;max-width:420px;padding:20px;">
        <div style="font-size:14px;font-weight:900;color:var(--accent);margin-bottom:4px;"><i class='bx bx-trophy'></i> ACEPTAR APUESTA</div>
        <div style="font-size:11px;color:#888;margin-bottom:14px;">${bet.challenger_name} predijo: <strong style="color:#fff;">${bet.challenger_score_a} - ${bet.challenger_score_b}</strong></div>
        <div style="font-size:11px;color:#888;font-weight:700;margin-bottom:8px;">TU PREDICCIÓN</div>
        <div style="display:flex;gap:8px;align-items:center;justify-content:center;margin-bottom:16px;">
            <input type="number" min="0" max="20" id="bet-accept-a" placeholder="0" style="width:60px;height:60px;background:#000;border:2px solid var(--accent);color:var(--accent);text-align:center;border-radius:10px;font-size:24px;font-weight:900;outline:none;">
            <span style="font-size:20px;color:#444;">-</span>
            <input type="number" min="0" max="20" id="bet-accept-b" placeholder="0" style="width:60px;height:60px;background:#000;border:2px solid var(--accent);color:var(--accent);text-align:center;border-radius:10px;font-size:24px;font-weight:900;outline:none;">
        </div>
        <div style="display:flex;gap:8px;">
            <button onclick="this.closest('div[style]').remove()" style="flex:1;padding:12px;background:transparent;border:1px solid #333;color:#aaa;border-radius:12px;cursor:pointer;font-weight:700;font-size:12px;">Cancelar</button>
            <button onclick="window._confirmAcceptBet('${betId}',this)" style="flex:2;padding:12px;background:var(--accent);color:#000;border:none;border-radius:12px;cursor:pointer;font-weight:900;font-size:12px;">ACEPTAR ⚔️</button>
        </div>
    </div>`;
    document.body.appendChild(m);
};

window._confirmAcceptBet = async function(betId, btn) {
    const sa = parseInt(document.getElementById('bet-accept-a')?.value);
    const sb2 = parseInt(document.getElementById('bet-accept-b')?.value);
    if (isNaN(sa) || isNaN(sb2)) { showToast && showToast('Ingresá tu predicción','error'); return; }
    const sb = window._sb;
    if (!sb || !userData) return;
    btn.disabled = true;
    btn.innerHTML = '<i class="bx bx-loader-alt bx-spin"></i>';
    await sb.from('prediction_bets').update({
        rival_score_a: sa, rival_score_b: sb2,
        rival_name: userData.name,
        status: 'active'
    }).eq('id', betId).catch(()=>{});
    btn.closest('div[style]').remove();
    showToast && showToast('⚔️ ¡Apuesta aceptada! Se resolverá cuando termine el partido.','success');
};

// Botón en prediction card para ver mis stats
window._openMyPredStats = function() { window._openPredStats(); };

