// --- CARGAR HISTORIAS EN BARRA DEL FEED ---
// Muestra la barra inmediatamente con "Tu historia", luego carga historias async con prioridad
window.initFeedStoriesBar = function() {
    const container = document.getElementById('feed-stories-container');
    if (!container) return;
    // El bloque MOMENTOS reemplazó a la barra de historias en el feed:
    // NO mostrarla acá (era la causa del flash al abrir el feed). Solo se
    // carga el caché de historias para los anillos de los avatares.
    container.style.display = 'none';
    const addBtn = `<div onclick="addStory()" style="flex-shrink:0;text-align:center;cursor:pointer;min-width:64px;" id="feed-add-story-btn">
      <div style="width:56px;height:56px;border-radius:50%;border:2px dashed var(--accent);display:flex;align-items:center;justify-content:center;background:#0d0d0d;margin:0 auto 4px;">
        <i class='bx bx-plus' style="color:var(--accent);font-size:20px;"></i>
      </div>
      <div style="font-size:9px;color:#888;white-space:nowrap;">Tu historia</div>
    </div>`;
    container.innerHTML = addBtn;
    // Cargar historias con prioridad en background
    loadFeedStories();
};

// ── Caché global de historias agrupadas por usuario ──────────
window._feedStoriesByUser = {}; // email -> [{id, media_url, content, created_at, ...}]

window.loadFeedStories = async function() {
    const container = document.getElementById('feed-stories-container');
    if (!container) return;
    const sb = _sb || window._sb;
    if (!sb) return;
    try {
        const now = new Date().toISOString();
        const myEmail = (userData && userData.email) || '';

        // Traer TODAS las historias activas (todas las de cada usuario dentro de 12hs)
        const { data: stories, error: stErr } = await sb.from('stories')
            .select('id, user_name, user_email, user_avatar, media_url, content, created_at, expires_at')
            .gt('expires_at', now)
            .order('created_at', { ascending: true }) // MÁS VIEJA PRIMERO — orden Instagram
            .limit(200);

        if (stErr) { console.warn('[loadFeedStories] query error:', stErr); return; }
        if (!stories || stories.length === 0) return;

        // Agrupar por usuario — UN bubble por usuario, con todas sus historias
        const userMap = {}; // email -> { user_name, user_avatar, stories: [] }
        stories.forEach(s => {
            if (!userMap[s.user_email]) {
                userMap[s.user_email] = { user_name: s.user_name, user_avatar: s.user_avatar, stories: [] };
            }
            userMap[s.user_email].stories.push(s);
        });

        // Guardar en caché global para el viewer
        window._feedStoriesByUser = userMap;

        // Traer following para prioridad
        let followingEmails = new Set();
        if (myEmail) {
            try {
                const { data: follows } = await sb.from('follows').select('following_email').eq('follower_email', myEmail);
                (follows || []).forEach(f => followingEmails.add(f.following_email));
            } catch(_e) {}
        }

        // Ordenar usuarios: primero el propio, luego seguidos, luego resto
        const userEmails = Object.keys(userMap).filter(e => e !== myEmail);
        const orderedEmails = [
            ...(myEmail && userMap[myEmail] ? [myEmail] : []),
            ...userEmails.filter(e => followingEmails.has(e)),
            ...userEmails.filter(e => !followingEmails.has(e))
        ];

        const storiesHtml = orderedEmails.map(email => {
            const ud = userMap[email];
            const initials = (ud.user_name || '?')[0].toUpperCase();
            // Usar la historia más reciente como thumbnail del bubble
            const lastStory = ud.stories[ud.stories.length - 1];
            const firstStory = ud.stories[0];
            const diff = Date.now() - new Date(lastStory.created_at).getTime();
            const ago = diff < 3600000 ? `${Math.floor(diff/60000)}m` : `${Math.floor(diff/3600000)}h`;
            const isMe = email === myEmail;
            const isFollowing = followingEmails.has(email);
            const borderColor = isMe ? 'var(--accent)' : isFollowing ? '#baff00' : '#ff3333';
            const thumbSrc = lastStory.media_url || ud.user_avatar || '';
            const countBadge = ud.stories.length > 1 ? `<div style="position:absolute;top:-2px;right:-2px;background:var(--accent);color:#000;border-radius:50%;width:16px;height:16px;font-size:9px;font-weight:900;display:flex;align-items:center;justify-content:center;border:1px solid #0d0d0d;">${ud.stories.length}</div>` : '';
            return `<div onclick="viewUserStories('${email.replace(/'/g,"\\'")}')" style="flex-shrink:0;text-align:center;cursor:pointer;min-width:68px;position:relative;">
              <div style="position:relative;display:inline-block;">
                <div style="width:58px;height:58px;border-radius:50%;border:2.5px solid ${borderColor};box-shadow:0 0 8px ${borderColor}55;display:flex;align-items:center;justify-content:center;background:#111;margin:0 auto 4px;overflow:hidden;">
                    ${thumbSrc ? `<img src="${thumbSrc}" style="width:100%;height:100%;object-fit:cover;" onerror="this.style.display='none'">` : ''}
                    <span style="font-weight:900;color:var(--accent);font-size:20px;position:absolute;">${thumbSrc ? '' : initials}</span>
                </div>
                ${countBadge}
              </div>
              <div style="font-size:9px;color:#ccc;white-space:nowrap;max-width:66px;overflow:hidden;text-overflow:ellipsis;">${(ud.user_name||'').split(' ')[0]}</div>
              <div style="font-size:8px;color:#555;">${ago}</div>
            </div>`;
        }).join('');

        // Limpiar y reinsertar
        Array.from(container.children).forEach(function(child) {
            if (child.id !== 'feed-add-story-btn') child.remove();
        });
        const addBtn = document.getElementById('feed-add-story-btn');
        if (addBtn) {
            addBtn.insertAdjacentHTML('afterend', storiesHtml);
        } else {
            container.innerHTML = `<div onclick="addStory()" style="flex-shrink:0;text-align:center;cursor:pointer;min-width:68px;" id="feed-add-story-btn">
              <div style="width:58px;height:58px;border-radius:50%;border:2px dashed var(--accent);display:flex;align-items:center;justify-content:center;background:#0d0d0d;margin:0 auto 4px;">
                <i class='bx bx-plus' style="color:var(--accent);font-size:22px;"></i>
              </div>
              <div style="font-size:9px;color:#888;white-space:nowrap;">Tu historia</div>
            </div>` + storiesHtml;
        }
    } catch(e) { console.warn('loadFeedStories error:', e); }
};

// ── Viewer de historias de un usuario — tipo Instagram ────────
window.viewUserStories = async function(userEmail) {
    // Si está en caché, usar caché; si no, cargar de DB
    let userStories = (window._feedStoriesByUser && window._feedStoriesByUser[userEmail])
        ? window._feedStoriesByUser[userEmail].stories
        : null;

    if (!userStories) {
        const sb = window._sb;
        if (!sb) return;
        try {
            const now = new Date().toISOString();
            const { data } = await sb.from('stories')
                .select('*').eq('user_email', userEmail).gt('expires_at', now)
                .order('created_at', { ascending: true });
            userStories = data || [];
        } catch(e) { return; }
    }

    if (!userStories || !userStories.length) return;
    _openStoryViewer(userStories, 0);
};

// Viewer de historias con navegación entre múltiples (tipo Instagram)
window._openStoryViewer = function(stories, startIndex) {
    let idx = startIndex || 0;
    const existing = document.getElementById('story-viewer-modal');
    if (existing) existing.remove();

    const modal = document.createElement('div');
    modal.id = 'story-viewer-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;';

    function renderStory(i) {
        const s = stories[i];
        if (!s) { modal.remove(); return; }
        const total = stories.length;
        const diff = Date.now() - new Date(s.created_at).getTime();
        const ago = diff < 3600000 ? `${Math.floor(diff/60000)}m` : `${Math.floor(diff/3600000)}h`;
        const progressBars = stories.map((_,pi) =>
            `<div style="flex:1;height:2px;border-radius:2px;background:${pi < i ? '#fff' : pi === i ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.3)'};margin:0 1px;"></div>`
        ).join('');

        modal.innerHTML = `
            <!-- Barras de progreso -->
            <div style="position:absolute;top:0;left:0;right:0;padding:10px 12px 0;display:flex;gap:2px;z-index:10;">
                ${progressBars}
            </div>
            <!-- Header con avatar y nombre -->
            <div style="position:absolute;top:18px;left:0;right:0;padding:12px 14px;display:flex;align-items:center;gap:10px;z-index:10;">
                <div style="width:36px;height:36px;border-radius:50%;background:#333;overflow:hidden;flex-shrink:0;border:1px solid rgba(255,255,255,0.3);">
                    ${s.user_avatar ? `<img src="${s.user_avatar}" style="width:100%;height:100%;object-fit:cover;">` : `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-weight:900;color:#fff;font-size:14px;">${(s.user_name||'?')[0].toUpperCase()}</div>`}
                </div>
                <div>
                    <div style="font-weight:800;font-size:13px;color:#fff;">${s.user_name||'Usuario'}</div>
                    <div style="font-size:10px;color:rgba(255,255,255,0.6);">${ago} · ${i+1}/${total}</div>
                </div>
                <button onclick="document.getElementById('story-viewer-modal')?.remove()" style="margin-left:auto;background:none;border:none;color:#fff;font-size:26px;cursor:pointer;padding:0 4px;line-height:1;">&times;</button>
            </div>
            <!-- Contenido de la historia -->
            <div style="width:100%;max-width:420px;height:100vh;max-height:100vh;position:relative;display:flex;align-items:center;justify-content:center;">
                ${s.media_url ? `<img src="${s.media_url}" style="width:100%;height:100%;object-fit:contain;">` : ''}
                ${s.content ? `<div style="position:absolute;bottom:80px;left:0;right:0;text-align:center;padding:16px;font-size:18px;font-weight:800;color:#fff;text-shadow:0 2px 8px rgba(0,0,0,0.8);">${s.content}</div>` : ''}
            </div>
            <!-- Controles de navegación táctil -->
            <div style="position:absolute;inset:0;display:flex;">
                <div style="flex:1;cursor:pointer;" onclick="_openStoryViewer(window._currentViewerStories,${i > 0 ? i-1 : 0})" title="Anterior"></div>
                <div style="flex:1;cursor:pointer;" onclick="_openStoryViewer(window._currentViewerStories,${i < total-1 ? i+1 : i})" title="Siguiente" ondblclick="document.getElementById('story-viewer-modal')?.remove()"></div>
            </div>
            <!-- Flechas -->
            ${i > 0 ? `<button onclick="_openStoryViewer(window._currentViewerStories,${i-1})" style="position:absolute;left:10px;top:50%;transform:translateY(-50%);background:rgba(255,255,255,0.15);border:none;color:#fff;border-radius:50%;width:36px;height:36px;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;z-index:10;"><i class='bx bx-chevron-left'></i></button>` : ''}
            ${i < total-1 ? `<button onclick="_openStoryViewer(window._currentViewerStories,${i+1})" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);background:rgba(255,255,255,0.15);border:none;color:#fff;border-radius:50%;width:36px;height:36px;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;z-index:10;"><i class='bx bx-chevron-right'></i></button>` : ''}
        `;
        // Guardar referencia global para navegación
        window._currentViewerStories = stories;
    }

    renderStory(idx);
    modal.onclick = function(e) { if(e.target===modal) modal.remove(); };
    document.addEventListener('keydown', function escKey(e) {
        if(e.key==='Escape'){modal.remove();document.removeEventListener('keydown',escKey);}
        if(e.key==='ArrowRight'){const ns=stories[idx+1];if(ns){idx++;window._openStoryViewer(stories,idx);}}
        if(e.key==='ArrowLeft'){const ps=stories[idx-1];if(ps){idx--;window._openStoryViewer(stories,idx);}}
    }, {once:true});
    document.body.appendChild(modal);
};

// viewFeedStory sigue existiendo como fallback (ahora usa el nuevo viewer)
window.viewFeedStory = function(storyId) {
    // Buscar en caché
    for (const email in (window._feedStoriesByUser||{})) {
        const ud = window._feedStoriesByUser[email];
        const found = ud.stories.find(s => s.id === storyId);
        if (found) { window.viewUserStories(email); return; }
    }
    // Fallback: cargar solo esa historia
    const sb = window._sb;
    if (!sb) return;
    sb.from('stories').select('*').eq('id', storyId).single().then(function(res) {
        if (res.data) window._openStoryViewer([res.data], 0);
    });
};

// --- BLOQUEAR USUARIO ---
window.blockUser = async function(targetEmail, targetName) {
    const sb = _sb || window._sb;
    if (!userData || !sb) { showToast('Iniciá sesión primero.', 'warning'); return; }
    if (!confirm(`¿Bloquear a ${targetName}? No verás su contenido y no podrá interactuar contigo.`)) return;
    const { error } = await sb.from('blocks').upsert({
        blocker_email: userData.email, blocked_email: targetEmail
    }, { onConflict: 'blocker_email,blocked_email' });
    if (error) { alert('Error al bloquear: ' + error.message); return; }
    alert(`${targetName} bloqueado/a.`);
};

