function _disponiblesPlayerCard(u, compact) {
    const photo = u.photo || u.avatar || '';
    const initials = (u.name||'?')[0].toUpperCase();
    const ps = u.photo_style || {};
    const _px = 50 + parseInt(ps.x || 0);
    const _py = 50 + parseInt(ps.y || 0);
    const _zoom = parseFloat(ps.zoom || 100);
    const _bgSize = _zoom > 100 ? `${_zoom}%` : 'cover';
    const av = photo
        ? `<div style="width:48px;height:48px;border-radius:50%;background-image:url('${photo}');background-size:${_bgSize};background-position:${_px}% ${_py}%;flex-shrink:0;border:2px solid #00e676;"></div>`
        : `<div style="width:48px;height:48px;border-radius:50%;background:#1a2a1a;display:flex;align-items:center;justify-content:center;font-weight:900;color:#00e676;font-size:18px;flex-shrink:0;border:2px solid #00e676;">${initials}</div>`;
    const pos = u.position || u.pos || '';
    const city = u.city || u.dept || '';
    return `<div style="display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #1a1a1a;cursor:pointer;" onclick="viewPlayerProfile('${u.email}')">
        ${av}
        <div style="flex:1;min-width:0;">
            <div style="font-weight:800;font-size:14px;display:flex;align-items:center;gap:6px;">${u.name||'Jugador'} <span style="width:7px;height:7px;background:#00e676;border-radius:50%;box-shadow:0 0 5px #00e676;flex-shrink:0;"></span></div>
            <div style="font-size:12px;color:#888;margin-top:2px;">${pos}${pos && city ? ' · ' : ''}${city}</div>
        </div>
        <button onclick="event.stopPropagation();sendClubRequestToPlayer('${u.email}','${(u.name||'').replace(/'/g,'')}')" style="background:rgba(186,255,0,0.1);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:8px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">VER PERFIL</button>
    </div>`;
}

window.loadDisponibles = async function(scope, btn) {
    document.querySelectorAll('.disp-loc-btn').forEach(b => {
        b.style.borderColor = '#333'; b.style.background = 'transparent'; b.style.color = '#aaa';
    });
    if (btn) { btn.style.borderColor = '#00e676'; btn.style.background = 'rgba(0,230,118,0.12)'; btn.style.color = '#00e676'; }

    const container = document.getElementById('amigos-feed');
    if (!container) return;
    container.innerHTML = `<div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div>`;

    const sb = _sb || window._sb;
    if (!sb) { container.innerHTML = '<div style="text-align:center;padding:30px;color:#555;">Sin conexión.</div>'; return; }
    const me = window.userData;

    try {
        // select('*') para no romper si falta alguna columna (pos/nat/photo_style/etc.)
        let q = sb.from('users').select('*').eq('available', true).neq('role', 'club').limit(50);
        if (scope === 'ciudad' && me && (me.city || me.dept)) {
            const c = me.city || me.dept;
            q = q.ilike('city', `%${c}%`);
        } else if (scope === 'pais' && me) {
            const nat = me.nat || me.nationality || 'Uruguay';
            q = q.ilike('nat', nat);
        }
        let { data, error } = await q;
        if (error) {
            // Reintento sin filtros que puedan fallar por columna inexistente
            console.warn('[Disponibles] error:', error.message);
            const retry = await sb.from('users').select('*').eq('available', true).limit(50);
            if (!retry.error) { data = retry.data; error = null; }
        }
        if (error) {
            // Fallback automático ante error de permisos
            if (scope !== 'mundo') { loadDisponibles('mundo', null); return; }
            container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><span style="font-size:36px;display:block;margin-bottom:10px;">⚽</span><div style="font-size:14px;font-weight:700;margin-bottom:6px;color:#aaa;">No se pudo cargar</div></div>`;
            return;
        }
        // Filtrar bots (bot-*@canchero.app) para que no aparezcan jugadores falsos
        if (data && data.length) {
            data = data.filter(u => !(window._isBot && window._isBot(u)));
        }
        if (!data || !data.length) {
            // Fallback progresivo: ciudad → pais → mundo
            if (scope === 'ciudad') { loadDisponibles('pais', null); return; }
            if (scope === 'pais') { loadDisponibles('mundo', null); return; }
            container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><span style="font-size:36px;display:block;margin-bottom:10px;">⚽</span><div style="font-size:14px;font-weight:700;margin-bottom:6px;color:#aaa;">No hay jugadores disponibles</div><div style="font-size:12px;">Activá tu disponibilidad en tu perfil para aparecer acá</div></div>`;
            return;
        }
        container.innerHTML = `<div style="padding:4px 0 8px;"><div style="font-size:12px;color:#555;margin-bottom:8px;">${data.length} jugador${data.length!==1?'es':''} disponible${data.length!==1?'s':''} ${scope==='ciudad'?'en tu ciudad':scope==='pais'?'en tu país':'en el mundo'}</div>${data.map(u => _disponiblesPlayerCard(u)).join('')}</div>`;
    } catch(e) {
        container.innerHTML = `<div style="text-align:center;padding:30px;color:#f44;font-size:12px;">Error: ${e.message}</div>`;
    }
};

// Modal version
window.openDisponiblesModal = function() {
    const m = document.getElementById('disponibles-modal');
    if (!m) return;
    m.style.display = 'flex';
    loadDisponiblesModal('ciudad', m.querySelector('.disp-modal-btn'));
};

window.loadDisponiblesModal = async function(scope, btn, customCountry, customCity) {
    document.querySelectorAll('.disp-modal-btn').forEach(b => {
        b.style.borderColor = '#333'; b.style.background = 'transparent'; b.style.color = '#aaa';
    });
    if (btn) { btn.style.borderColor = '#00e676'; btn.style.background = 'rgba(0,230,118,0.12)'; btn.style.color = '#00e676'; }

    const container = document.getElementById('disponibles-modal-list');
    if (!container) return;
    container.innerHTML = `<div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div>`;

    const sb = window._sb || window.supabaseClient;
    if (!sb) { container.innerHTML = '<div style="padding:20px;color:#555;text-align:center;">Sin conexión.</div>'; return; }
    const me = window.userData;

    try {
        // select('*') para no romper si falta alguna columna
        let q = sb.from('users').select('*').eq('available', true).neq('role', 'club').limit(60);

        if (scope === 'custom') {
            if (customCountry) q = q.ilike('nat', customCountry);
            if (customCity) q = q.ilike('city', `%${customCity}%`);
        } else if (scope === 'ciudad' && me && (me.city || me.dept)) {
            const c = me.city || me.dept;
            q = q.ilike('city', `%${c}%`);
        } else if (scope === 'pais' && me) {
            const nat = me.nat || me.nationality || 'Uruguay';
            q = q.ilike('nat', nat);
        }

        let { data, error } = await q;
        if (error) {
            console.warn('[DisponiblesModal] error:', error.message);
            const retry = await sb.from('users').select('*').eq('available', true).limit(60);
            if (!retry.error) { data = retry.data; error = null; }
        }
        if (error) {
            if (scope !== 'mundo') { loadDisponiblesModal('mundo', null); return; }
            container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><span style="font-size:36px;display:block;margin-bottom:10px;">⚽</span><div>No se pudo cargar</div></div>`;
            return;
        }
        if (data && data.length) { data = data.filter(u => !(window._isBot && window._isBot(u))); }
        if (!data || !data.length) {
            if (scope === 'ciudad') { loadDisponiblesModal('pais', null); return; }
            if (scope === 'pais') { loadDisponiblesModal('mundo', null); return; }
            container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><span style="font-size:36px;display:block;margin-bottom:10px;">⚽</span><div>No hay jugadores disponibles</div></div>`;
            return;
        }
        container.innerHTML = `<div style="padding:4px 0 8px;"><div style="font-size:11px;color:#555;margin-bottom:8px;">${data.length} jugador${data.length!==1?'es':''} disponible${data.length!==1?'s':''}</div>${data.map(u => _disponiblesPlayerCard(u)).join('')}</div>`;
    } catch(e) {
        container.innerHTML = `<div style="text-align:center;padding:20px;color:#f44;font-size:12px;">Error: ${e.message}</div>`;
    }
};

