    const m = document.createElement('div');
    m.id = 'clubes-buscan-page';
    m.style.cssText = 'position:fixed;left:0;right:0;bottom:0;top:'+(window._navH?window._navH():0)+'px;z-index:9950;background:#0a0a0a;overflow-y:auto;-webkit-overflow-scrolling:touch;';
    m.innerHTML = `<div style="max-width:600px;margin:0 auto;min-height:100%;padding-bottom:90px;">
        <div style="position:sticky;top:0;z-index:5;background:rgba(10,10,10,0.96);backdrop-filter:blur(10px);border-bottom:1px solid #1a1a1a;padding:calc(10px + env(safe-area-inset-top)) 16px 12px;">
            <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">
                <button onclick="document.getElementById('clubes-buscan-page').remove()" style="background:rgba(255,255,255,0.06);border:1px solid #2a2a2a;border-radius:20px;color:#fff;font-size:13px;font-weight:700;cursor:pointer;padding:7px 13px;display:flex;align-items:center;gap:5px;"><i class='bx bx-arrow-back'></i></button>
                <div style="font-size:15px;font-weight:900;color:var(--accent);flex:1;"><i class='bx bx-shield-quarter'></i> Equipos que buscan jugadores</div>
            </div>
            <input id="cb-search" placeholder="Buscar club o ciudad..." oninput="window._cbFilter()" style="width:100%;background:#141414;border:1px solid #222;border-radius:22px;color:#fff;font-size:13px;padding:10px 16px;outline:none;box-sizing:border-box;margin-bottom:10px;">
            <div style="display:flex;gap:8px;">${window.CancheroGeo ? window.CancheroGeo.selectsHTML('cb') : ''}</div>
        </div>
        <div id="clubes-buscan-list" style="padding:8px 16px;"><div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div></div>
    </div>`;
