window._cbAll = [];
window.loadClubesBuscan = async function(scope, btn) {
    const container = document.getElementById('clubes-buscan-list');
    if (!container) return;
    container.innerHTML = `<div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div>`;
    const sb = window._sb;
    if (!sb) { container.innerHTML = '<div style="padding:20px;color:#888;text-align:center;">Sin conexión.</div>'; return; }
    try {
        // 1) Clubes
        const { data: clubs } = await sb.from('clubs').select('*').limit(200);
        // 2) Miembros (para contar plantilla)
        let memberCount = {};
        try {
            const { data: mem } = await sb.from('club_members').select('club_id').neq('status','pendiente');
            (mem||[]).forEach(r=>{ memberCount[r.club_id]=(memberCount[r.club_id]||0)+1; });
        } catch(e){}
        // 3) Partidos abiertos / con cupo (para listar debajo del club)
        let openMatches = [];
        try {
            const { data: oms } = await sb.from('matches').select('*')
                .gte('scheduled_at', new Date(Date.now()-3*3600000).toISOString())
                .order('scheduled_at',{ascending:true}).limit(150);
            openMatches = (oms||[]).filter(m=>{
                const st=(m.status||'').toLowerCase();
                if (['finished','finalizado','cancelado','cancelled'].includes(st)) return false;
                const left=(m.slots_total||0)-(m.slots_taken||0);
                const isOpen = m.is_open===true || (m.match_type||'').toLowerCase().includes('open') || (m.modality||'').toLowerCase().includes('abierto');
                return isOpen || left>0;
            });
        } catch(e){}
        // Derivar clubes con cupo incompleto según su formato
        window._cbAll = (clubs||[]).map(c=>{
            const fmt = ((c.modality||c.format||'F11')+'').toLowerCase();
            const total = /5/.test(fmt)?5 : /7/.test(fmt)?7 : 11;
            const have = memberCount[c.id] || 0;
            const missing = Math.max(0, total - have);
            // partidos del club (por nombre o por owner)
            const cmatches = openMatches.filter(m=>{
                const owner = (m.created_by||'').toLowerCase();
                const cn = (c.name||'').toLowerCase();
                return (owner && owner===(c.owner_email||'').toLowerCase()) ||
                    ((m.home_club_name||m.team_a_name||'').toLowerCase()===cn) ||
                    ((m.away_club_name||m.team_b_name||'').toLowerCase()===cn);
            });
            return { id:c.id, club_name:c.name, logo:c.logo||c.logo_url, city:c.city, country:c.nat||c.country, fmt:fmt.toUpperCase(), have, total, missing_count:missing, matches:cmatches };
        }).filter(x=> x.missing_count>0); // Solo clubes que necesitan jugadores — los partidos van en "Unirme a un partido"
    } catch(e) {
        console.error('loadClubesBuscan:', e);
        window._cbAll = [];
    }
    window._cbFilter();
};

window._cbFilter = function() {
    const container = document.getElementById('clubes-buscan-list');
    if (!container) return;
    const qy = (document.getElementById('cb-search')?.value||'').toLowerCase();
    const country = (document.getElementById('cb-country')?.value||'').toLowerCase();
    const city = (document.getElementById('cb-city')?.value||'').toLowerCase();
    let data = (window._cbAll||[]).filter(r => {
        const hay = ((r.club_name||'')+(r.captain_email||'')+(r.city||'')+(r.country||'')).toLowerCase();
        if (qy && !hay.includes(qy)) return false;
        if (country && !(r.country||'').toLowerCase().includes(country)) return false;
        if (city && !(r.city||'').toLowerCase().includes(city)) return false;
        return true;
    });
    if (!data.length) { container.innerHTML = `<div style="text-align:center;padding:40px;color:#555;"><i class='bx bx-shield' style="font-size:36px;display:block;margin-bottom:10px;opacity:0.4;"></i><div style="font-size:14px;font-weight:700;color:#aaa;">Ningún club busca jugadores con ese filtro</div></div>`; return; }
    container.innerHTML = data.map(r => {
        const logo = r.logo ? `<img src="${r.logo}" style="width:42px;height:42px;border-radius:8px;object-fit:contain;background:#0a0a0a;border:1px solid #2a2a2a;flex-shrink:0;" onerror="this.style.display='none'">` : `<div style="width:42px;height:42px;border-radius:8px;background:rgba(186,255,0,0.1);border:1px solid rgba(186,255,0,0.3);display:flex;align-items:center;justify-content:center;color:var(--accent);font-size:20px;flex-shrink:0;"><i class='bx bxs-shield'></i></div>`;
        const matchesHtml = (r.matches||[]).length ? `<div style="margin-top:10px;border-top:1px solid #1a1a1a;padding-top:10px;">
            <div style="font-size:10px;color:#666;font-weight:800;letter-spacing:.5px;margin-bottom:6px;">PARTIDOS ABIERTOS DE ESTE EQUIPO</div>
            ${r.matches.map(m=>{
                const when = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{weekday:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
                const left = (m.slots_total||0)-(m.slots_taken||0);
                return `<div onclick="event.stopPropagation();window.viewMatchDetails&&window.viewMatchDetails('${m.id}')" style="display:flex;align-items:center;justify-content:space-between;gap:8px;background:#0d0d0d;border:1px solid #1a1a1a;border-radius:10px;padding:8px 10px;margin-bottom:6px;cursor:pointer;">
                    <div style="min-width:0;"><div style="font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${m.name||'Partido'}</div><div style="font-size:10px;color:#666;">${when}${m.venue?' · '+m.venue:''}</div></div>
                    <span style="font-size:10px;color:${left>0?'#00e676':'#888'};font-weight:800;white-space:nowrap;">${left>0?left+' libre'+(left!==1?'s':''):'lleno'}</span>
                </div>`;
            }).join('')}
        </div>` : '';
        return `<div onclick="window.viewClubProfile&&window.viewClubProfile('${r.id}')" style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:14px;margin-bottom:10px;cursor:pointer;transition:.15s;" onmouseover="this.style.borderColor='rgba(186,255,0,0.25)'" onmouseout="this.style.borderColor='#1e1e1e'">
            <div style="display:flex;align-items:center;gap:12px;">
                ${logo}
                <div style="flex:1;min-width:0;">
                    <div style="font-weight:800;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${r.club_name || 'Club'}</div>
                    <div style="font-size:11px;color:#888;">${r.fmt} · plantilla ${r.have}/${r.total}${[r.city,r.country].filter(Boolean).length?' · '+[r.city,r.country].filter(Boolean).join(', '):''}</div>
                </div>
                ${r.missing_count>0?`<span style="background:rgba(186,255,0,0.12);color:var(--accent);border:1px solid rgba(186,255,0,0.3);font-size:10px;font-weight:900;padding:4px 9px;border-radius:10px;white-space:nowrap;">Faltan ${r.missing_count}</span>`:''}
            </div>
            ${matchesHtml}
            <button onclick="event.stopPropagation();window.viewClubProfile&&window.viewClubProfile('${r.id}')" style="width:100%;margin-top:10px;background:var(--accent);color:#000;border:none;border-radius:10px;padding:9px;font-weight:900;font-size:12px;cursor:pointer;"><i class='bx bx-user-plus'></i> VER EQUIPO Y UNIRME</button>
        </div>`;
    }).join('');
};

window.sendJoinRequest = async function(requestId, clubName) {
    const sb = _sb || window._sb;
    const me = window.userData;
    if (!sb || !me) { showToast('Iniciá sesión primero.', 'warning'); return; }
    try {
        await sb.from('squad_request_applicants').insert({
            request_id: requestId, user_email: me.email, user_name: me.name, status: 'pending'
        });
    } catch(e) { /* tabla puede no existir */ }
    showToast('✅ Solicitud enviada a ' + clubName + '!', 'success');
};

function _timeAgo(iso) {
    try {
        const diff = Date.now() - new Date(iso).getTime();
        if (diff < 60000) return 'ahora';
        if (diff < 3600000) return Math.floor(diff/60000) + 'm';
        if (diff < 86400000) return Math.floor(diff/3600000) + 'h';
        return Math.floor(diff/86400000) + 'd';
    } catch(e) { return ''; }
}

