window.setPartidosFilter = async function(filter, btn) {
    document.querySelectorAll('.partidos-fbtn').forEach(b => {
        b.style.borderColor = '#333'; b.style.background = 'transparent'; b.style.color = '#aaa';
    });
    if (btn) { btn.style.borderColor = 'var(--accent)'; btn.style.background = 'rgba(186,255,0,0.1)'; btn.style.color = 'var(--accent)'; }

    const list = document.getElementById('partidos-list');
    if (!list || !_sb) return;
    list.innerHTML = `<div style="text-align:center;padding:30px;color:#555;"><i class='bx bx-loader-alt bx-spin' style="font-size:24px;"></i></div>`;

    try {
        const me = window.userData;
        let query = _sb.from('matches').select('id,name,modality,venue,scheduled_at,slots_total,slots_taken,price,match_type,city').eq('match_type','open').gte('scheduled_at', new Date().toISOString()).order('scheduled_at',{ascending:true}).limit(30);
        if (filter === 'ciudad' && me && (me.city || me.dept)) {
            query = query.eq('city', me.city || me.dept);
        }
        const { data } = await query;
        let filtered = data || [];
        if (filter === 'abiertos') {
            filtered = filtered.filter(m => (m.slots_total||10) - (m.slots_taken||0) > 0);
        }
        if (!filtered.length) {
            list.innerHTML = `<div style="text-align:center;padding:40px;color:#666;"><i class='bx bx-football' style="font-size:40px;display:block;margin-bottom:12px;opacity:0.4;"></i><div>No hay partidos${filter==='abiertos'?' con lugares disponibles':filter==='ciudad'?' en tu ciudad':''}</div></div>`;
            return;
        }
        list.innerHTML = filtered.map(m => {
            const when = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{weekday:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : 'Sin fecha';
            const total = m.slots_total || 10;
            const taken = m.slots_taken || 0;
            const missing = total - taken;
            const missingBadge = missing > 0
                ? `<span style="background:rgba(0,230,118,0.15);color:#00e676;border:1px solid rgba(0,230,118,0.3);border-radius:20px;padding:2px 8px;font-size:10px;font-weight:700;white-space:nowrap;">Faltan ${missing}</span>`
                : `<span style="background:rgba(255,68,68,0.1);color:#ff4444;border:1px solid rgba(255,68,68,0.3);border-radius:20px;padding:2px 8px;font-size:10px;font-weight:700;white-space:nowrap;">COMPLETO</span>`;
            return `<div class="match-list-item">
                <div class="match-info">
                    <div class="match-type-badge">${m.modality||'F5'}</div>
                    <div class="match-details">
                        <h4>${m.name||'Partido'}</h4>
                        <div class="match-meta">
                            <span><i class='bx bx-map'></i> ${m.venue||'—'}</span>
                            <span><i class='bx bx-time'></i> ${when}</span>
                            <span><i class='bx bx-user'></i> ${taken}/${total}</span>
                        </div>
                    </div>
                </div>
                <div style="display:flex;align-items:center;gap:8px;flex-direction:column;align-items:flex-end;">
                    ${missingBadge}
                    <div style="display:flex;align-items:center;gap:8px;">
                        <div class="match-price">${m.price?'$'+m.price:'Gratis'}</div>
                        ${missing > 0 ? `<button class="btn btn-outline" onclick="window.cancheroFeatures&&window.cancheroFeatures.matchRequests.requestJoin('${m.id}')">UNIRME</button>` : `<button class="btn btn-glass" disabled style="opacity:0.4;cursor:not-allowed;">LLENO</button>`}
                    </div>
                </div>
            </div>`;
        }).join('');
    } catch(e) {
        list.innerHTML = `<div style="text-align:center;padding:30px;color:#888;">Error: ${e.message}</div>`;
    }
};

// Activar filtro "faltan jugadores" en buscar-partidos
window.switchPartidosTab = function(tab) {
    if (tab === 'buscan-jugador') {
        window._partidosView = 'buscan';
        // Abrir el modal centralizado de búsqueda de jugadores disponibles
        // y mostrar partidos con lugares libres
        if (typeof switchDashboardTab === 'function') switchDashboardTab('jugador','buscar-partidos',null);
        setTimeout(() => {
            const list = document.getElementById('partidos-list');
            if (!list) return;
            const sbP = window._sb;
            if (!sbP) return;
            list.innerHTML = '<div style="text-align:center;padding:20px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i><div style="margin-top:6px;font-size:12px;">Cargando partidos que buscan jugadores...</div></div>';
            sbP.from('matches').select('*').gte('scheduled_at', new Date().toISOString()).order('scheduled_at',{ascending:true}).limit(40)
            .then(({ data }) => {
                const matches = (data||[]).filter(m => {
                    const total = m.slots_total || 10;
                    const taken = m.slots_taken || 0;
                    return (total - taken) > 0;
                });
                if (!matches.length) {
                    list.innerHTML = '<div style="text-align:center;padding:40px;color:#666;font-size:13px;"><i class="bx bx-user-x" style="font-size:40px;display:block;margin-bottom:10px;opacity:0.3;"></i>No hay partidos buscando jugadores ahora.</div>';
                    return;
                }
                const myEmail = userData?.email;
                list.innerHTML = `<div style="padding:0 0 8px;"><div style="font-size:11px;color:var(--accent);font-weight:900;letter-spacing:1px;margin-bottom:10px;"><i class="bx bx-user-plus"></i> ${matches.length} PARTIDO${matches.length!==1?'S':''} BUSCANDO JUGADORES</div>` +
                    matches.map(m => {
                        const slotsLeft = Math.max(0,(m.slots_total||10)-(m.slots_taken||0));
                        const date = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY',{weekday:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : 'Sin fecha';
                        const isMine = m.created_by === myEmail;
                        return `<div style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:14px;margin-bottom:10px;" onclick="window.viewMatchDetails&&window.viewMatchDetails('${m.id}')">
                            <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px;">
                                <div style="font-weight:800;font-size:13px;flex:1;">${m.name||'Partido'}</div>
                                <span style="background:rgba(186,255,0,0.12);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:20px;padding:3px 10px;font-size:10px;font-weight:900;white-space:nowrap;flex-shrink:0;">${slotsLeft} LIBRE${slotsLeft!==1?'S':''}</span>
                            </div>
                            <div style="font-size:11px;color:#666;display:flex;gap:10px;flex-wrap:wrap;margin-bottom:8px;">
                                <span><i class="bx bx-map"></i> ${m.venue||m.city||'Sin cancha'}</span>
                                <span><i class="bx bx-time"></i> ${date}</span>
                            </div>
                            ${!isMine ? `<button onclick="event.stopPropagation();joinOpenMatch&&joinOpenMatch('${m.id}')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:10px;padding:9px;font-weight:900;font-size:12px;cursor:pointer;"><i class="bx bx-user-plus"></i> UNIRME</button>` : '<div style="font-size:10px;color:#555;text-align:center;">Tu partido</div>'}
                        </div>`;
                    }).join('') + '</div>';
            }).catch(() => {
                list.innerHTML = '<div style="padding:20px;text-align:center;color:#f44;">Error al cargar.</div>';
            });
        }, 300);
    }
};

