window.switchMisPartidosTab = function(tab, el) {
    document.querySelectorAll('.mis-partidos-tab').forEach(function(b) {
        b.style.borderBottom = '2px solid transparent';
        b.style.color = '#666';
        b.style.fontWeight = '700';
        b.classList.remove('active');           // quitar clase para que el ícono no quede verde
        const ic = b.querySelector('i'); if (ic) ic.style.color = '#666';
    });
    if (el) { el.style.borderBottom = '2px solid var(--accent)'; el.style.color = '#fff'; el.style.fontWeight = '900'; el.classList.add('active'); const ic=el.querySelector('i'); if(ic) ic.style.color='var(--accent)'; }
    if (tab === 'calendario') {
        window._loadMatchCalendar();
    } else {
        loadMisPartidos(tab);
    }
};

// Swipe horizontal en tabs de mis-partidos
window._mptSwipe = function(e, container) {
    const dx = e.changedTouches[0].clientX - (window._mptTouchX || 0);
    if (Math.abs(dx) < 40) return;
    const tabs = ['creados','calendario','invitados','abiertos','solicitudes'];
    const active = container.querySelector('.mis-partidos-tab[style*="var(--accent)"]');
    const btns = Array.from(container.querySelectorAll('.mis-partidos-tab'));
    const ids = ['mpt-creados','mpt-calendario','mpt-invitados','mpt-abiertos','mpt-solicitudes'];
    let idx = btns.indexOf(active);
    if (idx < 0) idx = 0;
    const next = dx < 0 ? Math.min(idx+1, tabs.length-1) : Math.max(idx-1, 0);
    if (next !== idx) {
        const btn = document.getElementById(ids[next]);
        if (btn) window.switchMisPartidosTab(tabs[next], btn);
    }
};

// ============================================================
// CALENDARIO DE PARTIDOS
// ============================================================
window._matchCalendarFilters = { tipo: 'todos', precio: 'todos', fecha: null };

window._loadMatchCalendar = async function() {
    const container = document.getElementById('mis-partidos-content');
    if (!container) return;
    container.innerHTML = `
        <div style="padding:12px 0;">
            <!-- Filtros del calendario -->
            <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;padding:0 4px;">
                <div style="flex:1;display:flex;align-items:center;gap:8px;background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:8px 12px;">
                    <i class='bx bx-search' style="color:#555;font-size:16px;flex-shrink:0;"></i>
                    <input id="cal-search" type="text" placeholder="Buscar partido..." style="background:none;border:none;color:#fff;width:100%;outline:none;font-size:12px;" oninput="window._filterCalendar()">
                </div>
            </div>
            <div style="display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding-bottom:8px;margin-bottom:12px;">
                ${['Todos','Amistoso','Torneo','Liga','Abierto'].map((t,i) =>
                    `<button class="cal-tipo-btn${i===0?' cal-active':''}" data-tipo="${t.toLowerCase()}" onclick="window._setCalTipo(this)"
                        style="flex-shrink:0;padding:7px 14px;border-radius:20px;border:1px solid ${i===0?'var(--accent)':'#222'};background:${i===0?'rgba(186,255,0,0.1)':'transparent'};color:${i===0?'var(--accent)':'#666'};font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">${t}</button>`
                ).join('')}
                <button class="cal-tipo-btn" data-tipo="precio" onclick="window._togglePrecioFilter(this)"
                    style="flex-shrink:0;padding:7px 14px;border-radius:20px;border:1px solid #222;background:transparent;color:#666;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">💲 Precio</button>
            </div>
            <!-- Días del mes -->
            <div id="cal-days-strip" style="display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding-bottom:8px;margin-bottom:14px;"></div>
            <!-- Lista de partidos -->
            <div id="cal-matches-list"></div>
        </div>`;
    window._buildCalendarDays();
    window._markCalDaysWithMatches();
    await window._fetchAndRenderCalMatches();
};

// Marca con un punto los días que tienen partidos (creados + donde participo)
window._markCalDaysWithMatches = async function() {
    const sb = window._sb;
    const email = window.userData?.email;
    if (!sb || !email) return;
    try {
        const dates = new Set();
        const r1 = await sb.from('matches').select('scheduled_at').eq('created_by', email).gte('scheduled_at', new Date(Date.now()-86400000).toISOString()).limit(80);
        (r1?.data||[]).forEach(m=>{ if(m.scheduled_at) dates.add(m.scheduled_at.split('T')[0]); });
        try {
            const mp = await sb.from('match_players').select('match_id').eq('player_email', email).limit(80);
            const ids = (mp?.data||[]).map(x=>x.match_id);
            if (ids.length){ const r2 = await sb.from('matches').select('scheduled_at').in('id', ids); (r2?.data||[]).forEach(m=>{ if(m.scheduled_at) dates.add(m.scheduled_at.split('T')[0]); }); }
        } catch(e){}
        dates.forEach(d=>{
            const btn = document.querySelector(`.cal-day-btn[data-date="${d}"]`);
            if (btn && !btn.querySelector('.cal-day-dot')){
                const dot=document.createElement('div'); dot.className='cal-day-dot';
                dot.style.cssText='width:5px;height:5px;border-radius:50%;background:var(--accent);margin-top:3px;box-shadow:0 0 5px var(--accent);';
                btn.appendChild(dot);
            }
        });
    } catch(e){}
};

window._buildCalendarDays = function() {
    const strip = document.getElementById('cal-days-strip');
    if (!strip) return;
    const today = new Date();
    const days = [];
    for (let i = -1; i <= 29; i++) {
        const d = new Date(today); d.setDate(today.getDate() + i);
        days.push(d);
    }
    const dayNames = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
    strip.innerHTML = days.map((d, idx) => {
        const isToday = idx === 1;
        const dateStr = d.toISOString().split('T')[0];
        return `<button class="cal-day-btn${isToday?' cal-day-active':''}" data-date="${dateStr}"
            onclick="window._selectCalDay(this,'${dateStr}')"
            style="flex-shrink:0;display:flex;flex-direction:column;align-items:center;padding:8px 10px;border-radius:12px;border:1px solid ${isToday?'var(--accent)':'#1e1e1e'};background:${isToday?'rgba(186,255,0,0.1)':'transparent'};cursor:pointer;min-width:48px;">
            <div style="font-size:9px;color:${isToday?'var(--accent)':'#555'};font-weight:700;">${dayNames[d.getDay()]}</div>
            <div style="font-size:16px;font-weight:900;color:${isToday?'var(--accent)':'#fff'};">${d.getDate()}</div>
        </button>`;
    }).join('');
    // Auto-scroll al día de hoy
    setTimeout(() => {
        const active = strip.querySelector('.cal-day-active');
        if (active) active.scrollIntoView({ inline: 'center', behavior: 'smooth' });
    }, 100);
};

window._selectCalDay = function(btn, dateStr) {
    document.querySelectorAll('.cal-day-btn').forEach(b => {
        b.style.borderColor = '#1e1e1e'; b.style.background = 'transparent';
        b.querySelector('div:last-child').style.color = '#fff';
        b.querySelector('div:first-child').style.color = '#555';
    });
    btn.style.borderColor = 'var(--accent)'; btn.style.background = 'rgba(186,255,0,0.1)';
    btn.querySelectorAll('div').forEach(d => d.style.color = 'var(--accent)');
    window._matchCalendarFilters.fecha = dateStr;
    window._fetchAndRenderCalMatches();
};

window._setCalTipo = function(btn) {
    document.querySelectorAll('.cal-tipo-btn').forEach(b => {
        b.classList.remove('cal-active');
        b.style.borderColor = '#222'; b.style.background = 'transparent'; b.style.color = '#666';
    });
    btn.classList.add('cal-active');
    btn.style.borderColor = 'var(--accent)'; btn.style.background = 'rgba(186,255,0,0.1)'; btn.style.color = 'var(--accent)';
    window._matchCalendarFilters.tipo = btn.dataset.tipo || 'todos';
    window._fetchAndRenderCalMatches();
};

window._togglePrecioFilter = function(btn) {
    const current = window._matchCalendarFilters.precio || 'todos';
    const next = current === 'todos' ? 'gratis' : current === 'gratis' ? 'pago' : 'todos';
    window._matchCalendarFilters.precio = next;
    const labels = { todos: '💲 Precio', gratis: '🆓 Gratis', pago: '💰 De Pago' };
    if (btn) {
        btn.textContent = labels[next];
        btn.style.borderColor = next !== 'todos' ? 'var(--accent)' : '#222';
        btn.style.color = next !== 'todos' ? 'var(--accent)' : '#666';
        btn.style.background = next !== 'todos' ? 'rgba(186,255,0,0.1)' : 'transparent';
    }
    window._fetchAndRenderCalMatches();
};

window._filterCalendar = function() {
    window._fetchAndRenderCalMatches();
};

window._fetchAndRenderCalMatches = async function() {
    const listEl = document.getElementById('cal-matches-list');
    if (!listEl) return;
    listEl.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div>';
    const sb = window._sb;
    if (!sb) { listEl.innerHTML = '<div style="padding:20px;text-align:center;color:#f44;">Sin conexión.</div>'; return; }
    try {
        const { fecha, tipo } = window._matchCalendarFilters;
        const searchQuery = document.getElementById('cal-search')?.value?.trim() || '';
        let query = sb.from('matches').select('*').order('scheduled_at', { ascending: true }).limit(60);
        if (fecha) {
            query = query.gte('scheduled_at', fecha + 'T00:00:00').lte('scheduled_at', fecha + 'T23:59:59');
        } else {
            query = query.gte('scheduled_at', new Date().toISOString().split('T')[0] + 'T00:00:00');
        }
        const { data: matches } = await query;
        let filtered = (matches || []);
        // Aplicar filtros en memoria para evitar errores por columnas inexistentes
        if (tipo && tipo !== 'todos') {
            if (tipo === 'abierto') {
                filtered = filtered.filter(m => m.is_open === true || m.match_type === 'open' || m.type === 'abierto' || m.modality === 'abierto');
            } else if (tipo !== 'precio') {
                filtered = filtered.filter(m => {
                    const t = (m.type || m.match_type || '').toLowerCase();
                    return t.includes(tipo);
                });
            }
        }
        // Filtro de precio: mostrar solo partidos con costo > 0
        if (window._matchCalendarFilters.precio === 'pago') {
            filtered = filtered.filter(m => m.cost > 0 || m.price > 0 || m.fee > 0);
        } else if (window._matchCalendarFilters.precio === 'gratis') {
            filtered = filtered.filter(m => !m.cost && !m.price && !m.fee);
        }
        if (searchQuery) filtered = filtered.filter(m => (m.title || m.name || '').toLowerCase().includes(searchQuery.toLowerCase()) || (m.location || m.venue || '').toLowerCase().includes(searchQuery.toLowerCase()));

        if (!filtered.length) {
            listEl.innerHTML = `<div style="text-align:center;padding:40px;color:#555;">
                <i class='bx bx-calendar-x' style="font-size:36px;display:block;margin-bottom:10px;opacity:0.3;"></i>
                <div style="font-size:13px;color:#aaa;">No hay partidos${fecha ? ' para este día' : ' próximos'}.</div>
            </div>`; return;
        }

        // Agrupar por día
        const byDay = {};
        filtered.forEach(m => {
            const d = (m.scheduled_at || '').split('T')[0] || 'Sin fecha';
            if (!byDay[d]) byDay[d] = [];
            byDay[d].push(m);
        });

        listEl.innerHTML = Object.entries(byDay).map(([day, dayMatches]) => {
            const dayDate = day !== 'Sin fecha' ? new Date(day + 'T12:00:00') : null;
            const dayLabel = dayDate ? dayDate.toLocaleDateString('es-UY', { weekday:'long', day:'numeric', month:'long' }) : 'Sin fecha';
            return `<div style="margin-bottom:16px;">
                <div style="font-size:11px;color:#555;font-weight:900;letter-spacing:1px;margin-bottom:8px;text-transform:uppercase;">${dayLabel}</div>
                ${dayMatches.map(m => window._renderCalMatchCard(m)).join('')}
            </div>`;
        }).join('');
    } catch(e) {
        listEl.innerHTML = `<div style="padding:20px;text-align:center;color:#f44;font-size:12px;">Error: ${e.message}</div>`;
    }
};

window._renderCalMatchCard = function(m) {
    const hora = m.scheduled_at ? new Date(m.scheduled_at).toLocaleTimeString('es-UY', { hour:'2-digit', minute:'2-digit' }) : '--:--';
    const slots = m.slots_total || 0;
    const filled = m.slots_filled || 0;
    const available = Math.max(0, slots - filled);
    const isOpen = m.is_open;
    const tipo = (m.type || m.match_type || 'Amistoso').replace(/_/g,' ');
    const loc = m.location || m.venue || 'Cancha por confirmar';
    const precio = m.price || m.price_per_player;
    const hasCover = m.cover_url || m.photo_url;
    const meEmail = window.userData?.email;
    const isCreator = meEmail && m.created_by === meEmail;

    return `<div onclick="window._openMatchDetail('${m.id}')"
        style="background:#111;border:1px solid #1e1e1e;border-radius:14px;margin-bottom:10px;overflow:hidden;cursor:pointer;transition:.15s;"
        onmouseover="this.style.borderColor='rgba(186,255,0,0.2)'" onmouseout="this.style.borderColor='#1e1e1e'">
        ${hasCover ? `<div style="height:80px;background-image:url('${hasCover}');background-size:cover;background-position:center;"></div>` : ''}
        <div style="padding:12px 14px;">
            <div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:8px;">
                <div style="background:rgba(186,255,0,0.08);border:1px solid rgba(186,255,0,0.15);border-radius:8px;padding:6px 10px;text-align:center;min-width:44px;flex-shrink:0;">
                    <div style="font-size:14px;font-weight:900;color:var(--accent);">${hora}</div>
                    <div style="font-size:8px;color:#555;font-weight:700;">HS</div>
                </div>
                <div style="flex:1;">
                    <div style="font-weight:900;font-size:13px;margin-bottom:2px;">${m.title || m.name || 'Partido'}</div>
                    <div style="font-size:10px;color:#555;display:flex;align-items:center;gap:6px;">
                        <i class='bx bx-map-pin'></i>${loc}
                    </div>
                </div>
                ${isOpen ? `<div style="background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.2);border-radius:8px;padding:3px 8px;font-size:9px;font-weight:900;">ABIERTO</div>` : ''}
            </div>
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
                <span style="font-size:10px;color:#666;background:#0d0d0d;border-radius:6px;padding:3px 8px;">${tipo}</span>
                ${precio ? `<span style="font-size:10px;color:#888;background:#0d0d0d;border-radius:6px;padding:3px 8px;">💲 $${precio}</span>` : ''}
                ${slots > 0 ? `<span style="font-size:10px;color:${available > 0 ? '#4CAF50' : '#f44'};background:#0d0d0d;border-radius:6px;padding:3px 8px;">👥 ${available > 0 ? available + ' lugares' : 'Completo'}</span>` : ''}
                ${m.duration ? `<span style="font-size:10px;color:#888;background:#0d0d0d;border-radius:6px;padding:3px 8px;">⏱ ${m.duration}min</span>` : ''}
            </div>
        </div>
    </div>`;
};

window._openMatchDetail = async function(matchId) {
    if (!matchId) return;
    const sb = window._sb;
    if (!sb) return;
    const existing = document.getElementById('match-detail-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'match-detail-modal';
    modal.style.cssText = 'position:fixed;left:0;right:0;bottom:0;top:'+(window._navH?window._navH():0)+'px;z-index:9990;background:#0a0a0a;overflow-y:auto;';
    modal.innerHTML = '<div style="text-align:center;padding:60px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:28px;"></i></div>';
    document.body.appendChild(modal);
    try {
        const { data: m } = await sb.from('matches').select('*').eq('id', matchId).maybeSingle();
        if (!m) { modal.innerHTML = '<div style="padding:30px;text-align:center;color:#f44;">Partido no encontrado.</div>'; return; }
        const { data: players } = await sb.from('match_players').select('*').eq('match_id', matchId).limit(30);
        const { data: checkins } = await sb.from('match_checkins').select('*').eq('match_id', matchId).limit(30);
        const meEmail = window.userData?.email;
        const isCreator = meEmail && m.created_by === meEmail;
        const hora = m.scheduled_at ? new Date(m.scheduled_at).toLocaleString('es-UY', { weekday:'long', day:'numeric', month:'long', hour:'2-digit', minute:'2-digit' }) : 'Sin fecha';
        const tipo = (m.type || m.match_type || 'Amistoso').replace(/_/g,' ');
        const slots = m.slots_total || 0;
        const filled = m.slots_filled || (players||[]).length;
        const available = Math.max(0, slots - filled);
        const playerList = (players||[]);
        // match_checkins usa user_email (no player_email)
        const checkinSet = new Set((checkins||[]).map(c => c.user_email || c.player_email));

        modal.innerHTML = `
        <div style="max-width:680px;margin:0 auto;">
            <!-- Header con portada -->
            ${m.cover_url || m.photo_url ? `<div style="height:200px;background-image:url('${m.cover_url||m.photo_url}');background-size:cover;background-position:center;position:relative;">` : `<div style="height:120px;background:linear-gradient(135deg,#0d1a0d,#0a0a0a);position:relative;">`}
                <button onclick="document.getElementById('match-detail-modal').remove()" style="position:absolute;top:14px;left:14px;width:36px;height:36px;border-radius:50%;background:rgba(0,0,0,0.7);border:none;color:#fff;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class='bx bx-arrow-back'></i></button>
                <div style="position:absolute;bottom:14px;left:14px;"><div style="background:rgba(0,0,0,0.7);color:var(--accent);border-radius:6px;padding:4px 10px;font-size:10px;font-weight:900;">${tipo.toUpperCase()}</div></div>
            </div>
            <div style="padding:16px;">
                <h1 style="font-size:22px;font-weight:900;margin-bottom:6px;">${m.title || m.name || 'Partido'}</h1>
                ${m.description ? `<p style="font-size:13px;color:#aaa;margin-bottom:12px;line-height:1.6;">${m.description}</p>` : ''}
                <!-- Info rápida -->
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;">
                    ${[
                        { icon:'bx-calendar', label:'Fecha y hora', val: hora },
                        { icon:'bx-map-pin', label:'Lugar', val: m.location || m.venue || 'Por confirmar' },
                        { icon:'bx-group', label:'Jugadores', val: `${filled}/${slots > 0 ? slots : '?'} · ${available > 0 ? available+' lugares' : 'Completo'}` },
                        { icon:'bx-money', label:'Precio', val: m.price ? '$'+m.price+' /jugador' : 'Gratis' },
                        { icon:'bx-time', label:'Duración', val: m.duration ? m.duration+'min' : 'No especificada' },
                        { icon:'bx-shield', label:'Modalidad', val: m.modality || m.format || 'No especificada' }
                    ].map(item => `<div style="background:#111;border:1px solid #1e1e1e;border-radius:10px;padding:10px 12px;">
                        <div style="font-size:9px;color:#555;font-weight:900;letter-spacing:1px;margin-bottom:2px;"><i class='bx ${item.icon}'></i> ${item.label.toUpperCase()}</div>
                        <div style="font-size:12px;font-weight:700;color:#fff;">${item.val}</div>
                    </div>`).join('')}
                </div>
                <!-- Organizador -->
                <div style="background:#111;border:1px solid #1e1e1e;border-radius:12px;padding:12px;margin-bottom:14px;display:flex;align-items:center;gap:10px;cursor:pointer;" onclick="window.viewUserProfile&&window.viewUserProfile('${m.created_by||''}')">
                    <div style="width:40px;height:40px;border-radius:50%;background:rgba(186,255,0,0.1);border:2px solid rgba(186,255,0,0.3);display:flex;align-items:center;justify-content:center;font-weight:900;font-size:16px;color:var(--accent);">O</div>
                    <div>
                        <div style="font-size:10px;color:#555;font-weight:700;">ORGANIZADOR</div>
                        <div style="font-size:13px;font-weight:700;">${m.created_by || 'Organizador'}</div>
                    </div>
                    <i class='bx bx-chevron-right' style="margin-left:auto;color:#555;"></i>
                </div>
                <!-- Check-ins y jugadores -->
                ${playerList.length ? `<div style="margin-bottom:14px;">
                    <div style="font-size:11px;color:#555;font-weight:900;letter-spacing:1px;margin-bottom:8px;">CONVOCADOS (${playerList.length})</div>
                    <div style="display:flex;flex-wrap:wrap;gap:6px;">
                        ${playerList.map(p => `<div style="display:flex;align-items:center;gap:6px;background:${checkinSet.has(p.player_email)?'rgba(76,175,80,0.08)':'#111'};border:1px solid ${checkinSet.has(p.player_email)?'rgba(76,175,80,0.3)':'#1e1e1e'};border-radius:8px;padding:5px 10px;font-size:11px;">
                            <div style="width:22px;height:22px;border-radius:50%;background:#1a1a1a;border:1px solid #333;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:900;color:#555;">${(p.player_name||'?')[0]}</div>
                            <span style="font-weight:700;">${p.player_name || p.player_email?.split('@')[0] || 'Jug'}</span>
                            ${checkinSet.has(p.player_email) ? '<span style="color:#4CAF50;font-size:9px;font-weight:900;">✓ CHECK-IN</span>' : ''}
                        </div>`).join('')}
                    </div>
                </div>` : ''}
                <!-- Botones de acción -->
                <div style="display:flex;flex-direction:column;gap:8px;">
                    ${m.is_open && !isCreator ? `<button onclick="window._requestJoinMatch('${matchId}')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:12px;padding:13px;font-weight:900;font-size:14px;cursor:pointer;"><i class='bx bx-user-plus'></i> UNIRSE AL PARTIDO</button>` : ''}
                    ${meEmail && !checkinSet.has(meEmail) && playerList.find(p => p.player_email === meEmail) ? `<button onclick="window._doMatchCheckin('${matchId}')" style="width:100%;background:rgba(76,175,80,0.15);color:#4CAF50;border:1px solid rgba(76,175,80,0.3);border-radius:12px;padding:13px;font-weight:900;font-size:14px;cursor:pointer;"><i class='bx bx-check-circle'></i> HACER CHECK-IN</button>` : ''}
                    <button onclick="window._shareMatchToFriend('${matchId}','${(m.title||'Partido').replace(/'/g,"\\'")}')" style="width:100%;background:#111;color:#fff;border:1px solid #222;border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;"><i class='bx bx-share'></i> Invitar a un amigo</button>
                    ${isCreator ? `<button onclick="window._cancelMatch('${matchId}')" style="width:100%;background:rgba(255,68,68,0.1);color:#f44;border:1px solid rgba(255,68,68,0.2);border-radius:12px;padding:12px;font-weight:700;font-size:13px;cursor:pointer;"><i class='bx bx-x-circle'></i> Cancelar partido</button>` : ''}
                </div>
            </div>
        </div>`;
    } catch(e) {
        modal.innerHTML = `<div style="padding:30px;text-align:center;color:#f44;">Error: ${e.message}<br><button onclick="document.getElementById('match-detail-modal').remove()" style="margin-top:12px;padding:8px 16px;background:#111;border:1px solid #333;color:#fff;border-radius:8px;cursor:pointer;">Cerrar</button></div>`;
    }
};

window._requestJoinMatch = async function(matchId) {
    const sb = window._sb;
    const me = window.userData;
    if (!me) { showToast && showToast('Iniciá sesión para unirte','error'); return; }
    if (!sb) { showToast && showToast('Sin conexión','error'); return; }
    try {
        // Verificar si ya está anotado
        const { data: existing } = await sb.from('match_players').select('id,status').eq('match_id', matchId).eq('player_email', me.email).maybeSingle().catch(()=>({data:null}));
        if (existing) {
            showToast && showToast('Ya estás anotado a este partido ('+existing.status+')','info');
            return;
        }
        // Obtener info del partido para saber si es abierto
        const { data: match } = await sb.from('matches').select('is_open,max_players,created_by,name,team_a_name,team_b_name').eq('id', matchId).maybeSingle();
        if (!match) { showToast && showToast('Partido no encontrado','error'); return; }

        // Insertar solicitud
        const payload = {
            match_id: matchId,
            player_email: me.email,
            player_name: me.name || me.email,
            player_photo: me.photo || me.avatar_url || null,
            status: match.is_open ? 'pendiente' : 'pendiente',
            joined_at: new Date().toISOString()
        };
        const { error } = await sb.from('match_players').insert(payload);
        if (error) {
            if (error.code === '23505') { showToast && showToast('Ya tenés una solicitud enviada para este partido','info'); return; }
            throw error;
        }
        // Notificar al creador del partido
        try {
            const notifMsg = `${me.name || me.email} quiere unirse a "${match.name || 'tu partido'}"`;
            if (window.CancheroNotif?.create) {
                await window.CancheroNotif.create(match.created_by, 'match_invite', me.name, notifMsg);
            } else {
                await sb.from('notifications').insert({ recipient_email: match.created_by, type: 'match_invite', actor_email: me.email, actor_name: me.name, message: notifMsg, read: false }).catch(()=>{});
            }
        } catch(_) {}
        showToast && showToast('✅ Solicitud enviada. El capitán recibirá una notificación.', 'success');
        window._openMatchDetail(matchId);
    } catch(e) {
        showToast && showToast('Error al unirse: ' + (e.message||'intenta de nuevo'), 'error');
        console.error('_requestJoinMatch error:', e);
    }
};

window._doMatchCheckin = async function(matchId) {
    const sb = window._sb;
    const me = window.userData;
    if (!sb || !me) return;
    try {
        await sb.from('match_checkins').upsert({ match_id: matchId, user_email: me.email, checked_in_at: new Date().toISOString() }, { onConflict: 'match_id,user_email' });
        showToast && showToast('¡Check-in realizado! ✓', 'success');
        window._openMatchDetail(matchId);
    } catch(e) {
        showToast && showToast('Error: ' + e.message, 'error');
    }
};

window._shareMatchToFriend = function(matchId, title) {
    const url = window.location.origin + window.location.pathname + '?invite=' + matchId;
    const text = `¡Te invito a un partido en Canchero! "${title}"\n${url}`;
    if (navigator.share) {
        navigator.share({ title: 'Partido en Canchero', text, url }).catch(() => {});
    } else if (navigator.clipboard) {
        navigator.clipboard.writeText(text).then(() => showToast && showToast('Link copiado ✓', 'success'));
    } else {
        prompt('Copiá este link y envialo:', url);
    }
};

window.loadMisPartidos = async function(tab) {
    tab = tab || 'creados';
    const sb = window._sb;
    const email = window.userData && window.userData.email;
    const container = document.getElementById('mis-partidos-content');
    if (!container) return;
    if (!sb || !email) {
        container.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;display:block;margin-bottom:8px;"></i>Conectando...</div>';
        setTimeout(() => window.loadMisPartidos(tab), 1200);
        return;
    }
    container.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div>';

    // Set de partidos donde ya estoy anotado (para mostrar "Ya estás anotado" en vez de "Unirse")
    try {
        window._myJoinedMatchIds = new Set();
        const { data: _mine } = await sb.from('match_players').select('match_id').eq('player_email', email);
        (_mine||[]).forEach(r => window._myJoinedMatchIds.add(r.match_id));
    } catch(e) { if (!window._myJoinedMatchIds) window._myJoinedMatchIds = new Set(); }

    try {
        let matches = [];

        if (tab === 'creados') {
            // Mis partidos = creados por mí + donde estoy confirmado como jugador
            const { data: created } = await sb.from('matches')
                .select('*').eq('created_by', email)
                .order('scheduled_at', { ascending: false }).limit(30);
            let joined = [];
            try {
                const { data: mp } = await sb.from('match_players')
                    .select('match_id').eq('player_email', email)
                    .in('status', ['confirmado','accepted','aceptado','titular']);
                const ids = [...new Set((mp||[]).map(x=>x.match_id))].filter(Boolean);
                if (ids.length) {
                    const { data: jm } = await sb.from('matches').select('*').in('id', ids).limit(30);
                    joined = jm || [];
                }
            } catch(e){}
            const seen = new Set();
            matches = [...(created||[]), ...joined].filter(m => { if (seen.has(m.id)) return false; seen.add(m.id); return true; })
                .sort((a,b)=> new Date(b.scheduled_at||0) - new Date(a.scheduled_at||0));

        } else if (tab === 'invitados') {
            // Usar el nuevo sistema de invites V2 si está disponible
            if (window.CancheroMatchPlayers && typeof window.CancheroMatchPlayers.loadMatchInvitesV2 === 'function') {
                await window.CancheroMatchPlayers.loadMatchInvitesV2(container, email);
                return;
            }
            const { data } = await sb.from('match_invites')
                .select('*, matches(*)')
                .eq('to_email', email).eq('status', 'pendiente')
                .order('created_at', { ascending: false });

            if (data && data.length > 0) {
                container.innerHTML = data.map(function(inv) {
                    return '<div style="background:#111;border:1px solid #222;border-radius:14px;padding:16px;margin-bottom:12px;">' +
                        '<div style="font-size:11px;color:var(--accent);font-weight:700;margin-bottom:6px;">⚽ INVITACIÓN A PARTIDO</div>' +
                        '<div style="font-weight:900;font-size:15px;margin-bottom:4px;">' + ((inv.matches && inv.matches.name) || 'Partido') + '</div>' +
                        '<div style="font-size:12px;color:#888;margin-bottom:10px;">' +
                            '📍 ' + ((inv.matches && inv.matches.venue) || 'Sin cancha') + ' &nbsp;·&nbsp; ' +
                            '📅 ' + ((inv.matches && inv.matches.scheduled_at) ? new Date(inv.matches.scheduled_at).toLocaleDateString('es-UY') : 'Sin fecha') +
                        '</div>' +
                        '<div style="display:flex;gap:8px;">' +
                            '<button onclick="acceptMatchInvite(\'' + inv.id + '\',\'' + inv.match_id + '\')" style="flex:1;background:var(--accent);color:#000;border:none;border-radius:10px;padding:10px;font-weight:900;font-size:12px;cursor:pointer;">✓ ACEPTAR</button>' +
                            '<button onclick="rejectMatchInvite(\'' + inv.id + '\')" style="flex:1;background:#1a1a1a;color:#ff4444;border:1px solid #ff4444;border-radius:10px;padding:10px;font-weight:700;font-size:12px;cursor:pointer;">✗ RECHAZAR</button>' +
                        '</div></div>';
                }).join('');
                return;
            } else {
                container.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;"><i class="bx bx-envelope-open" style="font-size:32px;display:block;margin-bottom:8px;opacity:0.4;"></i>No tenés invitaciones pendientes.</div>';
                return;
            }

        } else if (tab === 'abiertos') {
            // Intentar con múltiples formas en que se puede guardar "abierto"
            const nowIso = new Date().toISOString();
            let abiertosData = [];
            try {
                const { data: d1 } = await sb.from('matches').select('*')
                    .or('match_type.eq.open,match_type.eq.abierto,is_open.eq.true')
                    .neq('created_by', email)
                    .gte('scheduled_at', nowIso)
                    .order('scheduled_at', { ascending: true }).limit(30);
                abiertosData = d1 || [];
            } catch(e) {
                // Fallback: traer todos y filtrar en memoria
                const { data: d2 } = await sb.from('matches').select('*')
                    .neq('created_by', email)
                    .gte('scheduled_at', nowIso)
                    .order('scheduled_at', { ascending: true }).limit(50);
                abiertosData = (d2 || []).filter(m => m.is_open === true || (m.match_type||'').toLowerCase().includes('open') || (m.match_type||'').toLowerCase().includes('abierto'));
            }
            matches = abiertosData;

        } else if (tab === 'solicitudes') {
            // Partidos donde soy creador O capitán
            const { data: mine } = await sb.from('matches')
                .select('*').or('created_by.eq.' + email + ',captain_home_email.eq.' + email + ',captain_away_email.eq.' + email)
                .order('scheduled_at', { ascending: false }).limit(30);
            const myMatches = mine || [];
            if (!myMatches.length) {
                container.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;"><i class="bx bx-user-voice" style="font-size:32px;display:block;margin-bottom:8px;opacity:0.4;"></i>No tenés partidos propios.<br><small style="font-size:11px;opacity:0.7;">Creá un partido para recibir solicitudes.</small></div>';
                return;
            }
            // Selector de partido + contenedor de cards Tinder
            window._misMatchesCache = myMatches;
            var selOpts = myMatches.map(function(m){ return '<option value="' + m.id + '">' + (m.name || 'Partido') + '</option>'; }).join('');
            container.innerHTML = '<div style="margin-bottom:14px;">' +
                '<label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:6px;">ELEGÍ TU PARTIDO</label>' +
                '<select id="solicitudes-match-sel" onchange="renderMatchRequestsTinder(this.value)" style="width:100%;background:#111;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;font-size:13px;">' + selOpts + '</select>' +
                '</div>' +
                '<div id="tinder-requests-container"></div>';
            setTimeout(function(){ renderMatchRequestsTinder(myMatches[0].id); }, 50);
            return;
        }

        // Deduplicar por ID (evitar apariciones múltiples)
        const seenMatchIds = new Set();
        matches = matches.filter(function(m) {
            if (!m || !m.id || seenMatchIds.has(m.id)) return false;
            seenMatchIds.add(m.id); return true;
        });

        if (!matches.length) {
            const emptyMsg = tab === 'creados'
                ? 'No creaste partidos aún.<br><small style="font-size:11px;opacity:0.7;">Tocá el botón verde para crear uno.</small>'
                : 'No hay partidos abiertos disponibles.';
            container.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;"><i class="bx bx-football" style="font-size:32px;display:block;margin-bottom:8px;opacity:0.4;"></i>' + emptyMsg + '</div>';
            return;
        }

        // Precargar mis checkins para mostrar estado correcto
        if (!window._myCheckins) window._myCheckins = new Set();
        try {
            const sbx = sb;
            const matchIds = matches.map(m => m.id);
            if (matchIds.length > 0) {
                const { data: myCI } = await sbx.from('match_checkins').select('match_id').eq('user_email', email).in('match_id', matchIds);
                (myCI || []).forEach(c => window._myCheckins.add(c.match_id));
            }
        } catch(_e) {}

        const _renderCard = function(m) {
            const date = m.scheduled_at ? new Date(m.scheduled_at) : null;
            const dateStr = date ? date.toLocaleDateString('es-UY', { weekday:'short', day:'numeric', month:'short' }) : 'Sin fecha';
            const tStr = date ? date.toLocaleTimeString('es-UY', { hour:'2-digit', minute:'2-digit' }) : '';
            const slots = (m.slots_total||10) - (m.slots_taken||0);
            const isMine = m.created_by === email;
            // Check-in window
            const now = Date.now();
            const matchTime = date ? date.getTime() : 0;
            const inCheckinWindow = matchTime > 0 && now >= (matchTime - 15*60000) && now <= (matchTime + 10*60000);
            const alreadyCheckedIn = window._myCheckins.has(m.id);
            const checkinHtml = inCheckinWindow
                ? (alreadyCheckedIn
                    ? '<div style="background:rgba(0,230,118,0.1);border:1px solid #00e676;border-radius:10px;padding:8px;text-align:center;font-size:11px;font-weight:700;color:#00e676;margin-top:8px;"><i class=\'bx bx-check-circle\'></i> Check-in realizado ✓</div>'
                    : '<button id="checkin-btn-' + m.id + '" onclick="window._doMatchCheckin(\'' + m.id + '\',\'' + (email||'').replace(/'/g,"\\'") + '\',\'' + (m.price||0) + '\')" style="width:100%;background:var(--accent);color:#000;border:none;border-radius:10px;padding:10px;font-weight:900;font-size:13px;cursor:pointer;margin-top:8px;"><i class=\'bx bx-qr-scan\'></i> HACER CHECK-IN ⚽</button>')
                : '';
            const nameEsc = (m.name||'Partido').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
            const venueEsc = (m.venue||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
            const captEsc = (m.created_by||'').replace(/'/g,"\\'");
            const mMod = (m.modality || m.match_type || 'abierto').toLowerCase();
            const modBadge = mMod.includes('cerr')
                ? '<span style="background:#ff4444;color:#fff;font-size:9px;font-weight:900;padding:2px 8px;border-radius:8px;margin-right:6px;">🔒 CERRADO</span>'
                : mMod.includes('amist') || m.is_friendly
                ? '<span style="background:#9c88ff;color:#fff;font-size:9px;font-weight:900;padding:2px 8px;border-radius:8px;margin-right:6px;">🤝 AMISTOSO</span>'
                : '<span style="background:#00e676;color:#000;font-size:9px;font-weight:900;padding:2px 8px;border-radius:8px;margin-right:6px;">ABIERTO</span>';
            // Escudos: usar logos del club si están disponibles
            var homeLogo = m.home_club_logo || m.team_a_logo || '';
            var awayLogo = m.away_club_logo || m.team_b_logo || '';
            var homeName = m.home_club_name || m.team_a_name || 'LOCAL';
            var awayName = m.away_club_name || m.team_b_name || 'VISITANTE';
            var homeInitial = (homeName[0]||'L').toUpperCase();
            var awayInitial = (awayName[0]||'V').toUpperCase();
            // Marcador en vivo en la tarjeta: si hay goles cargados, mostrar score
            // (no solo si está finalizado). Antes la tarjeta solo dibujaba el VS.
            var _hasScore = (m.home_score != null && m.away_score != null);
            var _stRaw = (m.status||'').toLowerCase();
            var _isLive = _stRaw==='live' || _stRaw==='en_vivo' || _stRaw==='envivo' || _stRaw==='en_juego' || m.is_live ||
                (!_stRaw && m.started_at && !m.finished_at);
            var _isFinTag = _stRaw==='finished' || _stRaw==='finalizado' || _stRaw==='terminado' || m.finished_at;
            var _scoreBlock = _hasScore
                ? '<div style="text-align:center;display:flex;flex-direction:column;align-items:center;gap:4px;">'
                    + '<div style="font-size:24px;font-weight:900;color:#fff;letter-spacing:2px;line-height:1;">'+(m.home_score||0)+' <span style="color:var(--accent);">-</span> '+(m.away_score||0)+'</div>'
                    + (_isLive ? '<span style="background:#ff3b3b;color:#fff;font-size:8px;font-weight:900;padding:2px 7px;border-radius:8px;animation:bpPulse 1.4s infinite;">● EN VIVO</span>'
                        : _isFinTag ? '<span style="background:#222;color:#aaa;font-size:8px;font-weight:900;padding:2px 7px;border-radius:8px;">FINAL</span>'
                        : '<span style="background:rgba(186,255,0,0.1);color:var(--accent);font-size:8px;font-weight:900;padding:2px 7px;border-radius:8px;">PARCIAL</span>')
                + '</div>'
                : '<div style="font-size:16px;font-weight:900;color:#555;">VS</div>';
            var shieldHtml = (
                '<div style="display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:10px;padding:10px 0;border-bottom:1px solid #1a1a1a;">' +
                    '<div style="text-align:center;flex:1;">' +
                        (homeLogo ? '<img src="'+homeLogo+'" style="width:36px;height:36px;object-fit:contain;border-radius:8px;border:1px solid #333;background:#0a0a0a;" onerror="this.style.display=\'none\'">' : '<div style="width:36px;height:36px;border-radius:8px;background:rgba(186,255,0,0.1);border:1px solid rgba(186,255,0,0.3);display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--accent);font-size:14px;margin:0 auto;">'+homeInitial+'</div>') +
                        '<div style="font-size:9px;color:#888;font-weight:700;margin-top:3px;max-width:60px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+homeName+'</div>' +
                    '</div>' +
                    _scoreBlock +
                    '<div style="text-align:center;flex:1;">' +
                        (awayLogo ? '<img src="'+awayLogo+'" style="width:36px;height:36px;object-fit:contain;border-radius:8px;border:1px solid #333;background:#0a0a0a;" onerror="this.style.display=\'none\'">' : '<div style="width:36px;height:36px;border-radius:8px;background:rgba(100,100,255,0.1);border:1px solid rgba(100,100,255,0.3);display:flex;align-items:center;justify-content:center;font-weight:900;color:#6464ff;font-size:14px;margin:0 auto;">'+awayInitial+'</div>') +
                        '<div style="font-size:9px;color:#888;font-weight:700;margin-top:3px;max-width:60px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+awayName+'</div>' +
                    '</div>' +
                '</div>');
            return '<div style="background:#111;border:1px solid #1e1e1e;border-radius:14px;padding:16px;margin-bottom:12px;position:relative;" onclick="window.viewMatchDetails&&window.viewMatchDetails(\'' + m.id + '\')" >' +
                shieldHtml +
                '<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">' + modBadge + (isMine ? '<span style="background:rgba(186,255,0,0.1);color:var(--accent);font-size:9px;font-weight:900;padding:2px 8px;border-radius:8px;">⚽ CAPITÁN</span>' : '') + '</div>' +
                '<div style="font-weight:900;font-size:15px;margin-bottom:6px;" onclick="event.stopPropagation()">' + (m.name || 'Partido') + '</div>' +
                '<div style="display:flex;gap:12px;font-size:12px;color:#888;margin-bottom:10px;flex-wrap:wrap;">' +
                    '<span>📅 ' + dateStr + ' ' + tStr + '</span>' +
                    '<span>📍 ' + (m.venue || m.city || 'Sin cancha') + '</span>' +
                    '<span>👥 ' + (slots > 0 ? slots + ' lugares libres' : 'COMPLETO') + '</span>' +
                '</div>' +
                '<div style="display:flex;gap:8px;flex-wrap:wrap;" onclick="event.stopPropagation()">' +
                    (isMine ?
                        '<button onclick="window.viewMatchDetails(\'' + m.id + '\')" style="flex:1;min-width:80px;background:var(--accent);color:#000;border:none;border-radius:10px;padding:9px;font-size:11px;font-weight:900;cursor:pointer;"><i class=\'bx bx-detail\'></i> PANEL</button>' +
                        '<button onclick="shareMatch(\'' + m.id + '\',\'' + nameEsc + '\',\'' + venueEsc + '\',\'' + dateStr + ' ' + tStr + '\')" style="flex:1;min-width:50px;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:9px;font-size:11px;font-weight:700;cursor:pointer;" title="Compartir"><i class=\'bx bx-share-alt\'></i></button>' +
                        '<button onclick="editMatchOpen(\'' + m.id + '\')" style="flex:1;min-width:44px;background:rgba(255,170,0,0.1);color:#ffaa00;border:1px solid rgba(255,170,0,0.3);border-radius:10px;padding:9px;font-size:11px;font-weight:700;cursor:pointer;" title="Editar"><i class=\'bx bx-edit\'></i></button>' +
                        '<button onclick="deleteMatch(\'' + m.id + '\')" style="flex:1;min-width:44px;background:rgba(255,68,68,0.1);color:#ff4444;border:1px solid rgba(255,68,68,0.3);border-radius:10px;padding:9px;font-size:11px;font-weight:700;cursor:pointer;" title="Eliminar"><i class=\'bx bx-trash\'></i></button>' +
                        (inCheckinWindow ? '<button onclick="window._showCaptainQR(\'' + m.id + '\')" style="flex:1;min-width:50px;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:10px;padding:9px;font-size:11px;cursor:pointer;" title="QR Check-in"><i class=\'bx bx-qr\'></i></button>' : '')
                        :
                        ((window._myJoinedMatchIds && window._myJoinedMatchIds.has(m.id))
                            ? '<div style="flex:1;min-width:80px;background:rgba(0,230,118,0.1);color:#00e676;border:1px solid rgba(0,230,118,0.35);border-radius:10px;padding:9px;font-size:11px;font-weight:900;text-align:center;"><i class=\'bx bx-check-circle\'></i> YA ESTÁS ANOTADO</div>'
                            : '<button onclick="joinOpenMatch(\'' + m.id + '\')" style="flex:1;min-width:80px;background:var(--accent);color:#000;border:none;border-radius:10px;padding:9px;font-size:11px;font-weight:900;cursor:pointer;"><i class=\'bx bx-user-plus\'></i> UNIRSE</button>')
                    ) +
                '</div>' + checkinHtml + '</div>';
        };

        // Separar en PRÓXIMOS y FINALIZADOS
        const _isFinished = function(m){
            const st = (m.status||'').toLowerCase();
            const d = m.scheduled_at ? new Date(m.scheduled_at).getTime() : 0;
            // Si el partido es a futuro, SIEMPRE es próximo (aunque tenga goles cargados en pruebas)
            if (d > 0 && d > Date.now()) return false;
            if (['finished','finalizado','terminado','cancelled','cancelado'].includes(st)) return true;
            if (m.home_score!=null && m.away_score!=null) return true;
            return d > 0 && d < (Date.now() - 3*3600000); // 3h después del horario = finalizado
        };
        const proximos = matches.filter(m=>!_isFinished(m));
        const finalizados = matches.filter(_isFinished);
        const secHead = function(ic,t,n){ return '<div style="font-size:12px;font-weight:900;color:var(--accent);letter-spacing:1px;margin:14px 0 10px;display:flex;align-items:center;gap:7px;"><i class="bx '+ic+'"></i> '+t+' <span style="color:#555;font-weight:700;">('+n+')</span></div>'; };
        let outHtml = '';
        if (proximos.length) outHtml += secHead('bx-calendar','PRÓXIMOS',proximos.length) + proximos.map(_renderCard).join('');
        const _revanchaBtn = function(m){
            return '<div style="margin:-6px 0 12px;"><button onclick="window.pedirRevancha&&window.pedirRevancha(\''+m.id+'\')" style="width:100%;background:rgba(255,170,0,0.1);color:#ffaa00;border:1px solid rgba(255,170,0,0.35);border-radius:10px;padding:9px;font-size:11px;font-weight:800;cursor:pointer;"><i class="bx bx-revision"></i> PEDIR REVANCHA</button></div>';
        };
        // Finalizados: dentro de un desplegable (no se ven directo)
        if (finalizados.length) outHtml += `<details style="margin-top:14px;border:1px solid #1a1a1a;border-radius:12px;background:#0d0d0d;overflow:hidden;">
            <summary style="list-style:none;cursor:pointer;padding:13px 14px;display:flex;align-items:center;gap:8px;font-size:12px;font-weight:900;color:var(--accent);letter-spacing:1px;user-select:none;"><i class="bx bx-flag"></i> FINALIZADOS <span style="color:#555;font-weight:700;">(${finalizados.length})</span><i class="bx bx-chevron-down" style="margin-left:auto;color:#666;"></i></summary>
            <div style="padding:0 14px 8px;">${finalizados.map(m=>_renderCard(m)+_revanchaBtn(m)).join('')}</div>
        </details>`;
        container.innerHTML = outHtml || '<div style="text-align:center;padding:40px;color:#555;font-size:13px;">Sin partidos.</div>';

    } catch(e) {
        console.error('loadMisPartidos error:', e);
        container.innerHTML = '<div style="padding:20px;color:#f44;font-size:12px;">Error cargando partidos.</div>';
    }
};

// Pedir revancha: crea un partido nuevo (mismos equipos/cancha) abierto y notifica al rival
window.pedirRevancha = async function(matchId) {
    const sb = window._sb;
    const email = window.userData && window.userData.email;
    if (!sb || !email) { if (typeof showToast==='function') showToast('Iniciá sesión.', 'warning'); return; }
    try {
        const { data: m } = await sb.from('matches').select('*').eq('id', matchId).single();
        if (!m) { showToast('No se encontró el partido.', 'error'); return; }
        const base = m.scheduled_at ? new Date(m.scheduled_at) : new Date();
        const next = new Date(base.getTime()); next.setDate(next.getDate() + 7); // misma hora, +1 semana
        const nuevo = {
            name: 'Revancha — ' + (m.name || 'Partido'),
            created_by: email,
            venue: m.venue || null, city: m.city || null, country: m.country || null,
            modality: m.modality || null, gender: m.gender || null, format: m.format || null,
            slots_total: m.slots_total || null,
            home_club_name: m.home_club_name || m.team_a_name || null,
            away_club_name: m.away_club_name || m.team_b_name || null,
            scheduled_at: next.toISOString(),
            is_open: true, status: 'abierto'
        };
        const { data: created, error } = await sb.from('matches').insert(nuevo).select('id').single();
        if (error) throw error;
        // Notificar al rival (capitán contrario / creador original)
        const rival = (m.created_by && m.created_by !== email) ? m.created_by : (m.captain_away_email || m.captain_home_email);
        if (rival && window.CancheroNotif) CancheroNotif.create(rival, 'revancha', 'Canchero', 'Te pidieron la revancha de "' + (m.name||'un partido') + '". ¡Aceptá el desafío!');
        if (typeof showToast==='function') showToast('¡Revancha creada! Quedó abierta para una semana.', 'success');
        if (created && window.viewMatchDetails) setTimeout(()=>window.viewMatchDetails(created.id), 400);
    } catch(e) {
        console.error('pedirRevancha error:', e);
        if (typeof showToast==='function') showToast('No se pudo crear la revancha.', 'error');
    }
};

window.acceptMatchInvite = async function(inviteId, matchId) {
    // El invitado elige su equipo (la invitación ya no lo fija)
    try {
        const sbA = window._sb;
        const me = window.userData;
        if (sbA && me) {
            const team = confirm('¿Querés jugar en el equipo LOCAL? (Aceptar = Local · Cancelar = Visitante)') ? 'home' : 'away';
            const natural = (me.pos || me.position) || 'MED';
            await sbA.from('match_players').upsert([{
                match_id: matchId, player_email: me.email, player_name: me.name || me.email,
                team, position: natural, is_sub: false, status: 'confirmado'
            }], { onConflict: 'match_id,player_email' });
        }
    } catch(e) { console.warn('[acceptInvite join]', e); }
    const sb = window._sb;
    const email = window.userData && window.userData.email;
    const name = (window.userData && window.userData.name) || email;
    if (!sb || !email) return;
    try {
        await sb.from('match_invites').update({ status: 'aceptada' }).eq('id', inviteId);
        await sb.from('match_players').insert({ match_id: matchId, player_email: email, player_name: name, status: 'confirmado' }).catch(function() {});
        if (typeof showToast === 'function') showToast('¡Unido al partido! 🎉', 'success');
        loadMisPartidos('invitados');
    } catch(e) {
        if (typeof showToast === 'function') showToast('Error al aceptar invitación.', 'error');
    }
};

window.rejectMatchInvite = async function(inviteId) {
    const sb = window._sb;
    if (!sb) return;
    try {
        await sb.from('match_invites').update({ status: 'rechazada' }).eq('id', inviteId);
        if (typeof showToast === 'function') showToast('Invitación rechazada.', 'default');
        loadMisPartidos('invitados');
    } catch(e) {}
};

window.shareMatch = async function(matchId, name, venue, dateStr) {
    const url = 'https://canchero.app/?partido=' + matchId;
    const text = '⚽ ¡Mirá este partido en Canchero!\n' + name + '\n📍 ' + venue + '\n📅 ' + dateStr + '\n\nUníte acá 👇\n' + url;
    if (navigator.share) {
        try { await navigator.share({ title: '⚽ Partido en Canchero', text: text, url: url }); } catch(e) {}
    } else {
        try { if (navigator.clipboard) navigator.clipboard.writeText(text); } catch(e) {}
        if (typeof showToast === 'function') showToast('Enlace copiado al portapapeles ✓', 'success');
    }
};

window.joinOpenMatch = async function(matchId) {
    if (window._mustBeJugador && !window._mustBeJugador('unirse a un partido')) return;
    const sb = window._sb;
    const email = window.userData && window.userData.email;
    const name = (window.userData && window.userData.name) || email;
    if (!sb || !email) return;
    try {
        // Las solicitudes cierran 20 minutos antes del partido
        try {
            const { data: mt } = await sb.from('matches').select('scheduled_at').eq('id', matchId).single();
            if (mt && mt.scheduled_at && (new Date(mt.scheduled_at) - Date.now()) < 20*60000) {
                if (typeof showToast === 'function') showToast('Las solicitudes cierran 20 minutos antes del partido. ⏱', 'warning');
                return;
            }
        } catch(e){}
        const res = await sb.from('match_players').select('id,status').eq('match_id', matchId).eq('player_email', email).maybeSingle().catch(function() { return { data: null }; });
        if (res && res.data) {
            if (typeof showToast === 'function') showToast(res.data.status === 'pendiente' ? 'Ya enviaste tu solicitud, esperá la aprobación del capitán.' : 'Ya estás en este partido.', 'default');
            return;
        }
        // ¿Hay ya un capitán confirmado? Si no, el primero en anotarse queda de capitán.
        let _firstCaptain = false;
        try {
            const { data: mInfo } = await sb.from('matches').select('captain_home_email,captain_away_email,created_by').eq('id', matchId).single();
            const { data: existingPlayers } = await sb.from('match_players').select('is_captain,status').eq('match_id', matchId);
            const hasCaptain = (mInfo && (mInfo.captain_home_email || mInfo.captain_away_email)) || (existingPlayers||[]).some(p => p.is_captain);
            if (!hasCaptain) _firstCaptain = true;
        } catch(e){}
        // Enviar SOLICITUD (pendiente) — el capitán la acepta estilo Tinder.
        // El primero en anotarse se marca como capitán al confirmarse.
        await sb.from('match_players').insert({
            match_id: matchId, player_email: email,
            player_name: name, position: (window.userData && window.userData.pos) || 'DEL',
            status: 'pendiente', is_captain: _firstCaptain
        });
        if (_firstCaptain) {
            try { await sb.from('matches').update({ captain_home_email: email }).eq('id', matchId); } catch(e){}
        }
        // Notificar al creador del partido
        try {
            const mres = await sb.from('matches').select('created_by,name').eq('id', matchId).single();
            if (mres && mres.data && mres.data.created_by && window.CancheroNotif) {
                window.CancheroNotif.create(mres.data.created_by, 'match_request', name, '⚽ ' + name + ' quiere unirse a tu partido "' + (mres.data.name||'') + '". Tocá para aprobar o rechazar.', matchId);
            }
        } catch(_e) {}
        if (typeof showToast === 'function') showToast('¡Solicitud enviada! El capitán la revisará. 📨', 'success');
        loadMisPartidos('abiertos');
    } catch(e) {
        console.error('joinOpenMatch error:', e);
        if (typeof showToast === 'function') showToast('Error al enviar solicitud.', 'error');
    }
};

// ── SOLICITUDES ESTILO TINDER ──────────────────────────────────
window.renderMatchRequestsTinder = async function(matchId) {
    const sb = window._sb;
    const cont = document.getElementById('tinder-requests-container');
    if (!sb || !cont || !matchId) return;
    cont.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div>';
    try {
        let { data: reqs } = await sb.from('match_players')
            .select('*').eq('match_id', matchId).eq('status', 'pendiente').order('joined_at', { ascending: true });
        // Nunca volver a mostrar una solicitud YA procesada en este dispositivo
        // (aunque el update en DB haya fallado por permisos, no se repite).
        try {
            const done = JSON.parse(localStorage.getItem('canchero_reqs_done')||'[]');
            reqs = (reqs||[]).filter(r => !done.includes('mp:'+r.id));
        } catch(e){}
        if (!reqs || !reqs.length) {
            cont.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;"><i class="bx bx-check-circle" style="font-size:36px;display:block;margin-bottom:10px;opacity:0.4;"></i>No hay solicitudes pendientes para este partido.</div>';
            return;
        }
        // Traer datos de usuarios
        const emails = reqs.map(function(r){ return r.player_email; });
        const usersMap = {};
        try {
            const { data: us } = await sb.from('users').select('email,name,photo,pos,city,stats').in('email', emails);
            (us||[]).forEach(function(u){ usersMap[u.email] = u; });
        } catch(_e) {}

        window._tinderQueue = reqs.map(function(r){ return { req: r, user: usersMap[r.player_email] || {} }; });
        window._tinderMatchId = matchId;
        _renderTinderStack();
    } catch(e) {
        console.error('renderMatchRequestsTinder error:', e);
        cont.innerHTML = '<div style="padding:20px;color:#f44;font-size:12px;">Error cargando solicitudes.</div>';
    }
};

function _renderTinderStack() {
    const cont = document.getElementById('tinder-requests-container');
    if (!cont) return;
    const queue = window._tinderQueue || [];
    if (!queue.length) {
        cont.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#555;font-size:13px;"><i class="bx bx-check-double" style="font-size:36px;display:block;margin-bottom:10px;color:var(--accent);"></i>¡Listo! Procesaste todas las solicitudes.</div>';
        return;
    }
    var cardsHtml = '';
    // Render hasta 3 cards apiladas (la primera es la activa)
    for (var i = Math.min(queue.length, 3) - 1; i >= 0; i--) {
        var item = queue[i];
        var u = item.user || {};
        var r = item.req;
        var nm = u.name || r.player_name || r.player_email.split('@')[0];
        var photo = u.photo;
        var pos = u.pos || r.position || '';
        var city = u.city || '';
        var st = u.stats || {};
        var initial = (nm||'?').trim()[0].toUpperCase();
        var emEsc = r.player_email.replace(/'/g, "\\'");
        var offset = i * 6;
        var scale = 1 - i * 0.04;
        var bgImg = photo
            ? 'background-image:linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0.1) 50%), url(\'' + photo + '\');background-size:cover;background-position:center;'
            : 'background:linear-gradient(135deg,#1a2a00,#0d0d0d);';
        var avatarBig = photo ? '' : '<div style="position:absolute;top:36%;left:50%;transform:translate(-50%,-50%);width:120px;height:120px;border-radius:50%;background:var(--accent);color:#000;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:54px;">' + initial + '</div>';
        cardsHtml += '<div class="tinder-card" data-idx="' + i + '" style="' + bgImg + 'transform:translateY(' + offset + 'px) scale(' + scale + ');z-index:' + (10 - i) + ';' + (i===0?'':'pointer-events:none;') + '">' +
            avatarBig +
            '<div style="position:absolute;bottom:0;left:0;right:0;padding:20px;">' +
                '<div style="font-size:24px;font-weight:900;color:#fff;">' + nm + '</div>' +
                '<div style="font-size:13px;color:var(--accent);font-weight:700;margin-bottom:8px;">' + (pos ? pos : 'Jugador') + (city ? ' · ' + city : '') + '</div>' +
                '<div style="display:flex;gap:14px;font-size:12px;color:#ddd;">' +
                    '<span>⚽ ' + (st.goals||0) + '</span><span>🅰️ ' + (st.assists||0) + '</span><span>📅 ' + (st.matches||0) + '</span><span>⭐ ' + (st.rating||50) + '</span>' +
                '</div>' +
                '<button onclick="window.viewUserProfile && window.viewUserProfile(\'' + emEsc + '\')" style="margin-top:10px;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);color:#fff;border-radius:20px;padding:6px 14px;font-size:11px;font-weight:700;cursor:pointer;backdrop-filter:blur(4px);">VER PERFIL COMPLETO</button>' +
            '</div>' +
        '</div>';
    }
    cont.innerHTML =
        '<div class="tinder-card-stack">' + cardsHtml + '</div>' +
        '<div class="tinder-actions">' +
            '<button class="tinder-btn tinder-btn-no" onclick="window._swipeTinder(\'left\')" title="Rechazar">✗</button>' +
            '<button class="tinder-btn tinder-btn-yes" onclick="window._swipeTinder(\'right\')" title="Aceptar">✓</button>' +
        '</div>' +
        '<div style="text-align:center;margin-top:10px;font-size:11px;color:#666;">' + queue.length + ' solicitud' + (queue.length>1?'es':'') + ' pendiente' + (queue.length>1?'s':'') + ' · Deslizá o usá los botones</div>';
    _attachTinderDrag();
}

function _attachTinderDrag() {
    var card = document.querySelector('.tinder-card[data-idx="0"]');
    if (!card) return;
    var startX = 0, curX = 0, dragging = false;
    function down(x){ dragging = true; startX = x; card.style.transition = 'none'; }
    function move(x){ if(!dragging) return; curX = x - startX; card.style.transform = 'translateX(' + curX + 'px) rotate(' + (curX/20) + 'deg)'; }
    function up(){ if(!dragging) return; dragging = false; card.style.transition = 'transform .3s, opacity .3s';
        if (curX > 90) window._swipeTinder('right');
        else if (curX < -90) window._swipeTinder('left');
        else card.style.transform = 'translateY(0) scale(1)';
        curX = 0;
    }
    card.addEventListener('mousedown', function(e){ down(e.clientX); });
    window.addEventListener('mousemove', function(e){ move(e.clientX); });
    window.addEventListener('mouseup', up);
    card.addEventListener('touchstart', function(e){ down(e.touches[0].clientX); }, {passive:true});
    card.addEventListener('touchmove', function(e){ move(e.touches[0].clientX); }, {passive:true});
    card.addEventListener('touchend', up);
}

window._swipeTinder = async function(direction) {
    const queue = window._tinderQueue || [];
    if (!queue.length) return;
    const item = queue[0];
    const sb = window._sb;
    const card = document.querySelector('.tinder-card[data-idx="0"]');
    if (card) { card.classList.add(direction === 'right' ? 'swipe-right' : 'swipe-left'); }

    try {
        if (direction === 'right') {
            // Aceptar: confirmar + asignar equipo balanceado (el que tenga menos jugadores) + notificar
            let _team = item.req.team;
            try {
                if (!_team) {
                    const { data: _cur } = await sb.from('match_players').select('team,status').eq('match_id', window._tinderMatchId).neq('status','rechazado');
                    const _h = (_cur||[]).filter(p => (p.team||'home')==='home').length;
                    const _a = (_cur||[]).filter(p => p.team==='away').length;
                    _team = _a < _h ? 'away' : 'home'; // mete al equipo con menos para que ambos se llenen
                }
            } catch(_te) { _team = _team || 'home'; }
            const _rAcc = await sb.from('match_players').update({ status: 'confirmado', team: _team }).eq('id', item.req.id);
            if (_rAcc.error) console.warn('aceptar solicitud:', _rAcc.error.message);
            try {
                const mres = await sb.from('matches').select('slots_taken,name').eq('id', window._tinderMatchId).single();
                if (mres && mres.data) {
                    // slots_taken lo mantiene el trigger de Postgres (RLS)
                    if (window.CancheroNotif) window.CancheroNotif.create(item.req.player_email, 'match_accept', 'Canchero', '✅ ¡Te aceptaron en el partido "' + (mres.data.name||'') + '"! Tocá para ver el panel del partido.', window._tinderMatchId);
                }
            } catch(_e) {}
            if (typeof showToast === 'function') showToast('✓ ' + (item.user.name || item.req.player_name || 'Jugador') + ' aceptado', 'success');
        } else {
            const _rRej = await sb.from('match_players').update({ status: 'rechazado' }).eq('id', item.req.id);
            if (_rRej.error) { try { await sb.from('match_players').delete().eq('id', item.req.id); } catch(_e){} }
            if (typeof showToast === 'function') showToast('✗ Solicitud rechazada', 'default');
        }
    } catch(e) { console.error('swipeTinder error:', e); }
    // Marcar como procesada en este dispositivo (no vuelve a aparecer nunca)
    try {
        const done = JSON.parse(localStorage.getItem('canchero_reqs_done')||'[]');
        if (!done.includes('mp:'+item.req.id)) { done.push('mp:'+item.req.id); localStorage.setItem('canchero_reqs_done', JSON.stringify(done.slice(-500))); }
    } catch(e){}

    setTimeout(function() {
        window._tinderQueue = queue.slice(1);
        _renderTinderStack();
    }, 320);
};

// ── Chat grupal del partido ────────────────────────────────────
window.openMatchGroupChat = async function(matchId, matchName, captainEmail) {
    const sb = window._sb;
    const email = window.userData && window.userData.email;
    if (!sb || !email) { if (typeof showToast === 'function') showToast('Iniciá sesión para abrir el chat.', 'warning'); return; }

    // 1) Buscar el chat existente del partido (defensivo por operación)
    let groupId = null;
    try {
        const r = await sb.from('group_chats').select('id,name').eq('match_id', matchId).maybeSingle();
        if (r && r.data) groupId = r.data.id;
        else if (r && r.error) console.warn('group_chats select:', r.error.message);
    } catch(e) { console.warn('group_chats select threw:', e); }

    // 2) Crear el chat si no existe
    if (!groupId) {
        try {
            const ins = await sb.from('group_chats').insert({
                name: '⚽ ' + matchName,
                created_by: captainEmail || email,
                match_id: matchId
            }).select('id').single();
            if (ins && ins.data) groupId = ins.data.id;
            else if (ins && ins.error) console.error('group_chats insert:', ins.error.message);
        } catch(e) { console.error('group_chats insert threw:', e); }

        // Sembrar miembros con el plantel (no crítico)
        if (groupId) {
            try {
                const pl = await sb.from('match_players').select('player_email').eq('match_id', matchId);
                const members = ((pl && pl.data) || []).map(function(p) { return { group_id: groupId, email: p.player_email, role: 'member' }; });
                if (members.length) await sb.from('group_members').upsert(members, { onConflict: 'group_id,email', ignoreDuplicates: true });
            } catch(e) { console.warn('group_members seed:', e); }
        }
    }

    if (!groupId) { if (typeof showToast === 'function') showToast('No se pudo abrir el chat del partido.', 'error'); return; }

    // 3) Auto-membresía del usuario actual (self-heal) antes de abrir
    try { await sb.from('group_members').upsert([{ group_id: groupId, email: email, role: 'member' }], { onConflict: 'group_id,email', ignoreDuplicates: true }); } catch(e) {}

    // 4) Abrir el hilo
    switchDashboardTab('jugador', 'mensajes', null);
    setTimeout(function() {
        if (window.CancheroMessaging && CancheroMessaging.openThread) CancheroMessaging.openThread('group', null, null, matchName, groupId, matchName);
        else if (typeof showToast === 'function') showToast('Mensajería no disponible.', 'error');
    }, 300);
};

// ── Crear Partido — refactorizado (datos reales, sin datos falsos) ──
window.toggleComplejoManual = function(sel) {
    const manualWrap = document.getElementById('cp-cancha-manual-wrap');
    if (manualWrap) manualWrap.style.display = sel.value === '__manual__' ? 'block' : 'none';
};

window.calcularTotalPartido = function() {
    const precio = parseFloat(document.getElementById('cp-precio-jugador')?.value) || 0;
    const activeTypeBtn = document.querySelector('#cp-ftype-selector .type-btn.active')
        || document.querySelector('.type-selector .type-btn.active');
    const fType = (activeTypeBtn ? activeTypeBtn.innerText.trim() : '11v11');
    const slotsMap = { '5v5': 10, '7v7': 14, '11v11': 22 };
    const slots = slotsMap[fType] || 22;
    const totalEl = document.getElementById('cp-total');
    if (totalEl) totalEl.value = precio * slots;
};

window.autoCalcLlegada = function() {
    const hora = document.getElementById('cp-hora')?.value;
    if (!hora) return;
    const [h, m] = hora.split(':').map(Number);
    const totalMin = h * 60 + m - 15;
    if (totalMin < 0) return;
    const llegH = Math.floor(totalMin / 60).toString().padStart(2, '0');
    const llegM = (totalMin % 60).toString().padStart(2, '0');
    const llegada = `${llegH}:${llegM}`;
    const llegadaEl = document.getElementById('cp-llegada');
    if (llegadaEl) llegadaEl.value = llegada;
    // El campo VISIBLE del paso de duración (antes tenía el mismo id que el hidden y
    // getElementById devolvía el oculto → el visible quedaba en --:--).
    const llegadaView = document.getElementById('cp-llegada-view');
    if (llegadaView) llegadaView.value = llegada;
    // Mostrar la hora de llegada sugerida al usuario
    const hint = document.getElementById('cp-llegada-hint');
    const txt = document.getElementById('cp-llegada-txt');
    if (txt) txt.textContent = llegada + ' hs';
    if (hint) hint.style.display = 'flex';
};

window.onCanchaChange = async function(select) {
    toggleComplejoManual(select);
    var val = select.value;
    if (!val || val === '__manual__') return;
    var bizEmail = val.indexOf('biz:') === 0 ? val.slice(4) : val;
    try {
        const sb = window._sb;
        if (!sb) return;
        const { data: courts } = await sb.from('business_courts').select('price_per_hour').eq('business_email', bizEmail).limit(1);
        if (courts && courts.length > 0 && courts[0].price_per_hour > 0) {
            const dur = parseInt(document.getElementById('cp-duracion')?.value) || 90;
            const activeTypeBtn = document.querySelector('#cp-ftype-selector .type-btn.active');
            const fType = activeTypeBtn ? activeTypeBtn.innerText.trim() : '11v11';
            const slotsMap = { '5v5': 10, '7v7': 14, '11v11': 22 };
            const slots = slotsMap[fType] || 22;
            const precioPorJugador = Math.round((courts[0].price_per_hour * (dur / 60)) / slots);
            const precioEl = document.getElementById('cp-precio-jugador');
            if (precioEl) precioEl.value = precioPorJugador;
            const hint = document.getElementById('cp-precio-hint');
            if (hint) hint.textContent = `Basado en $${courts[0].price_per_hour}/hora del complejo`;
            calcularTotalPartido();
        }
    } catch(_e) {}
};

// Preview + guardar (base64) del escudo de cada equipo al crear partido
window._matchLogos = { home: null, away: null };
window._previewMatchLogo = function(input, side) {
    const file = input.files && input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(e) {
        window._matchLogos[side] = e.target.result;
        const prev = document.getElementById('cp-' + side + '-logo-prev');
        if (prev) prev.innerHTML = `<img src="${e.target.result}" style="width:100%;height:100%;object-fit:cover;">`;
    };
    reader.readAsDataURL(file);
};

window.createOpenMatchAction = async function() {
    const sb = window._sb;
    const user = window.userData;
    if (!sb || !user) { if (typeof showToast === 'function') showToast('Iniciá sesión primero.', 'error'); return; }

    // Obtener tipo de partido con múltiples selectores de fallback
    const activeTypeBtn = document.querySelector('#cp-ftype-selector .type-btn.active')
        || document.querySelector('.type-selector .type-btn.active');
    const fType = activeTypeBtn ? activeTypeBtn.innerText.trim() : '11v11';

    const fecha = document.getElementById('cp-fecha') ? document.getElementById('cp-fecha').value : '';
    const hora  = document.getElementById('cp-hora') ? document.getElementById('cp-hora').value : '';
    const ciudad = (document.getElementById('cp-ciudad') && document.getElementById('cp-ciudad').value) || 'Montevideo';
    const nombreCustom = (document.getElementById('cp-nombre') && document.getElementById('cp-nombre').value.trim()) || '';

    if (!fecha || !hora) { if (typeof showToast === 'function') showToast('Seleccioná fecha y hora.', 'error'); return; }

    let venue = (document.getElementById('cp-cancha') && document.getElementById('cp-cancha').value) || '';
    window._matchComplejoEmail = null;
    if (venue.indexOf('biz:') === 0) {
        const _bemail = venue.slice(4);
        const _bz = (window._complejosReales && window._complejosReales[_bemail]) || null;
        window._matchComplejoEmail = _bemail;
        venue = (_bz && _bz.name) || _bemail;
    } else if (venue === '__manual__' || !venue) {
        const mn = (document.getElementById('cp-cancha-manual') && document.getElementById('cp-cancha-manual').value.trim()) || '';
        const md = (document.getElementById('cp-cancha-direccion') && document.getElementById('cp-cancha-direccion').value.trim()) || '';
        if (mn && md) venue = mn + ' — ' + md;
        else if (mn) venue = mn;
        else if (md) venue = md;
    }
    if (!venue) venue = ciudad;

    const activeModBtn = document.querySelector('#cp-modality-selector .type-btn.active')
        || document.querySelector('.cp-modality-selector .type-btn.active');
    const modalityText = activeModBtn ? activeModBtn.innerText.toLowerCase() : 'abierto';
    const modality = modalityText.indexOf('cerrado') >= 0 ? 'cerrado' : 'abierto';

    // Género del partido — leer dataset.gender que está en cada botón
    const activeGenderBtn = document.querySelector('#cp-gender-selector .type-btn.active');
    const matchGender = (activeGenderBtn?.dataset?.gender) || 'mixto';

    // Validación de género. OJO: el género del usuario se guarda capitalizado ('Masculino'/'Femenino')
    // pero el del partido es minúscula ('masculino'/'femenino'); normalizar ambos a minúscula.
    const userGender = (user.gender || user.sex || '').toLowerCase();
    if (userGender === 'masculino' && matchGender === 'femenino') {
        if (typeof showToast === 'function') showToast('Un jugador masculino no puede organizar un partido femenino. Elegí Mixto.', 'error');
        return;
    }
    if (userGender === 'femenino' && matchGender === 'masculino') {
        if (typeof showToast === 'function') showToast('Una jugadora femenina no puede organizar un partido masculino. Elegí Mixto.', 'error');
        return;
    }

    const slotsMap = { '5v5': 10, '7v7': 14, '11v11': 22 };
    const slots = slotsMap[fType] || 22;

    let matchDate;
    try { matchDate = new Date(fecha + 'T' + hora); } catch(e) { matchDate = new Date(); }
    const dateLabel = matchDate.toLocaleDateString('es-UY', { day: 'numeric', month: 'short' });
    // Nombre por defecto: "Local vs Visitante" (no "Picado…"). Fallback a formato/ciudad si no hay equipos.
    const _homeNm = (document.getElementById('cp-home-name')?.value?.trim()) || (window.userData?.club_name) || 'Local';
    const _awayNm = (document.getElementById('cp-away-name')?.value?.trim()) || 'Visitante';
    const name = nombreCustom || (_homeNm + ' vs ' + _awayNm);

    const duracion = parseInt(document.getElementById('cp-duracion')?.value) || 90;
    // Hora de llegada automática: 15 minutos antes del inicio
    const _arr = new Date(matchDate.getTime() - 15*60000);
    const llegada = (!isNaN(_arr.getTime())) ? (('0'+_arr.getHours()).slice(-2)+':'+('0'+_arr.getMinutes()).slice(-2)) : null;
    const precio = parseFloat(document.getElementById('cp-precio-jugador')?.value) || 0;
    const total = parseFloat(document.getElementById('cp-total')?.value) || 0;
    const reglas = document.getElementById('cp-reglas')?.value?.trim() || null;
    const apuestaTxt = document.getElementById('cp-apuesta')?.value?.trim() || '';

    const sbx = sb;
    try {
        let { data: match, error } = await sbx.from('matches').insert({
            name: name, match_type: modality, format: fType, venue: venue, city: ciudad,
            scheduled_at: matchDate.toISOString(), slots_total: slots, slots_taken: 1,
            created_by: user.email, captain_home_email: user.email, modality: modality,
            gender: matchGender, duration_minutes: duracion, arrival_time: llegada,
            price: precio, total_cost: total, rules: reglas,
            home_club_name: (document.getElementById('cp-home-name')?.value?.trim()) || null,
            away_club_name: (document.getElementById('cp-away-name')?.value?.trim()) || null,
            home_club_logo: (window._matchLogos && window._matchLogos.home) || null,
            away_club_logo: (window._matchLogos && window._matchLogos.away) || null
        }).select('id,name').single();
        if (error && /format/.test(error.message||'')) {
            // columna format inexistente: reintentar sin ella (el formato igual viaja en el name)
            ({ data: match, error } = await sbx.from('matches').insert({
                name: name + (name.includes(fType)?'':' ('+fType+')'), match_type: modality, venue: venue, city: ciudad,
                scheduled_at: matchDate.toISOString(), slots_total: slots, slots_taken: 1,
                created_by: user.email, captain_home_email: user.email, modality: modality,
                gender: matchGender, duration_minutes: duracion, arrival_time: llegada,
                price: precio, total_cost: total, rules: reglas
            }).select('id,name').single());
        }
        if (error) throw error;
        // Si el visitante es un CLUB existente: notificar al dueño y a sus jugadores (desafío)
        try {
            if (window._matchAwayClubId && match && match.id) {
                try { await sbx.from('matches').update({ away_club_id: window._matchAwayClubId }).eq('id', match.id); } catch(_e){}
                const awayName2 = (document.getElementById('cp-away-name')?.value?.trim()) || 'tu equipo';
                const msg = (user.name || 'Un equipo') + ' desafió a ' + awayName2 + ' a un partido el ' + (fecha||'') + '. Mirá la ficha y respondé.';
                if (window._matchAwayOwnerEmail && window.CancheroNotif) CancheroNotif.create(window._matchAwayOwnerEmail, 'match_challenge', user.name||user.email, msg, match.id);
                try {
                    const { data: mem } = await sbx.from('club_members').select('player_email').eq('club_id', window._matchAwayClubId).neq('status','pendiente');
                    (mem||[]).forEach(function(mm){ if (mm.player_email && window.CancheroNotif) CancheroNotif.create(mm.player_email, 'match_challenge', user.name||user.email, msg, match.id); });
                } catch(_e){}
                if (typeof showToast === 'function') showToast('¡Desafío enviado a ' + awayName2 + '!', 'success');
            }
        } catch(_ce) { console.warn('[desafio club]', _ce); }
        window._matchAwayClubId = null; window._matchAwayOwnerEmail = null;
        window._matchLogos = { home: null, away: null }; // limpiar
        // Si se eligió un COMPLEJO REAL: enviar solicitud de reserva al complejo
        try {
            if (window._matchComplejoEmail && match && match.id) {
                const _hi = (hora || '08:00').slice(0,5);
                const _hf = ((parseInt(_hi.split(':')[0],10)+1) < 10 ? '0':'') + (parseInt(_hi.split(':')[0],10)+1) + ':00';
                await sbx.from('business_reservations').insert({
                    business_email: window._matchComplejoEmail, client_email: user.email,
                    client_name: user.name || user.email, fecha: fecha, hora_inicio: _hi, hora_fin: _hf,
                    estado: 'pendiente', notas: 'Partido Canchero: ' + (name || 'partido') + ' (match ' + match.id + ')'
                });
                if (window.CancheroNotif) window.CancheroNotif.create(window._matchComplejoEmail, 'reserva', user.name || user.email,
                    (user.name || 'Un jugador') + ' organizó un partido en tu complejo el ' + fecha + ' a las ' + _hi + '. Confirmá la reserva en tu panel.');
                if (typeof showToast === 'function') showToast('Le enviamos la solicitud de reserva al complejo. Te avisamos cuando la confirmen.', 'info');
            }
        } catch(_re) { console.warn('[reserva complejo]', _re); }

        // Apuesta propuesta desde el formulario (queda como propuesta para aprobar en el panel)
        if (apuestaTxt) {
            try {
                await sbx.from('match_bets').insert({
                    match_id: match.id, proposer_email: user.email, proposer_team: 'home',
                    bet_text: apuestaTxt, status: 'proposed', edits_count: 0,
                    approvals_json: JSON.stringify([user.email])
                });
            } catch(_e) { console.warn('bet insert on create:', _e); }
        }

        try {
            await sbx.from('match_players').insert({
                match_id: match.id, player_email: user.email,
                player_name: user.name || user.email,
                position: user.position || 'DEL', team: 'home',
                status: 'confirmado', is_captain: true
            });
        } catch(_e) { console.warn('match_players insert:', _e); }

        let group = null;
        try {
            const { data: gData } = await sbx.from('group_chats').insert({
                name: '⚽ ' + name, created_by: user.email, match_id: match.id
            }).select('id').single();
            group = gData;
        } catch(_e) { console.warn('group_chats insert:', _e); }

        if (group && group.id) {
            try {
                await sbx.from('group_members').insert({ group_id: group.id, email: user.email, role: 'admin' });
            } catch(_e) {}
        }

        if (typeof showToast === 'function') showToast('¡Partido creado! ⚽🎉', 'success');
        // Abrir la ficha del partido recién creado (confirmación clara de que se creó).
        if (match && match.id && typeof window.viewMatchDetails === 'function') {
            setTimeout(function() { try { window.viewMatchDetails(match.id); } catch(e){ switchDashboardTab('jugador', 'mis-partidos', null); } }, 250);
        } else {
            switchDashboardTab('jugador', 'mis-partidos', null);
            setTimeout(function() { if (typeof loadMisPartidos === 'function') loadMisPartidos('creados'); }, 300);
        }

    } catch(e) {
        console.error('createOpenMatchAction error:', e, e && e.message, e && e.details, e && e.hint);
        var msg = (e && (e.message || e.details)) ? (': ' + (e.message || e.details)) : '. Intentá de nuevo.';
        if (typeof showToast === 'function') showToast('Error al crear el partido' + msg, 'error');
    }
};

// ── Escudo con IA ─────────────────────────────────────────────
window.switchEscudoTab = function(tab, btn) {
    document.querySelectorAll('.escudo-tab').forEach(function(b) {
        b.style.background = 'transparent'; b.style.color = '#666';
    });
    if (btn) { btn.style.background = 'rgba(186,255,0,0.1)'; btn.style.color = 'var(--accent)'; }
    var up = document.getElementById('escudo-upload-panel');
    var ia = document.getElementById('escudo-ia-panel');
    if (up) up.style.display = tab === 'upload' ? 'block' : 'none';
    if (ia) ia.style.display = tab === 'ia' ? 'block' : 'none';
};

// Moderación de palabras ofensivas
window._containsOffensiveWord = function(text) {
    const forbidden = ['puta','mierda','culo','pene','vagina','nazi','hitler','kk','concha','carajo','pelotudo','boludo','hdp','hdm','forro','sorete','putita'];
    const lower = (text || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
    return forbidden.some(w => lower.includes(w));
};

window.generateEscudoIA = function() {
    // Obtener datos del formulario wizard de escudo
    const nombre  = (document.getElementById('escudo-ia-nombre') || document.getElementById('club-name-input') || {}).value?.trim() || '';
    const ciudad  = (document.getElementById('escudo-ia-ciudad') || {}).value?.trim() || '';
    const colores = (document.getElementById('escudo-ia-colores') || {}).value?.trim() || 'verde y negro';
    const simbolo = (document.getElementById('escudo-ia-simbolo') || {}).value?.trim() || 'pelota de fútbol';
    const lema    = (document.getElementById('escudo-ia-lema') || {}).value?.trim() || '';

    if (!nombre) { if (typeof showToast === 'function') showToast('Ingresá el nombre del club.', 'error'); return; }
    if (window._containsOffensiveWord(nombre)) { if (typeof showToast === 'function') showToast('El nombre contiene palabras no permitidas.', 'error'); return; }

    const prompt = `Create a 2D retro football club badge in FIFA Street style for "${nombre}"${ciudad ? ' from ' + ciudad : ''}. ` +
        `Team colors: ${colores}. Main symbol/icon: ${simbolo}. ` +
        (lema ? `Club motto: "${lema}". ` : '') +
        `Style requirements: flat 2D illustration, retro street football aesthetic inspired by FIFA Street video game, ` +
        `bold black outlines, shield or crest shape, vibrant flat colors, geometric design, the club name "${nombre}" integrated in the badge, ` +
        `pixel-art inspired but clean vector look. Background: pure black (#000000). ` +
        `No photorealism, no gradients, no shadows. High contrast graphic art. Suitable as a team logo/badge.`;

    const resultEl = document.getElementById('escudo-ia-result') || document.getElementById('escudo-result-container');
    if (!resultEl) return;
    resultEl.style.display = 'block';

    resultEl.innerHTML = `
        <div style="background:#111;border:1px solid #333;border-radius:12px;padding:16px;margin-bottom:14px;">
            <div style="font-size:10px;color:#555;font-weight:900;letter-spacing:1px;margin-bottom:8px;">📋 PROMPT GENERADO — COPIÁ EN CHATGPT O DALL-E</div>
            <div id="escudo-prompt-display" style="font-size:11px;color:#ccc;line-height:1.7;margin-bottom:10px;background:#0d0d0d;border-radius:8px;padding:10px;">${prompt}</div>
            <button onclick="navigator.clipboard.writeText(document.getElementById('escudo-prompt-display').textContent).then(()=>(typeof showToast==='function'?showToast('Prompt copiado ✓','success'):alert('Copiado')))"
                style="width:100%;background:rgba(186,255,0,0.08);color:var(--accent);border:1px solid rgba(186,255,0,0.3);border-radius:8px;padding:9px;font-size:12px;font-weight:700;cursor:pointer;margin-bottom:6px;">
                📋 COPIAR PROMPT
            </button>
            <div style="display:flex;gap:8px;">
                <a href="https://chat.openai.com" target="_blank" style="flex:1;display:flex;align-items:center;justify-content:center;gap:6px;background:rgba(255,255,255,0.04);color:#aaa;border:1px solid #333;border-radius:8px;padding:8px;font-size:11px;font-weight:700;text-decoration:none;">→ ChatGPT</a>
                <a href="https://www.bing.com/images/create" target="_blank" style="flex:1;display:flex;align-items:center;justify-content:center;gap:6px;background:rgba(255,255,255,0.04);color:#aaa;border:1px solid #333;border-radius:8px;padding:8px;font-size:11px;font-weight:700;text-decoration:none;">→ Bing IA</a>
            </div>
        </div>
        <div style="border:2px dashed #333;border-radius:12px;padding:18px;text-align:center;">
            <div style="font-size:13px;color:#888;margin-bottom:12px;font-weight:700;">📁 Subí el escudo generado</div>
            <input type="file" id="escudo-upload-result" accept="image/*" style="display:none;" onchange="window._previewEscudoUpload(this)">
            <button onclick="document.getElementById('escudo-upload-result').click()"
                style="background:var(--accent);color:#000;border:none;border-radius:10px;padding:10px 24px;font-weight:900;cursor:pointer;font-size:13px;">
                📁 SUBIR IMAGEN
            </button>
            <div id="escudo-upload-preview" style="margin-top:14px;display:none;">
                <img id="escudo-preview-img" style="width:110px;height:110px;border-radius:50%;object-fit:cover;border:3px solid var(--accent);display:block;margin:0 auto 10px;">
                <button onclick="window._saveEscudoToClub()"
                    style="background:var(--accent);color:#000;border:none;border-radius:10px;padding:9px 22px;font-weight:900;font-size:13px;cursor:pointer;">
                    ✅ GUARDAR ESCUDO
                </button>
            </div>
        </div>`;
    resultEl.style.display = 'block';
};

// Preview del escudo antes de guardar
window._previewEscudoUpload = function(input) {
    const file = input.files[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { if (typeof showToast === 'function') showToast('La imagen no puede superar 5MB.', 'warning'); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = document.getElementById('escudo-preview-img');
        const preview = document.getElementById('escudo-upload-preview');
        if (img) { img.src = e.target.result; }
        if (preview) preview.style.display = 'block';
        window._escudoFile = file;
    };
    reader.readAsDataURL(file);
};

// Guardar escudo en Supabase Storage
window._saveEscudoToClub = async function() {
    const sb = window._sb;
    const file = window._escudoFile;
    const clubId = window.currentEditingClubId;
    if (!sb || !file) { if (typeof showToast === 'function') showToast('No hay imagen seleccionada.', 'warning'); return; }
    try {
        const ext = (file.name.split('.').pop() || 'png').toLowerCase();
        const path = clubId ? `clubs/${clubId}/logo.${ext}` : `clubs/temp_${Date.now()}.${ext}`;
        const { error: upErr } = await sb.storage.from('media').upload(path, file, { upsert: true });
        if (upErr) throw upErr;
        const { data: { publicUrl } } = sb.storage.from('media').getPublicUrl(path);
        if (clubId) {
            await sb.from('clubs').update({ logo_url: publicUrl, logo: publicUrl }).eq('id', clubId);
        }
        window._escudoUrl = publicUrl;
        // Actualizar vistas en tiempo real
        document.querySelectorAll(`[data-club-shield="${clubId}"]`).forEach(img => { img.src = publicUrl; img.style.display = 'block'; });
        document.querySelectorAll('.club-shield-img').forEach(img => { if (String(img.dataset.clubId) === String(clubId)) img.src = publicUrl; });
        if (typeof showToast === 'function') showToast('¡Escudo guardado y actualizado! ✅', 'success');
        const previewArea = document.getElementById('escudo-upload-preview');
        if (previewArea) previewArea.innerHTML = `<div style="text-align:center;padding:12px;"><div style="font-size:28px;">✅</div><div style="color:#00e676;font-weight:700;margin-top:6px;">Escudo guardado</div></div>`;
    } catch(e) { if (typeof showToast === 'function') showToast('Error al guardar: ' + (e.message||''), 'error'); }
};

window.useGeneratedEscudo = function(url) {
    if (!url && arguments[0] && arguments[0].dataset) url = arguments[0].dataset.url;
    window._escudoUrl = url;
    if (typeof showToast === 'function') showToast('Escudo IA seleccionado ✓', 'success');
};

// ── switchProfileTab — logros (wrapper) ───────────────────────
(function() {
    var _orig = window.switchProfileTab;
    window.switchProfileTab = function(role, tab, el) {
        if (typeof _orig === 'function') _orig(role, tab, el);
        if (tab === 'logros') {
            var container = document.getElementById((role || 'jugador') + '-profile-logros');
            if (!container) return;
            // FANÁTICO: logros de HINCHA (no los de jugador)
            if (window._activeProfileType && window._activeProfileType() === 'fanatico') {
                if (window._renderFanAchievements) window._renderFanAchievements(container);
                return;
            }
            if (container && window.CancheroAchievements) {
                var email = window.userData && window.userData.email;
                if (email) CancheroAchievements.renderAchievements(container, email);
            }
        }
    };
})();
// ── Logros del FANÁTICO (catálogo propio de hincha) ─────────────────────────
window._renderFanAchievements = function(container){
    if (!container) return;
    var fav = (window._getFanFavTeams ? window._getFanFavTeams() : []) || [];
    var lp = {}; try { lp = typeof window.userData.linked_profiles==='string'?JSON.parse(window.userData.linked_profiles):(window.userData.linked_profiles||{}); } catch(e){}
    var fan = lp.fanatico || {};
    var hasPhoto = !!fan.photo, hasBio = !!(fan.bio && fan.bio.trim());
    var CAT = [
      { icon:'bx-crown',    name:'Hincha registrado', desc:'Creaste tu perfil de fanático', got:true, rarity:'común' },
      { icon:'bx-camera',   name:'Cara visible',      desc:'Subiste tu foto de hincha',      got:hasPhoto, rarity:'común' },
      { icon:'bx-edit',     name:'Con identidad',     desc:'Escribiste tu bio de hincha',    got:hasBio, rarity:'común' },
      { icon:'bx-shield',   name:'Colores propios',   desc:'Elegiste al menos 1 equipo',     got:fav.length>=1, rarity:'común' },
      { icon:'bx-heart',    name:'Fiel',              desc:'Seguís a 3 equipos',             got:fav.length>=3, rarity:'raro' },
      { icon:'bx-group',    name:'De la comunidad',   desc:'Sumate a una comunidad de hinchas', got:false, rarity:'raro' },
      { icon:'bx-chat',     name:'Opinador',          desc:'Participá de un debate',         got:false, rarity:'raro' },
      { icon:'bx-photo-album', name:'Creador',        desc:'Publicá 10 momentos',            got:false, rarity:'épico' },
      { icon:'bx-star',     name:'Influencer',        desc:'Llegá a 100 seguidores',         got:false, rarity:'épico' },
      { icon:'bx-trophy',   name:'Leyenda hincha',    desc:'1 año en Canchero',              got:false, rarity:'legendario' }
    ];
    var rarityColors = { 'común':'#888', 'raro':'#4fc3f7', 'épico':'#9c88ff', 'legendario':'#FFD700' };
    container.innerHTML = '<div style="padding:4px 0 12px;"><div style="font-size:11px;font-weight:900;color:#888;letter-spacing:1px;margin-bottom:12px;">LOGROS DE HINCHA</div>'
      + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:10px;">'
      + CAT.map(function(a){
          var rc = rarityColors[a.rarity]||'#888';
          return '<div style="background:#111;border:1px solid '+(a.got?rc:'#1e1e1e')+';border-radius:12px;padding:12px 8px;text-align:center;opacity:'+(a.got?1:0.4)+';">'
            + '<i class="bx '+a.icon+'" style="font-size:26px;color:'+(a.got?'var(--accent)':'#555')+';display:block;margin-bottom:6px;"></i>'
            + '<div style="font-size:10.5px;font-weight:800;color:'+(a.got?'#fff':'#666')+';">'+a.name+'</div>'
            + '<div style="font-size:9px;color:#555;margin-top:2px;line-height:1.3;">'+a.desc+'</div>'
            + '</div>';
        }).join('')
      + '</div></div>';
};

