// ── Mini-badges de logros desbloqueados bajo la bio ───────────
window._renderProfileAchievementBadges = async function(email) {
    if (!window._sb || !email) return;
    var badgesWrap = document.getElementById('player-profile-badges');
    if (!badgesWrap) return;
    try {
        var res = await window._sb.from('player_achievements')
            .select('achievement_id').eq('player_email', email).limit(30);
        var data = (res && res.data) || [];
        if (!data.length) return;
        var unlockedIds = new Set(data.map(function(d) { return d.achievement_id; }));
        badgesWrap.querySelectorAll('.achievement-mini-badge').forEach(function(b) { b.remove(); });
        var CATALOG = (window.CancheroAchievements && window.CancheroAchievements.CATALOG) || [];

        // Filter: only unlocked, exclude social_first (Bienvenido a Canchero)
        var unlocked = CATALOG.filter(function(a) {
            return a.id !== 'social_first' && unlockedIds.has(a.id);
        });

        // Superseded logic: within same category, keep only the highest-target one
        var bestByCategory = {};
        unlocked.forEach(function(a) {
            var cat = a.category || a.id;
            var tgt = a.target || 0;
            if (!bestByCategory[cat] || tgt > (bestByCategory[cat].target || 0)) {
                bestByCategory[cat] = a;
            }
        });
        var toShow = Object.values(bestByCategory)
            .sort(function(a, b) { return (b.target||0) - (a.target||0); })
            .slice(0, 3);

        toShow.forEach(function(ach) {
            var badge = document.createElement('div');
            badge.className = 'achievement-mini-badge';
            badge.title = ach.name + ' — ' + ach.desc;
            badge.style.cssText = 'display:inline-flex;align-items:center;gap:4px;background:rgba(255,215,0,0.08);border:1px solid rgba(255,215,0,0.3);padding:4px 8px;border-radius:8px;font-size:11px;font-weight:700;color:#FFD700;cursor:pointer;flex-shrink:0;';
            badge.innerHTML = ach.icon + ' ' + ach.name;
            badge.onclick = function() {
                var tab = document.querySelector('.profile-tab[onclick*="logros"]');
                if (tab && typeof switchProfileTab === 'function') switchProfileTab('jugador','logros',tab);
            };
            badgesWrap.appendChild(badge);
        });
    } catch(e) { console.warn('[AchBadges]', e); }
};

// ============================================================
// MAPA LEAFLET EN CREAR PARTIDO
// ============================================================
window._cpMap = null;
window._cpMarker = null;

window.initCrearPartidoMap = function() {
    var el = document.getElementById('cp-leaflet-map');
    if (!el || typeof L === 'undefined') return;
    if (window._cpMap) {
        // Si el contenedor fue re-renderizado, el mapa viejo apunta a un DOM
        // muerto y se ve negro: destruirlo y crear uno nuevo.
        if (el._leaflet_id) { setTimeout(function(){ try { window._cpMap.invalidateSize(); } catch(e){} }, 120); return; }
        try { window._cpMap.remove(); } catch(e){}
        window._cpMap = null; window._cpMarker = null;
    }
    var map = L.map('cp-leaflet-map', { zoomControl: true }).setView([-34.9011, -56.1645], 13);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: 'OpenStreetMap'
    }).addTo(map);
    window._cpMap = map;
    map.on('click', function(e) { cpMapSetMarker(e.latlng.lat, e.latlng.lng); });
    var searchEl = document.getElementById('cp-map-search');
    if (searchEl) {
        searchEl.addEventListener('keydown', function(ev) {
            if (ev.key === 'Enter') { ev.preventDefault(); cpMapSearch(this.value); }
        });
    }
    // Centrar el mapa en la CIUDAD elegida (antes quedaba siempre en Montevideo).
    var citySel = document.getElementById('cp-ciudad');
    if (citySel && !citySel._cpCenterBound) {
        citySel._cpCenterBound = true;
        citySel.addEventListener('change', function(){ window._cpCenterOnCity(this.value); });
    }
    setTimeout(function(){ if (citySel && citySel.value) window._cpCenterOnCity(citySel.value); }, 200);
};

// Centra el mapa de Crear Partido en la ciudad elegida (geocoding Nominatim, cacheado).
// NO coloca marcador (eso lo hace el usuario tocando la cancha exacta); solo reposiciona
// la vista para que arranque en la ciudad correcta.
window._cpCenterOnCity = async function(city) {
    var map = window._cpMap;
    if (!map || !city) return;
    var pais = (document.getElementById('cp-pais') && document.getElementById('cp-pais').value) || 'Uruguay';
    var key = (city + '|' + pais).toLowerCase();
    window._cityCoordsCache = window._cityCoordsCache || {};
    try {
        var c = window._cityCoordsCache[key];
        if (!c) {
            var url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(city + ', ' + pais) + '&format=json&limit=1';
            var res = await fetch(url).then(function(r){ return r.json(); }).catch(function(){ return []; });
            if (res && res.length) { c = { lat: parseFloat(res[0].lat), lng: parseFloat(res[0].lon) }; window._cityCoordsCache[key] = c; }
        }
        // Solo mover si el usuario todavía no marcó una cancha exacta.
        if (c && !window._cpMarker) { try { map.setView([c.lat, c.lng], 13); } catch(e){} }
    } catch(e){}
};

window.cpMapSearch = async function(query) {
    // Sin query explícita: usar la dirección/cancha ya ingresada en el formulario
    if (!query || !query.trim()) {
        var _dir = document.getElementById('cp-cancha-direccion');
        var _man = document.getElementById('cp-cancha-manual');
        var _sel = document.getElementById('cp-cancha');
        query = (_dir && _dir.value.trim()) || (_man && _man.value.trim()) ||
                (_sel && _sel.selectedIndex > 0 && _sel.options[_sel.selectedIndex].text) || '';
    }
    if (!query || !query.trim()) { if(typeof showToast==='function') showToast('Escribí primero la dirección de la cancha.', 'info'); return; }
    try {
        var url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(query + ' Uruguay') + '&format=json&limit=1';
        var res = await fetch(url).then(function(r){ return r.json(); }).catch(function(){ return []; });
        if (!res || !res.length) { if(typeof showToast==='function') showToast('No se encontro esa direccion.', 'warning'); return; }
        cpMapSetMarker(parseFloat(res[0].lat), parseFloat(res[0].lon), res[0].display_name);
    } catch(e) {}
};

window.cpMapGeolocate = function() {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(function(pos) {
        cpMapSetMarker(pos.coords.latitude, pos.coords.longitude);
    }, function() { if(typeof showToast==='function') showToast('No se pudo obtener la ubicacion.', 'error'); });
};

window.cpMapSetMarker = function(lat, lng, address) {
    var map = window._cpMap;
    if (!map) return;
    if (window._cpMarker) window._cpMarker.remove();
    window._cpMarker = L.marker([lat, lng]).addTo(map);
    map.setView([lat, lng], 16);
    document.getElementById('cp-venue-lat').value = lat;
    document.getElementById('cp-venue-lng').value = lng;
    if (address) {
        var short = address.split(',').slice(0,2).join(',');
        var searchEl = document.getElementById('cp-map-search');
        if (searchEl) searchEl.value = short;
        var disp = document.getElementById('cp-venue-addr-display');
        if (disp) disp.textContent = '- ' + short;
        var manualDir = document.getElementById('cp-cancha-direccion');
        if (manualDir && !manualDir.value) manualDir.value = address.split(',').slice(0,3).join(',');
    } else {
        fetch('https://nominatim.openstreetmap.org/reverse?lat=' + lat + '&lon=' + lng + '&format=json')
            .then(function(r){ return r.json(); }).then(function(d) {
                var addr = d.display_name || (lat.toFixed(4) + ',' + lng.toFixed(4));
                var short = (d.address && (d.address.road || d.address.suburb)) || addr.split(',')[0];
                var searchEl2 = document.getElementById('cp-map-search');
                if (searchEl2) searchEl2.value = short;
                var disp2 = document.getElementById('cp-venue-addr-display');
                if (disp2) disp2.textContent = '- ' + short;
                var manualDir2 = document.getElementById('cp-cancha-direccion');
                if (manualDir2 && !manualDir2.value) manualDir2.value = addr.split(',').slice(0,3).join(',');
            }).catch(function(){});
    }
};

// ============================================================
// CARGA DE MIS CLUBES EN CREAR PARTIDO
// ============================================================
window._myClubsCache = [];
window._loadMyClubs = async function() {
    var sel = document.getElementById('cp-my-team');
    if (!sel || !window._sb || !window.userData) return;
    try {
        var email = window.userData.email;
        var data = [];
        var r1 = await window._sb.from('clubs').select('id,name,logo,logo_url').eq('owner_email', email).limit(20);
        if (r1.data && r1.data.length) data = r1.data;
        if (!data.length) {
            var r2 = await window._sb.from('club_members').select('club_id, clubs(id,name,logo,logo_url)').eq('player_email', email).limit(20);
            if (r2.data) data = r2.data.map(function(x){ return x.clubs; }).filter(Boolean);
        }
        window._myClubsCache = data;
        if (data.length) {
            sel.innerHTML = '<option value="">Sin equipo / partido libre</option>' +
                data.map(function(c){ return '<option value="' + (c.id||'') + '">' + (c.name||'Equipo') + '</option>'; }).join('');
        }
        // Poblar el selector de VISITANTE con todos los clubes (para desafiar)
        try {
            var away = document.getElementById('cp-away-team');
            if (away) {
                var rAll = await window._sb.from('clubs').select('id,name,logo,logo_url,owner_email').limit(200);
                window._allClubsCache = (rAll.data||[]);
                away.innerHTML = '<option value="">Elegí un club para desafiar (o escribí abajo)</option>' +
                    window._allClubsCache.map(function(c){ return '<option value="'+(c.id||'')+'">'+(c.name||'Club')+'</option>'; }).join('');
            }
        } catch(e){}
    } catch(e) {}
};

// Elegir un club existente como VISITANTE (desafío) → llena nombre/logo y guarda id para notificar
window._autoFillAwayTeam = function(clubId) {
    const nameInp = document.getElementById('cp-away-name');
    const prevDiv = document.getElementById('cp-away-logo-prev');
    window._matchLogos = window._matchLogos || {};
    if (!clubId) { window._matchAwayClubId = null; window._matchLogos.away = null; if (prevDiv) prevDiv.innerHTML = "<i class='bx bxs-shield' style=\"color:#9c88ff;font-size:18px;\"></i>"; return; }
    const club = (window._allClubsCache || []).find(c => String(c.id) === String(clubId));
    if (!club) return;
    if (nameInp) nameInp.value = club.name || '';
    window._matchAwayClubId = club.id || null;
    window._matchAwayOwnerEmail = club.owner_email || null;
    const logo = club.logo_url || club.logo || '';
    if (logo) { if (prevDiv) prevDiv.innerHTML = `<img src="${logo}" style="width:100%;height:100%;object-fit:cover;border-radius:8px;">`; window._matchLogos.away = logo; }
};

// Auto-completar nombre y escudo del equipo local al seleccionar un club
window._autoFillHomeTeam = function(clubId) {
    const nameInp = document.getElementById('cp-home-name');
    const prevDiv = document.getElementById('cp-home-logo-prev');
    if (!clubId) { // "Sin equipo / partido libre" → limpiar
        if (nameInp) nameInp.value = '';
        window._matchLogos = window._matchLogos || {}; window._matchLogos.home = null;
        if (prevDiv) prevDiv.innerHTML = "<i class='bx bxs-shield' style=\"color:var(--accent);font-size:18px;\"></i>";
        return;
    }
    const club = (window._myClubsCache || []).find(c => String(c.id) === String(clubId));
    if (!club) return;
    // Llenar nombre SIEMPRE con el club elegido (el usuario eligió ese equipo)
    if (nameInp) nameInp.value = club.name || '';
    window._matchHomeClubId = club.id || null;
    // Llenar logo preview + guardar para el insert
    const logo = club.logo_url || club.logo || '';
    window._matchLogos = window._matchLogos || {};
    if (logo) {
        if (prevDiv) prevDiv.innerHTML = `<img src="${logo}" style="width:100%;height:100%;object-fit:cover;border-radius:8px;">`;
        window._matchLogos.home = logo;
        window._matchHomeLogoB64 = logo;
        window._matchHomeLogoUrl = logo;
    }
};

// ============================================================
// EDITAR / ELIMINAR PARTIDO
// ============================================================
window.deleteMatch = async function(matchId) {
    if (!confirm('¿Eliminar este partido? Esta acción no se puede deshacer.')) return;
    var sbx = window._sb;
    if (!sbx) return;
    try {
        try { await sbx.from('match_players').delete().eq('match_id', matchId); } catch(_e){}
        try { await sbx.from('match_bets').delete().eq('match_id', matchId); } catch(_e){}
        try { await sbx.from('match_captain_log').delete().eq('match_id', matchId); } catch(_e){}
        try { await sbx.from('match_invites').delete().eq('match_id', matchId); } catch(_e){}
        try { await sbx.from('match_checkins').delete().eq('match_id', matchId); } catch(_e){}
        var res = await sbx.from('matches').delete().eq('id', matchId);
        if (res.error) throw res.error;
        if(typeof showToast==='function') showToast('Partido eliminado.', 'success');
        var dashboard = window.userData && window.userData.role === 'club' ? 'club' : 'jugador';
        // Cerrar modal de detalles si está abierto
        var detailModal = document.getElementById('match-detail-modal');
        if (detailModal) detailModal.remove();
        if(typeof switchDashboardTab==='function') switchDashboardTab(dashboard, 'mis-partidos');
        setTimeout(function(){ if(typeof loadMisPartidos==='function') loadMisPartidos('creados'); }, 300);
    } catch(e) {
        if(typeof showToast==='function') showToast('Error al eliminar: ' + (e.message||''), 'error');
        console.error('deleteMatch error:', e);
    }
};

window.editMatchOpen = async function(matchId) {
    var sb = window._sb;
    if (!sb) return;
    var res = await sb.from('matches').select('*').eq('id', matchId).single();
    if (!res.data) return;
    var m = res.data;
    var existing = document.getElementById('edit-match-modal');
    if (existing) existing.remove();
    var modal = document.createElement('div');
    modal.id = 'edit-match-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9200;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);';
    var fecha = m.scheduled_at ? m.scheduled_at.slice(0,10) : '';
    var hora  = m.scheduled_at ? m.scheduled_at.slice(11,16) : '';
    var nameEsc = (m.name||'').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    var venueEsc = (m.venue||'').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    var rulesEsc = (m.rules||'').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    modal.innerHTML = '<div style="background:#111;border:1px solid #222;border-radius:20px;width:100%;max-width:480px;padding:24px;max-height:90vh;overflow-y:auto;">' +
        '<h3 style="font-weight:900;margin-bottom:16px;font-size:18px;">Editar partido</h3>' +
        '<label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:4px;">NOMBRE</label>' +
        '<input id="em-name" type="text" value="' + nameEsc + '" style="width:100%;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;margin-bottom:12px;font-size:14px;">' +
        '<label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:4px;">COMPLEJO DE CANCHERO</label>' +
        '<select id="em-complejo" onchange="window._emPickComplejo(this)" style="width:100%;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;margin-bottom:10px;font-size:14px;"><option value="">Cargando complejos...</option></select>' +
        '<label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:4px;">CANCHA / LUGAR</label>' +
        '<input id="em-venue" type="text" value="' + venueEsc + '" placeholder="Elegí un complejo o escribí el lugar" style="width:100%;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;margin-bottom:12px;font-size:14px;">' +
        '<div style="display:flex;gap:8px;margin-bottom:12px;">' +
            '<div style="flex:2;"><label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:4px;">FECHA</label><input id="em-fecha" type="date" value="' + fecha + '" style="width:100%;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;font-size:14px;"></div>' +
            '<div style="flex:1;"><label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:4px;">HORA</label><input id="em-hora" type="time" value="' + hora + '" style="width:100%;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;font-size:14px;"></div>' +
        '</div>' +
        '<label style="font-size:11px;color:#888;font-weight:700;display:block;margin-bottom:4px;">REGLAS (opcional)</label>' +
        '<textarea id="em-rules" rows="3" style="width:100%;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;margin-bottom:16px;font-size:13px;resize:vertical;">' + rulesEsc + '</textarea>' +
        '<div style="display:flex;gap:8px;">' +
            '<button onclick="saveEditMatch(\'' + String(matchId).replace(/'/g,"\\'") + '\')" style="flex:1;background:var(--accent);color:#000;border:none;border-radius:12px;padding:12px;font-weight:900;cursor:pointer;">GUARDAR</button>' +
            '<button onclick="document.getElementById(\'edit-match-modal\').remove()" style="flex:1;background:#1a1a1a;color:#888;border:1px solid #333;border-radius:12px;padding:12px;font-weight:700;cursor:pointer;">CANCELAR</button>' +
        '</div>' +
    '</div>';
    modal.onclick = function(e){ if(e.target===modal) modal.remove(); };
    document.body.appendChild(modal);
    // Poblar el selector de complejos registrados (activos) + opción manual
    (async function(){
        var selEl = document.getElementById('em-complejo'); if(!selEl) return;
        try{
            var cr = await sb.from('users').select('email,name,city').in('role',['club','complejo']).eq('sub_status','active').order('name').limit(100);
            var rows = (cr && cr.data) || [];
            var opts = '<option value="">— Escribir el lugar manualmente —</option>';
            rows.forEach(function(c){ var label=(c.name||c.email)+(c.city?(' — '+c.city):''); opts += '<option value="'+String(label).replace(/"/g,'&quot;')+'">'+(c.name||c.email)+(c.city?(' — '+c.city):'')+'</option>'; });
            selEl.innerHTML = opts;
            // Pre-seleccionar si el venue actual coincide con un complejo
            if (m.venue) { for (var i=0;i<selEl.options.length;i++){ if(selEl.options[i].value===m.venue){ selEl.selectedIndex=i; break; } } }
        }catch(e){ selEl.innerHTML = '<option value="">— Escribir el lugar manualmente —</option>'; }
    })();
};

// Al elegir un complejo del selector, copiar su nombre al campo de lugar
window._emPickComplejo = function(sel){
    var v = sel && sel.value;
    var input = document.getElementById('em-venue');
    if (v && input) input.value = v;
};

window.saveEditMatch = async function(matchId) {
    var sb = window._sb;
    if (!sb) return;
    var nameEl = document.getElementById('em-name');
    var venueEl = document.getElementById('em-venue');
    var fechaEl = document.getElementById('em-fecha');
    var horaEl  = document.getElementById('em-hora');
    var rulesEl = document.getElementById('em-rules');
    var updates = {
        name: nameEl ? nameEl.value.trim() : undefined,
        venue: venueEl ? venueEl.value.trim() : undefined,
        rules: rulesEl ? rulesEl.value.trim() : undefined
    };
    if (fechaEl && horaEl && fechaEl.value && horaEl.value) {
        try { updates.scheduled_at = new Date(fechaEl.value + 'T' + horaEl.value).toISOString(); } catch(e){}
    }
    var res = await sb.from('matches').update(updates).eq('id', matchId);
    if (res.error) { if(typeof showToast==='function') showToast('Error: ' + res.error.message, 'error'); return; }
    if(typeof showToast==='function') showToast('Partido actualizado', 'success');
    // Avisar a TODOS los anotados del cambio (fecha/hora/lugar) con notificación + push
    try {
        var meName = (window.userData && window.userData.name) || 'El organizador';
        var matchName = updates.name || 'el partido';
        var whenTxt = updates.scheduled_at ? new Date(updates.scheduled_at).toLocaleString('es-UY',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) : '';
        var msg = '📋 "' + matchName + '" se actualizó' + (whenTxt ? (' · 📅 ' + whenTxt) : '') + (updates.venue ? (' · 📍 ' + updates.venue) : '');
        var plRes = await sb.from('match_players').select('player_email').eq('match_id', matchId);
        var emails = Array.from(new Set(((plRes && plRes.data) || []).map(function(p){ return p.player_email; }).filter(Boolean)));
        if (window.CancheroNotif && window.CancheroNotif.create) {
            for (var i = 0; i < emails.length; i++) { try { await window.CancheroNotif.create(emails[i], 'match_update', meName, msg); } catch(e){} }
        }
        if (emails.length && typeof showToast === 'function') showToast('Avisamos a ' + emails.length + ' anotado' + (emails.length !== 1 ? 's' : ''), 'success');
    } catch(e) { console.warn('notify match edit', e); }
    var mod = document.getElementById('edit-match-modal');
    if (mod) mod.remove();
    if(typeof loadMisPartidos==='function') loadMisPartidos('creados');
    if(window.MatchDashboard && document.getElementById('match-dashboard-overlay')) { try { window.MatchDashboard.open(matchId); } catch(e){} }
};

