window.openPredictionModal = function(matchId, matchName) {
    var existing = document.getElementById('prediction-modal');
    if (existing) existing.remove();
    var modal = document.createElement('div');
    modal.id = 'prediction-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9300;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);';
    var safeName = (matchName||'Partido').replace(/</g,'&lt;');
    var idSafe = JSON.stringify(matchId);
    modal.innerHTML = '<div style="background:#111;border:1px solid #222;border-radius:20px;width:100%;max-width:380px;padding:24px;">' +
        '<h3 style="font-weight:900;margin-bottom:4px;font-size:17px;">Prediccion</h3>' +
        '<p style="color:#888;font-size:12px;margin-bottom:20px;">' + safeName + '</p>' +
        '<div style="display:flex;align-items:center;gap:16px;justify-content:center;margin-bottom:20px;">' +
            '<div style="text-align:center;"><div style="font-size:11px;color:#888;margin-bottom:6px;">LOCAL</div><input type="number" id="pred-home" min="0" max="20" value="0" style="width:56px;text-align:center;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;font-size:20px;font-weight:900;"></div>' +
            '<div style="font-size:28px;font-weight:900;color:#555;"> - </div>' +
            '<div style="text-align:center;"><div style="font-size:11px;color:#888;margin-bottom:6px;">VISITANTE</div><input type="number" id="pred-away" min="0" max="20" value="0" style="width:56px;text-align:center;background:#1a1a1a;border:1px solid #333;color:#fff;border-radius:10px;padding:10px;font-size:20px;font-weight:900;"></div>' +
        '</div>' +
        '<label style="display:flex;align-items:center;gap:8px;cursor:pointer;margin-bottom:20px;font-size:13px;color:#aaa;">' +
            '<input type="checkbox" id="pred-notify" style="width:16px;height:16px;"> Notificarme si hay directo' +
        '</label>' +
        '<div style="display:flex;gap:8px;">' +
            '<button onclick="submitPrediction(' + idSafe + ')" style="flex:1;background:var(--accent);color:#000;border:none;border-radius:12px;padding:12px;font-weight:900;cursor:pointer;">ENVIAR</button>' +
            '<button onclick="document.getElementById(\'prediction-modal\').remove()" style="flex:1;background:#1a1a1a;color:#888;border:1px solid #333;border-radius:12px;padding:12px;font-weight:700;cursor:pointer;">CANCELAR</button>' +
        '</div>' +
    '</div>';
    modal.onclick = function(e){ if(e.target===modal) modal.remove(); };
    document.body.appendChild(modal);
};

window.submitPrediction = async function(matchId) {
    var sb = window._sb;
    var email = window.userData && window.userData.email;
    if (!sb || !email) return;
    var homeEl = document.getElementById('pred-home');
    var awayEl = document.getElementById('pred-away');
    var notifyEl = document.getElementById('pred-notify');
    var home = homeEl ? (parseInt(homeEl.value)||0) : 0;
    var away = awayEl ? (parseInt(awayEl.value)||0) : 0;
    var notify = notifyEl ? notifyEl.checked : false;
    await sb.from('match_predictions').upsert(
        { match_id: matchId, predictor_email: email, home_score: home, away_score: away },
        { onConflict: 'match_id,predictor_email' }
    ).catch(function(){});
    if (notify) {
        await sb.from('notifications').insert({
            user_email: email, type: 'live_request',
            content: 'Te avisaremos si hay directo en este partido.'
        }).catch(function(){});
    }
    if(typeof showToast==='function') showToast('Prediccion enviada!', 'success');
    var mod = document.getElementById('prediction-modal');
    if (mod) mod.remove();
};

