// COMPARTIR PARTIDO — DEEP LINK
// ============================================================
window.shareMatch = function(matchId, name, venue, dateStr) {
    var shareUrl = 'https://canchero-app.vercel.app/?invite=' + matchId;
    var nm = name || 'Partido';
    var existing = document.getElementById('share-match-modal');
    if (existing) existing.remove();
    var m = document.createElement('div');
    m.id = 'share-match-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:10001;background:rgba(0,0,0,0.85);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    function opt(icon, color, title, sub, onclick) {
        return '<button onclick="' + onclick + '" style="display:flex;align-items:center;gap:12px;background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:13px 15px;cursor:pointer;color:#fff;font-size:14px;font-weight:700;width:100%;text-align:left;margin-bottom:8px;">' +
            '<i class="bx ' + icon + '" style="font-size:20px;color:' + color + ';flex-shrink:0;"></i>' +
            '<div><div>' + title + '</div><div style="font-size:11px;color:#666;font-weight:400;">' + sub + '</div></div></button>';
    }
    m.innerHTML = '<div style="background:#0f110f;border:1px solid #1e1e1e;border-radius:20px;width:100%;max-width:400px;padding:20px;box-shadow:0 12px 50px rgba(0,0,0,0.7);">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">' +
            '<h3 style="font-size:15px;font-weight:900;margin:0;">📤 Compartir partido</h3>' +
            '<button onclick="document.getElementById(\'share-match-modal\').remove()" style="background:rgba(255,255,255,0.06);border:1px solid #333;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:18px;">&times;</button>' +
        '</div>' +
        opt('bx-user','var(--accent)','En mi perfil','Publicar el partido en tu perfil','window._shareMatchTo(\'post\',\'' + matchId + '\',this)') +
        opt('bx-news','var(--accent)','En el feed','Que lo vean todos','window._shareMatchTo(\'post\',\'' + matchId + '\',this)') +
        opt('bx-time-five','#9c88ff','En mis Momentos','Dura 12 horas','window._shareMatchTo(\'story\',\'' + matchId + '\',this)') +
        opt('bx-message-rounded','#64b4ff','Por mensaje','Enviar a un contacto','window._shareMatchTo(\'dm\',\'' + matchId + '\',this)') +
        opt('bx-link-external','#888','Copiar link / externo','WhatsApp, etc.','window._shareMatchExternal(\'' + matchId + '\',\'' + nm.replace(/'/g,"\\'") + '\')') +
    '</div>';
    m.onclick = function(e) { if (e.target === m) m.remove(); };
    document.body.appendChild(m);
    window._shareMatchData = { matchId: matchId, name: nm, venue: venue, dateStr: dateStr, url: shareUrl };
};

// Publicar texto simple al feed (usado por la ficha del partido)
window.createPostFromText = async function(text, mediaUrl, mediaType) {
    const sb = window._sb; const me = window.userData;
    if (!sb || !me) { if (typeof showToast==='function') showToast('Iniciá sesión.', 'warning'); return false; }
    try {
        const { error } = await sb.from('posts').insert({
            user_email: me.email, user_name: me.name || 'Jugador', user_role: me.role || 'jugador',
            user_avatar: me.photo || null,
            content: text, media_url: mediaUrl || null, media_type: mediaType || 'text', likes_count: 0,
            expires_at: new Date(Date.now()+12*3600000).toISOString()
        });
        if (error) throw error;
        return true;
    } catch(e) { console.error('createPostFromText', e); if (typeof showToast==='function') showToast('No se pudo publicar.', 'error'); return false; }
};

window._shareMatchExternal = function(matchId, name) {
    var d = window._shareMatchData || {};
    var shareUrl = d.url || ('https://canchero-app.vercel.app/?invite=' + matchId);
    var text = 'Partido: ' + (name||'Partido') + '\nUnite! ' + shareUrl;
    var modal = document.getElementById('share-match-modal'); if (modal) modal.remove();
    if (navigator.share) { navigator.share({ title: name||'Partido Canchero', text: text, url: shareUrl }).catch(function(){}); }
    else if (navigator.clipboard) { navigator.clipboard.writeText(shareUrl); if(typeof showToast==='function') showToast('Link copiado!', 'success'); }
    else { prompt('Copia el link del partido:', shareUrl); }
};

window._shareMatchTo = async function(dest, matchId, btn) {
    var d = window._shareMatchData || {};
    var sb = window._sb;
    var me = window.userData;
    if (!sb || !me) { if(typeof showToast==='function') showToast('Iniciá sesión.', 'error'); return; }
    var content = '⚽ ' + (d.name||'Partido') + (d.venue ? ' · 📍 ' + d.venue : '') + (d.dateStr ? ' · 📅 ' + d.dateStr : '') + '\n¡Sumate! ' + (d.url || ('https://canchero-app.vercel.app/?invite=' + matchId));
    if (btn) { btn.disabled = true; btn.style.opacity = '0.5'; }
    try {
        if (dest === 'post') {
            var { error: pe } = await sb.from('posts').insert({
                user_email: me.email, user_name: me.name, user_avatar: me.photo || null,
                user_role: me.role || 'jugador', content: content, media_type: 'text',
                likes_count: 0, comments_count: 0, pinned: false,
                expires_at: new Date(Date.now() + 12*60*60*1000).toISOString(), created_at: new Date().toISOString()
            });
            if (pe) throw pe;
            if(typeof showToast==='function') showToast('¡Partido compartido en tu perfil/feed!', 'success');
            try { if (typeof loadProfilePosts === 'function') loadProfilePosts(); } catch(e){}
        } else if (dest === 'story') {
            var { error: se } = await sb.from('stories').insert({
                user_email: me.email, user_name: me.name, user_role: me.role || 'jugador',
                content: content, media_url: null,
                expires_at: new Date(Date.now() + 12*60*60*1000).toISOString()
            });
            if (se) throw se;
            if(typeof showToast==='function') showToast('¡Partido en tu historia!', 'success');
            try { if (typeof social !== 'undefined' && social.loadStories) social.loadStories(); } catch(e){}
        } else if (dest === 'dm') {
            // Reutilizar el flujo de mensajería para elegir contacto
            document.getElementById('share-match-modal')?.remove();
            if (window.CancheroMessaging && typeof window.CancheroMessaging.init === 'function') {
                window.CancheroMessaging.init();
                if (typeof switchDashboardTab === 'function') switchDashboardTab(me.role||'jugador','mensajes',null);
                window._pendingMatchShareText = content;
                if(typeof showToast==='function') showToast('Elegí un chat y pegá el partido (copiado).', 'info');
                if (navigator.clipboard) navigator.clipboard.writeText(content);
            } else if (navigator.clipboard) {
                navigator.clipboard.writeText(content);
                if(typeof showToast==='function') showToast('Texto del partido copiado.', 'success');
            }
            return;
        }
        document.getElementById('share-match-modal')?.remove();
    } catch(e) {
        if(typeof showToast==='function') showToast('Error al compartir: ' + (e.message||e), 'error');
        if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    }
};

// Handler para deep link #partido/{id}
(function() {
    function _checkPartidoHash() {
        var hash = window.location.hash;
        if (hash && hash.startsWith('#partido/')) {
            var matchId = hash.replace('#partido/', '').split('?')[0].trim();
            if (matchId && window.MatchDashboard && typeof window.MatchDashboard.open === 'function') {
                setTimeout(function() { window.MatchDashboard.open(matchId); }, 2000);
            }
        }
    }
    if (document.readyState === 'loading') {
        window.addEventListener('load', _checkPartidoHash);
    } else {
        setTimeout(_checkPartidoHash, 2000);
    }
    window.addEventListener('hashchange', _checkPartidoHash);
})();

// ── Abrir post desde chat (link compartido) ──────────────────
window._openSharedPost = async function(postId) {
    // Navegar al feed y hacer scroll al post, o mostrar modal con el post
    const sb = window._sb;
    if (!sb) return;
    try {
        const { data: post } = await sb.from('posts').select('*').eq('id', postId).single();
        if (!post) { if (typeof showToast === 'function') showToast('Post no disponible.', 'warning'); return; }
        // Si es un reel, abrir el visor de reels haciendo foco en ese reel
        if (post.is_reel || post.media_type === 'video') {
            if (typeof window.openReels === 'function') {
                window._reelFocusId = postId;
                await window.openReels();
                // Scroll al reel target
                setTimeout(() => {
                    const sc = document.getElementById('reels-scroll');
                    if (!sc) return;
                    // Heurística: si el reel target no está cargado, recargar buscando por id
                    const allVids = sc.querySelectorAll('video');
                    let found = false;
                    allVids.forEach(v => { if (v.src && v.src.includes(post.media_url||'')) { v.scrollIntoView({behavior:'smooth',block:'start'}); found = true; }});
                    if (!found && post.media_url) {
                        // Si no se encontró, inyectar el reel target al principio
                        const card = document.createElement('div');
                        card.style.cssText = 'height:100vh;height:100dvh;min-height:100vh;width:100%;scroll-snap-align:start;scroll-snap-stop:always;position:relative;display:flex;align-items:center;justify-content:center;background:#000;';
                        const init = (post.user_name||'?')[0].toUpperCase();
                        card.innerHTML = `<video src="${post.media_url}" loop playsinline autoplay muted preload="auto" style="width:100%;height:100%;object-fit:contain;" onclick="this.muted=!this.muted"></video>
                            <div style="position:absolute;left:0;right:60px;bottom:0;padding:16px;background:linear-gradient(0deg,rgba(0,0,0,0.75),transparent);">
                                <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;"><div style="width:38px;height:38px;border-radius:50%;background:var(--accent);color:#000;font-weight:900;display:flex;align-items:center;justify-content:center;border:2px solid #fff;">${init}</div><div style="font-weight:800;font-size:14px;color:#fff;">${post.user_name||'Jugador'}</div></div>
                                ${post.content?`<div style="font-size:13px;color:#eee;">${(post.content||'').replace(/</g,'&lt;')}</div>`:''}</div>`;
                        sc.insertBefore(card, sc.firstChild);
                    }
                }, 300);
                return;
            }
        }
        // Mostrar en modal centrado
        const existing = document.getElementById('shared-post-view-modal');
        if (existing) existing.remove();
        const modal = document.createElement('div');
        modal.id = 'shared-post-view-modal';
        modal.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.9);display:flex;align-items:center;justify-content:center;padding:16px;';
        modal.innerHTML = `<div style="background:#111;border:1px solid #222;border-radius:20px;width:100%;max-width:420px;max-height:90vh;overflow-y:auto;padding:16px;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
                <div style="font-size:11px;color:var(--accent);font-weight:700;"><i class='bx bx-share-alt'></i> PUBLICACIÓN COMPARTIDA</div>
                <button onclick="document.getElementById('shared-post-view-modal').remove()" style="background:none;border:none;color:#888;font-size:22px;cursor:pointer;line-height:1;">&times;</button>
            </div>
            ${typeof buildPostCard === 'function' ? buildPostCard(post) : `<div style="padding:20px;color:#aaa;">${post.content||''}</div>`}
        </div>`;
        modal.onclick = function(e) { if (e.target === modal) modal.remove(); };
        document.body.appendChild(modal);
    } catch(e) { if (typeof showToast === 'function') showToast('No se pudo cargar el post.', 'error'); }
};

// ── CHECK-IN DE PARTIDOS ─────────────────────────────────────────────────────
window._myCheckins = window._myCheckins || new Set();

window._doMatchCheckin = async function(matchId, userEmail, matchPrice) {
    const sb = window._sb;
    const user = window.userData;
    if (!sb || !user) { if (typeof showToast === 'function') showToast('Iniciá sesión primero.', 'warning'); return; }
    try {
        const isCaptain = user.email === (window._captainEmailForMatch || user.email);
        const { error } = await sb.from('match_checkins').upsert({
            match_id: matchId,
            user_email: user.email,
            player_name: user.name || user.email,
            is_captain: isCaptain,
            team: 'home'
        }, { onConflict: 'match_id,user_email' });
        if (error && !error.message.includes('duplicate')) throw error;
        window._myCheckins.add(matchId);
        // Actualizar botón
        const btn = document.getElementById('checkin-btn-' + matchId);
        if (btn) btn.outerHTML = '<div style="background:rgba(0,230,118,0.1);border:1px solid #00e676;border-radius:10px;padding:8px;text-align:center;font-size:11px;font-weight:700;color:#00e676;margin-top:8px;"><i class=\'bx bx-check-circle\'></i> Check-in realizado ✓</div>';
        if (typeof showToast === 'function') showToast('¡Check-in realizado! ⚽✅', 'success');
    } catch(e) {
        if (typeof showToast === 'function') showToast('Error al hacer check-in: ' + (e.message||''), 'error');
    }
};

window._showCaptainQR = function(matchId) {
    const url = 'https://canchero-app.vercel.app/#checkin-' + matchId;
    const existing = document.getElementById('captain-qr-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'captain-qr-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.92);display:flex;align-items:center;justify-content:center;';
    modal.innerHTML = `<div style="background:#fff;border-radius:20px;padding:24px;text-align:center;max-width:300px;width:90%;">
        <div style="font-size:14px;font-weight:900;color:#000;margin-bottom:4px;">QR de Check-in</div>
        <div style="font-size:11px;color:#666;margin-bottom:16px;">Mostrá este QR a tus compañeros para que hagan check-in</div>
        <div id="captain-qr-canvas" style="display:flex;justify-content:center;"></div>
        <div style="font-size:10px;color:#999;margin-top:10px;word-break:break-all;">${url}</div>
        <button onclick="document.getElementById('captain-qr-modal').remove()" style="margin-top:14px;background:#111;color:#fff;border:none;border-radius:10px;padding:10px 24px;cursor:pointer;font-weight:700;">Cerrar</button>
    </div>`;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
    document.body.appendChild(modal);

    // Generar QR — cargar qrcodejs dinámicamente si no está
    function _renderQR() {
        const canvas = document.getElementById('captain-qr-canvas');
        if (!canvas) return;
        if (window.QRCode) {
            new window.QRCode(canvas, { text: url, width: 200, height: 200, colorDark: '#000', colorLight: '#fff' });
        } else {
            // Fallback: mostrar URL como texto
            canvas.innerHTML = '<div style="font-size:11px;color:#333;background:#f5f5f5;padding:12px;border-radius:8px;word-break:break-all;">' + url + '</div>';
            // Intentar cargar qrcodejs
            const s = document.createElement('script');
            s.src = 'https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';
            s.onload = () => { canvas.innerHTML = ''; new window.QRCode(canvas, { text: url, width: 200, height: 200 }); };
            document.head.appendChild(s);
        }
    }
    setTimeout(_renderQR, 100);
};

// Manejar hash #checkin-{matchId} al cargar
(function() {
    function _checkCheckinHash() {
        const hash = window.location.hash;
        if (hash && hash.startsWith('#checkin-')) {
            const matchId = hash.replace('#checkin-', '').split('?')[0].trim();
            if (!matchId) return;
            if (window.userData && window.userData.email) {
                window._doMatchCheckin(matchId, window.userData.email, 0);
            } else {
                // Esperar que se cargue el usuario
                window.addEventListener('_userLoaded', function handler() {
                    window.removeEventListener('_userLoaded', handler);
                    if (window.userData) window._doMatchCheckin(matchId, window.userData.email, 0);
                });
            }
        }
    }
    if (document.readyState === 'loading') window.addEventListener('load', function() { setTimeout(_checkCheckinHash, 2000); });
    else setTimeout(_checkCheckinHash, 2000);
    window.addEventListener('hashchange', _checkCheckinHash);
})();

// ── LIMPIEZA PERIÓDICA DE POSTS EXPIRADOS (desde frontend) ──────────────────
(function() {
    const CLEANUP_KEY = 'canchero_last_cleanup';
    const ONE_HOUR = 3600000;
    const last = parseInt(localStorage.getItem(CLEANUP_KEY) || '0');
    if (Date.now() - last > ONE_HOUR) {
        setTimeout(async function() {
            try {
                const sb = window._sb;
                if (!sb) return;
                await sb.rpc('cleanup_expired_posts');
                localStorage.setItem(CLEANUP_KEY, String(Date.now()));
            } catch(e) { /* silencioso */ }
        }, 5000);
    }
})();

// ── Jugadores disponibles para invitar a partido ─────────────────────────────
window._loadAvailablePlayersForMatch = async function(matchId, team) {
    const sb = window._sb;
    if (!sb) return;
    const existing = document.getElementById('avail-players-modal');
    if (existing) existing.remove();
    const modal = document.createElement('div');
    modal.id = 'avail-players-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,0.9);overflow-y:auto;padding:16px;';
    modal.innerHTML = `<div style="max-width:480px;margin:0 auto;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 0 16px;">
            <h3 style="font-family:Outfit,sans-serif;font-weight:900;font-size:16px;">🟢 Jugadores disponibles para invitar</h3>
            <button onclick="document.getElementById('avail-players-modal').remove()" style="background:none;border:none;color:#888;font-size:24px;cursor:pointer;">&times;</button>
        </div>
        <div id="avail-players-list"><div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:24px;"></i></div></div>
    </div>`;
    modal.onclick = e => { if (e.target === modal) modal.remove(); };
    document.body.appendChild(modal);
    try {
        const { data: players } = await sb.from('users')
            .select('email,name,photo,pos,city,available')
            .eq('available', true)
            .not('role', 'in', '("bot","admin","club","organizacion","tienda","profesional")')
            .limit(30);
        const listEl = document.getElementById('avail-players-list');
        if (!listEl) return;
        if (!players || !players.length) {
            listEl.innerHTML = '<div style="text-align:center;padding:30px;color:#555;">No hay jugadores disponibles en este momento.</div>';
            return;
        }
        listEl.innerHTML = players.map(p => `
            <div style="display:flex;align-items:center;gap:12px;padding:12px;border-bottom:1px solid #1a1a1a;">
                <div style="position:relative;flex-shrink:0;">
                    ${p.photo ? `<img src="${p.photo}" style="width:44px;height:44px;border-radius:50%;object-fit:cover;border:2px solid #333;">` : `<div style="width:44px;height:44px;border-radius:50%;background:rgba(186,255,0,0.1);border:2px solid rgba(186,255,0,0.2);display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--accent);">${(p.name||'?')[0].toUpperCase()}</div>`}
                    <span style="position:absolute;bottom:1px;right:1px;width:10px;height:10px;border-radius:50%;background:#00e676;border:2px solid #0d0d0d;"></span>
                </div>
                <div style="flex:1;min-width:0;">
                    <div style="font-weight:700;font-size:13px;">${p.name||p.email}</div>
                    <div style="font-size:10px;color:#666;">${p.pos||'JUG'} · ${p.city||'Uruguay'}</div>
                </div>
                <div style="display:flex;gap:6px;">
                    <button onclick="window.viewUserProfile&&window.viewUserProfile('${(p.email||'').replace(/'/g,"\\'")}' )" style="background:rgba(255,255,255,0.05);color:#aaa;border:1px solid #333;border-radius:8px;padding:5px 8px;font-size:10px;cursor:pointer;"><i class='bx bx-user'></i></button>
                    ${matchId ? `<button onclick="window.CancheroMatchPlayers&&window.CancheroMatchPlayers._sendInvite('${matchId}','${(p.email||'').replace(/'/g,"\\'")}','${(p.name||'').replace(/'/g,"\\'")}','${team||'home'}');document.getElementById('avail-players-modal').remove()" style="background:var(--accent);color:#000;border:none;border-radius:8px;padding:5px 10px;font-size:10px;font-weight:900;cursor:pointer;">INVITAR</button>` : ''}
                </div>
            </div>`).join('');
    } catch(e) { console.warn('loadAvailablePlayersForMatch:', e); }
};

// ── PANEL de NEGOCIO embebido (iframe del CRM dentro de la app) ──
// El negocio entra a su panel SIN perder el header (logo/rol/campana/ajustes)
// ni la barra inferior: el CRM se carga en un iframe fijo entre ambos.
window._ensureBizPanel = function(){
    var view = document.getElementById('view-jugador');
    if (!view) return;
    var sec = document.getElementById('jugador-panel');
    if (!sec) {
        var anchor = document.getElementById('jugador-feed');
        var parent = (anchor && anchor.parentNode) || view;
        sec = document.createElement('div');
        sec.id = 'jugador-panel';
        sec.className = 'dashboard-tab-content biz-panel-embed';
        sec.style.cssText = 'position:fixed;left:0;right:0;top:66px;bottom:80px;padding:0;margin:0;background:#0a0a0a;z-index:1;';
        sec.innerHTML = '<iframe id="biz-panel-iframe" title="Panel del negocio" style="width:100%;height:100%;border:0;display:block;background:#0a0a0a;"></iframe>';
        parent.appendChild(sec);
    }
    // SECCIONES DE LA APP dentro del panel (renderizadas por la APP, no por el CRM):
    // quedan abajo a la izquierda, debajo de la lista de opciones del panel, con
    // estilo propio que las distingue (son secciones fuera del panel, mismo rol).
    if (!document.getElementById('biz-panel-appnav')) {
        var nav2 = document.createElement('div');
        nav2.id = 'biz-panel-appnav';
        nav2.style.cssText = 'position:absolute;left:0;bottom:0;width:220px;max-width:56vw;z-index:5;background:rgba(10,14,10,0.97);border-top:1px dashed rgba(186,255,0,0.35);border-right:1px solid #1e201e;padding:8px 10px calc(8px + env(safe-area-inset-bottom));backdrop-filter:blur(8px);';
        var mk = function(icon, label, fn){
            return '<div onclick="' + fn + '" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;cursor:pointer;font-size:12.5px;color:#c8e6a0;font-weight:700;" onmouseover="this.style.background=\'rgba(186,255,0,0.1)\'" onmouseout="this.style.background=\'none\'">'
                 + '<i class="bx ' + icon + '" style="font-size:17px;width:20px;color:var(--accent);flex-shrink:0;"></i>' + label
                 + '<i class="bx bx-link-external" style="margin-left:auto;font-size:11px;opacity:.45;"></i></div>';
        };
        nav2.innerHTML =
            '<div style="font-size:9px;color:var(--accent);font-weight:900;letter-spacing:1.5px;margin:2px 0 5px;padding-left:10px;opacity:.85;">CANCHERO — MI APP</div>'
            + mk('bx-home-alt-2', 'Inicio', "switchDashboardTab('jugador','feed',null)")
            + mk('bx-search', 'Buscar', "switchDashboardTab('jugador','buscar',null)")
            + mk('bx-chat', 'Chats', "switchDashboardTab('jugador','mensajes',null)")
            + mk('bx-group', 'Comunidades', "window.CancheroComunidades&&CancheroComunidades.open()")
            + mk('bx-user', 'Mi Perfil', "switchDashboardTab('jugador','perfil',null)");
        sec.appendChild(nav2);
    }
    // Rol REAL del negocio (userData.role se corrompe a 'jugador'/vacío en memoria;
    // por eso el panel de la tienda abría el CRM de complejo). _trueRole lee el rol
    // persistido en localStorage, que es confiable.
    var role = (window._trueRole && window._trueRole()) || (window.userData && window.userData.role) || window._bizRole || 'club';
    // Sembrar la sesión que exigen las páginas crm-*.html (si falta, rebotan).
    try {
        var _u = window.userData || {};
        sessionStorage.setItem('crm_biz', JSON.stringify({
            email:_u.email, name:_u.name, role:role, account_status:'activo',
            photo:_u.photo, cover_photo:_u.cover_photo||_u.coverPhoto, city:_u.city, nat:_u.nat, sub_type:_u.subType||_u.sub_type
        }));
    } catch(e){}
    var iframe = document.getElementById('biz-panel-iframe');
    var map = { club:'crm-complejo.html', complejo:'crm-complejo.html', tienda:'crm-tienda.html', organizacion:'crm-organizacion.html', sponsor:'crm.html', profesional:'crm-profesional.html' };
    var src = map[role] || 'crm.html';
    if (iframe && iframe.getAttribute('data-src') !== src) {
        iframe.setAttribute('data-src', src);
        iframe.src = src + '?embed=1';
        iframe.onload = function(){ try { window._sizeBizPanel(); } catch(e){} };
    }
    window._sizeBizPanel();
    // Re-medir cuando header y barra ya estén posicionados (la barra monta/anima tarde).
    [120, 400, 1000, 2500].forEach(function(ms){ setTimeout(function(){ try { window._sizeBizPanel(); } catch(e){} }, ms); });
};
window._sizeBizPanel = function(){
    var sec = document.getElementById('jugador-panel'); if (!sec) return;
    var iframe = document.getElementById('biz-panel-iframe');
    var nav = document.getElementById('main-nav');
    var bar = document.getElementById('ruleta2-bar');
    var top = nav ? Math.round(nav.getBoundingClientRect().bottom) : 66;
    // En PC la barra inferior puede NO estar fija (o estar oculta): usar su top solo
    // si es una barra fixed visible; si no, el panel ocupa hasta el fondo de la ventana.
    // (Antes barTop daba 0 y el panel quedaba cortado a 220px de alto en escritorio.)
    var barTop = window.innerHeight;
    if (bar) {
        var _br = bar.getBoundingClientRect();
        var _fixed = false;
        try { _fixed = getComputedStyle(bar).position === 'fixed'; } catch(e){}
        if (_fixed && _br.height > 0 && _br.top > top + 100) barTop = _br.top;
    }
    var h = Math.max(220, Math.round(barTop - top - 6));
    sec.style.top = top + 'px';
    sec.style.bottom = 'auto';
    sec.style.height = h + 'px';
    if (iframe) iframe.style.height = h + 'px';
    // Atajos de la app: solo en PC (en el celular ya está la barra inferior)
    var nav2 = document.getElementById('biz-panel-appnav');
    if (nav2) {
        nav2.style.display = (window.innerWidth >= 900) ? '' : 'none';
        // Nunca tapado por la barra inferior: si se superponen, subirlo
        try {
            nav2.style.bottom = '0px';
            if (bar) {
                var nr = nav2.getBoundingClientRect();
                var br2 = bar.getBoundingClientRect();
                if (br2.height > 0 && nr.bottom > br2.top - 6) {
                    nav2.style.bottom = Math.round(nr.bottom - br2.top + 12) + 'px';
                }
            }
        } catch(e){}
    }
};
window.addEventListener('resize', function(){ try { window._sizeBizPanel && window._sizeBizPanel(); } catch(e){} });


/* ══════════════════════════════════════════════════════════════════════════
   RULETA NAV v2 — barra de 5 opciones + rueda radial con long-press
   - 5 opciones siempre visibles; la central es la sección actual (verde + glow)
   - Mantener presionado (≈480ms) o arrastrar abre la rueda radial
   - La rueda gira infinito en ambos sentidos; tic + vibración por cada cambio
   - La opción que queda en el centro define la sección de fondo
   - BUSCAR y CREAR despliegan sub-opciones; se cierran girando de nuevo
   - El movimiento es sólo horizontal; nada queda oculto arriba/abajo
══════════════════════════════════════════════════════════════════════════ */
(function(){
  var COMPLEJOS_SVG = "<svg viewBox='0 0 24 24' width='24' height='24' fill='none' stroke='currentColor' stroke-width='1.7'><rect x='2.5' y='4.5' width='19' height='15' rx='1.5'/><line x1='12' y1='4.5' x2='12' y2='19.5'/><circle cx='12' cy='12' r='2.6'/><rect x='2.5' y='8.5' width='3' height='7'/><rect x='18.5' y='8.5' width='3' height='7'/></svg>";

  // Orden circular. Centro por defecto = PERFIL (idx 0).
  // Izq: FEED, COMPLEJOS · Der: CHAT, PARTIDOS  (según pedido)
  // Barra FIJA de 5 (sin rueda), DINÁMICA por tipo de perfil activo.
  // Jugador/Club: Partidos · Buscar · Inicio · Chats · Perfil
  // Fanático:     Comunidades · Buscar · Inicio · Chats · Perfil
  function buildOpts(){
    var role = (window.userData && window.userData.role) || 'jugador';
    var bizRoles = ['club','complejo','tienda','organizacion','sponsor','profesional'];
    var t = (window._activeProfileType && window._activeProfileType()) || role;
    // Rol REAL confiable (userData.role se corrompe a 'jugador' en memoria).
    var trueRole = (window._trueRole && window._trueRole()) || role;
    var isBiz = (window._isBizAccount && window._isBizAccount()) || window._isBizUser || bizRoles.indexOf(trueRole) !== -1;
    var first;
    // Negocio: mostrar PANEL solo cuando la identidad ACTIVA es la de negocio
    // (si el usuario-negocio cambió a su identidad de jugador/fanático, va la barra normal).
    if (t === 'negocio' || (isBiz && t !== 'jugador' && t !== 'fanatico' && t !== 'team')) {
      // Negocio: primer ítem = Panel (abre su CRM)
      first = { id:'panel', label:'PANEL', icon:'bx-bar-chart-square', type:'tab', tab:'panel' };
    } else if (t === 'fanatico') {
      first = { id:'comunidades', label:'COMUNIDADES', icon:'bx-group', type:'action', fn:'comunidades' };
    } else {
      first = { id:'partidos', label:'PARTIDOS', icon:'bx-football', type:'tab', tab:'partidos', badge:'mobile-partidos-badge', badgeRed:true };
    }
    // Rol EQUIPO activo (C1): barra de 5 — Gestión · Buscar · Inicio · Partido · Perfil.
    if (t === 'team') {
      return [
        { id:'gestion',   label:'GESTIÓN',  icon:'bx-clipboard',    type:'action', fn:'gestion' },
        { id:'buscar',    label:'BUSCAR',   icon:'bx-search',       type:'tab', tab:'buscar' },
        { id:'feed',      label:'INICIO',   icon:'bx-home-alt',     type:'tab', tab:'feed' },
        { id:'partidos',  label:'PARTIDO',  icon:'bx-football',     type:'tab', tab:'partidos', badge:'mobile-partidos-badge', badgeRed:true },
        { id:'perfil',    label:'PERFIL',   icon:'bx-user',         type:'tab', tab:'perfil' } ];
    }
    return [ first,
      { id:'buscar',    label:'BUSCAR',   icon:'bx-search',       type:'tab', tab:'buscar' },
      { id:'feed',      label:'INICIO',   icon:'bx-home-alt',     type:'tab', tab:'feed' },
      { id:'mensajes',  label:'CHATS',    icon:'bx-message-dots', type:'tab', tab:'mensajes', badge:'mobile-msg-badge' },
      { id:'perfil',    label:'PERFIL',   icon:'bx-user',         type:'tab', tab:'perfil' } ];
  }
  void COMPLEJOS_SVG;
  var OPTS = buildOpts();
  var N = OPTS.length;
  // Reconstruir la barra cuando se cambia de perfil (fanático ↔ jugador/club)
  window._rebuildBottomNav = function(){ try {
    OPTS = buildOpts(); N = OPTS.length; STEP = 360 / N;
    // Centrar en INICIO (feed) sea cual sea el largo de la barra
    var fi = OPTS.findIndex(function(o){ return o.id === 'feed'; });
    state.index = fi >= 0 ? fi : Math.min(2, N-1);
    if (state.index >= N) state.index = Math.floor(N/2);
    renderBar();
    // PC (horizontal): el sidebar muestra las MISMAS 5 opciones del rol (Inicio arriba).
    try { window._renderSidebarNav && window._renderSidebarNav(); } catch(e){}
  } catch(e){} };
  // Exponer para el sidebar de PC (misma fuente de verdad que la rueda mobile).
  window._buildNavOpts = buildOpts;
  window._navActivate = function(o){ try { activate(o, false); } catch(e){} };
  // Render del sidebar de PC con EXACTAMENTE las 5 opciones del rol activo (Inicio arriba),
  // idénticas a la rueda inferior del celular. Reemplaza el menú estático largo.
  window._renderSidebarNav = function(){
    try {
      if (!window._buildNavOpts) return;
      var opts = (window._buildNavOpts() || []).slice();
      // Inicio (feed) primero.
      var fi = opts.findIndex(function(o){ return o.id === 'feed'; });
      if (fi > 0) { var f = opts.splice(fi, 1)[0]; opts.unshift(f); }
      var menus = document.querySelectorAll('#view-jugador .sidebar-menu, #view-club .sidebar-menu');
      if (!menus.length) return;
      var activeTab = 'feed';
      try { activeTab = (JSON.parse(localStorage.getItem('canchero_last_tab')||'{}').tab) || 'feed'; } catch(e){}
      var titleCase = function(s){ s = String(s||''); return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase(); };
      menus.forEach(function(menu){
        menu.innerHTML = opts.map(function(o){
          var lbl = (o.id === 'feed') ? 'Inicio' : titleCase(o.label);
          var isAct = (o.type === 'tab' && o.tab === activeTab) || (o.id === 'feed' && activeTab === 'feed');
          return '<li class="menu-item' + (isAct ? ' active' : '') + '"><i class="bx ' + (o.icon || 'bx-circle') + '"></i> ' + lbl + '</li>';
        }).join('');
        var lis = Array.from(menu.querySelectorAll('.menu-item'));
        lis.forEach(function(li, i){
          li.onclick = function(){
            lis.forEach(function(x){ x.classList.remove('active'); });
            li.classList.add('active');
            window._navActivate(opts[i]);
          };
        });
      });
    } catch(e){ console.warn('_renderSidebarNav', e && e.message); }
  };
  var STEP = 360 / N;            // grados entre opciones
  var R = 135;                   // radio donde van los iconos (px)
  var INNER_R = 92;              // radio interior del anillo glass
  var OUTER_R = 180;             // radio exterior del anillo glass
  var PIVOT_OFFSET = -15;        // centro de giro respecto al borde inferior
  var ARC = 52;                  // semiángulo visible (grados) — evita recorte lateral
  var DEG_PER_PX = 0.55;         // sensibilidad de arrastre
  var HOLD_MS = 600;             // tiempo de long-press para abrir la rueda
  var HINT_MAX = 1;              // veces que se muestra "mantené y girá" (se oculta tras el primer uso)

  var state = {
    index: 2,        // opción actual (centro) — INICIO centrado: partidos, buscar, inicio, chats, perfil
    rot: 0,          // rotación de la rueda en grados
    open: false,     // rueda desplegada
    centerI: 2,      // índice centrado durante el giro
    submenuId: null
  };

  // ---- audio "tic" (WebAudio) ----
  var _actx = null;
  function tic(){
    try {
      if (!_actx) _actx = new (window.AudioContext||window.webkitAudioContext)();
      var o = _actx.createOscillator(), g = _actx.createGain();
      o.type='square'; o.frequency.value=880;
      g.gain.setValueAtTime(0.05, _actx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.0001, _actx.currentTime+0.05);
      o.connect(g); g.connect(_actx.destination);
      o.start(); o.stop(_actx.currentTime+0.05);
    } catch(e){}
    try { if (navigator.vibrate) navigator.vibrate(8); } catch(e){}
  }

  function iconHTML(o, cls){
    if (o.svg) return o.svg;
    return "<i class='bx "+o.icon+"'></i>";
  }
  window._mundialIconFallback = function(img){ try{ var i=document.createElement('i'); i.className='bx bxs-trophy'; if(img&&img.parentNode) img.parentNode.replaceChild(i,img); }catch(e){} };

  function $(id){ return document.getElementById(id); }
  function mod(n,m){ return ((n%m)+m)%m; }

  // ---- BARRA: render de las 5 opciones centradas en state.index ----
  function renderBar(){
    var bar = $('ruleta2-bar');
    if (!bar) return;
    // preservar estado de badges antes de re-render
    var prevBadges = {};
    bar.querySelectorAll('.r2-badge').forEach(function(b){ prevBadges[b.id] = { t:b.textContent, d:b.style.display }; });

    // Barra FIJA: siempre las 5 en orden, se resalta la activa (no rota)
    var html = '';
    for (var i=0; i<N; i++){
      var o = OPTS[i];
      var center = (i===state.index);
      var colorStyle = (!center && o.color) ? ('color:'+o.color+';') : '';
      html += "<div class='r2-item"+(center?' r2-center':'')+"' data-i='"+i+"' style='"+colorStyle+"'>";
      html += "<span class='r2-ico'>"+iconHTML(o)+"</span>";
      if (o.badge) html += "<span class='r2-badge"+(o.badgeRed?' red':'')+"' id='"+o.badge+"'></span>";
      if (o.type==='submenu') html += "<i class='bx bx-chevron-up r2-caret'></i>";
      html += "<span>"+o.label+"</span></div>";
    }
    bar.innerHTML = html;
    // restaurar badges SOLO si tenían un número positivo (evita dots rojos fantasma)
    bar.querySelectorAll('.r2-badge').forEach(function(b){
      var prev = prevBadges[b.id];
      var n = prev ? parseInt(prev.t, 10) : 0;
      if (prev && n > 0){ b.textContent = prev.t; b.style.display = prev.d || 'flex'; }
      else { b.textContent = ''; b.style.display = 'none'; }
    });
  }

  // ---- Ejecutar la acción de una opción ----
  function activate(o, live){
    if (!o) return;
    // Cerrar SIEMPRE el modal flotante de perfil ajeno antes de cualquier navegación
    try { var _v = document.getElementById('vup-modal-overlay'); if (_v) _v.remove(); } catch(e){}
    try { var _vm = document.getElementById('vup-more-modal'); if (_vm) _vm.remove(); } catch(e){}
    if (o.type==='tab'){
      try { window.switchDashboardTab && window.switchDashboardTab('jugador', o.tab, null); } catch(e){}
    } else if (!live) {
      // acciones / submenús sólo al soltar (no en vivo durante el giro)
      if (o.type==='submenu'){ openSubmenu(o.sub); return; }
      switch(o.fn){
        case 'partidos': try{ window._setPartidosNavActive&&window._setPartidosNavActive(); window.showPartidosSheet&&window.showPartidosSheet(); }catch(e){} break;
        case 'torneos':  try{ window.openTorneosModal&&window.openTorneosModal(); }catch(e){} break;
        case 'juegos':   try{ window.openGamesModal&&window.openGamesModal(); }catch(e){} break;
        case 'comunidades': try{ window.CancheroComunidades&&window.CancheroComunidades.open(); }catch(e){} break;
        case 'gestion': try{
            // Abrir la gestión del EQUIPO activo
            var _tid = (window.userData && window.userData._activeClubId) || null;
            if (!_tid) { try { var _at = JSON.parse(localStorage.getItem('canchero_active_team')||'null'); _tid = _at && _at.id; } catch(_e){} }
            if (_tid) window.currentEditingClubId = _tid;
            window.switchDashboardTab && window.switchDashboardTab('jugador', 'club-gestion', null);
        }catch(e){} break;
        case 'plantilla': try{
            // Abrir la GESTIÓN del equipo directamente en la PLANILLA (gestionar jugadores),
            // NO el perfil público (antes abría viewClubProfile y "llevaba al perfil").
            var _pid = (window.userData && window.userData._activeClubId) || null;
            if (!_pid) { try { var _at2 = JSON.parse(localStorage.getItem('canchero_active_team')||'null'); _pid = _at2 && _at2.id; } catch(_e){} }
            if (_pid) window.currentEditingClubId = _pid;
            if (window.switchDashboardTab) window.switchDashboardTab('jugador', 'club-gestion', null);
            setTimeout(function(){ try {
                var b = Array.from(document.querySelectorAll('.club-gestion-tab')).find(function(x){ return (x.getAttribute('onclick')||'').indexOf("'planilla'")!==-1; });
                if (b) b.click(); else if (window.switchClubGestionTab) window.switchClubGestionTab('planilla');
            } catch(e){} }, 250);
        }catch(e){} break;
        case 'panel': try{
            var _r=(window.userData&&window.userData.role)||window._bizRole||'club';
            var _m={club:'crm-complejo.html',complejo:'crm-complejo.html',tienda:'crm-tienda.html',organizacion:'crm-organizacion.html',sponsor:'crm.html'};
            // Pasar la sesión de negocio al CRM: las páginas crm-*.html exigen
            // sessionStorage.crm_biz (si falta, rebotan a crm.html y "el panel no abre").
            // Lo sembramos desde userData (la página luego re-fetchea la fila completa).
            try {
              var _u = window.userData || {};
              sessionStorage.setItem('crm_biz', JSON.stringify({
                email: _u.email, name: _u.name, role: _r,
                account_status: 'activo',
                photo: _u.photo, cover_photo: _u.cover_photo || _u.coverPhoto,
                city: _u.city, nat: _u.nat, sub_type: _u.subType || _u.sub_type
              }));
            } catch(e){}
            window.location.href=_m[_r]||'crm.html';
        }catch(e){} break;
        case 'organizaciones': try{ window.openGlobalDirectory&&window.openGlobalDirectory('organizaciones'); }catch(e){} break;
      }
    }
  }

  // ---- Seleccionar opción (desde tap en barra o al soltar la rueda) ----
  function select(i, opts){
    opts = opts || {};
    state.index = mod(i, N);
    renderBar();
    var o = OPTS[state.index];
    if (o.type !== 'submenu') closeSubmenu();
    activate(o, false);
  }

  // Exponer para que canchero-swipe pueda sincronizar la barra al navegar con gesto
  window._ruleta2SelectById = function(optsId) {
    for (var i = 0; i < N; i++) {
      if (OPTS[i].id === optsId) { select(i); return; }
    }
  };
  // Sincronización SOLO visual (no re-activa la sección — evita doble render al swipear)
  window._ruleta2SyncById = function(optsId) {
    for (var i = 0; i < N; i++) {
      if (OPTS[i].id === optsId) { state.index = i; renderBar(); closeSubmenu(); return; }
    }
  };

  // ========================= RUEDA RADIAL =========================
  // Construye el disco glass (anillo + líneas divisorias) como SVG
  function buildDisc(){
    var disc = $('ruleta2-wheel');
    if (!disc) return;
    var size = OUTER_R*2, c = OUTER_R, ringR = (INNER_R+OUTER_R)/2, ringW = (OUTER_R-INNER_R);
    var lines = '';
    for (var i=0;i<N;i++){
      var a = ((i+0.5)*STEP) * Math.PI/180;   // ángulo del divisor (entre opciones)
      var x1 = c + INNER_R*Math.sin(a), y1 = c - INNER_R*Math.cos(a);
      var x2 = c + OUTER_R*Math.sin(a), y2 = c - OUTER_R*Math.cos(a);
      lines += "<line x1='"+x1.toFixed(1)+"' y1='"+y1.toFixed(1)+"' x2='"+x2.toFixed(1)+"' y2='"+y2.toFixed(1)+"' stroke='rgba(255,255,255,0.16)' stroke-width='1.2'/>";
    }
    disc.style.width = size+'px';
    disc.style.height = size+'px';
    disc.innerHTML =
      "<svg width='"+size+"' height='"+size+"' viewBox='0 0 "+size+" "+size+"'>"
      + "<defs>"
      + "<linearGradient id='r2glass' x1='0' y1='0' x2='0' y2='1'>"
      +   "<stop offset='0' stop-color='rgba(255,255,255,0.16)'/>"
      +   "<stop offset='0.5' stop-color='rgba(255,255,255,0.05)'/>"
      +   "<stop offset='1' stop-color='rgba(255,255,255,0.02)'/>"
      + "</linearGradient>"
      + "<radialGradient id='r2glow' cx='0.5' cy='0.5' r='0.5'>"
      +   "<stop offset='0' stop-color='rgba(186,255,0,0.10)'/>"
      +   "<stop offset='1' stop-color='rgba(186,255,0,0)'/>"
      + "</radialGradient>"
      + "</defs>"
      + "<circle cx='"+c+"' cy='"+c+"' r='"+ringR+"' fill='none' stroke='url(#r2glass)' stroke-width='"+ringW+"'/>"
      + "<circle cx='"+c+"' cy='"+c+"' r='"+ringR+"' fill='none' stroke='url(#r2glow)' stroke-width='"+ringW+"'/>"
      + "<circle cx='"+c+"' cy='"+c+"' r='"+OUTER_R+"' fill='none' stroke='rgba(255,255,255,0.20)' stroke-width='1.3'/>"
      + "<circle cx='"+c+"' cy='"+c+"' r='"+INNER_R+"' fill='none' stroke='rgba(255,255,255,0.12)' stroke-width='1'/>"
      + lines
      + "</svg>";
  }

  function buildWheelSegs(){
    var wheel = $('ruleta2-wheel-layer');
    if (!wheel) return;
    // limpiar segmentos previos
    wheel.querySelectorAll('.ruleta2-seg').forEach(function(s){ s.remove(); });
    for (var i=0;i<N;i++){
      var o = OPTS[i];
      var seg = document.createElement('div');
      seg.className = 'ruleta2-seg';
      seg.dataset.i = i;
      seg.innerHTML = iconHTML(o)+"<span>"+o.label+"</span>";
      wheel.appendChild(seg);
    }
  }

  function layoutWheel(){
    var layer = $('ruleta2-wheel-layer');
    if (!layer) return;
    var cx = window.innerWidth/2;
    var pivotY = window.innerHeight + PIVOT_OFFSET;
    // posicionar + rotar el disco glass
    var disc = $('ruleta2-wheel');
    if (disc){ disc.style.left = cx+'px'; disc.style.top = pivotY+'px';
      disc.style.transform = 'translate(-50%,-50%) rotate('+state.rot+'deg)'; }
    var segs = layer.querySelectorAll('.ruleta2-seg');
    var best=0, bestAbs=999;
    segs.forEach(function(seg){
      var i = +seg.dataset.i;
      var theta = i*STEP + state.rot;           // 0 = arriba
      var tn = ((theta+180)%360+360)%360-180;   // normalizado [-180,180]
      var rad = tn*Math.PI/180;
      var x = cx + R*Math.sin(rad);
      var y = pivotY - R*Math.cos(rad);
      var ad = Math.abs(tn);
      var vis = ad < ARC;
      var sc = 0.5 + 0.5*Math.cos(rad);
      seg.style.left = x+'px';
      seg.style.top  = y+'px';
      seg.style.transform = 'translate(-50%,-50%) scale('+(vis?sc:0.4)+')';
      seg.style.opacity = vis ? String(Math.max(0, (Math.cos(rad)-0.25)/0.75)) : '0';
      seg.classList.toggle('r2-on', ad < STEP/2);
      if (ad < bestAbs){ bestAbs=ad; best=i; }
    });
    // posicionar pin / label
    var pin = layer.querySelector('.ruleta2-center-pin');
    var lbl = $('ruleta2-wheel-label');
    var centeredAbove = window.innerHeight - (pivotY - R); // px sobre el borde inferior
    if (pin){ pin.style.bottom = (centeredAbove - 35) + 'px'; }
    if (lbl){ lbl.style.bottom = (centeredAbove + 52) + 'px'; lbl.textContent = OPTS[best].label; }
    // cambio de centro → tic + (en vivo) sección
    if (best !== state.centerI){
      state.centerI = best;
      tic();
      var o = OPTS[best];
      // fondo en vivo sólo para tabs y sólo durante arrastre manual (no en inercia)
      if (o.type==='tab' && !state._momentum) activate(o, true);
    }
  }

  function bumpHint(){
    try {
      var c = parseInt(localStorage.getItem('r2_hint_count')||'0',10) + 1;
      localStorage.setItem('r2_hint_count', String(c));
      if (c >= HINT_MAX){ var h=$('ruleta2-hint'); if(h) h.style.display='none'; }
    } catch(e){}
  }

  function openWheel(){
    if (state.open) return;
    state.open = true;
    _wheelWatchdog();
    state.rot = -state.index*STEP;
    state.centerI = state.index;
    var layer = $('ruleta2-wheel-layer');
    if (!layer) return;
    closeSubmenu();
    buildDisc();
    buildWheelSegs();
    layer.style.display = 'block';
    layer.classList.add('open');
    document.body.classList.add('r2-wheel-open'); // bloquea scroll → no secuestra el giro
    layoutWheel();
    bumpHint();
    try { if (navigator.vibrate) navigator.vibrate(15); } catch(e){}
  }

  // Guardias anti-trancado de la rueda (2026-06-13):
  // 1) tocar fuera del disco la cierra; 2) si queda abierta 8s sin gesto, se
  //    cierra sola; 3) cualquier scroll/teclado tambien la cierra.
  function _wheelWatchdog(){
    clearTimeout(window.__r2wd);
    window.__r2wd = setTimeout(function(){ if (state.open && !state._momentum) closeWheel(true); }, 8000);
  }
  // Cerrar al tocar FUERA — pero nunca durante un gesto activo sobre la rueda
  document.addEventListener('touchstart', function(ev){
    if (!state.open || state._touching) return;
    _wheelWatchdog();
    var inUI = ev.target.closest && (ev.target.closest('.ruleta2-nav') || ev.target.closest('#ruleta2-wheel-layer'));
    if (!inUI) closeWheel(false);
  }, { passive: true });
  // El scroll YA NO cierra la rueda (cerraba el giro a mitad de camino en el
  // celular por microscrolls — esa era la causa del "se traba").

  function closeWheel(commit){
    if (!state.open) return;
    state.open = false;
    var layer = $('ruleta2-wheel-layer');
    if (layer){ layer.classList.remove('open'); layer.style.display = 'none'; }
    document.body.classList.remove('r2-wheel-open');
    if (commit){
      // snap a la opción centrada
      select(state.centerI);
    }
  }

  // ========================= SUB-MENÚS =========================
  var SUBMENUS = {
    buscar: { title:'BUSCAR', items:[
      { ic:'bx-run',        label:'Jugadores',        run:function(){ window.openGlobalDirectory&&window.openGlobalDirectory('jugadores'); } },
      { ic:'bx-shield',     label:'Equipos / Clubes', run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','buscar-clubes',null); } },
      { ic:'bx-map-pin',    label:'Canchas',          run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','buscar-canchas',null); } },
      { ic:'bx-cancha', label:'Complejos',    run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','complejos',null); } },
      { ic:'bx-buildings',  label:'Organizaciones',   run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','organizaciones',null); } },
      { ic:'bx-trophy',     label:'Torneos',          run:function(){ window.openTorneosModal&&window.openTorneosModal(); } },
      { ic:'bx-store',      label:'Tiendas',          run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','tiendas',null); } },
      { ic:'bx-briefcase',  label:'Profesionales',    run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','profesionales',null); } },
      { ic:'bx-circle',     label:'Disponibles',      run:function(){ window.openDisponiblesModal&&window.openDisponiblesModal(); } }
    ]},
    crear: { title:'CREAR', items:[
      { ic:'bx-football',     label:'Crear Partido', run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','crear-partido',null); } },
      { ic:'bx-shield-plus',  label:'Crear Equipo',  run:function(){ if(window.openClubCreator)window.openClubCreator(); else window.switchDashboardTab&&window.switchDashboardTab('jugador','mis-clubes',null); } },
      { ic:'bx-trophy',       label:'Crear Torneo',  run:function(){ window.switchDashboardTab&&window.switchDashboardTab('jugador','crear-torneo',null); } }
    ]}
  };

  function openSubmenu(id){
    var cfg = SUBMENUS[id];
    var box = $('ruleta2-submenu');
    if (!cfg || !box) return;
    state.submenuId = id;
    var html = "<div class='r2-sub-card'><div class='r2-sub-head'><span>"+cfg.title+"</span>"
      + "<button onclick=\"window._r2CloseSub&&window._r2CloseSub()\">&times;</button></div>";
    cfg.items.forEach(function(it,idx){
      html += "<div class='r2-sub-item' data-sub='"+id+"' data-idx='"+idx+"'><i class='bx "+it.ic+"'></i> "+it.label+"</div>";
    });
    html += "</div>";
    box.innerHTML = html;
    box.style.display = 'flex';
    // tocar el fondo (fuera de la tarjeta) cierra
    box.onclick = function(e){ if (e.target === box) closeSubmenu(); };
    box.querySelectorAll('.r2-sub-item').forEach(function(el){
      el.addEventListener('click', function(){
        var s = el.dataset.sub, k = +el.dataset.idx;
        try { SUBMENUS[s].items[k].run(); } catch(e){}
        closeSubmenu();
      });
    });
  }
  function closeSubmenu(){
    var box = $('ruleta2-submenu');
    if (box){ box.style.display='none'; box.innerHTML=''; }
    state.submenuId = null;
  }
  window._r2CloseSub = closeSubmenu;

  // ========================= GESTOS =========================
  function bindGestures(){
    var nav = $('player-bottom-nav');
    if (!nav || nav._r2bound) return;
    nav._r2bound = true;

    var holdTimer=null, startX=0, startY=0, downI=-1, dragging=false, moved=false, lastX=0;
    var _vel=0, _lastT=0, _momentumRAF=null;

    function pdown(e){
      var pt = e.touches ? e.touches[0] : e;
      startX = lastX = pt.clientX; startY = pt.clientY;
      moved = false; dragging = false; state._touching = true;
      _vel = 0; _lastT = (e.timeStamp || Date.now());
      if (_momentumRAF){ cancelAnimationFrame(_momentumRAF); _momentumRAF = null; }
      var item = e.target.closest('.r2-item');
      downI = item ? +item.dataset.i : state.index;
      // Rueda desactivada: barra fija de 5, sin long-press.
    }
    function pmove(e){
      var pt = e.touches ? e.touches[0] : e;
      var dx = pt.clientX - startX, dy = pt.clientY - startY;
      if (!moved && (Math.abs(dx)>14 || Math.abs(dy)>14)) moved = true;
      // Rueda desactivada: no abrir por arrastre.
      if (state.open){
        if (e.cancelable) e.preventDefault();
        _wheelWatchdog();
        var ddx = pt.clientX - lastX; lastX = pt.clientX;
        var deg = ddx * DEG_PER_PX;
        state.rot -= deg;
        _vel = -deg; // velocidad para el fling
        layoutWheel();
      }
    }
    function pup(e){
      clearTimeout(holdTimer);
      state._touching = false;
      if (state.open){
        if (Math.abs(_vel) > 1.2){ _runMomentum(); } else { _snapAndClose(); }
      } else if (!moved){
        // tap simple → seleccionar esa opción / abrir submenú si es la central
        // (con lockout de 350ms: la barra se re-centra al seleccionar y un
        // segundo tap inmediato caía sobre otro ícono → "salteaba" secciones)
        if (window.__r2TapLock && Date.now() - window.__r2TapLock < 350) { dragging=false; return; }
        window.__r2TapLock = Date.now();
        var o = OPTS[mod(downI,N)];
        if (downI===state.index && o.type==='submenu'){ openSubmenu(o.sub); }
        else select(downI);
      }
      dragging=false;
    }

    // Inercia: la rueda sigue girando con la velocidad del flick y desacelera,
    // luego hace snap a la opción centrada. Permite recorrer todas las opciones.
    function _runMomentum(){
      var FRICTION = 0.94;   // desaceleración por frame
      var MIN_VEL = 0.4;     // por debajo de esto, frena y hace snap
      state._momentum = true;
      function step(){
        state.rot += _vel;
        _vel *= FRICTION;
        layoutWheel();
        if (Math.abs(_vel) > MIN_VEL){
          _momentumRAF = requestAnimationFrame(step);
        } else {
          _momentumRAF = null;
          // alinear a la sección más cercana antes de cerrar (nunca a mitad de camino)
          _snapAndClose();
        }
      }
      _momentumRAF = requestAnimationFrame(step);
    }

    // Anima la rotación hasta dejar EXACTAMENTE una sección centrada (12 en punto)
    // y recién ahí confirma + cierra. Evita que frene entre dos secciones.
    function _snapAndClose(){
      var centerI = Math.round(-state.rot / STEP);
      var target = -centerI * STEP;
      state._momentum = true;
      function anim(){
        var diff = target - state.rot;
        if (Math.abs(diff) < 0.4){
          state.rot = target; layoutWheel();
          state._momentum = false; _momentumRAF = null;
          closeWheel(true);
          return;
        }
        state.rot += diff * 0.22;
        layoutWheel();
        _momentumRAF = requestAnimationFrame(anim);
      }
      _momentumRAF = requestAnimationFrame(anim);
    }

    // touch — también sobre la RUEDA desplegada (antes solo la barra recibía
    // los gestos: si levantabas el dedo y volvías a tocar el disco, se trancaba)
    var _lastTouchT = 0;
    function tdown(e){ _lastTouchT = Date.now(); pdown(e); }
    function tend(e){ _lastTouchT = Date.now(); pup(e); }
    nav.addEventListener('touchstart', tdown, {passive:true});
    nav.addEventListener('touchmove', pmove, {passive:false});
    nav.addEventListener('touchend', tend);
    nav.addEventListener('touchcancel', function(){ _lastTouchT = Date.now(); clearTimeout(holdTimer); if(state.open) closeWheel(true); });
    var wheelLayer = document.getElementById('ruleta2-wheel-layer');
    if (wheelLayer){
      wheelLayer.addEventListener('touchstart', function(e){ if(!state.open) return; _lastTouchT=Date.now(); state._touching=true; var pt=e.touches[0]; startX=lastX=pt.clientX; startY=pt.clientY; moved=true; _vel=0; if(_momentumRAF){cancelAnimationFrame(_momentumRAF);_momentumRAF=null;state._momentum=false;} }, {passive:true});
      wheelLayer.addEventListener('touchmove', pmove, {passive:false});
      wheelLayer.addEventListener('touchend', tend);
      wheelLayer.addEventListener('touchcancel', function(){ _lastTouchT=Date.now(); if(state.open) closeWheel(true); });
    }

    // La rotación la maneja pmove (en nav y en wheelLayer). Con touch-action:none
    // en toda la capa (CSS) el navegador ya no secuestra el arrastre como scroll,
    // así que el gesto desde el centro-abajo (backdrop) también rota bien.
    // mouse (desktop / preview) — ignorar los "ghost clicks" que el WebView
    // dispara ~300ms después de cada touch (causaban doble selección)
    nav.addEventListener('mousedown', function(e){ if(e.button!==0) return; if (Date.now()-_lastTouchT < 800) return; pdown(e);
      document.addEventListener('mousemove', mm); document.addEventListener('mouseup', mu); });
    function mm(e){ pmove(e); }
    function mu(e){ if (Date.now()-_lastTouchT < 800) { document.removeEventListener('mousemove', mm); document.removeEventListener('mouseup', mu); return; } pup(e); document.removeEventListener('mousemove', mm); document.removeEventListener('mouseup', mu); }

    // cerrar submenú al tocar fuera
    document.addEventListener('click', function(e){
      if (state.submenuId && !e.target.closest('#ruleta2-submenu') && !e.target.closest('#player-bottom-nav')){
        closeSubmenu();
      }
    });
    window.addEventListener('resize', function(){ if(state.open) layoutWheel(); });
  }

  // Sincronizar el centro de la barra cuando otras partes cambian de tab
  window._r2SyncTab = function(tabId){
    // FIX 2026-06-11: el mapa viejo tenía índices de cuando OPTS tenía 15
    // opciones y dejaba la barra marcando una sección equivocada.
    var map = { 'partidos':'partidos','mis-partidos':'partidos','crear-partido':'partidos','buscar-partidos':'partidos',
      'buscar':'buscar','buscar-clubes':'buscar','buscar-canchas':'buscar','complejos':'buscar','tiendas':'buscar','profesionales':'buscar','organizaciones':'buscar',
      'feed':'feed','amigos':'feed','mensajes':'mensajes','perfil':'perfil',
      'mis-clubes':'equipos','ranking':'ranking','juegos':'juegos','en-vivo':'envivo' };
    var id = map[tabId];
    if (!id) return;
    for (var i=0;i<N;i++){ if (OPTS[i].id===id){ state.index=i; if(!state.open) renderBar(); return; } }
  };

  // Navegar a la sección siguiente/anterior SOLO entre tabs reales (para swipe global)
  window._r2SwipeSection = function(dir){
    var step = dir > 0 ? 1 : -1;
    var i = state.index;
    for (var c = 0; c < N; c++){
      i = mod(i + step, N);
      if (OPTS[i] && OPTS[i].type === 'tab'){ select(i); return; }
    }
  };

  // ── SWIPE GLOBAL ENTRE SECCIONES con animación visible ──
  function bindGlobalSectionSwipe(){
    if (window._globalSwipeBound) return;
    window._globalSwipeBound = true;

    // Indicadores de flecha en los bordes
    var indL = document.createElement('div');
    var indR = document.createElement('div');
    var _indBase = 'position:fixed;top:50%;transform:translateY(-50%);z-index:19999;pointer-events:none;font-size:22px;color:rgba(255,255,255,0.85);background:rgba(0,0,0,0.45);border-radius:50%;width:40px;height:40px;display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity .12s;';
    indL.style.cssText = _indBase + 'left:6px;';
    indR.style.cssText = _indBase + 'right:6px;';
    indL.innerHTML = '&#9664;';
    indR.innerHTML = '&#9654;';
    document.body.appendChild(indL);
    document.body.appendChild(indR);

    function getWrapper(){
      // Primer .dashboard-content visible (el del rol activo)
      var all = document.querySelectorAll('.dashboard-content');
      for (var i=0;i<all.length;i++){ if (all[i].offsetParent!==null) return all[i]; }
      return null;
    }

    function isExcluded(el){
      if (!el || !el.closest) return false;
      // feed-swipe-wrap ya no excluye — manejamos el swipe del feed manualmente
      return !!el.closest('input,textarea,select,video,canvas,[data-no-swipe],.ruleta2-nav,.msg-chat-area,.fut-card-3d-container,#tactic-board,.leaflet-container,[style*="overflow-x:auto"],[style*="overflow-x: auto"],[style*="overflow-x:scroll"],#reels-scroll');
    }

    function anyOverlayOpen(){
      var ids=['match-dashboard-overlay','torneos-modal','game-player-modal','live-viewer-modal','hilos-modal','post-thread-modal','reply-post-modal','edit-profile-modal'];
      for (var i=0;i<ids.length;i++){ var e=document.getElementById(ids[i]); if (e && e.style.display!=='none' && e.offsetParent!==null) return true; }
      if (document.querySelector('.modal-overlay[style*="flex"]')) return true;
      return false;
    }

    function reelsOpen(){
      var r=document.getElementById('reels-modal'); return !!(r && r.offsetParent!==null);
    }

    function feedVisible(){
      var f=document.getElementById('jugador-feed'); return !!(f && f.style.display!=='none' && f.offsetParent!==null);
    }

    function setTranslate(el, dx){
      if (!el) return;
      el.style.transition='none';
      el.style.transform='translate3d('+Math.round(dx)+'px,0,0)';
    }

    function snapBack(el){
      if (!el) return;
      el.style.transition='transform .22s cubic-bezier(0.25,0.46,0.45,0.94)';
      el.style.transform='translate3d(0,0,0)';
      setTimeout(function(){ if(el){ el.style.transition=''; el.style.transform=''; }},240);
    }

    function snapNavigate(el, toRight){
      if (!el) return;
      var out=(toRight?1:-1)*Math.round(window.innerWidth*0.28);
      el.style.transition='transform .18s ease';
      el.style.transform='translate3d('+out+'px,0,0)';
      setTimeout(function(){ if(el){ el.style.transition=''; el.style.transform=''; }},200);
    }

    var sx=0,sy=0,t0=0,tracking=false,moving=false,wrapper=null;

    document.addEventListener('touchstart',function(e){
      if(reelsOpen()){
        // Dentro del modal de Reels — rastrear para swipe horizontal de cierre
        if(e.target.closest && e.target.closest('#reels-scroll')){ tracking=false; return; }
        var t=e.touches[0]; sx=t.clientX; sy=t.clientY; t0=Date.now(); tracking=true; moving=false; wrapper=null;
        return;
      }
      if(anyOverlayOpen()||isExcluded(e.target)){ tracking=false; return; }
      var t=e.touches[0]; sx=t.clientX; sy=t.clientY; t0=Date.now(); tracking=true; moving=false;
      wrapper=getWrapper();
    },{passive:true});

    document.addEventListener('touchmove',function(e){
      if(!tracking) return;
      var t=e.touches[0], dx=t.clientX-sx, dy=t.clientY-sy;
      if(!moving&&Math.abs(dx)<8) return;
      if(!moving&&Math.abs(dy)>Math.abs(dx)){ tracking=false; snapBack(wrapper); return; }
      moving=true;
      if(!reelsOpen()&&wrapper){
        setTranslate(wrapper, dx*0.32);
      }
      // Indicadores
      var pct=Math.min(Math.abs(dx)/110,1);
      if(dx<-12){ indR.style.opacity=String(pct*0.9); indL.style.opacity='0'; }
      else if(dx>12){ indL.style.opacity=String(pct*0.9); indR.style.opacity='0'; }
      else{ indL.style.opacity='0'; indR.style.opacity='0'; }
    },{passive:true});

    document.addEventListener('touchend',function(e){
      indL.style.opacity='0'; indR.style.opacity='0';
      if(!tracking||!moving){ tracking=false; return; }
      tracking=false;
      var t=e.changedTouches[0], dx=t.clientX-sx, dy=t.clientY-sy, dt=Date.now()-t0;
      var THRESH=80;

      if(dt>650||Math.abs(dx)<THRESH||Math.abs(dx)<Math.abs(dy)*1.5){
        snapBack(wrapper); return;
      }

      // CASO: modal de Reels abierto
      if(reelsOpen()){
        var rm=document.getElementById('reels-modal');
        if(dx>0){
          // Derecha → volver a Publicaciones
          if(rm){ rm.style.transition='opacity .18s'; rm.style.opacity='0'; setTimeout(function(){ rm.remove(); },200); }
        } else {
          // Izquierda → cerrar Reels y sección siguiente
          if(rm){ rm.style.transition='opacity .15s'; rm.style.opacity='0'; setTimeout(function(){ rm.remove(); window._r2SwipeSection&&window._r2SwipeSection(1); },180); }
        }
        return;
      }

      // CASO: feed/Inicio en Publicaciones — a Reels SOLO se entra por el botón.
      // El swipe navega entre secciones como en cualquier otra.
      if(feedVisible()&&window._feedView!=='reels'){
        snapNavigate(wrapper, dx>0);
        setTimeout(function(){ window._r2SwipeSection&&window._r2SwipeSection(dx<0?1:-1); },190);
        return;
      }

      // CASO: cualquier otra sección
      snapNavigate(wrapper, dx>0);
      setTimeout(function(){ window._r2SwipeSection&&window._r2SwipeSection(dx<0?1:-1); },190);
    },{passive:true});
  }

  function init(){
    if ($('ruleta2-bar')){
      renderBar(); bindGestures();
      try { window._renderSidebarNav && window._renderSidebarNav(); } catch(e){}
      // --nav-h = altura real del header global (con safe-area del iPhone
      // puede ser ~95px; el valor fijo 70px dejaba contenido tapado)
      (function(){
        function setNavH(){
          var n = document.getElementById('main-nav');
          var h = (n && n.offsetHeight) || 70;
          document.documentElement.style.setProperty('--nav-h', h + 'px');
        }
        setNavH();
        window.addEventListener('resize', setNavH);
        setTimeout(setNavH, 800);
      })();
      // bindGlobalSectionSwipe() DESACTIVADO (2026-06-11): el cambio de sección
      // por gesto salteaba secciones y desincronizaba la barra. Solo barra/ruleta.
      // Barra dinámica estilo IG: se compacta al scrollear hacia abajo y
      // vuelve a su tamaño al subir o llegar arriba
      (function(){
        var nav = document.querySelector('.ruleta2-nav');
        if (!nav || nav._shrinkBound) return; nav._shrinkBound = true;
        var lastY = 0, ticking = false;
        // capture:true también escucha el scroll de contenedores internos
        // (listas, secciones) — no solo el de window
        document.addEventListener('scroll', function(ev){
          if (ticking) return; ticking = true;
          var tgt = ev.target;
          requestAnimationFrame(function(){
            var y = (tgt === document || tgt === document.documentElement || tgt === document.body)
              ? (window.scrollY || 0)
              : (tgt && tgt.scrollTop) || 0;
            if (y > 90 && y > lastY + 4) nav.classList.add('r2-compact');
            else if (y < lastY - 4 || y < 50) nav.classList.remove('r2-compact');
            lastY = y; ticking = false;
          });
        }, { passive: true, capture: true });
      })();
      try {
        var c = parseInt(localStorage.getItem('r2_hint_count')||'0',10);
        if (c >= HINT_MAX){ var h=$('ruleta2-hint'); if(h) h.style.display='none'; }
      } catch(e){}
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
  // re-init por si el nav aparece después
  setTimeout(init, 1000);
  window._initRuleta2 = init;
})();

// Engranaje del navbar superior (al lado de notificaciones)
window._closeNavGear = function(){
  var dd = document.getElementById('nav-gear-dropdown');
  if (dd) dd.classList.remove('open');
};
window._toggleNavGear = function(event){
  if (event) event.stopPropagation();
  var dd = document.getElementById('nav-gear-dropdown');
  if (!dd) return;
  var open = dd.classList.contains('open');
  if (open){ dd.classList.remove('open'); return; }
  dd.classList.add('open');
  var close = function(e){
    if (!dd.contains(e.target) && !e.target.closest('#nav-gear-btn')){
      dd.classList.remove('open');
      document.removeEventListener('click', close);
    }
  };
  setTimeout(function(){ document.addEventListener('click', close); }, 80);
};

// Mantener el centro de la ruleta v2 sincronizado con la navegación global
(function(){
  var _orig = window.switchDashboardTab;
  if (typeof _orig !== 'function') return;
  window.switchDashboardTab = function(role, tabId, el){
    // PANEL de negocio: crear/seed el iframe ANTES de que el core lo muestre.
    if (tabId === 'panel') { try { window._ensureBizPanel && window._ensureBizPanel(); } catch(e){} }
    var r = _orig.apply(this, arguments);
    if (tabId === 'panel') { try { window._sizeBizPanel && window._sizeBizPanel(); } catch(e){} }
    try { if (role === 'jugador' && window._r2SyncTab) window._r2SyncTab(tabId); } catch(e){}
    // Perfil según el perfil ACTIVO: equipo → perfil del club; fanático → perfil de hincha
    try {
      if (tabId === 'perfil') {
        var _ap = window._activeProfileType && window._activeProfileType();
        var _pv = document.getElementById('jugador-perfil');
        // Detección ROBUSTA de cuenta de negocio: no depender solo de _isBizAccount
        // (si el rol persistido se corrompió, el perfil de tienda/complejo caía al
        // fut-card de jugador). Chequear también trueRole / _bizRole / _isBizUser.
        var _trP = ((window._trueRole && window._trueRole()) || (window.userData && window.userData.role) || (window._bizRole||'') || '').toLowerCase();
        var _bizRolesP = ['club','complejo','tienda','organizacion','sponsor','profesional'];
        var _isBizP = (window._isBizAccount ? window._isBizAccount() : false) || _bizRolesP.indexOf(_trP) !== -1 || !!window._isBizUser;
        // Identidad de negocio activa = cuenta de negocio y NO cambió a jugador/fanático/equipo.
        if (_isBizP && _ap !== 'jugador' && _ap !== 'fanatico' && _ap !== 'team' && window.viewUserProfile && window.userData) {
          // NEGOCIO (dueño, identidad de negocio activa): perfil de negocio inline.
          // Si cambió a la identidad de JUGADOR (_ap==='jugador'), cae al perfil de
          // jugador normal (abajo) y NO se fuerza el perfil de negocio.
          // (no como overlay full-screen que tapa logo/campana/ajustes y el switcher).
          if (_pv) { _pv.style.visibility = 'hidden'; _pv.style.display = 'none'; }
          var _bizInline = document.getElementById('biz-inline-profile');
          if (!_bizInline && _pv && _pv.parentNode) {
            _bizInline = document.createElement('div');
            _bizInline.id = 'biz-inline-profile';
            _bizInline.className = 'dashboard-tab-content biz-inline-profile';
            _pv.parentNode.insertBefore(_bizInline, _pv.nextSibling);
          }
          if (_bizInline) {
            _bizInline.style.display = 'block';
            _bizInline.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:28px;color:var(--accent);"></i></div>';
            window.viewUserProfile(window.userData.email, true, { inline: true, container: _bizInline,
                bizRole: (window._trueRole && window._trueRole()) || null,
                bizId: (window.userData && window.userData._activeBizId) || null });
          } else {
            window.viewUserProfile(window.userData.email, true);
          }
        } else if (_ap === 'team' && window.userData && window.userData._activeClubId && window.viewClubProfile) {
          // Ocultar YA el perfil de jugador para que no se vea el "flash" mientras
          // carga el perfil del club (se restaura al cerrar el modal del club).
          if (_pv) _pv.style.visibility = 'hidden';
          window.viewClubProfile(window.userData._activeClubId);
        } else if (_pv) {
          // Identidad jugador/fanático: restaurar el perfil de jugador y ocultar el inline de negocio.
          // OJO: 'block' (no '') — el core ya puso display:block; poner '' cae al CSS
          // .dashboard-tab-content { display:none } y el perfil quedaba en NEGRO.
          var _bizInlineOff = document.getElementById('biz-inline-profile');
          if (_bizInlineOff) _bizInlineOff.style.display = 'none';
          _pv.style.visibility = ''; _pv.style.display = 'block';
          if (_ap === 'fanatico') { _pv.classList.add('fanatico-profile'); if (window._arrangeFanHeader) setTimeout(window._arrangeFanHeader, 30); }
          else { _pv.classList.remove('fanatico-profile'); if (window._restoreFanHeader) window._restoreFanHeader(); }
          // P0.6: al entrar al perfil, LIMPIAR y recargar los posts según la identidad activa.
          // Sin esto quedaban visibles los posts de la identidad anterior (jugador en fanático, etc.).
          try {
            var _ppc = document.getElementById('jugador-profile-feed-posts');
            if (_ppc) _ppc.innerHTML = '<div style="text-align:center;padding:30px;color:#555;"><i class="bx bx-loader-alt bx-spin" style="font-size:22px;"></i></div>';
            if (window.loadProfilePosts) setTimeout(function(){ try { window.loadProfilePosts(); } catch(e){} }, 20);
          } catch(e){}
        }
      } else {
        // Otra sección (no perfil): solo restaurar visibility. NO tocar display — el core
        // ya gestiona qué tab mostrar; forzar display aquí pisaba el estado correcto.
        var _pv2 = document.getElementById('jugador-perfil');
        if (_pv2) { _pv2.style.visibility = ''; }
        var _bizInline2 = document.getElementById('biz-inline-profile');
        if (_bizInline2) _bizInline2.style.display = 'none';
      }
    } catch(e){}
    // Salvavidas anti-"perfil en negro": si estamos en perfil y NO es identidad de negocio,
    // garantizar que el contenedor del perfil de jugador esté visible pase lo que pase
    // (una excepción a mitad del bloque de arriba podía dejarlo en display:none).
    try {
      if (tabId === 'perfil') {
        var _apG = window._activeProfileType && window._activeProfileType();
        var _isBizG = _apG && (String(_apG).indexOf('biz:') === 0 || _apG === 'negocio');
        var _pvG = document.getElementById('jugador-perfil');
        var _biG = document.getElementById('biz-inline-profile');
        if (_isBizG) {
          // Negocio: el inline debe estar visible; si quedó vacío, re-render.
          if (_biG) {
            _biG.style.display = 'block';
            if (!_biG.innerHTML || !_biG.querySelector('.social-profile')) {
              try { window.viewUserProfile(window.userData.email, true, { inline:true, container:_biG,
                bizRole:(window._trueRole&&window._trueRole())||null, bizId:(window.userData&&window.userData._activeBizId)||null }); } catch(e){}
            }
          }
        } else if (_pvG) {
          _pvG.style.visibility = ''; _pvG.style.display = 'block';
          if (_biG) _biG.style.display = 'none';
        }
      }
    } catch(e){}
    // Mantener el pill del switcher siempre al día (nombre + icono del rol activo)
    try { if (window._renderProfileSwitcher) window._renderProfileSwitcher(); } catch(e){}
    // Refrescar el sidebar de PC (resalta la sección activa; mismas 5 opciones que mobile).
    try { if (window._renderSidebarNav) window._renderSidebarNav(); } catch(e){}
    // cerrar el submenú de BUSCAR/CREAR al navegar a cualquier sección
    try { if (window._r2CloseSub) window._r2CloseSub(); } catch(e){}
    // cerrar Comunidades (overlay) al navegar con la barra → ya no hace falta "Volver"
    try { ['comunidad-detail','comunidades-view'].forEach(function(id){ var e=document.getElementById(id); if(e) e.remove(); }); } catch(e){}
    // cerrar Reels al cambiar de sección
    try {
        var _rm = document.getElementById('reels-modal');
        if (_rm) { _rm.style.transition='opacity .15s'; _rm.style.opacity='0'; setTimeout(function(){ _rm.remove(); },160); }
    } catch(e){}
    // cerrar sheets de reel
    try { ['reel-share-sheet','reel-dm-sheet'].forEach(function(id){ var e=document.getElementById(id); if(e) e.remove(); }); } catch(e){}
    // salir del juego embebido al cambiar de sección
    try {
        const _gp = document.getElementById('game-player-modal');
        if (_gp && _gp.style.display !== 'none' && window.closeGamePlayer) window.closeGamePlayer();
    } catch(e){}
    return r;
  };
})();



// ============================================================
// BOT DE ACTIVIDADES RECIENTES (cada 12hs, tope del feed)
// ============================================================
window._activityBotLastRun = 0;
window._insertActivityBot = async function(feedEl) {
    if (!feedEl) return;
    const now = Date.now();
    // Cache por 12hs en localStorage
    const cacheKey = 'canchero_activity_bot';
    const cached = (() => { try { return JSON.parse(localStorage.getItem(cacheKey)); } catch(e){ return null; }})();
    let botHtml = null;
    if (cached && (now - cached.ts) < 12 * 60 * 60 * 1000) {
        botHtml = cached.html;
    } else {
        const sb = window._sb;
        if (!sb) return;
        const since = new Date(now - 12 * 60 * 60 * 1000).toISOString();
        try {
            const [{ data: newUsers }, { data: newClubs }] = await Promise.all([
                sb.from('users').select('name,city,nat,created_at').gte('created_at', since).order('created_at', { ascending: false }).limit(5),
                sb.from('clubs').select('name,city,nat,created_at').gte('created_at', since).order('created_at', { ascending: false }).limit(5)
            ]);
            const items = [];
            (newUsers||[]).forEach(u => items.push({ type:'jugador', icon:'⚽', name: u.name || 'Nuevo jugador', loc: u.city || u.nat || '', at: u.created_at }));
            (newClubs||[]).forEach(c => items.push({ type:'club', icon:'🛡️', name: c.name || 'Nuevo club', loc: c.city || c.nat || '', at: c.created_at }));
            items.sort((a, b) => new Date(b.at) - new Date(a.at));
            const topItems = items.slice(0, 5);
            if (!topItems.length) return;

            const rows = topItems.map(it => `
                <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.04);">
                    <div style="font-size:18px;flex-shrink:0;">${it.icon}</div>
                    <div style="flex:1;">
                        <div style="font-size:12px;font-weight:700;color:#fff;">${it.name}</div>
                        ${it.loc ? `<div style="font-size:10px;color:#555;">📍 ${it.loc}</div>` : ''}
                    </div>
                    <div style="font-size:9px;color:#444;">${it.type === 'jugador' ? 'Jugador' : 'Club'}</div>
                </div>`).join('');

            botHtml = `
                <article style="background:linear-gradient(135deg,#0a1a0a,#0d130d);border:1px solid rgba(186,255,0,0.2);border-radius:16px;padding:14px 16px;margin-bottom:12px;">
                    <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">
                        <div style="width:38px;height:38px;border-radius:50%;background:rgba(186,255,0,0.12);border:2px solid var(--accent);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;">🤖</div>
                        <div>
                            <div style="font-size:13px;font-weight:900;color:var(--accent);">CANCHERO BOT</div>
                            <div style="font-size:10px;color:#555;">Actividad reciente · Últimas 12hs</div>
                        </div>
                        <div style="margin-left:auto;font-size:9px;color:#333;background:#111;border-radius:6px;padding:3px 7px;font-weight:700;">AUTO</div>
                    </div>
                    <div style="font-size:11px;color:#888;margin-bottom:8px;font-weight:700;letter-spacing:.5px;">NUEVOS EN CANCHERO:</div>
                    ${rows}
                </article>`;
            localStorage.setItem(cacheKey, JSON.stringify({ ts: now, html: botHtml }));
        } catch(e) { return; }
    }
    if (botHtml) {
        const existing = feedEl.querySelector('#canchero-bot-card');
        if (existing) existing.remove();
        const div = document.createElement('div');
        div.id = 'canchero-bot-card';
        div.innerHTML = botHtml;
        feedEl.insertBefore(div.firstElementChild, feedEl.firstChild);
    }
};

// ============================================================
// MENSAJES — back arrow y swipe para cerrar el chat activo
// ============================================================
(function _initMsgSwipe() {
    let startX = 0;
    document.addEventListener('touchstart', (e) => {
        const chatArea = document.getElementById('msg-chat-area');
        if (!chatArea) return;
        const hasActive = chatArea.querySelector('.msg-thread-container, .msg-messages-wrap, [id^="chat-thread-"]');
        if (!hasActive) return;
        if (e.touches[0].clientX < 30) startX = e.touches[0].clientX;
    }, { passive: true });

    document.addEventListener('touchend', (e) => {
        if (!startX) return;
        const endX = e.changedTouches[0].clientX;
        if (endX - startX > 60) {
            // Swipe derecha desde borde — cerrar thread y volver a lista
            const backBtn = document.querySelector('.msg-back-btn, [data-msg-back], #msg-back-arrow');
            if (backBtn) { backBtn.click(); }
            else if (window.CancheroMessaging && window.CancheroMessaging.closeThread) {
                window.CancheroMessaging.closeThread();
            } else {
                // fallback: ocultar área de chat, mostrar sidebar
                const sidebar = document.getElementById('msg-sidebar');
                const chatArea = document.getElementById('msg-chat-area');
                if (sidebar) sidebar.style.display = '';
                if (chatArea) chatArea.innerHTML = '<div class="msg-empty-state"><i class="bx bx-message-square-detail"></i><p>Seleccioná una conversación</p></div>';
            }
        }
        startX = 0;
    }, { passive: true });
})();

/* ═══════════════════════════════════════════════════════════════
   BUSCAR HUB — funciones para el tab jugador-buscar
═══════════════════════════════════════════════════════════════ */
window._buscarGlobal = (function(){
  let _timer = null;
  return function(q){
    const res = document.getElementById('buscar-global-results');
    if (!res) return;
    q = (q||'').trim();
    if (!q){ res.style.display='none'; return; }
    res.style.display = 'block';
    clearTimeout(_timer);
    _timer = setTimeout(async function(){
      res.innerHTML = '<div style="text-align:center;padding:20px;color:#555;"><i class="bx bx-loader-alt bx-spin"></i></div>';
      const sb = window._sb;
      if (!sb){ res.innerHTML=''; return; }
      try {
        /* Buscar en perfiles de usuarios */
        const [usersR, clubsR] = await Promise.all([
          sb.from('users').select('email,name,pos,photo').ilike('name','%'+q+'%').limit(8),
          sb.from('clubs').select('id,name,logo_url,city').ilike('name','%'+q+'%').limit(8).catch(()=>({data:[]}))
        ]);
        const users = (usersR&&usersR.data)||[];
        const clubs = (clubsR&&clubsR.data)||[];
        if (!users.length && !clubs.length){
          res.innerHTML='<div style="text-align:center;padding:16px;color:#555;font-size:13px;">Sin resultados para "'+q+'"</div>';
          return;
        }
        let html = '';
        if (users.length){
          html += '<div style="font-size:10px;font-weight:800;color:#555;letter-spacing:.5px;margin-bottom:8px;">JUGADORES</div>';
          html += users.map(u=>`<div onclick="window.openUserProfile&&openUserProfile('${u.email}')" style="display:flex;align-items:center;gap:10px;padding:10px;background:#111;border-radius:12px;margin-bottom:6px;cursor:pointer;">
            <div style="width:38px;height:38px;border-radius:50%;background:#1a1a1a;flex-shrink:0;overflow:hidden;display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--accent);">
              ${(u.photo||u.avatar_url)?`<img src="${u.photo||u.avatar_url}" style="width:100%;height:100%;object-fit:cover;">`:(u.name||'?')[0].toUpperCase()}
            </div>
            <div><div style="color:#fff;font-size:13px;font-weight:700;">${u.name||u.email}</div><div style="color:#555;font-size:11px;">${u.pos||u.position||'Jugador'}</div></div>
          </div>`).join('');
        }
        if (clubs.length){
          html += '<div style="font-size:10px;font-weight:800;color:#555;letter-spacing:.5px;margin:10px 0 8px;">CLUBES</div>';
          html += clubs.map(c=>`<div style="display:flex;align-items:center;gap:10px;padding:10px;background:#111;border-radius:12px;margin-bottom:6px;cursor:pointer;">
            <div style="width:38px;height:38px;border-radius:50%;background:#1a1a1a;flex-shrink:0;overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:18px;">
              ${c.logo_url?`<img src="${c.logo_url}" style="width:100%;height:100%;object-fit:cover;">`:' 🛡️'}
            </div>
            <div><div style="color:#fff;font-size:13px;font-weight:700;">${c.name}</div><div style="color:#555;font-size:11px;">${c.city||c.ciudad||'Club'}</div></div>
          </div>`).join('');
        }
        res.innerHTML = '<div style="background:#0d0d0d;border:1px solid #1a1a1a;border-radius:14px;padding:12px;">'+html+'</div>';
      } catch(e){ res.innerHTML=''; }
    }, 350);
  };
})();

window._abrirBuscarJugadores = function(){
  /* Abre el directorio global de jugadores (no la sección de partidos) */
  if (typeof window.openGlobalDirectory === 'function'){
    window.openGlobalDirectory('jugadores');
  } else if (typeof window.switchPartidosTab === 'function'){
    switchDashboardTab('jugador','buscar-partidos',null);
    setTimeout(()=>window.switchPartidosTab('buscan-jugador'),300);
  } else {
    switchDashboardTab('jugador','buscar-partidos',null);
  }
};
